/// The with-headroom control: ALL FIVE injections run together, each a short delay that leaves most of
/// the deadline. Every injection must have run once, in place (so the rows above are not refused for a
/// fixture reason), every one of the six children must have started, and the bootstrap must SUCCEED before
/// the deadline. On the base AND on the correction this passes.
#[test]
fn round6_with_headroom_every_late_validation_step_succeeds_before_the_deadline() {
    let mount_calls = clean_mount_census_calls();
    let (ran, outcome, state, deadline) = run_late(&LateV1::ALL, DelayV1::Brief, mount_calls);
    let observed = ran.route.children();
    println!(
        "CHILD-START-MARKER the headroom control: observed={observed:?} fired={:?} misplaced={:?} returned_before_the_deadline={}",
        state.fired.borrow(),
        state.misplaced.borrow(),
        Instant::now() < deadline
    );
    assert_eq!(observed.len(), 6, "every proof child must have run");
    let mut fired = state.fired.borrow().clone();
    fired.sort_by_key(|point| format!("{point:?}"));
    let mut every = LateV1::ALL.to_vec();
    every.sort_by_key(|point| format!("{point:?}"));
    assert_eq!(fired, every, "every injection must have run once");
    assert!(
        state.misplaced.borrow().is_empty(),
        "every injection ran in its place"
    );
    match outcome {
        Ok(verified) => assert!(verified.closure.fsck_strict),
        Err(failure) => panic!("the headroom control must succeed: {failure:?}"),
    }
    assert!(
        Instant::now() < deadline,
        "the control must finish inside its deadline"
    );
}

// ---------------------------------------------------------------------------------------------
// Round 6, STAGE B: every late-validation guard, one by one
//
// These rows need `GitHookPointV1::DeadlineObserved`, a test hook inside the one guard function that
// every late-validation step calls right after it returns. It does not exist on the pristine base, so
// these rows cannot compile there and NO base RED is claimed for them (Stage A above is the base RED).
// Their causality is shown on the correction by (a) the seam-only control, the correction with the single
// clock comparison inside the guard removed, and (b) one mutation per guard. Each row makes the step
// BEFORE one guard slow past the deadline and requires the typed timeout, the step it names, the exact
// ledger, all the children that had started, and that NO later guard ever ran (the run halted AT it).
// ---------------------------------------------------------------------------------------------

/// What the guard hook does when it is the guard with index `at` (counted over the whole run).
#[derive(Debug)]
enum AtGuardV1 {
    /// Nothing: the clean control records every guard.
    Observe,
    /// The step before that guard returned after the deadline.
    PassTheDeadline { at: usize, label: &'static str },
    /// The destination root is replaced, and the clock is NOT spent: at the guard immediately before the
    /// root's identity check, the identity check must still be the last, and still refuse.
    SwapTheRoot { at: usize, label: &'static str },
}

#[derive(Default)]
struct GuardLogV1 {
    /// Every guard that read the clock, in order, by step label.
    events: std::cell::RefCell<Vec<&'static str>>,
    /// How many guards had run when the final `fsck`'s post-exit callback ran.
    final_child_at: std::cell::Cell<Option<usize>>,
    /// The label of the guard the injection found at its index.
    injected: std::cell::Cell<Option<&'static str>>,
}

/// One Captured SHA-1 bootstrap whose every late-validation guard is logged, with `at` done at one guard.
fn run_guarded(
    rules: &[(&str, &str)],
    at: AtGuardV1,
) -> (RanV1, OutcomeV1, std::rc::Rc<GuardLogV1>, Instant) {
    let log = std::rc::Rc::new(GuardLogV1::default());
    let shared = log.clone();
    let (ran, outcome, deadline) = run_before(rules, ROUND6_DEADLINE_V1, move |dest, deadline| {
        let mut guards: Vec<Box<dyn std::any::Any>> = Vec::new();
        {
            let log = shared.clone();
            guards.push(Box::new(install_git_hook_for_test(
                GitHookPointV1::AfterChild,
                move |event| {
                    if event.label == "fsck --strict" {
                        log.final_child_at.set(Some(log.events.borrow().len()));
                    }
                },
            )));
        }
        let root = dest.path.clone();
        let away = root.with_file_name("dest-away-round6");
        let log = shared.clone();
        guards.push(Box::new(install_git_hook_for_test(
            GitHookPointV1::DeadlineObserved,
            move |event| {
                let index = log.events.borrow().len();
                log.events.borrow_mut().push(event.label);
                match &at {
                    AtGuardV1::Observe => {}
                    AtGuardV1::PassTheDeadline { at, label } => {
                        if index == *at {
                            log.injected.set(Some(event.label));
                            if event.label == *label {
                                pass_the_deadline(deadline);
                            }
                        }
                    }
                    AtGuardV1::SwapTheRoot { at, label } => {
                        if index == *at {
                            log.injected.set(Some(event.label));
                            if event.label == *label {
                                std::fs::rename(&root, &away).expect("the root moves away");
                                std::fs::create_dir(&root).expect("an empty root takes its name");
                            }
                        }
                    }
                }
            },
        )));
        guards
    });
    (ran, outcome, log, deadline)
}

/// The guards one clean run makes, and the filesystem facts the expected sequence is derived from (never
/// from the production code under test).
struct GuardShapeV1 {
    events: Vec<&'static str>,
    final_child_at: usize,
    /// Retained staging directories beneath `plain/`.
    staging_dirs: usize,
    /// The bootstrap root and every directory beneath it.
    bootstrap_dirs: usize,
    /// Every entry beneath the bootstrap root.
    bootstrap_entries: usize,
    /// Staged descriptors the final rewind goes through.
    staged: usize,
}

impl GuardShapeV1 {
    /// The chain steps of one sweep: the work and plain chain, each staging directory, HOME, XDG, and
    /// every bootstrap directory.
    fn chains(&self) -> usize {
        1 + self.staging_dirs + 2 + self.bootstrap_dirs
    }

    /// The census steps of the closing gate: before each directory and before each entry.
    fn census_steps(&self) -> usize {
        self.bootstrap_dirs + self.bootstrap_entries
    }

    /// The whole sequence a clean run must log, derived from the facts above: one success gate for each
    /// of its `read_only` children, the rewinds, and the closing gate over `admitted` object files.
    fn expected(&self, read_only: usize, admitted: usize) -> Vec<&'static str> {
        let chains = self.chains();
        let mut expected = Vec::new();
        for _ in 0..read_only {
            expected.push("gate");
            expected.extend(std::iter::repeat_n("chain", chains));
            expected.push("root");
        }
        expected.extend(std::iter::repeat_n("rewind", self.staged));
        expected.extend(["closing", "closing-census"]);
        expected.extend(std::iter::repeat_n("census", self.census_steps()));
        expected.push("closing-tree");
        expected.extend(std::iter::repeat_n("rehash", admitted));
        expected.extend(std::iter::repeat_n("chain", chains));
        expected.push("root");
        expected
    }

    /// Where each part starts in `events`: the first read-only child's gate, the final child's gate, the
    /// rewinds, and the closing gate.
    fn starts(&self) -> [usize; 4] {
        let group = self.chains() + 2;
        [
            0,
            self.final_child_at,
            self.final_child_at + group,
            self.final_child_at + group + self.staged,
        ]
    }
}

fn clean_guard_shape() -> GuardShapeV1 {
    let (ran, outcome, log, _) = run_guarded(&[], AtGuardV1::Observe);
    let verified = match outcome {
        Ok(verified) => verified,
        Err(failure) => panic!("the clean control must succeed: {failure:?}"),
    };
    let directories = |root: &Path| {
        snapshot(root)
            .values()
            .filter(|bytes| bytes.is_none())
            .count()
    };
    let bootstrap = ran.dest.bootstrap();
    let events = log.events.borrow().clone();
    GuardShapeV1 {
        events,
        final_child_at: log.final_child_at.get().expect("the final fsck ran"),
        staging_dirs: directories(&ran.dest.work().join("plain")),
        bootstrap_dirs: directories(&bootstrap) + 1,
        bootstrap_entries: snapshot(&bootstrap).len(),
        staged: verified.verified.staged.len(),
    }
}

/// The guard sequence of a clean run is EXACTLY the one derived from the filesystem: every guard of the
/// success path runs, once per step and per loop iteration, in order, and the LAST guard is the one
/// immediately before the root's identity check, with nothing observed after it. Every guard site has a
/// row below; this pins that none is missing, doubled, or moved.
#[test]
fn round6_the_late_validation_guards_run_in_the_documented_order() {
    let shape = clean_guard_shape();
    println!(
        "GUARD-MARKER staging_dirs={} bootstrap_dirs={} entries={} staged={} chains={} census_steps={} events={} final_child_at={}",
        shape.staging_dirs,
        shape.bootstrap_dirs,
        shape.bootstrap_entries,
        shape.staged,
        shape.chains(),
        shape.census_steps(),
        shape.events.len(),
        shape.final_child_at
    );
    assert!(
        shape.staging_dirs >= 1 && shape.staged >= 2,
        "the fixture must exercise the per-staging-directory and per-rewind loops"
    );
    // Captured: verify-pack, cat-file, rev-list and fsck are read-only; the pack, index and reverse index
    // are the three admitted files.
    assert_eq!(shape.events, shape.expected(4, 3));
    assert_eq!(shape.events.last(), Some(&"root"), "the root guard is last");
}

/// An Empty object database runs the same guards over its two read-only children and NO admitted file:
/// there is no rehash guard, and the closing gate still ends at the root's guard.
#[test]
fn round6_an_empty_object_database_logs_the_same_guards_without_a_rehash() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let (dest, verified) = phase_v(&capsule.capsule);
    let log = std::rc::Rc::new(GuardLogV1::default());
    let (seen, final_child) = (log.clone(), log.clone());
    let _observe = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        seen.events.borrow_mut().push(event.label);
    });
    let _final = install_git_hook_for_test(GitHookPointV1::AfterChild, move |event| {
        if event.label == "fsck --strict" {
            final_child
                .final_child_at
                .set(Some(final_child.events.borrow().len()));
        }
    });
    let (_area, runner) = lane_runner();
    let bootstrap = bootstrap(verified, &runner, GitObjectFormatV1::Sha1)
        .unwrap_or_else(|failure| panic!("the Empty control must succeed: {failure:?}"));
    let bootstrap_tree = dest.bootstrap();
    let directories = |root: &Path| {
        snapshot(root)
            .values()
            .filter(|bytes| bytes.is_none())
            .count()
    };
    let shape = GuardShapeV1 {
        events: log.events.borrow().clone(),
        final_child_at: log.final_child_at.get().expect("the final fsck ran"),
        staging_dirs: directories(&dest.work().join("plain")),
        bootstrap_dirs: directories(&bootstrap_tree) + 1,
        bootstrap_entries: snapshot(&bootstrap_tree).len(),
        staged: bootstrap.verified.staged.len(),
    };
    println!(
        "GUARD-MARKER the Empty control: staging_dirs={} bootstrap_dirs={} entries={} staged={} events={}",
        shape.staging_dirs,
        shape.bootstrap_dirs,
        shape.bootstrap_entries,
        shape.staged,
        shape.events.len()
    );
    assert_eq!(shape.events, shape.expected(2, 0));
    assert!(!shape.events.contains(&"rehash"));
    assert_eq!(shape.events.last(), Some(&"root"));
}

/// One Stage B row's expectation: the children that had started, and the last completed step.
fn guard_row_expectation(
    index: usize,
    starts: &[usize; 4],
) -> (&'static [&'static str], GitPlaneStepV1) {
    if index < starts[1] {
        (
            &["init", "index-pack", "verify-pack"],
            GitPlaneStepV1::BootstrapInit,
        )
    } else if index < starts[2] {
        (six_children(), GitPlaneStepV1::Closure)
    } else {
        (six_children(), GitPlaneStepV1::Fsck)
    }
}

/// The guards one row per guard label and per loop end isolates, as `(index, label)`.
fn guard_rows(shape: &GuardShapeV1) -> Vec<(usize, &'static str)> {
    let [first_gate, final_gate, rewinds, closing] = shape.starts();
    let chains = shape.chains();
    let census = closing + 2;
    let tree = census + shape.census_steps();
    let rehash = tree + 1;
    let sweep = rehash + 3;
    let mut rows = vec![
        // The first read-only child's success gate: the same guard code runs for each of the four.
        (first_gate, "gate"),
        // The final child's success gate: before its census, right after it (the sweep's first step),
        // the sweep's last chain step, and immediately before the root's identity.
        (final_gate, "gate"),
        (final_gate + 1, "chain"),
        (final_gate + chains, "chain"),
        (final_gate + chains + 1, "root"),
        // The staged rewinds.
        (rewinds, "rewind"),
        (rewinds + shape.staged - 1, "rewind"),
        // The closing gate, in order.
        (closing, "closing"),
        (closing + 1, "closing-census"),
        (census, "census"),
        (tree - 1, "census"),
        (tree, "closing-tree"),
        (rehash, "rehash"),
        (rehash + 2, "rehash"),
        (sweep, "chain"),
        (sweep + chains - 1, "chain"),
        (sweep + chains, "root"),
    ];
    rows.sort_unstable();
    rows.dedup();
    rows
}

/// Every guard of the success path halts the run ALONE: the step before it is made slow past the deadline,
/// and the run must end with a typed timeout AT that guard: the children that had started, the step it
/// names as last completed, the ledger exactly as a clean run leaves it, and NO later guard run (so nothing
/// further was done toward a verified result, and the root's identity was never reached).
#[test]
fn round6_each_late_validation_guard_halts_the_run_alone() {
    let clean = clean_charge();
    let shape = clean_guard_shape();
    let starts = shape.starts();
    let mut problems = Vec::new();
    for (index, label) in guard_rows(&shape) {
        let name = format!("guard #{index} `{label}`");
        let (ran, outcome, log, deadline) =
            run_guarded(&[], AtGuardV1::PassTheDeadline { at: index, label });
        let events = log.events.borrow().clone();
        println!(
            "GUARD-MARKER {name}: found={:?} guards_run={} last={:?} returned {}ms after the deadline",
            log.injected.get(),
            events.len(),
            events.last(),
            Instant::now().saturating_duration_since(deadline).as_millis()
        );
        if log.injected.get() != Some(label) {
            problems.push(format!(
                "{name}: the fixture found {:?} at that index",
                log.injected.get()
            ));
            continue;
        }
        let (children, completed) = guard_row_expectation(index, &starts);
        problems.extend(judge(
            &name,
            &ran,
            &outcome,
            children,
            Some(completed),
            ChargeV1::Exactly(ran.phase_v + clean),
            is_timeout,
        ));
        if events.len() != index + 1 {
            problems.push(format!(
                "{name}: {} guards ran after it, and the run must halt at it",
                events.len().saturating_sub(index + 1)
            ));
        }
    }
    assert_no_problems(problems);
}

/// The root's identity stays the LAST fallible gate: with the clock NOT spent, the root replaced at the
/// closing gate's last guard (the one immediately before the identity check) is refused by that check, with
/// every proof recorded; and the same swap at the success gate's last guard is refused there. Neither is a
/// timeout, and neither is a success. (A check that moved AFTER the identity would not run first.)
#[test]
fn round6_the_root_identity_is_still_the_last_fallible_gate_after_its_guard() {
    let clean = clean_charge();
    let shape = clean_guard_shape();
    let starts = shape.starts();
    let chains = shape.chains();
    let census = starts[3] + 2;
    let tree = census + shape.census_steps();
    let mut problems = Vec::new();
    for (index, completed) in [
        (starts[1] + chains + 1, GitPlaneStepV1::Closure),
        (tree + 1 + 3 + chains, GitPlaneStepV1::Fsck),
    ] {
        let (ran, outcome, log, _) = run_guarded(
            &[],
            AtGuardV1::SwapTheRoot {
                at: index,
                label: "root",
            },
        );
        println!(
            "GUARD-MARKER the root swapped at guard #{index}: found={:?} guards_run={}",
            log.injected.get(),
            log.events.borrow().len()
        );
        let name = format!("the root swapped at guard #{index}");
        if log.injected.get() != Some("root") {
            problems.push(format!(
                "{name}: the fixture found {:?}",
                log.injected.get()
            ));
            continue;
        }
        problems.extend(judge(
            &name,
            &ran,
            &outcome,
            six_children(),
            Some(completed),
            ChargeV1::Exactly(ran.phase_v + clean),
            is_identity_changed,
        ));
        if log.events.borrow().len() != index + 1 {
            problems.push(format!("{name}: a guard ran after the root's guard"));
        }
    }
    assert_no_problems(problems);
}

/// The guards belong to the SUCCESS path only: a final child that FAILED is settled exactly as before (its
/// failure, its effect and its ledger, never held to the success gate), so no success-gate, rewind or closing
/// guard ever runs for it. The earlier three children's success gates are all that were observed.
#[test]
fn round6_a_failed_final_child_is_never_held_to_the_success_gate_guards() {
    let clean = clean_charge();
    let shape = clean_guard_shape();
    let group = shape.chains() + 2;
    let (ran, outcome, log, _) = run_guarded(
        &[("fsck --strict", "\"$REAL\" \"$@\"; exit 2")],
        AtGuardV1::Observe,
    );
    let events = log.events.borrow().clone();
    println!(
        "GUARD-MARKER the failed final child: guards_run={} (three success gates are {})",
        events.len(),
        3 * group
    );
    let problems = judge(
        "a failed final fsck",
        &ran,
        &outcome,
        six_children(),
        Some(GitPlaneStepV1::Closure),
        ChargeV1::Exactly(ran.phase_v + clean),
        |cause| is_git_child(cause, "fsck --strict", 2),
    );
    assert_no_problems(problems);
    assert_eq!(events.len(), 3 * group, "no guard ran for the failed child");
}

/// The body of the function or method that starts with `signature`, to the closing brace that has the
/// signature line's own indentation.
fn body_of<'a>(source: &'a str, signature: &str) -> &'a str {
    let start = source
        .find(signature)
        .unwrap_or_else(|| panic!("`{signature}` is in the production source"));
    let line_start = source[..start].rfind('\n').map_or(0, |newline| newline + 1);
    let indent = " ".repeat(start - line_start);
    let rest = &source[start..];
    let end = rest
        .find(&format!("\n{indent}}}\n"))
        .expect("the function ends");
    &rest[..end]
}

/// STRUCTURAL ONLY (it reads the production source, so it is evidence of order and shape, never of
/// behavior; the behavioral evidence is every row above). The late-validation order is fixed in the
/// source: the admitted rehash streams under the deadline and never through the unbounded hash; the
/// closing gate is census, tree, rehash, then the sweep as its TAIL expression; the sweep's guard is
/// followed by nothing but the root's identity, which is the last fallible call, with only a tail
/// expression after it; the success arm uses the deadline gate; the runner callbacks stay unobserved;
/// and nothing fallible follows the closing gate but infallible construction.
#[test]
fn round6_the_late_validation_order_is_fixed_in_the_source() {
    let source = include_str!("custody_restore_git.rs");
    let at = |body: &str, needle: &str| {
        body.find(needle)
            .unwrap_or_else(|| panic!("`{needle}` is in `{body}`"))
    };

    let rehash = body_of(source, "fn remeasure_admitted(");
    assert!(rehash.contains("stream_digest(") && rehash.contains("observe_deadline("));
    assert!(
        !rehash.contains("hash_prefix("),
        "the admitted rehash is never an unbounded read"
    );

    let closing = body_of(source, "fn closing_gate(");
    let order = [
        at(closing, "refuse_mounts_within("),
        at(closing, "reconcile_paced("),
        at(closing, "remeasure_admitted("),
        at(closing, "sweep_chains("),
    ];
    assert!(order.windows(2).all(|pair| pair[0] < pair[1]), "{order:?}");
    assert!(
        !closing[order[3]..].contains(';'),
        "the sweep is the closing gate's tail expression"
    );

    let sweep = body_of(source, "fn sweep_chains(");
    let guard = at(sweep, "pace(\"root\")?;");
    let identity = at(sweep, "pinned_root_unchanged(");
    assert!(
        sweep[guard + "pace(\"root\")?;".len()..identity]
            .trim()
            .is_empty(),
        "the guard is the last statement before the root's identity"
    );
    assert!(
        !sweep[identity..].contains(';'),
        "the root's identity is the last fallible call: only a tail expression"
    );

    let settle = body_of(source, "fn settle_read_only<");
    assert!(settle.contains("self.deadline_gate()?") && !settle.contains("self.gate()?"));

    let gate = body_of(source, "fn gate(&self)");
    assert!(
        gate.contains("gate_parts(") && !gate.contains("observe_deadline("),
        "the runner callbacks' gate is not held to the deadline"
    );
    assert!(source.contains("match this.gate()"));

    let steps = body_of(source, "fn run_steps(");
    let tail = &steps[at(steps, "work.closing_gate()?;") + "work.closing_gate()?;".len()..];
    assert!(
        !tail.contains('?'),
        "only infallible construction follows the closing gate"
    );
    let construct = body_of(source, "fn into_result(");
    assert!(
        !construct.contains('?'),
        "the success value is built infallibly"
    );
}

// ---------------------------------------------------------------------------------------------
// Pass B1a: retained active-frame prevalidation
//
// Every row drives `prevalidate_active_frames_v1` over a REAL retained phase-V value: the rich
// capsule's two plan-produced frames, or hand-encoded frames (built with the real frame encoder) that
// stand where a sealed capsule's staged payloads would, beside a real phase-V capsule and its real
// ledger, pins, and destination. Prevalidation takes no runner, so no Git child can run; every refusal
// row also proves that the destination tree and the one ledger are exactly what they were.
//
// Pass A's controls above are unchanged. The mutation matrix in `.git/a2a-evidence/2b3b-pass-b1a/` maps
// each guard to the rows that turn red without it.
// ---------------------------------------------------------------------------------------------

type ClassV1 = CustodyCoverageClassV1;
const REFS_V1: ClassV1 = CustodyCoverageClassV1::RefsAndHead;
const LOGS_V1: ClassV1 = CustodyCoverageClassV1::StashAndReflogs;
const HEAD_BYTES_V1: &[u8] = b"ref: refs/heads/main\n";
const DIGEST_BYTES_V1: usize = 32;

/// One entry of a hand-built frame.
#[derive(Clone, Copy)]
enum EntryV1<'a> {
    Dir,
    File(&'a [u8]),
    Link(&'a [u8]),
}

type EntriesV1<'a> = [(&'a [u8], EntryV1<'a>)];

fn dir(path: &'static str) -> (&'static [u8], EntryV1<'static>) {
    (path.as_bytes(), EntryV1::Dir)
}

fn file(path: &'static str, content: &'static [u8]) -> (&'static [u8], EntryV1<'static>) {
    (path.as_bytes(), EntryV1::File(content))
}

fn link(path: &'static str, target: &'static [u8]) -> (&'static [u8], EntryV1<'static>) {
    (path.as_bytes(), EntryV1::Link(target))
}

/// A frame's bytes, from the real encoder, with the entries in canonical order whatever order they are
/// given in. A `/` or NUL cannot be in a component, but every other byte can: that is the codec's own
/// rule, so every spelling below is encodable.
fn encode_frame(class: ClassV1, generation: &str, entries: &EntriesV1<'_>) -> Vec<u8> {
    let mut ordered: Vec<(CustodyFramePathV1, EntryV1<'_>)> = entries
        .iter()
        .map(|(path, entry)| {
            (
                CustodyFramePathV1::from_bytes(path).expect("a frame path"),
                *entry,
            )
        })
        .collect();
    ordered.sort_by(|left, right| left.0.cmp(&right.0));
    let header = CustodyFrameHeaderV1::new(class, generation).expect("a frame header");
    let mut bytes = Vec::new();
    let mut encoder =
        CustodyFrameEncoderV1::new(&mut bytes, &header, frame_budget()).expect("an encoder");
    for (path, entry) in ordered {
        match entry {
            EntryV1::Dir => encoder.directory(&path, 0o755).expect("a directory"),
            EntryV1::File(content) => {
                let mut reader: &[u8] = content;
                encoder
                    .regular_file(&path, 0o644, content.len() as u64, &mut reader)
                    .expect("a regular file");
            }
            EntryV1::Link(target) => encoder.symlink(&path, target).expect("a symlink"),
        }
    }
    encoder.finish().expect("the trailer");
    bytes
}

/// `entries` plus a regular `HEAD`, unless they already name one.
fn with_head<'a>(entries: &EntriesV1<'a>) -> Vec<(&'a [u8], EntryV1<'a>)> {
    let mut all = entries.to_vec();
    if !all.iter().any(|(path, _)| *path == b"HEAD") {
        all.push((b"HEAD", EntryV1::File(HEAD_BYTES_V1)));
    }
    all
}

fn sha256_bytes(bytes: &[u8]) -> [u8; 32] {
    let mut sha256 = [0_u8; 32];
    sha256.copy_from_slice(digest::digest(&digest::SHA256, bytes).as_ref());
    sha256
}

/// Stage `bytes` as the one Captured payload of `class`, through a fresh unlinked descriptor, and set
/// the manifest's row for it: exactly what phase V would hold for a capsule carrying those bytes.
fn stage_frame(verified: &mut VerifiedCapsuleV1, class: ClassV1, bytes: &[u8]) {
    use std::io::{Seek as _, Write as _};
    verified.control.manifest = manifest_with_row(class, CustodyStateClassV1::Captured, verified);
    verified
        .staged
        .retain(|one| one.role != CustodyCapsuleArtifactRoleV1::CoveragePayload(class));
    let mut file = tempfile::tempfile().expect("an unlinked staging descriptor");
    file.write_all(bytes).expect("the frame bytes");
    file.seek(SeekFrom::Start(0)).expect("rewind");
    verified.staged.push(StagedPlaintextV1 {
        name: LosslessPathV1::from_bytes(format!("test/{class:?}.frame").into_bytes()),
        role: CustodyCapsuleArtifactRoleV1::CoveragePayload(class),
        file,
        length: bytes.len() as u64,
        sha256: sha256_bytes(bytes),
    });
}

fn staged_index(verified: &VerifiedCapsuleV1, class: ClassV1) -> usize {
    verified
        .staged
        .iter()
        .position(|one| one.role == CustodyCapsuleArtifactRoleV1::CoveragePayload(class))
        .expect("the staged payload")
}

/// One real phase-V value with its destination.
struct CaseV1 {
    dest: DestV1,
    verified: VerifiedCapsuleV1,
}

impl CaseV1 {
    /// A real all-Empty phase-V capsule whose manifest and staged payloads name `frames` (class, bytes).
    fn with_bytes(capsule: &CustomCapsuleV1, frames: &[(ClassV1, Vec<u8>)]) -> Self {
        let (dest, mut verified) = phase_v(&capsule.capsule);
        for (class, bytes) in frames {
            stage_frame(&mut verified, *class, bytes);
        }
        Self { dest, verified }
    }

    fn generation(capsule: &CustomCapsuleV1) -> String {
        let (_dest, verified) = phase_v(&capsule.capsule);
        verified.control.manifest.generation_id().to_owned()
    }

    /// A refs frame (with `HEAD` added) and, if given, a logs frame, both well formed for the generation.
    fn with_entries(
        capsule: &CustomCapsuleV1,
        refs: &EntriesV1<'_>,
        logs: Option<&EntriesV1<'_>>,
    ) -> Self {
        let generation = Self::generation(capsule);
        let mut frames = vec![(
            REFS_V1,
            encode_frame(REFS_V1, &generation, &with_head(refs)),
        )];
        if let Some(logs) = logs {
            frames.push((LOGS_V1, encode_frame(LOGS_V1, &generation, logs)));
        }
        Self::with_bytes(capsule, &frames)
    }

    fn refs_only(capsule: &CustomCapsuleV1, refs: &EntriesV1<'_>) -> Self {
        Self::with_entries(capsule, refs, None)
    }

    fn run(&mut self) -> Result<ActiveFramePlanV1, GitBootstrapErrorV1> {
        prevalidate(&mut self.verified, far_deadline())
    }

    /// Runs, and requires the refusal to leave no trace: not on the ledger, not in the destination tree,
    /// and no `repository/` entry.
    fn refusal(&mut self, row: &str) -> GitBootstrapErrorV1 {
        let ledger = ledger_used(&self.verified);
        let tree = snapshot(&self.dest.path);
        let error = self.run().expect_err(row);
        assert_eq!(ledger_used(&self.verified), ledger, "{row}: the ledger");
        assert_eq!(snapshot(&self.dest.path), tree, "{row}: a byte was written");
        assert_eq!(
            self.dest.entries(),
            [".restore-work"],
            "{row}: no repository exists"
        );
        error
    }

    fn fault(&mut self, row: &str, class: ClassV1, fault: ActiveFrameFaultV1) {
        match self.refusal(row) {
            GitBootstrapErrorV1::ActiveFrame {
                class: found_class,
                fault: found,
            } => assert_eq!((found_class, found), (class, fault), "{row}"),
            other => panic!("{row}: {other:?}"),
        }
    }

    fn accepted(&mut self, row: &str) -> ActiveFramePlanV1 {
        let ledger = ledger_used(&self.verified);
        let tree = snapshot(&self.dest.path);
        let plan = self
            .run()
            .unwrap_or_else(|error| panic!("{row}: must prevalidate: {error:?}"));
        assert_eq!(ledger_used(&self.verified), ledger, "{row}: the ledger");
        assert_eq!(snapshot(&self.dest.path), tree, "{row}: a byte was written");
        assert_eq!(self.dest.entries(), [".restore-work"], "{row}");
        assert!(
            self.verified.staged.iter().all(|one| position(one) == 0),
            "{row}: every staged descriptor is back at offset 0"
        );
        plan
    }
}

fn frames_capsule() -> CustomCapsuleV1 {
    empty(CustodyGitObjectFormatV1::Sha1)
}

fn path_string(bytes: &[u8]) -> String {
    lossy(bytes)
}

/// The test's own decode of one retained frame: `(entries, directories, regular files, content bytes)`.
/// It does not use the seam, and leaves the descriptor at offset 0.
fn independent_summary(
    file: &std::fs::File,
    class: ClassV1,
    generation: &str,
) -> (u64, u64, u64, u64) {
    use std::io::Seek as _;
    let mut handle = file.try_clone().expect("a duplicate descriptor");
    handle.seek(SeekFrom::Start(0)).expect("rewind");
    let header = CustodyFrameHeaderV1::new(class, generation).expect("a header");
    let (mut entries, mut directories, mut files, mut content_bytes) = (0, 0, 0, 0);
    {
        let reader = BufReader::new(&handle);
        let mut decoder =
            CustodyFrameDecoderV1::new(reader, &header, frame_budget()).expect("a decoder");
        while let Some(entry) = decoder.next_entry().expect("a whole frame") {
            entries += 1;
            match entry {
                CustodyFrameEntryV1::Directory { .. } => directories += 1,
                CustodyFrameEntryV1::Regular {
                    length,
                    mut content,
                    ..
                } => {
                    files += 1;
                    content_bytes += length;
                    std::io::copy(&mut content, &mut std::io::sink()).expect("its content");
                }
                CustodyFrameEntryV1::Symlink { .. } => {}
            }
        }
    }
    handle.seek(SeekFrom::Start(0)).expect("rewind");
    (entries, directories, files, content_bytes)
}

fn position(one: &StagedPlaintextV1) -> u64 {
    use std::io::Seek as _;
    (&one.file).stream_position().expect("a position")
}

/// The last step a flow that ran pass A has completed: B1a is called after it.
const B1A_COMPLETED_V1: Option<GitPlaneStepV1> = Some(GitPlaneStepV1::BootstrapGate);

/// Holds a refusal to pass A's failure shape: no active materialization began, the caller's last completed
/// step is carried unchanged, and the ledger figure is the one ledger's, exactly as it was before the call.
fn require_failure_shape(
    failure: GitBootstrapFailureV1,
    completed: Option<GitPlaneStepV1>,
    ledger: u64,
) -> GitBootstrapErrorV1 {
    assert!(
        !failure.active_materialization_began,
        "prevalidation writes nothing, so no materialization began: {:?}",
        failure.cause
    );
    assert_eq!(failure.last_completed, completed, "{:?}", failure.cause);
    assert_eq!(failure.ledger_used, ledger, "{:?}", failure.cause);
    failure.cause
}

/// The real entry point after pass A, with the refusal's cause returned and its shape checked.
fn prevalidate(
    verified: &mut VerifiedCapsuleV1,
    deadline: Instant,
) -> Result<ActiveFramePlanV1, GitBootstrapErrorV1> {
    let ledger = ledger_used(verified);
    prevalidate_active_frames_v1(verified, frame_budget(), deadline, B1A_COMPLETED_V1)
        .map_err(|failure| require_failure_shape(failure, B1A_COMPLETED_V1, ledger))
}

// ---------------------------------------------------------------------------------------------
// Successful controls: the real frames, and the whole master allowlist
// ---------------------------------------------------------------------------------------------

/// The rich capsule's two real frames prevalidate. The plan names each by class and staged index with the
/// staged length and digest, and its counts equal the test's own decode. Nothing is written, no ledger
/// entry is charged, every staged descriptor is back at offset 0, and a second run returns the same plan.
#[test]
fn b1a_the_rich_capsules_real_frames_prevalidate_and_change_nothing() {
    let fixture = PlanFixtureV1::rich_clone();
    let (manifest, capability, _receipts) = fixture.planned();
    let _ = expect_sealed(
        fixture
            .export(&manifest, capability)
            .expect("the rich export seals"),
    );
    let (dest, mut verified) = phase_v(&fixture.capsule_dir());
    let ledger = ledger_used(&verified);
    let tree = snapshot(&dest.path);

    let plan = prevalidate(&mut verified, far_deadline()).expect("the real frames prevalidate");
    // Checked before the test's own decode, which shares (and rewinds) each descriptor's offset.
    assert!(
        verified.staged.iter().all(|one| position(one) == 0),
        "every staged descriptor is back at offset 0"
    );
    let generation = verified.control.manifest.generation_id().to_owned();
    assert_eq!(
        plan.frames
            .iter()
            .map(|frame| frame.class)
            .collect::<Vec<_>>(),
        [REFS_V1, LOGS_V1]
    );
    for frame in &plan.frames {
        let staged = &verified.staged[frame.staged];
        assert_eq!(
            staged.role,
            CustodyCapsuleArtifactRoleV1::CoveragePayload(frame.class)
        );
        assert_eq!((frame.length, frame.sha256), (staged.length, staged.sha256));
        let (entries, directories, files, content_bytes) =
            independent_summary(&staged.file, frame.class, &generation);
        assert_eq!(
            (
                frame.entries,
                frame.directories,
                frame.regular_files,
                frame.content_bytes
            ),
            (entries, directories, files, content_bytes),
            "{:?}",
            frame.class
        );
        assert!(frame.entries > 1 && frame.regular_files > 0);
        assert_eq!(frame.entries, frame.directories + frame.regular_files);
    }
    assert_eq!(ledger_used(&verified), ledger);
    assert_eq!(snapshot(&dest.path), tree);
    assert_eq!(dest.entries(), [".restore-work"]);

    let again = prevalidate(&mut verified, far_deadline()).expect("a second run");
    assert_eq!(again, plan, "the same frames give the same plan");
}

/// Every exactly-allowed name in its actual class is admitted, in both frames, with the counts the test
/// knows, and the plan's retained facts bind the frames.
#[test]
fn b1a_the_master_allowlist_is_admitted_in_its_actual_classes() {
    let capsule = frames_capsule();
    let refs: &[(&[u8], EntryV1<'_>)] = &[
        (b"HEAD", EntryV1::File(HEAD_BYTES_V1)),
        (
            b"ORIG_HEAD",
            EntryV1::File(b"0123456789012345678901234567890123456789\n"),
        ),
        (b"FETCH_HEAD", EntryV1::File(b"fetched\n")),
        (b"packed-refs", EntryV1::File(b"# pack-refs with: peeled\n")),
        (b"refs", EntryV1::Dir),
        (b"refs/heads", EntryV1::Dir),
        (b"refs/heads/feature", EntryV1::Dir),
        (b"refs/heads/feature/x", EntryV1::File(b"oid\n")),
        (b"refs/heads/main", EntryV1::File(b"oid\n")),
        (b"refs/tags", EntryV1::Dir),
        (b"refs/tags/v1.0", EntryV1::File(b"oid\n")),
        (b"refs/stash", EntryV1::File(b"oid\n")),
    ];
    let logs: &[(&[u8], EntryV1<'_>)] = &[
        (b"logs", EntryV1::Dir),
        (b"logs/HEAD", EntryV1::File(b"log\n")),
        (b"logs/refs", EntryV1::Dir),
        (b"logs/refs/heads", EntryV1::Dir),
        (b"logs/refs/heads/main", EntryV1::File(b"log\n")),
        (b"logs/refs/stash", EntryV1::File(b"log\n")),
    ];
    let mut case = CaseV1::with_entries(&capsule, refs, Some(logs));
    let plan = case.accepted("the whole allowlist");
    assert_eq!(plan.frames.len(), 2);
    let refs_frame = &plan.frames[0];
    assert_eq!(
        (
            refs_frame.class,
            refs_frame.entries,
            refs_frame.directories,
            refs_frame.regular_files
        ),
        (REFS_V1, 12, 4, 8)
    );
    assert_eq!(
        refs_frame.content_bytes,
        (HEAD_BYTES_V1.len() + 41 + 8 + 25 + 4 * 4) as u64
    );
    let logs_frame = &plan.frames[1];
    assert_eq!(
        (
            logs_frame.class,
            logs_frame.entries,
            logs_frame.directories,
            logs_frame.regular_files,
            logs_frame.content_bytes
        ),
        (LOGS_V1, 6, 3, 3, 4 * 3)
    );
    for frame in &plan.frames {
        let staged = &case.verified.staged[frame.staged];
        assert_eq!((frame.length, frame.sha256), (staged.length, staged.sha256));
    }

    // A refs frame that is only a `HEAD` (an unborn repository) is whole; B1b owns its grammar.
    let mut only_head = CaseV1::refs_only(&capsule, &[]);
    let plan = only_head.accepted("HEAD alone");
    assert_eq!(
        (
            plan.frames.len(),
            plan.frames[0].entries,
            plan.frames[0].regular_files
        ),
        (1, 1, 1)
    );
}

/// Pass A still accepts the existing all-Empty capsule for both caller formats and reports no active
/// frame; complete G's first rule then refuses it with the typed Empty-refs refusal. The refusal leaves the
/// original ledger, every pin, and the destination exactly as Pass A left them, and creates no repository.
#[test]
fn b1a_an_all_empty_capsule_is_accepted_by_pass_a_and_refused_by_the_complete_g_rule() {
    for format in [
        CustodyGitObjectFormatV1::Sha1,
        CustodyGitObjectFormatV1::Sha256,
    ] {
        let capsule = empty(format);
        let (dest, verified) = phase_v(&capsule.capsule);
        let mut accepted = must_bootstrap(verified, core_format(format));
        assert!(accepted.active_frames.is_empty(), "{format:?}");
        assert_eq!(
            accepted.provenance,
            GitFormatProvenanceV1::CallerSelectedEmpty
        );

        let ledger = ledger_used(&accepted.verified);
        let tree = snapshot(&dest.path);
        let pins: Vec<String> = accepted.directories.keys().cloned().collect();
        let error = prevalidate(&mut accepted.verified, far_deadline())
            .expect_err("complete G refuses Empty refs");
        assert!(
            matches!(error, GitBootstrapErrorV1::EmptyRefsAndHead),
            "{format:?}: {error:?}"
        );
        assert_eq!(ledger_used(&accepted.verified), ledger, "{format:?}");
        assert_eq!(snapshot(&dest.path), tree, "{format:?}: a byte was written");
        assert_eq!(
            dest.entries(),
            [".restore-work"],
            "{format:?}: no repository"
        );
        assert_eq!(
            accepted.directories.keys().cloned().collect::<Vec<_>>(),
            pins,
            "{format:?}: the pins are retained"
        );

        // The rule is independent of Pass A: the same refusal on a fresh phase-V value.
        let (dest, mut verified) = phase_v(&capsule.capsule);
        let ledger = ledger_used(&verified);
        let error = prevalidate(&mut verified, far_deadline())
            .expect_err("Empty refs refuse without Pass A");
        assert!(
            matches!(error, GitBootstrapErrorV1::EmptyRefsAndHead),
            "{error:?}"
        );
        assert_eq!(ledger_used(&verified), ledger);
        assert_eq!(dest.entries(), [".restore-work"]);
        assert_eq!(dest.work_entries(), ["plain"]);
    }
}

/// Empty refs refuse even beside a Captured reflog frame, and before ANY frame is read.
#[test]
fn b1a_empty_refs_refuse_before_any_frame_is_read() {
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let logs = encode_frame(LOGS_V1, &generation, &[(b"logs", EntryV1::Dir)]);
    let mut case = CaseV1::with_bytes(&capsule, &[(LOGS_V1, logs)]);
    let labels = std::rc::Rc::new(std::cell::RefCell::new(Vec::<&'static str>::new()));
    let seen = labels.clone();
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        seen.borrow_mut().push(event.label);
    });
    let error = case.refusal("Empty refs beside a Captured reflog frame");
    assert!(
        matches!(error, GitBootstrapErrorV1::EmptyRefsAndHead),
        "{error:?}"
    );
    assert!(
        !labels
            .borrow()
            .iter()
            .any(|label| label.starts_with("frame-")),
        "no frame was rehashed or decoded: {:?}",
        labels.borrow()
    );
}

/// Impossible and unsupported coverage states refuse through the B1a entry as they do through Pass A,
/// for both active classes, and are never downgraded to Empty.
#[test]
fn b1a_active_coverage_states_that_cannot_be_restored_refuse() {
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    for class in [REFS_V1, LOGS_V1] {
        let frame = || encode_frame(class, &generation, &with_head(&[]));
        // Captured with no staged payload.
        let (dest, mut verified) = phase_v(&capsule.capsule);
        verified.control.manifest =
            manifest_with_row(class, CustodyStateClassV1::Captured, &verified);
        let error = prevalidate(&mut verified, far_deadline())
            .expect_err("a Captured class without its payload");
        assert!(
            matches!(&error, GitBootstrapErrorV1::UnsupportedCoverage { class: found, detail }
                if *found == class && detail.contains("exactly one")),
            "{class:?}: {error:?}"
        );
        assert_eq!(dest.entries(), [".restore-work"]);

        // Captured with two staged payloads.
        let mut case = CaseV1::with_bytes(&capsule, &[(class, frame())]);
        let twin = StagedPlaintextV1 {
            name: LosslessPathV1::from_bytes(b"test/twin".to_vec()),
            role: CustodyCapsuleArtifactRoleV1::CoveragePayload(class),
            file: case.verified.staged[staged_index(&case.verified, class)]
                .file
                .try_clone()
                .expect("a duplicate descriptor"),
            length: 1,
            sha256: [0; 32],
        };
        case.verified.staged.push(twin);
        let error = case.refusal("two payloads");
        assert!(
            matches!(&error, GitBootstrapErrorV1::UnsupportedCoverage { class: found, detail }
                if *found == class && detail.contains("exactly one")),
            "{class:?}: {error:?}"
        );

        // Empty with a staged payload (the refs class is Captured so only this class is wrong).
        let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, with_head_frame(&generation))]);
        if class == LOGS_V1 {
            stage_frame(&mut case.verified, LOGS_V1, &frame());
            case.verified.control.manifest =
                manifest_with_row(LOGS_V1, CustodyStateClassV1::Empty, &case.verified);
        } else {
            case.verified.control.manifest =
                manifest_with_row(REFS_V1, CustodyStateClassV1::Empty, &case.verified);
        }
        let error = case.refusal("Empty with a payload");
        assert!(
            matches!(&error, GitBootstrapErrorV1::UnsupportedCoverage { class: found, detail }
                if *found == class && detail.contains("Empty active class")),
            "{class:?}: {error:?}"
        );

        // Neither Captured nor Empty.
        let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, with_head_frame(&generation))]);
        case.verified.control.manifest =
            manifest_with_row(class, CustodyStateClassV1::Unresolved, &case.verified);
        let error = case.refusal("Unresolved");
        assert!(
            matches!(&error, GitBootstrapErrorV1::UnsupportedCoverage { class: found, .. }
                if *found == class),
            "{class:?}: {error:?}"
        );
    }
}

fn with_head_frame(generation: &str) -> Vec<u8> {
    encode_frame(REFS_V1, generation, &with_head(&[]))
}

// ---------------------------------------------------------------------------------------------
// Exactly one HEAD, the exact allowlist, class ownership, types, symlinks
// ---------------------------------------------------------------------------------------------

/// A Captured refs class holds exactly one `HEAD` regular file. Absent, a directory, or a symlink
/// refuses, with no repository and no byte written, and nothing is synthesized or copied from the
/// bootstrap.
#[test]
fn b1a_captured_refs_need_exactly_one_head_regular_file() {
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let refs_frame = |entries: &EntriesV1<'_>| encode_frame(REFS_V1, &generation, entries);

    let none_at_all = refs_frame(&[]);
    let no_head = refs_frame(&[(b"refs", EntryV1::Dir), (b"refs/heads", EntryV1::Dir)]);
    let only_orig = refs_frame(&[(b"ORIG_HEAD", EntryV1::File(b"x\n"))]);
    for (row, bytes) in [
        ("an empty frame", none_at_all),
        ("refs without a HEAD", no_head),
        ("ORIG_HEAD is not HEAD", only_orig),
    ] {
        let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, bytes)]);
        case.fault(row, REFS_V1, ActiveFrameFaultV1::MissingHead);
    }

    let mut case = CaseV1::with_bytes(
        &capsule,
        &[(REFS_V1, refs_frame(&[(b"HEAD", EntryV1::Dir)]))],
    );
    case.fault(
        "HEAD as a directory",
        REFS_V1,
        ActiveFrameFaultV1::WrongType {
            path: "HEAD".into(),
            expected: ActiveEntryKindV1::Regular,
        },
    );

    let mut case = CaseV1::with_bytes(
        &capsule,
        &[(
            REFS_V1,
            refs_frame(&[(b"HEAD", EntryV1::Link(b"refs/heads/main"))]),
        )],
    );
    case.fault(
        "HEAD as a symlink",
        REFS_V1,
        ActiveFrameFaultV1::Symlink {
            path: "HEAD".into(),
        },
    );

    // The control: a HEAD regular file is exactly what is needed, whatever it says.
    let mut case = CaseV1::with_bytes(
        &capsule,
        &[(REFS_V1, refs_frame(&[(b"HEAD", EntryV1::File(b""))]))],
    );
    case.accepted("an empty HEAD regular file is a B1b grammar question, not B1a's");
}

/// The exact master allowlist and nothing else: a name another class owns, an unsupported name, a lock
/// name, or an unknown name refuses. Each row is a frame whose `HEAD` is fine, so only the named entry
/// can be the cause.
#[test]
fn b1a_only_the_exact_allowlist_is_admitted_per_class() {
    let capsule = frames_capsule();
    let foreign = |path: &str, owner: ClassV1| ActiveFrameFaultV1::ForeignClass {
        path: path.into(),
        owner,
    };
    let unsupported = |path: &str| ActiveFrameFaultV1::Unsupported { path: path.into() };
    let config = ClassV1::GitConfigurationAndHooks;
    let operation = ClassV1::InProgressGitOperations;
    type RowV1 = (
        &'static str,
        Vec<(&'static [u8], EntryV1<'static>)>,
        ActiveFrameFaultV1,
    );
    let refs_rows: Vec<RowV1> = vec![
        (
            "config",
            vec![file("config", b"[core]\n")],
            foreign("config", config),
        ),
        (
            "hooks",
            vec![dir("hooks"), file("hooks/pre-commit", b"#!\n")],
            foreign("hooks", config),
        ),
        ("info", vec![dir("info")], foreign("info", config)),
        (
            "objects",
            vec![dir("objects")],
            foreign("objects", ClassV1::ObjectDatabase),
        ),
        (
            "an alternates file",
            vec![
                dir("objects"),
                dir("objects/info"),
                file("objects/info/alternates", b"/elsewhere\n"),
            ],
            foreign("objects", ClassV1::ObjectDatabase),
        ),
        (
            "MERGE_HEAD",
            vec![file("MERGE_HEAD", b"x\n")],
            foreign("MERGE_HEAD", operation),
        ),
        (
            "rebase-merge",
            vec![dir("rebase-merge")],
            foreign("rebase-merge", operation),
        ),
        (
            "CHERRY_PICK_HEAD",
            vec![file("CHERRY_PICK_HEAD", b"x\n")],
            foreign("CHERRY_PICK_HEAD", operation),
        ),
        (
            "BISECT_LOG",
            vec![file("BISECT_LOG", b"x\n")],
            foreign("BISECT_LOG", operation),
        ),
        (
            "index",
            vec![file("index", b"x")],
            foreign("index", ClassV1::Index),
        ),
        (
            "bridge evidence",
            vec![dir("a2a-bridge")],
            foreign("a2a-bridge", ClassV1::BridgeEvidence),
        ),
        (
            "logs inside the refs frame",
            vec![dir("logs")],
            foreign("logs", LOGS_V1),
        ),
        (
            "shallow",
            vec![file("shallow", b"x\n")],
            unsupported("shallow"),
        ),
        (
            "a lock file",
            vec![file("HEAD.lock", b"")],
            unsupported("HEAD.lock"),
        ),
        (
            "an unknown name",
            vec![file("surprise", b"")],
            unsupported("surprise"),
        ),
        (
            "linked worktrees",
            vec![dir("worktrees")],
            foreign("worktrees", ClassV1::LinkedWorktrees),
        ),
    ];
    for (row, entries, fault) in refs_rows {
        let mut case = CaseV1::refs_only(&capsule, &entries);
        case.fault(row, REFS_V1, fault);
    }

    let logs_rows: Vec<RowV1> = vec![
        (
            "HEAD inside the logs frame",
            vec![file("HEAD", b"x\n")],
            foreign("HEAD", REFS_V1),
        ),
        (
            "refs inside the logs frame",
            vec![dir("refs")],
            foreign("refs", REFS_V1),
        ),
        (
            "packed-refs inside the logs frame",
            vec![file("packed-refs", b"")],
            foreign("packed-refs", REFS_V1),
        ),
        (
            "config inside the logs frame",
            vec![file("config", b"")],
            foreign("config", config),
        ),
        (
            "shallow inside the logs frame",
            vec![file("shallow", b"")],
            unsupported("shallow"),
        ),
        (
            "an unknown name inside the logs frame",
            vec![dir("surprise")],
            unsupported("surprise"),
        ),
    ];
    for (row, entries, fault) in logs_rows {
        let mut case = CaseV1::with_entries(&capsule, &[], Some(&entries));
        case.fault(row, LOGS_V1, fault);
    }
}

/// Each top-level allowlisted name has its own entry type: files are regular, `refs` and `logs` are
/// directories.
#[test]
fn b1a_top_level_names_must_have_their_class_type() {
    let capsule = frames_capsule();
    let wrong = |path: &str, expected| ActiveFrameFaultV1::WrongType {
        path: path.into(),
        expected,
    };
    for name in ["ORIG_HEAD", "FETCH_HEAD", "packed-refs"] {
        let mut case = CaseV1::refs_only(&capsule, &[(name.as_bytes(), EntryV1::Dir)]);
        case.fault(name, REFS_V1, wrong(name, ActiveEntryKindV1::Regular));
    }
    let mut case = CaseV1::refs_only(&capsule, &[(b"refs", EntryV1::File(b"x"))]);
    case.fault(
        "refs as a regular file",
        REFS_V1,
        wrong("refs", ActiveEntryKindV1::Directory),
    );
    let mut case = CaseV1::with_entries(&capsule, &[], Some(&[(b"logs", EntryV1::File(b"x"))]));
    case.fault(
        "logs as a regular file",
        LOGS_V1,
        wrong("logs", ActiveEntryKindV1::Directory),
    );
}

/// A symlink is refused wherever the frame carries one: at a top-level name, under `refs/`, and under
/// `logs/`. A valid frame (its trailer verifies) holding a `refs` symlink refuses before any write.
#[test]
fn b1a_symlinks_are_refused_wherever_the_frame_carries_them() {
    let capsule = frames_capsule();
    let link = |path: &str| ActiveFrameFaultV1::Symlink { path: path.into() };
    let mut case = CaseV1::refs_only(&capsule, &[(b"refs", EntryV1::Link(b"/elsewhere"))]);
    case.fault("a refs symlink", REFS_V1, link("refs"));
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/heads", EntryV1::Dir),
            (b"refs/heads/main", EntryV1::Link(b"../../elsewhere")),
        ],
    );
    case.fault("a link beneath refs", REFS_V1, link("refs/heads/main"));
    let mut case = CaseV1::refs_only(&capsule, &[(b"packed-refs", EntryV1::Link(b"x"))]);
    case.fault("a packed-refs symlink", REFS_V1, link("packed-refs"));
    let mut case = CaseV1::with_entries(
        &capsule,
        &[],
        Some(&[
            (b"logs", EntryV1::Dir),
            (b"logs/HEAD", EntryV1::Link(b"/etc/passwd")),
        ]),
    );
    case.fault("a link beneath logs", LOGS_V1, link("logs/HEAD"));
    // A symlink under a name no class owns is still a symlink first.
    let mut case = CaseV1::refs_only(&capsule, &[(b"config", EntryV1::Link(b"x"))]);
    case.fault("a config symlink", REFS_V1, link("config"));
}

// ---------------------------------------------------------------------------------------------
// Portable spelling and collisions
// ---------------------------------------------------------------------------------------------

/// The portable component rule: printable ASCII `0x21..=0x7e`, no backslash, no trailing dot. Every
/// other spelling refuses with its own reason, never normalized: NFC and NFD, a lone invalid byte,
/// a backslash, a trailing dot or space, a control byte, an interior space, DEL.
#[test]
fn b1a_the_portable_spelling_rule_refuses_every_other_component() {
    let capsule = frames_capsule();
    let nfc: &[u8] = "caf\u{e9}".as_bytes();
    let nfd: &[u8] = "cafe\u{301}".as_bytes();
    assert_ne!(nfc, nfd);
    let refused: Vec<(&str, &[u8], PortableFaultV1)> = vec![
        ("NFC", nfc, PortableFaultV1::NonAscii),
        ("NFD", nfd, PortableFaultV1::NonAscii),
        ("a lone 0xff", b"a\xff", PortableFaultV1::NonAscii),
        ("a truncated sequence", b"a\xc3", PortableFaultV1::NonAscii),
        ("a backslash", b"a\\b", PortableFaultV1::Backslash),
        ("a leading backslash", b"\\a", PortableFaultV1::Backslash),
        ("a trailing dot", b"a.", PortableFaultV1::TrailingDot),
        ("two trailing dots", b"a..", PortableFaultV1::TrailingDot),
        ("a trailing space", b"a ", PortableFaultV1::Unprintable),
        ("an interior space", b"a b", PortableFaultV1::Unprintable),
        ("a tab", b"a\tb", PortableFaultV1::Unprintable),
        ("a control byte", b"a\x01b", PortableFaultV1::Unprintable),
        ("DEL", b"a\x7fb", PortableFaultV1::Unprintable),
    ];
    for (row, name, reason) in refused {
        let mut path = b"refs/heads/".to_vec();
        path.extend_from_slice(name);
        let mut case = CaseV1::refs_only(
            &capsule,
            &[
                (b"refs", EntryV1::Dir),
                (b"refs/heads", EntryV1::Dir),
                (&path, EntryV1::File(b"oid\n")),
            ],
        );
        case.fault(
            row,
            REFS_V1,
            ActiveFrameFaultV1::NonPortable {
                path: path_string(&path),
                reason,
            },
        );
    }
    // The same rule governs the logs class and every component, not only the last.
    let mut case = CaseV1::with_entries(
        &capsule,
        &[],
        Some(&[(b"logs", EntryV1::Dir), (b"logs/a ", EntryV1::Dir)]),
    );
    case.fault(
        "a logs component",
        LOGS_V1,
        ActiveFrameFaultV1::NonPortable {
            path: "logs/a ".into(),
            reason: PortableFaultV1::Unprintable,
        },
    );
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/d.", EntryV1::Dir),
            (b"refs/d./x", EntryV1::File(b"oid\n")),
        ],
    );
    case.fault(
        "a directory component",
        REFS_V1,
        ActiveFrameFaultV1::NonPortable {
            path: "refs/d.".into(),
            reason: PortableFaultV1::TrailingDot,
        },
    );

    // Controls: every other admitted byte, including punctuation and an interior or leading dot.
    for name in [
        "a.b", ".hidden", "a-b_c", "x~1", "A", "0", "a@b", "a{b}", "~",
    ] {
        let mut path = b"refs/heads/".to_vec();
        path.extend_from_slice(name.as_bytes());
        let mut case = CaseV1::refs_only(
            &capsule,
            &[
                (b"refs", EntryV1::Dir),
                (b"refs/heads", EntryV1::Dir),
                (&path, EntryV1::File(b"oid\n")),
            ],
        );
        let _ = case.accepted(name);
    }
}

/// Two distinct spellings that share the ASCII-lowercased key refuse, in either order and at any depth,
/// in either class. The key lowercases only `A..Z`: `@` and the backtick, which differ by 0x20 outside
/// the letters, stay distinct, and so do `a/b` and `ab`.
#[test]
fn b1a_ascii_case_collisions_refuse_and_distinct_spellings_do_not() {
    let capsule = frames_capsule();
    let collision = |path: &str, with: &str| ActiveFrameFaultV1::Collision {
        path: path.into(),
        with: with.into(),
    };
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/heads", EntryV1::Dir),
            (b"refs/heads/A", EntryV1::File(b"1\n")),
            (b"refs/heads/a", EntryV1::File(b"2\n")),
        ],
    );
    // Canonical order puts `A` (0x41) before `a` (0x61).
    case.fault(
        "A/a files",
        REFS_V1,
        collision("refs/heads/a", "refs/heads/A"),
    );
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/Heads", EntryV1::Dir),
            (b"refs/Heads/x", EntryV1::File(b"1\n")),
            (b"refs/heads", EntryV1::Dir),
            (b"refs/heads/x", EntryV1::File(b"2\n")),
        ],
    );
    case.fault(
        "case-differing directories",
        REFS_V1,
        collision("refs/heads", "refs/Heads"),
    );
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/tags", EntryV1::Dir),
            (b"refs/tags/V1", EntryV1::File(b"1\n")),
            (b"refs/tags/v1", EntryV1::File(b"2\n")),
        ],
    );
    case.fault("V1/v1", REFS_V1, collision("refs/tags/v1", "refs/tags/V1"));
    let mut case = CaseV1::with_entries(
        &capsule,
        &[],
        Some(&[
            (b"logs", EntryV1::Dir),
            (b"logs/refs", EntryV1::Dir),
            (b"logs/refs/Main", EntryV1::File(b"1\n")),
            (b"logs/refs/main", EntryV1::File(b"2\n")),
        ]),
    );
    case.fault(
        "reflog names",
        LOGS_V1,
        collision("logs/refs/main", "logs/refs/Main"),
    );
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/heads", EntryV1::Dir),
            (b"refs/heads/MiXeD", EntryV1::File(b"1\n")),
            (b"refs/heads/mixed", EntryV1::File(b"2\n")),
        ],
    );
    case.fault(
        "mixed case",
        REFS_V1,
        collision("refs/heads/mixed", "refs/heads/MiXeD"),
    );

    // Distinct spellings, and bytes that differ by 0x20 outside the letters, are different keys.
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/heads", EntryV1::Dir),
            (b"refs/heads/a", EntryV1::File(b"1\n")),
            (b"refs/heads/b", EntryV1::File(b"2\n")),
            (b"refs/heads/@", EntryV1::File(b"3\n")),
            (b"refs/heads/`", EntryV1::File(b"4\n")),
            (b"refs/heads/[", EntryV1::File(b"5\n")),
            (b"refs/heads/{", EntryV1::File(b"6\n")),
            (b"refs/heads/ab", EntryV1::File(b"7\n")),
            (b"refs/heads/a.b", EntryV1::File(b"8\n")),
            (b"refs/heads/a_b", EntryV1::File(b"9\n")),
            (b"refs/heads/a-b", EntryV1::File(b"0\n")),
        ],
    );
    let plan = case.accepted("distinct spellings");
    assert_eq!(
        plan.frames[0].regular_files,
        10 + 1,
        "ten branches and HEAD"
    );
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/a", EntryV1::Dir),
            (b"refs/a/b", EntryV1::File(b"1\n")),
            (b"refs/ab", EntryV1::File(b"2\n")),
        ],
    );
    let _ = case.accepted("component boundaries are part of the key");
}

// ---------------------------------------------------------------------------------------------
// The aggregate table, driven directly (the one table every frame of a restore feeds)
// ---------------------------------------------------------------------------------------------

/// The aggregate path table refuses what only the aggregate can see: the same path twice, a spelling
/// collision across entries that did not come from one frame, a parent that is absent, a regular file, or
/// spelled differently, an inactive class, and an overrun of its own bound; and its `finish` requires a
/// regular `HEAD`.
#[test]
fn b1a_the_aggregate_table_refuses_what_only_the_aggregate_sees() {
    use ActiveEntryKindV1::{Directory, Regular, Symlink};
    let bound = 1 << 20;
    let admit = |table: &mut ActivePathTableV1, class, path: &str, kind| {
        table.admit(class, path.as_bytes(), kind)
    };

    let mut table = ActivePathTableV1::new(bound);
    admit(&mut table, REFS_V1, "refs", Directory).expect("refs");
    assert_eq!(
        admit(&mut table, REFS_V1, "refs", Directory),
        Err(ActiveFrameFaultV1::Duplicate {
            path: "refs".into()
        }),
        "the same path from a second frame"
    );
    admit(&mut table, REFS_V1, "refs/heads", Directory).expect("refs/heads");
    admit(&mut table, REFS_V1, "refs/heads/A", Regular).expect("refs/heads/A");
    assert_eq!(
        admit(&mut table, REFS_V1, "refs/heads/a", Regular),
        Err(ActiveFrameFaultV1::Collision {
            path: "refs/heads/a".into(),
            with: "refs/heads/A".into()
        }),
        "a collision with an entry of an earlier frame"
    );
    assert_eq!(
        admit(&mut table, REFS_V1, "refs/tags/x", Regular),
        Err(ActiveFrameFaultV1::Conflict {
            path: "refs/tags/x".into()
        }),
        "an absent parent"
    );
    admit(&mut table, REFS_V1, "packed-refs", Regular).expect("packed-refs");
    assert_eq!(
        admit(&mut table, REFS_V1, "packed-refs/x", Regular),
        Err(ActiveFrameFaultV1::Conflict {
            path: "packed-refs/x".into()
        }),
        "a regular file is not a parent"
    );
    assert_eq!(
        admit(&mut table, REFS_V1, "refs/Heads/x", Regular),
        Err(ActiveFrameFaultV1::Conflict {
            path: "refs/Heads/x".into()
        }),
        "a parent spelled differently is not the parent"
    );
    assert_eq!(
        admit(&mut table, REFS_V1, "refs/heads/s", Symlink),
        Err(ActiveFrameFaultV1::Symlink {
            path: "refs/heads/s".into()
        })
    );
    assert_eq!(
        admit(&mut table, ClassV1::ObjectDatabase, "objects", Directory),
        Err(ActiveFrameFaultV1::InactiveClass {
            class: ClassV1::ObjectDatabase
        })
    );
    // The refusals admitted nothing: the earlier entries are the whole table, and there is no HEAD.
    assert_eq!(table.entries(), 4);
    assert_eq!(table.finish(), Err(ActiveFrameFaultV1::MissingHead));
    admit(&mut table, REFS_V1, "HEAD", Regular).expect("HEAD");
    assert_eq!(table.finish(), Ok(()));

    // A HEAD from the wrong class is not the refs class's HEAD.
    let mut table = ActivePathTableV1::new(bound);
    assert_eq!(
        admit(&mut table, LOGS_V1, "HEAD", Regular),
        Err(ActiveFrameFaultV1::ForeignClass {
            path: "HEAD".into(),
            owner: REFS_V1
        })
    );
    assert_eq!(table.finish(), Err(ActiveFrameFaultV1::MissingHead));

    // Its own bound: 4 entries' keys and spellings do not fit in a handful of bytes.
    let mut table = ActivePathTableV1::new(64);
    let mut refused = None;
    for path in ["HEAD", "ORIG_HEAD", "FETCH_HEAD", "packed-refs"] {
        if let Err(fault) = admit(&mut table, REFS_V1, path, Regular) {
            refused = Some(fault);
            break;
        }
    }
    assert_eq!(
        refused,
        Some(ActiveFrameFaultV1::PathTableBound { bound: 64 })
    );
}

/// The bound is a parameter of the entry point, so its refusal is exercised at a small size through the
/// whole decode: a frame whose paths do not fit refuses with the table bound, after the frame verified.
#[test]
fn b1a_the_path_table_bound_refuses_through_the_whole_decode() {
    let capsule = frames_capsule();
    let mut entries: Vec<(Vec<u8>, EntryV1<'static>)> = vec![
        (b"refs".to_vec(), EntryV1::Dir),
        (b"refs/heads".to_vec(), EntryV1::Dir),
    ];
    for index in 0..64 {
        entries.push((
            format!("refs/heads/branch-{index:03}").into_bytes(),
            EntryV1::File(b"oid\n"),
        ));
    }
    let borrowed: Vec<(&[u8], EntryV1<'_>)> = entries
        .iter()
        .map(|(path, entry)| (path.as_slice(), *entry))
        .collect();
    let mut case = CaseV1::refs_only(&capsule, &borrowed);
    // The default bound holds the frame.
    let _ = case.accepted("the default bound");
    let ledger = ledger_used(&case.verified);
    let failure = prevalidate_active_frames_bounded_v1(
        &mut case.verified,
        frame_budget(),
        far_deadline(),
        B1A_COMPLETED_V1,
        1024,
    )
    .expect_err("a small bound refuses");
    let error = require_failure_shape(failure, B1A_COMPLETED_V1, ledger);
    assert!(
        matches!(
            error,
            GitBootstrapErrorV1::ActiveFrame {
                class: REFS_V1,
                fault: ActiveFrameFaultV1::PathTableBound { bound: 1024 }
            }
        ),
        "{error:?}"
    );
    assert_eq!(ledger_used(&case.verified), ledger);
}

// ---------------------------------------------------------------------------------------------
// Complete decode: the trailer, the header, and the staged bytes
// ---------------------------------------------------------------------------------------------

fn flip(bytes: &mut [u8], index: usize) {
    bytes[index] ^= 0xff;
}

/// A whole frame is decoded through its verified trailer before anything is judged final. Every damaged
/// trailer, content digest, header binding, or trailing byte refuses with `FrameInvalid`, even though the
/// provisional entries before the damage were fine, and even when an entry fault came first: the frame's
/// integrity outranks what it says. Controls: the same frames undamaged succeed.
#[test]
fn b1a_a_failed_trailer_after_provisional_entries_refuses_the_whole_frame() {
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let good_entries: &[(&[u8], EntryV1<'_>)] = &[
        (b"refs", EntryV1::Dir),
        (b"refs/heads", EntryV1::Dir),
        (b"refs/heads/main", EntryV1::File(b"oid\n")),
    ];
    let good = encode_frame(REFS_V1, &generation, &with_head(good_entries));
    let invalid = |class| {
        move |error: &GitBootstrapErrorV1| {
            matches!(
                error,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid { class: found })
                    if *found == class
            )
        }
    };

    let mut damaged: Vec<(&str, Vec<u8>)> = Vec::new();
    let mut flipped_digest = good.clone();
    flip(&mut flipped_digest, good.len() - 1);
    damaged.push(("the frame digest's last byte", flipped_digest));
    let mut flipped_count = good.clone();
    flip(&mut flipped_count, good.len() - (DIGEST_BYTES_V1 + 8 + 8));
    damaged.push(("the trailer's entry count", flipped_count));
    let mut flipped_total = good.clone();
    flip(&mut flipped_total, good.len() - (DIGEST_BYTES_V1 + 8));
    damaged.push(("the trailer's content total", flipped_total));
    let mut flipped_tag = good.clone();
    flip(&mut flipped_tag, good.len() - (DIGEST_BYTES_V1 + 8 + 8 + 1));
    damaged.push(("the trailer's tag", flipped_tag));
    damaged.push(("a truncated trailer", good[..good.len() - 8].to_vec()));
    damaged.push(("no trailer at all", good[..good.len() - 49].to_vec()));
    let mut trailing = good.clone();
    trailing.push(0);
    damaged.push(("a byte after the trailer", trailing));
    let content_at = good
        .windows(HEAD_BYTES_V1.len())
        .position(|window| window == HEAD_BYTES_V1)
        .expect("the HEAD content");
    let mut flipped_content = good.clone();
    flip(&mut flipped_content, content_at);
    damaged.push(("a HEAD content byte", flipped_content));
    damaged.push((
        "another generation's header",
        encode_frame(REFS_V1, "another-generation", &with_head(good_entries)),
    ));
    damaged.push((
        "another class's header",
        encode_frame(LOGS_V1, &generation, &with_head(good_entries)),
    ));
    let mut with_link = encode_frame(
        REFS_V1,
        &generation,
        &with_head(&[(b"refs", EntryV1::Dir), (b"refs/l", EntryV1::Link(b"x"))]),
    );
    let last = with_link.len() - 1;
    flip(&mut with_link, last);
    damaged.push(("an entry fault and then a bad trailer", with_link));
    for (row, bytes) in damaged {
        let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, bytes)]);
        let error = case.refusal(row);
        assert!(invalid(REFS_V1)(&error), "{row}: {error:?}");
    }

    // The logs class is whole-decoded too.
    let logs_good = encode_frame(
        LOGS_V1,
        &generation,
        &[
            (b"logs", EntryV1::Dir),
            (b"logs/HEAD", EntryV1::File(b"log\n")),
        ],
    );
    let mut bad_logs = logs_good.clone();
    flip(&mut bad_logs, logs_good.len() - 1);
    let refs_ok = encode_frame(REFS_V1, &generation, &with_head(&[]));
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, refs_ok.clone()), (LOGS_V1, bad_logs)]);
    let error = case.refusal("a bad logs trailer");
    assert!(invalid(LOGS_V1)(&error), "{error:?}");

    // Controls: the undamaged frames.
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, good.clone()), (LOGS_V1, logs_good)]);
    let plan = case.accepted("undamaged frames");
    assert_eq!(plan.frames.len(), 2);
}

/// Staged bytes or length that differ from the verified plaintext refuse before decoding, and name the
/// staged frame: a changed byte, an appended byte, a truncation, an emptied file. Either class.
#[test]
fn b1a_staged_frame_byte_or_length_drift_refuses() {
    use std::os::unix::fs::FileExt as _;
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let refs = encode_frame(REFS_V1, &generation, &with_head(&[]));
    let logs = encode_frame(LOGS_V1, &generation, &[(b"logs", EntryV1::Dir)]);
    type Edit = fn(&std::fs::File);
    let edits: [(&str, Edit); 4] = [
        ("a byte changed", |file| {
            file.write_all_at(&[0xff], 12).expect("change a byte");
        }),
        ("a byte appended", |file| {
            let length = file.metadata().expect("metadata").len();
            file.write_all_at(b"x", length).expect("append");
        }),
        ("truncated", |file| {
            let length = file.metadata().expect("metadata").len();
            file.set_len(length - 1).expect("truncate");
        }),
        ("emptied", |file| file.set_len(0).expect("empty")),
    ];
    for class in [REFS_V1, LOGS_V1] {
        for (row, edit) in edits {
            let mut case = CaseV1::with_bytes(
                &capsule,
                &[(REFS_V1, refs.clone()), (LOGS_V1, logs.clone())],
            );
            let index = staged_index(&case.verified, class);
            edit(&case.verified.staged[index].file);
            let name = lossy(case.verified.staged[index].name.as_bytes());
            let error = case.refusal(&format!("{class:?}: {row}"));
            assert!(
                matches!(&error, GitBootstrapErrorV1::StagedInputChanged { name: found }
                    if *found == name),
                "{class:?}: {row}: {error:?}"
            );
        }
    }
}

/// A frame replaced between its rehash and its decode (with another well-formed frame, so only the
/// verified staged digest can tell) is refused: the decoded bytes are bound to the verified plaintext.
#[test]
fn b1a_a_frame_changed_between_the_rehash_and_the_decode_is_refused() {
    use std::os::unix::fs::FileExt as _;
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    // The replacement is shorter: the decode reads it whole, so only the verified digest can tell.
    let refs = encode_frame(
        REFS_V1,
        &generation,
        &with_head(&[(b"refs", EntryV1::Dir), (b"refs/heads", EntryV1::Dir)]),
    );
    let other = encode_frame(REFS_V1, &generation, &with_head(&[]));
    assert!(other.len() < refs.len());
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, refs)]);
    let handle = case.verified.staged[staged_index(&case.verified, REFS_V1)]
        .file
        .try_clone()
        .expect("a duplicate descriptor");
    let swapped = std::cell::Cell::new(false);
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        if event.label == "frame-rewind" && !swapped.replace(true) {
            handle.set_len(0).expect("empty the frame");
            handle.write_all_at(&other, 0).expect("another frame");
        }
    });
    let error = case.refusal("a frame swapped after its rehash");
    assert!(
        matches!(error, GitBootstrapErrorV1::StagedInputChanged { .. }),
        "{error:?}"
    );
}

/// A frame assembled byte by byte, with a correct trailer and digest, for structures the encoder will
/// not emit: each record is already encoded.
fn raw_frame(
    class_code: u8,
    generation: &str,
    records: &[Vec<u8>],
    entries: u64,
    total: u64,
) -> Vec<u8> {
    let mut bytes = b"a2a-cfr1".to_vec();
    bytes.push(1);
    bytes.push(class_code);
    bytes.extend_from_slice(&(generation.len() as u16).to_le_bytes());
    bytes.extend_from_slice(generation.as_bytes());
    for record in records {
        bytes.extend_from_slice(record);
    }
    bytes.push(0xff);
    bytes.extend_from_slice(&entries.to_le_bytes());
    bytes.extend_from_slice(&total.to_le_bytes());
    let frame_digest = sha256_bytes(&bytes);
    bytes.extend_from_slice(&frame_digest);
    bytes
}

fn raw_record(tag: u8, path: &[u8], tail: &[u8]) -> Vec<u8> {
    let mut record = vec![tag];
    record.extend_from_slice(&(path.len() as u16).to_le_bytes());
    record.extend_from_slice(path);
    record.extend_from_slice(tail);
    record
}

fn raw_file(path: &[u8], content: &[u8]) -> Vec<u8> {
    let mut tail = 0o644_u16.to_le_bytes().to_vec();
    tail.extend_from_slice(&(content.len() as u64).to_le_bytes());
    tail.extend_from_slice(content);
    tail.extend_from_slice(&sha256_bytes(content));
    raw_record(2, path, &tail)
}

/// A regular file is never a parent: a hand-built frame with a correct trailer whose entry sits under a
/// regular file is refused whole (by the codec's own structure rule, before the aggregate table sees it),
/// and so is one whose parent directory is simply absent. The aggregate table's own parent rule is
/// exercised directly above.
#[test]
fn b1a_a_hand_built_frame_with_a_file_parent_or_a_missing_parent_is_refused() {
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let whole = |records: &[Vec<u8>], total: u64| {
        raw_frame(1, &generation, records, records.len() as u64, total)
    };

    // Control: the same builder, with entries that are in order and under a directory, is whole.
    let control = whole(
        &[
            raw_file(b"HEAD", b"ref: refs/heads/main\n"),
            raw_record(1, b"refs", &0o755_u16.to_le_bytes()),
            raw_file(b"refs/x", b"1"),
        ],
        21 + 1,
    );
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, control)]);
    let plan = case.accepted("the hand-built control");
    assert_eq!(plan.frames[0].entries, 3);

    let under_a_file = whole(&[raw_file(b"HEAD", b"x"), raw_file(b"HEAD/x", b"y")], 2);
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, under_a_file)]);
    let error = case.refusal("an entry under a regular file");
    assert!(
        matches!(
            error,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid { class: REFS_V1 })
        ),
        "{error:?}"
    );

    let orphan = whole(
        &[raw_file(b"HEAD", b"x"), raw_file(b"refs/heads/main", b"y")],
        2,
    );
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, orphan)]);
    let error = case.refusal("an entry whose parents are absent");
    assert!(
        matches!(
            error,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid { class: REFS_V1 })
        ),
        "{error:?}"
    );
}

/// Every refusal of the real entry point is in pass A's failure shape: no active materialization began,
/// the caller's `completed` step is carried unchanged (whatever it is), and the ledger figure is the one
/// ledger's. The causes span every refusal family: Empty refs, an entry fault, a bad trailer, drift, and
/// a spent deadline. Nothing exists under `repository/`.
#[test]
fn b1a_every_refusal_is_in_the_failure_shape_that_began_no_materialization() {
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let bad_trailer = {
        let mut bytes = encode_frame(REFS_V1, &generation, &with_head(&[]));
        let last = bytes.len() - 1;
        flip(&mut bytes, last);
        bytes
    };
    let linked = encode_frame(
        REFS_V1,
        &generation,
        &with_head(&[(b"refs", EntryV1::Link(b"x"))]),
    );
    for completed in [
        None,
        Some(GitPlaneStepV1::Admission),
        Some(GitPlaneStepV1::BootstrapGate),
    ] {
        let mut rows: Vec<(&str, CaseV1, Instant)> = vec![
            (
                "empty refs",
                CaseV1::with_bytes(&capsule, &[]),
                far_deadline(),
            ),
            (
                "an entry fault",
                CaseV1::with_bytes(&capsule, &[(REFS_V1, linked.clone())]),
                far_deadline(),
            ),
            (
                "a bad trailer",
                CaseV1::with_bytes(&capsule, &[(REFS_V1, bad_trailer.clone())]),
                far_deadline(),
            ),
        ];
        let spent = Instant::now();
        std::thread::sleep(Duration::from_millis(5));
        rows.push((
            "a spent deadline",
            CaseV1::with_entries(&capsule, &[], None),
            spent,
        ));
        for (row, mut case, deadline) in rows {
            let ledger = ledger_used(&case.verified);
            let failure = prevalidate_active_frames_v1(
                &mut case.verified,
                frame_budget(),
                deadline,
                completed,
            )
            .expect_err(row);
            let _ = require_failure_shape(failure, completed, ledger);
            assert_eq!(
                case.dest.entries(),
                [".restore-work"],
                "{row}: no repository"
            );
        }
    }
    // The control: success carries no failure at all.
    let mut case = CaseV1::with_entries(&capsule, &[], None);
    prevalidate_active_frames_v1(&mut case.verified, frame_budget(), far_deadline(), None)
        .expect("a whole refs frame");
}

/// A frame that grows after its rehash is read only one byte past its verified length, never whole: the
/// decoder's source is bounded, so a frame that is not the verified plaintext is refused having consumed
/// at most that one extra byte.
#[test]
fn b1a_a_frame_that_grows_after_its_rehash_is_never_read_past_one_extra_byte() {
    use std::os::unix::fs::FileExt as _;
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let bytes = encode_frame(REFS_V1, &generation, &with_head(&[]));
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, bytes)]);
    let index = staged_index(&case.verified, REFS_V1);
    let handle = case.verified.staged[index]
        .file
        .try_clone()
        .expect("a duplicate descriptor");
    let length = case.verified.staged[index].length;
    let grown = std::cell::Cell::new(false);
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        if event.label == "frame-rewind" && !grown.replace(true) {
            handle
                .write_all_at(&vec![0_u8; 1024 * 1024], length)
                .expect("grow the frame");
        }
    });
    let error = case.refusal("a frame grown after its rehash");
    assert!(
        matches!(
            error,
            GitBootstrapErrorV1::StagedInputChanged { .. }
                | GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid {
                    class: REFS_V1
                })
        ),
        "{error:?}"
    );
    assert_eq!(
        position(&case.verified.staged[index]),
        length + 1,
        "one byte past the verified length, and no more"
    );
}

/// The caller's frame budget bounds the null-sink decode: a frame with more entries than the budget
/// allows, or more bytes, is refused whole, and the same frame under a sufficient budget is whole.
#[test]
fn b1a_the_callers_frame_budget_bounds_the_decode() {
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let bytes = encode_frame(
        REFS_V1,
        &generation,
        &with_head(&[
            dir("refs"),
            dir("refs/heads"),
            file("refs/heads/a", b"1\n"),
            file("refs/heads/b", b"2\n"),
            file("refs/heads/c", b"3\n"),
        ]),
    );
    let length = bytes.len() as u64;
    let run = |budget: CustodyFrameBudgetV1| {
        let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, bytes.clone())]);
        let ledger = ledger_used(&case.verified);
        let outcome = prevalidate_active_frames_bounded_v1(
            &mut case.verified,
            budget,
            far_deadline(),
            B1A_COMPLETED_V1,
            1 << 20,
        );
        assert_eq!(ledger_used(&case.verified), ledger);
        outcome.map_err(|failure| failure.cause)
    };
    let sufficient = CustodyFrameBudgetV1::new(6, length).expect("a budget");
    assert!(run(sufficient).is_ok(), "exactly enough entries and bytes");
    for (row, budget) in [
        (
            "one entry short",
            CustodyFrameBudgetV1::new(5, length).expect("a budget"),
        ),
        (
            "one byte short",
            CustodyFrameBudgetV1::new(6, length - 1).expect("a budget"),
        ),
    ] {
        let error = run(budget).expect_err(row);
        assert!(
            matches!(
                error,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid {
                    class: REFS_V1
                })
            ),
            "{row}: {error:?}"
        );
    }
}

/// The paced rehash, directly: it rewinds before and after, checks length and digest, never reads a
/// grown file whole, and an expired deadline refuses before a byte is read or a descriptor is moved.
#[test]
fn b1a_the_paced_rehash_checks_rewinds_and_reads_a_bounded_prefix() {
    use std::io::{Seek as _, Write as _};
    use std::os::unix::fs::FileExt as _;
    let capsule = frames_capsule();
    let generation = CaseV1::generation(&capsule);
    let bytes = encode_frame(REFS_V1, &generation, &with_head(&[]));
    let fresh = || {
        let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, bytes.clone())]);
        let index = staged_index(&case.verified, REFS_V1);
        (case.verified.staged.swap_remove(index), case)
    };

    // A descriptor left mid-file is rewound first; it ends at offset 0.
    let (mut one, _case) = fresh();
    one.file.seek(SeekFrom::Start(7)).expect("seek");
    reverify_staged_v1(&mut one, far_deadline()).expect("an unchanged frame");
    assert_eq!(position(&one), 0);

    // A same-length change and a truncation refuse by digest and length.
    let (mut one, _case) = fresh();
    one.file.write_all_at(&[0xff], 12).expect("change");
    assert!(matches!(
        reverify_staged_v1(&mut one, far_deadline()),
        Err(GitBootstrapErrorV1::StagedInputChanged { .. })
    ));
    let (mut one, _case) = fresh();
    one.file.set_len(one.length - 1).expect("truncate");
    assert!(matches!(
        reverify_staged_v1(&mut one, far_deadline()),
        Err(GitBootstrapErrorV1::StagedInputChanged { .. })
    ));

    // A grown file is read only one byte past its recorded length, never whole.
    let (mut one, _case) = fresh();
    one.file.seek(SeekFrom::End(0)).expect("seek");
    one.file
        .write_all(&vec![0_u8; 4 * 1024 * 1024])
        .expect("grow it");
    assert!(matches!(
        reverify_staged_v1(&mut one, far_deadline()),
        Err(GitBootstrapErrorV1::StagedInputChanged { .. })
    ));
    assert_eq!(position(&one), one.length + 1, "one byte past the length");

    // An expired deadline refuses before any read or rewind.
    let (mut one, _case) = fresh();
    one.file.seek(SeekFrom::Start(5)).expect("seek");
    let spent = Instant::now();
    std::thread::sleep(Duration::from_millis(5));
    assert!(matches!(
        reverify_staged_v1(&mut one, spent),
        Err(GitBootstrapErrorV1::Git(CustodyGitError::Timeout))
    ));
    assert_eq!(position(&one), 5, "no read and no rewind happened");
}

/// Retained descriptors are the only input: every staged leaf renamed away, and then unlinked, is still
/// read from its descriptor.
#[test]
fn b1a_renamed_and_unlinked_staged_frames_are_still_read_from_their_descriptors() {
    let fixture = PlanFixtureV1::rich_clone();
    let (manifest, capability, _receipts) = fixture.planned();
    let _ = expect_sealed(
        fixture
            .export(&manifest, capability)
            .expect("the rich export seals"),
    );
    let (dest, mut verified) = phase_v(&fixture.capsule_dir());
    let whole = prevalidate(&mut verified, far_deadline()).expect("the unmoved frames");

    let plain = dest.work().join("plain");
    let mut renamed = 0_usize;
    for (relative, bytes) in snapshot(&plain) {
        if bytes.is_some() {
            let from = plain.join(&relative);
            let to = from.with_file_name(format!("renamed-{renamed}"));
            std::fs::rename(&from, &to).expect("a staged leaf is renamed");
            renamed += 1;
        }
    }
    assert_eq!(renamed, verified.staged.len());
    let moved = prevalidate(&mut verified, far_deadline())
        .expect("renamed frames are read from their descriptors");
    assert_eq!(moved, whole);

    for (relative, bytes) in snapshot(&plain) {
        if bytes.is_some() {
            std::fs::remove_file(plain.join(&relative)).expect("a staged leaf is unlinked");
        }
    }
    let unlinked = prevalidate(&mut verified, far_deadline())
        .expect("unlinked frames are read from their descriptors");
    assert_eq!(unlinked, whole);
}

// ---------------------------------------------------------------------------------------------
// The one deadline paces every step: reads, entries, rewinds, and the success
// ---------------------------------------------------------------------------------------------

/// The one deadline of the pacing rows. A clean prevalidation of these small frames takes milliseconds.
const B1A_DEADLINE_V1: Duration = Duration::from_secs(3);

fn two_frame_case(capsule: &CustomCapsuleV1) -> CaseV1 {
    CaseV1::with_entries(
        capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/heads", EntryV1::Dir),
            (b"refs/heads/main", EntryV1::File(b"oid\n")),
        ],
        Some(&[
            (b"logs", EntryV1::Dir),
            (b"logs/HEAD", EntryV1::File(b"log\n")),
        ]),
    )
}

/// The guards of a clean two-frame run, in order, by label.
const CLEAN_GUARDS_V1: [&str; 10] = [
    "frames-entry",
    "frame-rehash",
    "frame-rewind",
    "frame-decoded",
    "frame-rewound",
    "frame-rehash",
    "frame-rewind",
    "frame-decoded",
    "frame-rewound",
    "frames-final",
];

fn record_guards() -> (
    std::rc::Rc<std::cell::RefCell<Vec<&'static str>>>,
    GitSeamGuardV1,
) {
    let labels = std::rc::Rc::new(std::cell::RefCell::new(Vec::<&'static str>::new()));
    let seen = labels.clone();
    let hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        seen.borrow_mut().push(event.label);
    });
    (labels, hook)
}

/// A clean run reads the clock at exactly the documented guards, in order, so no step is unobserved.
#[test]
fn b1a_the_guards_of_a_clean_run_are_the_documented_ones_in_order() {
    let capsule = frames_capsule();
    let mut case = two_frame_case(&capsule);
    let (labels, _hook) = record_guards();
    let _ = case.accepted("a clean two-frame run");
    assert_eq!(*labels.borrow(), CLEAN_GUARDS_V1);
}

/// Each guard halts the run alone: its step made slow past the deadline is refused with a typed timeout,
/// the run stops AT that guard (no later guard ever ran), nothing is written, and the ledger is as it
/// was. A brief delay at every guard, with headroom, still succeeds.
#[test]
fn b1a_each_guard_halts_the_run_alone_and_headroom_succeeds() {
    let capsule = frames_capsule();
    let mut distinct: Vec<&'static str> = Vec::new();
    for label in CLEAN_GUARDS_V1 {
        if !distinct.contains(&label) {
            distinct.push(label);
        }
    }
    for target in distinct {
        let mut case = two_frame_case(&capsule);
        let deadline = Instant::now() + B1A_DEADLINE_V1;
        let labels = std::rc::Rc::new(std::cell::RefCell::new(Vec::<&'static str>::new()));
        let fired = std::rc::Rc::new(std::cell::Cell::new(false));
        let (seen, slow) = (labels.clone(), fired.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            seen.borrow_mut().push(event.label);
            if event.label == target && !slow.replace(true) {
                pass_the_deadline(deadline);
            }
        });
        let ledger = ledger_used(&case.verified);
        let tree = snapshot(&case.dest.path);
        let error = prevalidate(&mut case.verified, deadline).expect_err(target);
        assert!(
            matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
            "{target}: {error:?}"
        );
        assert!(fired.get(), "{target}: the slow step never ran");
        assert_eq!(
            labels.borrow().last().copied(),
            Some(target),
            "{target}: the run halted AT its guard: {:?}",
            labels.borrow()
        );
        assert_eq!(ledger_used(&case.verified), ledger, "{target}");
        assert_eq!(snapshot(&case.dest.path), tree, "{target}");
        assert_eq!(case.dest.entries(), [".restore-work"], "{target}");
    }

    let mut case = two_frame_case(&capsule);
    let deadline = Instant::now() + B1A_DEADLINE_V1;
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, |_| {
        std::thread::sleep(Duration::from_millis(40));
    });
    prevalidate(&mut case.verified, deadline).expect("ten brief delays leave most of the deadline");
}

/// A deadline already spent refuses before the first read: no label past the entry guard, and every
/// staged descriptor is exactly where it was left.
#[test]
fn b1a_a_spent_deadline_refuses_before_any_frame_is_touched() {
    let capsule = frames_capsule();
    let mut case = two_frame_case(&capsule);
    for one in &case.verified.staged {
        use std::io::Seek as _;
        (&one.file)
            .seek(SeekFrom::Start(3))
            .expect("park the descriptor");
    }
    let spent = Instant::now();
    std::thread::sleep(Duration::from_millis(5));
    let (labels, _hook) = record_guards();
    let error = prevalidate(&mut case.verified, spent).expect_err("a spent deadline");
    assert!(
        matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
        "{error:?}"
    );
    assert_eq!(*labels.borrow(), ["frames-entry"]);
    assert!(case.verified.staged.iter().all(|one| position(one) == 3));
}

/// A frame of several entries whose deadline passes while one entry is being judged stops AT that entry:
/// the per-entry guard keeps the later entries from being decoded.
#[test]
fn b1a_the_deadline_is_observed_before_every_decoded_entry() {
    let capsule = frames_capsule();
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/heads", EntryV1::Dir),
            (b"refs/heads/a", EntryV1::File(b"1\n")),
            (b"refs/heads/b", EntryV1::File(b"2\n")),
            (b"refs/heads/c", EntryV1::File(b"3\n")),
            (b"refs/heads/d", EntryV1::File(b"4\n")),
        ],
    );
    let deadline = Instant::now() + B1A_DEADLINE_V1;
    let entries = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
    let seen = entries.clone();
    let _hook = install_git_hook_for_test(GitHookPointV1::FrameEntry, move |event| {
        seen.borrow_mut()
            .push(event.path.to_string_lossy().into_owned());
        if event.path == Path::new("refs/heads/a") {
            pass_the_deadline(deadline);
        }
    });
    let error = prevalidate(&mut case.verified, deadline)
        .expect_err("the deadline passed while judging an entry");
    assert!(
        matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
        "{error:?}"
    );
    assert_eq!(
        *entries.borrow(),
        ["HEAD", "refs", "refs/heads", "refs/heads/a"],
        "no entry after the one that spent the deadline was decoded"
    );
}

/// Reads are paced too: a large regular file whose entry spends the deadline is not read past the one
/// buffer the decoder had already taken. The descriptor stops within one buffer of where it was.
#[test]
fn b1a_no_frame_byte_is_read_after_the_deadline() {
    let capsule = frames_capsule();
    let big = vec![b'x'; 300 * 1024];
    let mut case = CaseV1::refs_only(
        &capsule,
        &[
            (b"refs", EntryV1::Dir),
            (b"refs/heads", EntryV1::Dir),
            (b"refs/heads/big", EntryV1::File(&big)),
        ],
    );
    let deadline = Instant::now() + B1A_DEADLINE_V1;
    // The rehash reads the whole frame once; the decode must then stop after its first buffer. The
    // hook marks the decode: it runs at an entry, which only the decode reaches.
    let _hook = install_git_hook_for_test(GitHookPointV1::FrameEntry, move |event| {
        if event.path == Path::new("refs/heads/big") {
            pass_the_deadline(deadline);
        }
    });
    let error = prevalidate(&mut case.verified, deadline)
        .expect_err("the deadline passed before the content was read");
    assert!(
        matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
        "{error:?}"
    );
    let one = &case.verified.staged[staged_index(&case.verified, REFS_V1)];
    assert!(one.length > 2 * HASH_BUFFER_BYTES_V1 as u64);
    assert!(
        position(one) <= HASH_BUFFER_BYTES_V1 as u64,
        "the decode read {} bytes of {}: past the deadline",
        position(one),
        one.length
    );
}

// ---------------------------------------------------------------------------------------------
// Bounded private metadata for the later second decode
// ---------------------------------------------------------------------------------------------

/// The entry digest binds class, kind, path, and length, in order: any one difference changes it, and
/// the same entries give the same digest.
#[test]
fn b1a_the_entry_digest_binds_class_kind_path_length_and_order() {
    use ActiveEntryKindV1::{Directory, Regular};
    let digest_of = |class, entries: &[(ActiveEntryKindV1, &str, u64)]| {
        let mut digest = ActiveEntryDigestV1::new(class);
        for (kind, path, length) in entries {
            digest.record(*kind, path.as_bytes(), *length);
        }
        digest.finish()
    };
    let base = [(Directory, "refs", 0), (Regular, "refs/x", 3)];
    let reference = digest_of(REFS_V1, &base);
    assert_eq!(reference, digest_of(REFS_V1, &base), "deterministic");
    let variants: [(&str, [u8; 32]); 6] = [
        ("class", digest_of(LOGS_V1, &base)),
        (
            "kind",
            digest_of(REFS_V1, &[(Directory, "refs", 0), (Directory, "refs/x", 3)]),
        ),
        (
            "path",
            digest_of(REFS_V1, &[(Directory, "refs", 0), (Regular, "refs/y", 3)]),
        ),
        (
            "length",
            digest_of(REFS_V1, &[(Directory, "refs", 0), (Regular, "refs/x", 4)]),
        ),
        (
            "order",
            digest_of(REFS_V1, &[(Regular, "refs/x", 3), (Directory, "refs", 0)]),
        ),
        ("count", digest_of(REFS_V1, &base[..1])),
    ];
    for (what, other) in variants {
        assert_ne!(other, reference, "{what}");
    }
    // A path boundary is part of the record: `ab` + `c` is not `a` + `bc`.
    assert_ne!(
        digest_of(REFS_V1, &[(Regular, "ab", 0), (Regular, "c", 0)]),
        digest_of(REFS_V1, &[(Regular, "a", 0), (Regular, "bc", 0)]),
    );
    // And the path is length-prefixed: one path that embeds the bytes of the next record (its content
    // length and the following kind, as the digest lays them out) is not those two records. Without the
    // prefix the two lists would hash the same bytes.
    let embedded = "a\0\0\0\0\0\0\0\0\u{2}b";
    assert_ne!(
        digest_of(REFS_V1, &[(Regular, "a", 0), (Regular, "b", 0)]),
        digest_of(REFS_V1, &[(Regular, embedded, 0)]),
    );
}

/// The plan's facts for a second decode are those of the frames: different frames give different
/// entry digests, and the same frame staged again gives the same.
#[test]
fn b1a_the_plan_is_reproducible_and_distinguishes_frames() {
    let capsule = frames_capsule();
    let one = |entries: &EntriesV1<'_>| {
        CaseV1::refs_only(&capsule, entries)
            .accepted("a frame")
            .frames[0]
            .clone()
    };
    let a = one(&[dir("refs"), file("refs/x", b"1\n")]);
    let again = one(&[dir("refs"), file("refs/x", b"1\n")]);
    let content = one(&[dir("refs"), file("refs/x", b"2\n")]);
    let name = one(&[dir("refs"), file("refs/y", b"1\n")]);
    assert_eq!(a, again);
    // Content is bound by the staged digest, the names and shapes by the entry digest.
    assert_ne!(a.sha256, content.sha256);
    assert_eq!(a.entries_sha256, content.entries_sha256);
    assert_ne!(a.entries_sha256, name.entries_sha256);
}

// ---------------------------------------------------------------------------------------------
// Pass A's no-repository invariant is function-scoped, and B1a's seam writes nothing
// ---------------------------------------------------------------------------------------------

/// Direct `bootstrap_git_objects_v1` never creates `repository/`, for every capsule shape: it leaves only
/// `.restore-work/` in the destination, and nothing named `repository` anywhere beneath it. B1a's
/// prevalidation run afterwards on the same retained value adds no entry either.
#[test]
fn b1a_the_direct_bootstrap_creates_no_repository_and_prevalidation_adds_none() {
    let fixture = PlanFixtureV1::rich_clone();
    let (manifest, capability, _receipts) = fixture.planned();
    let _ = expect_sealed(
        fixture
            .export(&manifest, capability)
            .expect("the rich export seals"),
    );
    let rich = fixture.capsule_dir();
    let captured_capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let empty_sha256 = empty(CustodyGitObjectFormatV1::Sha256);
    // Only the rich capsule carries active frames; the other two have Empty refs.
    for (row, capsule, format, frames) in [
        ("rich", rich, GitObjectFormatV1::Sha1, true),
        (
            "captured",
            captured_capsule.capsule.clone(),
            GitObjectFormatV1::Sha1,
            false,
        ),
        (
            "empty",
            empty_sha256.capsule.clone(),
            GitObjectFormatV1::Sha256,
            false,
        ),
    ] {
        let (dest, verified) = phase_v(&capsule);
        let mut bootstrap = must_bootstrap(verified, format);
        assert_eq!(dest.entries(), [".restore-work"], "{row}");
        let after_bootstrap = snapshot(&dest.path);
        assert!(
            after_bootstrap
                .keys()
                .all(|name| !name.contains("repository")),
            "{row}: {:?}",
            after_bootstrap.keys().collect::<Vec<_>>()
        );
        let ledger = ledger_used(&bootstrap.verified);
        let outcome = prevalidate(&mut bootstrap.verified, far_deadline());
        match (frames, outcome) {
            (true, Ok(plan)) => assert_eq!(plan.frames.len(), 2, "{row}"),
            (false, Err(GitBootstrapErrorV1::EmptyRefsAndHead)) => {}
            (_, other) => panic!("{row}: {other:?}"),
        }
        assert_eq!(ledger_used(&bootstrap.verified), ledger, "{row}");
        assert_eq!(snapshot(&dest.path), after_bootstrap, "{row}");
        assert_eq!(dest.entries(), [".restore-work"], "{row}");
    }
}

const B1A_MARKER_V1: &str = "// Pass B1a: retained active-frame prevalidation";

/// STRUCTURAL ONLY. Pass A's whole-module forbidden-name scan is narrowed to the bootstrap
/// implementation (its production source up to the B1a marker), because later passes create the
/// repository in this file; the marker is unique and the narrowing leaves a nonempty region before and
/// after it. B1a's own region (through B1b's, up to B2a's marker, where creating and charging begin) is
/// then held to a read-only vocabulary: no path open, no walker, no repository or create-new write, no
/// ledger charge, no Git runner, no object-store route, no unsafe.
#[test]
fn b1a_the_prevalidation_region_is_read_only_and_the_scan_split_is_unique() {
    let source = include_str!("custody_restore_git.rs");
    assert_eq!(source.matches(B1A_MARKER_V1).count(), 1, "one marker");
    let (before, region) = source.split_once(B1A_MARKER_V1).expect("the marker");
    // B2a's region, which creates and charges, is outside this read-only scan; its own scan covers it.
    let (region, _later) = region
        .split_once(B2A_MARKER_V1)
        .expect("the B2a marker follows B1a's region");
    assert!(before.contains("pub(crate) fn bootstrap_git_objects_v1("));
    assert!(region.contains("pub(crate) fn prevalidate_active_frames_v1("));
    assert!(
        !before.contains("prevalidate_active_frames_v1("),
        "Pass A's region does not call the prevalidation"
    );
    let code: String = region
        .lines()
        .filter(|line| !line.trim_start().starts_with("//"))
        .collect::<Vec<_>>()
        .join("\n");
    // The one ledger is only READ, once, for the failure's figure: it is never charged or released.
    assert_eq!(
        code.matches(".ledger").count(),
        1,
        "one access to the ledger"
    );
    assert!(code.contains(".ledger.borrow().used()"));
    for forbidden in [
        "std::fs",
        "File::open(",
        "OpenOptions",
        "read_dir(",
        "create_new",
        "create_staging_directory",
        "write_all",
        "GitRunnerV1",
        "GitRunRequestV1",
        "GitObjectStoreRouteV1",
        "object_store",
        "borrow_mut",
        "ReservedPairV1",
        "OwnedChargeV1",
        "ScratchLedgerV1",
        ".reserve(",
        ".release(",
        "roll_back",
        "unsafe",
        "\"repository\"",
        "remeasure_git_directory",
        "measure_git_directory",
        "walk",
        "Command",
    ] {
        assert!(
            !code.contains(forbidden),
            "the prevalidation region mentions `{forbidden}`"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Pass B1b: pure refs agreement and inert config
//
// The grammar, agreement, and limit rows drive `RefsBuilderV1` over byte slices and readers: the same
// code that later runs over retained final descriptors, fed here by the test. Objects are named by one
// fill character (`a`..`e`) so a row reads as the refs it describes. The production rows below them run
// the real entry point over REAL retained phase-V values and frames. Nothing here writes a byte, runs
// Git on the code under test, or charges the ledger.
//
// Pass A's and B1a's controls above are unchanged. The mutation matrix in
// `.git/a2a-evidence/2b3b-pass-b1b/` maps each guard to the rows that turn red without it.
// ---------------------------------------------------------------------------------------------

use crate::custody_seal::{CustodyOriginalRefV1, CustodyRefTargetV1};

type KindV1 = CustodyGitObjectKindV1;

/// The pure rows' object pool: `a` and `b` are commits, `c` an annotated tag, `d` a tree, `e` a blob,
/// and `f` an object of unknown kind.
const POOL_V1: [(char, KindV1); 6] = [
    ('a', KindV1::Commit),
    ('b', KindV1::Commit),
    ('c', KindV1::Tag),
    ('d', KindV1::Tree),
    ('e', KindV1::Blob),
    ('f', KindV1::Unknown),
];
const BOTH_FORMATS_V1: [GitObjectFormatV1; 2] =
    [GitObjectFormatV1::Sha1, GitObjectFormatV1::Sha256];

fn oid_len(format: GitObjectFormatV1) -> usize {
    match format {
        GitObjectFormatV1::Sha1 => 40,
        GitObjectFormatV1::Sha256 => 64,
    }
}

fn oid_of(fill: char, format: GitObjectFormatV1) -> String {
    fill.to_string().repeat(oid_len(format))
}

fn manifest_format_of(format: GitObjectFormatV1) -> CustodyGitObjectFormatV1 {
    match format {
        GitObjectFormatV1::Sha1 => CustodyGitObjectFormatV1::Sha1,
        GitObjectFormatV1::Sha256 => CustodyGitObjectFormatV1::Sha256,
    }
}

fn pool_object(fill: char, format: GitObjectFormatV1) -> CustodyOriginalObjectV1 {
    let kind = POOL_V1
        .iter()
        .find(|(found, _)| *found == fill)
        .expect("a pooled object")
        .1;
    CustodyOriginalObjectV1::new(manifest_format_of(format), oid_of(fill, format), kind)
        .expect("a pooled object")
}

/// What a manifest ref says its target is.
#[derive(Clone, Copy)]
enum WantV1 {
    Direct(char),
    Symbolic(&'static str),
    Unborn,
}

fn want_ref(format: GitObjectFormatV1, name: &str, want: WantV1) -> CustodyOriginalRefV1 {
    let target = match want {
        WantV1::Direct(fill) => CustodyRefTargetV1::Direct(pool_object(fill, format)),
        WantV1::Symbolic(target) => {
            CustodyRefTargetV1::Symbolic(LosslessPathV1::from_bytes(target.as_bytes().to_vec()))
        }
        WantV1::Unborn => CustodyRefTargetV1::Unborn,
    };
    CustodyOriginalRefV1::new(LosslessPathV1::from_bytes(name.as_bytes().to_vec()), target)
        .expect("a manifest ref")
}

/// A manifest over the pool (or over no objects) and `refs`.
fn pool_manifest(
    format: GitObjectFormatV1,
    pooled: bool,
    refs: &[(&str, WantV1)],
) -> CustodyManifestV1 {
    let objects = if pooled {
        POOL_V1
            .iter()
            .map(|(fill, _)| pool_object(*fill, format))
            .collect()
    } else {
        vec![]
    };
    let state = if pooled {
        CustodyStateClassV1::Captured
    } else {
        CustodyStateClassV1::Empty
    };
    CustodyManifestV1::new(
        "unit-b1b",
        "run-b1b",
        "materialization-b1b",
        GENERATION_V1,
        coverage_rows(state),
        refs.iter()
            .map(|(name, want)| want_ref(format, name, *want))
            .collect(),
        objects,
        vec![],
        vec![],
    )
    .expect("a pooled manifest")
}

type FileV1 = (&'static str, Vec<u8>);
type ManifestRefsV1 = Vec<(&'static str, WantV1)>;

fn direct_file(fill: char, format: GitObjectFormatV1) -> Vec<u8> {
    format!("{}\n", oid_of(fill, format)).into_bytes()
}

fn symbolic_file(target: &str) -> Vec<u8> {
    format!("ref: {target}\n").into_bytes()
}

fn file_of(path: &'static str, content: Vec<u8>) -> FileV1 {
    (path, content)
}

/// An attached `HEAD` on `refs/heads/main`, which is commit `a`.
fn base_files(format: GitObjectFormatV1) -> Vec<FileV1> {
    vec![
        file_of("HEAD", symbolic_file("refs/heads/main")),
        file_of("refs/heads/main", direct_file('a', format)),
    ]
}

/// `files` into a builder, then the agreement with a manifest of `refs`.
fn pure_run(
    format: GitObjectFormatV1,
    pooled: bool,
    files: &[FileV1],
    refs: &[(&str, WantV1)],
    limits: RefsLimitsV1,
) -> Result<RefsAgreementV1, GitBootstrapErrorV1> {
    let mut builder = RefsBuilderV1::new(format, limits, far_deadline());
    for (path, content) in files {
        let mut reader: &[u8] = content;
        builder.admit_file(path.as_bytes(), &mut reader)?;
    }
    builder.finish(&pool_manifest(format, pooled, refs))
}

fn pure(
    format: GitObjectFormatV1,
    files: &[FileV1],
    refs: &[(&str, WantV1)],
) -> Result<RefsAgreementV1, GitBootstrapErrorV1> {
    pure_run(format, true, files, refs, RefsLimitsV1::v1())
}

fn refs_fault(error: GitBootstrapErrorV1) -> RefsFaultV1 {
    match error {
        GitBootstrapErrorV1::Refs(fault) => fault,
        other => panic!("a refs fault, not {other:?}"),
    }
}

fn fault_of(result: Result<RefsAgreementV1, GitBootstrapErrorV1>, row: &str) -> RefsFaultV1 {
    refs_fault(result.expect_err(row))
}

fn row_fault(path: &str, why: RowFaultV1) -> RefsFaultV1 {
    RefsFaultV1::Row {
        path: path.to_owned(),
        why,
    }
}

fn name_fault(path: &str, why: RefNameFaultV1) -> RefsFaultV1 {
    RefsFaultV1::RefName {
        path: path.to_owned(),
        why,
    }
}

// ---------------------------------------------------------------------------------------------
// Ref names
// ---------------------------------------------------------------------------------------------

/// The ref-name rule: every name is under `refs/`, has no empty component, follows the portable ASCII
/// spelling rule, and Git's check-ref-format rules (no leading dot, no `.lock` suffix, no `..`, none of
/// `~ ^ : ? * [`, no `@{`). Each refusal is its own typed reason, and a valid neighbour passes.
#[test]
fn b1b_ref_names_follow_the_git_rules_and_the_portable_rule() {
    for valid in [
        "refs/heads/main",
        "refs/tags/v1.0",
        "refs/remotes/origin/HEAD",
        "refs/stash",
        "refs/heads/feature/deep/er",
        "refs/heads/a-b_c",
        "refs/heads/a.b",
        "refs/heads/@x",
        "refs/heads/lock",
        "refs/notes/commits",
        "refs/heads/x.locked",
    ] {
        assert_eq!(check_ref_name_v1(valid.as_bytes()), Ok(()), "{valid}");
    }
    let table: &[(&[u8], RefNameFaultV1)] = &[
        (b"refs", RefNameFaultV1::NotUnderRefs),
        (b"heads/main", RefNameFaultV1::NotUnderRefs),
        (b"HEAD", RefNameFaultV1::NotUnderRefs),
        (b"", RefNameFaultV1::NotUnderRefs),
        (b"refs/", RefNameFaultV1::EmptyComponent),
        (b"refs//x", RefNameFaultV1::EmptyComponent),
        (b"refs/heads/", RefNameFaultV1::EmptyComponent),
        (b"refs/heads/.hidden", RefNameFaultV1::LeadingDot),
        (b"refs/.x/y", RefNameFaultV1::LeadingDot),
        (b"refs/heads/x.lock", RefNameFaultV1::LockSuffix),
        (b"refs/x.lock/y", RefNameFaultV1::LockSuffix),
        (b"refs/heads/a..b", RefNameFaultV1::DoubleDot),
        (b"refs/heads/a~1", RefNameFaultV1::ForbiddenByte),
        (b"refs/heads/a^", RefNameFaultV1::ForbiddenByte),
        (b"refs/heads/a:b", RefNameFaultV1::ForbiddenByte),
        (b"refs/heads/a?", RefNameFaultV1::ForbiddenByte),
        (b"refs/heads/a*", RefNameFaultV1::ForbiddenByte),
        (b"refs/heads/a[", RefNameFaultV1::ForbiddenByte),
        (b"refs/heads/a@{b", RefNameFaultV1::AtBrace),
        (
            b"refs/heads/a.",
            RefNameFaultV1::Portable(PortableFaultV1::TrailingDot),
        ),
        (
            b"refs/heads/a b",
            RefNameFaultV1::Portable(PortableFaultV1::Unprintable),
        ),
        (
            b"refs/heads/a\tb",
            RefNameFaultV1::Portable(PortableFaultV1::Unprintable),
        ),
        (
            b"refs/heads/a\x7f",
            RefNameFaultV1::Portable(PortableFaultV1::Unprintable),
        ),
        (
            b"refs/heads/a\\b",
            RefNameFaultV1::Portable(PortableFaultV1::Backslash),
        ),
        (
            "refs/heads/h\u{e9}".as_bytes(),
            RefNameFaultV1::Portable(PortableFaultV1::NonAscii),
        ),
        (
            b"refs/heads/\xff",
            RefNameFaultV1::Portable(PortableFaultV1::NonAscii),
        ),
    ];
    for (name, why) in table {
        assert_eq!(
            check_ref_name_v1(name),
            Err(why.clone()),
            "{}",
            String::from_utf8_lossy(name)
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Loose refs, HEAD, and ORIG_HEAD
// ---------------------------------------------------------------------------------------------

/// HEAD, ORIG_HEAD, and a loose ref parse in both formats: a direct ref is exactly the format's
/// lowercase hex and one LF, a symbolic ref exactly `ref: ` and a full ref name and one LF.
#[test]
fn b1b_exact_loose_refs_parse_in_both_formats() {
    for format in BOTH_FORMATS_V1 {
        let agreement = pure(
            format,
            &[
                file_of("HEAD", symbolic_file("refs/heads/main")),
                file_of("ORIG_HEAD", direct_file('b', format)),
                file_of("refs/heads/main", direct_file('a', format)),
                file_of("refs/heads/alias", symbolic_file("refs/heads/main")),
                file_of("refs/tags/v1", direct_file('c', format)),
                file_of("refs/heads/deep/er", direct_file('b', format)),
            ],
            &[],
        )
        .unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(
            agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: Some(oid_of('a', format)),
            }
        );
        assert_eq!(agreement.loose_refs, 4, "{format:?}");
        assert_eq!(agreement.symbolic_refs, 1, "{format:?}");
        assert_eq!(agreement.effective_refs, 4, "{format:?}");
        assert_eq!(agreement.orig_head, Some(oid_of('b', format)));
        assert_eq!((agreement.packed_refs, agreement.peeled_rows), (0, 0));
        // A detached HEAD is the same grammar.
        let detached = pure(format, &[file_of("HEAD", direct_file('a', format))], &[])
            .unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(
            detached.head,
            HeadStateV1::Detached {
                oid: oid_of('a', format)
            }
        );
    }
}

/// Every malformed loose ref refuses with its own typed reason, for HEAD and for a loose ref alike:
/// nothing is trimmed, lowercased, or defaulted.
#[test]
fn b1b_malformed_loose_refs_refuse_with_typed_reasons() {
    for format in BOTH_FORMATS_V1 {
        let good = oid_of('a', format);
        let other_width = oid_of(
            'a',
            if oid_len(format) == 40 {
                GitObjectFormatV1::Sha256
            } else {
                GitObjectFormatV1::Sha1
            },
        );
        let upper = good.to_uppercase();
        let rows: Vec<(&str, Vec<u8>, RowFaultV1)> = vec![
            ("empty", b"".to_vec(), RowFaultV1::EmptyFile),
            (
                "no newline",
                good.clone().into_bytes(),
                RowFaultV1::PartialLine,
            ),
            (
                "no newline, symbolic",
                b"ref: refs/heads/main".to_vec(),
                RowFaultV1::PartialLine,
            ),
            ("lone newline", b"\n".to_vec(), RowFaultV1::ObjectId),
            (
                "crlf",
                format!("{good}\r\n").into_bytes(),
                RowFaultV1::ObjectId,
            ),
            (
                "trailing space",
                format!("{good} \n").into_bytes(),
                RowFaultV1::ObjectId,
            ),
            (
                "leading space",
                format!(" {good}\n").into_bytes(),
                RowFaultV1::ObjectId,
            ),
            (
                "uppercase",
                format!("{upper}\n").into_bytes(),
                RowFaultV1::ObjectId,
            ),
            (
                "the other format's width",
                format!("{other_width}\n").into_bytes(),
                RowFaultV1::ObjectId,
            ),
            (
                "one hex digit short",
                format!("{}\n", &good[1..]).into_bytes(),
                RowFaultV1::ObjectId,
            ),
            (
                "a non-hex digit",
                format!("g{}\n", &good[1..]).into_bytes(),
                RowFaultV1::ObjectId,
            ),
            (
                "a NUL",
                format!("{}\0\n", &good[1..]).into_bytes(),
                RowFaultV1::ObjectId,
            ),
            (
                "a second line",
                format!("{good}\n{good}\n").into_bytes(),
                RowFaultV1::ExtraLine,
            ),
            (
                "a trailing blank line",
                format!("{good}\n\n").into_bytes(),
                RowFaultV1::ExtraLine,
            ),
            (
                "a second, partial line",
                format!("{good}\nx").into_bytes(),
                RowFaultV1::ExtraLine,
            ),
            (
                "ref: without its space",
                b"ref:refs/heads/main\n".to_vec(),
                RowFaultV1::ObjectId,
            ),
            (
                "a symbolic ref with two spaces",
                b"ref:  refs/heads/main\n".to_vec(),
                RowFaultV1::SymbolicTarget(RefNameFaultV1::NotUnderRefs),
            ),
            (
                "a symbolic target with a trailing space",
                b"ref: refs/heads/main \n".to_vec(),
                RowFaultV1::SymbolicTarget(RefNameFaultV1::Portable(PortableFaultV1::Unprintable)),
            ),
            (
                "a symbolic target with a CR",
                b"ref: refs/heads/main\r\n".to_vec(),
                RowFaultV1::SymbolicTarget(RefNameFaultV1::Portable(PortableFaultV1::Unprintable)),
            ),
            (
                "a symbolic target outside refs/",
                b"ref: HEAD\n".to_vec(),
                RowFaultV1::SymbolicTarget(RefNameFaultV1::NotUnderRefs),
            ),
            (
                "an empty symbolic target",
                b"ref: \n".to_vec(),
                RowFaultV1::SymbolicTarget(RefNameFaultV1::NotUnderRefs),
            ),
            (
                "a symbolic target with ..",
                b"ref: refs/heads/a..b\n".to_vec(),
                RowFaultV1::SymbolicTarget(RefNameFaultV1::DoubleDot),
            ),
            (
                "a symbolic target ending .lock",
                b"ref: refs/heads/x.lock\n".to_vec(),
                RowFaultV1::SymbolicTarget(RefNameFaultV1::LockSuffix),
            ),
        ];
        for path in ["HEAD", "refs/heads/x"] {
            for (row, content, why) in &rows {
                let result = pure(format, &[file_of(path, content.clone())], &[]);
                assert_eq!(
                    fault_of(result, row),
                    row_fault(path, why.clone()),
                    "{format:?} {path}: {row}"
                );
            }
        }
    }
}

/// ORIG_HEAD is only ever a direct object id: a symbolic ORIG_HEAD refuses, and so does every malformed
/// spelling.
#[test]
fn b1b_orig_head_is_a_direct_object_id_only() {
    for format in BOTH_FORMATS_V1 {
        let mut files = base_files(format);
        files.push(file_of("ORIG_HEAD", symbolic_file("refs/heads/main")));
        assert_eq!(
            fault_of(pure(format, &files, &[]), "symbolic ORIG_HEAD"),
            row_fault("ORIG_HEAD", RowFaultV1::ObjectId)
        );
        for (row, content, why) in [
            ("empty", b"".to_vec(), RowFaultV1::EmptyFile),
            (
                "no newline",
                oid_of('a', format).into_bytes(),
                RowFaultV1::PartialLine,
            ),
            (
                "two lines",
                format!("{0}\n{0}\n", oid_of('a', format)).into_bytes(),
                RowFaultV1::ExtraLine,
            ),
        ] {
            let mut files = base_files(format);
            files.push(file_of("ORIG_HEAD", content));
            assert_eq!(
                fault_of(pure(format, &files, &[]), row),
                row_fault("ORIG_HEAD", why),
                "{row}"
            );
        }
    }
}

/// Which paths are refs files: the allowlist routes only HEAD, ORIG_HEAD, FETCH_HEAD, packed-refs,
/// refs/**, and logs/HEAD or logs/refs/**. Any other file is refused, whatever it holds, and a ref
/// file under a forbidden name is refused by its name. A path may be admitted once.
#[test]
fn b1b_only_refs_files_are_admitted_and_each_once() {
    let format = GitObjectFormatV1::Sha1;
    for path in [
        "config",
        "index",
        "shallow",
        "MERGE_HEAD",
        "hooks/pre-commit",
        "objects/pack/x",
        "info/refs",
        "refs",
        "logs",
        "logs/foo",
        "logs/refs",
        "refs.lock",
        "head",
        "HEAD/x",
        "packed-refs/x",
        "",
    ] {
        let mut builder = RefsBuilderV1::new(format, RefsLimitsV1::v1(), far_deadline());
        let mut reader: &[u8] = b"anything\n";
        let error = builder
            .admit_file(path.as_bytes(), &mut reader)
            .expect_err(path);
        assert_eq!(
            refs_fault(error),
            RefsFaultV1::UnexpectedFile { path: path.into() },
            "{path}"
        );
    }
    for (path, why) in [
        ("refs/heads/x.lock", RefNameFaultV1::LockSuffix),
        ("refs/heads/.x", RefNameFaultV1::LeadingDot),
        ("refs/heads/a..b", RefNameFaultV1::DoubleDot),
        (
            "refs/heads/a b",
            RefNameFaultV1::Portable(PortableFaultV1::Unprintable),
        ),
    ] {
        let mut files = base_files(format);
        files.push(file_of(path, direct_file('a', format)));
        assert_eq!(
            fault_of(pure(format, &files, &[]), path),
            name_fault(path, why),
            "{path}"
        );
    }
    for path in [
        "HEAD",
        "ORIG_HEAD",
        "FETCH_HEAD",
        "packed-refs",
        "refs/heads/main",
        "logs/HEAD",
        "logs/refs/heads/main",
    ] {
        let mut builder = RefsBuilderV1::new(format, RefsLimitsV1::v1(), far_deadline());
        let content: &[u8] = match path {
            "HEAD" => b"ref: refs/heads/main\n",
            "packed-refs" | "FETCH_HEAD" | "logs/HEAD" | "logs/refs/heads/main" => b"",
            _ => b"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n",
        };
        let mut reader: &[u8] = content;
        builder
            .admit_file(path.as_bytes(), &mut reader)
            .expect("the first admission");
        let mut again: &[u8] = content;
        let error = builder
            .admit_file(path.as_bytes(), &mut again)
            .expect_err(path);
        assert_eq!(
            refs_fault(error),
            RefsFaultV1::Duplicate { path: path.into() },
            "{path}"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// packed-refs
// ---------------------------------------------------------------------------------------------

const PACKED_HEADER_V1: &str = "# pack-refs with: peeled fully-peeled sorted \n";

fn packed(format: GitObjectFormatV1, header: &str, rows: &[(&str, char, Option<char>)]) -> Vec<u8> {
    let mut text = header.to_owned();
    for (name, fill, peeled) in rows {
        text.push_str(&format!("{} {name}\n", oid_of(*fill, format)));
        if let Some(peeled) = peeled {
            text.push_str(&format!("^{}\n", oid_of(*peeled, format)));
        }
    }
    text.into_bytes()
}

/// A real-shaped packed-refs file parses in both formats: the header line, sorted rows, a peeled row
/// under its annotated tag, a packed-only ref, and a ref that a loose one also names (the loose one wins).
#[test]
fn b1b_packed_refs_parse_with_peeled_rows_and_loose_precedence() {
    for format in BOTH_FORMATS_V1 {
        let mut files = vec![file_of("HEAD", symbolic_file("refs/heads/main"))];
        files.push(file_of(
            "packed-refs",
            packed(
                format,
                PACKED_HEADER_V1,
                &[
                    ("refs/heads/main", 'a', None),
                    ("refs/heads/other", 'b', None),
                    ("refs/tags/v1", 'c', Some('a')),
                    ("refs/tags/v2", 'a', None),
                ],
            ),
        ));
        // A loose ref hides the packed one of the same name.
        files.push(file_of("refs/heads/other", direct_file('a', format)));
        let agreement = pure(
            format,
            &files,
            &[
                ("HEAD", WantV1::Symbolic("refs/heads/main")),
                ("refs/heads/main", WantV1::Direct('a')),
                ("refs/heads/other", WantV1::Direct('a')),
                ("refs/tags/v1", WantV1::Direct('c')),
            ],
        )
        .unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(agreement.packed_refs, 4, "{format:?}");
        assert_eq!(agreement.peeled_rows, 1, "{format:?}");
        assert_eq!(agreement.loose_refs, 1, "{format:?}");
        assert_eq!(agreement.effective_refs, 4, "{format:?}");
        assert_eq!(agreement.manifest_refs, 4, "{format:?}");
        assert_eq!(
            agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: Some(oid_of('a', format)),
            }
        );
    }
}

/// Packed-refs headers: the exact Git header, any subset of its three traits, or none at all, and an
/// empty file or header-only file is a valid packed-refs with no rows.
#[test]
fn b1b_packed_refs_headers_and_empty_files() {
    let format = GitObjectFormatV1::Sha1;
    let rows = [("refs/heads/main", 'a', None)];
    for header in [
        PACKED_HEADER_V1,
        "# pack-refs with: peeled fully-peeled sorted\n",
        "# pack-refs with: peeled\n",
        "# pack-refs with: sorted\n",
        "# pack-refs with:\n",
        "# pack-refs with: \n",
        "",
    ] {
        let mut files = vec![file_of("HEAD", symbolic_file("refs/heads/main"))];
        files.push(file_of("packed-refs", packed(format, header, &rows)));
        pure(format, &files, &[])
            .unwrap_or_else(|error| panic!("header {header:?} must parse: {error:?}"));
    }
    for content in [&b""[..], b"# pack-refs with: peeled fully-peeled sorted \n"] {
        let mut files = vec![file_of("HEAD", symbolic_file("refs/heads/main"))];
        files.push(file_of("packed-refs", content.to_vec()));
        let agreement = pure(format, &files, &[]).expect("a packed-refs with no rows");
        assert_eq!(agreement.packed_refs, 0);
        assert_eq!(agreement.effective_refs, 0);
    }
}

/// Every malformed packed-refs refuses with its own typed reason.
#[test]
fn b1b_malformed_packed_refs_refuse_with_typed_reasons() {
    for format in BOTH_FORMATS_V1 {
        let a = oid_of('a', format);
        let c = oid_of('c', format);
        let b = oid_of('b', format);
        let header = PACKED_HEADER_V1;
        let rows: Vec<(&str, String, RefsFaultV1)> = vec![
            (
                "an unknown trait",
                "# pack-refs with: peeled bogus \n".into(),
                row_fault("packed-refs", RowFaultV1::PackedHeader),
            ),
            (
                "a repeated trait",
                "# pack-refs with: sorted sorted \n".into(),
                row_fault("packed-refs", RowFaultV1::PackedHeader),
            ),
            (
                "a header without the colon",
                "# pack-refs with peeled\n".into(),
                row_fault("packed-refs", RowFaultV1::PackedHeader),
            ),
            (
                "a header glued to its traits",
                "# pack-refs with:peeled\n".into(),
                row_fault("packed-refs", RowFaultV1::PackedHeader),
            ),
            (
                "a comment that is not the header",
                format!("# comment\n{a} refs/heads/main\n"),
                row_fault("packed-refs", RowFaultV1::PackedHeader),
            ),
            (
                "a second header",
                format!("{header}{a} refs/heads/main\n{header}"),
                row_fault("packed-refs", RowFaultV1::PackedHeader),
            ),
            (
                "a header after a row",
                format!("{a} refs/heads/main\n{header}"),
                row_fault("packed-refs", RowFaultV1::PackedHeader),
            ),
            (
                "a row without a name",
                format!("{header}{a}\n"),
                row_fault("packed-refs", RowFaultV1::PackedRow),
            ),
            (
                "a row with two spaces",
                format!("{header}{a}  refs/heads/main\n"),
                name_fault(" refs/heads/main", RefNameFaultV1::NotUnderRefs),
            ),
            (
                "a row with a bad object id",
                format!("{header}{} refs/heads/main\n", a.to_uppercase()),
                row_fault("packed-refs", RowFaultV1::ObjectId),
            ),
            (
                "a row with a short object id",
                format!("{header}{} refs/heads/main\n", &a[1..]),
                row_fault("packed-refs", RowFaultV1::ObjectId),
            ),
            (
                "a row with a bad name",
                format!("{header}{a} refs/heads/x.lock\n"),
                name_fault("refs/heads/x.lock", RefNameFaultV1::LockSuffix),
            ),
            (
                "a row outside refs/",
                format!("{header}{a} HEAD\n"),
                name_fault("HEAD", RefNameFaultV1::NotUnderRefs),
            ),
            (
                "a row with a CR",
                format!("{header}{a} refs/heads/main\r\n"),
                name_fault(
                    "refs/heads/main\r",
                    RefNameFaultV1::Portable(PortableFaultV1::Unprintable),
                ),
            ),
            (
                "a missing final newline",
                format!("{header}{a} refs/heads/main"),
                row_fault("packed-refs", RowFaultV1::PartialLine),
            ),
            (
                "a blank line",
                format!("{header}\n{a} refs/heads/main\n"),
                row_fault("packed-refs", RowFaultV1::PackedRow),
            ),
            (
                "a peeled row first",
                format!("{header}^{a}\n{a} refs/heads/main\n"),
                row_fault("packed-refs", RowFaultV1::PeeledOrphan),
            ),
            (
                "two peeled rows",
                format!("{header}{c} refs/tags/v1\n^{a}\n^{b}\n"),
                row_fault("packed-refs", RowFaultV1::PeeledOrphan),
            ),
            (
                "a peeled row with a bad object id",
                format!("{header}{c} refs/tags/v1\n^{}\n", a.to_uppercase()),
                row_fault("packed-refs", RowFaultV1::ObjectId),
            ),
            (
                "an empty peeled row",
                format!("{header}{c} refs/tags/v1\n^\n"),
                row_fault("packed-refs", RowFaultV1::ObjectId),
            ),
            (
                "rows out of order under the sorted trait",
                format!("{header}{a} refs/heads/b\n{a} refs/heads/a\n"),
                row_fault("packed-refs", RowFaultV1::PackedOrder),
            ),
            (
                "a repeated name under the sorted trait",
                format!("{header}{a} refs/heads/a\n{a} refs/heads/a\n"),
                row_fault("packed-refs", RowFaultV1::PackedOrder),
            ),
            (
                "a repeated name without the sorted trait",
                format!("# pack-refs with: peeled \n{a} refs/heads/a\n{b} refs/heads/a\n"),
                row_fault("packed-refs", RowFaultV1::PackedDuplicate),
            ),
        ];
        for (row, content, expected) in rows {
            let files = vec![
                file_of("HEAD", symbolic_file("refs/heads/main")),
                file_of("packed-refs", content.into_bytes()),
            ];
            assert_eq!(
                fault_of(pure(format, &files, &[]), row),
                expected,
                "{format:?}: {row}"
            );
        }
        // Out of order without the sorted trait is fine: only the header promises an order.
        let files = vec![
            file_of("HEAD", symbolic_file("refs/heads/main")),
            file_of(
                "packed-refs",
                format!("# pack-refs with: peeled \n{a} refs/heads/b\n{a} refs/heads/a\n")
                    .into_bytes(),
            ),
        ];
        pure(format, &files, &[]).expect("unsorted rows without the sorted trait");
    }
}

// ---------------------------------------------------------------------------------------------
// FETCH_HEAD and reflogs
// ---------------------------------------------------------------------------------------------

fn fetch_head(format: GitObjectFormatV1, rows: &[(char, &str, &str)]) -> Vec<u8> {
    rows.iter()
        .map(|(fill, flag, note)| format!("{}\t{flag}\t{note}\n", oid_of(*fill, format)))
        .collect::<String>()
        .into_bytes()
}

/// FETCH_HEAD rows are `<oid> TAB (empty | not-for-merge) TAB <note> LF`; the first row's object is the
/// ref's value, and every row's object must be in the inventory. Empty is a valid FETCH_HEAD.
#[test]
fn b1b_fetch_head_rows_parse_and_the_first_row_is_the_value() {
    for format in BOTH_FORMATS_V1 {
        let mut files = base_files(format);
        files.push(file_of(
            "FETCH_HEAD",
            fetch_head(
                format,
                &[
                    ('b', "", "branch 'main' of https://example.invalid/r"),
                    (
                        'a',
                        "not-for-merge",
                        "branch 'side' of https://example.invalid/r",
                    ),
                    (
                        'c',
                        "not-for-merge",
                        "tag 'v1' of https://example.invalid/r",
                    ),
                    ('d', "", ""),
                ],
            ),
        ));
        let agreement = pure(format, &files, &[("FETCH_HEAD", WantV1::Direct('b'))])
            .unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(agreement.fetch_head_rows, 4);
        assert_eq!(agreement.manifest_refs, 1);
        // The second row's object is not the ref's value.
        assert_eq!(
            fault_of(
                pure(format, &files, &[("FETCH_HEAD", WantV1::Direct('a'))]),
                "the second row"
            ),
            RefsFaultV1::OriginalMismatch {
                name: "FETCH_HEAD".into(),
                expected: format!("direct {}", oid_of('a', format)),
                found: format!("direct {}", oid_of('b', format)),
            }
        );
        let mut empty_files = base_files(format);
        empty_files.push(file_of("FETCH_HEAD", Vec::new()));
        let agreement = pure(format, &empty_files, &[]).expect("an empty FETCH_HEAD");
        assert_eq!(agreement.fetch_head_rows, 0);
        // An empty FETCH_HEAD has no value for the manifest's FETCH_HEAD.
        assert_eq!(
            fault_of(
                pure(format, &empty_files, &[("FETCH_HEAD", WantV1::Direct('a'))]),
                "no first row"
            ),
            RefsFaultV1::MissingOriginal {
                name: "FETCH_HEAD".into()
            }
        );
    }
}

#[test]
fn b1b_malformed_fetch_head_refuses_with_typed_reasons() {
    for format in BOTH_FORMATS_V1 {
        let a = oid_of('a', format);
        let rows: Vec<(&str, String, RowFaultV1)> = vec![
            (
                "a bad flag",
                format!("{a}\tmerge\tnote\n"),
                RowFaultV1::FetchHeadRow,
            ),
            (
                "no tabs",
                format!("{a} not-for-merge note\n"),
                RowFaultV1::FetchHeadRow,
            ),
            ("one tab", format!("{a}\t\n"), RowFaultV1::FetchHeadRow),
            ("a bare oid", format!("{a}\n"), RowFaultV1::FetchHeadRow),
            (
                "an upper-case oid",
                format!("{}\t\tnote\n", a.to_uppercase()),
                RowFaultV1::ObjectId,
            ),
            (
                "a short oid",
                format!("{}\t\tnote\n", &a[1..]),
                RowFaultV1::ObjectId,
            ),
            (
                "no final newline",
                format!("{a}\t\tnote"),
                RowFaultV1::PartialLine,
            ),
            (
                "a blank row",
                format!("{a}\t\tnote\n\n"),
                RowFaultV1::FetchHeadRow,
            ),
            (
                "a NUL in the note",
                format!("{a}\t\tno\0te\n"),
                RowFaultV1::FetchHeadRow,
            ),
        ];
        for (row, content, why) in rows {
            let mut files = base_files(format);
            files.push(file_of("FETCH_HEAD", content.into_bytes()));
            assert_eq!(
                fault_of(pure(format, &files, &[]), row),
                row_fault("FETCH_HEAD", why),
                "{format:?}: {row}"
            );
        }
    }
}

fn log_row(format: GitObjectFormatV1, old: char, new: char, tail: &str) -> String {
    format!("{} {} {tail}\n", oid_of(old, format), oid_of(new, format))
}

const IDENT_V1: &str = "A U Thor <author@example.invalid> 1700000000 +0000";

/// Reflogs are `logs/HEAD` and `logs/refs/<ref name>`: each row is two object ids, an identity ending in
/// `>`, a timestamp, a zone, and an optional TAB message; the object ids need not be in the inventory (a
/// reflog may name an object that is gone), but they are the format's width. An empty log is valid.
#[test]
fn b1b_reflogs_parse_streaming_and_count_their_rows() {
    for format in BOTH_FORMATS_V1 {
        let mut files = base_files(format);
        let head_log = [
            log_row(
                format,
                '0',
                'a',
                &format!("{IDENT_V1}\tcommit (initial): one"),
            ),
            log_row(format, 'a', 'b', &format!("{IDENT_V1}\tcheckout: moving")),
            log_row(format, 'b', 'a', IDENT_V1),
            log_row(
                format,
                '0',
                '9',
                "N <n@e> 0 -1200\tmessage with <angle> brackets and a\u{e9}",
            ),
        ]
        .concat();
        files.push(file_of("logs/HEAD", head_log.into_bytes()));
        files.push(file_of(
            "logs/refs/heads/main",
            log_row(format, '0', 'a', IDENT_V1).into_bytes(),
        ));
        files.push(file_of("logs/refs/stash", Vec::new()));
        let agreement =
            pure(format, &files, &[]).unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(agreement.reflog_files, 3, "{format:?}");
        assert_eq!(agreement.reflog_rows, 5, "{format:?}");
    }
}

#[test]
fn b1b_malformed_reflogs_refuse_with_typed_reasons() {
    for format in BOTH_FORMATS_V1 {
        let (a, b) = (oid_of('a', format), oid_of('b', format));
        let rows: Vec<(&str, String, RowFaultV1)> = vec![
            (
                "one object id",
                format!("{a} {IDENT_V1}\n"),
                RowFaultV1::LogRow,
            ),
            (
                "an upper-case old id",
                format!("{} {b} {IDENT_V1}\n", a.to_uppercase()),
                RowFaultV1::LogRow,
            ),
            (
                "a short new id",
                format!("{a} {} {IDENT_V1}\n", &b[1..]),
                RowFaultV1::LogRow,
            ),
            (
                "two spaces after the old id",
                format!("{a}  {b} {IDENT_V1}\n"),
                RowFaultV1::LogRow,
            ),
            (
                "an identity without an address",
                format!("{a} {b} A U Thor 1700000000 +0000\n"),
                RowFaultV1::LogRow,
            ),
            (
                "an address that never opens",
                format!("{a} {b} A U Thor> 1700000000 +0000\n"),
                RowFaultV1::LogRow,
            ),
            (
                "an address that never closes",
                format!("{a} {b} A U Thor <author@example.invalid 1700000000 +0000\n"),
                RowFaultV1::LogRow,
            ),
            (
                "no identity",
                format!("{a} {b} 1700000000 +0000\n"),
                RowFaultV1::LogRow,
            ),
            (
                "a timestamp that is not digits",
                format!("{a} {b} A <a@e> 17x0000000 +0000\n"),
                RowFaultV1::LogRow,
            ),
            (
                "a missing timestamp",
                format!("{a} {b} A <a@e> +0000\n"),
                RowFaultV1::LogRow,
            ),
            (
                "a zone without a sign",
                format!("{a} {b} A <a@e> 1700000000 0000\n"),
                RowFaultV1::LogRow,
            ),
            (
                "a short zone",
                format!("{a} {b} A <a@e> 1700000000 +000\n"),
                RowFaultV1::LogRow,
            ),
            (
                "a zone with letters",
                format!("{a} {b} A <a@e> 1700000000 +00x0\n"),
                RowFaultV1::LogRow,
            ),
            (
                "a blank row",
                format!("{a} {b} {IDENT_V1}\n\n"),
                RowFaultV1::LogRow,
            ),
            (
                "a NUL in the message",
                format!("{a} {b} {IDENT_V1}\tme\0ssage\n"),
                RowFaultV1::LogRow,
            ),
            (
                "no final newline",
                format!("{a} {b} {IDENT_V1}"),
                RowFaultV1::PartialLine,
            ),
        ];
        for (row, content, why) in rows {
            let mut files = base_files(format);
            files.push(file_of("logs/HEAD", content.into_bytes()));
            assert_eq!(
                fault_of(pure(format, &files, &[]), row),
                row_fault("logs/HEAD", why),
                "{format:?}: {row}"
            );
        }
    }
}

/// A reflog's path is judged as a ref name: `logs/refs/heads/x.lock` and `logs/refs/a..b` refuse, and
/// only `logs/HEAD` and `logs/refs/**` are reflogs.
#[test]
fn b1b_reflog_paths_are_ref_names() {
    let format = GitObjectFormatV1::Sha1;
    for (path, name, why) in [
        (
            "logs/refs/heads/x.lock",
            "refs/heads/x.lock",
            RefNameFaultV1::LockSuffix,
        ),
        ("logs/refs/a..b", "refs/a..b", RefNameFaultV1::DoubleDot),
        (
            "logs/refs/heads/a b",
            "refs/heads/a b",
            RefNameFaultV1::Portable(PortableFaultV1::Unprintable),
        ),
    ] {
        let mut files = base_files(format);
        files.push(file_of(path, Vec::new()));
        assert_eq!(
            fault_of(pure(format, &files, &[]), path),
            name_fault(name, why),
            "{path}"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Agreement: HEAD states, precedence, resolution, kinds, targets, and the manifest
// ---------------------------------------------------------------------------------------------

/// Attached, detached, and unborn HEAD agree with the manifest in both formats; an unborn HEAD needs no
/// object at all (an Empty database), and `Unborn` and `Symbolic` both describe it.
#[test]
fn b1b_attached_detached_and_unborn_heads_agree_with_the_manifest() {
    for format in BOTH_FORMATS_V1 {
        let attached = pure(
            format,
            &base_files(format),
            &[
                ("HEAD", WantV1::Symbolic("refs/heads/main")),
                ("refs/heads/main", WantV1::Direct('a')),
            ],
        )
        .unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(
            attached.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: Some(oid_of('a', format)),
            }
        );
        assert_eq!((attached.manifest_refs, attached.direct_targets), (2, 1));

        let detached = pure(
            format,
            &[file_of("HEAD", direct_file('a', format))],
            &[("HEAD", WantV1::Direct('a'))],
        )
        .unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(
            detached.head,
            HeadStateV1::Detached {
                oid: oid_of('a', format)
            }
        );
        assert_eq!((detached.manifest_refs, detached.direct_targets), (1, 1));

        // Unborn: an Empty database, a HEAD naming a branch that does not exist.
        let unborn_files = [file_of("HEAD", symbolic_file("refs/heads/main"))];
        for refs in [
            &[][..],
            &[("HEAD", WantV1::Symbolic("refs/heads/main"))][..],
            &[("HEAD", WantV1::Unborn)][..],
        ] {
            let unborn = pure_run(format, false, &unborn_files, refs, RefsLimitsV1::v1())
                .unwrap_or_else(|error| panic!("{format:?} {}: {error:?}", refs.len()));
            assert_eq!(
                unborn.head,
                HeadStateV1::Symbolic {
                    target: "refs/heads/main".into(),
                    resolved: None,
                }
            );
            assert_eq!((unborn.direct_targets, unborn.effective_refs), (0, 0));
        }
        // Detached HEAD in an Empty database has no object to name: absent, not unborn.
        assert_eq!(
            fault_of(
                pure_run(
                    format,
                    false,
                    &[file_of("HEAD", direct_file('a', format))],
                    &[],
                    RefsLimitsV1::v1()
                ),
                "an empty inventory"
            ),
            RefsFaultV1::TargetAbsent {
                name: "HEAD".into(),
                oid: oid_of('a', format)
            }
        );
        // No HEAD at all is not an unborn HEAD: exactly one valid HEAD is required.
        assert_eq!(
            fault_of(
                pure(
                    format,
                    &[file_of("refs/heads/main", direct_file('a', format))],
                    &[]
                ),
                "no HEAD"
            ),
            RefsFaultV1::MissingHead
        );
    }
}

/// A loose ref hides a packed ref of the same name (direct or symbolic); a packed-only ref is a ref and
/// can be HEAD's target. A packed row that a loose ref of exactly that name hides is not an active
/// target: its object need not be in the inventory, and no kind or peeled closure applies to it, while
/// every structural rule (grammar, order, name, collisions) still does.
#[test]
fn b1b_loose_refs_win_over_packed_refs_and_packed_only_refs_count() {
    let format = GitObjectFormatV1::Sha1;
    let header = PACKED_HEADER_V1;
    let rows = |extra: &[(&str, char, Option<char>)]| packed(format, header, extra);
    let head = file_of("HEAD", symbolic_file("refs/heads/main"));

    let mut files = vec![
        head.clone(),
        file_of("packed-refs", rows(&[("refs/heads/main", 'a', None)])),
        file_of("refs/heads/main", direct_file('b', format)),
    ];
    pure(format, &files, &[("refs/heads/main", WantV1::Direct('b'))]).expect("the loose value");
    assert_eq!(
        fault_of(
            pure(format, &files, &[("refs/heads/main", WantV1::Direct('a'))]),
            "the packed value is hidden"
        ),
        RefsFaultV1::OriginalMismatch {
            name: "refs/heads/main".into(),
            expected: format!("direct {}", oid_of('a', format)),
            found: format!("direct {}", oid_of('b', format)),
        }
    );
    // HEAD resolves through the loose value, not the packed one.
    let agreement = pure(format, &files, &[]).expect("loose over packed");
    assert_eq!(
        agreement.head,
        HeadStateV1::Symbolic {
            target: "refs/heads/main".into(),
            resolved: Some(oid_of('b', format)),
        }
    );

    // Packed only: HEAD resolves through the packed row.
    files = vec![
        head.clone(),
        file_of("packed-refs", rows(&[("refs/heads/main", 'a', None)])),
    ];
    let agreement = pure(format, &files, &[("refs/heads/main", WantV1::Direct('a'))])
        .expect("a packed-only ref");
    assert_eq!(
        agreement.head,
        HeadStateV1::Symbolic {
            target: "refs/heads/main".into(),
            resolved: Some(oid_of('a', format)),
        }
    );
    assert_eq!(agreement.loose_refs, 0);

    // A loose symbolic ref hides a packed direct one.
    files = vec![
        head.clone(),
        file_of(
            "packed-refs",
            rows(&[
                ("refs/heads/alias", 'a', None),
                ("refs/heads/main", 'a', None),
            ]),
        ),
        file_of("refs/heads/alias", symbolic_file("refs/heads/main")),
    ];
    pure(
        format,
        &files,
        &[("refs/heads/alias", WantV1::Symbolic("refs/heads/main"))],
    )
    .expect("the loose symbolic ref wins");
    assert_eq!(
        fault_of(
            pure(format, &files, &[("refs/heads/alias", WantV1::Direct('a'))]),
            "the packed direct value is hidden"
        ),
        RefsFaultV1::OriginalMismatch {
            name: "refs/heads/alias".into(),
            expected: format!("direct {}", oid_of('a', format)),
            found: "symbolic refs/heads/main".into(),
        }
    );

    // A packed row that a loose ref hides is not an active target: its stale object (here absent from the
    // inventory, as after `pack-refs`, a branch advance, and a prune) is not required.
    files = vec![
        head,
        file_of("packed-refs", rows(&[("refs/heads/hidden", '7', None)])),
        file_of("refs/heads/hidden", direct_file('a', format)),
    ];
    let agreement = pure(
        format,
        &files,
        &[("refs/heads/hidden", WantV1::Direct('a'))],
    )
    .expect("a shadowed stale packed row");
    assert_eq!((agreement.packed_refs, agreement.effective_refs), (1, 1));
    assert_eq!(
        agreement.direct_targets, 1,
        "only the loose value is active"
    );
}

/// A shadowed packed row is judged structurally and nothing more: its object, its kind, and its peeled
/// value (absent, of the wrong kind, a tag without a peel under `fully-peeled`) are never consulted, while
/// every grammar rule, order, and name rule still applies to it, a row nothing shadows is still held to
/// all of them, and a different name shadows nothing.
#[test]
fn b1b_a_shadowed_packed_row_is_not_an_active_target() {
    for format in BOTH_FORMATS_V1 {
        let missing = '7';
        let head = file_of("HEAD", symbolic_file("refs/heads/main"));
        let header = PACKED_HEADER_V1;
        let loose = |path: &'static str, fill: char| file_of(path, direct_file(fill, format));
        let rows = |list: &[(&str, char, Option<char>)]| {
            file_of("packed-refs", packed(format, header, list))
        };
        // Stale objects the inventory lacks, a wrong kind under a branch, a tag with no peeled row, a peeled
        // value that is absent and one that is itself a tag: all behind loose refs of the same names.
        let stale = rows(&[
            ("refs/heads/absent", missing, None),
            ("refs/heads/blob", 'e', None),
            ("refs/tags/bare", 'c', None),
            ("refs/tags/gone", 'c', Some(missing)),
            ("refs/tags/nontag", 'a', Some('b')),
            ("refs/tags/tagged", 'c', Some('c')),
        ]);
        let shadows = vec![
            head.clone(),
            stale.clone(),
            loose("refs/heads/absent", 'a'),
            loose("refs/heads/blob", 'b'),
            loose("refs/tags/bare", 'c'),
            loose("refs/tags/gone", 'c'),
            loose("refs/tags/tagged", 'c'),
            // A loose SYMBOLIC ref hides a packed one too.
            file_of("refs/tags/nontag", symbolic_file("refs/heads/absent")),
        ];
        let agreement = pure(format, &shadows, &[])
            .unwrap_or_else(|error| panic!("{format:?}: the stale rows are shadowed: {error:?}"));
        assert_eq!(agreement.packed_refs, 6, "{format:?}");
        assert_eq!(agreement.peeled_rows, 3, "{format:?}");
        assert_eq!(agreement.effective_refs, 6, "{format:?}");
        // The active direct objects are only the loose ones: a, b, and c.
        assert_eq!(agreement.direct_targets, 3, "{format:?}");

        // Nothing shadows a row of another name, and an unshadowed row is held to every closure rule.
        let kind_fault = |name: &str, oid: char, found: &'static str| RefsFaultV1::TargetKind {
            name: name.into(),
            oid: oid_of(oid, format),
            found,
            expected: "commit",
        };
        let rejected: Vec<(&str, Vec<FileV1>, RefsFaultV1)> = vec![
            (
                "an absent object, shadowed by another name",
                vec![
                    head.clone(),
                    rows(&[("refs/heads/absent", missing, None)]),
                    loose("refs/heads/absent-not", 'a'),
                ],
                RefsFaultV1::TargetAbsent {
                    name: "refs/heads/absent".into(),
                    oid: oid_of(missing, format),
                },
            ),
            (
                "an absent object, shadowed only by its prefix",
                vec![
                    head.clone(),
                    rows(&[("refs/heads/absent", missing, None)]),
                    loose("refs/heads", 'a'),
                ],
                // `refs/heads` as a ref conflicts with the packed name under it: structure is judged first.
                RefsFaultV1::Conflict {
                    name: "refs/heads/absent".into(),
                    with: "refs/heads".into(),
                },
            ),
            (
                "a branch on a blob",
                vec![head.clone(), rows(&[("refs/heads/blob", 'e', None)])],
                kind_fault("refs/heads/blob", 'e', "blob"),
            ),
            (
                "a tag with no peeled row under fully-peeled",
                vec![head.clone(), rows(&[("refs/tags/bare", 'c', None)])],
                RefsFaultV1::PeelMissing {
                    name: "refs/tags/bare".into(),
                },
            ),
            (
                "an absent peeled value",
                vec![
                    head.clone(),
                    rows(&[("refs/tags/gone", 'c', Some(missing))]),
                ],
                RefsFaultV1::TargetAbsent {
                    name: "refs/tags/gone".into(),
                    oid: oid_of(missing, format),
                },
            ),
            (
                "a peeled value that is a tag",
                vec![head.clone(), rows(&[("refs/tags/tagged", 'c', Some('c'))])],
                RefsFaultV1::PeeledIsTag {
                    name: "refs/tags/tagged".into(),
                },
            ),
            (
                "a peeled row under a commit",
                vec![head.clone(), rows(&[("refs/tags/nontag", 'a', Some('b'))])],
                RefsFaultV1::PeeledNotTag {
                    name: "refs/tags/nontag".into(),
                },
            ),
        ];
        for (row, files, expected) in rejected {
            assert_eq!(
                fault_of(pure(format, &files, &[]), row),
                expected,
                "{format:?}: {row}"
            );
        }

        // The grammar of a shadowed row is still judged: a malformed row, a bad name, a repeated name, and
        // rows out of order under `sorted` refuse even when a loose ref shadows every one of them.
        let a = oid_of('a', format);
        let bad: Vec<(&str, String, RefsFaultV1)> = vec![
            (
                "a bad object id",
                format!("{header}{} refs/heads/main\n", a.to_uppercase()),
                row_fault("packed-refs", RowFaultV1::ObjectId),
            ),
            (
                "a bad name",
                format!("{header}{a} refs/heads/main.lock\n"),
                name_fault("refs/heads/main.lock", RefNameFaultV1::LockSuffix),
            ),
            (
                "rows out of order",
                format!("{header}{a} refs/heads/main\n{a} refs/heads/a\n"),
                row_fault("packed-refs", RowFaultV1::PackedOrder),
            ),
            (
                "an orphan peeled row",
                format!("{header}^{a}\n{a} refs/heads/main\n"),
                row_fault("packed-refs", RowFaultV1::PeeledOrphan),
            ),
        ];
        for (row, content, expected) in bad {
            let files = vec![
                head.clone(),
                file_of("packed-refs", content.into_bytes()),
                loose("refs/heads/main", 'a'),
                loose("refs/heads/a", 'a'),
            ];
            assert_eq!(
                fault_of(pure(format, &files, &[]), row),
                expected,
                "{format:?}: {row}"
            );
        }

        // Case collisions and conflicts are still judged across shadowed names.
        let files = vec![
            head.clone(),
            rows(&[("refs/heads/Main", missing, None)]),
            loose("refs/heads/main", 'a'),
        ];
        assert_eq!(
            fault_of(pure(format, &files, &[]), "a shadowed collision"),
            RefsFaultV1::Collision {
                name: "refs/heads/main".into(),
                with: "refs/heads/Main".into(),
            },
            "{format:?}"
        );
    }
}

/// `n` symbolic refs starting at HEAD, each naming the next, the last naming `last`.
fn chain_files(n: usize, last: &'static str, format: GitObjectFormatV1) -> Vec<FileV1> {
    let names: Vec<&'static str> = (1..n)
        .map(|index| &*Box::leak(format!("refs/heads/s{index}").into_boxed_str()))
        .collect();
    let mut files = Vec::new();
    for index in 0..n {
        let target = names.get(index).copied().unwrap_or(last);
        let path = if index == 0 { "HEAD" } else { names[index - 1] };
        files.push(file_of(path, symbolic_file(target)));
    }
    files.push(file_of("refs/heads/main", direct_file('a', format)));
    files
}

/// A chain may follow at most five symbolic refs (Git's own bound): five, ending in a value or in an
/// unborn branch, resolve; six refuse. Ending in an absent ref is unborn only for HEAD or a manifest
/// `Unborn`, so the unborn chain declares each hop `Unborn`.
#[test]
fn b1b_symbolic_chains_are_bounded_at_five() {
    for format in BOTH_FORMATS_V1 {
        let agreement = pure(format, &chain_files(5, "refs/heads/main", format), &[])
            .unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(
            agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/s1".into(),
                resolved: Some(oid_of('a', format)),
            }
        );
        assert_eq!(agreement.symbolic_refs, 4);
        assert_eq!(
            fault_of(
                pure(format, &chain_files(6, "refs/heads/main", format), &[]),
                "six symbolic refs"
            ),
            RefsFaultV1::TooDeep {
                name: "HEAD".into()
            }
        );
        // The same bound for an unborn tail.
        let unborn = |n: usize| {
            let mut files = chain_files(n, "refs/heads/gone", format);
            files.pop();
            let refs: Vec<(&str, WantV1)> = std::iter::once(("HEAD", WantV1::Unborn))
                .chain((1..n).map(|index| {
                    (
                        &*Box::leak(format!("refs/heads/s{index}").into_boxed_str()),
                        WantV1::Unborn,
                    )
                }))
                .collect();
            pure(format, &files, &refs)
        };
        let agreement = unborn(5).unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert!(matches!(
            agreement.head,
            HeadStateV1::Symbolic { resolved: None, .. }
        ));
        assert_eq!(
            fault_of(unborn(6), "six symbolic refs ending unborn"),
            RefsFaultV1::TooDeep {
                name: "HEAD".into()
            }
        );
    }
}

/// Cycles fail closed, whatever their shape: HEAD in a loop, a self loop, a loop that HEAD is not in, a
/// ring short enough to close within the bound (a cycle) and one too long to (too deep).
#[test]
fn b1b_symbolic_cycles_fail_closed() {
    let format = GitObjectFormatV1::Sha1;
    let main = file_of("refs/heads/main", direct_file('a', format));
    let cycle = |name: &str| RefsFaultV1::Cycle { name: name.into() };

    let files = vec![
        file_of("HEAD", symbolic_file("refs/heads/a")),
        file_of("refs/heads/a", symbolic_file("refs/heads/b")),
        file_of("refs/heads/b", symbolic_file("refs/heads/a")),
    ];
    assert_eq!(
        fault_of(pure(format, &files, &[]), "HEAD in a loop"),
        cycle("HEAD")
    );

    let files = vec![
        file_of("HEAD", symbolic_file("refs/heads/main")),
        main.clone(),
        file_of("refs/heads/self", symbolic_file("refs/heads/self")),
    ];
    assert_eq!(
        fault_of(pure(format, &files, &[]), "a self loop"),
        cycle("refs/heads/self")
    );

    let files = vec![
        file_of("HEAD", symbolic_file("refs/heads/main")),
        main.clone(),
        file_of("refs/heads/a", symbolic_file("refs/heads/b")),
        file_of("refs/heads/b", symbolic_file("refs/heads/a")),
    ];
    assert_eq!(
        fault_of(pure(format, &files, &[]), "a loop beside HEAD"),
        cycle("refs/heads/a")
    );

    // A loop through a packed ref cannot exist (packed refs are direct), so a symbolic loop in loose refs
    // is the only kind; rings of six and seven close at, and past, the bound.
    for (ring, expected) in [
        (6, cycle("refs/heads/r1")),
        (
            7,
            RefsFaultV1::TooDeep {
                name: "refs/heads/r1".into(),
            },
        ),
    ] {
        let name = |index: usize| -> &'static str {
            Box::leak(format!("refs/heads/r{index}").into_boxed_str())
        };
        let mut files = vec![
            file_of("HEAD", symbolic_file("refs/heads/main")),
            main.clone(),
        ];
        for index in 1..=ring {
            let next = if index == ring { 1 } else { index + 1 };
            files.push(file_of(name(index), symbolic_file(name(next))));
        }
        assert_eq!(
            fault_of(pure(format, &files, &[]), &format!("a ring of {ring}")),
            expected,
            "a ring of {ring}"
        );
    }
}

/// Only HEAD may be unborn on its own; any other symbolic ref whose chain ends in a missing ref is
/// refused as dangling unless the manifest says it is `Unborn`.
#[test]
fn b1b_dangling_symbolic_refs_refuse_unless_head_or_declared_unborn() {
    for format in BOTH_FORMATS_V1 {
        let mut files = base_files(format);
        files.push(file_of(
            "refs/remotes/origin/HEAD",
            symbolic_file("refs/remotes/origin/main"),
        ));
        assert_eq!(
            fault_of(pure(format, &files, &[]), "a dangling remote HEAD"),
            RefsFaultV1::Dangling {
                name: "refs/remotes/origin/HEAD".into(),
                target: "refs/remotes/origin/main".into(),
            }
        );
        // A manifest that says it is unborn makes it so; a manifest that merely says it is symbolic does
        // not, because the target is still absent.
        pure(
            format,
            &files,
            &[("refs/remotes/origin/HEAD", WantV1::Unborn)],
        )
        .expect("declared unborn");
        assert_eq!(
            fault_of(
                pure(
                    format,
                    &files,
                    &[(
                        "refs/remotes/origin/HEAD",
                        WantV1::Symbolic("refs/remotes/origin/main")
                    )],
                ),
                "declared symbolic only"
            ),
            RefsFaultV1::Dangling {
                name: "refs/remotes/origin/HEAD".into(),
                target: "refs/remotes/origin/main".into(),
            }
        );
        // The target may be absent after more than one hop: the last name is the absent one.
        let files = vec![
            file_of("HEAD", symbolic_file("refs/heads/main")),
            file_of("refs/heads/main", direct_file('a', format)),
            file_of("refs/heads/x", symbolic_file("refs/heads/y")),
            file_of("refs/heads/y", symbolic_file("refs/heads/z")),
        ];
        assert_eq!(
            fault_of(pure(format, &files, &[]), "two hops to nothing"),
            RefsFaultV1::Dangling {
                name: "refs/heads/x".into(),
                target: "refs/heads/z".into(),
            }
        );
    }
}

/// Kind rules: `refs/heads/**`, a detached or resolved HEAD, and ORIG_HEAD must name a commit; other refs
/// may name any known kind; an object of unknown kind is refused wherever it is named.
#[test]
fn b1b_object_kinds_are_validated() {
    for format in BOTH_FORMATS_V1 {
        let kind_fault = |name: &str, fill: char, found: &'static str| RefsFaultV1::TargetKind {
            name: name.into(),
            oid: oid_of(fill, format),
            found,
            expected: "commit",
        };
        for (fill, found) in [('c', "tag"), ('d', "tree"), ('e', "blob")] {
            let mut files = base_files(format);
            files.push(file_of("refs/heads/x", direct_file(fill, format)));
            assert_eq!(
                fault_of(pure(format, &files, &[]), "a head"),
                kind_fault("refs/heads/x", fill, found)
            );
            assert_eq!(
                fault_of(
                    pure(format, &[file_of("HEAD", direct_file(fill, format))], &[]),
                    "a detached HEAD"
                ),
                kind_fault("HEAD", fill, found)
            );
            let mut files = base_files(format);
            files.push(file_of("ORIG_HEAD", direct_file(fill, format)));
            assert_eq!(
                fault_of(pure(format, &files, &[]), "ORIG_HEAD"),
                kind_fault("ORIG_HEAD", fill, found)
            );
            // A symbolic HEAD or head resolves to a non-commit through a tag ref.
            let files = vec![
                file_of("HEAD", symbolic_file("refs/tags/t")),
                file_of("refs/tags/t", direct_file(fill, format)),
            ];
            assert_eq!(
                fault_of(pure(format, &files, &[]), "HEAD resolving to a non-commit"),
                kind_fault("HEAD", fill, found)
            );
            let mut files = base_files(format);
            files.push(file_of("refs/tags/t", direct_file(fill, format)));
            files.push(file_of("refs/heads/alias", symbolic_file("refs/tags/t")));
            assert_eq!(
                fault_of(
                    pure(format, &files, &[]),
                    "an alias resolving to a non-commit"
                ),
                kind_fault("refs/heads/alias", fill, found)
            );
        }
        // Any known kind is a fine tag, note, or custom ref target.
        let mut files = base_files(format);
        for (path, fill) in [
            ("refs/tags/a", 'a'),
            ("refs/tags/c", 'c'),
            ("refs/tags/d", 'd'),
            ("refs/tags/e", 'e'),
            ("refs/notes/commits", 'a'),
            ("refs/custom/x", 'e'),
        ] {
            files.push(file_of(path, direct_file(fill, format)));
        }
        pure(format, &files, &[]).expect("known kinds under non-branch refs");
        // An unknown kind is refused wherever it is named.
        let mut files = base_files(format);
        files.push(file_of("refs/tags/u", direct_file('f', format)));
        assert_eq!(
            fault_of(pure(format, &files, &[]), "an unknown kind"),
            RefsFaultV1::TargetKind {
                name: "refs/tags/u".into(),
                oid: oid_of('f', format),
                found: "unknown",
                expected: "a known kind",
            }
        );
    }
}

/// Every active direct target, from every place one can come from, must be in the inventory, even when
/// the manifest lists none of the refs. The same ref is accepted once its object is in the inventory.
#[test]
fn b1b_every_extra_direct_target_must_be_in_the_inventory() {
    for format in BOTH_FORMATS_V1 {
        let missing = oid_of('7', format);
        let absent = |name: &str| RefsFaultV1::TargetAbsent {
            name: name.into(),
            oid: missing.clone(),
        };
        let header = PACKED_HEADER_V1;
        let loose = |path: &'static str, fill: char| file_of(path, direct_file(fill, format));
        let cases: Vec<(&str, Vec<FileV1>, &str)> = vec![
            (
                "a loose ref",
                vec![loose("refs/heads/x", '7')],
                "refs/heads/x",
            ),
            (
                "a loose tag",
                vec![loose("refs/tags/t", '7')],
                "refs/tags/t",
            ),
            (
                "a packed row",
                vec![file_of(
                    "packed-refs",
                    packed(format, header, &[("refs/heads/p", '7', None)]),
                )],
                "refs/heads/p",
            ),
            (
                "a peeled row",
                vec![file_of(
                    "packed-refs",
                    packed(format, header, &[("refs/tags/v1", 'c', Some('7'))]),
                )],
                "refs/tags/v1",
            ),
            ("ORIG_HEAD", vec![loose("ORIG_HEAD", '7')], "ORIG_HEAD"),
            (
                "a FETCH_HEAD row",
                vec![file_of(
                    "FETCH_HEAD",
                    fetch_head(
                        format,
                        &[('a', "", "first"), ('7', "not-for-merge", "second")],
                    ),
                )],
                "FETCH_HEAD",
            ),
        ];
        for (row, extra, name) in cases {
            let mut files = base_files(format);
            files.extend(extra);
            assert_eq!(
                fault_of(pure(format, &files, &[]), row),
                absent(name),
                "{format:?}: {row}"
            );
        }
        // With an empty inventory, any direct ref is absent.
        assert_eq!(
            fault_of(
                pure_run(
                    format,
                    false,
                    &[
                        file_of("HEAD", symbolic_file("refs/heads/main")),
                        loose("refs/heads/main", 'a')
                    ],
                    &[],
                    RefsLimitsV1::v1()
                ),
                "an empty inventory"
            ),
            RefsFaultV1::TargetAbsent {
                name: "refs/heads/main".into(),
                oid: oid_of('a', format)
            }
        );
        // And the same refs pass when their objects are present.
        let mut files = base_files(format);
        files.extend([
            loose("refs/heads/x", 'b'),
            loose("refs/tags/t", 'c'),
            loose("ORIG_HEAD", 'a'),
            file_of(
                "packed-refs",
                packed(format, header, &[("refs/tags/v1", 'c', Some('a'))]),
            ),
            file_of(
                "FETCH_HEAD",
                fetch_head(format, &[('a', "", "n"), ('e', "", "n")]),
            ),
        ]);
        let agreement = pure(format, &files, &[]).expect("every target present");
        // a (main/ORIG_HEAD/peeled/FETCH_HEAD), b, c, e.
        assert_eq!(agreement.direct_targets, 4, "{format:?}");
        assert_eq!(agreement.manifest_refs, 0);
    }
}

/// Peeled rows are checked against object kinds: only a tag has a peeled value, which is never a tag
/// itself; under the `fully-peeled` trait every tag row needs one, and under `peeled` alone it does not.
#[test]
fn b1b_peeled_rows_are_checked_against_object_kinds() {
    let format = GitObjectFormatV1::Sha1;
    let run = |header: &str, rows: &[(&str, char, Option<char>)]| {
        let files = vec![
            file_of("HEAD", symbolic_file("refs/heads/main")),
            file_of("packed-refs", packed(format, header, rows)),
        ];
        pure(format, &files, &[])
    };
    run(PACKED_HEADER_V1, &[("refs/tags/v1", 'c', Some('a'))]).expect("a tag and its peeled value");
    run(PACKED_HEADER_V1, &[("refs/tags/v1", 'c', Some('d'))]).expect("a tag of a tree");
    assert_eq!(
        fault_of(
            run(PACKED_HEADER_V1, &[("refs/heads/x", 'a', Some('b'))]),
            "a peeled value under a commit"
        ),
        RefsFaultV1::PeeledNotTag {
            name: "refs/heads/x".into()
        }
    );
    assert_eq!(
        fault_of(
            run(PACKED_HEADER_V1, &[("refs/tags/v1", 'c', Some('c'))]),
            "a tag peeled to a tag"
        ),
        RefsFaultV1::PeeledIsTag {
            name: "refs/tags/v1".into()
        }
    );
    assert_eq!(
        fault_of(
            run(PACKED_HEADER_V1, &[("refs/tags/v1", 'c', None)]),
            "fully-peeled without a peeled row"
        ),
        RefsFaultV1::PeelMissing {
            name: "refs/tags/v1".into()
        }
    );
    run(
        "# pack-refs with: peeled sorted \n",
        &[("refs/tags/v1", 'c', None)],
    )
    .expect("peeled alone does not require a row");
    run("", &[("refs/tags/v1", 'c', None)]).expect("no header, no promise");
    // A non-tag row without a peeled row is the ordinary case.
    run(PACKED_HEADER_V1, &[("refs/heads/x", 'a', None)]).expect("a commit with no peeled row");
}

/// Every manifest ref is cross-checked by name and by target kind; the refs the manifest does not list
/// are still checked, and `Unborn` means a symbolic ref whose chain ends in a missing ref.
#[test]
fn b1b_every_manifest_ref_is_cross_checked_by_name_and_target() {
    for format in BOTH_FORMATS_V1 {
        let mut files = base_files(format);
        files.extend([
            file_of("refs/heads/side", direct_file('b', format)),
            file_of("refs/tags/v1", direct_file('c', format)),
            file_of("refs/heads/alias", symbolic_file("refs/heads/main")),
            file_of("ORIG_HEAD", direct_file('b', format)),
        ]);
        let all: Vec<(&str, WantV1)> = vec![
            ("HEAD", WantV1::Symbolic("refs/heads/main")),
            ("ORIG_HEAD", WantV1::Direct('b')),
            ("refs/heads/alias", WantV1::Symbolic("refs/heads/main")),
            ("refs/heads/main", WantV1::Direct('a')),
            ("refs/heads/side", WantV1::Direct('b')),
            ("refs/tags/v1", WantV1::Direct('c')),
        ];
        let agreement =
            pure(format, &files, &all).unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(agreement.manifest_refs, 6);
        // A subset: the unlisted refs are still restored and still valid.
        let subset = pure(format, &files, &all[..1]).expect("a subset");
        assert_eq!(subset.manifest_refs, 1);
        assert_eq!(subset.effective_refs, 4);

        let with = |name: &'static str, want: WantV1| -> Vec<(&'static str, WantV1)> {
            let mut refs: Vec<_> = all.iter().filter(|(n, _)| *n != name).cloned().collect();
            refs.push((name, want));
            refs
        };
        let mismatch =
            |name: &str, expected: String, found: String| RefsFaultV1::OriginalMismatch {
                name: name.into(),
                expected,
                found,
            };
        let (a, b) = (oid_of('a', format), oid_of('b', format));
        let table: Vec<(&str, ManifestRefsV1, RefsFaultV1)> = vec![
            (
                "a missing original ref",
                with("refs/heads/ghost", WantV1::Direct('a')),
                RefsFaultV1::MissingOriginal {
                    name: "refs/heads/ghost".into(),
                },
            ),
            (
                "a missing pseudoref",
                with("FETCH_HEAD", WantV1::Direct('a')),
                RefsFaultV1::MissingOriginal {
                    name: "FETCH_HEAD".into(),
                },
            ),
            (
                "a different object",
                with("refs/heads/side", WantV1::Direct('a')),
                mismatch(
                    "refs/heads/side",
                    format!("direct {a}"),
                    format!("direct {b}"),
                ),
            ),
            (
                "a different ORIG_HEAD",
                with("ORIG_HEAD", WantV1::Direct('a')),
                mismatch("ORIG_HEAD", format!("direct {a}"), format!("direct {b}")),
            ),
            (
                "direct, but symbolic",
                with("refs/heads/alias", WantV1::Direct('a')),
                mismatch(
                    "refs/heads/alias",
                    format!("direct {a}"),
                    "symbolic refs/heads/main".into(),
                ),
            ),
            (
                "symbolic, but direct",
                with("refs/heads/side", WantV1::Symbolic("refs/heads/main")),
                mismatch(
                    "refs/heads/side",
                    "symbolic refs/heads/main".into(),
                    format!("direct {b}"),
                ),
            ),
            (
                "another symbolic target",
                with("HEAD", WantV1::Symbolic("refs/heads/side")),
                mismatch(
                    "HEAD",
                    "symbolic refs/heads/side".into(),
                    "symbolic refs/heads/main".into(),
                ),
            ),
            (
                "an attached HEAD that the manifest calls detached",
                with("HEAD", WantV1::Direct('a')),
                mismatch(
                    "HEAD",
                    format!("direct {a}"),
                    "symbolic refs/heads/main".into(),
                ),
            ),
            (
                "unborn, but direct",
                with("refs/heads/main", WantV1::Unborn),
                mismatch("refs/heads/main", "unborn".into(), format!("direct {a}")),
            ),
            (
                "unborn, but the chain resolves",
                with("HEAD", WantV1::Unborn),
                mismatch("HEAD", "unborn".into(), "symbolic refs/heads/main".into()),
            ),
        ];
        for (row, refs, expected) in table {
            assert_eq!(
                fault_of(pure(format, &files, &refs), row),
                expected,
                "{format:?}: {row}"
            );
        }
        // A detached HEAD that the manifest calls attached.
        assert_eq!(
            fault_of(
                pure(
                    format,
                    &[file_of("HEAD", direct_file('a', format))],
                    &[("HEAD", WantV1::Symbolic("refs/heads/main"))]
                ),
                "a detached HEAD called attached"
            ),
            mismatch(
                "HEAD",
                "symbolic refs/heads/main".into(),
                format!("direct {a}")
            )
        );
    }
}

/// A manifest ref with a name or a symbolic target that is not a valid ref name is refused by name, and
/// the three pseudorefs are the only names that need not be under `refs/`.
#[test]
fn b1b_manifest_ref_names_and_targets_are_validated() {
    let format = GitObjectFormatV1::Sha1;
    let files = base_files(format);
    for (name, why) in [
        ("refs/heads/x.lock", RefNameFaultV1::LockSuffix),
        ("heads/main", RefNameFaultV1::NotUnderRefs),
        ("head", RefNameFaultV1::NotUnderRefs),
        ("MERGE_HEAD", RefNameFaultV1::NotUnderRefs),
        ("refs/heads/a..b", RefNameFaultV1::DoubleDot),
    ] {
        assert_eq!(
            fault_of(pure(format, &files, &[(name, WantV1::Direct('a'))]), name),
            RefsFaultV1::ManifestName {
                name: name.into(),
                why
            },
            "{name}"
        );
    }
    for (target, why) in [
        ("main", RefNameFaultV1::NotUnderRefs),
        ("HEAD", RefNameFaultV1::NotUnderRefs),
        ("refs/heads/x.lock", RefNameFaultV1::LockSuffix),
    ] {
        assert_eq!(
            fault_of(
                pure(format, &files, &[("HEAD", WantV1::Symbolic(target))]),
                target
            ),
            RefsFaultV1::ManifestTarget {
                name: "HEAD".into(),
                target: target.into(),
                why
            },
            "{target}"
        );
    }
    // A manifest object in another format than the caller's is the inventory's format refusal.
    let mut builder = RefsBuilderV1::new(format, RefsLimitsV1::v1(), far_deadline());
    for (path, content) in &files {
        let mut reader: &[u8] = content;
        builder
            .admit_file(path.as_bytes(), &mut reader)
            .expect("a file");
    }
    let error = builder
        .finish(&pool_manifest(GitObjectFormatV1::Sha256, true, &[]))
        .expect_err("a SHA-256 manifest for a SHA-1 caller");
    assert!(
        matches!(error, GitBootstrapErrorV1::FormatMismatch(_)),
        "{error:?}"
    );
}

/// Structure: a ref and a ref under it (in any mix of loose and packed) conflict, spellings that differ
/// only by ASCII case collide, and the same name loose and packed is one ref, not a collision.
#[test]
fn b1b_ref_names_that_conflict_or_collide_refuse() {
    let format = GitObjectFormatV1::Sha1;
    let header = PACKED_HEADER_V1;
    let head = file_of("HEAD", symbolic_file("refs/heads/main"));
    let loose = |path: &'static str| file_of(path, direct_file('a', format));
    let rows =
        |list: &[(&str, char, Option<char>)]| file_of("packed-refs", packed(format, header, list));
    let conflict = |name: &str, with: &str| RefsFaultV1::Conflict {
        name: name.into(),
        with: with.into(),
    };
    let collision = |name: &str, with: &str| RefsFaultV1::Collision {
        name: name.into(),
        with: with.into(),
    };
    assert_eq!(
        fault_of(
            pure(
                format,
                &[
                    head.clone(),
                    loose("refs/heads/a"),
                    rows(&[("refs/heads/a/b", 'a', None)])
                ],
                &[]
            ),
            "loose over packed"
        ),
        conflict("refs/heads/a/b", "refs/heads/a")
    );
    assert_eq!(
        fault_of(
            pure(
                format,
                &[
                    head.clone(),
                    loose("refs/heads/a/b"),
                    rows(&[("refs/heads/a", 'a', None)])
                ],
                &[]
            ),
            "packed over loose"
        ),
        conflict("refs/heads/a/b", "refs/heads/a")
    );
    assert_eq!(
        fault_of(
            pure(
                format,
                &[
                    head.clone(),
                    rows(&[("refs/heads/a", 'a', None), ("refs/heads/a/b", 'a', None)])
                ],
                &[]
            ),
            "within packed"
        ),
        conflict("refs/heads/a/b", "refs/heads/a")
    );
    assert_eq!(
        fault_of(
            pure(
                format,
                &[
                    head.clone(),
                    loose("refs/heads/Main"),
                    rows(&[("refs/heads/main", 'a', None)])
                ],
                &[]
            ),
            "case, loose and packed"
        ),
        collision("refs/heads/main", "refs/heads/Main")
    );
    assert_eq!(
        fault_of(
            pure(
                format,
                &[head.clone(), loose("refs/heads/A"), loose("refs/heads/a")],
                &[]
            ),
            "case, both loose"
        ),
        collision("refs/heads/a", "refs/heads/A")
    );
    assert_eq!(
        fault_of(
            pure(
                format,
                &[
                    head.clone(),
                    rows(&[("refs/heads/A", 'a', None), ("refs/heads/a", 'a', None)])
                ],
                &[]
            ),
            "case, both packed"
        ),
        collision("refs/heads/a", "refs/heads/A")
    );
    // The same name in both is one ref, and a prefix that is not a path component is no conflict.
    pure(
        format,
        &[
            head.clone(),
            loose("refs/heads/a"),
            rows(&[("refs/heads/a", 'a', None), ("refs/heads/ab", 'a', None)]),
        ],
        &[],
    )
    .expect("the same name loose and packed, and a sibling that shares a prefix");
}

// ---------------------------------------------------------------------------------------------
// Limits and the one deadline, on the pure builder
// ---------------------------------------------------------------------------------------------

fn limits_with(edit: impl FnOnce(&mut RefsLimitsV1)) -> RefsLimitsV1 {
    let mut limits = RefsLimitsV1::v1();
    edit(&mut limits);
    limits
}

fn limit_fault(what: RefsLimitKindV1, bound: u64) -> RefsFaultV1 {
    RefsFaultV1::Limit { what, bound }
}

/// Runs `pure_run` under `limits` over `files` with an attached-HEAD manifest-free state.
fn limited(
    format: GitObjectFormatV1,
    files: &[FileV1],
    limits: RefsLimitsV1,
) -> Result<RefsAgreementV1, GitBootstrapErrorV1> {
    pure_run(format, true, files, &[], limits)
}

/// The documented v1 limits, and the retained-cost formula the accounting rows rely on.
#[test]
fn b1b_the_v1_limits_and_the_cost_formula_are_the_documented_ones() {
    let limits = RefsLimitsV1::v1();
    assert_eq!(limits.line_bytes, 8 * 1024);
    assert_eq!(limits.loose_file_bytes, 16 * 1024);
    assert_eq!(limits.packed_file_bytes, 64 * 1024 * 1024);
    assert_eq!(limits.fetch_head_bytes, 1024 * 1024);
    assert_eq!(limits.log_file_bytes, 64 * 1024 * 1024);
    assert_eq!(limits.entries, 262_144);
    assert_eq!(limits.retained_bytes, 64 * 1024 * 1024);
    // Two copies of the name (the map key and its case key), the value, and a fixed allowance.
    assert_eq!(refs_entry_cost_v1(0, 0), 64);
    assert_eq!(refs_entry_cost_v1(15, 40), 64 + 2 * 15 + 40);
    assert!(limits.line_bytes < limits.loose_file_bytes);
}

/// Each per-file byte cap is exact: a file of exactly the cap parses, one byte more is refused with the
/// typed limit and the cap, for every kind of file and in both formats.
#[test]
fn b1b_each_file_byte_cap_is_exact() {
    for format in BOTH_FORMATS_V1 {
        let direct = direct_file('a', format);
        let symbolic = symbolic_file("refs/heads/main");
        let packed_bytes = packed(
            format,
            PACKED_HEADER_V1,
            &[
                ("refs/heads/main", 'a', None),
                ("refs/tags/v1", 'c', Some('a')),
            ],
        );
        let fetch = fetch_head(format, &[('a', "", "note"), ('b', "not-for-merge", "n")]);
        let log = [
            log_row(format, '0', 'a', IDENT_V1),
            log_row(format, 'a', 'b', &format!("{IDENT_V1}\tmessage")),
        ]
        .concat()
        .into_bytes();
        type Edit = fn(&mut RefsLimitsV1, u64);
        let rows: Vec<(&str, FileV1, RefsLimitKindV1, Edit)> = vec![
            (
                "HEAD",
                file_of("HEAD", symbolic.clone()),
                RefsLimitKindV1::LooseFile,
                |limits, bound| limits.loose_file_bytes = bound,
            ),
            (
                "a detached HEAD",
                file_of("HEAD", direct.clone()),
                RefsLimitKindV1::LooseFile,
                |limits, bound| limits.loose_file_bytes = bound,
            ),
            (
                "ORIG_HEAD",
                file_of("ORIG_HEAD", direct.clone()),
                RefsLimitKindV1::LooseFile,
                |limits, bound| limits.loose_file_bytes = bound,
            ),
            (
                "a loose ref",
                file_of("refs/heads/x", direct.clone()),
                RefsLimitKindV1::LooseFile,
                |limits, bound| limits.loose_file_bytes = bound,
            ),
            (
                "packed-refs",
                file_of("packed-refs", packed_bytes),
                RefsLimitKindV1::PackedFile,
                |limits, bound| limits.packed_file_bytes = bound,
            ),
            (
                "FETCH_HEAD",
                file_of("FETCH_HEAD", fetch),
                RefsLimitKindV1::FetchHeadFile,
                |limits, bound| limits.fetch_head_bytes = bound,
            ),
            (
                "a reflog",
                file_of("logs/HEAD", log),
                RefsLimitKindV1::LogFile,
                |limits, bound| limits.log_file_bytes = bound,
            ),
        ];
        for (row, file, what, edit) in rows {
            let length = file.1.len() as u64;
            let others = if file.0 == "HEAD" {
                vec![]
            } else {
                vec![file_of("HEAD", symbolic.clone())]
            };
            let run = |bound: u64| {
                let mut files = others.clone();
                files.push(file.clone());
                limited(format, &files, limits_with(|limits| edit(limits, bound)))
            };
            // The HEAD file itself must also be valid for the manifest-free finish.
            run(length).unwrap_or_else(|error| panic!("{format:?} {row}: at the cap: {error:?}"));
            assert_eq!(
                fault_of(run(length - 1), row),
                limit_fault(what, length - 1),
                "{format:?} {row}: one byte over"
            );
        }
    }
}

/// The line cap is exact too, for every line-structured file: a line of exactly the cap (without its
/// LF) parses, one byte longer is refused.
#[test]
fn b1b_the_line_cap_is_exact() {
    for format in BOTH_FORMATS_V1 {
        let width = oid_len(format) as u64;
        let head = file_of("HEAD", symbolic_file("refs/heads/main"));
        let head_line = "ref: refs/heads/main".len() as u64;
        // Each row: the files, and the length of the one line the cap is lowered onto.
        let rows: Vec<(&str, Vec<FileV1>, u64)> = vec![
            (
                "a direct loose ref",
                vec![
                    head.clone(),
                    file_of("refs/heads/x", direct_file('a', format)),
                ],
                width,
            ),
            ("a symbolic HEAD", vec![head.clone()], head_line),
            (
                "a packed row",
                vec![
                    head.clone(),
                    file_of(
                        "packed-refs",
                        packed(format, "", &[("refs/heads/x", 'a', None)]),
                    ),
                ],
                width + 1 + "refs/heads/x".len() as u64,
            ),
            (
                "a FETCH_HEAD row",
                vec![
                    head.clone(),
                    file_of("FETCH_HEAD", fetch_head(format, &[('a', "", "note")])),
                ],
                width + 2 + "note".len() as u64,
            ),
            (
                "a reflog row",
                vec![
                    head.clone(),
                    file_of(
                        "logs/HEAD",
                        log_row(format, '0', 'a', IDENT_V1).into_bytes(),
                    ),
                ],
                2 * width + 2 + IDENT_V1.len() as u64,
            ),
        ];
        for (row, files, cap) in rows {
            let run = |bound: u64| {
                limited(
                    format,
                    &files,
                    limits_with(|limits| {
                        limits.line_bytes = bound;
                    }),
                )
            };
            run(cap).unwrap_or_else(|error| panic!("{format:?} {row}: at the cap: {error:?}"));
            assert_eq!(
                fault_of(run(cap - 1), row),
                limit_fault(RefsLimitKindV1::Line, cap - 1),
                "{format:?} {row}"
            );
        }
    }
}

/// The record cap counts every admitted record: each loose file (HEAD and ORIG_HEAD included), each
/// packed row and peeled row, each FETCH_HEAD row, and each reflog file.
#[test]
fn b1b_the_entry_cap_counts_every_admitted_record() {
    for format in BOTH_FORMATS_V1 {
        let files = vec![
            file_of("HEAD", symbolic_file("refs/heads/main")), // 1
            file_of("ORIG_HEAD", direct_file('a', format)),    // 2
            file_of("refs/heads/main", direct_file('a', format)), // 3
            file_of(
                "packed-refs",
                packed(
                    format,
                    PACKED_HEADER_V1,
                    &[
                        ("refs/heads/p", 'a', None),
                        ("refs/tags/v1", 'c', Some('a')),
                    ],
                ),
            ), // 4, 5, and the peeled row 6
            file_of(
                "FETCH_HEAD",
                fetch_head(format, &[('a', "", "n"), ('b', "", "n")]),
            ), // 7, 8
            file_of("logs/HEAD", Vec::new()),                  // 9
            file_of("logs/refs/heads/main", Vec::new()),       // 10
        ];
        let run =
            |bound: u64| limited(format, &files, limits_with(|limits| limits.entries = bound));
        let agreement = run(10).unwrap_or_else(|error| panic!("{format:?}: {error:?}"));
        assert_eq!(agreement.reflog_files, 2);
        assert_eq!(
            fault_of(run(9), "one record over"),
            limit_fault(RefsLimitKindV1::Entries, 9),
            "{format:?}"
        );
        assert_eq!(
            fault_of(run(0), "no records"),
            limit_fault(RefsLimitKindV1::Entries, 0),
            "{format:?}"
        );
    }
}

/// The retained-bytes cap is exact: the sum of every retained record's cost parses, one byte less is
/// refused. A reflog retains only its name (its rows stream by and are never kept).
#[test]
fn b1b_the_retained_cap_is_exact_and_reflogs_retain_only_their_names() {
    for format in BOTH_FORMATS_V1 {
        let width = oid_len(format);
        let files = vec![
            file_of("HEAD", symbolic_file("refs/heads/main")),
            file_of("refs/heads/main", direct_file('a', format)),
            file_of("refs/heads/alias", symbolic_file("refs/heads/main")),
            file_of("ORIG_HEAD", direct_file('b', format)),
            file_of(
                "packed-refs",
                packed(
                    format,
                    PACKED_HEADER_V1,
                    &[
                        ("refs/heads/p", 'a', None),
                        ("refs/tags/v1", 'c', Some('a')),
                    ],
                ),
            ),
            file_of(
                "FETCH_HEAD",
                fetch_head(format, &[('a', "", "n"), ('b', "", "n")]),
            ),
            file_of(
                "logs/HEAD",
                log_row(format, '0', 'a', IDENT_V1).into_bytes(),
            ),
        ];
        let expected = refs_entry_cost_v1("HEAD".len(), "refs/heads/main".len())
            + refs_entry_cost_v1("refs/heads/main".len(), width)
            + refs_entry_cost_v1("refs/heads/alias".len(), "refs/heads/main".len())
            + refs_entry_cost_v1("ORIG_HEAD".len(), width)
            + refs_entry_cost_v1("refs/heads/p".len(), width)
            + refs_entry_cost_v1("refs/tags/v1".len(), 2 * width)
            + 2 * refs_entry_cost_v1(0, width)
            + refs_entry_cost_v1("logs/HEAD".len(), 0);
        let run = |bound: u64| {
            limited(
                format,
                &files,
                limits_with(|limits| limits.retained_bytes = bound),
            )
        };
        run(expected).unwrap_or_else(|error| panic!("{format:?}: at the sum: {error:?}"));
        assert_eq!(
            fault_of(run(expected - 1), "one byte less"),
            limit_fault(RefsLimitKindV1::Retained, expected - 1),
            "{format:?}"
        );
    }
}

/// A reader that serves `data` forever (or until `data` is `None`'s generator ends) and counts what it
/// served: bounded admission means a hostile stream stops at the cap, never at the end of the stream.
struct EndlessV1<F: FnMut(&mut [u8]) -> usize> {
    fill: F,
    served: std::rc::Rc<std::cell::Cell<u64>>,
}

impl<F: FnMut(&mut [u8]) -> usize> std::io::Read for EndlessV1<F> {
    fn read(&mut self, buffer: &mut [u8]) -> std::io::Result<usize> {
        let count = (self.fill)(buffer);
        self.served.set(self.served.get() + count as u64);
        Ok(count)
    }
}

/// Never-ending inputs stop at their cap with a typed refusal after reading at most the cap plus one
/// byte, never buffering the stream: a line with no LF, an endless list of valid packed rows, FETCH_HEAD
/// rows, and reflog rows.
#[test]
fn b1b_endless_inputs_stop_at_their_caps() {
    for format in BOTH_FORMATS_V1 {
        let served = std::rc::Rc::new(std::cell::Cell::new(0_u64));
        let builder = |limits: RefsLimitsV1| {
            served.set(0);
            RefsBuilderV1::new(format, limits, far_deadline())
        };
        // No LF, ever: the line cap stops it before the loose-file cap.
        let mut x = EndlessV1 {
            fill: |buffer: &mut [u8]| {
                buffer.fill(b'x');
                buffer.len()
            },
            served: served.clone(),
        };
        let limits = RefsLimitsV1::v1();
        let error = builder(limits)
            .admit_file(b"refs/heads/x", &mut x)
            .expect_err("an endless line");
        assert_eq!(
            refs_fault(error),
            limit_fault(RefsLimitKindV1::Line, limits.line_bytes)
        );
        assert!(
            served.get() <= limits.loose_file_bytes + 1,
            "{}",
            served.get()
        );
        // With the line cap out of the way, the loose-file cap itself stops it.
        served.set(0);
        let limits = limits_with(|limits| {
            limits.line_bytes = 1 << 30;
            limits.loose_file_bytes = 100;
        });
        let error = builder(limits)
            .admit_file(b"HEAD", &mut x)
            .expect_err("an endless loose file");
        assert_eq!(
            refs_fault(error),
            limit_fault(RefsLimitKindV1::LooseFile, 100)
        );
        assert!(served.get() <= 101, "{}", served.get());

        // Endless valid rows, one family at a time, each stopped by its file cap.
        type RowFn = Box<dyn Fn(u64) -> String>;
        let families: Vec<(&str, &[u8], RowFn, RefsLimitKindV1)> = vec![
            (
                "packed rows",
                &b"packed-refs"[..],
                Box::new(move |index| format!("{} refs/heads/n{index}\n", oid_of('a', format))),
                RefsLimitKindV1::PackedFile,
            ),
            (
                "FETCH_HEAD rows",
                &b"FETCH_HEAD"[..],
                Box::new(move |_| format!("{}\t\tnote\n", oid_of('a', format))),
                RefsLimitKindV1::FetchHeadFile,
            ),
            (
                "reflog rows",
                &b"logs/HEAD"[..],
                Box::new(move |_| log_row(format, '0', 'a', IDENT_V1)),
                RefsLimitKindV1::LogFile,
            ),
        ];
        for (family, path, row, what) in families {
            let cap = 64 * 1024_u64;
            let limits = limits_with(|limits| {
                limits.packed_file_bytes = cap;
                limits.fetch_head_bytes = cap;
                limits.log_file_bytes = cap;
            });
            let mut index = 0_u64;
            let mut pending: Vec<u8> = Vec::new();
            let mut stream = EndlessV1 {
                fill: |buffer: &mut [u8]| {
                    while pending.len() < buffer.len() {
                        pending.extend_from_slice(row(index).as_bytes());
                        index += 1;
                    }
                    let count = buffer.len();
                    buffer.copy_from_slice(&pending[..count]);
                    pending.drain(..count);
                    count
                },
                served: served.clone(),
            };
            let error = builder(limits)
                .admit_file(path, &mut stream)
                .expect_err(family);
            assert_eq!(refs_fault(error), limit_fault(what, cap), "{family}");
            assert!(served.get() <= cap + 1, "{family}: served {}", served.get());
        }
    }
}

/// A read error from the source is an `Unreadable` refusal naming the file, never a partial success.
#[test]
fn b1b_a_failing_source_is_unreadable_not_partial() {
    struct FailingV1;
    impl std::io::Read for FailingV1 {
        fn read(&mut self, _buffer: &mut [u8]) -> std::io::Result<usize> {
            Err(std::io::Error::other("a failing source"))
        }
    }
    for path in [
        "HEAD",
        "refs/heads/x",
        "ORIG_HEAD",
        "FETCH_HEAD",
        "packed-refs",
        "logs/HEAD",
    ] {
        let mut builder =
            RefsBuilderV1::new(GitObjectFormatV1::Sha1, RefsLimitsV1::v1(), far_deadline());
        let error = builder
            .admit_file(path.as_bytes(), &mut FailingV1)
            .expect_err(path);
        assert_eq!(
            refs_fault(error),
            RefsFaultV1::Unreadable { path: path.into() },
            "{path}"
        );
    }
}

/// A source that hands out `data` in small reads and counts them; `on_read` runs before each one.
struct SlowV1<'a> {
    data: &'a [u8],
    reads: std::rc::Rc<std::cell::Cell<usize>>,
    on_read: Box<dyn Fn(usize) + 'a>,
}

impl std::io::Read for SlowV1<'_> {
    fn read(&mut self, buffer: &mut [u8]) -> std::io::Result<usize> {
        (self.on_read)(self.reads.get());
        self.reads.set(self.reads.get() + 1);
        let count = buffer.len().min(16).min(self.data.len());
        buffer[..count].copy_from_slice(&self.data[..count]);
        self.data = &self.data[count..];
        Ok(count)
    }
}

/// The one deadline is checked before every read of every file kind: a deadline already spent refuses
/// before the first read, and a deadline that passes during one read stops the next. No byte is
/// requested from a source after the deadline.
#[test]
fn b1b_no_source_read_follows_the_deadline() {
    let format = GitObjectFormatV1::Sha1;
    let rows = packed(
        format,
        PACKED_HEADER_V1,
        &[
            ("refs/heads/a", 'a', None),
            ("refs/heads/b", 'a', None),
            ("refs/heads/c", 'a', None),
        ],
    );
    let log = [
        log_row(format, '0', 'a', IDENT_V1),
        log_row(format, 'a', 'b', IDENT_V1),
        log_row(format, 'b', 'a', IDENT_V1),
    ]
    .concat()
    .into_bytes();
    let fetch = fetch_head(
        format,
        &[('a', "", "one"), ('b', "", "two"), ('a', "", "three")],
    );
    let files: Vec<(&[u8], Vec<u8>)> = vec![
        (&b"HEAD"[..], symbolic_file("refs/heads/main")),
        (&b"refs/heads/x"[..], direct_file('a', format)),
        (&b"packed-refs"[..], rows),
        (&b"FETCH_HEAD"[..], fetch),
        (&b"logs/HEAD"[..], log),
    ];
    for (path, data) in &files {
        let label = String::from_utf8_lossy(path).into_owned();
        // Already spent: refused before the first read.
        let reads = std::rc::Rc::new(std::cell::Cell::new(0_usize));
        let spent = Instant::now();
        std::thread::sleep(Duration::from_millis(5));
        let mut source = SlowV1 {
            data,
            reads: reads.clone(),
            on_read: Box::new(|_| {}),
        };
        let mut builder = RefsBuilderV1::new(format, RefsLimitsV1::v1(), spent);
        let error = builder.admit_file(path, &mut source).expect_err(&label);
        assert!(
            matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
            "{label}: {error:?}"
        );
        assert_eq!(reads.get(), 0, "{label}: a read after a spent deadline");

        // Passes during the first read: the second is never requested.
        let reads = std::rc::Rc::new(std::cell::Cell::new(0_usize));
        let deadline = Instant::now() + Duration::from_secs(3);
        let mut source = SlowV1 {
            data,
            reads: reads.clone(),
            on_read: Box::new(move |index| {
                if index == 0 {
                    pass_the_deadline(deadline);
                }
            }),
        };
        let mut builder = RefsBuilderV1::new(format, RefsLimitsV1::v1(), deadline);
        let error = builder.admit_file(path, &mut source).expect_err(&label);
        assert!(
            matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
            "{label}: {error:?}"
        );
        assert_eq!(reads.get(), 1, "{label}: a read after the deadline");
    }
}

/// A spent deadline refuses ahead of everything else the builder does with a file, including routing it:
/// a path that is no refs file at all is a timeout, not an unexpected file, and nothing is read.
#[test]
fn b1b_a_spent_deadline_refuses_before_a_file_is_routed() {
    let spent = Instant::now();
    std::thread::sleep(Duration::from_millis(5));
    for path in ["config", "HEAD", "refs/heads/x", "logs/HEAD"] {
        let reads = std::rc::Rc::new(std::cell::Cell::new(0_usize));
        let mut source = SlowV1 {
            data: b"x\n",
            reads: reads.clone(),
            on_read: Box::new(|_| {}),
        };
        let mut builder = RefsBuilderV1::new(GitObjectFormatV1::Sha1, RefsLimitsV1::v1(), spent);
        let error = builder
            .admit_file(path.as_bytes(), &mut source)
            .expect_err(path);
        assert!(
            matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
            "{path}: {error:?}"
        );
        assert_eq!(reads.get(), 0, "{path}");
    }
}

/// The agreement's own phases each observe the deadline: a clean run reads the clock at exactly the
/// documented guards, in order; each guard halts the run alone, AT that guard; and brief delays at every
/// guard, with headroom, still succeed.
#[test]
fn b1b_the_agreement_phases_each_observe_the_deadline() {
    const GUARDS: [&str; 4] = [
        "refs-structure",
        "refs-targets",
        "refs-resolved",
        "refs-manifest",
    ];
    let format = GitObjectFormatV1::Sha1;
    let files = base_files(format);
    let refs = [
        ("HEAD", WantV1::Symbolic("refs/heads/main")),
        ("refs/heads/main", WantV1::Direct('a')),
    ];
    let run = |deadline: Instant| {
        let mut builder = RefsBuilderV1::new(format, RefsLimitsV1::v1(), deadline);
        for (path, content) in &files {
            let mut reader: &[u8] = content;
            builder.admit_file(path.as_bytes(), &mut reader)?;
        }
        builder.finish(&pool_manifest(format, true, &refs))
    };
    let (labels, hook) = record_guards();
    run(far_deadline()).expect("a clean run");
    drop(hook);
    assert_eq!(*labels.borrow(), GUARDS);

    for target in GUARDS {
        let deadline = Instant::now() + B1A_DEADLINE_V1;
        let labels = std::rc::Rc::new(std::cell::RefCell::new(Vec::<&'static str>::new()));
        let fired = std::rc::Rc::new(std::cell::Cell::new(false));
        let (seen, slow) = (labels.clone(), fired.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            seen.borrow_mut().push(event.label);
            if event.label == target && !slow.replace(true) {
                pass_the_deadline(deadline);
            }
        });
        let error = run(deadline).expect_err(target);
        assert!(
            matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
            "{target}: {error:?}"
        );
        assert!(fired.get(), "{target}: the slow step never ran");
        assert_eq!(
            labels.borrow().last().copied(),
            Some(target),
            "{target}: the run halted AT its guard: {:?}",
            labels.borrow()
        );
    }
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, |_| {
        std::thread::sleep(Duration::from_millis(40));
    });
    run(Instant::now() + B1A_DEADLINE_V1).expect("brief delays leave most of the deadline");
}

// ---------------------------------------------------------------------------------------------
// The inert config encoder
// ---------------------------------------------------------------------------------------------

const CONFIG_SHA1_V1: &[u8] = b"[core]\n\trepositoryformatversion = 0\n\tbare = false\n\tfilemode = true\n\tlogallrefupdates = true\n\tfsmonitor = false\n";
const CONFIG_SHA256_V1: &[u8] = b"[core]\n\trepositoryformatversion = 1\n\tbare = false\n\tfilemode = true\n\tlogallrefupdates = true\n\tfsmonitor = false\n[extensions]\n\tobjectformat = sha256\n";

/// The encoder's bytes are exactly the master's ordered keys, in both formats: `[core]`
/// repositoryformatversion (0 or 1), bare, filemode, logallrefupdates, fsmonitor; SHA-256 additionally
/// `[extensions]` objectformat. LF line ends, tab indentation, `key = value`, one trailing LF.
#[test]
fn b1b_the_inert_config_is_the_golden_bytes_in_both_formats() {
    assert_eq!(
        encode_inert_config_v1(GitObjectFormatV1::Sha1),
        CONFIG_SHA1_V1,
        "{}",
        String::from_utf8_lossy(&encode_inert_config_v1(GitObjectFormatV1::Sha1))
    );
    assert_eq!(
        encode_inert_config_v1(GitObjectFormatV1::Sha256),
        CONFIG_SHA256_V1,
        "{}",
        String::from_utf8_lossy(&encode_inert_config_v1(GitObjectFormatV1::Sha256))
    );
    // Deterministic: the same bytes every time, and the two formats differ.
    for format in BOTH_FORMATS_V1 {
        assert_eq!(
            encode_inert_config_v1(format),
            encode_inert_config_v1(format)
        );
    }
    assert_ne!(
        encode_inert_config_v1(GitObjectFormatV1::Sha1),
        encode_inert_config_v1(GitObjectFormatV1::Sha256)
    );
}

/// The shape rules hold byte for byte, and nothing behavior-affecting is in either encoding: no include,
/// remote, filter, hooks path, credential helper, alias, or any key beyond the documented ones.
#[test]
fn b1b_the_inert_config_has_only_the_documented_shape_and_no_behavior_keys() {
    for format in BOTH_FORMATS_V1 {
        let bytes = encode_inert_config_v1(format);
        let text = std::str::from_utf8(&bytes).expect("UTF-8");
        assert!(
            text.ends_with('\n') && !text.ends_with("\n\n"),
            "one trailing LF"
        );
        assert!(!bytes.contains(&b'\r'), "LF line ends only");
        let mut keys = Vec::new();
        for line in text.lines() {
            if line.starts_with('[') {
                assert!(line.ends_with(']'));
            } else {
                let rest = line.strip_prefix('\t').expect("a tab-indented key");
                assert!(!rest.starts_with(' ') && !rest.starts_with('\t'));
                let (key, value) = rest.split_once(" = ").expect("`key = value`");
                assert!(!key.is_empty() && !value.is_empty());
                assert!(!value.contains(' ') && !value.contains('\t'));
                keys.push(key.to_owned());
            }
        }
        let expected: &[&str] = match format {
            GitObjectFormatV1::Sha1 => &[
                "repositoryformatversion",
                "bare",
                "filemode",
                "logallrefupdates",
                "fsmonitor",
            ],
            GitObjectFormatV1::Sha256 => &[
                "repositoryformatversion",
                "bare",
                "filemode",
                "logallrefupdates",
                "fsmonitor",
                "objectformat",
            ],
        };
        assert_eq!(keys, expected, "{format:?}");
        let lowered = text.to_ascii_lowercase();
        for forbidden in [
            "include",
            "remote",
            "filter",
            "hookspath",
            "credential",
            "alias",
            "url",
            "pager",
            "editor",
            "sshcommand",
            "gpg",
            "diff",
            "merge",
            "worktree",
            "alternate",
            "core.fsmonitor = true",
        ] {
            assert!(
                !lowered.contains(forbidden),
                "{format:?} mentions {forbidden}"
            );
        }
    }
}

/// The golden bytes mean what they say to real Git: `git config --list` reads back exactly the
/// documented keys, and a repository whose config is replaced by them reports the right object format,
/// is not bare, and has its git directory where it was put. (Fixture plumbing, not the restore's effect
/// seam; the repository here is a scratch one.)
#[test]
fn b1b_real_git_reads_the_inert_config_back() {
    let git = |dir: &Path, args: &[&str]| -> String {
        let output = Command::new(lane_git_path())
            .env_clear()
            .env("PATH", "/usr/bin:/bin")
            .env("LC_ALL", "C")
            .env("HOME", "/nonexistent")
            .env("GIT_CONFIG_NOSYSTEM", "1")
            .env("GIT_CONFIG_GLOBAL", "/dev/null")
            .current_dir(dir)
            .args(args)
            .output()
            .expect("the fixture Git child runs");
        assert!(
            output.status.success(),
            "git {args:?}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8(output.stdout)
            .expect("UTF-8")
            .trim_end()
            .to_owned()
    };
    for (format, flag, listed, name) in [
        (
            GitObjectFormatV1::Sha1,
            "--object-format=sha1",
            "core.repositoryformatversion=0\ncore.bare=false\ncore.filemode=true\ncore.logallrefupdates=true\ncore.fsmonitor=false",
            "sha1",
        ),
        (
            GitObjectFormatV1::Sha256,
            "--object-format=sha256",
            "core.repositoryformatversion=1\ncore.bare=false\ncore.filemode=true\ncore.logallrefupdates=true\ncore.fsmonitor=false\nextensions.objectformat=sha256",
            "sha256",
        ),
    ] {
        let area = tempfile::TempDir::new().expect("a scratch area");
        let area_path = area.path().canonicalize().expect("a canonical area");
        let repository = area_path.join("repository");
        std::fs::create_dir(&repository).expect("the repository");
        git(&area_path, &["init", "--bare", "-q", "--template=", flag, "repository/.git"]);
        let config = repository.join(".git/config");
        std::fs::write(&config, encode_inert_config_v1(format)).expect("the encoded config");
        assert_eq!(git(&repository, &["config", "--file", ".git/config", "--list"]), listed);
        assert_eq!(git(&repository, &["rev-parse", "--show-object-format"]), name);
        assert_eq!(git(&repository, &["rev-parse", "--is-bare-repository"]), "false");
        assert_eq!(git(&repository, &["rev-parse", "--git-dir"]), ".git");
    }
}

// ---------------------------------------------------------------------------------------------
// The retained entry point: real phase-V values, real frames, the one capsule, ledger, and deadline
// ---------------------------------------------------------------------------------------------

/// The failure shape of the retained agreement is B1a's: no materialization began, the caller's
/// completed step and the one ledger's charge are carried.
fn agree_with(
    verified: &mut VerifiedCapsuleV1,
    plan: &ActiveFramePlanV1,
    format: GitObjectFormatV1,
    deadline: Instant,
    limits: RefsLimitsV1,
) -> Result<RefsAgreementV1, GitBootstrapErrorV1> {
    let ledger = ledger_used(verified);
    agree_active_refs_bounded_v1(
        verified,
        plan,
        format,
        frame_budget(),
        deadline,
        B1A_COMPLETED_V1,
        limits,
    )
    .map_err(|failure| require_failure_shape(failure, B1A_COMPLETED_V1, ledger))
}

fn agree(
    verified: &mut VerifiedCapsuleV1,
    plan: &ActiveFramePlanV1,
    format: GitObjectFormatV1,
) -> Result<RefsAgreementV1, GitBootstrapErrorV1> {
    agree_with(verified, plan, format, far_deadline(), RefsLimitsV1::v1())
}

/// The refs the manifest of `verified` lists, replaced on the retained value (as the frames are staged).
fn set_refs(verified: &mut VerifiedCapsuleV1, refs: Vec<CustodyOriginalRefV1>) {
    let base = &verified.control.manifest;
    verified.control.manifest = CustodyManifestV1::new(
        base.unit_id(),
        base.run_id(),
        base.materialization_id(),
        base.generation_id(),
        base.coverage().to_vec(),
        refs,
        base.original_objects().to_vec(),
        base.dependencies().to_vec(),
        base.exclusions().to_vec(),
    )
    .expect("a manifest with refs");
}

fn real_object(capsule: &CustomCapsuleV1, kind: KindV1) -> CustodyOriginalObjectV1 {
    capsule
        .source
        .objects
        .iter()
        .find(|object| object.kind() == kind)
        .expect("a real object of that kind")
        .clone()
}

fn direct_ref(name: &str, object: &CustodyOriginalObjectV1) -> CustodyOriginalRefV1 {
    CustodyOriginalRefV1::new(
        LosslessPathV1::from_bytes(name.as_bytes().to_vec()),
        CustodyRefTargetV1::Direct(object.clone()),
    )
    .expect("a manifest ref")
}

fn symbolic_ref(name: &str, target: &str) -> CustodyOriginalRefV1 {
    CustodyOriginalRefV1::new(
        LosslessPathV1::from_bytes(name.as_bytes().to_vec()),
        CustodyRefTargetV1::Symbolic(LosslessPathV1::from_bytes(target.as_bytes().to_vec())),
    )
    .expect("a manifest ref")
}

fn fb<'a>(path: &'static str, content: &'a [u8]) -> (&'a [u8], EntryV1<'a>) {
    (path.as_bytes(), EntryV1::File(content))
}

fn db(path: &'static str) -> (&'static [u8], EntryV1<'static>) {
    (path.as_bytes(), EntryV1::Dir)
}

/// The real state of a Captured capsule: an attached `HEAD` on a loose `refs/heads/main` (the real commit),
/// `ORIG_HEAD`, a packed `refs/heads/side` and `refs/tags/v1` (the real annotated tag, peeled to the
/// real commit), and a `logs/HEAD` and `logs/refs/heads/main` reflog.
struct RealStateV1 {
    refs_frame: Vec<u8>,
    logs_frame: Vec<u8>,
    manifest_refs: Vec<CustodyOriginalRefV1>,
}

fn real_state(capsule: &CustomCapsuleV1, format: GitObjectFormatV1) -> RealStateV1 {
    let generation = CaseV1::generation(capsule);
    let commit = real_object(capsule, KindV1::Commit);
    let tag = real_object(capsule, KindV1::Tag);
    let (commit_id, tag_id) = (commit.object_id().to_owned(), tag.object_id().to_owned());
    let loose = format!("{commit_id}\n");
    let packed_text = format!(
        "{PACKED_HEADER_V1}{commit_id} refs/heads/side\n{tag_id} refs/tags/v1\n^{commit_id}\n"
    );
    let zero = "0".repeat(oid_len(format));
    let log = format!("{zero} {commit_id} {IDENT_V1}\tbranch: Created from main\n");
    let refs_frame = encode_frame(
        REFS_V1,
        &generation,
        &[
            fb("HEAD", b"ref: refs/heads/main\n"),
            fb("ORIG_HEAD", loose.as_bytes()),
            fb("packed-refs", packed_text.as_bytes()),
            db("refs"),
            db("refs/heads"),
            fb("refs/heads/main", loose.as_bytes()),
            db("refs/tags"),
        ],
    );
    let logs_frame = encode_frame(
        LOGS_V1,
        &generation,
        &[
            db("logs"),
            fb("logs/HEAD", log.as_bytes()),
            db("logs/refs"),
            db("logs/refs/heads"),
            fb("logs/refs/heads/main", log.as_bytes()),
        ],
    );
    let manifest_refs = vec![
        symbolic_ref("HEAD", "refs/heads/main"),
        direct_ref("ORIG_HEAD", &commit),
        direct_ref("refs/heads/main", &commit),
        direct_ref("refs/heads/side", &commit),
        direct_ref("refs/tags/v1", &tag),
    ];
    RealStateV1 {
        refs_frame,
        logs_frame,
        manifest_refs,
    }
}

fn real_case(capsule: &CustomCapsuleV1, format: GitObjectFormatV1) -> CaseV1 {
    let state = real_state(capsule, format);
    let mut case = CaseV1::with_bytes(
        capsule,
        &[(REFS_V1, state.refs_frame), (LOGS_V1, state.logs_frame)],
    );
    set_refs(&mut case.verified, state.manifest_refs);
    case
}

/// Real SHA-1 and SHA-256 capsules (real Git objects, a real pack, a real phase-V value) carry the
/// real-shaped refs through the WHOLE chain: pass A's bootstrap proves the objects with real Git, B1a
/// prevalidates the frames and returns its plan, and B1b's agreement over those same retained
/// descriptors, the one ledger, and the one deadline accepts every manifest ref. B1b writes, charges, and
/// reserves nothing.
#[test]
fn b1b_real_objects_and_frames_agree_through_the_whole_chain_in_both_formats() {
    for cformat in [
        CustodyGitObjectFormatV1::Sha1,
        CustodyGitObjectFormatV1::Sha256,
    ] {
        let format = core_format(cformat);
        let capsule = captured(cformat);
        let CaseV1 { dest, verified } = real_case(&capsule, format);
        let mut boot = must_bootstrap(verified, format);
        assert_eq!(
            boot.provenance,
            GitFormatProvenanceV1::CapsuleObjectsAndPack
        );
        let plan = prevalidate(&mut boot.verified, far_deadline()).expect("B1a admits the frames");
        let ledger = ledger_used(&boot.verified);
        let tree = snapshot(&dest.path);

        let agreement = agree(&mut boot.verified, &plan, format)
            .unwrap_or_else(|error| panic!("{cformat:?}: {error:?}"));
        let commit = real_object(&capsule, KindV1::Commit).object_id().to_owned();
        assert_eq!(
            agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: Some(commit.clone()),
            }
        );
        assert_eq!(agreement.orig_head, Some(commit));
        assert_eq!(
            (
                agreement.loose_refs,
                agreement.packed_refs,
                agreement.peeled_rows,
                agreement.effective_refs,
                agreement.manifest_refs,
                agreement.reflog_files,
                agreement.reflog_rows,
                agreement.direct_targets,
            ),
            (1, 2, 1, 3, 5, 2, 2, 2),
            "{cformat:?}"
        );
        // Nothing was written, charged, or left mid-read.
        assert_eq!(ledger_used(&boot.verified), ledger, "{cformat:?}");
        assert_eq!(snapshot(&dest.path), tree, "{cformat:?}");
        assert_eq!(dest.entries(), [".restore-work"], "{cformat:?}");
        assert!(boot
            .verified
            .staged
            .iter()
            .filter(|one| matches!(one.role, CustodyCapsuleArtifactRoleV1::CoveragePayload(_)))
            .all(|one| position(one) == 0));
        // The same retained value agrees again, to the same result.
        assert_eq!(
            agree(&mut boot.verified, &plan, format).expect("a second agreement"),
            agreement
        );
    }
}

/// The success control: Empty objects (no pack, an empty inventory) with a Captured, valid, UNBORN HEAD
/// agree for BOTH caller formats, and the bootstrap reports caller-selected provenance.
#[test]
fn b1b_empty_objects_with_a_captured_unborn_head_agree_for_both_caller_formats() {
    for cformat in [
        CustodyGitObjectFormatV1::Sha1,
        CustodyGitObjectFormatV1::Sha256,
    ] {
        let format = core_format(cformat);
        let capsule = empty(cformat);
        let case = CaseV1::refs_only(&capsule, &[db("refs"), db("refs/heads"), db("refs/tags")]);
        let CaseV1 { dest, verified } = case;
        let mut boot = must_bootstrap(verified, format);
        assert_eq!(boot.provenance, GitFormatProvenanceV1::CallerSelectedEmpty);
        assert!(matches!(boot.objects, BootstrapObjectsV1::Empty));
        assert_eq!(boot.closure.inventory_objects, 0);
        let plan = prevalidate(&mut boot.verified, far_deadline()).expect("B1a admits the frame");
        let tree = snapshot(&dest.path);
        let agreement = agree(&mut boot.verified, &plan, format)
            .unwrap_or_else(|error| panic!("{cformat:?}: {error:?}"));
        assert_eq!(
            agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: None,
            }
        );
        assert_eq!(
            (
                agreement.effective_refs,
                agreement.direct_targets,
                agreement.manifest_refs
            ),
            (0, 0, 0)
        );
        assert_eq!(snapshot(&dest.path), tree);
        // With a manifest that lists the unborn HEAD, either way, it still agrees.
        for head in [
            symbolic_ref("HEAD", "refs/heads/main"),
            CustodyOriginalRefV1::new(
                LosslessPathV1::from_bytes(b"HEAD".to_vec()),
                CustodyRefTargetV1::Unborn,
            )
            .expect("an unborn ref"),
        ] {
            set_refs(&mut boot.verified, vec![head]);
            let agreement = agree(&mut boot.verified, &plan, format).expect("a listed unborn HEAD");
            assert_eq!(agreement.manifest_refs, 1);
        }
    }
}

/// An all-Empty capsule has no HEAD, so there is nothing to agree: an empty plan (what B1a would have
/// refused to produce) is the same typed refusal, and no HEAD is synthesized. A refs frame with a missing
/// plan entry, or only a reflog frame, is the same refusal.
#[test]
fn b1b_empty_refs_are_refused_and_no_head_is_synthesized() {
    let capsule = frames_capsule();
    let mut case = CaseV1::with_bytes(&capsule, &[]);
    let error =
        prevalidate(&mut case.verified, far_deadline()).expect_err("B1a refuses Empty refs");
    assert!(
        matches!(error, GitBootstrapErrorV1::EmptyRefsAndHead),
        "{error:?}"
    );
    let empty_plan = ActiveFramePlanV1 { frames: vec![] };
    let error =
        agree(&mut case.verified, &empty_plan, GitObjectFormatV1::Sha1).expect_err("no refs frame");
    assert!(
        matches!(error, GitBootstrapErrorV1::EmptyRefsAndHead),
        "{error:?}"
    );
    assert_eq!(case.dest.entries(), [".restore-work"]);

    // Reflogs alone: still no HEAD.
    let generation = CaseV1::generation(&capsule);
    let logs = encode_frame(LOGS_V1, &generation, &[db("logs")]);
    let mut case = CaseV1::with_bytes(&capsule, &[(LOGS_V1, logs)]);
    let error = prevalidate(&mut case.verified, far_deadline()).expect_err("B1a refuses");
    assert!(
        matches!(error, GitBootstrapErrorV1::EmptyRefsAndHead),
        "{error:?}"
    );
    let error =
        agree(&mut case.verified, &empty_plan, GitObjectFormatV1::Sha1).expect_err("no refs");
    assert!(
        matches!(error, GitBootstrapErrorV1::EmptyRefsAndHead),
        "{error:?}"
    );
}

/// The rich plan-backed capsule's REAL frames, as real Git wrote them (a clone with packed refs, a
/// symbolic `origin/HEAD`, a stash, `ORIG_HEAD` from an interrupted merge, and every reflog), agree. The
/// expected facts come from real Git against the real source repository: its ref list (name, object,
/// symbolic target) becomes the manifest's refs, and its HEAD must be the agreement's HEAD.
#[test]
fn b1b_the_rich_clones_real_frames_agree_with_real_git() {
    let fixture = PlanFixtureV1::rich_clone();
    let (manifest, capability, _receipts) = fixture.planned();
    let _ = expect_sealed(
        fixture
            .export(&manifest, capability)
            .expect("the rich export seals"),
    );
    // The fixture's source clone, beside its export scratch: `<area>/scratch/capsule`.
    let git_dir = fixture
        .capsule_dir()
        .parent()
        .and_then(Path::parent)
        .expect("the fixture area")
        .join("clone/.git");
    assert!(
        git_dir.join("HEAD").is_file(),
        "the source clone's git directory"
    );
    let (dest, mut verified) = phase_v(&fixture.capsule_dir());
    let plan = prevalidate(&mut verified, far_deadline()).expect("B1a admits the real frames");
    let format = GitObjectFormatV1::Sha1;

    // Without a manifest ref, every active target of the real repository is still checked.
    let bare = agree(&mut verified, &plan, format).expect("the real refs agree");
    assert!(
        verified
            .staged
            .iter()
            .filter(|one| matches!(one.role, CustodyCapsuleArtifactRoleV1::CoveragePayload(_)))
            .all(|one| position(one) == 0),
        "every active frame's descriptor is back at offset 0"
    );
    // Real Git's own view.
    let listing = plumb(
        &git_dir,
        &[
            "for-each-ref",
            "--format=%(refname)\t%(objectname)\t%(symref)",
        ],
        None,
    );
    let head_target = plumb(&git_dir, &["symbolic-ref", "HEAD"], None);
    let head_oid = plumb(&git_dir, &["rev-parse", "HEAD"], None);
    let refs: Vec<(String, String, String)> = listing
        .lines()
        .map(|line| {
            let mut fields = line.split('\t');
            (
                fields.next().expect("a name").to_owned(),
                fields.next().expect("an object").to_owned(),
                fields.next().unwrap_or("").to_owned(),
            )
        })
        .collect();
    assert!(
        refs.len() >= 5,
        "a clone with branches, remotes, and a stash: {refs:?}"
    );
    assert!(refs
        .iter()
        .any(|(name, _, symref)| name == "refs/stash" && symref.is_empty()));
    assert!(refs
        .iter()
        .any(|(name, _, symref)| name == "refs/remotes/origin/HEAD" && !symref.is_empty()));
    assert_eq!(bare.effective_refs, refs.len() as u64, "the real ref count");
    assert_eq!(
        bare.head,
        HeadStateV1::Symbolic {
            target: head_target.clone(),
            resolved: Some(head_oid.clone()),
        }
    );
    assert!(
        bare.orig_head.is_some(),
        "the interrupted merge left ORIG_HEAD"
    );
    assert!(bare.reflog_files >= 3, "{}", bare.reflog_files);
    assert!(bare.packed_refs > 0, "a clone packs its remote refs");

    // With the manifest listing EVERY real ref and HEAD, each is cross-checked by name and target.
    let objects = verified.control.manifest.original_objects().to_vec();
    let mut listed = vec![symbolic_ref("HEAD", &head_target)];
    for (name, oid, symref) in &refs {
        if symref.is_empty() {
            let object = objects
                .iter()
                .find(|object| object.object_id() == oid)
                .unwrap_or_else(|| panic!("{name} names {oid}, which the manifest lists"));
            listed.push(direct_ref(name, object));
        } else {
            listed.push(symbolic_ref(name, symref));
        }
    }
    set_refs(&mut verified, listed.clone());
    let full = agree(&mut verified, &plan, format).expect("every real ref agrees");
    assert_eq!(full.manifest_refs, listed.len() as u64);
    assert_eq!(full.head, bare.head);

    // A manifest that disagrees with real Git on ONE ref is refused by name.
    let (name, oid, _) = refs
        .iter()
        .find(|(name, _, symref)| name == "refs/heads/main" && symref.is_empty())
        .expect("the real main branch");
    let other = objects
        .iter()
        .find(|object| object.object_id() != oid && object.kind() == KindV1::Commit)
        .expect("another real commit");
    let mut wrong = listed.clone();
    wrong.retain(|record| record.name().as_bytes() != name.as_bytes());
    wrong.push(direct_ref(name, other));
    set_refs(&mut verified, wrong);
    assert_eq!(
        refs_fault(agree(&mut verified, &plan, format).expect_err("a wrong object")),
        RefsFaultV1::OriginalMismatch {
            name: name.clone(),
            expected: format!("direct {}", other.object_id()),
            found: format!("direct {oid}"),
        }
    );
    // And one that lists a ref the real repository never had.
    let mut ghost = listed;
    ghost.push(direct_ref("refs/heads/never-existed", other));
    set_refs(&mut verified, ghost);
    assert_eq!(
        refs_fault(agree(&mut verified, &plan, format).expect_err("a ghost ref")),
        RefsFaultV1::MissingOriginal {
            name: "refs/heads/never-existed".into()
        }
    );
    assert_eq!(dest.entries(), [".restore-work"]);

    // Retained descriptors are the only input: every staged leaf renamed away, then unlinked, still agrees.
    set_refs(&mut verified, Vec::new());
    let plain = dest.work().join("plain");
    for (relative, bytes) in snapshot(&plain) {
        if bytes.is_some() {
            let from = plain.join(&relative);
            let to = from.with_file_name(format!("moved-{}", relative.replace('/', "-")));
            std::fs::rename(&from, &to).expect("a staged leaf is renamed");
        }
    }
    assert_eq!(
        agree(&mut verified, &plan, format).expect("renamed leaves"),
        bare
    );
    for (relative, bytes) in snapshot(&plain) {
        if bytes.is_some() {
            std::fs::remove_file(plain.join(&relative)).expect("a staged leaf is unlinked");
        }
    }
    assert_eq!(
        agree(&mut verified, &plan, format).expect("unlinked leaves"),
        bare
    );
}

/// Prevalidates a case's frames, then returns its plan.
fn planned(case: &mut CaseV1) -> ActiveFramePlanV1 {
    prevalidate(&mut case.verified, far_deadline()).expect("B1a admits the frames")
}

/// A refusal in the retained agreement leaves no trace (the ledger, the whole destination tree, and the
/// directory listing are exactly what they were) and is in B1a's failure shape; a refused run still
/// reports the typed fault. One row per class of fault, each from a real frame beside real objects.
#[test]
fn b1b_retained_refusals_leave_no_trace_and_keep_the_failure_shape() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let format = GitObjectFormatV1::Sha1;
    let commit = real_object(&capsule, KindV1::Commit);
    let blob = real_object(&capsule, KindV1::Blob);
    let missing = "7".repeat(40);
    let generation = CaseV1::generation(&capsule);
    let bad_head = encode_frame(REFS_V1, &generation, &[fb("HEAD", b"not a ref\n")]);
    let blob_branch = format!("{}\n", blob.object_id());
    let kind_frame = encode_frame(
        REFS_V1,
        &generation,
        &[
            fb("HEAD", b"ref: refs/heads/main\n"),
            db("refs"),
            db("refs/heads"),
            fb("refs/heads/main", blob_branch.as_bytes()),
        ],
    );
    let absent = format!("{missing}\n");
    let absent_frame = encode_frame(
        REFS_V1,
        &generation,
        &[
            fb("HEAD", b"ref: refs/heads/main\n"),
            db("refs"),
            db("refs/heads"),
            fb("refs/heads/main", absent.as_bytes()),
        ],
    );
    let good = encode_frame(
        REFS_V1,
        &generation,
        &[
            fb("HEAD", b"ref: refs/heads/main\n"),
            db("refs"),
            db("refs/heads"),
        ],
    );
    let rows: Vec<(&str, Vec<u8>, Vec<CustodyOriginalRefV1>)> = vec![
        ("a malformed HEAD", bad_head, vec![]),
        ("a branch on a blob", kind_frame, vec![]),
        ("a target outside the inventory", absent_frame, vec![]),
        (
            "a manifest ref the frame lacks",
            good.clone(),
            vec![direct_ref("refs/heads/main", &commit)],
        ),
    ];
    for (row, frame, refs) in rows {
        let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, frame)]);
        set_refs(&mut case.verified, refs);
        let plan = planned(&mut case);
        let ledger = ledger_used(&case.verified);
        let tree = snapshot(&case.dest.path);
        let error = agree(&mut case.verified, &plan, format).expect_err(row);
        assert!(
            matches!(error, GitBootstrapErrorV1::Refs(_)),
            "{row}: {error:?}"
        );
        assert_eq!(ledger_used(&case.verified), ledger, "{row}: the ledger");
        assert_eq!(snapshot(&case.dest.path), tree, "{row}: a byte was written");
        assert_eq!(case.dest.entries(), [".restore-work"], "{row}");
    }
}

fn two_real_frames(capsule: &CustomCapsuleV1) -> CaseV1 {
    real_case(capsule, GitObjectFormatV1::Sha1)
}

/// The agreement reads exactly the frames B1a admitted: a plan that is not this capsule's is refused
/// before a frame is decoded, whatever is wrong with it: an entry digest, a count, a length, a digest, a
/// staged index, a class, the frame order, or a missing or extra frame.
#[test]
fn b1b_the_plan_binds_the_frames_the_agreement_reads() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let format = GitObjectFormatV1::Sha1;
    let mut case = two_real_frames(&capsule);
    let plan = planned(&mut case);
    assert_eq!(plan.frames.len(), 2);
    agree(&mut case.verified, &plan, format).expect("the untampered plan");

    type Edit = fn(&mut ActiveFramePlanV1);
    let edits: [(&str, Edit); 12] = [
        ("an entry digest", |plan| {
            plan.frames[0].entries_sha256[0] ^= 1
        }),
        ("the second frame's entry digest", |plan| {
            plan.frames[1].entries_sha256[31] ^= 1
        }),
        ("an entry count", |plan| plan.frames[0].entries += 1),
        ("a directory count", |plan| plan.frames[1].directories += 1),
        ("a file count", |plan| plan.frames[0].regular_files += 1),
        ("a content byte count", |plan| {
            plan.frames[0].content_bytes += 1
        }),
        ("a length", |plan| plan.frames[0].length += 1),
        ("a staged digest", |plan| plan.frames[1].sha256[0] ^= 1),
        ("a staged index", |plan| {
            plan.frames[0].staged = plan.frames[1].staged
        }),
        ("a swapped frame order", |plan| plan.frames.reverse()),
        ("a missing frame", |plan| {
            plan.frames.pop();
        }),
        ("an extra frame", |plan| {
            let extra = plan.frames[0].clone();
            plan.frames.push(extra);
        }),
    ];
    for (row, edit) in edits {
        let mut tampered = plan.clone();
        edit(&mut tampered);
        let ledger = ledger_used(&case.verified);
        let error = agree(&mut case.verified, &tampered, format).expect_err(row);
        assert!(
            matches!(error, GitBootstrapErrorV1::ActivePlanMismatch(_)),
            "{row}: {error:?}"
        );
        assert_eq!(ledger_used(&case.verified), ledger, "{row}");
    }
    // A plan whose class says something else than the staged role it points at.
    let mut tampered = plan.clone();
    tampered.frames[0].class = LOGS_V1;
    let error = agree(&mut case.verified, &tampered, format).expect_err("a wrong class");
    assert!(
        matches!(error, GitBootstrapErrorV1::ActivePlanMismatch(_)),
        "{error:?}"
    );
}

/// A staged frame that no longer is the verified plaintext is refused as THAT, ahead of whatever it says:
/// bytes changed or length changed after B1a (caught by the rehash), and a frame swapped for a well-formed
/// frame carrying a bad HEAD between the rehash and the decode (caught by binding the decoded bytes to the
/// verified digest: the content fault is held, and integrity outranks it).
#[test]
fn b1b_integrity_outranks_content_and_drift_is_refused() {
    use std::os::unix::fs::FileExt as _;
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let format = GitObjectFormatV1::Sha1;
    for (row, edit) in [
        (
            "a byte changed",
            (|file: &std::fs::File| file.write_all_at(&[0xff], 12).expect("change"))
                as fn(&std::fs::File),
        ),
        ("truncated", |file| {
            let length = file.metadata().expect("metadata").len();
            file.set_len(length - 1).expect("truncate");
        }),
        ("a byte appended", |file| {
            let length = file.metadata().expect("metadata").len();
            file.write_all_at(b"x", length).expect("append");
        }),
    ] {
        let mut case = two_real_frames(&capsule);
        let plan = planned(&mut case);
        let index = staged_index(&case.verified, REFS_V1);
        edit(&case.verified.staged[index].file);
        let name = lossy(case.verified.staged[index].name.as_bytes());
        let error = agree(&mut case.verified, &plan, format).expect_err(row);
        assert!(
            matches!(&error, GitBootstrapErrorV1::StagedInputChanged { name: found } if *found == name),
            "{row}: {error:?}"
        );
    }

    let generation = CaseV1::generation(&capsule);
    let good = encode_frame(
        REFS_V1,
        &generation,
        &[
            fb("HEAD", b"ref: refs/heads/main\n"),
            db("refs"),
            db("refs/heads"),
            db("refs/tags"),
        ],
    );
    let evil = encode_frame(REFS_V1, &generation, &[fb("HEAD", b"not a ref at all\n")]);
    assert!(evil.len() < good.len());
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, good)]);
    let plan = planned(&mut case);
    let handle = case.verified.staged[staged_index(&case.verified, REFS_V1)]
        .file
        .try_clone()
        .expect("a duplicate descriptor");
    let swapped = std::cell::Cell::new(false);
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        if event.label == "frame-rewind" && !swapped.replace(true) {
            handle.set_len(0).expect("empty the frame");
            handle.write_all_at(&evil, 0).expect("another frame");
        }
    });
    let error = agree(&mut case.verified, &plan, format).expect_err("a swapped frame");
    assert!(
        matches!(error, GitBootstrapErrorV1::StagedInputChanged { .. }),
        "the swapped frame's bad HEAD must not outrank its integrity: {error:?}"
    );

    // A frame swapped for one whose HEAD content is corrupt (its per-file digest no longer holds) fails
    // inside the content read: that is an invalid frame, never a refs fault and never a success.
    let generation = CaseV1::generation(&capsule);
    let good = encode_frame(
        REFS_V1,
        &generation,
        &[fb("HEAD", b"ref: refs/heads/main\n"), db("refs")],
    );
    let mut corrupt = good.clone();
    let at = corrupt
        .windows(5)
        .position(|window| window == b"ref: ")
        .expect("the HEAD content");
    corrupt[at + 6] ^= 0x01;
    assert_eq!(corrupt.len(), good.len());
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, good)]);
    let plan = planned(&mut case);
    let handle = case.verified.staged[staged_index(&case.verified, REFS_V1)]
        .file
        .try_clone()
        .expect("a duplicate descriptor");
    let swapped = std::cell::Cell::new(false);
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        if event.label == "frame-rewind" && !swapped.replace(true) {
            handle.write_all_at(&corrupt, 0).expect("a corrupt frame");
        }
    });
    let error = agree(&mut case.verified, &plan, format).expect_err("a corrupt frame");
    assert!(
        matches!(
            error,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid { class: REFS_V1 })
        ),
        "{error:?}"
    );
}

/// The retained agreement's guards: a clean two-frame run reads the clock at exactly the documented
/// guards in order (the shared rehash guards, then its own); each halts the run alone AT that guard with
/// nothing written; brief delays at every guard, with headroom, still succeed; a deadline already spent
/// refuses at the entry guard; and the deadline is observed before every decoded entry.
#[test]
fn b1b_the_retained_agreement_observes_the_one_deadline() {
    const CLEAN: [&str; 14] = [
        "refs-entry",
        "frame-rehash",
        "frame-rewind",
        "refs-decoded",
        "refs-rewound",
        "frame-rehash",
        "frame-rewind",
        "refs-decoded",
        "refs-rewound",
        "refs-structure",
        "refs-targets",
        "refs-resolved",
        "refs-manifest",
        "refs-final",
    ];
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let format = GitObjectFormatV1::Sha1;
    let fresh = || {
        let mut case = two_real_frames(&capsule);
        let plan = planned(&mut case);
        (case, plan)
    };
    let (mut case, plan) = fresh();
    let (labels, hook) = record_guards();
    agree(&mut case.verified, &plan, format).expect("a clean run");
    drop(hook);
    assert_eq!(*labels.borrow(), CLEAN);

    let mut distinct: Vec<&'static str> = Vec::new();
    for label in CLEAN {
        if !distinct.contains(&label) {
            distinct.push(label);
        }
    }
    for target in distinct {
        let (mut case, plan) = fresh();
        let deadline = Instant::now() + B1A_DEADLINE_V1;
        let labels = std::rc::Rc::new(std::cell::RefCell::new(Vec::<&'static str>::new()));
        let fired = std::rc::Rc::new(std::cell::Cell::new(false));
        let (seen, slow) = (labels.clone(), fired.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            seen.borrow_mut().push(event.label);
            if event.label == target && !slow.replace(true) {
                pass_the_deadline(deadline);
            }
        });
        let ledger = ledger_used(&case.verified);
        let tree = snapshot(&case.dest.path);
        let error = agree_with(
            &mut case.verified,
            &plan,
            format,
            deadline,
            RefsLimitsV1::v1(),
        )
        .expect_err(target);
        assert!(
            matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
            "{target}: {error:?}"
        );
        assert!(fired.get(), "{target}: the slow step never ran");
        assert_eq!(
            labels.borrow().last().copied(),
            Some(target),
            "{target}: the run halted AT its guard: {:?}",
            labels.borrow()
        );
        assert_eq!(ledger_used(&case.verified), ledger, "{target}");
        assert_eq!(snapshot(&case.dest.path), tree, "{target}");
    }

    let (mut case, plan) = fresh();
    {
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, |_| {
            std::thread::sleep(Duration::from_millis(40));
        });
        agree_with(
            &mut case.verified,
            &plan,
            format,
            Instant::now() + B1A_DEADLINE_V1,
            RefsLimitsV1::v1(),
        )
        .expect("fourteen brief delays leave most of the deadline");
    }

    // Spent: refused at the entry guard, no descriptor moved.
    let (mut case, plan) = fresh();
    for one in &case.verified.staged {
        use std::io::Seek as _;
        (&one.file)
            .seek(SeekFrom::Start(3))
            .expect("park the descriptor");
    }
    let spent = Instant::now();
    std::thread::sleep(Duration::from_millis(5));
    let (labels, hook) = record_guards();
    let error = agree_with(&mut case.verified, &plan, format, spent, RefsLimitsV1::v1())
        .expect_err("a spent deadline");
    drop(hook);
    assert!(
        matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
        "{error:?}"
    );
    assert_eq!(*labels.borrow(), ["refs-entry"]);
    assert!(case.verified.staged.iter().all(|one| position(one) == 3));
}

/// A deadline that passes while one entry is being read stops AT that entry (no later entry is decoded),
/// and a large reflog whose entry spends the deadline is not read past the one buffer the decoder had
/// already taken.
#[test]
fn b1b_the_retained_agreement_decodes_nothing_after_the_deadline() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let format = GitObjectFormatV1::Sha1;
    let generation = CaseV1::generation(&capsule);
    let commit = real_object(&capsule, KindV1::Commit);
    let branch = format!("{}\n", commit.object_id());
    let refs = encode_frame(
        REFS_V1,
        &generation,
        &[
            fb("HEAD", b"ref: refs/heads/a\n"),
            db("refs"),
            db("refs/heads"),
            fb("refs/heads/a", branch.as_bytes()),
            fb("refs/heads/b", branch.as_bytes()),
            fb("refs/heads/c", branch.as_bytes()),
        ],
    );
    // The deadline passes while a DIRECTORY entry is judged, where nothing is read from it: the loop's own
    // guard stops the decode at the next entry. Then while a regular file's entry is judged: the file's
    // admission refuses before its first read. Either way no later entry is decoded.
    for (spender, expected) in [
        ("refs/heads", &["HEAD", "refs", "refs/heads"][..]),
        (
            "refs/heads/a",
            &["HEAD", "refs", "refs/heads", "refs/heads/a"][..],
        ),
    ] {
        let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, refs.clone())]);
        let plan = planned(&mut case);
        let deadline = Instant::now() + B1A_DEADLINE_V1;
        let entries = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
        let seen = entries.clone();
        let hook = install_git_hook_for_test(GitHookPointV1::FrameEntry, move |event| {
            seen.borrow_mut()
                .push(event.path.to_string_lossy().into_owned());
            if event.path == Path::new(spender) {
                pass_the_deadline(deadline);
            }
        });
        let error = agree_with(
            &mut case.verified,
            &plan,
            format,
            deadline,
            RefsLimitsV1::v1(),
        )
        .expect_err("the deadline passed while judging an entry");
        assert!(
            matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
            "{spender}: {error:?}"
        );
        assert_eq!(
            *entries.borrow(),
            expected,
            "{spender}: no entry after the one that spent the deadline was decoded"
        );
        drop(hook);
    }

    // Reads are paced: a 300 KiB reflog whose entry spends the deadline is not read further.
    let zero = "0".repeat(40);
    let row = format!("{zero} {} {IDENT_V1}\tmessage\n", commit.object_id());
    let log = row.repeat(300 * 1024 / row.len() + 1);
    let logs = encode_frame(
        LOGS_V1,
        &generation,
        &[db("logs"), fb("logs/HEAD", log.as_bytes())],
    );
    let head_frame = encode_frame(
        REFS_V1,
        &generation,
        &[fb("HEAD", b"ref: refs/heads/main\n"), db("refs")],
    );
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, head_frame), (LOGS_V1, logs)]);
    let plan = planned(&mut case);
    let deadline = Instant::now() + B1A_DEADLINE_V1;
    let _hook = install_git_hook_for_test(GitHookPointV1::FrameEntry, move |event| {
        if event.path == Path::new("logs/HEAD") {
            pass_the_deadline(deadline);
        }
    });
    let error = agree_with(
        &mut case.verified,
        &plan,
        format,
        deadline,
        RefsLimitsV1::v1(),
    )
    .expect_err("the deadline passed before the log was read");
    assert!(
        matches!(error, GitBootstrapErrorV1::Git(CustodyGitError::Timeout)),
        "{error:?}"
    );
    let one = &case.verified.staged[staged_index(&case.verified, LOGS_V1)];
    assert!(one.length > 2 * HASH_BUFFER_BYTES_V1 as u64);
    assert!(
        position(one) <= HASH_BUFFER_BYTES_V1 as u64,
        "the decode read {} bytes of {}: past the deadline",
        position(one),
        one.length
    );
}

/// The limits apply through the retained entry point, with the failure shape and no trace: a FETCH_HEAD
/// larger than its cap, and every per-class cap lowered by one from what the real frames need.
#[test]
fn b1b_limits_apply_through_the_retained_entry_point() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let format = GitObjectFormatV1::Sha1;
    let generation = CaseV1::generation(&capsule);
    let commit = real_object(&capsule, KindV1::Commit);
    let row = format!(
        "{}\t\tbranch 'main' of https://example.invalid/repository\n",
        commit.object_id()
    );
    let limits = RefsLimitsV1::v1();
    let big = row.repeat((limits.fetch_head_bytes as usize / row.len()) + 2);
    assert!(big.len() as u64 > limits.fetch_head_bytes);
    let frame = encode_frame(
        REFS_V1,
        &generation,
        &[
            fb("HEAD", b"ref: refs/heads/main\n"),
            fb("FETCH_HEAD", big.as_bytes()),
        ],
    );
    let mut case = CaseV1::with_bytes(&capsule, &[(REFS_V1, frame)]);
    let plan = planned(&mut case);
    let ledger = ledger_used(&case.verified);
    let tree = snapshot(&case.dest.path);
    let error = agree(&mut case.verified, &plan, format).expect_err("a FETCH_HEAD past its cap");
    assert_eq!(
        refs_fault(error),
        limit_fault(RefsLimitKindV1::FetchHeadFile, limits.fetch_head_bytes)
    );
    assert_eq!(ledger_used(&case.verified), ledger);
    assert_eq!(snapshot(&case.dest.path), tree);

    // The real two-frame state needs these records; one fewer is refused through the same entry point.
    let mut case = two_real_frames(&capsule);
    let plan = planned(&mut case);
    let needed = 1 + 1 + 1 + 2 + 1 + 2; // HEAD, ORIG_HEAD, loose main, two packed rows, a peeled row, two reflogs
    for (bound, ok) in [(needed, true), (needed - 1, false)] {
        let outcome = agree_with(
            &mut case.verified,
            &plan,
            format,
            far_deadline(),
            limits_with(|limits| limits.entries = bound),
        );
        match (ok, outcome) {
            (true, Ok(_)) => {}
            (false, Err(error)) => assert_eq!(
                refs_fault(error),
                limit_fault(RefsLimitKindV1::Entries, bound)
            ),
            (ok, other) => panic!("{bound}: {ok}: {other:?}"),
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Structure: the agreement region is pure
// ---------------------------------------------------------------------------------------------

const B1B_MARKER_V1: &str = "// Pass B1b: pure refs agreement and inert config";

/// STRUCTURAL ONLY. B1b's region (the production source from its marker to B2a's marker) is pure: it opens
/// no path, walks nothing, writes nothing, charges and reserves nothing, runs no Git child and no process,
/// routes no object store, and has no unsafe. The marker is unique, follows B1a's region, and its region
/// holds the entry points; B1a's own read-only scan covers it too (it runs to B2a's marker). The
/// behavior is proven by the retained rows above, which leave the ledger and the destination unchanged.
#[test]
fn b1b_the_agreement_region_is_pure_and_the_split_is_unique() {
    let source = include_str!("custody_restore_git.rs");
    assert_eq!(source.matches(B1B_MARKER_V1).count(), 1, "one marker");
    assert_eq!(source.matches(B1A_MARKER_V1).count(), 1, "one B1a marker");
    let (before, region) = source.split_once(B1B_MARKER_V1).expect("the marker");
    // B2a's region, which creates and charges, is outside this pure scan; its own scan covers it.
    let (region, _later) = region
        .split_once(B2A_MARKER_V1)
        .expect("the B2a marker follows B1b's region");
    assert!(before.contains(B1A_MARKER_V1), "B1b follows B1a");
    assert!(before.contains("pub(crate) fn prevalidate_active_frames_v1("));
    assert!(region.contains("pub(crate) fn agree_active_refs_v1("));
    assert!(region.contains("pub(crate) fn encode_inert_config_v1("));
    assert!(
        !before.contains("agree_active_refs_v1(") && !before.contains("encode_inert_config_v1("),
        "the earlier passes do not call B1b"
    );
    let code: String = region
        .lines()
        .filter(|line| !line.trim_start().starts_with("//"))
        .collect::<Vec<_>>()
        .join("\n");
    // The one ledger is not touched here at all: B1b's failure reads its figure through B1a's helper.
    assert_eq!(
        code.matches(".ledger").count(),
        0,
        "no access to the ledger"
    );
    for forbidden in [
        "std::fs",
        "File::open(",
        "OpenOptions",
        "read_dir(",
        "create_new",
        "create_staging_directory",
        "write_all",
        "GitRunnerV1",
        "GitRunRequestV1",
        "GitCommandV1",
        "GitObjectStoreRouteV1",
        "object_store",
        "borrow_mut",
        "ReservedPairV1",
        "OwnedChargeV1",
        "ScratchLedgerV1",
        ".reserve(",
        ".release(",
        "roll_back",
        "unsafe",
        "\"repository\"",
        "remeasure_git_directory",
        "measure_git_directory",
        "walk",
        "Command",
        "spawn",
        "std::process",
        "mkdir",
        "rename",
        "remove_file",
        "set_len",
    ] {
        assert!(
            !code.contains(forbidden),
            "the pure region mentions `{forbidden}`"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Pass B2a: the create-new second object store
//
// Every row drives `materialize_object_store_v1` over a REAL retained value: a real phase-V capsule (real
// Git objects and a real pack with real active frames, or an Empty object database with a captured unborn
// HEAD), carried through pass A's real bootstrap (the first object store, proven by real Git) and B1a's real
// prevalidation. The helper takes no runner, so no Git child can run in it. Every row also proves the one
// ledger's conservation: what the helper reports charged is exactly what the ledger moved, on every outcome.
//
// Pass A's, B1a's, and B1b's controls above are unchanged, except the two structural scans' region ends
// (see `B2A_MARKER_V1`). The mutation matrix in `.git/a2a-evidence/2b3b-pass-b2a/` maps each guard to the
// rows that turn red without it.
// ---------------------------------------------------------------------------------------------

/// The step a flow that ran pass A has completed: B2a is called after it.
const B2A_COMPLETED_V1: Option<GitPlaneStepV1> = Some(GitPlaneStepV1::BootstrapGate);

const B2A_MARKER_V1: &str = "// Pass B2a: charged second object store";

/// The final hierarchy's directories, in creation order, by destination-relative name.
const SLOTS_V1: [&str; 5] = [
    "repository",
    "repository/.git",
    "repository/.git/objects",
    "repository/.git/objects/pack",
    "repository/.git/objects/info",
];

/// The three admitted files, in copy order.
const EXTENSIONS_V1: [&str; 3] = ["pack", "idx", "rev"];

/// A real phase-V value carried through pass A (the first object store, proven) and B1a (the active frames,
/// prevalidated): exactly what a later flow holds when it calls the second-store helper.
struct StoreCaseV1 {
    dest: DestV1,
    boot: VerifiedGitBootstrapV1,
    plan: ActiveFramePlanV1,
    format: GitObjectFormatV1,
    /// The one ledger's charge when phase V returned: before any bootstrap entry.
    phase_v_used: u64,
}

fn charge_of(charged: ObjectStoreChargeV1) -> u64 {
    charged.entries * ENTRY_V1 + charged.bytes
}

fn none_charged() -> ObjectStoreChargeV1 {
    ObjectStoreChargeV1::default()
}

impl StoreCaseV1 {
    fn of(capsule: &CustomCapsuleV1, cformat: CustodyGitObjectFormatV1) -> Self {
        let format = core_format(cformat);
        let CaseV1 { dest, verified } = if capsule.source.objects.is_empty() {
            CaseV1::refs_only(capsule, &[db("refs"), db("refs/heads"), db("refs/tags")])
        } else {
            real_case(capsule, format)
        };
        let phase_v_used = ledger_used(&verified);
        let mut boot = must_bootstrap(verified, format);
        let plan = prevalidate(&mut boot.verified, far_deadline()).expect("B1a admits the frames");
        Self {
            dest,
            boot,
            plan,
            format,
            phase_v_used,
        }
    }

    fn ledger(&self) -> u64 {
        ledger_used(&self.boot.verified)
    }

    /// The real entry point under `deadline`, with EVERY outcome held to the helper's contract: a success
    /// reports the completed step; a refusal carries the caller's completed step and the one ledger's
    /// charge; and the ledger moved by exactly what the helper reports it charged.
    fn attempt_by(
        &mut self,
        deadline: Instant,
    ) -> Result<FinalObjectStoreV1, Box<ObjectStoreFailureV1>> {
        let before = self.ledger();
        let result =
            materialize_object_store_v1(&self.boot, &self.plan, deadline, B2A_COMPLETED_V1);
        let moved = self.ledger() - before;
        match &result {
            Ok(done) => {
                assert_eq!(done.step, GitPlaneStepV1::Objects);
                assert_eq!(
                    moved,
                    charge_of(done.charged),
                    "the ledger moved as reported"
                );
            }
            Err(failure) => {
                assert_eq!(failure.last_completed, B2A_COMPLETED_V1);
                assert_eq!(failure.ledger_used, self.ledger(), "the failure's figure");
                assert_eq!(
                    moved,
                    charge_of(failure.partial.charged),
                    "{:?}: the ledger moved as reported",
                    failure.cause
                );
            }
        }
        result
    }

    fn attempt(&mut self) -> Result<FinalObjectStoreV1, Box<ObjectStoreFailureV1>> {
        self.attempt_by(far_deadline())
    }

    fn done(&mut self, row: &str) -> FinalObjectStoreV1 {
        match self.attempt() {
            Ok(done) => done,
            Err(failure) => panic!("{row}: must succeed: {:?}", failure.cause),
        }
    }

    fn refused(&mut self, row: &str) -> Box<ObjectStoreFailureV1> {
        match self.attempt() {
            Ok(_) => panic!("{row}: must refuse"),
            Err(failure) => failure,
        }
    }

    /// A refusal before any write: no active materialization began, nothing was created, pinned, or
    /// charged, and the destination tree and the one ledger are exactly what they were.
    fn refused_before_any_write(&mut self, row: &str) -> GitBootstrapErrorV1 {
        let tree = snapshot(&self.dest.path);
        let ledger = self.ledger();
        let failure = self.refused(row);
        assert!(
            !failure.active_materialization_began,
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(failure.partial.charged, none_charged(), "{row}");
        assert!(failure.partial.files.is_empty(), "{row}");
        assert!(failure.partial.in_flight.is_none(), "{row}");
        assert_eq!(pins_present(&failure.partial.pins), [false; 5], "{row}");
        assert_eq!(self.ledger(), ledger, "{row}: the ledger");
        assert_eq!(snapshot(&self.dest.path), tree, "{row}: a byte was written");
        assert_eq!(self.dest.entries(), [".restore-work"], "{row}");
        failure.cause
    }

    fn pack_hash(&self) -> String {
        match &self.boot.objects {
            BootstrapObjectsV1::Captured { pack_hash, .. } => pack_hash.clone(),
            BootstrapObjectsV1::Empty => panic!("an Empty capsule has no pack"),
        }
    }

    /// The three admitted files' lengths, in copy order, as the test's own measurement of the bootstrap.
    fn lengths(&self) -> [u64; 3] {
        let files = bootstrap_object_files(&self.dest);
        let mut lengths = [0_u64; 3];
        for (length, extension) in lengths.iter_mut().zip(EXTENSIONS_V1) {
            let suffix = format!(".{extension}");
            let found: Vec<&(String, Vec<u8>)> = files
                .iter()
                .filter(|(name, _)| name.ends_with(&suffix))
                .collect();
            assert_eq!(found.len(), 1, "exactly one .{extension}");
            *length = found[0].1.len() as u64;
        }
        lengths
    }

    /// Every created entry's destination-relative name, in the order the helper creates them.
    fn entry_names(&self) -> Vec<String> {
        let mut names: Vec<String> = SLOTS_V1.iter().map(|slot| (*slot).to_owned()).collect();
        if let BootstrapObjectsV1::Captured { pack_hash, .. } = &self.boot.objects {
            for extension in EXTENSIONS_V1 {
                names.push(format!(
                    "repository/.git/objects/pack/pack-{pack_hash}.{extension}"
                ));
            }
        }
        names
    }
}

fn pins_present(pins: &PartialObjectPinsV1) -> [bool; 5] {
    [
        pins.repository.is_some(),
        pins.git.is_some(),
        pins.objects.is_some(),
        pins.pack.is_some(),
        pins.info.is_some(),
    ]
}

/// The bootstrap's `objects/pack` files, by name, with their bytes, as the test reads them from disk.
fn bootstrap_object_files(dest: &DestV1) -> Vec<(String, Vec<u8>)> {
    files_in(&dest.bootstrap().join("objects/pack"))
}

fn files_in(directory: &Path) -> Vec<(String, Vec<u8>)> {
    let mut files: Vec<(String, Vec<u8>)> = std::fs::read_dir(directory)
        .expect("a listable directory")
        .map(|entry| {
            let path = entry.expect("an entry").path();
            (
                path.file_name()
                    .expect("a name")
                    .to_string_lossy()
                    .into_owned(),
                std::fs::read(&path).expect("a readable file"),
            )
        })
        .collect();
    files.sort();
    files
}

fn listing(directory: &Path) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(directory)
        .expect("a listable directory")
        .map(|entry| {
            entry
                .expect("an entry")
                .file_name()
                .to_string_lossy()
                .into_owned()
        })
        .collect();
    names.sort();
    names
}

fn exists(path: &Path) -> bool {
    std::fs::symlink_metadata(path).is_ok()
}

fn stored(dest: &DestV1, relative: &str) -> PathBuf {
    dest.path.join(relative)
}

fn pack_directory(dest: &DestV1) -> PathBuf {
    stored(dest, "repository/.git/objects/pack")
}

/// A pin is exactly the directory the path names: its canonical path, device, and inode.
fn assert_pin_is(pin: &PinnedDirectoryV1, path: &Path) {
    use std::os::unix::fs::MetadataExt as _;
    let metadata = std::fs::metadata(path).expect("the pinned directory");
    assert_eq!(pin.canonical_path(), path);
    assert_eq!(pin.identity().dev, Some(metadata.dev()), "{path:?}");
    assert_eq!(pin.identity().ino, Some(metadata.ino()), "{path:?}");
}

/// What the helper's partial facts say exists must be what is on disk: each slot's pin is present exactly
/// when its directory is there (and a pinned one always is), and the files on disk are the completed copies
/// and the one in flight, plus `unlisted` entries the facts cannot carry (an entry created and then refused
/// before its pin existed). Only for rows where nothing is planted at a slot.
fn assert_partial_is_the_disk(case: &StoreCaseV1, failure: &ObjectStoreFailureV1, unlisted: usize) {
    let present = pins_present(&failure.partial.pins);
    let mut on_disk = 0;
    for (slot, pinned) in SLOTS_V1.iter().zip(present) {
        let found = exists(&stored(&case.dest, slot));
        assert!(
            !pinned || found,
            "{slot}: a pin for a directory that is not there"
        );
        on_disk += usize::from(found);
    }
    let mut listed = present.iter().filter(|pinned| **pinned).count() + unlisted;
    let pack = pack_directory(&case.dest);
    if pack.is_dir() {
        let names = listing(&pack);
        on_disk += names.len();
        let relatives = failure
            .partial
            .files
            .iter()
            .map(|file| file.relative.as_str())
            .chain(
                failure
                    .partial
                    .in_flight
                    .iter()
                    .map(|flight| flight.relative.as_str()),
            );
        for relative in relatives {
            listed += 1;
            let leaf = relative.rsplit('/').next().expect("a leaf");
            assert!(
                names.iter().any(|name| name == leaf),
                "{relative}: listed but absent"
            );
        }
    }
    assert_eq!(on_disk, listed, "{:?}", failure.cause);
}

fn plant_one(case: &StoreCaseV1, slot: &str, kind: PlantV1, outside: &Path) -> GitSeamGuardV1 {
    let target = stored(&case.dest, slot);
    let outside = outside.to_path_buf();
    let planted = std::rc::Rc::new(std::cell::Cell::new(false));
    install_git_hook_for_test(GitHookPointV1::BeforeObjectCreate, move |event| {
        if event.path == target && !planted.replace(true) {
            plant(&target, kind, &outside);
        }
    })
}

/// Leaves exactly `headroom` bytes on the one ledger, by reserving the rest.
fn leave_headroom(verified: &VerifiedCapsuleV1, headroom: u64) {
    let used = ledger_used(verified);
    let filler = RESTORE_BYTES_CEILING_V1
        .checked_sub(used + headroom)
        .expect("room for the filler");
    verified
        .destination
        .ledger
        .borrow_mut()
        .reserve(filler)
        .expect("the filler fits");
}

fn captured_case(cformat: CustodyGitObjectFormatV1) -> (CustomCapsuleV1, StoreCaseV1) {
    let capsule = captured(cformat);
    let case = StoreCaseV1::of(&capsule, cformat);
    (capsule, case)
}

const BOTH_CAPSULE_FORMATS_V1: [CustodyGitObjectFormatV1; 2] = [
    CustodyGitObjectFormatV1::Sha1,
    CustodyGitObjectFormatV1::Sha256,
];

// ---------------------------------------------------------------------------------------------
// The exact second object store, and both stores' charges
// ---------------------------------------------------------------------------------------------

/// A Captured capsule in each caller format: the helper creates `repository/.git/objects/{pack,info}` and
/// copies exactly the three admitted files, byte for byte. The facts it retains are the created objects, and
/// the one ledger is charged for the second copy as well as the first.
#[test]
fn b2a_both_formats_copy_the_exact_pack_idx_and_rev_and_charge_both_stores() {
    use std::io::Seek as _;
    use std::os::unix::fs::MetadataExt as _;
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let row = format!("{cformat:?}");
        let (_capsule, mut case) = captured_case(cformat);
        assert_eq!(
            case.boot.provenance,
            GitFormatProvenanceV1::CapsuleObjectsAndPack
        );
        let work_before = snapshot(&case.dest.work());
        let first_store_bytes = tree_bytes(&case.dest.bootstrap());
        let ledger_after_bootstrap = case.ledger();
        let expected = bootstrap_object_files(&case.dest);
        assert_eq!(expected.len(), 3, "{row}");
        let lengths = case.lengths();
        let children = case.boot.runs.len();
        let hash = case.pack_hash();

        let done = case.done(&row);

        // The hierarchy: the repository's only child is `.git`, which holds only `objects`.
        assert_eq!(
            case.dest.entries(),
            [".restore-work", "repository"],
            "{row}"
        );
        let repository = stored(&case.dest, "repository");
        assert_eq!(listing(&repository), [".git"], "{row}");
        assert_eq!(listing(&repository.join(".git")), ["objects"], "{row}");
        assert_eq!(
            listing(&repository.join(".git/objects")),
            ["info", "pack"],
            "{row}"
        );
        assert!(listing(&repository.join(".git/objects/info")).is_empty());
        // Exactly the three admitted files, byte for byte.
        assert_eq!(files_in(&pack_directory(&case.dest)), expected, "{row}");

        // The retained facts: the files in copy order, each the created object.
        let relatives: Vec<&str> = done
            .files
            .iter()
            .map(|file| file.relative.as_str())
            .collect();
        assert_eq!(
            relatives,
            [
                format!("objects/pack/pack-{hash}.pack"),
                format!("objects/pack/pack-{hash}.idx"),
                format!("objects/pack/pack-{hash}.rev"),
            ],
            "{row}"
        );
        for (file, length) in done.files.iter().zip(lengths) {
            let name = file.relative.rsplit('/').next().expect("a leaf");
            let bytes = &expected
                .iter()
                .find(|(found, _)| found == name)
                .expect("an admitted file")
                .1;
            assert_eq!(file.length, length, "{row}: {name}");
            assert_eq!(file.sha256, sha256_bytes(bytes), "{row}: {name}");
            let metadata =
                std::fs::metadata(pack_directory(&case.dest).join(name)).expect("a copied file");
            assert_eq!(
                (file.dev, file.ino),
                (metadata.dev(), metadata.ino()),
                "{row}"
            );
            assert_eq!((&file.file).stream_position().expect("a position"), 0);
            let mut read = Vec::new();
            (&file.file)
                .read_to_end(&mut read)
                .expect("the retained descriptor reads");
            assert_eq!(&read, bytes, "{row}: {name}: the retained descriptor");
        }
        assert_pin_is(&done.pins.repository, &repository);
        assert_pin_is(&done.pins.git, &repository.join(".git"));
        assert_pin_is(&done.pins.objects, &repository.join(".git/objects"));
        assert_pin_is(&done.pins.pack, &repository.join(".git/objects/pack"));
        assert_pin_is(&done.pins.info, &repository.join(".git/objects/info"));

        // Both stores are charged: eight entries (five directories and three files) and the second copy's
        // bytes, on top of the bootstrap's own, which the helper never changes.
        let second_store_bytes = tree_bytes(&pack_directory(&case.dest));
        assert_eq!(second_store_bytes, lengths.iter().sum::<u64>(), "{row}");
        assert_eq!(
            done.charged,
            ObjectStoreChargeV1 {
                entries: 8,
                bytes: second_store_bytes
            },
            "{row}"
        );
        assert_eq!(
            case.ledger() - ledger_after_bootstrap,
            8 * ENTRY_V1 + second_store_bytes,
            "{row}"
        );
        assert_eq!(
            case.ledger() - case.phase_v_used,
            (2 + INIT_BARE_ENTRIES_V1 + INDEX_PACK_ENTRIES_V1 + 8) * ENTRY_V1
                + first_store_bytes
                + second_store_bytes,
            "{row}: HOME, XDG, the bootstrap, and the final store are all on the one ledger"
        );

        // The first store, the staging tree, and the staged descriptors are untouched, and no Git child ran.
        assert_eq!(snapshot(&case.dest.work()), work_before, "{row}");
        assert_eq!(case.boot.runs.len(), children, "{row}: no child ran");
        assert!(case
            .boot
            .verified
            .staged
            .iter()
            .all(|one| position(one) == 0));
    }
}

/// An Empty object database still creates the whole required hierarchy and copies no pack: five entries are
/// charged, the pack directory is empty, and the format is the caller's, for both caller formats.
#[test]
fn b2a_empty_objects_create_the_hierarchy_and_copy_no_pack_for_both_formats() {
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let row = format!("{cformat:?}");
        let capsule = empty(cformat);
        let mut case = StoreCaseV1::of(&capsule, cformat);
        assert_eq!(
            case.boot.provenance,
            GitFormatProvenanceV1::CallerSelectedEmpty
        );
        assert!(matches!(case.boot.objects, BootstrapObjectsV1::Empty));
        let work_before = snapshot(&case.dest.work());
        let ledger_after_bootstrap = case.ledger();
        let done = case.done(&row);

        assert!(done.files.is_empty(), "{row}");
        assert_eq!(
            done.charged,
            ObjectStoreChargeV1 {
                entries: 5,
                bytes: 0
            },
            "{row}"
        );
        assert_eq!(
            case.ledger() - ledger_after_bootstrap,
            5 * ENTRY_V1,
            "{row}"
        );
        let repository = stored(&case.dest, "repository");
        assert_eq!(listing(&repository), [".git"], "{row}");
        assert_eq!(listing(&repository.join(".git")), ["objects"], "{row}");
        assert_eq!(
            listing(&repository.join(".git/objects")),
            ["info", "pack"],
            "{row}"
        );
        assert!(listing(&pack_directory(&case.dest)).is_empty(), "{row}");
        assert!(listing(&repository.join(".git/objects/info")).is_empty());
        assert_pin_is(&done.pins.repository, &repository);
        assert_pin_is(&done.pins.git, &repository.join(".git"));
        assert_pin_is(&done.pins.objects, &repository.join(".git/objects"));
        assert_pin_is(&done.pins.pack, &repository.join(".git/objects/pack"));
        assert_pin_is(&done.pins.info, &repository.join(".git/objects/info"));
        assert_eq!(snapshot(&case.dest.work()), work_before, "{row}");
        assert_eq!(
            case.boot
                .runs
                .iter()
                .map(|run| run.label)
                .collect::<Vec<_>>(),
            [
                "init --bare",
                "cat-file --batch-all-objects",
                "fsck --strict"
            ],
            "{row}: no index, verify-pack, rev-list, or further child"
        );
    }
}

/// Only the three admitted regular files are streamed. Entries added to the bootstrap afterwards (a hook, a
/// `.keep`, an alternates file, a description) are never copied, the bootstrap's own HEAD and config never
/// reach the new store, and the bootstrap is byte-identical afterwards, planted entries included.
#[test]
fn b2a_no_bootstrap_head_config_hook_or_stray_file_is_copied() {
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let bootstrap = case.dest.bootstrap();
    let hash = case.pack_hash();
    std::fs::create_dir(bootstrap.join("hooks")).expect("a planted hooks directory");
    std::fs::write(bootstrap.join("hooks/pre-commit"), b"#!/bin/sh\nexit 1\n")
        .expect("a planted hook");
    std::fs::write(
        bootstrap.join(format!("objects/pack/pack-{hash}.keep")),
        b"keep",
    )
    .expect("a planted keep file");
    std::fs::write(bootstrap.join("objects/info/alternates"), b"/elsewhere\n")
        .expect("a planted alternates file");
    std::fs::write(bootstrap.join("description"), b"planted").expect("a planted description");
    let work_before = snapshot(&case.dest.work());

    let _ = case.done("stray entries");

    assert_eq!(snapshot(&case.dest.work()), work_before, "the bootstrap");
    let git = stored(&case.dest, "repository/.git");
    assert_eq!(listing(&git), ["objects"]);
    for forbidden in ["HEAD", "config", "hooks", "refs", "description", "info"] {
        assert!(!exists(&git.join(forbidden)), "{forbidden}");
    }
    assert!(
        listing(&git.join("objects/info")).is_empty(),
        "no alternates"
    );
    let names: Vec<String> = listing(&pack_directory(&case.dest));
    assert_eq!(names.len(), 3, "{names:?}");
    assert!(
        names.iter().all(|name| !name.ends_with(".keep")),
        "{names:?}"
    );
}

/// Pass A's no-repository invariant is function-scoped: direct bootstrap creates only `.restore-work/` (for
/// every capsule shape), and only this helper creates `repository/`.
#[test]
fn b2a_only_this_helper_creates_the_repository_and_direct_bootstrap_still_never_does() {
    for populated in [true, false] {
        let cformat = CustodyGitObjectFormatV1::Sha1;
        let capsule = if populated {
            captured(cformat)
        } else {
            empty(cformat)
        };
        let case = StoreCaseV1::of(&capsule, cformat);
        // Pass A and B1a have both run on this value, and nothing is under `repository/`.
        assert_eq!(case.dest.entries(), [".restore-work"], "{populated}");
        assert!(snapshot(&case.dest.path)
            .keys()
            .all(|name| !name.contains("repository")));
        let mut case = case;
        let _ = case.done("the helper");
        assert_eq!(
            case.dest.entries(),
            [".restore-work", "repository"],
            "{populated}"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Complete active prevalidation and a proven bootstrap come first
// ---------------------------------------------------------------------------------------------

/// Complete G needs a captured HEAD: an Empty `RefsAndHead` class is the typed pre-repository refusal, for
/// both caller formats and both object shapes, with a reflog-only capsule the same. Pass A accepts all of
/// them; the helper refuses before it creates, pins, or charges anything.
#[test]
fn b2a_empty_refs_refuse_before_the_repository_is_created_for_every_shape_and_format() {
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        for populated in [true, false] {
            let row = format!("{cformat:?} populated={populated}");
            let capsule = if populated {
                captured(cformat)
            } else {
                empty(cformat)
            };
            let format = core_format(cformat);
            // No active frame at all, and a reflog frame alone: neither carries a HEAD.
            let generation = CaseV1::generation(&capsule);
            let logs = encode_frame(LOGS_V1, &generation, &[db("logs")]);
            for (shape, frames) in [
                ("no frame", vec![]),
                ("reflogs only", vec![(LOGS_V1, logs)]),
            ] {
                let CaseV1 { dest, verified } = CaseV1::with_bytes(&capsule, &frames);
                let boot = must_bootstrap(verified, format);
                // B1a would refuse to produce a plan; the hand-built plan stands where one would be.
                let plan = ActiveFramePlanV1 {
                    frames: boot
                        .verified
                        .staged
                        .iter()
                        .enumerate()
                        .filter(|(_, one)| {
                            one.role == CustodyCapsuleArtifactRoleV1::CoveragePayload(LOGS_V1)
                        })
                        .map(|(staged, one)| ActiveFrameSummaryV1 {
                            class: LOGS_V1,
                            staged,
                            length: one.length,
                            sha256: one.sha256,
                            entries: 1,
                            directories: 1,
                            regular_files: 0,
                            content_bytes: 0,
                            entries_sha256: [0; 32],
                        })
                        .collect(),
                };
                let tree = snapshot(&dest.path);
                let ledger = ledger_used(&boot.verified);
                let failure =
                    materialize_object_store_v1(&boot, &plan, far_deadline(), B2A_COMPLETED_V1)
                        .expect_err(&format!("{row} {shape}"));
                assert!(
                    matches!(failure.cause, GitBootstrapErrorV1::EmptyRefsAndHead),
                    "{row} {shape}: {:?}",
                    failure.cause
                );
                assert!(!failure.active_materialization_began, "{row} {shape}");
                assert_eq!(failure.last_completed, B2A_COMPLETED_V1, "{row} {shape}");
                assert_eq!(failure.ledger_used, ledger, "{row} {shape}");
                assert_eq!(failure.partial.charged, none_charged(), "{row} {shape}");
                assert_eq!(pins_present(&failure.partial.pins), [false; 5]);
                assert!(failure.partial.files.is_empty());
                assert_eq!(ledger_used(&boot.verified), ledger, "{row} {shape}");
                assert_eq!(snapshot(&dest.path), tree, "{row} {shape}");
                assert_eq!(dest.entries(), [".restore-work"], "{row} {shape}");
            }
        }
    }
}

/// A plan that is not this capsule's active frames is refused before any write: reordered, short, extra,
/// pointing at another payload or class, or carrying another length or digest than the verified one. The
/// control with the real plan then succeeds on the same untouched value.
#[test]
fn b2a_a_plan_that_is_not_this_capsules_refuses_before_any_write() {
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    type EditV1 = fn(&mut ActiveFramePlanV1);
    let rows: [(&str, EditV1); 8] = [
        ("reversed", |plan| plan.frames.reverse()),
        ("without the logs frame", |plan| {
            plan.frames.pop();
        }),
        ("without the refs frame", |plan| {
            plan.frames.remove(0);
        }),
        ("an extra frame", |plan| {
            let again = plan.frames[0].clone();
            plan.frames.push(again);
        }),
        ("another staged payload", |plan| plan.frames[0].staged += 1),
        ("another class", |plan| plan.frames[0].class = LOGS_V1),
        ("another length", |plan| plan.frames[1].length += 1),
        ("another digest", |plan| plan.frames[0].sha256[0] ^= 1),
    ];
    for (row, edit) in rows {
        let original = case.plan.clone();
        edit(&mut case.plan);
        let cause = case.refused_before_any_write(row);
        assert!(
            matches!(cause, GitBootstrapErrorV1::ActivePlanMismatch(_)),
            "{row}: {cause:?}"
        );
        case.plan = original;
    }
    let _ = case.done("the real plan");
}

fn refused_while_tampered(
    case: &mut StoreCaseV1,
    row: &str,
    tamper: impl FnOnce(&mut VerifiedGitBootstrapV1) -> Box<dyn FnOnce(&mut VerifiedGitBootstrapV1)>,
) -> GitBootstrapErrorV1 {
    let undo = tamper(&mut case.boot);
    let cause = case.refused_before_any_write(row);
    undo(&mut case.boot);
    cause
}

fn pack_hash_mut(boot: &mut VerifiedGitBootstrapV1) -> &mut String {
    match &mut boot.objects {
        BootstrapObjectsV1::Captured { pack_hash, .. } => pack_hash,
        BootstrapObjectsV1::Empty => panic!("a Captured bootstrap"),
    }
}

fn admitted_mut(boot: &mut VerifiedGitBootstrapV1) -> &mut Vec<AdmittedObjectFileV1> {
    match &mut boot.objects {
        BootstrapObjectsV1::Captured { files, .. } => files,
        BootstrapObjectsV1::Empty => panic!("a Captured bootstrap"),
    }
}

/// Only a proven bootstrap is copied: closure evidence that is incomplete or contradicts the manifest, the
/// objects, or the provenance; a pack name that is not the admitted hash (a path, the wrong width, upper
/// case); files that are not the three admitted ones in order; a retained descriptor that is not the admitted
/// file; or a bootstrap whose pack directory is not retained. Each refuses before any write, and the
/// untampered control then succeeds on the same value.
#[test]
fn b2a_an_unproven_bootstrap_refuses_before_any_write() {
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let input = |cause: GitBootstrapErrorV1, row: &str| {
        assert!(
            matches!(cause, GitBootstrapErrorV1::ObjectStoreInput(_)),
            "{row}: {cause:?}"
        );
    };

    let cause = refused_while_tampered(&mut case, "no strict fsck", |boot| {
        let saved = boot.closure;
        boot.closure.fsck_strict = false;
        Box::new(move |boot| boot.closure = saved)
    });
    input(cause, "no strict fsck");

    let cause = refused_while_tampered(&mut case, "another inventory size", |boot| {
        let saved = boot.closure;
        boot.closure.inventory_objects += 1;
        Box::new(move |boot| boot.closure = saved)
    });
    input(cause, "another inventory size");

    let cause = refused_while_tampered(&mut case, "a vacuous closure for a pack", |boot| {
        let saved = boot.closure;
        boot.closure.closure = GitClosureProofV1::Vacuous;
        Box::new(move |boot| boot.closure = saved)
    });
    input(cause, "a vacuous closure for a pack");

    let cause = refused_while_tampered(&mut case, "another reachable count", |boot| {
        let saved = boot.closure;
        boot.closure.closure = GitClosureProofV1::Reachable { objects: 5 };
        Box::new(move |boot| boot.closure = saved)
    });
    input(cause, "another reachable count");

    let cause =
        refused_while_tampered(&mut case, "caller-selected provenance for a pack", |boot| {
            let saved = boot.provenance;
            boot.provenance = GitFormatProvenanceV1::CallerSelectedEmpty;
            Box::new(move |boot| boot.provenance = saved)
        });
    input(cause, "caller-selected provenance for a pack");

    let cause =
        refused_while_tampered(&mut case, "Empty objects for a Captured manifest", |boot| {
            let saved = std::mem::replace(&mut boot.objects, BootstrapObjectsV1::Empty);
            Box::new(move |boot| boot.objects = saved)
        });
    input(cause, "Empty objects for a Captured manifest");

    for (row, replacement) in [
        ("a path in the pack name", "../escape".to_owned()),
        ("a pack name of the wrong width", "ab".repeat(32)),
        ("an upper-case pack name", "AB".repeat(20)),
        ("an empty pack name", String::new()),
    ] {
        let cause = refused_while_tampered(&mut case, row, |boot| {
            let saved = std::mem::replace(pack_hash_mut(boot), replacement);
            Box::new(move |boot| *pack_hash_mut(boot) = saved)
        });
        input(cause, row);
    }

    // A pack name that is a path or upper case, with the three files' names changed to match: only the
    // object-id rule refuses it.
    for (row, replacement) in [
        (
            "a path in the pack name and the file names",
            "../escape".to_owned(),
        ),
        ("an upper-case pack name and file names", "AB".repeat(20)),
    ] {
        let cause = refused_while_tampered(&mut case, row, |boot| {
            let saved = std::mem::replace(pack_hash_mut(boot), replacement.clone());
            let originals: Vec<String> = admitted_mut(boot)
                .iter()
                .map(|file| file.relative.clone())
                .collect();
            for (file, extension) in admitted_mut(boot).iter_mut().zip(EXTENSIONS_V1) {
                file.relative = format!("objects/pack/pack-{replacement}.{extension}");
            }
            Box::new(move |boot| {
                *pack_hash_mut(boot) = saved;
                for (file, original) in admitted_mut(boot).iter_mut().zip(originals) {
                    file.relative = original;
                }
            })
        });
        input(cause, row);
    }

    // A Captured bootstrap over a manifest whose object database row is Empty: the coverage must agree.
    let cause = refused_while_tampered(
        &mut case,
        "a Captured bootstrap over an Empty row",
        |boot| {
            let emptied = manifest_with_row(
                CustodyCoverageClassV1::ObjectDatabase,
                CustodyStateClassV1::Empty,
                &boot.verified,
            );
            let saved = std::mem::replace(&mut boot.verified.control.manifest, emptied);
            Box::new(move |boot| boot.verified.control.manifest = saved)
        },
    );
    input(cause, "a Captured bootstrap over an Empty row");

    // The Empty arm: Empty objects, caller-selected provenance, a vacuous closure, and an Empty coverage
    // row, over a manifest that nevertheless lists objects.
    let cause = refused_while_tampered(&mut case, "an Empty database that lists objects", |boot| {
        let emptied = manifest_with_row(
            CustodyCoverageClassV1::ObjectDatabase,
            CustodyStateClassV1::Empty,
            &boot.verified,
        );
        let saved_manifest = std::mem::replace(&mut boot.verified.control.manifest, emptied);
        let saved_objects = std::mem::replace(&mut boot.objects, BootstrapObjectsV1::Empty);
        let saved_provenance = boot.provenance;
        let saved_closure = boot.closure;
        boot.provenance = GitFormatProvenanceV1::CallerSelectedEmpty;
        boot.closure.closure = GitClosureProofV1::Vacuous;
        Box::new(move |boot| {
            boot.verified.control.manifest = saved_manifest;
            boot.objects = saved_objects;
            boot.provenance = saved_provenance;
            boot.closure = saved_closure;
        })
    });
    input(cause, "an Empty database that lists objects");

    let cause = refused_while_tampered(&mut case, "files out of order", |boot| {
        admitted_mut(boot).swap(0, 1);
        Box::new(|boot| admitted_mut(boot).swap(0, 1))
    });
    input(cause, "files out of order");

    let cause = refused_while_tampered(&mut case, "a missing file", |boot| {
        let last = admitted_mut(boot).pop().expect("three files");
        Box::new(move |boot| admitted_mut(boot).push(last))
    });
    input(cause, "a missing file");

    let cause = refused_while_tampered(&mut case, "a renamed file", |boot| {
        let saved = std::mem::replace(
            &mut admitted_mut(boot)[0].relative,
            "objects/pack/other.pack".to_owned(),
        );
        Box::new(move |boot| admitted_mut(boot)[0].relative = saved)
    });
    input(cause, "a renamed file");

    let cause = refused_while_tampered(&mut case, "the other object format", |boot| {
        let saved = boot.object_format;
        boot.object_format = GitObjectFormatV1::Sha256;
        Box::new(move |boot| boot.object_format = saved)
    });
    input(cause, "the other object format");

    let cause = refused_while_tampered(&mut case, "no retained active frames", |boot| {
        let saved = std::mem::take(&mut boot.active_frames);
        Box::new(move |boot| boot.active_frames = saved)
    });
    input(cause, "no retained active frames");

    let cause = refused_while_tampered(&mut case, "no retained pack directory", |boot| {
        let saved = boot
            .directories
            .remove("objects/pack")
            .expect("the pack directory");
        Box::new(move |boot| {
            boot.directories.insert("objects/pack".to_owned(), saved);
        })
    });
    input(cause, "no retained pack directory");

    // A retained descriptor that is not the admitted file: another length.
    let cause = refused_while_tampered(&mut case, "another descriptor", |boot| {
        let mut other = tempfile::tempfile().expect("another file");
        use std::io::Write as _;
        other.write_all(b"not the admitted bytes").expect("bytes");
        let saved = std::mem::replace(&mut admitted_mut(boot)[0].file, other);
        Box::new(move |boot| admitted_mut(boot)[0].file = saved)
    });
    assert!(
        matches!(
            cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::IdentityChanged(_))
        ),
        "another descriptor: {cause:?}"
    );

    let _ = case.done("the untampered value");
}

// ---------------------------------------------------------------------------------------------
// Preexisting entries are collisions, and the ledger is released once and only for what was never created
// ---------------------------------------------------------------------------------------------

/// A preplanted file, empty directory, or symlink at each of the eight entries the helper creates (the five
/// directories and the three object files) is a collision: the planted entry is left exactly as it was and
/// nothing is written through it, the entry that was never created is given back to the ledger and nothing
/// else is, and the facts name exactly what this invocation did create before it.
#[test]
fn b2a_preexisting_slots_are_collisions_and_stay_unchanged() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let names = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1).entry_names();
    assert_eq!(names.len(), 8);
    for (index, slot) in names.iter().enumerate() {
        for kind in [
            PlantV1::RegularFile,
            PlantV1::EmptyDirectory,
            PlantV1::Symlink,
        ] {
            let row = format!("{slot} {kind:?}");
            let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            assert_eq!(
                &case.entry_names(),
                &names,
                "the same names for the same capsule"
            );
            let lengths = case.lengths();
            let (_outside_area, outside) = external_dir_with(&["decoy"]);
            let outside_before = snapshot(&outside);
            let _hook = plant_one(&case, slot, kind, &outside);

            let failure = case.refused(&row);
            assert!(
                matches!(&failure.cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { name })
                        if name == slot),
                "{row}: {:?}",
                failure.cause
            );
            // Active materialization began exactly when an earlier entry had been created.
            assert_eq!(failure.active_materialization_began, index > 0, "{row}");
            // The facts: the earlier directories are pinned, the earlier files complete, nothing in flight.
            let expected_pins: Vec<bool> = (0..5).map(|slot_index| slot_index < index).collect();
            assert_eq!(
                pins_present(&failure.partial.pins).to_vec(),
                expected_pins,
                "{row}"
            );
            let complete = index.saturating_sub(5);
            assert_eq!(failure.partial.files.len(), complete, "{row}");
            assert!(failure.partial.in_flight.is_none(), "{row}");
            // The refused entry's allowance went back; everything created before it stays charged.
            assert_eq!(
                failure.partial.charged,
                ObjectStoreChargeV1 {
                    entries: index as u64,
                    bytes: lengths[..complete].iter().sum(),
                },
                "{row}"
            );
            // Earlier entries exist; later ones do not; the planted entry is untouched.
            let target = stored(&case.dest, slot);
            for (later, name) in names.iter().enumerate() {
                let path = stored(&case.dest, name);
                if later < index {
                    assert!(
                        exists(&path),
                        "{row}: {name} was created before the collision"
                    );
                } else if later > index {
                    assert!(
                        !exists(&path),
                        "{row}: {name} was created after the collision"
                    );
                }
            }
            match kind {
                PlantV1::RegularFile => {
                    assert_eq!(
                        std::fs::read(&target).expect("planted"),
                        b"planted",
                        "{row}"
                    );
                }
                PlantV1::EmptyDirectory => {
                    assert!(
                        listing(&target).is_empty(),
                        "{row}: something was written inside"
                    );
                }
                PlantV1::Symlink => {
                    assert_eq!(
                        std::fs::read_link(&target).expect("a link"),
                        outside,
                        "{row}"
                    );
                    assert_eq!(snapshot(&outside), outside_before, "{row}: written through");
                }
            }
        }
    }
}

/// A refused invocation leaves every created byte, and a second invocation over the same retained value
/// (after a success, and after a partial failure) refuses at `repository` as a collision: it overwrites
/// nothing, and its own reservation is given back.
#[test]
fn b2a_a_second_invocation_refuses_and_cannot_overwrite_the_first_partial_state() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);

    // After a success.
    let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let _ = case.done("the first invocation");
    let after_first = snapshot(&case.dest.path);
    let ledger = case.ledger();
    let failure = case.refused("the second invocation");
    assert!(
        matches!(&failure.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { name })
                if name == "repository"),
        "{:?}",
        failure.cause
    );
    assert!(!failure.active_materialization_began, "it created nothing");
    assert_eq!(failure.partial.charged, none_charged());
    assert_eq!(case.ledger(), ledger, "the second reservation was released");
    assert_eq!(snapshot(&case.dest.path), after_first, "byte-identical");

    // After a partial failure: the `.idx` copy was refused after its file was created.
    let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let idx = case.entry_names()[6].clone();
    let _device = override_created_dev_for_test(&idx, device_of(&case.dest.path) + 1);
    let first = case.refused("the first invocation");
    assert!(
        matches!(
            first.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::DeviceCrossing { .. })
        ),
        "{:?}",
        first.cause
    );
    assert!(first.active_materialization_began);
    let after_first = snapshot(&case.dest.path);
    let ledger = case.ledger();
    let second = case.refused("the second invocation");
    assert!(
        matches!(&second.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { name })
                if name == "repository"),
        "{:?}",
        second.cause
    );
    assert!(!second.active_materialization_began);
    assert_eq!(case.ledger(), ledger);
    assert_eq!(
        snapshot(&case.dest.path),
        after_first,
        "the partial state is byte-identical"
    );
}

// ---------------------------------------------------------------------------------------------
// Entry and byte exhaustion are exact
// ---------------------------------------------------------------------------------------------

/// The bound is exact at every entry and every byte: with one byte less than an entry needs, the entry is
/// refused and not created; the headroom of exactly the whole charge succeeds. Everything created before the
/// refusal stays, charged, and the facts say so.
#[test]
fn b2a_entry_and_byte_exhaustion_is_exact_and_leaves_typed_partial_effects() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let lengths = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1).lengths();
    let total_bytes: u64 = lengths.iter().sum();

    // The exact fit succeeds.
    let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    leave_headroom(&case.boot.verified, 8 * ENTRY_V1 + total_bytes);
    let done = case.done("the exact fit");
    assert_eq!(
        case.ledger(),
        RESTORE_BYTES_CEILING_V1,
        "the ledger is exactly full"
    );
    assert_eq!(charge_of(done.charged), 8 * ENTRY_V1 + total_bytes);

    // One byte short of an ENTRY, at each of the eight entries.
    for index in 0..8_usize {
        let row = format!("entry {index}");
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let complete = index.saturating_sub(5);
        let bytes_before: u64 = lengths[..complete].iter().sum();
        leave_headroom(
            &case.boot.verified,
            index as u64 * ENTRY_V1 + bytes_before + (ENTRY_V1 - 1),
        );
        let failure = case.refused(&row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Budget(_))
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(failure.active_materialization_began, index > 0, "{row}");
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: index as u64,
                bytes: bytes_before
            },
            "{row}"
        );
        assert_eq!(failure.partial.files.len(), complete, "{row}");
        assert!(failure.partial.in_flight.is_none(), "{row}");
        assert_partial_is_the_disk(&case, &failure, 0);
        // The entry that was refused was not created.
        let names = case.entry_names();
        assert!(!exists(&stored(&case.dest, &names[index])), "{row}");
    }

    // One byte short of a FILE's bytes: its entry exists, empty or partly written, and stays charged.
    for chunk in [None, Some(16_usize)] {
        for file in 0..3_usize {
            let row = format!("bytes of file {file} chunk {chunk:?}");
            let _chunk = chunk.map(override_object_copy_chunk_for_test);
            let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            let bytes_before: u64 = lengths[..file].iter().sum();
            let length = lengths[file];
            leave_headroom(
                &case.boot.verified,
                (6 + file as u64) * ENTRY_V1 + bytes_before + length - 1,
            );
            let failure = case.refused(&row);
            assert!(
                matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Budget(_))
                ),
                "{row}: {:?}",
                failure.cause
            );
            assert!(failure.active_materialization_began, "{row}");
            // The refused chunk is the last one: it is never written.
            let last = chunk.map_or(length, |size| ((length - 1) % size as u64) + 1);
            let written = length - last;
            let flight = failure
                .partial
                .in_flight
                .as_ref()
                .expect("the file in flight");
            assert_eq!(
                (flight.expected_length, flight.written),
                (length, written),
                "{row}"
            );
            assert_eq!(
                failure.partial.charged,
                ObjectStoreChargeV1 {
                    entries: 6 + file as u64,
                    bytes: bytes_before + written
                },
                "{row}"
            );
            assert_eq!(failure.partial.files.len(), file, "{row}");
            // The partial bytes are on disk, exactly what was charged, and are a prefix of the original.
            let leaf = flight.relative.rsplit('/').next().expect("a leaf");
            let copied = std::fs::read(pack_directory(&case.dest).join(leaf)).expect("the file");
            let original = std::fs::read(case.dest.bootstrap().join(&flight.relative))
                .expect("the bootstrap file");
            assert_eq!(copied.len() as u64, written, "{row}");
            assert_eq!(&original[..copied.len()], &copied[..], "{row}");
            assert_partial_is_the_disk(&case, &failure, 0);
        }
    }
}

// ---------------------------------------------------------------------------------------------
// The retained bootstrap files are what is copied
// ---------------------------------------------------------------------------------------------

/// An admitted bootstrap file that is replaced, swapped for a link, or changed before the copy is refused
/// before any write, and the replacement is never followed or read: a symlink to a copy of the bytes, a new
/// inode holding the same bytes, and an appended byte (the retained descriptor's own length no longer the
/// admitted one).
#[test]
fn b2a_a_replaced_or_changed_bootstrap_object_file_refuses_before_any_write() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for extension in EXTENSIONS_V1 {
        for action in ["symlink", "a new inode", "an appended byte"] {
            let row = format!("{extension}: {action}");
            let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            let path = admitted_path(&case.dest.bootstrap(), extension);
            let original = std::fs::read(&path).expect("the admitted file");
            let (_outside_area, outside) = external_dir_with(&["decoy"]);
            let outside_before = snapshot(&outside);
            match action {
                "symlink" => {
                    let copy = outside.join("copy");
                    std::fs::write(&copy, &original).expect("a copy elsewhere");
                    std::fs::remove_file(&path).expect("the file goes");
                    std::os::unix::fs::symlink(&copy, &path).expect("a link in its place");
                }
                "a new inode" => {
                    std::fs::rename(&path, path.with_extension("moved")).expect("moved away");
                    std::fs::write(&path, &original).expect("the same bytes, a new inode");
                }
                _ => append_fixture_byte(&path),
            }
            let outside_planted = snapshot(&outside);
            let cause = case.refused_before_any_write(&row);
            let accepted = match action {
                "symlink" => matches!(
                    cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. })
                ),
                _ => matches!(
                    cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::IdentityChanged(_))
                ),
            };
            assert!(accepted, "{row}: {cause:?}");
            assert_eq!(
                snapshot(&outside),
                outside_planted,
                "{row}: the outside changed"
            );
            assert_ne!(outside_before, BTreeMap::new());
        }
    }
}

/// A bootstrap file that changes DURING the copy is never taken for the admitted bytes. The copy streams
/// from the retained descriptor, one bounded chunk at a time, and the result is checked against the length
/// and SHA-256 admitted: a same-length change in place, an appended byte, and a truncation each refuse with
/// a typed copy refusal, and the bytes written so far are preserved with the facts that describe them.
#[test]
fn b2a_a_bootstrap_file_that_changes_during_the_copy_is_refused_with_the_partial_bytes_kept() {
    // A chunk no admitted file's length is a multiple of, so the last chunk is short and the read bound
    // (never past the admitted length) is what keeps a grown source from being copied.
    let _chunk = override_object_copy_chunk_for_test(13);
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (extension, action) in [
        ("pack", "changed in place"),
        ("idx", "an appended byte"),
        ("rev", "truncated"),
    ] {
        let row = format!("{extension}: {action}");
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let source = admitted_path(&case.dest.bootstrap(), extension);
        let original = std::fs::read(&source).expect("the admitted file");
        let output_leaf = source.file_name().expect("a name").to_owned();
        let output = pack_directory(&case.dest).join(&output_leaf);
        let chunks = std::rc::Rc::new(std::cell::Cell::new(0_usize));
        let seen = chunks.clone();
        let acting = (source.clone(), output.clone(), action);
        let _hook = install_git_hook_for_test(GitHookPointV1::BeforeObjectChunk, move |event| {
            if event.path != acting.1 {
                return;
            }
            seen.set(seen.get() + 1);
            // A change in place must precede the first read to be seen at all; the others act between
            // the first chunk and the second.
            if seen.get() != if acting.2 == "changed in place" { 1 } else { 2 } {
                return;
            }
            match acting.2 {
                "changed in place" => change_in_place(&acting.0),
                "an appended byte" => append_fixture_byte(&acting.0),
                _ => with_fixture_write_permission(&acting.0, || {
                    std::fs::OpenOptions::new()
                        .write(true)
                        .open(&acting.0)
                        .and_then(|file| file.set_len(20))
                        .expect("a truncation");
                }),
            }
        });
        let failure = case.refused(&row);
        // Each refusal is its own guard's: the digest of the bytes streamed, the probe past the admitted
        // length, and the end of the source before it.
        let wanted = match action {
            "changed in place" => "admitted SHA-256",
            "an appended byte" => "longer than the admitted",
            _ => "the source ended after",
        };
        match &failure.cause {
            GitBootstrapErrorV1::ObjectCopy { relative, detail } => {
                assert!(relative.ends_with(extension), "{row}: {relative}");
                assert!(detail.contains(wanted), "{row}: {detail}");
            }
            other => panic!("{row}: {other:?}"),
        }
        assert!(failure.active_materialization_began, "{row}");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the file in flight");
        assert_eq!(flight.expected_length, original.len() as u64, "{row}");
        // What is on disk is exactly what the facts say was written, and is kept.
        let copied = std::fs::read(&output).expect("the partial copy");
        assert_eq!(copied.len() as u64, flight.written, "{row}");
        match action {
            "changed in place" => {
                assert_eq!(
                    flight.written,
                    original.len() as u64,
                    "{row}: every byte was read"
                );
                assert_ne!(
                    copied, original,
                    "{row}: the changed byte was copied, and refused"
                );
            }
            "an appended byte" => {
                assert_eq!(
                    copied,
                    original,
                    "{row}: the first {} bytes",
                    original.len()
                );
            }
            _ => {
                assert!(flight.written < original.len() as u64, "{row}");
                assert!(copied.len() >= 13, "{row}: the first chunk was copied");
            }
        }
        // Files before it are complete, files after it were never created.
        let position = EXTENSIONS_V1
            .iter()
            .position(|found| *found == extension)
            .expect("ext");
        assert_eq!(failure.partial.files.len(), position, "{row}");
        assert_eq!(
            listing(&pack_directory(&case.dest)).len(),
            position + 1,
            "{row}"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Late swaps: every retained chain is rechecked around the writes
// ---------------------------------------------------------------------------------------------

/// Runs `act` once, just before the helper creates the entry at `target` (after its pre-create recheck).
fn act_before_creating(target: PathBuf, act: impl Fn() + 'static) -> GitSeamGuardV1 {
    let fired = std::rc::Rc::new(std::cell::Cell::new(false));
    install_git_hook_for_test(GitHookPointV1::BeforeObjectCreate, move |event| {
        if event.path == target && !fired.replace(true) {
            act();
        }
    })
}

/// Runs `act` once, at the `nth` time the helper reads the clock for the guard `label`.
fn act_at_guard(label: &'static str, nth: usize, act: impl Fn() + 'static) -> GitSeamGuardV1 {
    let seen = std::rc::Rc::new(std::cell::Cell::new(0_usize));
    install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        if event.label == label {
            seen.set(seen.get() + 1);
            if seen.get() == nth {
                act();
            }
        }
    })
}

fn identity_changed(error: &GitBootstrapErrorV1) -> bool {
    matches!(
        error,
        GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::IdentityChanged(_))
    )
}

fn move_away(path: &Path, to: &str) {
    std::fs::rename(path, path.with_file_name(to)).expect("moved away");
}

/// The guards the helper reads after a swap happened: a refusal that comes from the swapped step's OWN
/// recheck never reaches the guard of any later step (a later directory, file, gate, sync, or read-back).
struct AfterSwapV1 {
    swapped: std::rc::Rc<std::cell::Cell<bool>>,
    labels: std::rc::Rc<std::cell::RefCell<Vec<&'static str>>>,
}

impl AfterSwapV1 {
    fn new() -> Self {
        Self {
            swapped: std::rc::Rc::new(std::cell::Cell::new(false)),
            labels: std::rc::Rc::new(std::cell::RefCell::new(Vec::new())),
        }
    }

    fn flag(&self) -> std::rc::Rc<std::cell::Cell<bool>> {
        self.swapped.clone()
    }

    fn record(&self) -> GitSeamGuardV1 {
        let (swapped, labels) = (self.swapped.clone(), self.labels.clone());
        install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            if swapped.get() {
                labels.borrow_mut().push(event.label);
            }
        })
    }

    fn assert_refused_within_the_step(&self, row: &str) {
        let labels = self.labels.borrow();
        assert!(!labels.is_empty(), "{row}: the swap was never reached");
        for later in [
            "objects-directory",
            "objects-file",
            "objects-gate",
            "objects-sync",
            "objects-verify",
            "objects-final",
        ] {
            assert!(
                !labels.contains(&later),
                "{row}: the run went on to `{later}` after the swap: {labels:?}"
            );
        }
    }
}

/// One swap between two writes: the entry it happens before, the swap itself (given the destination's
/// paths and an outside directory a link may name), and how many entries the helper had created when the
/// next recheck refused.
struct SwapV1 {
    row: &'static str,
    before: usize,
    swap: fn(&PathsV1, &Path),
    entries: u64,
    /// Entries under `repository*` that the swap itself plants (a replacement directory or link).
    planted: usize,
}

/// A directory the helper created and pinned that is renamed away and replaced by a new directory, or by a
/// link, between two writes is caught at the next recheck: the entry that raced went through the retained
/// pin into the moved directory (never through the new name), no later entry is created, and every byte is
/// preserved. A bootstrap, staging, work, or HOME/XDG chain swapped between two writes is caught the same
/// way, and a replacement bootstrap file is never read: the copy comes from the retained descriptor.
#[test]
fn b2a_late_parent_link_and_staging_swaps_refuse_through_retained_pins() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let rows = [
        SwapV1 {
            row: "an output parent replaced by a directory",
            before: 2,
            swap: |paths, _| {
                let git = paths.root.join("repository/.git");
                move_away(&git, ".git-away");
                std::fs::create_dir(&git).expect("a new directory takes the name");
            },
            entries: 3,
            planted: 1,
        },
        SwapV1 {
            row: "an output parent replaced by a link",
            before: 3,
            swap: |paths, outside| {
                let objects = paths.root.join("repository/.git/objects");
                move_away(&objects, "objects-away");
                std::os::unix::fs::symlink(outside, &objects).expect("a link takes the name");
            },
            entries: 4,
            planted: 1,
        },
        SwapV1 {
            row: "an earlier output directory replaced by a link",
            before: 4,
            swap: |paths, outside| {
                let pack = paths.root.join("repository/.git/objects/pack");
                move_away(&pack, "pack-away");
                std::os::unix::fs::symlink(outside, &pack).expect("a link takes the name");
            },
            entries: 5,
            planted: 1,
        },
        SwapV1 {
            row: "the repository replaced by a link",
            before: 1,
            swap: |paths, outside| {
                let repository = paths.root.join("repository");
                move_away(&repository, "repository-away");
                std::os::unix::fs::symlink(outside, &repository).expect("a link takes the name");
            },
            entries: 2,
            planted: 1,
        },
        SwapV1 {
            row: "the bootstrap pack directory replaced",
            before: 6,
            swap: |paths, _| {
                let pack = paths.bootstrap.join("objects/pack");
                move_away(&pack, "pack-away");
                std::fs::create_dir(&pack).expect("a new directory takes the name");
                // Same-named files with other bytes: they must never be read.
                for entry in std::fs::read_dir(pack.with_file_name("pack-away")).expect("the old") {
                    let name = entry.expect("an entry").file_name();
                    std::fs::write(pack.join(name), b"poison").expect("a poisoned file");
                }
            },
            entries: 7,
            planted: 0,
        },
        SwapV1 {
            row: "the staging directory replaced",
            before: 5,
            swap: |paths, _| {
                let plain = paths.work.join("plain");
                move_away(&plain, "plain-away");
                std::fs::create_dir(&plain).expect("a new directory takes the name");
            },
            entries: 6,
            planted: 0,
        },
        SwapV1 {
            row: "the work directory replaced",
            before: 7,
            swap: |paths, _| {
                move_away(&paths.work, ".restore-work-away");
                std::fs::create_dir(&paths.work).expect("a new directory takes the name");
            },
            entries: 8,
            planted: 0,
        },
        SwapV1 {
            row: "the XDG directory replaced by a link",
            before: 0,
            swap: |paths, outside| {
                let xdg = paths.work.join("xdg");
                move_away(&xdg, "xdg-away");
                std::os::unix::fs::symlink(outside, &xdg).expect("a link takes the name");
            },
            entries: 1,
            planted: 0,
        },
        SwapV1 {
            row: "an unrelated bootstrap directory replaced",
            before: 4,
            swap: |paths, _| {
                let info = paths.bootstrap.join("objects/info");
                move_away(&info, "info-away");
                std::fs::create_dir(&info).expect("a new directory takes the name");
            },
            entries: 5,
            planted: 0,
        },
    ];
    for SwapV1 {
        row,
        before,
        swap,
        entries,
        planted,
    } in rows
    {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let lengths = case.lengths();
        let (_outside_area, outside) = external_dir_with(&["decoy"]);
        let outside_before = snapshot(&outside);
        let originals = bootstrap_object_files(&case.dest);
        let paths = PathsV1::of(&case.dest);
        let names = case.entry_names();
        let swapping = outside.clone();
        let after = AfterSwapV1::new();
        let swapped = after.flag();
        let _hook = act_before_creating(stored(&case.dest, &names[before]), move || {
            swap(&paths, &swapping);
            swapped.set(true);
        });
        let _guards = after.record();
        let failure = case.refused(row);
        assert!(
            identity_changed(&failure.cause),
            "{row}: {:?}",
            failure.cause
        );
        assert!(failure.active_materialization_began, "{row}");
        after.assert_refused_within_the_step(row);
        assert_eq!(
            snapshot(&outside),
            outside_before,
            "{row}: written through a link"
        );
        // The entry that raced is created (it went through the retained pin) and refused at once; nothing
        // after it exists, anywhere.
        let complete = before.saturating_sub(5).min(3);
        assert_eq!(failure.partial.charged.entries, entries, "{row}");
        assert_eq!(
            failure.partial.charged.bytes,
            lengths[..complete].iter().sum::<u64>(),
            "{row}: no byte of the raced file was streamed"
        );
        assert_eq!(failure.partial.files.len(), complete, "{row}");
        assert_eq!(failure.partial.in_flight.is_some(), before >= 5, "{row}");
        if let Some(flight) = &failure.partial.in_flight {
            assert_eq!(flight.written, 0, "{row}");
        }
        assert_eq!(
            repository_keys(&case.dest),
            entries as usize + planted,
            "{row}: exactly the entries reported exist under the repository, and the swap's own"
        );
        // Whatever was copied is the original bytes; a replacement file was never read.
        let moved_pack = pack_directory(&case.dest);
        let linked = std::fs::symlink_metadata(&moved_pack)
            .map(|metadata| metadata.file_type().is_symlink())
            .unwrap_or(true);
        if !linked && moved_pack.is_dir() {
            for (name, bytes) in files_in(&moved_pack) {
                let original = originals.iter().find(|(found, _)| *found == name);
                assert!(
                    original.is_some_and(|(_, original)| *original == bytes || bytes.is_empty()),
                    "{row}: {name}"
                );
            }
        }
    }
}

/// The pre-write recheck is its own guard: a chain swapped at the helper's own entry to a step (the clock
/// guard before it) refuses BEFORE the entry is created, where the post-write recheck would have let the
/// entry race into the moved directory first.
#[test]
fn b2a_a_chain_swapped_before_a_step_refuses_before_that_entry_is_created() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    type PreV1 = (&'static str, &'static str, usize, fn(&PathsV1), u64, usize);
    let rows: [PreV1; 4] = [
        (
            "an output parent, before the objects directory",
            "objects-directory",
            3,
            |paths| {
                let git = paths.root.join("repository/.git");
                move_away(&git, ".git-away");
                std::fs::create_dir(&git).expect("a new directory takes the name");
            },
            2,
            1,
        ),
        (
            "the repository, before the `.git` directory",
            "objects-directory",
            2,
            |paths| {
                let repository = paths.root.join("repository");
                move_away(&repository, "repository-away");
                std::fs::create_dir(&repository).expect("a new directory takes the name");
            },
            1,
            1,
        ),
        (
            "a bootstrap directory, before the first file",
            "objects-file",
            1,
            |paths| {
                let pack = paths.bootstrap.join("objects/pack");
                move_away(&pack, "pack-away");
                std::fs::create_dir(&pack).expect("a new directory takes the name");
            },
            5,
            0,
        ),
        (
            "the staging directory, before the second file",
            "objects-file",
            2,
            |paths| {
                let plain = paths.work.join("plain");
                move_away(&plain, "plain-away");
                std::fs::create_dir(&plain).expect("a new directory takes the name");
            },
            6,
            0,
        ),
    ];
    for (row, label, nth, swap, entries, planted) in rows {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let paths = PathsV1::of(&case.dest);
        let _hook = act_at_guard(label, nth, move || swap(&paths));
        let failure = case.refused(row);
        assert!(
            identity_changed(&failure.cause),
            "{row}: {:?}",
            failure.cause
        );
        assert!(failure.active_materialization_began, "{row}");
        assert_eq!(failure.partial.charged.entries, entries, "{row}");
        assert!(
            failure.partial.in_flight.is_none(),
            "{row}: no entry was in flight"
        );
        assert_eq!(
            repository_keys(&case.dest),
            entries as usize + planted,
            "{row}: the step's entry was never created, in the moved tree or anywhere"
        );
    }
}

/// How many entries (files, directories, links) the snapshot holds under a name starting with `repository`:
/// the helper's created entries, wherever a swap moved them, plus whatever a swap planted.
fn repository_keys(dest: &DestV1) -> usize {
    snapshot(&dest.path)
        .keys()
        .filter(|name| name.starts_with("repository"))
        .count()
}

// ---------------------------------------------------------------------------------------------
// The final gate: the root is checked LAST, and a late link or root swap refuses with every byte kept
// ---------------------------------------------------------------------------------------------

/// The destination root swapped just before the final gate refuses with every file already complete: the
/// retained facts name all eight entries, they are all in the moved root, and the replacement stays empty.
#[test]
fn b2a_a_root_swapped_before_the_final_gate_refuses_with_every_effect_preserved() {
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let lengths = case.lengths();
    let root = case.dest.path.clone();
    let away = root.with_file_name("dest-away");
    let (swap_root, swap_away) = (root.clone(), away.clone());
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeObjectsFinalGate, move |_| {
        std::fs::rename(&swap_root, &swap_away).expect("the root moves away");
        std::fs::create_dir(&swap_root).expect("an empty root takes its name");
    });
    let failure = case.refused("the final gate");
    assert!(identity_changed(&failure.cause), "{:?}", failure.cause);
    assert!(failure.active_materialization_began);
    assert_eq!(
        failure.partial.charged,
        ObjectStoreChargeV1 {
            entries: 8,
            bytes: lengths.iter().sum()
        }
    );
    assert_eq!(failure.partial.files.len(), 3, "every copy was complete");
    assert!(failure.partial.in_flight.is_none());
    assert_eq!(pins_present(&failure.partial.pins), [true; 5]);
    assert_eq!(
        case.dest.entries(),
        Vec::<String>::new(),
        "the replacement root stays empty"
    );
    assert_eq!(listing(&away.join("repository/.git/objects/pack")).len(), 3);
}

/// An output file replaced by a link between its copy and the final gate is refused, never followed: the
/// gate looks every created file up by name through its retained pin. The outside file is untouched.
#[test]
fn b2a_an_output_file_replaced_by_a_link_before_the_final_gate_refuses() {
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let rev = case.entry_names()[7].clone();
    let rev_path = stored(&case.dest, &rev);
    let (_outside_area, outside) = external_dir_with(&["decoy"]);
    let outside_before = snapshot(&outside);
    let link_target = outside.join("decoy");
    let swapped = rev_path.clone();
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeObjectsFinalGate, move |_| {
        move_away(&swapped, "moved.rev");
        std::os::unix::fs::symlink(&link_target, &swapped).expect("a link takes the name");
    });
    let failure = case.refused("a linked output file");
    assert!(
        matches!(
            failure.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. })
        ),
        "{:?}",
        failure.cause
    );
    assert_eq!(
        snapshot(&outside),
        outside_before,
        "written through the link"
    );
    assert_eq!(failure.partial.files.len(), 3);
    assert!(
        rev_path.with_file_name("moved.rev").is_file(),
        "the bytes are kept"
    );
}

/// A copied file that is no longer the one the helper measured (another inode holding the same bytes, a
/// longer file, or a directory) is refused at the final gate: the gate looks every created file up by name
/// through its retained pin and holds it to the device, inode, and length it was measured with.
#[test]
fn b2a_an_output_file_that_is_no_longer_the_copy_refuses_before_the_final_gate() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for action in ["a new inode", "an appended byte", "a directory"] {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let idx = case.entry_names()[6].clone();
        let path = stored(&case.dest, &idx);
        let acting = path.clone();
        let _hook =
            install_git_hook_for_test(
                GitHookPointV1::BeforeObjectsFinalGate,
                move |_| match action {
                    "a new inode" => {
                        let bytes = std::fs::read(&acting).expect("the copy");
                        move_away(&acting, "moved.idx");
                        std::fs::write(&acting, bytes).expect("the same bytes, a new inode");
                    }
                    "an appended byte" => {
                        use std::io::Write as _;
                        std::fs::OpenOptions::new()
                            .append(true)
                            .open(&acting)
                            .and_then(|mut file| file.write_all(b"x"))
                            .expect("an appended byte");
                    }
                    _ => {
                        move_away(&acting, "moved.idx");
                        std::fs::create_dir(&acting).expect("a directory takes the name");
                    }
                },
            );
        let failure = case.refused(action);
        assert!(
            identity_changed(&failure.cause),
            "{action}: {:?}",
            failure.cause
        );
        assert!(failure.active_materialization_began, "{action}");
        assert_eq!(
            failure.partial.files.len(),
            3,
            "{action}: every copy was complete"
        );
    }
}

/// The caller's last completed step is carried unchanged on every refusal, before the first write and
/// after writes began; the helper never claims a step of its own on a failure.
#[test]
fn b2a_the_callers_completed_step_is_carried_unchanged_on_every_refusal() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let mut wrong = case.plan.clone();
    wrong.frames.reverse();
    let steps = [
        None,
        Some(GitPlaneStepV1::Admission),
        Some(GitPlaneStepV1::BootstrapGate),
    ];
    for completed in steps {
        let failure = materialize_object_store_v1(&case.boot, &wrong, far_deadline(), completed)
            .expect_err("a wrong plan");
        assert_eq!(failure.last_completed, completed);
        assert!(!failure.active_materialization_began);
    }
    for completed in steps {
        let case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let pack = case.entry_names()[5].clone();
        let _device = override_created_dev_for_test(&pack, device_of(&case.dest.path) + 1);
        let failure =
            materialize_object_store_v1(&case.boot, &case.plan, far_deadline(), completed)
                .expect_err("a device refusal after writes began");
        assert_eq!(failure.last_completed, completed);
        assert!(failure.active_materialization_began);
    }
}

// ---------------------------------------------------------------------------------------------
// Devices and mounts
// ---------------------------------------------------------------------------------------------

/// A created entry on another device refuses for every one of the eight entries, and its charge stays: the
/// entry exists (it was created before the device was read), it is named in the facts when it is a file, no
/// later entry is created, and the ledger moved by exactly what the facts report.
#[test]
fn b2a_a_device_mismatch_refuses_for_every_entry_and_keeps_the_charge() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let names = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1).entry_names();
    for (index, slot) in names.iter().enumerate() {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let lengths = case.lengths();
        let other = device_of(&case.dest.path) + 1;
        let _device = override_created_dev_for_test(slot, other);
        let failure = case.refused(slot);
        assert!(
            matches!(&failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::DeviceCrossing { name })
                    if name == slot),
            "{slot}: {:?}",
            failure.cause
        );
        assert!(failure.active_materialization_began, "{slot}");
        let complete = index.saturating_sub(5);
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: index as u64 + 1,
                bytes: lengths[..complete].iter().sum()
            },
            "{slot}: the created entry stays charged"
        );
        assert!(exists(&stored(&case.dest, slot)), "{slot}: it was created");
        for later in &names[index + 1..] {
            assert!(
                !exists(&stored(&case.dest, later)),
                "{slot}: {later} was created after"
            );
        }
        // A directory refused on its device has no pin; a file is named in flight with nothing written.
        let unlisted = usize::from(index < 5);
        assert_eq!(failure.partial.in_flight.is_some(), index >= 5, "{slot}");
        assert_partial_is_the_disk(&case, &failure, unlisted);
    }
}

/// The mount census runs before the first entry, before each file's write, and at the final gate: a mount
/// that appears for any ONE census call refuses at that call, with only the entries made before it, and a
/// census that cannot list the mount points fails closed before anything is created.
#[test]
fn b2a_a_mount_appearing_at_any_census_refuses_and_a_failing_census_fails_closed() {
    for (populated, expected_entries) in [(true, vec![0_u64, 5, 6, 7, 8]), (false, vec![0, 5])] {
        let cformat = CustodyGitObjectFormatV1::Sha1;
        let capsule = if populated {
            captured(cformat)
        } else {
            empty(cformat)
        };
        // Learn the number of census calls in a clean run.
        let mut case = StoreCaseV1::of(&capsule, cformat);
        let census = crate::custody_mounts::seam::install_list(vec![b"/".to_vec()]);
        let _ = case.done("a clean run");
        let total = census.calls();
        drop(census);
        assert_eq!(
            total,
            expected_entries.len(),
            "populated={populated}: {total} census calls"
        );

        for call in 1..=total {
            let row = format!("populated={populated} call {call}");
            let mut case = StoreCaseV1::of(&capsule, cformat);
            let inside = case
                .dest
                .path
                .join(".restore-work/home")
                .as_os_str()
                .as_bytes()
                .to_vec();
            let _census = crate::custody_mounts::seam::install(Box::new(move |number| {
                if number == call {
                    Ok(vec![b"/".to_vec(), inside.clone()])
                } else {
                    Ok(vec![b"/".to_vec()])
                }
            }));
            let failure = case.refused(&row);
            assert!(
                matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::MountBoundary(_))
                ),
                "{row}: {:?}",
                failure.cause
            );
            assert_eq!(
                failure.partial.charged.entries,
                expected_entries[call - 1],
                "{row}: the census precedes the entries it guards"
            );
            assert_eq!(failure.active_materialization_began, call > 1, "{row}");
            assert_partial_is_the_disk(&case, &failure, 0);
        }
    }

    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let _census = crate::custody_mounts::seam::install(Box::new(|_| {
        Err(crate::custody_mounts::CustodyMountErrorV1::MalformedLine { line: 1 })
    }));
    let cause = case.refused_before_any_write("a failing census");
    assert!(
        matches!(
            cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::MountBoundary(_))
        ),
        "{cause:?}"
    );
}

// ---------------------------------------------------------------------------------------------
// The one deadline paces every step
// ---------------------------------------------------------------------------------------------

/// The one deadline of the pacing rows. A clean run of these small files takes milliseconds.
const B2A_DEADLINE_V1: Duration = Duration::from_secs(2);

/// Every label the helper's clean Captured run reads the clock at: each step of the success path is paced.
const B2A_GUARDS_V1: [&str; 14] = [
    "chain",
    "objects-chain",
    "objects-checked",
    "objects-directory",
    "objects-entry",
    "objects-file",
    "objects-final",
    "objects-gate",
    "objects-read",
    "objects-source",
    "objects-sync",
    "objects-sync-directory",
    "objects-verify",
    "root",
];

/// A deadline already spent refuses before the first entry: the clock is read once, and nothing is created,
/// charged, or pinned.
#[test]
fn b2a_a_spent_deadline_refuses_before_any_write() {
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let spent = Instant::now();
    std::thread::sleep(Duration::from_millis(5));
    let (labels, _hook) = record_guards();
    let tree = snapshot(&case.dest.path);
    let ledger = case.ledger();
    let failure = match case.attempt_by(spent) {
        Ok(_) => panic!("a spent deadline must refuse"),
        Err(failure) => failure,
    };
    assert!(
        matches!(
            failure.cause,
            GitBootstrapErrorV1::Git(CustodyGitError::Timeout)
        ),
        "{:?}",
        failure.cause
    );
    assert!(!failure.active_materialization_began);
    assert_eq!(*labels.borrow(), ["objects-entry"]);
    assert_eq!(case.ledger(), ledger);
    assert_eq!(snapshot(&case.dest.path), tree);
}

/// The clock is read at exactly the documented guards, so no step is unobserved: the first guard is the
/// entry, the last is the one immediately before the destination root's identity check (the final gate's),
/// the distinct labels are exactly the documented ones, and each is read exactly as often as the design
/// says. The recheck runs 21 times for a Captured run (the first gate, two around each of the five
/// directories, three around each of the three files, and the final gate) and 12 for an Empty one, and
/// every recheck covers every retained chain, output directory and file, and admitted source file.
#[test]
fn b2a_the_guards_of_a_clean_run_are_the_documented_ones() {
    for populated in [true, false] {
        let cformat = CustodyGitObjectFormatV1::Sha1;
        let capsule = if populated {
            captured(cformat)
        } else {
            empty(cformat)
        };
        let mut case = StoreCaseV1::of(&capsule, cformat);
        let staging = case.boot.verified.destination.staging.borrow().len();
        let bootstrap_directories = case.boot.directories.len();
        let (labels, _hook) = record_guards();
        let _ = case.done("a clean run");
        let labels = labels.borrow();
        assert_eq!(labels.first().copied(), Some("objects-entry"));
        assert_eq!(labels.last().copied(), Some("root"));
        let count = |wanted: &str| labels.iter().filter(|label| **label == wanted).count();
        let sweeps = if populated { 21 } else { 12 };
        let expected: Vec<(&str, usize)> = vec![
            ("objects-entry", 1),
            ("objects-gate", if populated { 4 } else { 1 }),
            // The guard right after every NON-final recheck (the full gates and the rechecks between
            // writes): the recheck ends in the root's identity, which can block.
            ("objects-checked", if populated { 20 } else { 11 }),
            ("objects-read", if populated { 3 } else { 0 }),
            ("objects-sync-directory", if populated { 3 } else { 0 }),
            ("objects-directory", 5),
            ("objects-file", if populated { 3 } else { 0 }),
            ("objects-sync", if populated { 3 } else { 0 }),
            ("objects-verify", if populated { 3 } else { 0 }),
            ("objects-final", 1),
            ("root", sweeps),
            ("chain", sweeps * (1 + staging + 2 + bootstrap_directories)),
            ("objects-source", if populated { 3 * sweeps } else { 0 }),
            ("objects-chain", if populated { 90 } else { 30 }),
        ];
        for (label, times) in &expected {
            assert_eq!(count(label), *times, "populated={populated}: {label}");
        }
        assert_eq!(
            labels.len(),
            expected.iter().map(|(_, times)| times).sum::<usize>(),
            "populated={populated}: no other label"
        );
        let mut distinct: Vec<&str> = labels.clone();
        distinct.sort_unstable();
        distinct.dedup();
        let documented: Vec<&str> = B2A_GUARDS_V1
            .into_iter()
            .filter(|label| populated || !matches!(*label, "objects-source"))
            .filter(|label| {
                populated
                    || !matches!(
                        *label,
                        "objects-file"
                            | "objects-read"
                            | "objects-sync"
                            | "objects-sync-directory"
                            | "objects-verify"
                    )
            })
            .collect();
        assert_eq!(distinct, documented, "populated={populated}");
    }
}

/// Each distinct guard halts the run alone: its step made slow past the deadline is refused with a typed
/// timeout, the run stops AT that guard (no later guard ever ran), every byte created so far is kept and
/// reported, and a brief delay at every guard, with headroom, still succeeds.
#[test]
fn b2a_each_guard_halts_the_run_alone_and_headroom_succeeds() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for target in B2A_GUARDS_V1 {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let deadline = Instant::now() + B2A_DEADLINE_V1;
        let labels = std::rc::Rc::new(std::cell::RefCell::new(Vec::<&'static str>::new()));
        let fired = std::rc::Rc::new(std::cell::Cell::new(false));
        let (seen, slow) = (labels.clone(), fired.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            seen.borrow_mut().push(event.label);
            if event.label == target && !slow.replace(true) {
                pass_the_deadline(deadline);
            }
        });
        let failure = match case.attempt_by(deadline) {
            Ok(_) => panic!("{target}: a spent deadline must refuse"),
            Err(failure) => failure,
        };
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Git(CustodyGitError::Timeout)
            ),
            "{target}: {:?}",
            failure.cause
        );
        assert!(fired.get(), "{target}: the slow step never ran");
        assert_eq!(
            labels.borrow().last().copied(),
            Some(target),
            "{target}: the run halted AT its guard"
        );
    }

    let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    // Some five hundred guards, each delayed a millisecond, still leave most of a generous deadline.
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, |_| {
        std::thread::sleep(Duration::from_millis(1));
    });
    case.attempt_by(Instant::now() + 10 * B2A_DEADLINE_V1)
        .unwrap_or_else(|failure| panic!("brief delays leave headroom: {:?}", failure.cause));
}

/// No success past the deadline: when the clock passes at any guard of the FINAL gate (its entry, the guard
/// right after its mount census, and the last guard right before the root's identity), the run still
/// refuses, with every file complete and reported. The identity check is therefore the last fallible call,
/// and the final gate's own chain recheck is what makes it so (the post-write rechecks before it have their
/// own guards, which this row does not count).
#[test]
fn b2a_a_deadline_spent_in_the_final_gate_cannot_succeed() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (row, label) in [
        ("the final gate's entry", "objects-final"),
        ("the guard after the final census", "objects-chain"),
        ("the last guard before the root's identity", "root"),
    ] {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let lengths = case.lengths();
        let deadline = Instant::now() + B2A_DEADLINE_V1;
        let in_final = std::rc::Rc::new(std::cell::Cell::new(false));
        let fired = std::rc::Rc::new(std::cell::Cell::new(false));
        let started = in_final.clone();
        let _gate = install_git_hook_for_test(GitHookPointV1::BeforeObjectsFinalGate, move |_| {
            started.set(true);
        });
        let (inside, once) = (in_final.clone(), fired.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            if inside.get() && event.label == label && !once.replace(true) {
                pass_the_deadline(deadline);
            }
        });
        let failure = match case.attempt_by(deadline) {
            Ok(_) => panic!("{row}: no success after the deadline"),
            Err(failure) => failure,
        };
        assert!(fired.get(), "{row}: the final gate never read that guard");
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Git(CustodyGitError::Timeout)
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: 8,
                bytes: lengths.iter().sum()
            },
            "{row}: every entry was already made"
        );
        assert_eq!(failure.partial.files.len(), 3, "{row}");
    }
}

/// Reads and writes are paced too: with chunks of 16 bytes, a deadline that passes before the second chunk of
/// the `.pack` stops the copy there. Exactly one chunk was read, charged, and written, nothing after it, and
/// the retained source descriptor itself has not moved past that one chunk (no later chunk was even read).
#[test]
fn b2a_no_chunk_is_read_after_the_deadline() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let names = case.entry_names();
    let output = stored(&case.dest, &names[5]);
    let deadline = Instant::now() + B2A_DEADLINE_V1;
    let chunks = std::rc::Rc::new(std::cell::Cell::new(0_usize));
    let seen = chunks.clone();
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeObjectChunk, move |event| {
        if event.path == output {
            seen.set(seen.get() + 1);
            if seen.get() == 2 {
                pass_the_deadline(deadline);
            }
        }
    });
    let failure = match case.attempt_by(deadline) {
        Ok(_) => panic!("the deadline passed mid-copy"),
        Err(failure) => failure,
    };
    assert!(
        matches!(
            failure.cause,
            GitBootstrapErrorV1::Git(CustodyGitError::Timeout)
        ),
        "{:?}",
        failure.cause
    );
    assert_eq!(chunks.get(), 2, "no third chunk was started");
    let flight = failure
        .partial
        .in_flight
        .as_ref()
        .expect("the pack in flight");
    assert_eq!(flight.written, 16);
    assert_eq!(
        failure.partial.charged,
        ObjectStoreChargeV1 {
            entries: 6,
            bytes: 16
        }
    );
    let written = std::fs::read(stored(&case.dest, &names[5])).expect("the partial pack");
    assert_eq!(written.len(), 16);
    assert_eq!(
        listing(&pack_directory(&case.dest)).len(),
        1,
        "no later file was created"
    );
    let BootstrapObjectsV1::Captured { files, .. } = &case.boot.objects else {
        panic!("a Captured bootstrap");
    };
    assert_eq!(
        (&files[0].file).stream_position().expect("a position"),
        16,
        "the source was read one chunk, not two"
    );
}

// ---------------------------------------------------------------------------------------------
// Streaming: bounded chunks, charged ahead of each write, synced after the last byte
// ---------------------------------------------------------------------------------------------

/// The copy is a stream of bounded chunks: with 16-byte chunks every file is read, charged, and written one
/// chunk at a time (the disk holds exactly the chunks before the one about to be read), and with the default
/// chunk each small file is one chunk. Each file and then its directory are synced after its LAST chunk and
/// before the next file begins.
#[test]
fn b2a_the_copy_is_chunked_and_synced_after_the_last_byte() {
    for chunk in [Some(16_usize), None] {
        let _seam = chunk.map(override_object_copy_chunk_for_test);
        let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
        let lengths = case.lengths();
        let names = case.entry_names();
        let outputs: Vec<PathBuf> = names[5..]
            .iter()
            .map(|name| stored(&case.dest, name))
            .collect();
        let log = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
        let mut guards = Vec::new();
        {
            let (log, outputs) = (log.clone(), outputs.clone());
            guards.push(install_git_hook_for_test(
                GitHookPointV1::BeforeObjectChunk,
                move |event| {
                    let index = outputs
                        .iter()
                        .position(|path| path == event.path)
                        .expect("an output");
                    let on_disk = std::fs::metadata(event.path).expect("the output").len();
                    log.borrow_mut()
                        .push(format!("chunk {index} disk {on_disk}"));
                },
            ));
        }
        {
            let (log, outputs, pack) = (log.clone(), outputs.clone(), pack_directory(&case.dest));
            guards.push(install_git_hook_for_test(
                GitHookPointV1::ObjectSynced,
                move |event| {
                    if event.label == "directory" {
                        assert_eq!(event.path, pack);
                        log.borrow_mut().push("sync directory".to_owned());
                    } else {
                        let index = outputs
                            .iter()
                            .position(|path| path == event.path)
                            .expect("an output");
                        log.borrow_mut().push(format!("sync file {index}"));
                    }
                },
            ));
        }
        let _ = case.done("a streamed copy");
        drop(guards);

        let mut expected = Vec::new();
        for (index, length) in lengths.iter().enumerate() {
            let size = chunk.map_or(u64::MAX, |size| size as u64);
            let chunks = length.div_ceil(size.min(*length).max(1));
            for number in 0..chunks {
                expected.push(format!(
                    "chunk {index} disk {}",
                    (number * size).min(*length)
                ));
            }
            expected.push(format!("sync file {index}"));
            expected.push("sync directory".to_owned());
        }
        assert_eq!(*log.borrow(), expected, "chunk {chunk:?}");
    }
}

// ---------------------------------------------------------------------------------------------
// Retained descriptors are read from their start, and the written copy is read back
// ---------------------------------------------------------------------------------------------

/// The retained source descriptors are sought to their start explicitly: parked elsewhere by an earlier
/// reader (as the runner leaves a shared duplicate), each is still copied whole, and the bytes are exact.
#[test]
fn b2a_the_source_descriptors_are_read_from_their_start() {
    use std::io::Seek as _;
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let expected = bootstrap_object_files(&case.dest);
    let BootstrapObjectsV1::Captured { files, .. } = &case.boot.objects else {
        panic!("a Captured bootstrap");
    };
    for admitted in files {
        (&admitted.file)
            .seek(SeekFrom::Start(9))
            .expect("park the descriptor");
    }
    let _ = case.done("parked descriptors");
    assert_eq!(files_in(&pack_directory(&case.dest)), expected);
}

/// The written file is read back from its own descriptor and held to the admitted digest: a copy that
/// changes after it was written and synced (same inode, same length) is refused at the read-back, with
/// every byte kept and the file named in flight.
#[test]
fn b2a_a_copy_changed_after_its_write_is_refused_at_the_read_back() {
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let names = case.entry_names();
    let output = stored(&case.dest, &names[6]);
    let pack = pack_directory(&case.dest);
    let acting = output.clone();
    let _hook = install_git_hook_for_test(GitHookPointV1::ObjectSynced, move |event| {
        if event.label == "directory" && event.path == pack && acting.exists() {
            change_in_place(&acting);
        }
    });
    let failure = case.refused("a copy changed after its write");
    match &failure.cause {
        GitBootstrapErrorV1::ObjectCopy { relative, detail } => {
            assert!(relative.ends_with(".idx"), "{relative}");
            assert!(detail.contains("written file"), "{detail}");
        }
        other => panic!("{other:?}"),
    }
    let flight = failure
        .partial
        .in_flight
        .as_ref()
        .expect("the idx in flight");
    assert_eq!(
        flight.written, flight.expected_length,
        "every byte was written"
    );
    assert_eq!(failure.partial.files.len(), 1, "the pack is whole");
    assert_ne!(
        std::fs::read(&output).expect("the changed copy"),
        std::fs::read(admitted_path(&case.dest.bootstrap(), "idx")).expect("the admitted idx"),
        "the changed bytes are kept"
    );
}

/// A chain swapped while a file is being streamed is caught by the recheck that follows that file's
/// write, before the final gate: the last file is complete and reported, and the run never reaches the
/// final gate's guard.
#[test]
fn b2a_a_chain_swapped_during_the_last_copy_refuses_before_the_final_gate() {
    let (_capsule, mut case) = captured_case(CustodyGitObjectFormatV1::Sha1);
    let names = case.entry_names();
    let output = stored(&case.dest, &names[7]);
    let paths = PathsV1::of(&case.dest);
    let after = AfterSwapV1::new();
    let swapped = after.flag();
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeObjectChunk, move |event| {
        if event.path == output && !swapped.replace(true) {
            let plain = paths.work.join("plain");
            move_away(&plain, "plain-away");
            std::fs::create_dir(&plain).expect("a new directory takes the name");
        }
    });
    let _guards = after.record();
    let failure = case.refused("a swap during the last copy");
    assert!(identity_changed(&failure.cause), "{:?}", failure.cause);
    assert_eq!(failure.partial.files.len(), 3, "the last copy is whole");
    assert!(failure.partial.in_flight.is_none());
    let labels = after.labels.borrow();
    assert!(labels.contains(&"objects-sync") && labels.contains(&"objects-verify"));
    assert!(
        !labels.contains(&"objects-final"),
        "the file's own recheck refused before the final gate: {labels:?}"
    );
}

// ---------------------------------------------------------------------------------------------
// Failure paths whose real trigger is the storage itself: a partial write, a failed sync, a refused create
//
// Each row raises one fault in place of one filesystem effect (`ObjectFaultV1`), so what a full disk, an
// I/O error, or a permission refusal leaves behind is exercised, and the typed facts are held to the disk.
// ---------------------------------------------------------------------------------------------

/// A write that reaches the file only in part (a full disk, a quota, an I/O error after a prefix) leaves
/// exactly that prefix, and the typed facts say so: the file in flight reports the bytes that reached it,
/// the ledger keeps exactly those bytes charged (the part of the chunk that was reserved and never written
/// is given back), and nothing after the failed file is created. A write that reports it wrote nothing is
/// the same refusal, never a loop.
#[test]
fn b2a_a_partial_write_failure_records_exactly_the_bytes_that_reached_the_file() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (row, fault) in [
        ("a prefix of the first chunk", ObjectFaultV1::WriteAfter(5)),
        (
            "the first chunk whole, then nothing",
            ObjectFaultV1::WriteAfter(16),
        ),
        (
            "a prefix of the second chunk",
            ObjectFaultV1::WriteAfter(20),
        ),
        (
            "a zero-byte write inside the first chunk",
            ObjectFaultV1::WriteZeroAfter(7),
        ),
        (
            "a zero-byte write after two chunks",
            ObjectFaultV1::WriteZeroAfter(32),
        ),
    ] {
        let limit = match fault {
            ObjectFaultV1::WriteAfter(limit) | ObjectFaultV1::WriteZeroAfter(limit) => limit,
            other => panic!("not a write fault: {other:?}"),
        };
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let names = case.entry_names();
        let original = std::fs::read(admitted_path(&case.dest.bootstrap(), "pack"))
            .expect("the admitted pack");
        let _fault = override_object_fault_for_test(fault);
        let failure = case.refused(row);
        match &failure.cause {
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Io(detail)) => {
                assert!(detail.contains(".pack"), "{row}: {detail}");
            }
            other => panic!("{row}: {other:?}"),
        }
        assert!(failure.active_materialization_began, "{row}");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the pack in flight");
        assert_eq!(flight.written, limit, "{row}: the retained fact");
        let on_disk = std::fs::read(stored(&case.dest, &names[5])).expect("the partial pack");
        assert_eq!(on_disk.len() as u64, limit, "{row}: the file on disk");
        assert_eq!(&original[..on_disk.len()], &on_disk[..], "{row}: a prefix");
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: 6,
                bytes: limit
            },
            "{row}: exactly the bytes that reached the file stay charged"
        );
        assert!(failure.partial.files.is_empty(), "{row}");
        assert_eq!(
            listing(&pack_directory(&case.dest)).len(),
            1,
            "{row}: nothing after the failed file"
        );
    }
}

/// A failed `fsync` of the file, or of its directory, is a refusal and never a success: the file is
/// whole on disk and still named in flight (it is not yet a completed copy), nothing after it is created,
/// and the directory sync is not attempted when the file's own failed.
#[test]
fn b2a_a_sync_failure_refuses_and_keeps_the_whole_file() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (row, fault, synced) in [
        (
            "the file's sync",
            ObjectFaultV1::SyncFile,
            Vec::<&str>::new(),
        ),
        (
            "the directory's sync",
            ObjectFaultV1::SyncDirectory,
            vec!["file"],
        ),
    ] {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let lengths = case.lengths();
        let names = case.entry_names();
        let original = std::fs::read(admitted_path(&case.dest.bootstrap(), "pack"))
            .expect("the admitted pack");
        let events = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
        let seen = events.clone();
        let _hook = install_git_hook_for_test(GitHookPointV1::ObjectSynced, move |event| {
            seen.borrow_mut().push(event.label.to_owned());
        });
        let _fault = override_object_fault_for_test(fault);
        let failure = case.refused(row);
        match &failure.cause {
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Io(detail)) => {
                assert!(detail.contains("injected"), "{row}: {detail}");
            }
            other => panic!("{row}: {other:?}"),
        }
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the pack in flight");
        assert_eq!(
            (flight.written, flight.expected_length),
            (lengths[0], lengths[0])
        );
        assert!(
            failure.partial.files.is_empty(),
            "{row}: not a completed copy"
        );
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: 6,
                bytes: lengths[0]
            },
            "{row}"
        );
        assert_eq!(
            std::fs::read(stored(&case.dest, &names[5])).expect("the pack"),
            original,
            "{row}: the whole file is kept"
        );
        assert_eq!(listing(&pack_directory(&case.dest)).len(), 1, "{row}");
        assert_eq!(*events.borrow(), synced, "{row}: the syncs that ran");
    }
}

/// A create that fails for any reason but a collision keeps its entry charged (the primitive cannot say
/// whether anything was created) and creates nothing after it, for each of the three files: the entry's
/// allowance is not given back, unlike a collision's.
#[test]
fn b2a_a_file_create_failure_other_than_a_collision_keeps_its_charge() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let _fault = override_object_fault_for_test(ObjectFaultV1::CreateFile);
    let failure = case.refused("a refused create");
    assert!(
        matches!(
            failure.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Io(_))
        ),
        "{:?}",
        failure.cause
    );
    assert!(
        failure.active_materialization_began,
        "the directories exist"
    );
    assert_eq!(
        failure.partial.charged,
        ObjectStoreChargeV1 {
            entries: 6,
            bytes: 0
        },
        "five directories and the refused file's entry"
    );
    assert!(failure.partial.in_flight.is_none(), "no file was created");
    assert!(failure.partial.files.is_empty());
    assert_eq!(pins_present(&failure.partial.pins), [true; 5]);
    assert!(listing(&pack_directory(&case.dest)).is_empty());
}

/// The deadline observed after the recheck, the read, and the file sync is never followed by an effect.
const B2A_SPENT_DEADLINE_V1: Duration = Duration::from_millis(1200);

/// These multi-row fixtures reach later files or many retry calls before injecting expiry. Leave
/// headroom for those earlier calls under aggregate load; each row still spends its ONE deadline
/// at the selected guard/call and forbids every effect or continuation after it.
const B2A_LATE_ROW_DEADLINE_V1: Duration = Duration::from_secs(6);

/// No effect follows a guard that finds the deadline spent. The guard right after every non-final recheck
/// (whose last call is the root's identity, which can block), after each source read (before its chunk is
/// charged and written), and after each file's sync (before the directory's) is made slow past the
/// deadline, at every occurrence in a clean Captured run: the run refuses with a timeout and no create,
/// chunk, sync, or final-gate event follows it, and the facts say exactly what had been done.
#[test]
fn b2a_no_effect_follows_a_guard_that_finds_the_deadline_spent() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let mut learn = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let (labels, hook) = record_guards();
    let _ = learn.done("a clean run");
    let rows: Vec<(&str, usize)> = ["objects-checked", "objects-read", "objects-sync-directory"]
        .into_iter()
        .map(|wanted| {
            (
                wanted,
                labels
                    .borrow()
                    .iter()
                    .filter(|label| **label == wanted)
                    .count(),
            )
        })
        .collect();
    drop(hook);
    assert_eq!(
        rows,
        [
            ("objects-checked", 20),
            ("objects-read", 3),
            ("objects-sync-directory", 3)
        ]
    );

    for (target, total) in rows {
        for nth in 1..=total {
            let row = format!("{target} #{nth}");
            let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            let lengths = case.lengths();
            let deadline = Instant::now() + B2A_LATE_ROW_DEADLINE_V1;
            let spent = std::rc::Rc::new(std::cell::Cell::new(false));
            let seen = std::rc::Rc::new(std::cell::Cell::new(0_usize));
            let effects = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
            let (flag, counter) = (spent.clone(), seen.clone());
            let _clock =
                install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
                    if event.label == target {
                        counter.set(counter.get() + 1);
                        if counter.get() == nth {
                            flag.set(true);
                            pass_the_deadline(deadline);
                        }
                    }
                });
            let mut effect_hooks = Vec::new();
            for point in [
                GitHookPointV1::BeforeObjectCreate,
                GitHookPointV1::BeforeObjectChunk,
                GitHookPointV1::ObjectSynced,
                GitHookPointV1::BeforeObjectsFinalGate,
            ] {
                let (flag, log) = (spent.clone(), effects.clone());
                effect_hooks.push(install_git_hook_for_test(point, move |event| {
                    if flag.get() {
                        log.borrow_mut()
                            .push(format!("{point:?} {} {:?}", event.label, event.path));
                    }
                }));
            }
            let failure = match case.attempt_by(deadline) {
                Ok(_) => panic!("{row}: no success after the deadline"),
                Err(failure) => failure,
            };
            drop(effect_hooks);
            assert!(spent.get(), "{row}: the guard never ran");
            assert!(
                matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Git(CustodyGitError::Timeout)
                ),
                "{row}: {:?}",
                failure.cause
            );
            assert!(
                effects.borrow().is_empty(),
                "{row}: effects after the spent guard: {:?}",
                effects.borrow()
            );
            match target {
                "objects-read" => {
                    // The chunk that was read is neither charged nor written.
                    let before: u64 = lengths[..nth - 1].iter().sum();
                    let flight = failure.partial.in_flight.as_ref().expect("in flight");
                    assert_eq!(flight.written, 0, "{row}");
                    assert_eq!(failure.partial.charged.bytes, before, "{row}");
                    assert_eq!(failure.partial.files.len(), nth - 1, "{row}");
                }
                "objects-sync-directory" => {
                    // The file is whole, synced to its own descriptor, and not yet a completed copy.
                    let flight = failure.partial.in_flight.as_ref().expect("in flight");
                    assert_eq!(flight.written, lengths[nth - 1], "{row}");
                    assert_eq!(failure.partial.files.len(), nth - 1, "{row}");
                }
                _ => {}
            }
        }
    }
}

// ---------------------------------------------------------------------------------------------
// The copy's own retries and continuations observe the one deadline
//
// A blocking call cannot be preempted, so the deadline can pass INSIDE a read, a write, or the length probe.
// Whatever such a call returns (a prefix, an interruption, the last byte), no further call on the same
// descriptor may follow it: every retry and every continuation reads the same absolute clock first, and a
// write that stops there keeps exactly the bytes the file accepted charged, giving back the rest of the
// chunk it had reserved.
//
// A returned call is made slow through the `ObjectIo` hook, which runs after the call returns and before
// its result is examined: a hook that sleeps IS that call having been slow, and every call that returns
// after it is logged. The two results a real regular file does not produce on demand, an interruption and
// a short write, are injected by the test-only seams `interrupt_object_calls_for_test` and
// `ObjectFaultV1::ShortWrites`.
// ---------------------------------------------------------------------------------------------

/// The deadline of a row that makes one call slow: long enough for the run to reach the call, short enough
/// that the row ends soon after it.
const B2A_SLOW_CALL_DEADLINE_V1: Duration = B2A_SPENT_DEADLINE_V1;

/// Every returned read, write, and probe of the copy, in order, and what followed the one made slow.
struct CallClockV1 {
    calls: std::rc::Rc<std::cell::RefCell<Vec<(&'static str, PathBuf)>>>,
    after_slow: std::rc::Rc<std::cell::RefCell<Vec<String>>>,
    slowed: std::rc::Rc<std::cell::Cell<bool>>,
    _hook: GitSeamGuardV1,
}

impl CallClockV1 {
    /// Records every call. The `nth` (counting from one) call labelled `label` on `file` spends `deadline`
    /// before its result is examined, if one is named; every call that returns after it is logged. Every
    /// call also pauses for `pause`, which a row with headroom uses to prove brief delays are harmless.
    fn watch(
        deadline: Instant,
        slow: Option<(&'static str, usize, &Path)>,
        pause: Duration,
    ) -> Self {
        let calls = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let after_slow = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let slowed = std::rc::Rc::new(std::cell::Cell::new(false));
        let target = slow.map(|(label, nth, file)| (label, nth, file.to_path_buf()));
        let counted = std::cell::Cell::new(0_usize);
        let (log, later, flag) = (calls.clone(), after_slow.clone(), slowed.clone());
        let hook = install_git_hook_for_test(GitHookPointV1::ObjectIo, move |event| {
            log.borrow_mut()
                .push((event.label, event.path.to_path_buf()));
            if flag.get() {
                later
                    .borrow_mut()
                    .push(format!("{} {:?}", event.label, event.path));
                return;
            }
            if !pause.is_zero() {
                std::thread::sleep(pause);
            }
            if let Some((label, nth, file)) = &target {
                if event.label == *label && event.path == file.as_path() {
                    counted.set(counted.get() + 1);
                    if counted.get() == *nth {
                        flag.set(true);
                        pass_the_deadline(deadline);
                    }
                }
            }
        });
        Self {
            calls,
            after_slow,
            slowed,
            _hook: hook,
        }
    }

    fn fired(&self) -> bool {
        self.slowed.get()
    }

    /// The calls with this label, on any file.
    fn count(&self, label: &str) -> usize {
        self.calls
            .borrow()
            .iter()
            .filter(|(seen, _)| *seen == label)
            .count()
    }

    /// The labels of the calls on `file`, in order.
    fn labels_on(&self, file: &Path) -> Vec<&'static str> {
        self.calls
            .borrow()
            .iter()
            .filter(|(_, path)| path == file)
            .map(|(label, _)| *label)
            .collect()
    }

    /// Every call that returned after the slow one: there must be none.
    fn after_the_slow_call(&self) -> Vec<String> {
        self.after_slow.borrow().clone()
    }
}

/// The refusal a spent deadline must give: a typed timeout.
fn timed_out(
    row: &str,
    result: Result<FinalObjectStoreV1, Box<ObjectStoreFailureV1>>,
) -> Box<ObjectStoreFailureV1> {
    match result {
        Ok(_) => panic!("{row}: no success after the deadline"),
        Err(failure) => {
            assert!(
                matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Git(CustodyGitError::Timeout)
                ),
                "{row}: {:?}",
                failure.cause
            );
            failure
        }
    }
}

/// The charge is exactly the disk: every byte in the pack directory is charged and reported, nothing
/// reserved and never written stays charged, and each file's entry is accounted for. The completed files are
/// whole, and the file in flight is on disk at exactly its `written` count.
fn assert_charge_is_the_disk(row: &str, case: &StoreCaseV1, failure: &ObjectStoreFailureV1) {
    let on_disk = files_in(&pack_directory(&case.dest));
    let total: u64 = on_disk.iter().map(|(_, bytes)| bytes.len() as u64).sum();
    assert_eq!(
        failure.partial.charged.bytes, total,
        "{row}: the charge is the bytes on disk"
    );
    let whole: u64 = failure.partial.files.iter().map(|file| file.length).sum();
    let flying = failure.partial.in_flight.as_ref().map(|flight| {
        let leaf = flight.relative.rsplit('/').next().expect("a leaf");
        let found = on_disk
            .iter()
            .find(|(name, _)| name == leaf)
            .unwrap_or_else(|| panic!("{row}: the file in flight is on disk"));
        assert_eq!(
            found.1.len() as u64,
            flight.written,
            "{row}: the file in flight is on disk at its written count"
        );
        flight.written
    });
    assert_eq!(whole + flying.unwrap_or(0), total, "{row}: the facts");
    let entries = 5 + failure.partial.files.len() as u64 + u64::from(flying.is_some());
    assert_eq!(failure.partial.charged.entries, entries, "{row}: entries");
}

/// A short write: each write call accepts at most five bytes, as signals, quotas, and some filesystems make
/// it. A 16-byte chunk is written five, five, five, and one.
fn short_writes_of_five() -> GitSeamGuardV1 {
    override_object_fault_for_test(ObjectFaultV1::ShortWrites(5))
}

/// Short writes, an interruption of each kind of call, and 16-byte chunks: the run a signal-prone or
/// network filesystem gives. The first calls of the first file are interrupted (two of each kind).
fn retry_script() -> Vec<GitSeamGuardV1> {
    vec![
        override_object_copy_chunk_for_test(16),
        short_writes_of_five(),
        interrupt_object_calls_for_test(ObjectCallV1::Read, 2),
        interrupt_object_calls_for_test(ObjectCallV1::Write, 2),
        interrupt_object_calls_for_test(ObjectCallV1::Probe, 2),
    ]
}

/// A write that accepts only a prefix of a chunk and then returns AFTER the deadline is followed by no second
/// write: the file keeps exactly the accepted prefix, the ledger and the facts keep exactly those bytes
/// charged (the rest of the 16-byte chunk, reserved and never written, is given back), and nothing after the
/// file is created. The write that completes the chunk leaves nothing to give back.
#[test]
fn b2a_a_slow_short_write_keeps_exactly_the_accepted_prefix_and_makes_no_second_write() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (row, slow_write, accepted) in [
        ("the first write took five of sixteen", 1_usize, 5_u64),
        ("the second write took five more", 2, 10),
        ("the third write took five more", 3, 15),
        ("the fourth write completed the chunk", 4, 16),
    ] {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let names = case.entry_names();
        let output = stored(&case.dest, &names[5]);
        let original = std::fs::read(admitted_path(&case.dest.bootstrap(), "pack"))
            .expect("the admitted pack");
        let _fault = short_writes_of_five();
        let deadline = Instant::now() + B2A_SLOW_CALL_DEADLINE_V1;
        let clock = CallClockV1::watch(
            deadline,
            Some(("write", slow_write, &output)),
            Duration::ZERO,
        );
        let failure = timed_out(row, case.attempt_by(deadline));
        assert!(clock.fired(), "{row}: the slow write never ran");
        assert_eq!(
            clock.after_the_slow_call(),
            Vec::<String>::new(),
            "{row}: a call followed the write that returned after the deadline"
        );
        assert_eq!(clock.count("write"), slow_write, "{row}: no second write");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the pack in flight");
        assert_eq!(flight.written, accepted, "{row}: the retained fact");
        let on_disk = std::fs::read(&output).expect("the partial pack");
        assert_eq!(on_disk.len() as u64, accepted, "{row}: the file on disk");
        assert_eq!(&original[..on_disk.len()], &on_disk[..], "{row}: a prefix");
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: 6,
                bytes: accepted
            },
            "{row}: exactly the accepted bytes stay charged"
        );
        assert!(failure.partial.files.is_empty(), "{row}");
        assert_eq!(listing(&pack_directory(&case.dest)).len(), 1, "{row}");
        assert_charge_is_the_disk(row, &case, &failure);
    }
}

/// An interrupted read or write returns without having done anything, and it is retried only while the
/// deadline is still ahead: an interruption that returns after it is followed by no further call on that
/// descriptor. A write interrupted that way gives back all of its chunk's reservation; one that follows an
/// accepted prefix keeps exactly that prefix.
#[test]
fn b2a_an_interrupted_read_or_write_is_never_retried_after_the_deadline() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    struct SlowCallRowV1 {
        row: &'static str,
        /// The kind of call interrupted, and how many of its first calls are.
        interrupted: (ObjectCallV1, u32),
        /// Whether the writes are also short (five bytes at most).
        short: bool,
        /// The call made slow: its label and its number among the pack's calls of that label.
        slow: (&'static str, usize),
        /// The calls that ran, and the bytes the file accepted.
        reads: usize,
        writes: usize,
        accepted: u64,
    }
    let rows = [
        SlowCallRowV1 {
            row: "the first read was interrupted and slow",
            interrupted: (ObjectCallV1::Read, 3),
            short: false,
            slow: ("read", 1),
            reads: 1,
            writes: 0,
            accepted: 0,
        },
        SlowCallRowV1 {
            row: "the third read was interrupted and slow, after two prompt retries",
            interrupted: (ObjectCallV1::Read, 3),
            short: false,
            slow: ("read", 3),
            reads: 3,
            writes: 0,
            accepted: 0,
        },
        SlowCallRowV1 {
            row: "the first write was interrupted and slow",
            interrupted: (ObjectCallV1::Write, 3),
            short: false,
            slow: ("write", 1),
            reads: 1,
            writes: 1,
            accepted: 0,
        },
        SlowCallRowV1 {
            row: "the third write was interrupted and slow, after two prompt retries",
            interrupted: (ObjectCallV1::Write, 3),
            short: false,
            slow: ("write", 3),
            reads: 1,
            writes: 3,
            accepted: 0,
        },
        SlowCallRowV1 {
            row: "an interrupted write, then five of sixteen accepted slowly",
            interrupted: (ObjectCallV1::Write, 1),
            short: true,
            slow: ("write", 2),
            reads: 1,
            writes: 2,
            accepted: 5,
        },
    ];
    for SlowCallRowV1 {
        row,
        interrupted: (call, interruptions),
        short,
        slow: (label, nth),
        reads,
        writes,
        accepted,
    } in rows
    {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let names = case.entry_names();
        let output = stored(&case.dest, &names[5]);
        let _interrupts = interrupt_object_calls_for_test(call, interruptions);
        let _short = short.then(short_writes_of_five);
        let deadline = Instant::now() + B2A_SLOW_CALL_DEADLINE_V1;
        let clock = CallClockV1::watch(deadline, Some((label, nth, &output)), Duration::ZERO);
        let failure = timed_out(row, case.attempt_by(deadline));
        assert!(clock.fired(), "{row}: the slow call never ran");
        assert_eq!(
            clock.after_the_slow_call(),
            Vec::<String>::new(),
            "{row}: a call followed the interruption that returned after the deadline"
        );
        assert_eq!(clock.count("read"), reads, "{row}: reads");
        assert_eq!(clock.count("write"), writes, "{row}: writes");
        assert_eq!(clock.count("probe"), 0, "{row}: probes");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the pack in flight");
        assert_eq!(flight.written, accepted, "{row}: the retained fact");
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: 6,
                bytes: accepted
            },
            "{row}: nothing reserved and never written stays charged"
        );
        assert_eq!(
            std::fs::metadata(&output).expect("the pack").len(),
            accepted,
            "{row}: the file on disk"
        );
        let BootstrapObjectsV1::Captured { files, .. } = &case.boot.objects else {
            panic!("a Captured bootstrap");
        };
        let read_so_far = (&files[0].file).stream_position().expect("a position");
        assert_eq!(
            read_so_far,
            if call == ObjectCallV1::Read { 0 } else { 16 },
            "{row}: the source was read once, or not at all"
        );
        assert_charge_is_the_disk(row, &case, &failure);
    }
}

/// The length probe is held to the deadline before EVERY call, the first included: a last write that
/// returns after the deadline is followed by no probe, and an interrupted probe that returns after it is
/// not retried. The file is whole on disk and fully charged, and it is not a completed copy.
#[test]
fn b2a_the_length_probe_is_never_called_after_the_deadline() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    // (row, interruptions of the probe, the slow call's label and number, probes that ran)
    for (row, interruptions, (label, nth), probes) in [
        (
            "the last write returned after the deadline",
            0_u32,
            ("write", 1_usize),
            0_usize,
        ),
        (
            "the first probe was interrupted and slow",
            2,
            ("probe", 1),
            1,
        ),
        (
            "the second probe was interrupted and slow",
            2,
            ("probe", 2),
            2,
        ),
    ] {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let lengths = case.lengths();
        assert!(
            lengths[0] as usize <= HASH_BUFFER_BYTES_V1,
            "the pack is one chunk, so its first write is its last"
        );
        let names = case.entry_names();
        let output = stored(&case.dest, &names[5]);
        let _interrupts = interrupt_object_calls_for_test(ObjectCallV1::Probe, interruptions);
        let deadline = Instant::now() + B2A_SLOW_CALL_DEADLINE_V1;
        let clock = CallClockV1::watch(deadline, Some((label, nth, &output)), Duration::ZERO);
        let failure = timed_out(row, case.attempt_by(deadline));
        assert!(clock.fired(), "{row}: the slow call never ran");
        assert_eq!(
            clock.after_the_slow_call(),
            Vec::<String>::new(),
            "{row}: a call followed the call that returned after the deadline"
        );
        assert_eq!(clock.count("read"), 1, "{row}");
        assert_eq!(clock.count("write"), 1, "{row}");
        assert_eq!(clock.count("probe"), probes, "{row}: probes");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the pack in flight");
        assert_eq!(
            (flight.written, flight.expected_length),
            (lengths[0], lengths[0]),
            "{row}: the file is whole"
        );
        assert!(
            failure.partial.files.is_empty(),
            "{row}: not a completed copy"
        );
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: 6,
                bytes: lengths[0]
            },
            "{row}"
        );
        assert_charge_is_the_disk(row, &case, &failure);
    }
}

/// Every call of a run full of interruptions and short writes, made slow in turn, is the last call: the
/// calls of the first chunk (where every interruption falls), of the last chunk, and of the probe, and the
/// first call of the next file. Whichever returns after the deadline, the run refuses with a timeout, no call
/// follows it, and the charge is exactly the bytes on disk.
#[test]
fn b2a_no_read_write_or_probe_follows_a_call_that_returned_after_the_deadline() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let mut learn = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let names = learn.entry_names();
    let pack = stored(&learn.dest, &names[5]);
    let idx = stored(&learn.dest, &names[6]);
    let (pack_calls, idx_calls) = {
        let _script = retry_script();
        let clock = CallClockV1::watch(far_deadline(), None, Duration::ZERO);
        let _ = learn.done("a clean scripted run");
        (clock.labels_on(&pack), clock.labels_on(&idx))
    };
    let total = pack_calls.len();
    assert!(total > 24, "the pack spans many chunks: {total} calls");
    assert_eq!(
        pack_calls.iter().filter(|label| **label == "probe").count(),
        3,
        "two interrupted probes and the real one"
    );
    assert!(!idx_calls.is_empty());
    let mut chosen: Vec<usize> = (1..=9).chain(total - 7..=total).collect();
    chosen.dedup();
    for nth in chosen {
        let row = format!("call {nth} of {total}: {}", pack_calls[nth - 1]);
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        // This run's own pack: every case has a destination of its own.
        let target = stored(&case.dest, &case.entry_names()[5]);
        let _script = retry_script();
        let deadline = Instant::now() + B2A_LATE_ROW_DEADLINE_V1;
        // Counts every call on the pack, whatever its kind: the slow one is the `nth` of them.
        let counted = std::rc::Rc::new(std::cell::Cell::new(0_usize));
        let calls = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
        let slowed = std::rc::Rc::new(std::cell::Cell::new(false));
        let (seen, log, flag) = (counted.clone(), calls.clone(), slowed.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::ObjectIo, move |event| {
            if flag.get() {
                log.borrow_mut()
                    .push(format!("{} {:?}", event.label, event.path));
                return;
            }
            if event.path == target {
                seen.set(seen.get() + 1);
                if seen.get() == nth {
                    flag.set(true);
                    pass_the_deadline(deadline);
                }
            }
        });
        let failure = timed_out(&row, case.attempt_by(deadline));
        assert!(slowed.get(), "{row}: the slow call never ran");
        assert_eq!(
            *calls.borrow(),
            Vec::<String>::new(),
            "{row}: a call followed it"
        );
        assert_eq!(counted.get(), nth, "{row}");
        assert!(
            failure.partial.files.is_empty(),
            "{row}: the pack is in flight"
        );
        assert_charge_is_the_disk(&row, &case, &failure);
    }
}

/// With headroom, the same run of interruptions and short writes completes: every interrupted call is
/// retried, every short write is continued to the whole chunk, the files are the admitted bytes, and both
/// copies' charge is exactly what is on disk, with the brief delays of a slow filesystem at every call.
#[test]
fn b2a_interrupted_and_short_calls_with_headroom_copy_exactly_and_conserve_the_ledger() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (row, pause) in [
        ("no delay", Duration::ZERO),
        ("a millisecond at every call", Duration::from_millis(1)),
    ] {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let lengths = case.lengths();
        let expected = bootstrap_object_files(&case.dest);
        let _script = retry_script();
        let deadline = Instant::now() + 10 * B2A_DEADLINE_V1;
        let clock = CallClockV1::watch(deadline, None, pause);
        let done = case
            .attempt_by(deadline)
            .unwrap_or_else(|failure| panic!("{row}: headroom must succeed: {:?}", failure.cause));
        assert_eq!(
            files_in(&pack_directory(&case.dest)),
            expected,
            "{row}: the exact bytes"
        );
        assert_eq!(
            done.charged,
            ObjectStoreChargeV1 {
                entries: 8,
                bytes: lengths.iter().sum()
            },
            "{row}"
        );
        // The calls a 16-byte chunk and five-byte writes take, plus the injected interruptions (two of each
        // kind, all on the first file), and one probe per file.
        let chunks: Vec<u64> = lengths.iter().map(|length| length.div_ceil(16)).collect();
        let writes: u64 = lengths
            .iter()
            .map(|length| {
                (0..length.div_ceil(16))
                    .map(|chunk| (length - chunk * 16).min(16).div_ceil(5))
                    .sum::<u64>()
            })
            .sum();
        assert_eq!(
            clock.count("read") as u64,
            chunks.iter().sum::<u64>() + 2,
            "{row}: reads"
        );
        assert_eq!(clock.count("write") as u64, writes + 2, "{row}: writes");
        assert_eq!(clock.count("probe"), 3 + 2, "{row}: probes");
    }
}

/// A write that FAILS after interruptions or short writes still conserves the ledger exactly: the bytes the
/// file accepted stay charged and reported (a failure and a zero-length write are the same refusal as
/// before, never a loop, and never a timeout while the deadline is ahead), and the rest of the chunk is given
/// back. The interruptions before it are retried.
#[test]
fn b2a_a_write_failure_after_retries_and_short_writes_conserves_the_ledger() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    // (row, the interrupted kind and count, the failure, the bytes the file accepted, reads, writes)
    for (row, interruptions, fault, accepted, reads, writes) in [
        (
            "two interrupted writes, then five bytes, then an I/O error",
            (ObjectCallV1::Write, 2_u32),
            ObjectFaultV1::WriteAfter(5),
            5_u64,
            1_usize,
            4_usize,
        ),
        (
            "an interrupted write, then seven bytes, then a zero-length write",
            (ObjectCallV1::Write, 1),
            ObjectFaultV1::WriteZeroAfter(7),
            7,
            1,
            3,
        ),
        (
            "interrupted reads, a whole chunk, then four bytes and an I/O error",
            (ObjectCallV1::Read, 2),
            ObjectFaultV1::WriteAfter(20),
            20,
            4,
            3,
        ),
    ] {
        let mut case = StoreCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let names = case.entry_names();
        let original = std::fs::read(admitted_path(&case.dest.bootstrap(), "pack"))
            .expect("the admitted pack");
        let _interrupts = interrupt_object_calls_for_test(interruptions.0, interruptions.1);
        let _fault = override_object_fault_for_test(fault);
        let clock = CallClockV1::watch(far_deadline(), None, Duration::ZERO);
        let failure = case.refused(row);
        match &failure.cause {
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Io(detail)) => {
                assert!(detail.contains(".pack"), "{row}: {detail}");
            }
            other => panic!("{row}: {other:?}"),
        }
        assert_eq!(
            (
                clock.count("read"),
                clock.count("write"),
                clock.count("probe")
            ),
            (reads, writes, 0),
            "{row}: the interrupted calls were retried, and nothing else ran"
        );
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the pack in flight");
        assert_eq!(flight.written, accepted, "{row}: the retained fact");
        let on_disk = std::fs::read(stored(&case.dest, &names[5])).expect("the partial pack");
        assert_eq!(&original[..on_disk.len()], &on_disk[..], "{row}: a prefix");
        assert_eq!(
            failure.partial.charged,
            ObjectStoreChargeV1 {
                entries: 6,
                bytes: accepted
            },
            "{row}: exactly the bytes that reached the file stay charged"
        );
        assert_charge_is_the_disk(row, &case, &failure);
    }
}

// ---------------------------------------------------------------------------------------------
// Structure: B2a's region creates and charges, and only that

/// STRUCTURAL ONLY. B2a's region (the production source from its marker on, up to the end of the file) is
/// held to its own vocabulary, because B1a's read-only scan and B1b's pure scan now end at this marker: it
/// opens no path, walks nothing, runs no Git child or process, routes no object store, renames, removes,
/// truncates, links, or re-permissions nothing, has no unsafe, and names no bootstrap HEAD, config, or hook.
/// Everything it creates is create-new beneath a retained pin. The marker is unique, follows B1b's region,
/// and the region holds the entry point. The behavior is proven by the rows above, which run the code.
#[test]
fn b2a_the_object_store_region_is_create_new_only_and_the_split_is_unique() {
    let source = include_str!("custody_restore_git.rs");
    assert_eq!(source.matches(B2A_MARKER_V1).count(), 1, "one marker");
    assert_eq!(source.matches(B1B_MARKER_V1).count(), 1, "one B1b marker");
    let (before, region) = source.split_once(B2A_MARKER_V1).expect("the marker");
    // B2b's region, which restores and names the metadata, is outside this object-store scan; its own scan
    // covers it.
    let (region, _later) = region
        .split_once(B2B_MARKER_V1)
        .expect("the B2b marker follows B2a's region");
    assert!(before.contains(B1B_MARKER_V1), "B2a follows B1b");
    assert!(before.contains("pub(crate) fn encode_inert_config_v1("));
    assert!(region.contains("pub(crate) fn materialize_object_store_v1("));
    assert!(
        !before.contains("materialize_object_store_v1("),
        "the earlier passes do not call B2a"
    );
    let code: String = region
        .lines()
        .filter(|line| !line.trim_start().starts_with("//"))
        .collect::<Vec<_>>()
        .join("\n");
    for forbidden in [
        "std::fs",
        "File::open(",
        "OpenOptions",
        "read_dir(",
        "GitRunnerV1",
        "GitRunRequestV1",
        "GitCommandV1",
        "GitObjectStoreRouteV1",
        "remeasure_git_directory",
        "measure_git_directory",
        "walk",
        "Command",
        "spawn",
        "std::process",
        "mkdir",
        "rename",
        "remove_file",
        "remove_dir",
        "unlink",
        "set_len",
        "truncate",
        "hard_link",
        "symlink(",
        "set_permissions",
        "unsafe",
        "WorkV1",
        "OwnedChargeV1",
        "settle_to",
        "\"HEAD\"",
        "\"config\"",
        "\"hooks\"",
        "\"refs\"",
    ] {
        assert!(
            !code.contains(forbidden),
            "the object-store region mentions `{forbidden}`"
        );
    }
    // What it does use: create-new beneath retained pins, the one deadline, and the one ledger.
    for required in [
        "create_staging_directory(",
        "create_new_regular_child(",
        "observe_deadline(",
        "before_deadline(",
        "stream_digest(",
        "sync_all(",
        "pack.sync(",
        "reserve_entries(",
        ".reserve(",
        "sweep_chains(",
        "refuse_mounts_within(",
    ] {
        assert!(
            code.contains(required),
            "the object-store region lacks `{required}`"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Pass B2b: the exact active metadata and the final ref agreement
//
// Every row drives `materialize_active_metadata_v1` over a REAL retained value: a real phase-V capsule (real
// Git objects and a real pack with real active frames, or an Empty object database with a captured unborn
// HEAD), carried through pass A's real bootstrap, B1a's real prevalidation, and B2a's real second object
// store. The step takes no runner, so no Git child can run in it. Every row also proves the one ledger's
// conservation: what the step reports charged is exactly what the ledger moved, on every outcome, and every
// failure's partial facts are held to the disk.
//
// Pass A's, B1a's, B1b's, and B2a's controls above are unchanged, except the B2a structural scan's region end
// (see `B2B_MARKER_V1`). The mutation matrix in `.git/a2a-evidence/2b3b-pass-b2b/` maps each guard to the
// rows that turn red without it.
// ---------------------------------------------------------------------------------------------

const B2B_MARKER_V1: &str = "// Pass B2b: exact active metadata and final ref agreement";

/// The aggregate path table's default byte bound (the production default, restated: it is private there), and
/// the fixed allowance per entry it adds to each path's two copies.
const B2B_TABLE_BOUND_V1: u64 = 64 * 1024 * 1024;
const B2B_ENTRY_OVERHEAD_V1: u64 = 64;

/// The step a flow that ran the object copy has completed: B2b is called after it.
const B2B_COMPLETED_V1: Option<GitPlaneStepV1> = Some(GitPlaneStepV1::Objects);

/// One entry of a frame spec.
#[derive(Clone)]
enum SpecKindV1 {
    Dir,
    File(Vec<u8>),
    Link(Vec<u8>),
}

/// One frame's entries, in the order given.
#[derive(Clone, Default)]
struct FrameSpecV1 {
    entries: Vec<(String, SpecKindV1)>,
}

impl FrameSpecV1 {
    fn new() -> Self {
        Self::default()
    }

    fn dir(mut self, path: &str) -> Self {
        self.entries.push((path.to_owned(), SpecKindV1::Dir));
        self
    }

    fn file(mut self, path: &str, bytes: impl AsRef<[u8]>) -> Self {
        self.entries
            .push((path.to_owned(), SpecKindV1::File(bytes.as_ref().to_vec())));
        self
    }

    fn link(mut self, path: &str, target: &str) -> Self {
        self.entries.push((
            path.to_owned(),
            SpecKindV1::Link(target.as_bytes().to_vec()),
        ));
        self
    }

    /// Without the entry at `path`.
    fn without(mut self, path: &str) -> Self {
        self.entries.retain(|(found, _)| found != path);
        self
    }

    fn encode(&self, class: ClassV1, generation: &str) -> Vec<u8> {
        let borrowed: Vec<(&[u8], EntryV1<'_>)> = self
            .entries
            .iter()
            .map(|(path, kind)| {
                (
                    path.as_bytes(),
                    match kind {
                        SpecKindV1::Dir => EntryV1::Dir,
                        SpecKindV1::File(bytes) => EntryV1::File(bytes),
                        SpecKindV1::Link(target) => EntryV1::Link(target),
                    },
                )
            })
            .collect();
        encode_frame(class, generation, &borrowed)
    }
}

/// The test's own decode of one retained frame, through the real codec on a duplicate descriptor: every
/// entry in order, a directory as `None` and a regular file with its bytes. It is the oracle for what the
/// restored tree must hold, and leaves the shared descriptor at offset 0.
fn decoded_entries(
    file: &std::fs::File,
    class: ClassV1,
    generation: &str,
) -> Vec<(String, Option<Vec<u8>>)> {
    use std::io::Seek as _;
    let mut handle = file.try_clone().expect("a duplicate descriptor");
    handle.seek(SeekFrom::Start(0)).expect("rewind");
    let header = CustodyFrameHeaderV1::new(class, generation).expect("a header");
    let mut entries = Vec::new();
    {
        let reader = BufReader::new(&handle);
        let mut decoder =
            CustodyFrameDecoderV1::new(reader, &header, frame_budget()).expect("a decoder");
        while let Some(entry) = decoder.next_entry().expect("a whole frame") {
            match entry {
                CustodyFrameEntryV1::Directory { path, .. } => {
                    entries.push((path_string(path.as_bytes()), None));
                }
                CustodyFrameEntryV1::Regular {
                    path, mut content, ..
                } => {
                    let mut bytes = Vec::new();
                    std::io::Read::read_to_end(&mut content, &mut bytes).expect("its content");
                    entries.push((path_string(path.as_bytes()), Some(bytes)));
                }
                CustodyFrameEntryV1::Symlink { .. } => panic!("a symlink in an active frame"),
            }
        }
    }
    handle.seek(SeekFrom::Start(0)).expect("rewind");
    entries
}

/// The golden config bytes of the caller's format, written out independently of the encoder.
fn golden_config(format: GitObjectFormatV1) -> &'static [u8] {
    match format {
        GitObjectFormatV1::Sha1 => CONFIG_SHA1_V1,
        GitObjectFormatV1::Sha256 => CONFIG_SHA256_V1,
    }
}

impl StoreCaseV1 {
    /// A case whose active frames are `refs` (and `logs`), and whose manifest lists `manifest_refs`: carried
    /// through pass A, B1a, and a real phase-V value exactly as [`StoreCaseV1::of`] does.
    fn with_frames(
        capsule: &CustomCapsuleV1,
        cformat: CustodyGitObjectFormatV1,
        refs: &FrameSpecV1,
        logs: Option<&FrameSpecV1>,
        manifest_refs: Vec<CustodyOriginalRefV1>,
    ) -> Self {
        let format = core_format(cformat);
        let generation = CaseV1::generation(capsule);
        let mut frames = vec![(REFS_V1, refs.encode(REFS_V1, &generation))];
        if let Some(logs) = logs {
            frames.push((LOGS_V1, logs.encode(LOGS_V1, &generation)));
        }
        let CaseV1 { dest, mut verified } = CaseV1::with_bytes(capsule, &frames);
        set_refs(&mut verified, manifest_refs);
        let phase_v_used = ledger_used(&verified);
        let mut boot = must_bootstrap(verified, format);
        let plan = prevalidate(&mut boot.verified, far_deadline()).expect("B1a admits the frames");
        Self {
            dest,
            boot,
            plan,
            format,
            phase_v_used,
        }
    }
}

/// A real phase-V value carried through pass A, B1a, and B2a: exactly what a later flow holds when it calls
/// the metadata step.
struct MetaCaseV1 {
    store: StoreCaseV1,
    objects: FinalObjectStoreV1,
    format: GitObjectFormatV1,
    /// The frame budget the step is given.
    budget: CustodyFrameBudgetV1,
}

fn meta_charge(charged: MetadataChargeV1) -> u64 {
    charged.entries * ENTRY_V1 + charged.bytes
}

impl MetaCaseV1 {
    fn from_store(mut store: StoreCaseV1) -> Self {
        let objects = store.done("the object copy");
        let format = store.format;
        Self {
            store,
            objects,
            format,
            budget: frame_budget(),
        }
    }

    /// The rich real frames of a Captured capsule, or the refs-only frames of an Empty one.
    fn of(capsule: &CustomCapsuleV1, cformat: CustodyGitObjectFormatV1) -> Self {
        Self::from_store(StoreCaseV1::of(capsule, cformat))
    }

    fn with_frames(
        capsule: &CustomCapsuleV1,
        cformat: CustodyGitObjectFormatV1,
        refs: &FrameSpecV1,
        logs: Option<&FrameSpecV1>,
        manifest_refs: Vec<CustodyOriginalRefV1>,
    ) -> Self {
        Self::from_store(StoreCaseV1::with_frames(
            capsule,
            cformat,
            refs,
            logs,
            manifest_refs,
        ))
    }

    fn ledger(&self) -> u64 {
        self.store.ledger()
    }

    fn dest(&self) -> &DestV1 {
        &self.store.dest
    }

    fn git(&self) -> PathBuf {
        stored(&self.store.dest, "repository/.git")
    }

    fn meta(&self, relative: &str) -> PathBuf {
        self.git().join(relative)
    }

    /// The real entry point under `deadline`, with EVERY outcome held to the step's contract: a success
    /// reports the config step; a refusal carries the one ledger's charge; and the ledger moved by exactly
    /// what the step reports it charged.
    fn attempt_with(
        &mut self,
        deadline: Instant,
        completed: Option<GitPlaneStepV1>,
        table_bound: u64,
        limits: RefsLimitsV1,
    ) -> Result<FinalMetadataV1, Box<MetadataFailureV1>> {
        let before = self.ledger();
        let result = materialize_active_metadata_bounded_v1(
            &self.store.boot,
            &self.objects,
            &self.store.plan,
            self.budget,
            deadline,
            completed,
            table_bound,
            limits,
        );
        let moved = self.ledger() - before;
        match &result {
            Ok(done) => {
                assert_eq!(done.step, GitPlaneStepV1::Config);
                assert_eq!(
                    moved,
                    meta_charge(done.charged),
                    "the ledger moved as reported"
                );
            }
            Err(failure) => {
                assert_eq!(failure.ledger_used, self.ledger(), "the failure's figure");
                assert_eq!(
                    moved,
                    meta_charge(failure.partial.charged),
                    "{:?}: the ledger moved as reported",
                    failure.cause
                );
            }
        }
        result
    }

    fn attempt_by(&mut self, deadline: Instant) -> Result<FinalMetadataV1, Box<MetadataFailureV1>> {
        self.attempt_with(
            deadline,
            B2B_COMPLETED_V1,
            B2B_TABLE_BOUND_V1,
            RefsLimitsV1::v1(),
        )
    }

    fn attempt(&mut self) -> Result<FinalMetadataV1, Box<MetadataFailureV1>> {
        self.attempt_by(far_deadline())
    }

    fn done(&mut self, row: &str) -> FinalMetadataV1 {
        match self.attempt() {
            Ok(done) => done,
            Err(failure) => panic!("{row}: must succeed: {:?}", failure.cause),
        }
    }

    fn refused(&mut self, row: &str) -> Box<MetadataFailureV1> {
        match self.attempt() {
            Ok(_) => panic!("{row}: must refuse"),
            Err(failure) => failure,
        }
    }

    /// The restored tree the retained frames must produce, by the test's own decode: every entry of every
    /// active frame, by its path beneath `.git`.
    fn expected_frames(&self) -> BTreeMap<String, Option<Vec<u8>>> {
        let generation = self.store.boot.verified.control.manifest.generation_id();
        let mut tree = BTreeMap::new();
        for frame in &self.store.boot.active_frames {
            let one = &self.store.boot.verified.staged[frame.staged];
            for (path, content) in decoded_entries(&one.file, frame.class, generation) {
                tree.insert(path, content);
            }
        }
        tree
    }

    /// What is on disk beneath `.git` except the object store the earlier pass made.
    fn metadata_on_disk(&self) -> BTreeMap<String, Option<Vec<u8>>> {
        let mut tree = snapshot(&self.git());
        tree.retain(|name, _| name != "objects" && !name.starts_with("objects/"));
        tree
    }

    fn entry_count(&self) -> usize {
        self.metadata_on_disk().len()
    }

    /// A refusal that began nothing: no entry was created, pinned, or charged by the step, and the destination
    /// tree and the one ledger are exactly what they were.
    fn refused_before_any_write(&mut self, row: &str) -> GitBootstrapErrorV1 {
        let tree = snapshot(&self.dest().path);
        let ledger = self.ledger();
        let failure = self.refused(row);
        assert!(
            !failure.active_materialization_began,
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(failure.partial.charged, none_charged(), "{row}");
        assert!(failure.partial.files.is_empty(), "{row}");
        assert!(failure.partial.in_flight.is_none(), "{row}");
        assert!(failure.partial.directories.is_empty(), "{row}");
        assert_eq!(self.ledger(), ledger, "{row}: the ledger");
        assert_eq!(
            snapshot(&self.dest().path),
            tree,
            "{row}: a byte was written"
        );
        failure.cause
    }
}

/// A refusal's partial facts are the disk: every pinned directory and every whole file is on disk, the file
/// in flight is on disk at exactly its `written` count, nothing else exists beneath `.git` but the object
/// store, and the charge is exactly the entries and bytes on disk (plus `unlisted` entries the facts cannot
/// carry: an entry created and then refused before its pin existed). Only for rows where nothing is planted.
fn assert_metadata_partial_is_the_disk(
    row: &str,
    case: &MetaCaseV1,
    failure: &MetadataFailureV1,
    unlisted: u64,
) {
    let on_disk = case.metadata_on_disk();
    let mut listed = 0_u64;
    let mut bytes = 0_u64;
    for relative in failure.partial.directories.keys() {
        assert_eq!(
            on_disk.get(relative),
            Some(&None),
            "{row}: directory {relative}"
        );
        listed += 1;
    }
    for file in &failure.partial.files {
        use std::io::Seek as _;
        if failure.last_completed <= Some(GitPlaneStepV1::Objects) {
            assert_eq!(
                (&file.file).stream_position().expect("a position"),
                0,
                "{row}: {}: a whole file is retained at offset 0",
                file.relative
            );
        }
        let found = on_disk
            .get(&file.relative)
            .unwrap_or_else(|| panic!("{row}: {} is not on disk", file.relative));
        assert_eq!(
            found.as_ref().map(|found| found.len() as u64),
            Some(file.length),
            "{row}: {}",
            file.relative
        );
        listed += 1;
        bytes += file.length;
    }
    if let Some(flight) = &failure.partial.in_flight {
        let found = on_disk
            .get(&flight.relative)
            .unwrap_or_else(|| panic!("{row}: the file in flight is not on disk"));
        assert_eq!(
            found.as_ref().map(|found| found.len() as u64),
            Some(flight.written),
            "{row}: the file in flight is on disk at its written count"
        );
        assert!(flight.written <= flight.expected_length, "{row}");
        listed += 1;
        bytes += flight.written;
    }
    assert_eq!(
        on_disk.len() as u64,
        listed + unlisted,
        "{row}: {:?}: every entry on disk is in the facts",
        failure.cause
    );
    assert_eq!(
        failure.partial.charged,
        MetadataChargeV1 {
            entries: listed + unlisted,
            bytes
        },
        "{row}: the charge is the disk"
    );
}

/// The real-shaped refs of a Captured capsule as specs (the same content as `real_state`), and its manifest
/// refs: an attached `HEAD` on a loose `refs/heads/main`, `ORIG_HEAD`, a packed `refs/heads/side` and
/// `refs/tags/v1` (the real annotated tag, peeled to the real commit), and reflogs.
struct RealSpecsV1 {
    commit: String,
    tag: String,
    refs: FrameSpecV1,
    logs: FrameSpecV1,
    manifest_refs: Vec<CustodyOriginalRefV1>,
}

fn real_specs(capsule: &CustomCapsuleV1, format: GitObjectFormatV1) -> RealSpecsV1 {
    let commit = real_object(capsule, KindV1::Commit);
    let tag = real_object(capsule, KindV1::Tag);
    let (commit_id, tag_id) = (commit.object_id().to_owned(), tag.object_id().to_owned());
    let loose = format!("{commit_id}\n");
    let packed_text = format!(
        "{PACKED_HEADER_V1}{commit_id} refs/heads/side\n{tag_id} refs/tags/v1\n^{commit_id}\n"
    );
    let zero = "0".repeat(oid_len(format));
    let log = format!("{zero} {commit_id} {IDENT_V1}\tbranch: Created from main\n");
    RealSpecsV1 {
        commit: commit_id,
        tag: tag_id,
        refs: FrameSpecV1::new()
            .file("HEAD", "ref: refs/heads/main\n")
            .file("ORIG_HEAD", &loose)
            .file("packed-refs", &packed_text)
            .dir("refs")
            .dir("refs/heads")
            .file("refs/heads/main", &loose)
            .dir("refs/tags"),
        logs: FrameSpecV1::new()
            .dir("logs")
            .file("logs/HEAD", &log)
            .dir("logs/refs")
            .dir("logs/refs/heads")
            .file("logs/refs/heads/main", &log),
        manifest_refs: vec![
            symbolic_ref("HEAD", "refs/heads/main"),
            direct_ref("ORIG_HEAD", &commit),
            direct_ref("refs/heads/main", &commit),
            direct_ref("refs/heads/side", &commit),
            direct_ref("refs/tags/v1", &tag),
        ],
    }
}

/// The destination-relative names of the files a case's frames carry, in the order a restore creates them,
/// and its directories: from the test's own decode.
fn expected_names(case: &MetaCaseV1) -> (Vec<String>, Vec<String>) {
    let (mut files, mut directories) = (Vec::new(), Vec::new());
    let generation = case.store.boot.verified.control.manifest.generation_id();
    for frame in &case.store.boot.active_frames {
        let one = &case.store.boot.verified.staged[frame.staged];
        for (path, content) in decoded_entries(&one.file, frame.class, generation) {
            if content.is_some() {
                files.push(path);
            } else {
                directories.push(path);
            }
        }
    }
    (files, directories)
}

// ---------------------------------------------------------------------------------------------
// The exact restored metadata, both formats, both object shapes
// ---------------------------------------------------------------------------------------------

/// Real SHA-1 and SHA-256 capsules (real Git objects, a real pack, real frames) restore their active metadata
/// byte for byte beneath the retained `.git`: every directory and regular file of both frames, HEAD,
/// ORIG_HEAD, packed-refs, the loose ref, and both reflogs, then the golden config of the caller's format.
/// The refs agree with all five manifest refs, read from the retained final descriptors. The repository's
/// only child stays `.git`, the object copy and the bootstrap are untouched, no Git child ran, and the facts
/// are exact: each pin is the directory, each file's descriptor is at offset 0 and reads the bytes, and the
/// one ledger moved by exactly the entries and bytes created.
#[test]
fn b2b_the_real_frames_restore_byte_exact_in_both_formats_with_the_exact_facts() {
    use std::io::Seek as _;
    use std::os::unix::fs::MetadataExt as _;
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let row = format!("{cformat:?}");
        let capsule = captured(cformat);
        let mut case = MetaCaseV1::of(&capsule, cformat);
        assert_eq!(
            case.store.boot.provenance,
            GitFormatProvenanceV1::CapsuleObjectsAndPack
        );
        let format = case.format;
        let expected = case.expected_frames();
        assert_eq!(expected.len(), 12, "{row}: six directories and six files");
        let work_before = snapshot(&case.dest().work());
        let objects_before: BTreeMap<_, _> = snapshot(&case.git())
            .into_iter()
            .filter(|(name, _)| name == "objects" || name.starts_with("objects/"))
            .collect();
        let ledger_before = case.ledger();
        let children = case.store.boot.runs.len();
        let (file_names, directory_names) = expected_names(&case);

        let done = case.done(&row);

        // The exact tree: the frames' entries byte for byte, and the golden config; nothing else.
        let mut want = expected.clone();
        want.insert("config".to_owned(), Some(golden_config(format).to_vec()));
        assert_eq!(case.metadata_on_disk(), want, "{row}");
        assert_eq!(
            listing(&case.git()),
            [
                "HEAD",
                "ORIG_HEAD",
                "config",
                "logs",
                "objects",
                "packed-refs",
                "refs"
            ],
            "{row}"
        );
        assert_eq!(
            listing(&stored(case.dest(), "repository")),
            [".git"],
            "{row}: the repository's only child is .git"
        );
        assert_eq!(
            case.dest().entries(),
            [".restore-work", "repository"],
            "{row}"
        );
        assert_eq!(
            std::fs::read(case.meta("HEAD")).expect("HEAD"),
            b"ref: refs/heads/main\n",
            "{row}"
        );

        // The facts: the frames' files in order, then the config; every directory pinned.
        assert_eq!(done.step, GitPlaneStepV1::Config);
        let mut relatives: Vec<&str> = done
            .files
            .iter()
            .map(|file| file.relative.as_str())
            .collect();
        assert_eq!(relatives.pop(), Some("config"), "{row}: the config is last");
        assert_eq!(relatives, file_names, "{row}: creation order");
        assert_eq!(
            done.directories.keys().cloned().collect::<Vec<_>>(),
            {
                let mut sorted = directory_names.clone();
                sorted.sort();
                sorted
            },
            "{row}"
        );
        for (relative, pin) in &done.directories {
            assert_pin_is(pin, &case.meta(relative));
        }
        for file in &done.files {
            let path = case.meta(&file.relative);
            let bytes = std::fs::read(&path).expect("a restored file");
            let metadata = std::fs::metadata(&path).expect("metadata");
            assert_eq!(file.length, bytes.len() as u64, "{row}: {}", file.relative);
            assert_eq!(
                file.sha256,
                sha256_bytes(&bytes),
                "{row}: {}",
                file.relative
            );
            assert_eq!(
                (file.dev, file.ino),
                (metadata.dev(), metadata.ino()),
                "{row}: {}",
                file.relative
            );
            assert_eq!((&file.file).stream_position().expect("a position"), 0);
            let mut read = Vec::new();
            (&file.file)
                .read_to_end(&mut read)
                .expect("the retained descriptor reads");
            assert_eq!(
                read, bytes,
                "{row}: {}: the retained descriptor",
                file.relative
            );
        }
        assert_eq!(
            done.config().map(|file| file.relative.as_str()),
            Some("config")
        );

        // The refs agree with every manifest ref, from the final descriptors.
        assert_eq!(
            done.agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: Some(real_object(&capsule, KindV1::Commit).object_id().to_owned()),
            },
            "{row}"
        );
        assert_eq!(
            (
                done.agreement.loose_refs,
                done.agreement.packed_refs,
                done.agreement.peeled_rows,
                done.agreement.effective_refs,
                done.agreement.manifest_refs,
                done.agreement.reflog_files,
                done.agreement.reflog_rows,
                done.agreement.direct_targets,
            ),
            (1, 2, 1, 3, 5, 2, 2, 2),
            "{row}"
        );

        // The charge: the 12 frame entries plus the config, and every byte of them; the ledger moved by it.
        let bytes: u64 = done.files.iter().map(|file| file.length).sum();
        assert_eq!(
            done.charged,
            MetadataChargeV1 { entries: 13, bytes },
            "{row}"
        );
        assert_eq!(
            case.ledger() - ledger_before,
            13 * ENTRY_V1 + bytes,
            "{row}"
        );

        // Everything earlier is untouched: the bootstrap, the object copy, and the staged descriptors.
        assert_eq!(
            snapshot(&case.dest().work()),
            work_before,
            "{row}: the bootstrap"
        );
        let objects_after: BTreeMap<_, _> = snapshot(&case.git())
            .into_iter()
            .filter(|(name, _)| name == "objects" || name.starts_with("objects/"))
            .collect();
        assert_eq!(objects_after, objects_before, "{row}: the object copy");
        assert_eq!(
            case.store.boot.runs.len(),
            children,
            "{row}: no Git child ran"
        );
        assert!(case
            .store
            .boot
            .verified
            .staged
            .iter()
            .all(|one| position(one) == 0));
        for forbidden in ["hooks", "info", "description", "shallow", "index"] {
            assert!(!exists(&case.meta(forbidden)), "{row}: {forbidden}");
        }
    }
}

/// Empty objects (no pack, an empty inventory) with a captured, valid, UNBORN HEAD restore for BOTH caller
/// formats: the refs frame's directories and HEAD byte for byte, and the golden config of the caller's
/// format (the bootstrap reports caller-selected provenance, and nothing in the capsule chose the format).
#[test]
fn b2b_empty_objects_with_a_captured_unborn_head_restore_for_both_caller_formats() {
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let row = format!("{cformat:?}");
        let capsule = empty(cformat);
        let mut case = MetaCaseV1::of(&capsule, cformat);
        assert_eq!(
            case.store.boot.provenance,
            GitFormatProvenanceV1::CallerSelectedEmpty
        );
        let format = case.format;
        let ledger_before = case.ledger();
        let done = case.done(&row);

        let mut want = BTreeMap::new();
        want.insert("HEAD".to_owned(), Some(HEAD_BYTES_V1.to_vec()));
        for directory in ["refs", "refs/heads", "refs/tags"] {
            want.insert(directory.to_owned(), None);
        }
        want.insert("config".to_owned(), Some(golden_config(format).to_vec()));
        assert_eq!(case.metadata_on_disk(), want, "{row}");
        assert_eq!(
            done.agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: None
            },
            "{row}: an unborn HEAD"
        );
        assert_eq!(
            (done.agreement.effective_refs, done.agreement.direct_targets),
            (0, 0),
            "{row}"
        );
        assert_eq!(
            done.charged,
            MetadataChargeV1 {
                entries: 5,
                bytes: HEAD_BYTES_V1.len() as u64 + golden_config(format).len() as u64
            },
            "{row}"
        );
        assert_eq!(
            case.ledger() - ledger_before,
            meta_charge(done.charged),
            "{row}"
        );
        assert_eq!(
            listing(&case.git()),
            ["HEAD", "config", "objects", "refs"],
            "{row}"
        );
        assert!(listing(&pack_directory(case.dest())).is_empty(), "{row}");
    }
}

// ---------------------------------------------------------------------------------------------
// Every head state and ref family is restored byte for byte, and agrees
// ---------------------------------------------------------------------------------------------

/// The ways the real specs vary, each with what its agreement must report.
struct FamilyV1 {
    row: &'static str,
    edit: fn(&CustomCapsuleV1, &mut RealSpecsV1),
    head: fn(&RealSpecsV1) -> HeadStateV1,
    /// loose refs, packed refs, peeled rows, effective refs, manifest refs, reflog files, FETCH_HEAD rows,
    /// direct targets.
    counts: (u64, u64, u64, u64, u64, u64, u64, u64),
}

fn edit_none(_: &CustomCapsuleV1, _: &mut RealSpecsV1) {}

/// A detached HEAD: the commit itself, listed by the manifest as a direct ref.
fn edit_detached(capsule: &CustomCapsuleV1, specs: &mut RealSpecsV1) {
    let commit = real_object(capsule, KindV1::Commit);
    specs.refs = specs
        .refs
        .clone()
        .without("HEAD")
        .file("HEAD", format!("{}\n", specs.commit));
    specs.manifest_refs[0] = direct_ref("HEAD", &commit);
}

/// An unborn branch in a Captured capsule: HEAD names `refs/heads/main`, which does not exist, and the
/// manifest says so with `Unborn`.
fn edit_unborn(_: &CustomCapsuleV1, specs: &mut RealSpecsV1) {
    specs.refs = specs.refs.clone().without("refs/heads/main");
    specs.logs = specs.logs.clone().without("logs/refs/heads/main");
    specs
        .manifest_refs
        .retain(|record| record.name().as_bytes() != b"refs/heads/main");
    specs.manifest_refs[0] = CustodyOriginalRefV1::new(
        LosslessPathV1::from_bytes(b"HEAD".to_vec()),
        CustodyRefTargetV1::Unborn,
    )
    .expect("an unborn ref");
}

/// A loose ref that shadows a packed row of the same name: the loose lightweight tag wins over the packed
/// annotated one, and the manifest lists the loose value.
fn edit_loose_over_packed(capsule: &CustomCapsuleV1, specs: &mut RealSpecsV1) {
    let commit = real_object(capsule, KindV1::Commit);
    specs.refs = specs
        .refs
        .clone()
        .file("refs/tags/v1", format!("{}\n", specs.commit));
    for record in &mut specs.manifest_refs {
        if record.name().as_bytes() == b"refs/tags/v1" {
            *record = direct_ref("refs/tags/v1", &commit);
        }
    }
}

/// FETCH_HEAD, a stash ref, and its reflog beside ORIG_HEAD and the rest.
fn edit_pseudorefs_and_stash(capsule: &CustomCapsuleV1, specs: &mut RealSpecsV1) {
    let commit = real_object(capsule, KindV1::Commit);
    let zero = "0".repeat(specs.commit.len());
    let log = format!("{zero} {} {IDENT_V1}\tWIP on main\n", specs.commit);
    specs.refs = specs
        .refs
        .clone()
        .file(
            "FETCH_HEAD",
            format!("{}\t\tbranch 'main' of origin\n", specs.commit),
        )
        .file("refs/stash", format!("{}\n", specs.commit));
    specs.logs = specs.logs.clone().file("logs/refs/stash", log);
    specs.manifest_refs.push(direct_ref("FETCH_HEAD", &commit));
    specs.manifest_refs.push(direct_ref("refs/stash", &commit));
}

fn family_head(specs: &RealSpecsV1) -> HeadStateV1 {
    HeadStateV1::Symbolic {
        target: "refs/heads/main".into(),
        resolved: Some(specs.commit.clone()),
    }
}

/// Detached, unborn, loose-over-packed, packed-only, ORIG_HEAD, FETCH_HEAD, stash, and reflogs each restore
/// byte for byte (the tree equals the test's own decode of the frames, plus the golden config) and agree with
/// the manifest from the retained final descriptors, in both formats.
#[test]
fn b2b_every_head_state_and_ref_family_restores_exactly_and_agrees() {
    let families = [
        FamilyV1 {
            row: "an attached HEAD, packed-only refs, ORIG_HEAD",
            edit: edit_none,
            head: family_head,
            counts: (1, 2, 1, 3, 5, 2, 0, 2),
        },
        FamilyV1 {
            row: "a detached HEAD",
            edit: edit_detached,
            head: |specs| HeadStateV1::Detached {
                oid: specs.commit.clone(),
            },
            counts: (1, 2, 1, 3, 5, 2, 0, 2),
        },
        FamilyV1 {
            row: "an unborn branch",
            edit: edit_unborn,
            head: |_| HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: None,
            },
            counts: (0, 2, 1, 2, 4, 1, 0, 2),
        },
        FamilyV1 {
            row: "a loose ref over a packed one",
            edit: edit_loose_over_packed,
            head: family_head,
            // The packed annotated tag is shadowed by the loose ref, so it is not an active target.
            counts: (2, 2, 1, 3, 5, 2, 0, 1),
        },
        FamilyV1 {
            row: "FETCH_HEAD, a stash ref, and its reflog",
            edit: edit_pseudorefs_and_stash,
            head: family_head,
            counts: (2, 2, 1, 4, 7, 3, 1, 2),
        },
    ];
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let capsule = captured(cformat);
        let format = core_format(cformat);
        for family in &families {
            let row = format!("{cformat:?}: {}", family.row);
            let mut specs = real_specs(&capsule, format);
            (family.edit)(&capsule, &mut specs);
            let mut case = MetaCaseV1::with_frames(
                &capsule,
                cformat,
                &specs.refs,
                Some(&specs.logs),
                specs.manifest_refs.clone(),
            );
            let mut want = case.expected_frames();
            let done = case.done(&row);
            want.insert("config".to_owned(), Some(golden_config(format).to_vec()));
            assert_eq!(case.metadata_on_disk(), want, "{row}");
            assert_eq!(done.agreement.head, (family.head)(&specs), "{row}");
            let a = &done.agreement;
            assert_eq!(
                (
                    a.loose_refs,
                    a.packed_refs,
                    a.peeled_rows,
                    a.effective_refs,
                    a.manifest_refs,
                    a.reflog_files,
                    a.fetch_head_rows,
                    a.direct_targets,
                ),
                family.counts,
                "{row}"
            );
        }
    }
}

// ---------------------------------------------------------------------------------------------
// The config is created once, last, and only after every ref is agreed
// ---------------------------------------------------------------------------------------------

/// Every entry of the metadata is created before the refs are read back, the agreement completes before the
/// config exists, and the config is created exactly once and last (nothing is created after it): the order
/// of the create events and the clock's labels shows it. The bootstrap's config is never copied: the
/// restored config is the golden bytes, whatever the bootstrap holds.
#[test]
fn b2b_the_config_is_created_once_last_and_only_after_the_refs_agree() {
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let row = format!("{cformat:?}");
        let capsule = captured(cformat);
        let mut case = MetaCaseV1::of(&capsule, cformat);
        // A hostile bootstrap config that must never reach the final repository.
        let bootstrap_config = case.dest().bootstrap().join("config");
        assert!(
            exists(&bootstrap_config),
            "{row}: the bootstrap has a config"
        );
        let planted =
            b"[core]\n\tfsmonitor = /tmp/b2b-marker\n[include]\n\tpath = /tmp/elsewhere\n";
        std::fs::write(&bootstrap_config, planted).expect("a hostile bootstrap config");
        let events = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
        let mut hooks = Vec::new();
        {
            let log = events.clone();
            hooks.push(install_git_hook_for_test(
                GitHookPointV1::BeforeObjectCreate,
                move |event| {
                    log.borrow_mut()
                        .push(format!("create {}", event.path.display()))
                },
            ));
        }
        {
            let log = events.clone();
            hooks.push(install_git_hook_for_test(
                GitHookPointV1::DeadlineObserved,
                move |event| {
                    if matches!(
                        event.label,
                        "metadata-refs" | "metadata-agreed" | "metadata-config"
                    ) {
                        log.borrow_mut().push(event.label.to_owned());
                    }
                },
            ));
        }
        let git = case.git();
        let _ = case.done(&row);
        drop(hooks);
        let events = events.borrow();
        let create_of = |name: &str| format!("create {}", git.join(name).display());
        let position_of = |wanted: &str| {
            events
                .iter()
                .position(|event| event == wanted)
                .unwrap_or_else(|| panic!("{row}: no `{wanted}` in {events:?}"))
        };
        let agreed = position_of("metadata-agreed");
        let started = position_of("metadata-refs");
        let config = position_of(&create_of("config"));
        assert_eq!(
            events
                .iter()
                .filter(|event| **event == create_of("config"))
                .count(),
            1,
            "{row}: the config is created once"
        );
        assert!(started < agreed && agreed < config, "{row}: {events:?}");
        assert_eq!(
            events.iter().position(|event| event == "metadata-config"),
            Some(agreed + 1),
            "{row}: the config step begins right after the agreement"
        );
        assert_eq!(
            config,
            events.len() - 1,
            "{row}: nothing is created after the config"
        );
        // Every other entry was created before the refs were read back.
        assert!(
            events[..started]
                .iter()
                .all(|event| event.starts_with("create ")),
            "{row}"
        );
        assert_eq!(started, events.len() - 4, "{row}: {events:?}");
        assert_eq!(
            std::fs::read(case.meta("config")).expect("the config"),
            golden_config(case.format),
            "{row}: the golden bytes, never the bootstrap's"
        );
        assert_eq!(
            std::fs::read(&bootstrap_config).expect("the bootstrap config"),
            planted,
            "{row}: the bootstrap is untouched"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// The second pass applies pass B1a's rules again, before anything is created
// ---------------------------------------------------------------------------------------------

/// What B1a's plan says of `bytes`, by the test's own decode: the same counts and the same entry digest,
/// computed independently of any later pass's flow. A frame that does not decode whole is described by
/// zeros: it can never reach the comparison.
fn summary_of(
    bytes: &[u8],
    class: ClassV1,
    generation: &str,
    staged: usize,
) -> ActiveFrameSummaryV1 {
    let header = CustodyFrameHeaderV1::new(class, generation).expect("a header");
    let mut digest = ActiveEntryDigestV1::new(class);
    let (mut entries, mut directories, mut files, mut content_bytes) = (0_u64, 0_u64, 0_u64, 0_u64);
    let mut whole = true;
    match CustodyFrameDecoderV1::new(bytes, &header, frame_budget()) {
        Err(_) => whole = false,
        Ok(mut decoder) => loop {
            match decoder.next_entry() {
                Err(_) => {
                    whole = false;
                    break;
                }
                Ok(None) => break,
                Ok(Some(entry)) => {
                    entries += 1;
                    match entry {
                        CustodyFrameEntryV1::Directory { path, .. } => {
                            directories += 1;
                            digest.record(ActiveEntryKindV1::Directory, path.as_bytes(), 0);
                        }
                        CustodyFrameEntryV1::Symlink { path, .. } => {
                            files += 1;
                            digest.record(ActiveEntryKindV1::Symlink, path.as_bytes(), 0);
                        }
                        CustodyFrameEntryV1::Regular {
                            path,
                            length,
                            mut content,
                            ..
                        } => {
                            files += 1;
                            content_bytes += length;
                            digest.record(ActiveEntryKindV1::Regular, path.as_bytes(), length);
                            let _ = std::io::copy(&mut content, &mut std::io::sink());
                        }
                    }
                }
            }
        },
    }
    let zeros = !whole;
    ActiveFrameSummaryV1 {
        class,
        staged,
        length: bytes.len() as u64,
        sha256: sha256_bytes(bytes),
        entries: if zeros { 0 } else { entries },
        directories: if zeros { 0 } else { directories },
        regular_files: if zeros { 0 } else { files },
        content_bytes: if zeros { 0 } else { content_bytes },
        entries_sha256: if zeros { [0; 32] } else { digest.finish() },
    }
}

/// Replace the staged payload of `class` IN PLACE (the same slot, so every retained classification and
/// index stays valid) with `bytes`, and make the plan describe exactly those bytes: what a hand-built plan
/// would say, so only the step's own guards can tell the frame from a prevalidated one.
fn swap_frame(case: &mut MetaCaseV1, class: ClassV1, bytes: &[u8]) {
    use std::io::{Seek as _, Write as _};
    let generation = case
        .store
        .boot
        .verified
        .control
        .manifest
        .generation_id()
        .to_owned();
    let index = staged_index(&case.store.boot.verified, class);
    let mut file = tempfile::tempfile().expect("an unlinked staging descriptor");
    file.write_all(bytes).expect("the frame bytes");
    file.seek(SeekFrom::Start(0)).expect("rewind");
    let one = &mut case.store.boot.verified.staged[index];
    one.file = file;
    one.length = bytes.len() as u64;
    one.sha256 = sha256_bytes(bytes);
    let summary = summary_of(bytes, class, &generation, index);
    *case
        .store
        .plan
        .frames
        .iter_mut()
        .find(|frame| frame.class == class)
        .expect("a planned frame") = summary;
}

fn generation_of(case: &MetaCaseV1) -> String {
    case.store
        .boot
        .verified
        .control
        .manifest
        .generation_id()
        .to_owned()
}

/// The cause the pass B1a prevalidation gives a frame set, on a fresh capsule.
fn b1a_cause_of(capsule: &CustomCapsuleV1, frames: &[(ClassV1, Vec<u8>)]) -> String {
    let mut case = CaseV1::with_bytes(capsule, frames);
    let cause = prevalidate(&mut case.verified, far_deadline())
        .expect_err("pass B1a refuses the frame set");
    format!("{cause:?}")
}

/// The refs frame every second-pass row starts from: a HEAD and the empty branch and tag directories.
fn base_refs() -> FrameSpecV1 {
    FrameSpecV1::new()
        .file("HEAD", HEAD_BYTES_V1)
        .dir("refs")
        .dir("refs/heads")
        .dir("refs/tags")
}

/// An entry the active subset never carries, or carries in the wrong place, or spells wrongly, in a frame
/// that an earlier pass would never have admitted (the plan here is hand-built to describe it): the second
/// pass refuses it with the very cause pass B1a gives, before creating it, keeps what it had already created,
/// and leaves the bytes of everything behavior-affecting unwritten.
#[test]
fn b2b_the_second_pass_refuses_what_pass_b1a_refuses_before_creating_it() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let long = |name: &str| format!("refs/heads/{name}");
    // (row, the frame's class, its entries, the paths that must not exist afterwards)
    let rows: Vec<(&str, ClassV1, FrameSpecV1, Vec<String>)> = vec![
        (
            "a symlink in refs",
            REFS_V1,
            base_refs().link("refs/heads/l", "main"),
            vec![long("l")],
        ),
        (
            "a config file",
            REFS_V1,
            base_refs().file("config", "[core]\n\tfsmonitor = /tmp/b2b-marker\n"),
            vec!["config".into()],
        ),
        (
            "a hooks directory and a hook",
            REFS_V1,
            base_refs()
                .dir("hooks")
                .file("hooks/pre-commit", "#!/bin/sh\ntouch /tmp/b2b-marker\n"),
            vec!["hooks".into(), "hooks/pre-commit".into()],
        ),
        (
            "an include-bearing info file",
            REFS_V1,
            base_refs()
                .dir("info")
                .file("info/attributes", "* filter=x\n"),
            vec!["info".into(), "info/attributes".into()],
        ),
        (
            "shallow",
            REFS_V1,
            base_refs().file("shallow", "x\n"),
            vec!["shallow".into()],
        ),
        (
            "an objects entry",
            REFS_V1,
            base_refs().dir("objects").file("objects/stray", "x"),
            vec!["objects/stray".into()],
        ),
        (
            "an index",
            REFS_V1,
            base_refs().file("index", "DIRC"),
            vec!["index".into()],
        ),
        (
            "modules and worktrees",
            REFS_V1,
            base_refs().dir("modules").dir("worktrees"),
            vec!["modules".into(), "worktrees".into()],
        ),
        (
            "a logs entry in the refs class",
            REFS_V1,
            base_refs().dir("logs").file("logs/HEAD", "x\n"),
            vec!["logs".into()],
        ),
        (
            "a non-ASCII spelling",
            REFS_V1,
            base_refs().file(&long("caf\u{e9}"), "x\n"),
            vec![long("caf\u{e9}")],
        ),
        (
            "a backslash",
            REFS_V1,
            base_refs().file(&long("a\\b"), "x\n"),
            vec![long("a\\b")],
        ),
        (
            "a trailing dot",
            REFS_V1,
            base_refs().file(&long("a."), "x\n"),
            vec![long("a.")],
        ),
        (
            "a space",
            REFS_V1,
            base_refs().file(&long("a b"), "x\n"),
            vec![long("a b")],
        ),
        (
            "refs as a regular file",
            REFS_V1,
            FrameSpecV1::new()
                .file("HEAD", HEAD_BYTES_V1)
                .file("refs", "x"),
            vec![],
        ),
        (
            "HEAD as a directory",
            REFS_V1,
            FrameSpecV1::new().dir("HEAD").dir("refs"),
            vec![],
        ),
        (
            "two spellings that differ only by ASCII case",
            REFS_V1,
            base_refs().file(&long("A"), "A\n").file(&long("a"), "a\n"),
            // A case-insensitive filesystem resolves `a` to `A`; inspect the actual entries below.
            vec![],
        ),
        (
            "no HEAD at all",
            REFS_V1,
            FrameSpecV1::new().dir("refs").dir("refs/heads"),
            vec![],
        ),
    ];
    for (row, class, spec, absent) in rows {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let generation = generation_of(&case);
        let evil = spec.encode(class, &generation);
        let expected = b1a_cause_of(&capsule, &[(class, evil.clone())]);
        swap_frame(&mut case, class, &evil);
        let failure = case.refused(row);
        assert_eq!(
            format!("{:?}", failure.cause),
            expected,
            "{row}: the second pass gives pass B1a's cause"
        );
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
        assert_eq!(
            failure.active_materialization_began,
            failure.partial.charged.entries > 0,
            "{row}"
        );
        for path in &absent {
            assert!(!exists(&case.meta(path)), "{row}: `{path}` was created");
        }
        if row == "two spellings that differ only by ASCII case" {
            let entries: Vec<_> = std::fs::read_dir(case.meta("refs/heads"))
                .expect("the branch directory")
                .map(|entry| entry.expect("a branch entry").file_name())
                .collect();
            assert_eq!(entries, [std::ffi::OsString::from("A")], "{row}");
            assert_eq!(
                std::fs::read(case.meta("refs/heads/A")).unwrap(),
                b"A\n",
                "{row}"
            );
        }
        for forbidden in [
            "hooks",
            "config",
            "info",
            "shallow",
            "index",
            "modules",
            "worktrees",
        ] {
            assert!(!exists(&case.meta(forbidden)), "{row}: {forbidden}");
        }
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }

    // The same holds for the logs class, after a whole refs frame was restored.
    let logs_rows: Vec<(&str, FrameSpecV1, &str)> = vec![
        (
            "a symlink in logs",
            FrameSpecV1::new().dir("logs").link("logs/l", "HEAD"),
            "logs/l",
        ),
        (
            "a refs entry in the logs class",
            FrameSpecV1::new().dir("logs").dir("refs"),
            "refs/heads/x",
        ),
        (
            "logs as a regular file",
            FrameSpecV1::new().file("logs", "x"),
            "logs",
        ),
    ];
    for (row, spec, absent) in logs_rows {
        // A case with a logs frame: the plan names both classes.
        let mut case = MetaCaseV1::with_frames(
            &capsule,
            CustodyGitObjectFormatV1::Sha1,
            &base_refs(),
            Some(&FrameSpecV1::new().dir("logs")),
            vec![symbolic_ref("HEAD", "refs/heads/main")],
        );
        let generation = generation_of(&case);
        let refs = base_refs().encode(REFS_V1, &generation);
        let evil = spec.encode(LOGS_V1, &generation);
        let expected = b1a_cause_of(&capsule, &[(REFS_V1, refs), (LOGS_V1, evil.clone())]);
        swap_frame(&mut case, LOGS_V1, &evil);
        let failure = case.refused(row);
        assert_eq!(format!("{:?}", failure.cause), expected, "{row}");
        assert!(
            failure.active_materialization_began,
            "{row}: refs was restored"
        );
        assert!(!exists(&case.meta(absent)), "{row}: `{absent}`");
        assert!(
            exists(&case.meta("HEAD")),
            "{row}: the refs frame was whole"
        );
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }
}

/// The aggregate path table's byte bound applies in the second pass: a bound the first pass cleared (the
/// default) is refused when it is smaller, with the same typed fault, before the entry that passes it is
/// created.
#[test]
fn b2b_the_path_table_bound_applies_in_the_second_pass() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let failure = match case.attempt_with(
        far_deadline(),
        B2B_COMPLETED_V1,
        B2B_ENTRY_OVERHEAD_V1 * 2,
        RefsLimitsV1::v1(),
    ) {
        Ok(_) => panic!("a tiny table bound must refuse"),
        Err(failure) => failure,
    };
    assert!(
        matches!(
            &failure.cause,
            GitBootstrapErrorV1::ActiveFrame {
                fault: ActiveFrameFaultV1::PathTableBound { .. },
                ..
            }
        ),
        "{:?}",
        failure.cause
    );
    assert_eq!(failure.last_completed, B2B_COMPLETED_V1);
    assert_metadata_partial_is_the_disk("a tiny table bound", &case, &failure, 0);
    assert!(
        failure.partial.charged.entries < 3,
        "the entry that passed the bound was never created: {:?}",
        failure.partial.charged
    );
}

// ---------------------------------------------------------------------------------------------
// Each retained frame is reverified immediately before its own second decode
// ---------------------------------------------------------------------------------------------

/// A staged frame whose bytes or length drifted after its plan (a changed byte, an appended byte, a
/// truncation, an emptied file) is refused by the reverify BEFORE its decode begins, and named: for the refs
/// frame nothing at all was created, and for the logs frame the refs frame had been restored whole and not
/// one logs entry exists. Each frame is reverified at its own turn, not all up front.
#[test]
fn b2b_a_frame_changed_after_its_plan_is_refused_by_the_reverify_before_its_decode() {
    use std::os::unix::fs::FileExt as _;
    type Edit = fn(&std::fs::File);
    let edits: [(&str, Edit); 4] = [
        ("a byte changed", |file| {
            file.write_all_at(&[0xff], 12).expect("change a byte");
        }),
        ("a byte appended", |file| {
            let length = file.metadata().expect("metadata").len();
            file.write_all_at(b"x", length).expect("append");
        }),
        ("truncated", |file| {
            let length = file.metadata().expect("metadata").len();
            file.set_len(length - 1).expect("truncate");
        }),
        ("emptied", |file| file.set_len(0).expect("empty")),
    ];
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for class in [REFS_V1, LOGS_V1] {
        for (row, edit) in edits {
            let row = format!("{class:?}: {row}");
            let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            let index = staged_index(&case.store.boot.verified, class);
            edit(&case.store.boot.verified.staged[index].file);
            let name = lossy(case.store.boot.verified.staged[index].name.as_bytes());
            let failure = case.refused(&row);
            assert!(
                matches!(&failure.cause, GitBootstrapErrorV1::StagedInputChanged { name: found }
                    if *found == name),
                "{row}: {:?}",
                failure.cause
            );
            assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
            assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
            if class == REFS_V1 {
                assert!(!failure.active_materialization_began, "{row}");
                assert_eq!(failure.partial.charged, none_charged(), "{row}");
                assert_eq!(case.entry_count(), 0, "{row}: nothing was created");
            } else {
                assert!(failure.active_materialization_began, "{row}");
                assert_eq!(
                    failure.partial.files.len(),
                    4,
                    "{row}: the refs frame was whole"
                );
                assert!(exists(&case.meta("refs/heads/main")), "{row}");
                assert!(!exists(&case.meta("logs")), "{row}: no logs entry");
            }
        }
    }
}

/// A frame replaced between its rehash and its decode (with another well-formed frame, so only the verified
/// staged digest can tell) is refused as that, AFTER the replacement's entries were created (a frame is not
/// final until its trailer and its bytes are verified), and every byte created stays: a shorter replacement
/// (the byte count differs) and one of exactly the same length (only the digest differs).
#[test]
fn b2b_a_frame_changed_between_the_rehash_and_the_decode_is_refused_with_the_partial_state() {
    use std::os::unix::fs::FileExt as _;
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    for (row, replacement, entries, head) in [
        (
            "a shorter well-formed frame",
            FrameSpecV1::new().file("HEAD", HEAD_BYTES_V1),
            1_usize,
            HEAD_BYTES_V1.to_vec(),
        ),
        (
            "a well-formed frame of the same length",
            base_refs()
                .without("HEAD")
                .file("HEAD", "ref: refs/heads/mine\n"),
            4,
            b"ref: refs/heads/mine\n".to_vec(),
        ),
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let generation = generation_of(&case);
        let other = replacement.encode(REFS_V1, &generation);
        let index = staged_index(&case.store.boot.verified, REFS_V1);
        let staged_length = case.store.boot.verified.staged[index].length as usize;
        assert_eq!(other.len() < staged_length, entries == 1, "{row}");
        assert_eq!(other.len() == staged_length, entries == 4, "{row}");
        let handle = case.store.boot.verified.staged[index]
            .file
            .try_clone()
            .expect("a duplicate descriptor");
        let swapped = std::cell::Cell::new(false);
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            if event.label == "frame-rewind" && !swapped.replace(true) {
                handle.set_len(0).expect("empty the frame");
                handle.write_all_at(&other, 0).expect("another frame");
            }
        });
        let failure = case.refused(row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::StagedInputChanged { .. }
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
        assert!(failure.active_materialization_began, "{row}");
        // The replacement's entries were created, and refused only when the bytes were bound.
        assert_eq!(case.entry_count(), entries, "{row}");
        assert_eq!(
            std::fs::read(case.meta("HEAD")).expect("HEAD"),
            head,
            "{row}"
        );
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }
}

/// A plan that does not describe the frame it names (one more entry, directory, regular file, or content byte,
/// or another entry digest) is refused once the frame has decoded whole and its bytes are bound to the
/// verified plaintext: the frame is the verified bytes, so every byte of it was restored, and nothing after it
/// is. The refs frame and the logs frame each.
#[test]
fn b2b_a_plan_that_does_not_describe_the_frame_is_refused_after_its_decode() {
    type BreakV1 = fn(&mut ActiveFrameSummaryV1);
    let breaks: [(&str, BreakV1); 5] = [
        ("one more entry", |summary| summary.entries += 1),
        ("one more directory", |summary| summary.directories += 1),
        ("one more regular file", |summary| {
            summary.regular_files += 1
        }),
        ("one more content byte", |summary| {
            summary.content_bytes += 1
        }),
        ("another entry digest", |summary| {
            summary.entries_sha256[0] ^= 1
        }),
    ];
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (class_index, restored_before) in [(0_usize, 0_usize), (1, 7)] {
        for (row, breakage) in breaks {
            let row = format!("frame {class_index}: {row}");
            let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            breakage(&mut case.store.plan.frames[class_index]);
            let failure = case.refused(&row);
            assert!(
                matches!(&failure.cause, GitBootstrapErrorV1::ActivePlanMismatch(detail)
                    if detail.contains("admitted")),
                "{row}: {:?}",
                failure.cause
            );
            assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
            assert!(failure.active_materialization_began, "{row}");
            // The frame itself was whole and restored; the next frame never began.
            let frame_entries = if class_index == 0 { 7 } else { 5 };
            assert_eq!(case.entry_count(), restored_before + frame_entries, "{row}");
            assert!(!exists(&case.meta("config")), "{row}");
            assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
        }
    }
}

/// The retained descriptors are the only input: every staged file is renamed away or unlinked after phase V,
/// and the step still restores the exact frames, and reads nothing by name.
#[test]
fn b2b_renamed_and_unlinked_staged_frames_are_still_read_from_their_descriptors() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let expected = case.expected_frames();
    let plain = case.dest().work().join("plain");
    let mut moved = 0;
    let mut removed = 0;
    for (number, entry) in walk_files(&plain).into_iter().enumerate() {
        if number % 2 == 0 {
            std::fs::rename(&entry, entry.with_extension("renamed")).expect("renamed away");
            moved += 1;
        } else {
            std::fs::remove_file(&entry).expect("unlinked");
            removed += 1;
        }
    }
    assert!(moved > 0 && removed > 0, "both kinds of drift were made");
    let _ = case.done("staged names gone");
    let mut want = expected;
    want.insert(
        "config".to_owned(),
        Some(golden_config(case.format).to_vec()),
    );
    assert_eq!(case.metadata_on_disk(), want);
}

/// Every regular file beneath `root`, by path.
fn walk_files(root: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    let mut frontier = vec![root.to_path_buf()];
    while let Some(directory) = frontier.pop() {
        for entry in std::fs::read_dir(&directory).expect("a directory") {
            let path = entry.expect("an entry").path();
            if std::fs::symlink_metadata(&path).expect("metadata").is_dir() {
                frontier.push(path);
            } else {
                files.push(path);
            }
        }
    }
    files.sort();
    files
}

/// Each frame is reverified at its own turn, immediately before its decode: the events show one rehash
/// before the refs frame's first entry and a second one after the refs frame's last entry and before the
/// logs frame's first, never both up front.
#[test]
fn b2b_each_frame_is_rehashed_immediately_before_its_own_decode() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let events = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
    let mut hooks = Vec::new();
    {
        let log = events.clone();
        hooks.push(install_git_hook_for_test(
            GitHookPointV1::DeadlineObserved,
            move |event| {
                if event.label == "frame-rehash" {
                    log.borrow_mut().push("rehash".to_owned());
                }
            },
        ));
    }
    {
        let log = events.clone();
        let git = case.git();
        hooks.push(install_git_hook_for_test(
            GitHookPointV1::BeforeObjectCreate,
            move |event| {
                let relative = event.path.strip_prefix(&git).expect("beneath .git");
                log.borrow_mut().push(relative.display().to_string());
            },
        ));
    }
    let _ = case.done("two frames");
    drop(hooks);
    let events = events.borrow();
    let at = |wanted: &str| {
        events
            .iter()
            .position(|event| event == wanted)
            .unwrap_or_else(|| panic!("no `{wanted}` in {events:?}"))
    };
    let rehashes: Vec<usize> = events
        .iter()
        .enumerate()
        .filter(|(_, event)| *event == "rehash")
        .map(|(index, _)| index)
        .collect();
    assert_eq!(rehashes.len(), 2, "{events:?}");
    assert!(
        rehashes[0] < at("HEAD"),
        "the refs frame is rehashed before its first entry"
    );
    assert!(
        at("refs/heads/main") < rehashes[1] && rehashes[1] < at("logs"),
        "the logs frame is rehashed after the refs frame is restored and before its own first entry: {events:?}"
    );
}

// ---------------------------------------------------------------------------------------------
// A frame that is not whole stays fatal, and every partial byte stays
// ---------------------------------------------------------------------------------------------

/// A frame that does not decode whole is fatal at the point of damage, in the second pass too, even though
/// every earlier entry was fine and was already created: damage to a trailer, a content digest, a header
/// binding, or a trailing byte is `FrameInvalid` for its class, with every provisional byte kept and the
/// facts naming exactly what exists. Controls: the undamaged frame restores.
#[test]
fn b2b_a_bad_trailer_or_damage_after_provisional_content_keeps_every_partial_byte() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let generation = CaseV1::generation(&capsule);
    let spec = FrameSpecV1::new()
        .file("HEAD", HEAD_BYTES_V1)
        .file("packed-refs", PACKED_HEADER_V1)
        .dir("refs")
        .dir("refs/heads");
    let good = spec.encode(REFS_V1, &generation);
    let mut damaged: Vec<(&str, Vec<u8>, usize)> = Vec::new();
    // (row, bytes, the entries that exist beforehand)
    let entries = 4;
    let mut flipped_digest = good.clone();
    flip(&mut flipped_digest, good.len() - 1);
    damaged.push(("the frame digest's last byte", flipped_digest, entries));
    let mut flipped_count = good.clone();
    flip(&mut flipped_count, good.len() - (DIGEST_BYTES_V1 + 8 + 8));
    damaged.push(("the trailer's entry count", flipped_count, entries));
    let mut flipped_total = good.clone();
    flip(&mut flipped_total, good.len() - (DIGEST_BYTES_V1 + 8));
    damaged.push(("the trailer's content total", flipped_total, entries));
    damaged.push((
        "a truncated trailer",
        good[..good.len() - 8].to_vec(),
        entries,
    ));
    damaged.push((
        "no trailer at all",
        good[..good.len() - 49].to_vec(),
        entries,
    ));
    let mut trailing = good.clone();
    trailing.push(0);
    damaged.push(("a byte after the trailer", trailing, entries));
    let note_at = good
        .windows(9)
        .position(|window| window == b"pack-refs")
        .expect("the packed-refs content");
    let mut flipped_content = good.clone();
    flip(&mut flipped_content, note_at);
    // The file's content digest fails at the read that exhausts it: its last chunk is never written, and
    // the entries after it were never reached.
    damaged.push(("a content byte of the second file", flipped_content, 2));
    damaged.push((
        "another generation's header",
        spec.encode(REFS_V1, "another-generation"),
        0,
    ));
    damaged.push((
        "another class's header",
        spec.encode(LOGS_V1, &generation),
        0,
    ));
    let whole = |records: &[Vec<u8>], total: u64| {
        raw_frame(1, &generation, records, records.len() as u64, total)
    };
    damaged.push((
        "an entry under a regular file",
        whole(&[raw_file(b"HEAD", b"x"), raw_file(b"HEAD/x", b"y")], 2),
        1,
    ));
    damaged.push((
        "an entry whose parents are absent",
        whole(
            &[raw_file(b"HEAD", b"x"), raw_file(b"refs/heads/main", b"y")],
            2,
        ),
        1,
    ));
    for (row, bytes, created) in damaged {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        swap_frame(&mut case, REFS_V1, &bytes);
        let failure = case.refused(row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid {
                    class: REFS_V1
                })
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
        assert_eq!(failure.active_materialization_began, created > 0, "{row}");
        assert_eq!(
            case.entry_count(),
            created,
            "{row}: exactly the provisional entries before the damage exist"
        );
        assert!(!exists(&case.meta("config")), "{row}: no config");
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }

    // The content flip leaves a partial file: some bytes of it were written, never all.
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let mut bytes = good.clone();
    flip(&mut bytes, note_at);
    swap_frame(&mut case, REFS_V1, &bytes);
    let _chunk = override_object_copy_chunk_for_test(16);
    let failure = case.refused("the content flip in chunks");
    let flight = failure
        .partial
        .in_flight
        .as_ref()
        .expect("packed-refs in flight");
    assert_eq!(flight.relative, "packed-refs");
    assert_eq!(
        flight.written, 32,
        "two whole chunks were written; the third failed its digest"
    );
    assert!(flight.written < flight.expected_length);
    assert_metadata_partial_is_the_disk("the content flip in chunks", &case, &failure, 0);

    // The control: the undamaged frame restores.
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    swap_frame(&mut case, REFS_V1, &good);
    let _ = case.done("the undamaged frame");
    assert_eq!(
        std::fs::read(case.meta("packed-refs")).expect("packed-refs"),
        PACKED_HEADER_V1.as_bytes()
    );
}

// ---------------------------------------------------------------------------------------------
// A file that changes while it is written, and the caller's frame budget
// ---------------------------------------------------------------------------------------------

/// A file that changes during its own write, after the last chunk returned, is never taken for what was
/// written: an appended byte and a truncation are refused by the check of the file's own descriptor, a name
/// swapped for a link or another inode by the check of its entry through the retained parent, each before the
/// file is kept (it stays in flight, with every byte), and a config changed in place after its write is
/// refused by its read-back.
#[test]
fn b2b_a_file_that_changes_during_its_own_write_is_refused_with_the_partial_state() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let head_length = HEAD_BYTES_V1.len() as u64;
    type ChangeV1 = fn(&Path, &Path);
    let rows: [(&str, ChangeV1, &str); 4] = [
        (
            "an appended byte",
            |path, _| {
                use std::io::Write as _;
                std::fs::OpenOptions::new()
                    .append(true)
                    .open(path)
                    .and_then(|mut file| file.write_all(b"x"))
                    .expect("an appended byte");
            },
            "regular file of the frame's length",
        ),
        (
            "a truncation",
            |path, _| {
                std::fs::OpenOptions::new()
                    .write(true)
                    .open(path)
                    .and_then(|file| file.set_len(5))
                    .expect("a truncation");
            },
            "regular file of the frame's length",
        ),
        (
            "a link in its place",
            |path, outside| {
                move_away(path, "HEAD.moved");
                std::os::unix::fs::symlink(outside.join("decoy"), path).expect("a link");
            },
            "",
        ),
        (
            "another inode in its place",
            |path, _| {
                let bytes = std::fs::read(path).expect("HEAD");
                move_away(path, "HEAD.moved");
                std::fs::write(path, bytes).expect("the same bytes, a new inode");
            },
            "",
        ),
    ];
    for (row, change, detail) in rows {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let target = case.meta("HEAD");
        let (_outside_area, outside) = external_dir_with(&["decoy"]);
        let outside_before = snapshot(&outside);
        let (acting, away) = (target.clone(), outside.clone());
        let acted = std::cell::Cell::new(false);
        let _hook = install_git_hook_for_test(GitHookPointV1::ObjectIo, move |event| {
            if event.label == "write" && event.path == acting && !acted.replace(true) {
                change(&acting, &away);
            }
        });
        let failure = case.refused(row);
        match (&failure.cause, detail.is_empty()) {
            (
                GitBootstrapErrorV1::MetadataCopy {
                    relative,
                    detail: found,
                },
                false,
            ) => {
                assert_eq!(relative, "HEAD", "{row}");
                assert!(found.contains(detail), "{row}: {found}");
            }
            (GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. }), true)
                if row == "a link in its place" => {}
            (cause, true) if row != "a link in its place" => {
                assert!(identity_changed(cause), "{row}: {cause:?}");
            }
            (cause, _) => panic!("{row}: {cause:?}"),
        }
        assert_eq!(
            snapshot(&outside),
            outside_before,
            "{row}: written through a link"
        );
        assert!(failure.active_materialization_began, "{row}");
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("HEAD stays in flight");
        assert_eq!(
            (flight.relative.as_str(), flight.written),
            ("HEAD", head_length),
            "{row}"
        );
        assert!(
            failure.partial.files.is_empty(),
            "{row}: the file was never kept"
        );
        assert_eq!(
            failure.partial.charged,
            MetadataChargeV1 {
                entries: 1,
                bytes: head_length
            },
            "{row}"
        );
    }

    // The config, changed in place (same inode, same length) after its write and before its read-back.
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let config = case.meta("config");
    // The seventeenth recheck of a clean run of this capsule is the one that ends the config's own write.
    let _hook = act_at_guard("metadata-checked", 17, move || {
        use std::os::unix::fs::FileExt as _;
        let file = std::fs::OpenOptions::new()
            .write(true)
            .open(&config)
            .expect("the config opens for the racer");
        file.write_all_at(b"X", 0).expect("a byte changed in place");
    });
    let failure = case.refused("a config changed in place");
    assert!(
        matches!(&failure.cause, GitBootstrapErrorV1::MetadataCopy { relative, .. }
            if relative == "config"),
        "{:?}",
        failure.cause
    );
    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Refs));
    assert_eq!(
        failure.partial.files.len(),
        2,
        "HEAD and the config were kept"
    );
}

/// The caller's frame budget bounds the second decode: a budget below the frame's entry count stops the decode
/// at the first entry past it (the entries before it were already restored, and kept), and one too small for
/// any frame stops it before the first entry.
#[test]
fn b2b_the_callers_frame_budget_bounds_the_second_decode() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    for (row, budget, created) in [
        (
            "two entries",
            CustodyFrameBudgetV1::new(2, 1 << 30).expect("a budget"),
            2_usize,
        ),
        (
            "bytes too few for any frame",
            CustodyFrameBudgetV1::new(1 << 20, 80).expect("a budget"),
            0,
        ),
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        case.budget = budget;
        let failure = case.refused(row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid {
                    class: REFS_V1
                })
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(case.entry_count(), created, "{row}");
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }
}

// ---------------------------------------------------------------------------------------------
// A held fault never pre-empts the frame's own integrity (source round 1 repair)
//
// The first refusal of what was DONE with a decoded entry (an admission fault, or a failed create or write) is
// held: nothing more is judged or created, but the decoder is drained through its trailer and the decoded bytes
// are bound to the verified plaintext and the plan, and only then is the held fault reported. A frame that is
// not whole, or not the verified bytes, is refused as THAT, whatever its first entry said, and every byte
// created before the fault stays.
// ---------------------------------------------------------------------------------------------

/// A well-formed refs frame of EXACTLY `length` bytes: `spec` builds the entries from a padding string that it
/// puts in HEAD's content, and the padding is sized so the encoded frame is `length` bytes long.
fn frame_of_length(generation: &str, length: usize, spec: impl Fn(&str) -> FrameSpecV1) -> Vec<u8> {
    let bare = spec("").encode(REFS_V1, generation);
    assert!(bare.len() <= length, "{} > {length}", bare.len());
    let padded = spec(&"x".repeat(length - bare.len())).encode(REFS_V1, generation);
    assert_eq!(padded.len(), length);
    padded
}

/// A frame whose entry after HEAD is an admission fault (`hooks` is never active), with entries after it that
/// must never be created.
fn faulted_frame_spec(padding: &str) -> FrameSpecV1 {
    FrameSpecV1::new()
        .file("HEAD", format!("ref: refs/heads/main\n{padding}"))
        .dir("hooks")
        .dir("refs")
        .dir("refs/heads")
}

/// Replace the staged refs frame IN PLACE with `bytes` at the one moment between its rehash and its decode (the
/// reverify's own last guard), through a duplicate of the retained descriptor.
fn replace_frame_after_rehash(case: &MetaCaseV1, bytes: Vec<u8>) -> GitSeamGuardV1 {
    use std::os::unix::fs::FileExt as _;
    let index = staged_index(&case.store.boot.verified, REFS_V1);
    let handle = case.store.boot.verified.staged[index]
        .file
        .try_clone()
        .expect("a duplicate descriptor");
    let swapped = std::cell::Cell::new(false);
    install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        if event.label == "frame-rewind" && !swapped.replace(true) {
            handle.set_len(0).expect("empty the frame");
            handle.write_all_at(&bytes, 0).expect("another frame");
        }
    })
}

/// An entry fault followed by anything that makes the frame not whole or not the verified bytes is refused as
/// that, never as the entry fault: a malformed trailer (a flipped digest, a flipped count, a truncated trailer,
/// a byte after it) after an ADMISSION fault and after a COLLISION; a frame replaced between its rehash and its
/// decode by a shorter one and by one of exactly the same length (only the digest differs), after an admission
/// fault and after a collision; and a plan that does not describe the frame, which outranks the held fault too.
/// Everything created before the fault stays, nothing after it is created, and the control (a whole, verified
/// frame) reports the held fault itself.
#[test]
fn b2b_a_held_entry_fault_never_pre_empts_the_trailer_the_digest_or_the_plan() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let invalid = |cause: &GitBootstrapErrorV1| {
        matches!(
            cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid { class: REFS_V1 })
        )
    };
    let changed = |cause: &GitBootstrapErrorV1| {
        matches!(cause, GitBootstrapErrorV1::StagedInputChanged { .. })
    };

    // The control: a whole, verified frame reports the admission fault itself, after creating only HEAD.
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let generation = generation_of(&case);
    let faulted = faulted_frame_spec("").encode(REFS_V1, &generation);
    let expected = b1a_cause_of(&capsule, &[(REFS_V1, faulted.clone())]);
    swap_frame(&mut case, REFS_V1, &faulted);
    let failure = case.refused("the control");
    assert_eq!(format!("{:?}", failure.cause), expected);
    assert_eq!(
        case.metadata_on_disk().keys().collect::<Vec<_>>(),
        ["HEAD"],
        "only the entry before the fault exists: nothing after a held fault is created"
    );
    assert_metadata_partial_is_the_disk("the control", &case, &failure, 0);

    // A malformed trailer after an admission fault.
    type MalformV1 = fn(&mut Vec<u8>);
    let malformed: [(&str, MalformV1); 4] = [
        ("a flipped frame digest", |bytes| {
            let last = bytes.len() - 1;
            flip(bytes, last);
        }),
        ("a flipped trailer entry count", |bytes| {
            let at = bytes.len() - (DIGEST_BYTES_V1 + 8 + 8);
            flip(bytes, at);
        }),
        ("a truncated trailer", |bytes| {
            bytes.truncate(bytes.len() - 8)
        }),
        ("a byte after the trailer", |bytes| bytes.push(0)),
    ];
    for (row, damage) in malformed {
        let row = format!("an admission fault, then {row}");
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let mut bytes = faulted_frame_spec("").encode(REFS_V1, &generation_of(&case));
        damage(&mut bytes);
        swap_frame(&mut case, REFS_V1, &bytes);
        let failure = case.refused(&row);
        assert!(invalid(&failure.cause), "{row}: {:?}", failure.cause);
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
        assert_eq!(
            case.metadata_on_disk().keys().collect::<Vec<_>>(),
            ["HEAD"],
            "{row}"
        );
        assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
    }

    // A collision (the first entry's name is planted) then a malformed trailer, and then a changed frame.
    for row in [
        "a collision, then a flipped digest",
        "a collision, then a shorter frame",
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let head = case.meta("HEAD");
        let (_outside_area, outside) = external_dir_with(&["decoy"]);
        let _plant = act_before_creating(head.clone(), {
            let at = head.clone();
            move || plant(&at, PlantV1::RegularFile, &outside)
        });
        let good = base_refs().encode(REFS_V1, &generation_of(&case));
        let _swap = if row.ends_with("a flipped digest") {
            let mut bad = good.clone();
            let last = bad.len() - 1;
            flip(&mut bad, last);
            swap_frame(&mut case, REFS_V1, &bad);
            None
        } else {
            let shorter = FrameSpecV1::new()
                .file("HEAD", HEAD_BYTES_V1)
                .encode(REFS_V1, &generation_of(&case));
            Some(replace_frame_after_rehash(&case, shorter))
        };
        let failure = case.refused(row);
        let accepted = if row.ends_with("a flipped digest") {
            invalid(&failure.cause)
        } else {
            changed(&failure.cause)
        };
        assert!(accepted, "{row}: {:?}", failure.cause);
        assert_eq!(
            std::fs::read(&head).expect("the planted file"),
            b"planted",
            "{row}"
        );
        assert_eq!(
            case.entry_count(),
            1,
            "{row}: nothing but the planted entry"
        );
        assert_eq!(
            failure.partial.charged,
            none_charged(),
            "{row}: the refused entry was given back"
        );
    }

    // A frame replaced between its rehash and its decode, after an admission fault: a shorter one, and one of
    // exactly the original's length (the staged digest alone tells them apart).
    let original_length = {
        let case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let index = staged_index(&case.store.boot.verified, REFS_V1);
        case.store.boot.verified.staged[index].length as usize
    };
    for (row, same_length) in [
        ("a shorter frame", false),
        ("a frame of the same length", true),
    ] {
        let row = format!("an admission fault, then {row}");
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let generation = generation_of(&case);
        let replacement = if same_length {
            frame_of_length(&generation, original_length, faulted_frame_spec)
        } else {
            faulted_frame_spec("").encode(REFS_V1, &generation)
        };
        assert_eq!(replacement.len() == original_length, same_length, "{row}");
        let _hook = replace_frame_after_rehash(&case, replacement);
        let failure = case.refused(&row);
        assert!(changed(&failure.cause), "{row}: {:?}", failure.cause);
        assert_eq!(
            case.metadata_on_disk().keys().collect::<Vec<_>>(),
            ["HEAD"],
            "{row}: the entry before the fault exists, nothing after it"
        );
        assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
    }

    // A plan that does not describe the frame outranks the held fault (the decode is whole and verified).
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    swap_frame(&mut case, REFS_V1, &faulted);
    case.store.plan.frames[0].entries += 1;
    let failure = case.refused("a stale plan summary");
    assert!(
        matches!(&failure.cause, GitBootstrapErrorV1::ActivePlanMismatch(detail)
            if detail.contains("admitted")),
        "{:?}",
        failure.cause
    );
    assert_metadata_partial_is_the_disk("a stale plan summary", &case, &failure, 0);
}

// ---------------------------------------------------------------------------------------------
// The refs agreement hashes exactly the stream the parsers consume (source round 1 repair)
// ---------------------------------------------------------------------------------------------

/// A valid reflog of `rows` rows of one fixed length, each ending in a four-digit message number, and that
/// length: far past one 8 KiB parser buffer for the sizes the rows below use.
fn big_reflog(commit: &str, format: GitObjectFormatV1, rows: usize) -> (String, usize) {
    let zero = "0".repeat(oid_len(format));
    let mut text = String::new();
    let mut row_length = 0;
    for number in 0..rows {
        let row = format!("{zero} {commit} {IDENT_V1}\tmessage {number:04}\n");
        row_length = row.len();
        text.push_str(&row);
    }
    (text, row_length)
}

/// A restored file that changes WHILE the parsers read it (after their first read returned, in a part they have
/// not read yet, with the same inode and the same length) is refused as changed, never accepted for what it now
/// says: an equivalent change (one message digit) that the parsers would accept, and a malformed one (a NUL byte
/// in a row) that they would refuse, which must still be reported as the integrity failure, because the digest
/// is taken over the very bytes the parsers consume and a parser fault is held until the file is drained and
/// verified. The control reads the same reflog unchanged and succeeds, so the rows differ only by the change.
#[test]
fn b2b_a_ref_file_that_changes_while_it_is_parsed_is_refused_as_changed() {
    use std::os::unix::fs::FileExt as _;
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let capsule = captured(cformat);
        let format = core_format(cformat);
        let specs = real_specs(&capsule, format);
        let (log, row_length) = big_reflog(&specs.commit, format, 400);
        assert!(
            log.len() > 3 * 8192,
            "the reflog spans several parser buffers"
        );
        // A byte of a message number deep in the unread part: the tens digit of row 340.
        let at = (340 * row_length + row_length - 3) as u64;
        let logs = specs
            .logs
            .clone()
            .without("logs/HEAD")
            .file("logs/HEAD", &log);

        let build = || {
            MetaCaseV1::with_frames(
                &capsule,
                cformat,
                &specs.refs,
                Some(&logs),
                specs.manifest_refs.clone(),
            )
        };
        let mut control = build();
        let _ = control.done(&format!("{cformat:?}: the unchanged reflog"));

        type ChangeV1 = fn(&std::fs::File, u64);
        let changes: [(&str, ChangeV1); 3] = [
            ("an equivalent digit", |file, at| {
                let mut byte = [0_u8; 1];
                file.read_exact_at(&mut byte, at).expect("the digit");
                assert!(byte[0].is_ascii_digit());
                file.write_all_at(&[byte[0] ^ 1], at)
                    .expect("a digit changed");
            }),
            ("a NUL byte", |file, at| {
                file.write_all_at(&[0], at).expect("a NUL written");
            }),
            ("an appended byte", |file, _| {
                let end = file.metadata().expect("metadata").len();
                file.write_all_at(b"x", end).expect("a byte appended");
            }),
        ];
        for (change_row, change) in changes {
            let row = format!("{cformat:?}: {change_row} in the unread part of a reflog");
            let mut case = build();
            let target = case.meta("logs/HEAD");
            let reads = std::rc::Rc::new(std::cell::Cell::new(0_usize));
            let seen = reads.clone();
            let acting = target.clone();
            let _hook = install_git_hook_for_test(GitHookPointV1::AfterRefsRead, move |event| {
                if event.path == acting {
                    seen.set(seen.get() + 1);
                    // After the FIRST read of the file, before anything past it has been read.
                    if seen.get() == 1 {
                        let file = std::fs::OpenOptions::new()
                            .write(true)
                            .read(true)
                            .open(&acting)
                            .expect("the racer opens the reflog");
                        change(&file, at);
                    }
                }
            });
            let failure = case.refused(&row);
            assert!(
                matches!(&failure.cause, GitBootstrapErrorV1::MetadataCopy { relative, .. }
                    if relative == "logs/HEAD"),
                "{row}: {:?}",
                failure.cause
            );
            assert!(reads.get() > 1, "{row}: the file was read in several calls");
            assert_eq!(
                failure.last_completed,
                Some(GitPlaneStepV1::Metadata),
                "{row}"
            );
            assert!(!exists(&case.meta("config")), "{row}: no config");
            assert_eq!(
                failure.partial.charged.entries, 12,
                "{row}: every frame entry was restored, and no config"
            );
        }
    }
}

/// The drain that follows a held ref fault reads the one absolute deadline before EVERY read: a malformed row early
/// in a large reflog stops the parsers after the first buffer, the rest of the file is drained for its digest, and
/// a read of the drain that returns after the deadline is followed by no further read of that file.
#[test]
fn b2b_the_drain_after_a_held_ref_fault_never_reads_past_the_deadline() {
    use std::os::unix::fs::FileExt as _;
    let cformat = CustodyGitObjectFormatV1::Sha1;
    let capsule = captured(cformat);
    let format = core_format(cformat);
    let specs = real_specs(&capsule, format);
    let (log, _row_length) = big_reflog(&specs.commit, format, 400);
    // A NUL in the second buffer: the parsers refuse inside it, with most of the file unread.
    let logs = specs
        .logs
        .clone()
        .without("logs/HEAD")
        .file("logs/HEAD", &log);
    let mut case = MetaCaseV1::with_frames(
        &capsule,
        cformat,
        &specs.refs,
        Some(&logs),
        specs.manifest_refs.clone(),
    );
    let target = case.meta("logs/HEAD");
    // This fixture deliberately spends the deadline on the third read. Give it scheduling
    // headroom to reach that proven read before doing so under bounded contention.
    let deadline = Instant::now() + Duration::from_secs(4);
    let reads = std::rc::Rc::new(std::cell::Cell::new(0_usize));
    let seen = reads.clone();
    let acting = target.clone();
    let _hook = install_git_hook_for_test(GitHookPointV1::AfterRefsRead, move |event| {
        if event.path != acting {
            return;
        }
        seen.set(seen.get() + 1);
        match seen.get() {
            // After the first read: a row in the part not yet read is changed in place to a malformed one.
            1 => {
                let file = std::fs::OpenOptions::new()
                    .write(true)
                    .open(&acting)
                    .expect("the racer opens the reflog");
                file.write_all_at(&[0], 10_000).expect("a NUL written");
            }
            // The parsers refused inside the second read's buffer, so the third read is the drain's first: it
            // returns after the deadline.
            3 => pass_the_deadline(deadline),
            _ => {}
        }
    });
    let failure = timed_out_metadata("a drain read past the deadline", case.attempt_by(deadline));
    assert_eq!(
        reads.get(),
        3,
        "no read of the file follows the one that returned after the deadline"
    );
    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Metadata));
    assert!(!exists(&case.meta("config")));
}

// ---------------------------------------------------------------------------------------------
// Preexisting names are collisions, never reused, and the ledger is released only for what was never created
// ---------------------------------------------------------------------------------------------

/// The destination-relative creates of a clean run in order: `(path beneath .git, is a file)`.
fn creation_order(
    capsule: &CustomCapsuleV1,
    cformat: CustodyGitObjectFormatV1,
) -> Vec<(String, bool)> {
    let mut case = MetaCaseV1::of(capsule, cformat);
    let git = case.git();
    let events = std::rc::Rc::new(std::cell::RefCell::new(Vec::<(String, bool)>::new()));
    let log = events.clone();
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeObjectCreate, move |event| {
        let relative = event.path.strip_prefix(&git).expect("beneath .git");
        log.borrow_mut()
            .push((relative.display().to_string(), event.label == "file"));
    });
    let _ = case.done("a clean run");
    let order = events.borrow().clone();
    order
}

/// A preplanted file, empty directory, or symlink at each entry the step creates (every directory and file
/// of both frames, and the config) is a collision: the planted entry is left exactly as it was and nothing
/// is written through it or beneath it, the entry that was never created is given back to the ledger and
/// nothing else is, the facts name exactly what this invocation created before it, and a planted entry is
/// never reused as a directory.
#[test]
fn b2b_preexisting_names_are_collisions_and_stay_unchanged() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let order = creation_order(&capsule, CustodyGitObjectFormatV1::Sha1);
    assert_eq!(
        order.len(),
        13,
        "twelve frame entries and the config: {order:?}"
    );
    assert_eq!(order.last(), Some(&("config".to_owned(), true)));
    for (index, (slot, _)) in order.iter().enumerate() {
        for kind in [
            PlantV1::RegularFile,
            PlantV1::EmptyDirectory,
            PlantV1::Symlink,
        ] {
            let row = format!("{slot} {kind:?}");
            let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            let (_outside_area, outside) = external_dir_with(&["decoy"]);
            let outside_before = snapshot(&outside);
            let target = case.meta(slot);
            let planted = std::rc::Rc::new(std::cell::Cell::new(false));
            let (hooked, at, away) = (planted.clone(), target.clone(), outside.clone());
            let _hook =
                install_git_hook_for_test(GitHookPointV1::BeforeObjectCreate, move |event| {
                    if event.path == at && !hooked.replace(true) {
                        plant(&at, kind, &away);
                    }
                });
            let failure = case.refused(&row);
            assert!(planted.get(), "{row}: the plant never ran");
            let full = format!("repository/.git/{slot}");
            assert!(
                matches!(&failure.cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { name })
                        if *name == full),
                "{row}: {:?}",
                failure.cause
            );
            // What came before it was created and charged; it and everything after it was not.
            let before = &order[..index];
            let files_before = before.iter().filter(|(_, file)| *file).count();
            assert_eq!(failure.active_materialization_began, index > 0, "{row}");
            assert_eq!(
                failure.partial.directories.len(),
                before.len() - files_before,
                "{row}"
            );
            assert_eq!(failure.partial.files.len(), files_before, "{row}");
            assert!(failure.partial.in_flight.is_none(), "{row}");
            assert_eq!(failure.partial.charged.entries, index as u64, "{row}");
            let want_bytes: u64 = failure.partial.files.iter().map(|file| file.length).sum();
            assert_eq!(failure.partial.charged.bytes, want_bytes, "{row}");
            // The completed step is the caller's, or Refs when only the config collided.
            let want_step = if slot == "config" {
                Some(GitPlaneStepV1::Refs)
            } else {
                B2B_COMPLETED_V1
            };
            assert_eq!(failure.last_completed, want_step, "{row}");
            for (earlier, _) in before {
                assert!(
                    exists(&case.meta(earlier)),
                    "{row}: {earlier} was created before"
                );
            }
            for (later, _) in &order[index + 1..] {
                assert!(
                    !exists(&case.meta(later)),
                    "{row}: {later} was created after"
                );
            }
            let on_disk = case.metadata_on_disk();
            assert_eq!(
                on_disk.len(),
                index + 1,
                "{row}: the earlier entries and the planted one"
            );
            match kind {
                PlantV1::RegularFile => {
                    assert_eq!(
                        std::fs::read(&target).expect("planted"),
                        b"planted",
                        "{row}"
                    );
                }
                PlantV1::EmptyDirectory => {
                    assert!(
                        listing(&target).is_empty(),
                        "{row}: something was written inside"
                    );
                }
                PlantV1::Symlink => {
                    assert_eq!(
                        std::fs::read_link(&target).expect("a link"),
                        outside,
                        "{row}"
                    );
                    assert_eq!(snapshot(&outside), outside_before, "{row}: written through");
                }
            }
        }
    }
}

/// A refused invocation leaves every created byte, and a second invocation over the same retained value
/// (after a success, and after a partial failure) refuses at its FIRST entry as a collision: it overwrites
/// nothing, begins nothing, and its own reservation is given back.
#[test]
fn b2b_a_second_invocation_refuses_and_cannot_overwrite_the_first_partial_state() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let order = creation_order(&capsule, CustodyGitObjectFormatV1::Sha1);
    let first_name = format!("repository/.git/{}", order[0].0);

    // After a success.
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let _ = case.done("the first invocation");
    let after_first = snapshot(&case.dest().path);
    let ledger = case.ledger();
    let failure = case.refused("the second invocation");
    assert!(
        matches!(&failure.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { name })
                if *name == first_name),
        "{:?}",
        failure.cause
    );
    assert!(!failure.active_materialization_began, "it created nothing");
    assert_eq!(failure.partial.charged, none_charged());
    assert_eq!(case.ledger(), ledger, "the second reservation was released");
    assert_eq!(snapshot(&case.dest().path), after_first, "byte-identical");

    // After a partial failure: the third entry was refused on its device after it was created.
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let third = format!("repository/.git/{}", order[2].0);
    let _device = override_created_dev_for_test(&third, device_of(&case.dest().path) + 1);
    let first = case.refused("the first invocation");
    assert!(
        matches!(
            first.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::DeviceCrossing { .. })
        ),
        "{:?}",
        first.cause
    );
    assert!(first.active_materialization_began);
    let after_first = snapshot(&case.dest().path);
    let ledger = case.ledger();
    let second = case.refused("the second invocation");
    assert!(
        matches!(&second.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { name })
                if *name == first_name),
        "{:?}",
        second.cause
    );
    assert!(!second.active_materialization_began);
    assert_eq!(case.ledger(), ledger);
    assert_eq!(
        snapshot(&case.dest().path),
        after_first,
        "the partial state is byte-identical"
    );
}

// ---------------------------------------------------------------------------------------------
// Every original ref is cross-checked over the retained FINAL descriptors, before any config exists
// ---------------------------------------------------------------------------------------------

type RefsCheckV1 = fn(&RefsFaultV1) -> bool;
type RefsEditV1 = fn(&CustomCapsuleV1, &mut RealSpecsV1);
type RefsRowV1 = (&'static str, RefsEditV1, RefsCheckV1);

/// A refusal of the ref agreement leaves the whole metadata restored and no config: every frame entry exists
/// byte for byte, the last completed step is `Metadata`, and the facts are the disk.
fn assert_refs_refusal(row: &str, case: &MetaCaseV1, failure: &MetadataFailureV1) {
    assert_eq!(
        failure.last_completed,
        Some(GitPlaneStepV1::Metadata),
        "{row}"
    );
    assert!(failure.active_materialization_began, "{row}");
    assert!(!exists(&case.meta("config")), "{row}: no config");
    assert_eq!(
        case.metadata_on_disk(),
        case.expected_frames(),
        "{row}: every frame entry is restored and nothing else"
    );
    assert!(failure.partial.in_flight.is_none(), "{row}");
    assert_metadata_partial_is_the_disk(row, case, failure, 0);
}

fn refs_fault_of(row: &str, failure: &MetadataFailureV1) -> RefsFaultV1 {
    match &failure.cause {
        GitBootstrapErrorV1::Refs(fault) => fault.clone(),
        other => panic!("{row}: {other:?}"),
    }
}

fn absent_like(oid: &str) -> String {
    "f".repeat(oid.len())
}

/// Frames whose files are well formed bytes but whose refs are wrong (so pass B1a, which judges names and
/// types only, admitted them) are refused by the agreement over the restored files, in both formats: an
/// object absent from the inventory, a wrong kind, every malformed loose row, a dangling or cyclic or too
/// deep symbolic chain, every malformed packed row, reflog, and FETCH_HEAD row, a bad ref name, and a
/// packed ref that conflicts with a loose one. Each leaves every frame entry restored, no config, and the
/// step `Metadata` completed.
#[test]
fn b2b_the_restored_files_are_agreed_with_the_manifest_and_a_bad_ref_stops_before_the_config() {
    let rows: Vec<RefsRowV1> = vec![
        (
            "a ref naming an object absent from the inventory",
            |_, specs| {
                specs.refs = specs.refs.clone().file(
                    "refs/heads/ghost",
                    format!("{}\n", absent_like(&specs.commit)),
                );
            },
            |fault| matches!(fault, RefsFaultV1::TargetAbsent { name, .. } if name == "refs/heads/ghost"),
        ),
        (
            "a branch naming a tree",
            |capsule, specs| {
                let tree = real_object(capsule, KindV1::Tree);
                specs.refs = specs
                    .refs
                    .clone()
                    .file("refs/heads/tree", format!("{}\n", tree.object_id()));
            },
            |fault| matches!(fault, RefsFaultV1::TargetKind { name, expected: "commit", found: "tree", .. } if name == "refs/heads/tree"),
        ),
        (
            "a malformed loose row",
            |_, specs| specs.refs = specs.refs.clone().file("refs/heads/bad", "garbage\n"),
            |fault| matches!(fault, RefsFaultV1::Row { why: RowFaultV1::ObjectId, path } if path == "refs/heads/bad"),
        ),
        (
            "an empty loose file",
            |_, specs| specs.refs = specs.refs.clone().file("refs/heads/empty", ""),
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Row {
                        why: RowFaultV1::EmptyFile,
                        ..
                    }
                )
            },
        ),
        (
            "a CRLF loose row",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .file("refs/heads/crlf", format!("{}\r\n", specs.commit));
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Row {
                        why: RowFaultV1::ObjectId,
                        ..
                    }
                )
            },
        ),
        (
            "two lines in a loose file",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .file("refs/heads/two", format!("{0}\n{0}\n", specs.commit));
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Row {
                        why: RowFaultV1::ExtraLine,
                        ..
                    }
                )
            },
        ),
        (
            "a loose file without its final line feed",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .file("refs/heads/open", specs.commit.clone());
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Row {
                        why: RowFaultV1::PartialLine,
                        ..
                    }
                )
            },
        ),
        (
            "a dangling symbolic ref",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .file("refs/heads/dang", "ref: refs/heads/nowhere\n");
            },
            |fault| matches!(fault, RefsFaultV1::Dangling { name, target } if name == "refs/heads/dang" && target == "refs/heads/nowhere"),
        ),
        (
            "a symbolic cycle",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .file("refs/heads/a", "ref: refs/heads/b\n")
                    .file("refs/heads/b", "ref: refs/heads/a\n");
            },
            |fault| matches!(fault, RefsFaultV1::Cycle { .. }),
        ),
        (
            "a symbolic chain of six refs from HEAD",
            |_, specs| {
                let mut refs = specs
                    .refs
                    .clone()
                    .without("HEAD")
                    .file("HEAD", "ref: refs/heads/s1\n");
                for index in 1..6 {
                    let target = if index == 5 {
                        "refs/heads/main".to_owned()
                    } else {
                        format!("refs/heads/s{}", index + 1)
                    };
                    refs = refs.file(&format!("refs/heads/s{index}"), format!("ref: {target}\n"));
                }
                specs.refs = refs;
            },
            |fault| matches!(fault, RefsFaultV1::TooDeep { name } if name == "HEAD"),
        ),
        (
            "HEAD naming something that is not a ref",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .without("HEAD")
                    .file("HEAD", "ref: elsewhere/x\n");
            },
            |fault| matches!(fault, RefsFaultV1::Row { why: RowFaultV1::SymbolicTarget(_), path } if path == "HEAD"),
        ),
        (
            "ORIG_HEAD naming a branch symbolically",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .without("ORIG_HEAD")
                    .file("ORIG_HEAD", "ref: refs/heads/main\n");
            },
            |fault| matches!(fault, RefsFaultV1::Row { why: RowFaultV1::ObjectId, path } if path == "ORIG_HEAD"),
        ),
        (
            "a loose ref named like a lock file",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .file("refs/heads/main.lock", format!("{}\n", specs.commit));
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::RefName {
                        why: RefNameFaultV1::LockSuffix,
                        ..
                    }
                )
            },
        ),
        (
            "a packed row with a peeled row but no ref before it",
            |_, specs| {
                specs.refs = specs.refs.clone().without("packed-refs").file(
                    "packed-refs",
                    format!("{PACKED_HEADER_V1}^{}\n", specs.commit),
                );
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Row {
                        why: RowFaultV1::PeeledOrphan,
                        ..
                    }
                )
            },
        ),
        (
            "a malformed packed-refs header",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .without("packed-refs")
                    .file("packed-refs", "# pack-refs with: unknown \n");
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Row {
                        why: RowFaultV1::PackedHeader,
                        ..
                    }
                )
            },
        ),
        (
            "packed rows out of order under the sorted trait",
            |_, specs| {
                specs.refs = specs.refs.clone().without("packed-refs").file(
                    "packed-refs",
                    format!(
                        "{PACKED_HEADER_V1}{0} refs/heads/z\n{0} refs/heads/a\n",
                        specs.commit
                    ),
                );
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Row {
                        why: RowFaultV1::PackedOrder,
                        ..
                    }
                )
            },
        ),
        (
            "a peeled row after a commit",
            |_, specs| {
                specs.refs = specs.refs.clone().without("packed-refs").file(
                    "packed-refs",
                    format!("{PACKED_HEADER_V1}{0} refs/heads/a\n^{0}\n", specs.commit),
                );
            },
            |fault| matches!(fault, RefsFaultV1::PeeledNotTag { name } if name == "refs/heads/a"),
        ),
        (
            "a tag with no peeled row under the fully-peeled trait",
            |_, specs| {
                specs.refs = specs.refs.clone().without("packed-refs").file(
                    "packed-refs",
                    format!("{PACKED_HEADER_V1}{} refs/tags/v1\n", specs.tag),
                );
            },
            |fault| matches!(fault, RefsFaultV1::PeelMissing { name } if name == "refs/tags/v1"),
        ),
        (
            "a packed ref under a loose one",
            |_, specs| {
                specs.refs = specs
                    .refs
                    .clone()
                    .without("packed-refs")
                    .file(
                        "packed-refs",
                        format!("{PACKED_HEADER_V1}{} refs/tags/x/y\n", specs.commit),
                    )
                    .file("refs/tags/x", format!("{}\n", specs.commit));
            },
            |fault| matches!(fault, RefsFaultV1::Conflict { .. }),
        ),
        (
            "a malformed reflog row",
            |_, specs| {
                specs.logs = specs
                    .logs
                    .clone()
                    .without("logs/HEAD")
                    .file("logs/HEAD", "not a reflog row\n");
            },
            |fault| matches!(fault, RefsFaultV1::Row { why: RowFaultV1::LogRow, path } if path == "logs/HEAD"),
        ),
        (
            "a malformed FETCH_HEAD row",
            |_, specs| specs.refs = specs.refs.clone().file("FETCH_HEAD", "not a row\n"),
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Row {
                        why: RowFaultV1::FetchHeadRow,
                        ..
                    }
                )
            },
        ),
        (
            "a file under logs that is no reflog",
            |_, specs| specs.logs = specs.logs.clone().file("logs/stray", "x\n"),
            |fault| matches!(fault, RefsFaultV1::UnexpectedFile { path } if path == "logs/stray"),
        ),
    ];
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let capsule = captured(cformat);
        let format = core_format(cformat);
        for (row, edit, check) in &rows {
            let row = format!("{cformat:?}: {row}");
            let mut specs = real_specs(&capsule, format);
            edit(&capsule, &mut specs);
            let mut case = MetaCaseV1::with_frames(
                &capsule,
                cformat,
                &specs.refs,
                Some(&specs.logs),
                specs.manifest_refs.clone(),
            );
            let failure = case.refused(&row);
            let fault = refs_fault_of(&row, &failure);
            assert!(check(&fault), "{row}: {fault:?}");
            assert_refs_refusal(&row, &case, &failure);
        }
    }
}

/// The agreement also checks every ORIGINAL ref against the restored state: with the frames themselves fine,
/// a manifest that lists a ref that was not restored, a different target, a different symbolic target, an
/// unborn ref that exists, or a name that is no ref name is refused after the metadata is restored and before
/// any config exists.
#[test]
fn b2b_every_original_ref_is_cross_checked_by_name_and_target() {
    type EditV1 = fn(&CustomCapsuleV1, &RealSpecsV1) -> Vec<CustodyOriginalRefV1>;
    let rows: Vec<(&str, EditV1, RefsCheckV1)> = vec![
        (
            "an original ref that was not restored",
            |capsule, specs| {
                let mut refs = specs.manifest_refs.clone();
                refs.push(direct_ref(
                    "refs/heads/ghost",
                    &real_object(capsule, KindV1::Commit),
                ));
                refs
            },
            |fault| matches!(fault, RefsFaultV1::MissingOriginal { name } if name == "refs/heads/ghost"),
        ),
        (
            "an original ref with another direct target",
            |capsule, specs| {
                let mut refs = specs.manifest_refs.clone();
                refs.retain(|record| record.name().as_bytes() != b"refs/heads/main");
                refs.push(direct_ref(
                    "refs/heads/main",
                    &real_object(capsule, KindV1::Tree),
                ));
                refs
            },
            |fault| matches!(fault, RefsFaultV1::OriginalMismatch { name, .. } if name == "refs/heads/main"),
        ),
        (
            "an original HEAD with another symbolic target",
            |_, specs| {
                let mut refs = specs.manifest_refs.clone();
                refs[0] = symbolic_ref("HEAD", "refs/heads/other");
                refs
            },
            |fault| matches!(fault, RefsFaultV1::OriginalMismatch { name, .. } if name == "HEAD"),
        ),
        (
            "an original unborn ref that exists",
            |_, specs| {
                let mut refs = specs.manifest_refs.clone();
                refs.retain(|record| record.name().as_bytes() != b"refs/heads/main");
                refs.push(
                    CustodyOriginalRefV1::new(
                        LosslessPathV1::from_bytes(b"refs/heads/main".to_vec()),
                        CustodyRefTargetV1::Unborn,
                    )
                    .expect("an unborn ref"),
                );
                refs
            },
            |fault| matches!(fault, RefsFaultV1::OriginalMismatch { name, .. } if name == "refs/heads/main"),
        ),
        (
            "an original ref that is not a ref name",
            |capsule, specs| {
                let mut refs = specs.manifest_refs.clone();
                refs.push(direct_ref(
                    "refs/heads/a..b",
                    &real_object(capsule, KindV1::Commit),
                ));
                refs
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::ManifestName {
                        why: RefNameFaultV1::DoubleDot,
                        ..
                    }
                )
            },
        ),
        (
            "an original symbolic ref with an invalid target",
            |_, specs| {
                let mut refs = specs.manifest_refs.clone();
                refs.push(symbolic_ref("refs/heads/link", "not-under-refs"));
                refs
            },
            |fault| matches!(fault, RefsFaultV1::ManifestTarget { .. }),
        ),
        (
            "an original ORIG_HEAD that is not the restored one",
            |capsule, specs| {
                let mut refs = specs.manifest_refs.clone();
                refs.retain(|record| record.name().as_bytes() != b"ORIG_HEAD");
                refs.push(direct_ref("ORIG_HEAD", &real_object(capsule, KindV1::Tree)));
                refs
            },
            |fault| matches!(fault, RefsFaultV1::OriginalMismatch { name, .. } if name == "ORIG_HEAD"),
        ),
    ];
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let capsule = captured(cformat);
        let format = core_format(cformat);
        for (row, edit, check) in &rows {
            let row = format!("{cformat:?}: {row}");
            let specs = real_specs(&capsule, format);
            let mut case = MetaCaseV1::with_frames(
                &capsule,
                cformat,
                &specs.refs,
                Some(&specs.logs),
                specs.manifest_refs.clone(),
            );
            // The frames were prevalidated and copied; the manifest the agreement judges is changed after.
            let refs = edit(&capsule, &specs);
            set_refs(&mut case.store.boot.verified, refs);
            let failure = case.refused(&row);
            let fault = refs_fault_of(&row, &failure);
            assert!(check(&fault), "{row}: {fault:?}");
            assert_refs_refusal(&row, &case, &failure);
        }
    }
}

/// The limits of the refs agreement apply to the retained final descriptors, not only to byte slices: a
/// loose-file cap, an entry cap, and a line cap each refuse through the real descriptors, after the metadata
/// is restored and before any config.
#[test]
fn b2b_the_ref_limits_apply_through_the_retained_final_descriptors() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let rows: Vec<(&str, RefsLimitsV1, RefsCheckV1)> = vec![
        (
            "a loose file cap below HEAD's length",
            RefsLimitsV1 {
                loose_file_bytes: 10,
                ..RefsLimitsV1::v1()
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Limit {
                        what: RefsLimitKindV1::LooseFile,
                        bound: 10
                    }
                )
            },
        ),
        (
            "a line cap below the packed rows",
            RefsLimitsV1 {
                line_bytes: 20,
                ..RefsLimitsV1::v1()
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Limit {
                        what: RefsLimitKindV1::Line,
                        bound: 20
                    }
                )
            },
        ),
        (
            "an entry cap below the restored refs",
            RefsLimitsV1 {
                entries: 2,
                ..RefsLimitsV1::v1()
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Limit {
                        what: RefsLimitKindV1::Entries,
                        bound: 2
                    }
                )
            },
        ),
        (
            "a retained-bytes cap below the restored refs",
            RefsLimitsV1 {
                retained_bytes: 100,
                ..RefsLimitsV1::v1()
            },
            |fault| {
                matches!(
                    fault,
                    RefsFaultV1::Limit {
                        what: RefsLimitKindV1::Retained,
                        bound: 100
                    }
                )
            },
        ),
    ];
    for (row, limits, check) in rows {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let failure =
            match case.attempt_with(far_deadline(), B2B_COMPLETED_V1, B2B_TABLE_BOUND_V1, limits) {
                Ok(_) => panic!("{row}: must refuse"),
                Err(failure) => failure,
            };
        let fault = refs_fault_of(row, &failure);
        assert!(check(&fault), "{row}: {fault:?}");
        assert_refs_refusal(row, &case, &failure);
    }
}

// ---------------------------------------------------------------------------------------------
// The agreement reads the retained descriptors: integrity outranks content, and a swapped name is never read
// ---------------------------------------------------------------------------------------------

/// The one clock label the agreement begins with: the swaps below happen right after it, before the recheck
/// that precedes the first read.
const REFS_BEGIN_V1: &str = "metadata-refs";

/// A restored file changed in place between its write and the agreement (the same inode and the same length)
/// is refused as THAT, whatever it now says: a valid but different object id that would otherwise be an
/// ordinary ref refusal, and bytes that are no ref at all. The retained descriptor's digest is the
/// integrity guard, and it outranks the parsers.
#[test]
fn b2b_a_file_changed_in_place_is_refused_as_changed_before_anything_it_says() {
    use std::os::unix::fs::FileExt as _;
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let tree = real_object(&capsule, KindV1::Tree).object_id().to_owned();
    for (row, change) in [
        (
            "a valid object id of another kind",
            Box::new(move |path: &Path, length: usize| {
                let file = std::fs::OpenOptions::new()
                    .write(true)
                    .open(path)
                    .expect("open");
                file.write_all_at(format!("{tree}\n").as_bytes(), 0)
                    .expect("rewrite");
                assert_eq!(length, 41);
            }) as Box<dyn Fn(&Path, usize)>,
        ),
        (
            "bytes that are no ref",
            Box::new(|path: &Path, _length: usize| {
                let file = std::fs::OpenOptions::new()
                    .write(true)
                    .open(path)
                    .expect("open");
                file.write_all_at(b"zzzzzzzz", 0).expect("rewrite");
            }),
        ),
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let target = case.meta("ORIG_HEAD");
        // The frames' own bytes, by the test's decode: nothing is restored yet.
        let length = case.expected_frames()["ORIG_HEAD"]
            .as_ref()
            .expect("ORIG_HEAD is a file")
            .len();
        let changing = target.clone();
        let acted = std::cell::Cell::new(false);
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            if event.label == REFS_BEGIN_V1 && !acted.replace(true) {
                change(&changing, length);
            }
        });
        let failure = case.refused(row);
        assert!(
            matches!(&failure.cause, GitBootstrapErrorV1::MetadataCopy { relative, .. }
                if relative == "ORIG_HEAD"),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(
            failure.last_completed,
            Some(GitPlaneStepV1::Metadata),
            "{row}"
        );
        assert!(!exists(&case.meta("config")), "{row}");
    }
}

/// A restored file whose NAME is swapped (for a link to a copy of the very same bytes, for another inode
/// holding them, or for nothing) is refused by the recheck that precedes the agreement's first read: the
/// replacement is never opened or read, and nothing outside is touched. Every refusal leaves the
/// metadata restored, no config, and the step `Metadata` completed.
#[test]
fn b2b_a_restored_file_swapped_before_the_agreement_is_never_read_by_name() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for action in ["a link to a copy of the bytes", "a new inode", "moved away"] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let target = case.meta("refs/heads/main");
        let original = case.expected_frames()["refs/heads/main"]
            .clone()
            .expect("the loose ref is a file");
        let (_outside_area, outside) = external_dir_with(&["decoy"]);
        let outside_before = snapshot(&outside);
        let copy = outside.join("copy");
        let acting = target.clone();
        let acted = std::cell::Cell::new(false);
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            if event.label != REFS_BEGIN_V1 || acted.replace(true) {
                return;
            }
            match action {
                "a link to a copy of the bytes" => {
                    std::fs::write(&copy, &original).expect("a copy elsewhere");
                    move_away(&acting, "main.moved");
                    std::os::unix::fs::symlink(&copy, &acting).expect("a link in its place");
                }
                "a new inode" => {
                    move_away(&acting, "main.moved");
                    std::fs::write(&acting, &original).expect("the same bytes, a new inode");
                }
                _ => move_away(&acting, "main.moved"),
            }
        });
        let failure = case.refused(action);
        let accepted = match action {
            "a link to a copy of the bytes" => matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. })
            ),
            _ => identity_changed(&failure.cause),
        };
        assert!(accepted, "{action}: {:?}", failure.cause);
        assert_eq!(
            failure.last_completed,
            Some(GitPlaneStepV1::Metadata),
            "{action}"
        );
        assert!(!exists(&case.meta("config")), "{action}");
        let outside_after = snapshot(&outside);
        assert_eq!(
            outside_after.keys().collect::<Vec<_>>(),
            if action == "a link to a copy of the bytes" {
                vec!["copy", "decoy"]
            } else {
                vec!["decoy"]
            },
            "{action}: nothing was created outside"
        );
        assert_eq!(
            outside_after.get("decoy"),
            outside_before.get("decoy"),
            "{action}"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Late swaps: every retained chain is rechecked around each entry
// ---------------------------------------------------------------------------------------------

/// The destination's interesting paths for a swap row, owned so a `'static` hook can carry them.
#[derive(Clone)]
struct MetaPathsV1 {
    root: PathBuf,
    git: PathBuf,
    work: PathBuf,
    bootstrap: PathBuf,
}

impl MetaPathsV1 {
    fn of(case: &MetaCaseV1) -> Self {
        Self {
            root: case.dest().path.clone(),
            git: case.git(),
            work: case.dest().work(),
            bootstrap: case.dest().bootstrap(),
        }
    }
}

/// One swap, by what it does to the destination's paths and an outside directory a link may name.
struct MetaSwapV1 {
    row: &'static str,
    swap: fn(&MetaPathsV1, &Path),
    /// Entries under `repository*` that the swap itself plants (a replacement directory or link).
    planted: usize,
    /// The swap is on the chain of only the slots beneath this metadata directory, if one is named.
    under: Option<&'static str>,
}

fn swap_rows() -> Vec<MetaSwapV1> {
    vec![
        MetaSwapV1 {
            row: "`.git` replaced by a directory",
            swap: |paths, _| {
                move_away(&paths.git, ".git-away");
                std::fs::create_dir(&paths.git).expect("a new directory takes the name");
            },
            planted: 1,
            under: None,
        },
        MetaSwapV1 {
            row: "`.git` replaced by a link",
            swap: |paths, outside| {
                move_away(&paths.git, ".git-away");
                std::os::unix::fs::symlink(outside, &paths.git).expect("a link takes the name");
            },
            planted: 1,
            under: None,
        },
        MetaSwapV1 {
            row: "the repository replaced by a link",
            swap: |paths, outside| {
                let repository = paths.git.parent().expect("the repository").to_path_buf();
                move_away(&repository, "repository-away");
                std::os::unix::fs::symlink(outside, &repository).expect("a link takes the name");
            },
            planted: 1,
            under: None,
        },
        MetaSwapV1 {
            row: "the object copy's `objects` replaced by a link",
            swap: |paths, outside| {
                let objects = paths.git.join("objects");
                move_away(&objects, "objects-away");
                std::os::unix::fs::symlink(outside, &objects).expect("a link takes the name");
            },
            planted: 1,
            under: None,
        },
        MetaSwapV1 {
            row: "the object copy's pack directory replaced by a directory",
            swap: |paths, _| {
                let pack = paths.git.join("objects/pack");
                move_away(&pack, "pack-away");
                std::fs::create_dir(&pack).expect("a new directory takes the name");
            },
            planted: 1,
            under: None,
        },
        MetaSwapV1 {
            row: "the metadata directory `refs` replaced by a link",
            swap: |paths, outside| {
                let refs = paths.git.join("refs");
                move_away(&refs, "refs-away");
                std::os::unix::fs::symlink(outside, &refs).expect("a link takes the name");
            },
            planted: 1,
            under: Some("refs"),
        },
        MetaSwapV1 {
            row: "the bootstrap pack directory replaced",
            swap: |paths, _| {
                let pack = paths.bootstrap.join("objects/pack");
                move_away(&pack, "pack-away");
                std::fs::create_dir(&pack).expect("a new directory takes the name");
                for entry in std::fs::read_dir(pack.with_file_name("pack-away")).expect("the old") {
                    let name = entry.expect("an entry").file_name();
                    std::fs::write(pack.join(name), b"poison").expect("a poisoned file");
                }
            },
            planted: 0,
            under: None,
        },
        MetaSwapV1 {
            row: "the staging directory replaced",
            swap: |paths, _| {
                let plain = paths.work.join("plain");
                move_away(&plain, "plain-away");
                std::fs::create_dir(&plain).expect("a new directory takes the name");
            },
            planted: 0,
            under: None,
        },
        MetaSwapV1 {
            row: "the work directory replaced",
            swap: |paths, _| {
                move_away(&paths.work, ".restore-work-away");
                std::fs::create_dir(&paths.work).expect("a new directory takes the name");
            },
            planted: 0,
            under: None,
        },
        MetaSwapV1 {
            row: "an admitted bootstrap object file replaced by a link",
            swap: |paths, outside| {
                let pack = admitted_path_in(&paths.bootstrap.join("objects/pack"), "pack");
                move_away(&pack, "admitted.moved");
                std::os::unix::fs::symlink(outside.join("decoy"), &pack).expect("a link");
            },
            planted: 0,
            under: None,
        },
        MetaSwapV1 {
            row: "an admitted bootstrap object file replaced by another inode",
            swap: |paths, _| {
                let pack = admitted_path_in(&paths.bootstrap.join("objects/pack"), "pack");
                let bytes = std::fs::read(&pack).expect("the admitted pack");
                move_away(&pack, "admitted.moved");
                std::fs::write(&pack, bytes).expect("the same bytes, a new inode");
            },
            planted: 0,
            under: None,
        },
        MetaSwapV1 {
            row: "an admitted bootstrap object file grown",
            swap: |paths, _| {
                let pack = admitted_path_in(&paths.bootstrap.join("objects/pack"), "pack");
                append_fixture_byte(&pack);
            },
            planted: 0,
            under: None,
        },
        MetaSwapV1 {
            row: "the XDG directory replaced by a link",
            swap: |paths, outside| {
                let xdg = paths.work.join("xdg");
                move_away(&xdg, "xdg-away");
                std::os::unix::fs::symlink(outside, &xdg).expect("a link takes the name");
            },
            planted: 0,
            under: None,
        },
    ]
}

/// [`act_at_guard`] that also records every guard read after the action ran (the hook point holds one hook, so
/// the two cannot be installed apart).
fn act_at_guard_recording(
    label: &'static str,
    nth: usize,
    act: impl Fn() + 'static,
    after: &AfterSwapV1,
) -> GitSeamGuardV1 {
    let seen = std::cell::Cell::new(0_usize);
    let (swapped, labels) = (after.swapped.clone(), after.labels.clone());
    install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        if swapped.get() {
            labels.borrow_mut().push(event.label);
        }
        if event.label == label {
            seen.set(seen.get() + 1);
            if seen.get() == nth {
                act();
            }
        }
    })
}

/// A swap's refusal: a retained directory or file that is no longer the entry its parent holds, or a link
/// where one was.
fn swap_refusal(cause: &GitBootstrapErrorV1) -> bool {
    identity_changed(cause)
        || matches!(
            cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. })
        )
}

/// The guards the step reads after a swap happened: a refusal that comes from the swapped step's OWN recheck
/// never reaches the guard of any later step (a later entry's decode, a frame, a gate, the agreement, the
/// config, the final gate). `in_config_gate` excuses the gate's own first guard, which is where a swap made at
/// the config step's start is refused.
fn assert_refused_within_the_b2b_step(after: &AfterSwapV1, in_config_gate: bool, row: &str) {
    let labels = after.labels.borrow();
    assert!(!labels.is_empty(), "{row}: the swap was never reached");
    for later in [
        "metadata-item",
        "metadata-frame",
        "metadata-decoded",
        "metadata-gate",
        "metadata-read",
        "metadata-refs",
        "metadata-agreed",
        "metadata-config",
        "metadata-final",
    ] {
        if in_config_gate && matches!(later, "metadata-gate" | "metadata-config") {
            continue;
        }
        assert!(
            !labels.contains(&later),
            "{row}: the run went on to `{later}` after the swap: {labels:?}"
        );
    }
}

/// A directory this step created, or one of the chains beneath it, swapped between two entries is caught by
/// the recheck around the next entry, for each of thirteen swaps and for one entry of every shape (a file in the
/// first frame, a directory, a file under a metadata directory, a file in the second frame, and the config):
///
/// - a swap AFTER the pre-create recheck and before the create: the entry that raced went through the
///   retained pin into the moved directory (never through the new name) and is refused by ITS OWN post-create
///   recheck (no later guard of any later step is read), with nothing after it created;
/// - a swap BEFORE the pre-create recheck: refused BEFORE the entry is created at all.
///
/// Nothing is ever written through a link, and every byte created is kept.
#[test]
fn b2b_late_swaps_refuse_through_retained_pins_before_and_after_each_entry() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let order = creation_order(&capsule, CustodyGitObjectFormatV1::Sha1);
    let slots = [
        "HEAD",
        "refs",
        "refs/heads/main",
        "logs/refs/heads/main",
        "config",
    ];
    assert!(swap_rows().iter().any(|row| row.under == Some("refs")));
    let objects_entries = 8_usize;
    for slot in slots {
        let index = order
            .iter()
            .position(|(name, _)| name == slot)
            .expect("a slot of the run");
        let is_file = order[index].1;
        for swap_row in swap_rows() {
            // A swap of a metadata directory is on the chain of the slots beneath it only.
            if let Some(under) = swap_row.under {
                if !slot.starts_with(&format!("{under}/")) {
                    continue;
                }
            }
            for after_pre_recheck in [true, false] {
                let row = format!(
                    "{slot}: {} ({})",
                    swap_row.row,
                    if after_pre_recheck {
                        "after the pre-create recheck"
                    } else {
                        "before it"
                    }
                );
                let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
                let (_outside_area, outside) = external_dir_with(&["decoy"]);
                let outside_before = snapshot(&outside);
                let paths = MetaPathsV1::of(&case);
                let swapping = outside.clone();
                let swap = swap_row.swap;
                let after = AfterSwapV1::new();
                let swapped = after.flag();
                let flag = swapped.clone();
                let act = move || {
                    swap(&paths, &swapping);
                    flag.set(true);
                };
                // One hook per point: the swap made at a guard records the guards after it itself.
                let (_hook, _guards) = if after_pre_recheck {
                    (
                        act_before_creating(case.meta(slot), act),
                        Some(after.record()),
                    )
                } else if slot == "config" {
                    (
                        act_at_guard_recording("metadata-config", 1, act, &after),
                        None,
                    )
                } else {
                    (
                        act_at_guard_recording("metadata-item", index + 1, act, &after),
                        None,
                    )
                };
                let failure = case.refused(&row);
                assert!(swapped.get(), "{row}: the swap never ran");
                assert!(swap_refusal(&failure.cause), "{row}: {:?}", failure.cause);
                assert_refused_within_the_b2b_step(&after, slot == "config", &row);
                assert_eq!(
                    snapshot(&outside),
                    outside_before,
                    "{row}: written through a link"
                );
                let made = if after_pre_recheck { index + 1 } else { index };
                assert_eq!(failure.active_materialization_began, made > 0, "{row}");
                assert_eq!(failure.partial.charged.entries, made as u64, "{row}");
                // Where the refusal is the swapped slot's own post-create recheck, the file it created is
                // in flight with nothing written; a directory is pinned.
                assert_eq!(
                    failure.partial.in_flight.is_some(),
                    after_pre_recheck && is_file,
                    "{row}"
                );
                if let Some(flight) = &failure.partial.in_flight {
                    assert_eq!(flight.written, 0, "{row}");
                }
                assert_eq!(
                    repository_keys(case.dest()),
                    objects_entries + made + swap_row.planted,
                    "{row}: exactly the entries made exist under the repository, and the swap's own"
                );
                // The completed step is the caller's, or Refs once the config step began.
                let want = if slot == "config" {
                    Some(GitPlaneStepV1::Refs)
                } else {
                    B2B_COMPLETED_V1
                };
                assert_eq!(failure.last_completed, want, "{row}");
            }
        }
    }
}

/// A COMPLETED file or directory swapped while a later entry is being restored is caught at the next FULL
/// recheck: at the start of the next frame (before any entry of it is created) when the swap is made between
/// the frames, and at the gate after the last frame (before the refs are agreed and before any config) when it
/// is made inside the last frame. The between-entries recheck is bounded to the new entry's own chain, so a
/// completed sibling is not looked at until then; nothing is written through anything swapped, and every byte
/// is kept.
#[test]
fn b2b_a_completed_entry_swapped_is_caught_at_the_next_full_recheck() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    type SwapFnV1 = Box<dyn Fn(&MetaPathsV1, &Path)>;
    let swaps: Vec<(&str, SwapFnV1)> = vec![
        (
            "a completed file replaced by a link",
            Box::new(|paths, outside| {
                let head = paths.git.join("HEAD");
                move_away(&head, "HEAD.moved");
                std::os::unix::fs::symlink(outside.join("decoy"), &head).expect("a link");
            }),
        ),
        (
            "a completed file replaced by another inode",
            Box::new(|paths, _| {
                let head = paths.git.join("HEAD");
                let bytes = std::fs::read(&head).expect("HEAD");
                move_away(&head, "HEAD.moved");
                std::fs::write(&head, bytes).expect("the same bytes, a new inode");
            }),
        ),
        (
            "a completed file grown",
            Box::new(|paths, _| {
                use std::io::Write as _;
                std::fs::OpenOptions::new()
                    .append(true)
                    .open(paths.git.join("HEAD"))
                    .and_then(|mut file| file.write_all(b"x"))
                    .expect("an appended byte");
            }),
        ),
        (
            "a completed directory replaced",
            Box::new(|paths, _| {
                let tags = paths.git.join("refs/tags");
                move_away(&tags, "tags-away");
                std::fs::create_dir(&tags).expect("a new directory takes the name");
            }),
        ),
    ];
    for (row, swap) in swaps {
        let swap = std::rc::Rc::new(swap);
        // Between the frames: the second frame's own guard runs before its recheck of everything made.
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (_outside_area, outside) = external_dir_with(&["decoy"]);
        let outside_before = snapshot(&outside);
        let (paths, away, acting) = (MetaPathsV1::of(&case), outside.clone(), swap.clone());
        let _hook = act_at_guard("metadata-frame", 2, move || acting(&paths, &away));
        let failure = case.refused(row);
        assert!(
            identity_changed(&failure.cause)
                || matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. })
                ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(snapshot(&outside), outside_before, "{row}");
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
        assert!(!exists(&case.meta("logs")), "{row}: the next frame began");
        assert_eq!(
            failure.partial.charged.entries, 7,
            "{row}: the refs frame, whole"
        );
        drop(_hook);

        // Inside the last frame: the gate after the frames refuses it, before any step completes.
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (paths, away, acting) = (MetaPathsV1::of(&case), outside.clone(), swap.clone());
        let _hook = act_before_creating(case.meta("logs"), move || acting(&paths, &away));
        let failure = case.refused(row);
        assert!(
            identity_changed(&failure.cause)
                || matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. })
                ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(snapshot(&outside), outside_before, "{row}");
        assert_eq!(
            failure.last_completed, B2B_COMPLETED_V1,
            "{row}: Metadata is not complete"
        );
        assert_eq!(
            failure.partial.charged.entries, 12,
            "{row}: both frames were whole"
        );
        assert!(exists(&case.meta("logs/refs/heads/main")), "{row}");
        assert!(!exists(&case.meta("config")), "{row}");
    }
}

// ---------------------------------------------------------------------------------------------
// The final gate: the root is checked LAST, and a late link or root swap refuses with every byte kept
// ---------------------------------------------------------------------------------------------

/// The destination root swapped just before the final gate refuses with every entry already made: the facts
/// name all of them, they are all in the moved root, the replacement stays empty, and the last completed step
/// is `Refs` (the config step completes only in a success).
#[test]
fn b2b_a_root_swapped_before_the_final_gate_refuses_with_every_effect_preserved() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let root = case.dest().path.clone();
    let away = root.with_file_name("dest-away");
    let (swap_root, swap_away) = (root.clone(), away.clone());
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeMetadataFinalGate, move |_| {
        std::fs::rename(&swap_root, &swap_away).expect("the root moves away");
        std::fs::create_dir(&swap_root).expect("an empty root takes its name");
    });
    let failure = case.refused("the final gate");
    assert!(identity_changed(&failure.cause), "{:?}", failure.cause);
    assert!(failure.active_materialization_began);
    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Refs));
    assert_eq!(failure.partial.directories.len(), 6);
    assert_eq!(
        failure.partial.files.len(),
        7,
        "six frame files and the config"
    );
    assert!(failure.partial.in_flight.is_none());
    assert_eq!(failure.partial.charged.entries, 13);
    assert_eq!(
        case.dest().entries(),
        Vec::<String>::new(),
        "the replacement root stays empty"
    );
    assert_eq!(
        std::fs::read(away.join("repository/.git/config")).expect("the config in the moved root"),
        golden_config(case.format)
    );
}

/// A file or directory of the metadata (or the config) swapped between its creation and the final gate is
/// refused there, never followed: a link, another inode holding the same bytes, a longer file, or a
/// directory in its place, a replaced metadata directory, and a replaced object copy file. Each leaves every
/// byte, and the step `Refs`.
#[test]
fn b2b_a_late_swap_before_the_final_gate_refuses_whatever_it_replaced() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    type FinalSwapV1 = (&'static str, &'static str, fn(&Path, &Path));
    let rows: [FinalSwapV1; 8] = [
        (
            "a ref file replaced by a link",
            "refs/heads/main",
            |path, outside| {
                move_away(path, "moved");
                std::os::unix::fs::symlink(outside.join("decoy"), path).expect("a link");
            },
        ),
        (
            "the config replaced by a link",
            "config",
            |path, outside| {
                move_away(path, "moved");
                std::os::unix::fs::symlink(outside.join("decoy"), path).expect("a link");
            },
        ),
        (
            "a reflog replaced by another inode",
            "logs/HEAD",
            |path, _| {
                let bytes = std::fs::read(path).expect("the reflog");
                move_away(path, "moved");
                std::fs::write(path, bytes).expect("the same bytes, a new inode");
            },
        ),
        ("the config grown", "config", |path, _| {
            use std::io::Write as _;
            std::fs::OpenOptions::new()
                .append(true)
                .open(path)
                .and_then(|mut file| file.write_all(b"x"))
                .expect("an appended byte");
        }),
        (
            "a ref file replaced by a directory",
            "ORIG_HEAD",
            |path, _| {
                move_away(path, "moved");
                std::fs::create_dir(path).expect("a directory takes the name");
            },
        ),
        ("a metadata directory replaced", "logs/refs", |path, _| {
            move_away(path, "moved");
            std::fs::create_dir(path).expect("a new directory takes the name");
        }),
        (
            "a metadata directory replaced by a link",
            "refs/heads",
            |path, outside| {
                move_away(path, "moved");
                std::os::unix::fs::symlink(outside, path).expect("a link");
            },
        ),
        (
            "an object copy file replaced by another inode",
            "objects/pack/PACK",
            |path, _| {
                let bytes = std::fs::read(path).expect("the pack");
                move_away(path, "moved");
                std::fs::write(path, bytes).expect("the same bytes, a new inode");
            },
        ),
    ];
    for (row, slot, swap) in rows {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let target = if slot.ends_with("PACK") {
            admitted_path_in(&pack_directory(case.dest()), "pack")
        } else {
            case.meta(slot)
        };
        let (_outside_area, outside) = external_dir_with(&["decoy"]);
        let outside_before = snapshot(&outside);
        let (acting, away) = (target.clone(), outside.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::BeforeMetadataFinalGate, move |_| {
            swap(&acting, &away);
        });
        let failure = case.refused(row);
        assert!(
            identity_changed(&failure.cause)
                || matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. })
                ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(
            snapshot(&outside),
            outside_before,
            "{row}: written through a link"
        );
        assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Refs), "{row}");
        assert_eq!(
            failure.partial.charged.entries, 13,
            "{row}: every entry was already made"
        );
        if row != "the config grown" {
            assert!(
                exists(&target.with_file_name("moved")),
                "{row}: the original bytes are kept beside the swap"
            );
        }
    }
}

/// The `.pack` file in `directory`.
fn admitted_path_in(directory: &Path, extension: &str) -> PathBuf {
    std::fs::read_dir(directory)
        .expect("a pack directory")
        .map(|entry| entry.expect("an entry").path())
        .find(|path| path.extension().is_some_and(|found| found == extension))
        .expect("a pack file")
}

// ---------------------------------------------------------------------------------------------
// Devices and mounts
// ---------------------------------------------------------------------------------------------

/// A created entry on another device refuses for every one of the thirteen entries, and its charge stays: the
/// entry exists (it was created before the device was read), it is named in the facts when it is a file, no
/// later entry is created, and the ledger moved by exactly what the facts report.
#[test]
fn b2b_a_device_mismatch_refuses_for_every_entry_and_keeps_the_charge() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let order = creation_order(&capsule, CustodyGitObjectFormatV1::Sha1);
    for (index, (slot, is_file)) in order.iter().enumerate() {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let name = format!("repository/.git/{slot}");
        let other = device_of(&case.dest().path) + 1;
        let _device = override_created_dev_for_test(&name, other);
        let failure = case.refused(slot);
        assert!(
            matches!(&failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::DeviceCrossing { name: found })
                    if *found == name),
            "{slot}: {:?}",
            failure.cause
        );
        assert!(failure.active_materialization_began, "{slot}");
        assert_eq!(
            failure.partial.charged.entries,
            index as u64 + 1,
            "{slot}: the entry stays charged"
        );
        assert!(exists(&case.meta(slot)), "{slot}: it was created");
        for (later, _) in &order[index + 1..] {
            assert!(
                !exists(&case.meta(later)),
                "{slot}: {later} was created after"
            );
        }
        // A directory refused on its device has no pin; a file is named in flight with nothing written.
        assert_eq!(failure.partial.in_flight.is_some(), *is_file, "{slot}");
        assert_metadata_partial_is_the_disk(slot, &case, &failure, u64::from(!*is_file));
        let want = if slot == "config" {
            Some(GitPlaneStepV1::Refs)
        } else {
            B2B_COMPLETED_V1
        };
        assert_eq!(failure.last_completed, want, "{slot}");
    }
}

/// The mount census runs at the step's entry, after the frames, before the config, and at the final gate: a
/// mount that appears for any ONE census call refuses at that call, with only the entries made before it and
/// the step reported exactly as far as it got, and a census that cannot list the mount points fails closed
/// before anything is created.
#[test]
fn b2b_a_mount_appearing_at_any_census_refuses_and_a_failing_census_fails_closed() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    // The census calls of a clean run, and what each guards: the entries made and the last completed step.
    let expected = [
        (0_u64, B2B_COMPLETED_V1),
        (12, B2B_COMPLETED_V1),
        (12, Some(GitPlaneStepV1::Refs)),
        (13, Some(GitPlaneStepV1::Refs)),
    ];
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let census = crate::custody_mounts::seam::install_list(vec![b"/".to_vec()]);
    let _ = case.done("a clean run");
    assert_eq!(
        census.calls(),
        expected.len(),
        "the census calls of a clean run"
    );
    drop(census);

    for call in 1..=expected.len() {
        let row = format!("call {call}");
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let inside = case
            .dest()
            .path
            .join(".restore-work/home")
            .as_os_str()
            .as_bytes()
            .to_vec();
        // The object copy's own census calls came earlier; this census counts only the step's.
        let _census = crate::custody_mounts::seam::install(Box::new(move |number| {
            if number == call {
                Ok(vec![b"/".to_vec(), inside.clone()])
            } else {
                Ok(vec![b"/".to_vec()])
            }
        }));
        let failure = case.refused(&row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::MountBoundary(_))
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(
            failure.partial.charged.entries,
            expected[call - 1].0,
            "{row}"
        );
        assert_eq!(failure.last_completed, expected[call - 1].1, "{row}");
        assert_eq!(failure.active_materialization_began, call > 1, "{row}");
        assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
    }

    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let _census = crate::custody_mounts::seam::install(Box::new(|_| {
        Err(crate::custody_mounts::CustodyMountErrorV1::MalformedLine { line: 1 })
    }));
    let cause = case.refused_before_any_write("a failing census");
    assert!(
        matches!(
            cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::MountBoundary(_))
        ),
        "{cause:?}"
    );
}

// ---------------------------------------------------------------------------------------------
// Entry and byte exhaustion are exact
// ---------------------------------------------------------------------------------------------

/// The bound is exact at every entry and every byte: with one byte less than an entry needs, the entry is
/// refused and not created; with one byte less than a file's bytes, the file's entry exists and its refused
/// chunk is never written; the headroom of exactly the whole charge succeeds. Everything created before the
/// refusal stays, charged, and the facts say so.
#[test]
fn b2b_entry_and_byte_exhaustion_is_exact_and_leaves_typed_partial_effects() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let order = creation_order(&capsule, CustodyGitObjectFormatV1::Sha1);
    // The lengths of the files, by name, from a clean run (the config included).
    let mut learn = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let done = learn.done("a clean run");
    let lengths: BTreeMap<String, u64> = done
        .files
        .iter()
        .map(|file| (file.relative.clone(), file.length))
        .collect();
    let total_bytes: u64 = lengths.values().sum();
    let bytes_before = |index: usize| -> u64 {
        order[..index]
            .iter()
            .filter(|(_, is_file)| *is_file)
            .map(|(name, _)| lengths[name])
            .sum()
    };

    // The exact fit succeeds.
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    leave_headroom(&case.store.boot.verified, 13 * ENTRY_V1 + total_bytes);
    let done = case.done("the exact fit");
    assert_eq!(
        case.ledger(),
        RESTORE_BYTES_CEILING_V1,
        "the ledger is exactly full"
    );
    assert_eq!(meta_charge(done.charged), 13 * ENTRY_V1 + total_bytes);

    // One byte short of an ENTRY, at each of the thirteen entries.
    for (index, (slot, _)) in order.iter().enumerate() {
        let row = format!("entry {index} ({slot})");
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        leave_headroom(
            &case.store.boot.verified,
            index as u64 * ENTRY_V1 + bytes_before(index) + (ENTRY_V1 - 1),
        );
        let failure = case.refused(&row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Budget(_))
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(failure.active_materialization_began, index > 0, "{row}");
        assert_eq!(
            failure.partial.charged,
            MetadataChargeV1 {
                entries: index as u64,
                bytes: bytes_before(index)
            },
            "{row}"
        );
        assert!(failure.partial.in_flight.is_none(), "{row}");
        assert!(
            !exists(&case.meta(slot)),
            "{row}: the refused entry was not created"
        );
        assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
    }

    // One byte short of a FILE's bytes: its entry exists, empty or partly written, and stays charged.
    for chunk in [None, Some(4_usize)] {
        for (index, (slot, is_file)) in order.iter().enumerate() {
            if !is_file {
                continue;
            }
            let row = format!("bytes of {slot}, chunk {chunk:?}");
            let _chunk = chunk.map(override_object_copy_chunk_for_test);
            let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            let length = lengths[slot];
            leave_headroom(
                &case.store.boot.verified,
                (index as u64 + 1) * ENTRY_V1 + bytes_before(index) + length - 1,
            );
            let failure = case.refused(&row);
            assert!(
                matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Budget(_))
                ),
                "{row}: {:?}",
                failure.cause
            );
            // The refused chunk is the last one: it is never written.
            let last = chunk.map_or(length, |size| ((length - 1) % size as u64) + 1);
            let written = length - last;
            let flight = failure
                .partial
                .in_flight
                .as_ref()
                .expect("the file in flight");
            assert_eq!(
                (
                    flight.relative.as_str(),
                    flight.expected_length,
                    flight.written
                ),
                (slot.as_str(), length, written),
                "{row}"
            );
            assert_eq!(
                failure.partial.charged,
                MetadataChargeV1 {
                    entries: index as u64 + 1,
                    bytes: bytes_before(index) + written
                },
                "{row}"
            );
            assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Failure paths whose real trigger is the storage itself: a partial write and a refused create
// ---------------------------------------------------------------------------------------------

/// What a Captured or Empty run creates first: the first file in canonical order, its length, and how many
/// directories precede it (each charged an entry).
fn first_file_of(case: &MetaCaseV1) -> (String, u64, u64) {
    let generation = generation_of(case);
    let mut directories = 0_u64;
    for frame in &case.store.boot.active_frames {
        let one = &case.store.boot.verified.staged[frame.staged];
        for (path, content) in decoded_entries(&one.file, frame.class, &generation) {
            match content {
                Some(bytes) => return (path, bytes.len() as u64, directories),
                None => directories += 1,
            }
        }
    }
    panic!("a frame holds a file");
}

/// A write that reaches the file only in part (a full disk, a quota, an I/O error after a prefix) leaves
/// exactly that prefix, and the typed facts say so: the file in flight reports the bytes that reached it, the
/// ledger keeps exactly those bytes charged (the part of the chunk that was reserved and never written is
/// given back), and nothing after the failed file is created. A write that reports it wrote nothing is the
/// same refusal, never a loop.
#[test]
fn b2b_a_partial_write_failure_records_exactly_the_bytes_that_reached_the_file() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    for (row, fault) in [
        ("a prefix of the first chunk", ObjectFaultV1::WriteAfter(5)),
        (
            "the first chunk whole, then nothing",
            ObjectFaultV1::WriteAfter(16),
        ),
        (
            "a prefix of the second chunk",
            ObjectFaultV1::WriteAfter(20),
        ),
        (
            "a zero-byte write inside the first chunk",
            ObjectFaultV1::WriteZeroAfter(7),
        ),
    ] {
        let limit = match fault {
            ObjectFaultV1::WriteAfter(limit) | ObjectFaultV1::WriteZeroAfter(limit) => limit,
            other => panic!("not a write fault: {other:?}"),
        };
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (first, length, before) = first_file_of(&case);
        assert!(
            length > limit,
            "{row}: the first file is longer than the limit"
        );
        let _fault = override_object_fault_for_test(fault);
        let failure = case.refused(row);
        match &failure.cause {
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Io(detail)) => {
                assert!(detail.contains(&first), "{row}: {detail}");
            }
            other => panic!("{row}: {other:?}"),
        }
        assert!(failure.active_materialization_began, "{row}");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the first file in flight");
        assert_eq!(flight.written, limit, "{row}: the retained fact");
        let on_disk = std::fs::read(case.meta(&first)).expect("the partial file");
        assert_eq!(on_disk.len() as u64, limit, "{row}: the file on disk");
        let whole = case.expected_frames()[&first].clone().expect("a file");
        assert_eq!(&whole[..on_disk.len()], &on_disk[..], "{row}: a prefix");
        assert_eq!(
            failure.partial.charged,
            MetadataChargeV1 {
                entries: before + 1,
                bytes: limit
            },
            "{row}: exactly the bytes that reached the file stay charged"
        );
        assert!(failure.partial.files.is_empty(), "{row}");
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1, "{row}");
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }
}

/// A create that fails for any reason but a collision keeps its entry charged (the primitive cannot say
/// whether anything was created) and creates nothing after it, and materialization is reported begun even when
/// the refused create was the FIRST entry of the step: the allowance is not given back, unlike a collision's.
#[test]
fn b2b_a_file_create_failure_other_than_a_collision_keeps_its_charge_and_reports_begun() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let (first, _, before) = first_file_of(&case);
    assert_eq!(before, 0, "the first entry of the step is a file");
    let _fault = override_object_fault_for_test(ObjectFaultV1::CreateFile);
    let failure = case.refused("a refused create");
    assert!(
        matches!(
            failure.cause,
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Io(_))
        ),
        "{:?}",
        failure.cause
    );
    assert!(
        failure.active_materialization_began,
        "the create may have made the file"
    );
    assert_eq!(
        failure.partial.charged,
        MetadataChargeV1 {
            entries: 1,
            bytes: 0
        },
        "the refused file's entry stays charged"
    );
    assert!(failure.partial.in_flight.is_none(), "no file was created");
    assert!(failure.partial.files.is_empty());
    assert_eq!(case.entry_count(), 0, "{first}: nothing is on disk");
    assert_eq!(failure.last_completed, B2B_COMPLETED_V1);
}

// ---------------------------------------------------------------------------------------------
// The one deadline paces every step
// ---------------------------------------------------------------------------------------------

/// The one deadline of the pacing rows. A clean run of these small files takes milliseconds.
const B2B_DEADLINE_V1: Duration = Duration::from_secs(2);

/// Every label a clean run reads the clock at: each step of the success path is paced (the frame rehash's and
/// the refs agreement's own guards included).
const B2B_GUARDS_V1: [&str; 22] = [
    "chain",
    "frame-rehash",
    "frame-rewind",
    "metadata-agreed",
    "metadata-chain",
    "metadata-checked",
    "metadata-config",
    "metadata-decoded",
    "metadata-entry",
    "metadata-final",
    "metadata-frame",
    "metadata-gate",
    "metadata-item",
    "metadata-read",
    "metadata-refs",
    "objects-chain",
    "objects-source",
    "refs-manifest",
    "refs-resolved",
    "refs-structure",
    "refs-targets",
    "root",
];

fn timed_out_metadata(
    row: &str,
    result: Result<FinalMetadataV1, Box<MetadataFailureV1>>,
) -> Box<MetadataFailureV1> {
    match result {
        Ok(_) => panic!("{row}: no success after the deadline"),
        Err(failure) => {
            assert!(
                matches!(
                    failure.cause,
                    GitBootstrapErrorV1::Git(CustodyGitError::Timeout)
                ),
                "{row}: {:?}",
                failure.cause
            );
            failure
        }
    }
}

/// A deadline already spent refuses before the first entry: the clock is read once, and nothing is created,
/// charged, or pinned.
#[test]
fn b2b_a_spent_deadline_refuses_before_any_write() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let spent = Instant::now();
    std::thread::sleep(Duration::from_millis(5));
    let (labels, _hook) = record_guards();
    let tree = snapshot(&case.dest().path);
    let ledger = case.ledger();
    let failure = timed_out_metadata("a spent deadline", case.attempt_by(spent));
    assert!(!failure.active_materialization_began);
    assert_eq!(*labels.borrow(), ["metadata-entry"]);
    assert_eq!(case.ledger(), ledger);
    assert_eq!(snapshot(&case.dest().path), tree);
    assert_eq!(failure.last_completed, B2B_COMPLETED_V1);
}

/// The clock is read at exactly the documented guards, so no step is unobserved: the first guard is the
/// entry, the last is the one immediately before the destination root's identity check (the final gate's),
/// the distinct labels are exactly the documented ones, and each is read exactly as often as the design says.
/// The recheck runs `5 + frames + 2 dirs + 3 (files + config)` times before the final gate, and every one is
/// followed by the clock.
#[test]
fn b2b_the_guards_of_a_clean_run_are_the_documented_ones() {
    for populated in [true, false] {
        let cformat = CustodyGitObjectFormatV1::Sha1;
        let capsule = if populated {
            captured(cformat)
        } else {
            empty(cformat)
        };
        let mut case = MetaCaseV1::of(&capsule, cformat);
        let staging = case.store.boot.verified.destination.staging.borrow().len();
        let bootstrap_directories = case.store.boot.directories.len();
        let (frames, files, directories) = {
            let (names, dirs) = expected_names(&case);
            (case.store.plan.frames.len(), names.len(), dirs.len())
        };
        let (labels, _hook) = record_guards();
        let _ = case.done("a clean run");
        let labels = labels.borrow();
        assert_eq!(labels.first().copied(), Some("metadata-entry"));
        assert_eq!(labels.last().copied(), Some("root"));
        let count = |wanted: &str| labels.iter().filter(|label| **label == wanted).count();
        // Gates: the entry, after the frames, before the config; rechecks: one per frame, two per directory,
        // three per file and the config, one before the refs, one after the config.
        let checked = 5 + frames + 2 * directories + 3 * (files + 1);
        let sweeps = checked + 1;
        let objects_files = if populated { 3 } else { 0 };
        let expected: Vec<(&str, usize)> = vec![
            ("metadata-entry", 1),
            ("metadata-gate", 3),
            ("metadata-checked", checked),
            ("metadata-frame", frames),
            ("metadata-item", directories + files),
            ("metadata-read", files + 1),
            ("metadata-decoded", frames),
            ("metadata-refs", 1),
            ("metadata-agreed", 1),
            ("metadata-config", 1),
            ("metadata-final", 1),
            ("frame-rehash", frames),
            ("frame-rewind", frames),
            ("refs-structure", 1),
            ("refs-targets", 1),
            ("refs-resolved", 1),
            ("refs-manifest", 1),
            ("root", sweeps),
            ("chain", sweeps * (1 + staging + 2 + bootstrap_directories)),
            ("objects-source", sweeps * objects_files),
            ("objects-chain", sweeps * (5 + objects_files)),
        ];
        for (label, times) in &expected {
            assert_eq!(count(label), *times, "populated={populated}: {label}");
        }
        assert!(
            count("metadata-chain") > 0,
            "populated={populated}: the metadata chains are paced"
        );
        assert_eq!(
            labels.len(),
            expected.iter().map(|(_, times)| times).sum::<usize>() + count("metadata-chain"),
            "populated={populated}: no other label"
        );
        let mut distinct: Vec<&str> = labels.clone();
        distinct.sort_unstable();
        distinct.dedup();
        let documented: Vec<&str> = B2B_GUARDS_V1
            .into_iter()
            .filter(|label| populated || *label != "objects-source")
            .collect();
        assert_eq!(distinct, documented, "populated={populated}");
    }
}

/// Each distinct guard halts the run alone: its step made slow past the deadline is refused with a typed
/// timeout, the run stops AT that guard (no later guard ever ran), every byte created so far is kept and
/// reported, and a brief delay at every guard, with headroom, still succeeds.
#[test]
fn b2b_each_guard_halts_the_run_alone_and_headroom_succeeds() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for target in B2B_GUARDS_V1 {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let deadline = Instant::now() + B2B_DEADLINE_V1;
        let labels = std::rc::Rc::new(std::cell::RefCell::new(Vec::<&'static str>::new()));
        let fired = std::rc::Rc::new(std::cell::Cell::new(false));
        let (seen, slow) = (labels.clone(), fired.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            seen.borrow_mut().push(event.label);
            if event.label == target && !slow.replace(true) {
                pass_the_deadline(deadline);
            }
        });
        let failure = timed_out_metadata(target, case.attempt_by(deadline));
        assert!(fired.get(), "{target}: the slow step never ran");
        assert_eq!(
            labels.borrow().last().copied(),
            Some(target),
            "{target}: the run halted AT its guard"
        );
        assert_metadata_partial_is_the_disk(target, &case, &failure, 0);
    }

    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    // Some two thousand guards, each delayed a millisecond, still leave most of a generous deadline.
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, |_| {
        std::thread::sleep(Duration::from_millis(1));
    });
    case.attempt_by(Instant::now() + 20 * B2B_DEADLINE_V1)
        .unwrap_or_else(|failure| panic!("brief delays leave headroom: {:?}", failure.cause));
}

/// No success past the deadline: when the clock passes at any guard of the FINAL gate (its entry, the guard
/// right after its mount census, and the last guard right before the root's identity), the run still
/// refuses, with every entry made and reported. The identity check is therefore the last fallible call.
#[test]
fn b2b_a_deadline_spent_in_the_final_gate_cannot_succeed() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (row, label) in [
        ("the final gate's entry", "metadata-final"),
        ("the guard after the final census", "objects-chain"),
        ("the last guard before the root's identity", "root"),
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let deadline = Instant::now() + B2B_DEADLINE_V1;
        let in_final = std::rc::Rc::new(std::cell::Cell::new(false));
        let fired = std::rc::Rc::new(std::cell::Cell::new(false));
        let started = in_final.clone();
        let _gate = install_git_hook_for_test(GitHookPointV1::BeforeMetadataFinalGate, move |_| {
            started.set(true);
        });
        let (inside, once) = (in_final.clone(), fired.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            if inside.get() && event.label == label && !once.replace(true) {
                pass_the_deadline(deadline);
            }
        });
        let failure = timed_out_metadata(row, case.attempt_by(deadline));
        assert!(fired.get(), "{row}: the final gate never read that guard");
        assert_eq!(
            failure.partial.charged.entries, 13,
            "{row}: every entry was already made"
        );
        assert_eq!(failure.partial.files.len(), 7, "{row}");
        assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Refs), "{row}");
    }
}

/// The deadline observed after the recheck, the decode, the read, the agreement, and the config step's start
/// is never followed by an effect.
const B2B_SPENT_DEADLINE_V1: Duration = Duration::from_millis(1200);

/// No effect follows a guard that finds the deadline spent. Each guard that stands between a blocking step
/// and the next effect (after every non-final recheck and gate, each frame's start, each decoded entry, each
/// content read, each frame's decode, the agreement, and the config step's start) is made slow past the
/// deadline at every occurrence in a clean run: the run refuses with a timeout and no create, chunk, read,
/// write, or final-gate event follows it, and the facts say exactly what had been done.
#[test]
fn b2b_no_effect_follows_a_guard_that_finds_the_deadline_spent() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let targets = [
        "metadata-checked",
        "metadata-frame",
        "metadata-item",
        "metadata-read",
        "metadata-decoded",
        "metadata-agreed",
        "metadata-config",
    ];
    let mut learn = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let (labels, hook) = record_guards();
    let _ = learn.done("a clean run");
    let rows: Vec<(&str, usize)> = targets
        .into_iter()
        .map(|wanted| {
            (
                wanted,
                labels
                    .borrow()
                    .iter()
                    .filter(|label| **label == wanted)
                    .count(),
            )
        })
        .collect();
    drop(hook);
    // One refs frame of HEAD, three directories, and the config: eighteen rechecks, two reads.
    assert_eq!(
        rows,
        [
            ("metadata-checked", 18),
            ("metadata-frame", 1),
            ("metadata-item", 4),
            ("metadata-read", 2),
            ("metadata-decoded", 1),
            ("metadata-agreed", 1),
            ("metadata-config", 1),
        ]
    );
    for (target, total) in rows {
        for nth in 1..=total {
            let row = format!("{target} #{nth}");
            let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            let deadline = Instant::now() + B2B_SPENT_DEADLINE_V1;
            let spent = std::rc::Rc::new(std::cell::Cell::new(false));
            let seen = std::rc::Rc::new(std::cell::Cell::new(0_usize));
            let effects = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
            let (flag, counter) = (spent.clone(), seen.clone());
            let _clock =
                install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
                    if event.label == target {
                        counter.set(counter.get() + 1);
                        if counter.get() == nth {
                            flag.set(true);
                            pass_the_deadline(deadline);
                        }
                    }
                });
            let mut effect_hooks = Vec::new();
            for point in [
                GitHookPointV1::BeforeObjectCreate,
                GitHookPointV1::BeforeObjectChunk,
                GitHookPointV1::ObjectIo,
                GitHookPointV1::BeforeMetadataFinalGate,
            ] {
                let (flag, log) = (spent.clone(), effects.clone());
                effect_hooks.push(install_git_hook_for_test(point, move |event| {
                    if flag.get() {
                        log.borrow_mut()
                            .push(format!("{point:?} {} {:?}", event.label, event.path));
                    }
                }));
            }
            let failure = timed_out_metadata(&row, case.attempt_by(deadline));
            drop(effect_hooks);
            assert!(spent.get(), "{row}: the guard never ran");
            assert!(
                effects.borrow().is_empty(),
                "{row}: effects after the spent guard: {:?}",
                effects.borrow()
            );
            match target {
                // The chunk that was read is neither charged nor written: the file exists, empty.
                "metadata-read" => {
                    let flight = failure.partial.in_flight.as_ref().expect("in flight");
                    assert_eq!(flight.written, 0, "{row}");
                    assert_eq!(
                        failure.partial.charged.bytes,
                        if nth == 1 {
                            0
                        } else {
                            HEAD_BYTES_V1.len() as u64
                        },
                        "{row}"
                    );
                }
                // A judged entry that was never created is neither charged nor on disk.
                "metadata-item" => {
                    assert_eq!(failure.partial.charged.entries, nth as u64 - 1, "{row}");
                }
                "metadata-agreed" => {
                    assert_eq!(
                        failure.last_completed,
                        Some(GitPlaneStepV1::Metadata),
                        "{row}"
                    );
                    assert!(!exists(&case.meta("config")), "{row}");
                }
                "metadata-config" => {
                    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Refs), "{row}");
                    assert!(!exists(&case.meta("config")), "{row}");
                }
                _ => {}
            }
            assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
        }
    }
}

// ---------------------------------------------------------------------------------------------
// The step's own writes observe the one deadline
//
// A blocking call cannot be preempted, so the deadline can pass INSIDE a read or a write. Whatever such a
// call returns (a prefix, an interruption, the last byte), no further call follows it: every continuation of
// a short write reads the same absolute clock first, and a write that stops there keeps exactly the bytes the
// file accepted charged, giving back the rest of the chunk it had reserved. The returned call is made slow
// through the `ObjectIo` hook, and the two results a regular file does not produce on demand, an interruption
// and a short write, are injected by the test-only seams.
// ---------------------------------------------------------------------------------------------

/// Short writes (five bytes at most), an interruption of two writes, and 16-byte chunks: the run a signal-prone
/// or network filesystem gives. The first writes of the first file are interrupted.
fn retry_script_b2b() -> Vec<GitSeamGuardV1> {
    vec![
        override_object_copy_chunk_for_test(16),
        short_writes_of_five(),
        interrupt_object_calls_for_test(ObjectCallV1::Write, 2),
    ]
}

/// A write that accepts only a prefix of a chunk and then returns AFTER the deadline is followed by no second
/// write: the file keeps exactly the accepted prefix, the ledger and the facts keep exactly those bytes
/// charged (the rest of the 16-byte chunk, reserved and never written, is given back), and nothing after the
/// file is created. The write that completes the chunk leaves nothing to give back, and no later chunk is read.
#[test]
fn b2b_a_slow_short_write_keeps_exactly_the_accepted_prefix_and_makes_no_second_write() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    for (row, slow_write, accepted) in [
        ("the first write took five of sixteen", 1_usize, 5_u64),
        ("the second write took five more", 2, 10),
        ("the third write took five more", 3, 15),
        ("the fourth write completed the chunk", 4, 16),
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (first, _, before) = first_file_of(&case);
        let output = case.meta(&first);
        let original = case.expected_frames()[&first].clone().expect("a file");
        let _fault = short_writes_of_five();
        let deadline = Instant::now() + B2A_SLOW_CALL_DEADLINE_V1;
        let clock = CallClockV1::watch(
            deadline,
            Some(("write", slow_write, &output)),
            Duration::ZERO,
        );
        let failure = timed_out_metadata(row, case.attempt_by(deadline));
        assert!(clock.fired(), "{row}: the slow write never ran");
        assert_eq!(
            clock.after_the_slow_call(),
            Vec::<String>::new(),
            "{row}: a call followed the write that returned after the deadline"
        );
        assert_eq!(clock.count("write"), slow_write, "{row}: no second write");
        assert_eq!(clock.count("read"), 1, "{row}: no later chunk was read");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the first file in flight");
        assert_eq!(flight.written, accepted, "{row}: the retained fact");
        let on_disk = std::fs::read(&output).expect("the partial file");
        assert_eq!(on_disk.len() as u64, accepted, "{row}: the file on disk");
        assert_eq!(&original[..on_disk.len()], &on_disk[..], "{row}: a prefix");
        assert_eq!(
            failure.partial.charged,
            MetadataChargeV1 {
                entries: before + 1,
                bytes: accepted
            },
            "{row}: exactly the accepted bytes stay charged"
        );
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }
}

/// An interrupted write returns without having done anything, and it is retried only while the deadline is
/// still ahead: an interruption that returns after it is followed by no further call on that descriptor. A
/// write interrupted that way gives back all of its chunk's reservation; one that follows an accepted prefix
/// keeps exactly that prefix.
#[test]
fn b2b_an_interrupted_write_is_never_retried_after_the_deadline() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    // (row, interruptions, short writes, the slow write's number, writes that ran, bytes the file accepted)
    for (row, interruptions, short, slow_write, writes, accepted) in [
        (
            "the first write was interrupted and slow",
            3_u32,
            false,
            1_usize,
            1_usize,
            0_u64,
        ),
        (
            "the third write was interrupted and slow, after two prompt retries",
            3,
            false,
            3,
            3,
            0,
        ),
        (
            "an interrupted write, then five of sixteen accepted slowly",
            1,
            true,
            2,
            2,
            5,
        ),
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (first, _, before) = first_file_of(&case);
        let output = case.meta(&first);
        let _interrupts = interrupt_object_calls_for_test(ObjectCallV1::Write, interruptions);
        let _short = short.then(short_writes_of_five);
        let deadline = Instant::now() + B2A_SLOW_CALL_DEADLINE_V1;
        let clock = CallClockV1::watch(
            deadline,
            Some(("write", slow_write, &output)),
            Duration::ZERO,
        );
        let failure = timed_out_metadata(row, case.attempt_by(deadline));
        assert!(clock.fired(), "{row}: the slow call never ran");
        assert_eq!(
            clock.after_the_slow_call(),
            Vec::<String>::new(),
            "{row}: a call followed the interruption that returned after the deadline"
        );
        assert_eq!(clock.count("write"), writes, "{row}: writes");
        assert_eq!(clock.count("read"), 1, "{row}: reads");
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the first file in flight");
        assert_eq!(flight.written, accepted, "{row}: the retained fact");
        assert_eq!(
            failure.partial.charged,
            MetadataChargeV1 {
                entries: before + 1,
                bytes: accepted
            },
            "{row}: nothing reserved and never written stays charged"
        );
        assert_eq!(
            std::fs::metadata(&output).expect("the file").len(),
            accepted,
            "{row}"
        );
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }
}

/// No chunk is read after the deadline: with chunks of 16 bytes, a deadline that passes before the second
/// chunk of the first file stops the copy there. Exactly one chunk was read, charged, and written, and
/// nothing after it.
#[test]
fn b2b_no_chunk_is_read_after_the_deadline() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let (first, length, before) = first_file_of(&case);
    assert!(length > 16 && length <= 32);
    let output = case.meta(&first);
    let deadline = Instant::now() + B2B_DEADLINE_V1;
    let chunks = std::rc::Rc::new(std::cell::Cell::new(0_usize));
    let seen = chunks.clone();
    let target = output.clone();
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeObjectChunk, move |event| {
        if event.path == target {
            seen.set(seen.get() + 1);
            if seen.get() == 2 {
                pass_the_deadline(deadline);
            }
        }
    });
    let clock = CallClockV1::watch(deadline, None, Duration::ZERO);
    let failure = timed_out_metadata(
        "a deadline before the second chunk",
        case.attempt_by(deadline),
    );
    assert_eq!(chunks.get(), 2, "no third chunk was started");
    assert_eq!(clock.count("read"), 1, "the second chunk was never read");
    let flight = failure
        .partial
        .in_flight
        .as_ref()
        .expect("the file in flight");
    assert_eq!(flight.written, 16);
    assert_eq!(
        failure.partial.charged,
        MetadataChargeV1 {
            entries: before + 1,
            bytes: 16
        }
    );
    assert_eq!(std::fs::read(&output).expect("the partial file").len(), 16);
    assert_metadata_partial_is_the_disk("a deadline before the second chunk", &case, &failure, 0);
}

/// Every call of the first file in a run full of interruptions and short writes, made slow in turn, is the
/// last call: whichever returns after the deadline, the run refuses with a timeout, no call follows it, and
/// the charge is exactly the bytes on disk.
#[test]
fn b2b_no_read_or_write_follows_a_call_that_returned_after_the_deadline() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let mut learn = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
    let (first, _, _) = first_file_of(&learn);
    let output = learn.meta(&first);
    let calls = {
        let _script = retry_script_b2b();
        let clock = CallClockV1::watch(far_deadline(), None, Duration::ZERO);
        let _ = learn.done("a clean scripted run");
        clock.labels_on(&output)
    };
    let total = calls.len();
    assert!(
        total >= 8,
        "the first file spans several chunks and writes: {calls:?}"
    );
    for nth in 1..=total {
        let row = format!("call {nth} of {total}: {}", calls[nth - 1]);
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        // This run's own file: every case has a destination of its own.
        let target = case.meta(&first);
        let _script = retry_script_b2b();
        let deadline = Instant::now() + B2A_SLOW_CALL_DEADLINE_V1;
        let counted = std::rc::Rc::new(std::cell::Cell::new(0_usize));
        let after = std::rc::Rc::new(std::cell::RefCell::new(Vec::<String>::new()));
        let slowed = std::rc::Rc::new(std::cell::Cell::new(false));
        let (seen, log, flag) = (counted.clone(), after.clone(), slowed.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::ObjectIo, move |event| {
            if flag.get() {
                log.borrow_mut()
                    .push(format!("{} {:?}", event.label, event.path));
                return;
            }
            if event.path == target {
                seen.set(seen.get() + 1);
                if seen.get() == nth {
                    flag.set(true);
                    pass_the_deadline(deadline);
                }
            }
        });
        let failure = timed_out_metadata(&row, case.attempt_by(deadline));
        assert!(slowed.get(), "{row}: the slow call never ran");
        assert_eq!(
            *after.borrow(),
            Vec::<String>::new(),
            "{row}: a call followed it"
        );
        assert_eq!(counted.get(), nth, "{row}");
        assert!(
            failure.partial.files.is_empty(),
            "{row}: the first file is in flight"
        );
        assert_metadata_partial_is_the_disk(&row, &case, &failure, 0);
    }
}

/// With headroom, the same run of interruptions and short writes completes: every interrupted write is
/// retried, every short write is continued to the whole chunk, the files are the frame's exact bytes and the
/// golden config, and the charge is exactly what is on disk, with the brief delays of a slow filesystem at
/// every call.
#[test]
fn b2b_interrupted_and_short_writes_with_headroom_restore_exactly_and_conserve_the_ledger() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (row, pause) in [
        ("no delay", Duration::ZERO),
        ("a millisecond at every call", Duration::from_millis(1)),
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let mut expected = case.expected_frames();
        expected.insert(
            "config".to_owned(),
            Some(golden_config(case.format).to_vec()),
        );
        let _script = retry_script_b2b();
        let deadline = Instant::now() + 10 * B2B_DEADLINE_V1;
        let clock = CallClockV1::watch(deadline, None, pause);
        let done = case
            .attempt_by(deadline)
            .unwrap_or_else(|failure| panic!("{row}: headroom must succeed: {:?}", failure.cause));
        assert_eq!(case.metadata_on_disk(), expected, "{row}: the exact bytes");
        let lengths: Vec<u64> = expected
            .values()
            .filter_map(|content| content.as_ref().map(|bytes| bytes.len() as u64))
            .collect();
        assert_eq!(
            done.charged,
            MetadataChargeV1 {
                entries: 13,
                bytes: lengths.iter().sum()
            },
            "{row}"
        );
        // 16-byte chunks, five-byte writes, and the two interrupted writes of the first file.
        let reads: u64 = lengths.iter().map(|length| length.div_ceil(16)).sum();
        let writes: u64 = lengths
            .iter()
            .map(|length| {
                (0..length.div_ceil(16))
                    .map(|chunk| (length - chunk * 16).min(16).div_ceil(5))
                    .sum::<u64>()
            })
            .sum();
        assert_eq!(clock.count("read") as u64, reads, "{row}: reads");
        assert_eq!(clock.count("write") as u64, writes + 2, "{row}: writes");
        assert_eq!(clock.count("probe"), 0, "{row}: the step probes nothing");
    }
}

/// A write that FAILS after interruptions or short writes still conserves the ledger exactly: the bytes the
/// file accepted stay charged and reported (a failure and a zero-length write are the same refusal as before,
/// never a loop, and never a timeout while the deadline is ahead), and the rest of the chunk is given back.
/// The interruptions before it are retried.
#[test]
fn b2b_a_write_failure_after_retries_conserves_the_ledger() {
    let _chunk = override_object_copy_chunk_for_test(16);
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    // (row, interrupted writes, the failure, the bytes the file accepted, writes that ran)
    for (row, interruptions, fault, accepted, writes) in [
        (
            "two interrupted writes, then five bytes, then an I/O error",
            2_u32,
            ObjectFaultV1::WriteAfter(5),
            5_u64,
            4_usize,
        ),
        (
            "an interrupted write, then seven bytes, then a zero-length write",
            1,
            ObjectFaultV1::WriteZeroAfter(7),
            7,
            3,
        ),
    ] {
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (first, _, before) = first_file_of(&case);
        let _interrupts = interrupt_object_calls_for_test(ObjectCallV1::Write, interruptions);
        let _fault = override_object_fault_for_test(fault);
        let clock = CallClockV1::watch(far_deadline(), None, Duration::ZERO);
        let failure = case.refused(row);
        match &failure.cause {
            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Io(detail)) => {
                assert!(detail.contains(&first), "{row}: {detail}");
            }
            other => panic!("{row}: {other:?}"),
        }
        assert_eq!(
            (clock.count("read"), clock.count("write")),
            (1, writes),
            "{row}: the interrupted writes were retried, and nothing else ran"
        );
        let flight = failure
            .partial
            .in_flight
            .as_ref()
            .expect("the first file in flight");
        assert_eq!(flight.written, accepted, "{row}: the retained fact");
        assert_eq!(
            failure.partial.charged,
            MetadataChargeV1 {
                entries: before + 1,
                bytes: accepted
            },
            "{row}: exactly the bytes that reached the file stay charged"
        );
        assert_metadata_partial_is_the_disk(row, &case, &failure, 0);
    }
}

/// The recheck between two entries is bounded to the new entry's own chain, so the work of a restore grows with
/// its entries and not with their square: eighty sibling directories cost a few chain checks each, where a
/// full recheck per entry would cost on the order of the entries made so far (thousands more).
#[test]
fn b2b_the_recheck_between_entries_does_not_grow_with_the_entries_made() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let mut refs = base_refs();
    for number in 0..80 {
        refs = refs.dir(&format!("refs/tags/t{number:02}"));
    }
    let mut case = MetaCaseV1::with_frames(
        &capsule,
        CustodyGitObjectFormatV1::Sha1,
        &refs,
        None,
        vec![symbolic_ref("HEAD", "refs/heads/main")],
    );
    let (labels, _hook) = record_guards();
    let done = case.done("eighty directories");
    assert_eq!(done.directories.len(), 83);
    let chains = labels
        .borrow()
        .iter()
        .filter(|label| **label == "metadata-chain")
        .count();
    // The exact count: each directory costs its parent's chain before its create and its own after, each
    // file three times its parent's chain (the config sits in `.git`, which is no metadata directory), and a
    // full recheck costs one step per directory and file made so far: none at the entry and at the first
    // frame's start, then the frame's 84 entries at the gate after it, before the refs are read, and at the
    // config gate, and those and the config at the final gate. A per-entry recheck of everything made would
    // cost thousands more, and one that skipped the chain fewer.
    let depth = |path: &str| path.matches('/').count() + 1;
    let parent_depth = |path: &str| path.rsplit_once('/').map_or(0, |(parent, _)| depth(parent));
    let mut expected = 0;
    for relative in done.directories.keys() {
        expected += parent_depth(relative) + depth(relative);
    }
    let frame_files: Vec<&str> = done
        .files
        .iter()
        .map(|file| file.relative.as_str())
        .filter(|relative| *relative != "config")
        .collect();
    for relative in &frame_files {
        expected += 3 * parent_depth(relative);
    }
    let made = done.directories.len() + frame_files.len();
    expected += 4 * made + 1;
    assert_eq!(chains, expected, "metadata chain checks for {made} entries");
    assert!(chains < 1500, "{chains}: linear in the entries made");
}

// ---------------------------------------------------------------------------------------------
// The step's inputs, and its typed progress
// ---------------------------------------------------------------------------------------------

/// The step builds on exactly one restore's earlier passes: a plan that is not this capsule's, a bootstrap
/// that is not a proven object store, and an object copy that is not the copy of this bootstrap's admitted
/// files (not completed, a file missing, another digest, another name) each refuse before the first entry,
/// carrying the caller's step and beginning nothing.
#[test]
fn b2b_the_inputs_must_be_one_restores_and_refuse_before_any_write() {
    type TamperV1 = fn(&mut MetaCaseV1);
    type ExpectedV1 = fn(&GitBootstrapErrorV1) -> bool;
    let rows: Vec<(&str, TamperV1, ExpectedV1)> = vec![
        (
            "a plan that is not this capsule's",
            |case| case.store.plan.frames.reverse(),
            |cause| matches!(cause, GitBootstrapErrorV1::ActivePlanMismatch(_)),
        ),
        (
            "a bootstrap whose strict fsck was not proven",
            |case| case.store.boot.closure.fsck_strict = false,
            |cause| matches!(cause, GitBootstrapErrorV1::ObjectStoreInput(_)),
        ),
        (
            "an object copy that has not completed its step",
            |case| case.objects.step = GitPlaneStepV1::Admission,
            |cause| matches!(cause, GitBootstrapErrorV1::MetadataInput(_)),
        ),
        (
            "an object copy with a file missing",
            |case| {
                case.objects.files.pop();
            },
            |cause| matches!(cause, GitBootstrapErrorV1::MetadataInput(_)),
        ),
        (
            "an object copy file with another digest",
            |case| case.objects.files[0].sha256[0] ^= 1,
            |cause| matches!(cause, GitBootstrapErrorV1::MetadataInput(_)),
        ),
        (
            "an object copy file with another length",
            |case| case.objects.files[1].length += 1,
            |cause| matches!(cause, GitBootstrapErrorV1::MetadataInput(_)),
        ),
        (
            "an object copy file with another name",
            |case| case.objects.files[2].relative.push('x'),
            |cause| matches!(cause, GitBootstrapErrorV1::MetadataInput(_)),
        ),
    ];
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for (row, tamper, expected) in rows {
        for completed in [None, Some(GitPlaneStepV1::Admission), B2B_COMPLETED_V1] {
            let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
            tamper(&mut case);
            let tree = snapshot(&case.dest().path);
            let ledger = case.ledger();
            let failure = match case.attempt_with(
                far_deadline(),
                completed,
                B2B_TABLE_BOUND_V1,
                RefsLimitsV1::v1(),
            ) {
                Ok(_) => panic!("{row}: must refuse"),
                Err(failure) => failure,
            };
            assert!(expected(&failure.cause), "{row}: {:?}", failure.cause);
            assert_eq!(
                failure.last_completed, completed,
                "{row}: the caller's step is carried"
            );
            assert!(!failure.active_materialization_began, "{row}");
            assert_eq!(failure.partial.charged, none_charged(), "{row}");
            assert_eq!(case.ledger(), ledger, "{row}: the ledger");
            assert_eq!(
                snapshot(&case.dest().path),
                tree,
                "{row}: a byte was written"
            );
        }
    }
}

/// Complete G needs a captured HEAD: a bootstrap whose capsule has an Empty `RefsAndHead` class is the typed
/// pre-write refusal, for both caller formats, before the object copy is even compared: no HEAD is
/// synthesized, nothing is created, and the caller's step is carried.
#[test]
fn b2b_empty_refs_refuse_before_any_write_and_no_head_is_synthesized() {
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let sibling = MetaCaseV1::of(&empty(cformat), cformat);
        let capsule = empty(cformat);
        let CaseV1 { dest, verified } = CaseV1::with_bytes(&capsule, &[]);
        let boot = must_bootstrap(verified, core_format(cformat));
        let tree = snapshot(&dest.path);
        let ledger = ledger_used(&boot.verified);
        let failure = materialize_active_metadata_v1(
            &boot,
            &sibling.objects,
            &ActiveFramePlanV1 { frames: vec![] },
            frame_budget(),
            far_deadline(),
            B2B_COMPLETED_V1,
        )
        .expect_err("an Empty RefsAndHead");
        assert!(
            matches!(failure.cause, GitBootstrapErrorV1::EmptyRefsAndHead),
            "{cformat:?}: {:?}",
            failure.cause
        );
        assert_eq!(failure.last_completed, B2B_COMPLETED_V1);
        assert!(!failure.active_materialization_began);
        assert_eq!(failure.partial.charged, none_charged());
        assert_eq!(failure.ledger_used, ledger);
        assert_eq!(snapshot(&dest.path), tree);
        assert_eq!(
            dest.entries(),
            [".restore-work"],
            "{cformat:?}: no repository exists"
        );
    }
}

/// Typed progress: the last completed step is the caller's until the frames are all restored and the gate
/// after them passes (`Metadata`), then until the refs agree (`Refs`); the config step completes only in a
/// success (`Config`). The caller's own step is carried unchanged on every refusal before the metadata step
/// completes, whatever it is.
#[test]
fn b2b_the_last_completed_step_is_typed_at_each_step() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    for completed in [None, Some(GitPlaneStepV1::Admission), B2B_COMPLETED_V1] {
        // A refusal after writes began but before the metadata step completes: the caller's own.
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let name = format!(
            "repository/.git/{}",
            creation_order(&capsule, CustodyGitObjectFormatV1::Sha1)[3].0
        );
        let _device = override_created_dev_for_test(&name, device_of(&case.dest().path) + 1);
        let failure = match case.attempt_with(
            far_deadline(),
            completed,
            B2B_TABLE_BOUND_V1,
            RefsLimitsV1::v1(),
        ) {
            Ok(_) => panic!("a device refusal"),
            Err(failure) => failure,
        };
        assert_eq!(failure.last_completed, completed);
        assert!(failure.active_materialization_began);
        drop(_device);

        // The metadata step is whole and the agreement refuses: `Metadata`, whatever the caller's step was.
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let specs = real_specs(&capsule, case.format);
        let mut refs = specs.manifest_refs.clone();
        refs.push(symbolic_ref("refs/heads/link", "refs/heads/main"));
        set_refs(&mut case.store.boot.verified, refs);
        let failure = match case.attempt_with(
            far_deadline(),
            completed,
            B2B_TABLE_BOUND_V1,
            RefsLimitsV1::v1(),
        ) {
            Ok(_) => panic!("an agreement refusal"),
            Err(failure) => failure,
        };
        assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Metadata));

        // The refs agree and the config collides: `Refs`.
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let config = case.meta("config");
        let planted = std::rc::Rc::new(std::cell::Cell::new(false));
        let (flag, at) = (planted.clone(), config.clone());
        let _hook = install_git_hook_for_test(GitHookPointV1::BeforeObjectCreate, move |event| {
            if event.path == at && !flag.replace(true) {
                std::fs::write(&at, b"planted").expect("a planted config");
            }
        });
        let failure = match case.attempt_with(
            far_deadline(),
            completed,
            B2B_TABLE_BOUND_V1,
            RefsLimitsV1::v1(),
        ) {
            Ok(_) => panic!("a config collision"),
            Err(failure) => failure,
        };
        assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Refs));
        assert_eq!(
            std::fs::read(&config).expect("the planted config"),
            b"planted"
        );
        drop(_hook);

        // A success: the config step.
        let mut case = MetaCaseV1::of(&capsule, CustodyGitObjectFormatV1::Sha1);
        let done = case
            .attempt_with(
                far_deadline(),
                completed,
                B2B_TABLE_BOUND_V1,
                RefsLimitsV1::v1(),
            )
            .unwrap_or_else(|failure| panic!("a clean run: {:?}", failure.cause));
        assert_eq!(done.step, GitPlaneStepV1::Config);
    }
}

// ---------------------------------------------------------------------------------------------
// Structure: B2b's region creates and charges, and only that
// ---------------------------------------------------------------------------------------------

/// STRUCTURAL ONLY. B2b's region (the production source from its marker on, up to B2c's marker) is held
/// to its own vocabulary, because B2a's create-new scan now ends at this marker: it opens no path, walks
/// nothing, runs no Git child or process, routes no object store, renames, removes, truncates, links, or
/// re-permissions nothing, has no unsafe, names the `config` leaf exactly once, and names no hook, alternate,
/// info, shallow, index, module, or worktree entry, nor any ref or HEAD path. Everything it creates is
/// create-new beneath a retained pin. The marker is unique, follows B2a's region, and the region holds the
/// entry point. The behavior is proven by the rows above, which run the code.
#[test]
fn b2b_the_metadata_region_is_create_new_only_and_the_split_is_unique() {
    let source = include_str!("custody_restore_git.rs");
    assert_eq!(source.matches(B2B_MARKER_V1).count(), 1, "one marker");
    assert_eq!(source.matches(B2A_MARKER_V1).count(), 1, "one B2a marker");
    let (before, region) = source.split_once(B2B_MARKER_V1).expect("the marker");
    // B2c's region, which runs Git children and gates the whole, is outside this metadata scan; its own scan
    // covers it.
    let (region, _later) = region
        .split_once(B2C_MARKER_V1)
        .expect("the B2c marker follows B2b's region");
    assert!(before.contains(B2A_MARKER_V1), "B2b follows B2a");
    assert!(before.contains("pub(crate) fn materialize_object_store_v1("));
    assert!(region.contains("pub(crate) fn materialize_active_metadata_v1("));
    assert!(
        !before.contains("materialize_active_metadata_v1("),
        "the earlier passes do not call B2b"
    );
    let code: String = region
        .lines()
        .filter(|line| !line.trim_start().starts_with("//"))
        .collect::<Vec<_>>()
        .join("\n");
    for forbidden in [
        "std::fs",
        "File::open(",
        "OpenOptions",
        "read_dir(",
        "GitRunnerV1",
        "GitRunRequestV1",
        "GitCommandV1",
        "GitObjectStoreRouteV1",
        "remeasure_git_directory",
        "measure_git_directory",
        "walk",
        "Command",
        "spawn",
        "std::process",
        "mkdir",
        "rename",
        "remove_file",
        "remove_dir",
        "unlink",
        "set_len",
        "truncate",
        "hard_link",
        "symlink(",
        "set_permissions",
        "unsafe",
        "WorkV1",
        "OwnedChargeV1",
        "settle_to",
        "\"HEAD\"",
        "\"refs\"",
        "\"logs\"",
        "\"hooks\"",
        "\"alternates\"",
        "\"info\"",
        "\"shallow\"",
        "\"index\"",
        "\"modules\"",
        "\"worktrees\"",
        "ORIG_HEAD",
        "FETCH_HEAD",
        "packed-refs",
    ] {
        assert!(
            !code.contains(forbidden),
            "the metadata region mentions `{forbidden}`"
        );
    }
    assert_eq!(
        code.matches("\"config\"").count(),
        1,
        "the config leaf is named exactly once"
    );
    // What it does use: create-new beneath retained pins, the one deadline, the one ledger, the retained
    // descriptors, the pass B1a rules again, and the pass B1b parsers.
    for required in [
        "create_staging_directory(",
        "create_output_file(",
        "observe_deadline(",
        "before_deadline(",
        "stream_digest(",
        "write_step(",
        "give_back_unwritten(",
        "reserve_entries(",
        ".reserve(",
        "sweep_chains(",
        "output_chains(",
        "source_files_unchanged(",
        "refuse_mounts_within(",
        "reverify_staged_v1(",
        "ActivePathTableV1::new(",
        ".admit(",
        "CustodyFrameDecoderV1::new(",
        "RefsBuilderV1::new(",
        ".admit_file(",
        ".finish(",
        "encode_inert_config_v1(",
        "try_clone(",
    ] {
        assert!(
            code.contains(required),
            "the metadata region lacks `{required}`"
        );
    }
    // No retry or continuation loop on a descriptor beyond the guarded write loop and the guarded drain loop
    // (each reads the one clock before every call, a retry included).
    assert_eq!(
        code.matches("Interrupted").count(),
        2,
        "the interrupted-write arm and the drain loop's guarded retry"
    );
}

// ---------------------------------------------------------------------------------------------
// Pass B2c: the final closure, the typed result, and the wrapper
//
// Every row drives `restore_git_plane_v1` over a REAL retained value: a real phase-V capsule (real Git
// objects and a real pack with real active frames, or an Empty object database with a captured unborn
// HEAD), carried by the wrapper itself through pass A's real bootstrap, B1a's and B1b's real prevalidation,
// B2a's real second object store, B2b's real metadata, and the final proof, with REAL Git children (a
// fixture route records them and, for one child, tampers with it). The one ledger's conservation and the
// typed failure shape are held on every outcome.
//
// Pass A's, B1a's, B1b's, B2a's, and B2b's controls above are unchanged, except the B2b structural scan's
// region end (see `B2C_MARKER_V1`). The mutation matrix in `.git/a2a-evidence/2b3b-pass-b2c/` maps each
// guard to the rows that turn red without it.
// ---------------------------------------------------------------------------------------------

const B2C_MARKER_V1: &str = "// Pass B2c: final closure, typed result and wrapper";

/// The one absolute deadline of the rows that spend it: a clean run takes about a second, so everything
/// before an injected guard finishes far inside it; under extreme load a row fails with a different, visible
/// cause, never passes wrongly.
const B2C_DEADLINE_V1: Duration = Duration::from_secs(8);

type PlaneOutcomeV1 = Result<RestoredGitPlaneV1, Box<GitPlaneRestoreFailureV1>>;

/// The subtrees the wrapper's own writes hold beneath the destination: HOME, XDG, and the bootstrap (pass A),
/// and the final repository (B2a and B2b).
const BOOTSTRAP_SUBTREES_V1: [&str; 3] = [
    ".restore-work/home",
    ".restore-work/xdg",
    ".restore-work/git-bootstrap",
];
const PLANE_SUBTREES_V1: [&str; 4] = [
    ".restore-work/home",
    ".restore-work/xdg",
    ".restore-work/git-bootstrap",
    "repository",
];

/// The subcommand tokens the recording route logs for a clean run: pass A's six children (Captured), then
/// the final database's three.
const CAPTURED_CHILDREN_V1: [&str; 9] = [
    "init",
    "index-pack",
    "verify-pack",
    "cat-file",
    "rev-list",
    "fsck",
    "cat-file",
    "rev-list",
    "fsck",
];
/// An Empty database: init, an empty inventory, and fsck, twice. No index-pack, verify-pack, or rev-list.
const EMPTY_CHILDREN_V1: [&str; 5] = ["init", "cat-file", "fsck", "cat-file", "fsck"];
const FINAL_LABELS_CAPTURED_V1: [&str; 3] = [
    "cat-file --batch-all-objects",
    "rev-list --missing=print",
    "fsck --strict",
];
const FINAL_LABELS_EMPTY_V1: [&str; 2] = ["cat-file --batch-all-objects", "fsck --strict"];

/// A real phase-V value, ready for the wrapper.
struct PlaneInV1 {
    dest: DestV1,
    verified: VerifiedCapsuleV1,
    /// The caller's object format.
    format: GitObjectFormatV1,
    /// The one ledger's charge when phase V returned.
    phase_v: u64,
}

impl PlaneInV1 {
    fn of(case: CaseV1, caller: CustodyGitObjectFormatV1) -> Self {
        let phase_v = ledger_used(&case.verified);
        Self {
            dest: case.dest,
            verified: case.verified,
            format: core_format(caller),
            phase_v,
        }
    }

    /// A Captured capsule with real frames: an attached HEAD, ORIG_HEAD, packed refs, a loose ref, reflogs.
    fn rich(capsule: &CustomCapsuleV1, caller: CustodyGitObjectFormatV1) -> Self {
        Self::of(real_case(capsule, core_format(caller)), caller)
    }

    /// An Empty capsule with a captured, valid, UNBORN HEAD (no objects, no pack).
    fn unborn(capsule: &CustomCapsuleV1, caller: CustodyGitObjectFormatV1) -> Self {
        Self::of(
            CaseV1::refs_only(capsule, &[db("refs"), db("refs/heads"), db("refs/tags")]),
            caller,
        )
    }

    /// No active frame at all: an Empty `RefsAndHead` class, which pass A accepts.
    fn frameless(capsule: &CustomCapsuleV1, caller: CustodyGitObjectFormatV1) -> Self {
        Self::of(CaseV1::with_bytes(capsule, &[]), caller)
    }

    /// A reflog frame alone: still no HEAD.
    fn reflogs_only(capsule: &CustomCapsuleV1, caller: CustodyGitObjectFormatV1) -> Self {
        let generation = CaseV1::generation(capsule);
        let logs = encode_frame(LOGS_V1, &generation, &[db("logs")]);
        Self::of(CaseV1::with_bytes(capsule, &[(LOGS_V1, logs)]), caller)
    }

    fn with_frames(
        capsule: &CustomCapsuleV1,
        caller: CustodyGitObjectFormatV1,
        refs: &FrameSpecV1,
        logs: Option<&FrameSpecV1>,
        manifest_refs: Vec<CustodyOriginalRefV1>,
    ) -> Self {
        let generation = CaseV1::generation(capsule);
        let mut frames = vec![(REFS_V1, refs.encode(REFS_V1, &generation))];
        if let Some(logs) = logs {
            frames.push((LOGS_V1, logs.encode(LOGS_V1, &generation)));
        }
        let mut case = CaseV1::with_bytes(capsule, &frames);
        set_refs(&mut case.verified, manifest_refs);
        Self::of(case, caller)
    }
}

/// One run of the wrapper, with what the test needs to judge it.
struct PlaneRunV1 {
    dest: DestV1,
    phase_v: u64,
    format: GitObjectFormatV1,
    outcome: PlaneOutcomeV1,
}

impl PlaneRunV1 {
    fn success(&self, row: &str) -> &RestoredGitPlaneV1 {
        match &self.outcome {
            Ok(plane) => plane,
            Err(failure) => panic!(
                "{row}: must succeed: {:?} (completed {:?})",
                failure.cause, failure.last_completed
            ),
        }
    }

    fn failure(&self, row: &str) -> &GitPlaneRestoreFailureV1 {
        match &self.outcome {
            Ok(_) => panic!("{row}: must refuse"),
            Err(failure) => failure,
        }
    }

    /// The one ledger's charge now, read from the capsule the outcome retains (a failure that happened inside
    /// pass A has consumed the capsule, and reports only its figure).
    fn ledger_now(&self) -> Option<u64> {
        match &self.outcome {
            Ok(plane) => Some(ledger_used(plane.capsule())),
            Err(failure) => failure
                .partial
                .bootstrap
                .as_ref()
                .map(|boot| ledger_used(&boot.verified)),
        }
    }

    /// The invariants EVERY outcome keeps: the figure a failure reports is the one ledger's, and the ledger
    /// holds no more than what the wrapper's own writes hold on disk (no second ledger, no replenishment, and
    /// nothing reserved that was never written, for the rows that charge nothing pending).
    fn assert_one_ledger(&self, row: &str) {
        match &self.outcome {
            Ok(plane) => {
                assert_eq!(plane.ledger_used(), ledger_used(plane.capsule()), "{row}");
                assert_eq!(
                    plane.ledger_used(),
                    self.phase_v + charge_on_disk(&self.dest, &PLANE_SUBTREES_V1),
                    "{row}: the one ledger holds exactly what the wrapper wrote"
                );
            }
            Err(failure) => {
                if let Some(now) = self.ledger_now() {
                    assert_eq!(failure.ledger_used, now, "{row}: the failure's figure");
                }
            }
        }
    }
}

/// The entries and bytes the subtrees hold on disk, by the TEST's own measurement: every entry costs one
/// allowance, every regular file its length.
fn charge_on_disk(dest: &DestV1, subtrees: &[&str]) -> u64 {
    snapshot(&dest.path)
        .iter()
        .filter(|(name, _)| {
            subtrees
                .iter()
                .any(|root| name.as_str() == *root || name.starts_with(&format!("{root}/")))
        })
        .map(|(_, bytes)| ENTRY_V1 + bytes.as_ref().map_or(0, |bytes| bytes.len() as u64))
        .sum()
}

/// The real entry point under `deadline`, over a route that records (and may tamper with) the children.
fn run_plane(input: PlaneInV1, route: &RouteV1, deadline: Instant) -> PlaneRunV1 {
    let (_area, runner) = route.runner();
    let outcome = restore_git_plane_v1(
        input.verified,
        &runner,
        input.format,
        frame_budget(),
        deadline,
    );
    PlaneRunV1 {
        dest: input.dest,
        phase_v: input.phase_v,
        format: input.format,
        outcome,
    }
}

/// [`run_plane`] with the caller's frame budget, path-table bound, and refs limits.
fn run_plane_bounded(
    input: PlaneInV1,
    route: &RouteV1,
    budget: CustodyFrameBudgetV1,
    table_bound: u64,
    limits: RefsLimitsV1,
) -> PlaneRunV1 {
    let (_area, runner) = route.runner();
    let outcome = restore_git_plane_bounded_v1(
        input.verified,
        &runner,
        input.format,
        budget,
        far_deadline(),
        table_bound,
        limits,
    );
    PlaneRunV1 {
        dest: input.dest,
        phase_v: input.phase_v,
        format: input.format,
        outcome,
    }
}

/// A rule body that applies `shell` to a child of the FINAL database only (`GIT_DIR=.git`), and delegates
/// the bootstrap's identical child untouched (`GIT_DIR=git-bootstrap`).
fn final_only(shell: &str) -> String {
    format!("if [ \"$GIT_DIR\" = .git ]; then {shell}; else \"$REAL\" \"$@\"; fi")
}

/// The entries the final `.git` must hold, by the test's OWN decode of the retained frames, the golden
/// config of the caller's format, and the bootstrap's object files as the test reads them from disk.
fn expected_git_tree(
    plane: &RestoredGitPlaneV1,
    dest: &DestV1,
) -> BTreeMap<String, Option<Vec<u8>>> {
    let generation = plane.capsule().control.manifest.generation_id().to_owned();
    let mut tree = BTreeMap::new();
    for frame in &plane.bootstrap.active_frames {
        let one = &plane.capsule().staged[frame.staged];
        for (path, content) in decoded_entries(&one.file, frame.class, &generation) {
            tree.insert(path, content);
        }
    }
    tree.insert(
        "config".to_owned(),
        Some(golden_config(plane.object_format()).to_vec()),
    );
    for directory in ["objects", "objects/info", "objects/pack"] {
        tree.insert(directory.to_owned(), None);
    }
    for (name, bytes) in bootstrap_object_files(dest) {
        tree.insert(format!("objects/pack/{name}"), Some(bytes));
    }
    tree
}

/// What a clean wrapper run must leave, for every shape: the exact `.git` tree and nothing else beside it,
/// every retained pin the directory it names, every retained descriptor at offset 0 and reading exactly the
/// bytes on disk, every staged descriptor at offset 0, and one ledger that holds exactly what was written.
fn assert_clean_plane(ran: &PlaneRunV1, plane: &RestoredGitPlaneV1, row: &str) {
    use std::io::Seek as _;
    let git = stored(&ran.dest, "repository/.git");
    let want = expected_git_tree(plane, &ran.dest);
    assert_eq!(snapshot(&git), want, "{row}: the exact tree");
    assert_eq!(
        listing(&stored(&ran.dest, "repository")),
        [".git"],
        "{row}: the repository's only child is .git"
    );
    assert_eq!(ran.dest.entries(), [".restore-work", "repository"], "{row}");
    for forbidden in ["hooks", "info", "description", "shallow", "index"] {
        assert!(!exists(&git.join(forbidden)), "{row}: {forbidden}");
    }
    assert_eq!(plane.step, GitPlaneStepV1::FinalGate, "{row}");
    assert_pin_is(
        &plane.objects.pins.repository,
        &stored(&ran.dest, "repository"),
    );
    assert_pin_is(&plane.objects.pins.git, &git);
    assert_pin_is(&plane.objects.pins.objects, &git.join("objects"));
    assert_pin_is(&plane.objects.pins.pack, &git.join("objects/pack"));
    assert_pin_is(&plane.objects.pins.info, &git.join("objects/info"));
    for (relative, pin) in &plane.metadata.directories {
        assert_pin_is(pin, &git.join(relative));
    }
    for file in plane.objects.files.iter().chain(&plane.metadata.files) {
        assert_eq!(
            (&file.file).stream_position().expect("a position"),
            0,
            "{row}: {}",
            file.relative
        );
        let mut read = Vec::new();
        (&file.file)
            .read_to_end(&mut read)
            .expect("the retained descriptor reads");
        assert_eq!(
            Some(&Some(read)),
            want.get(&file.relative),
            "{row}: {}: the retained descriptor reads the bytes on disk",
            file.relative
        );
        (&file.file)
            .seek(SeekFrom::Start(0))
            .expect("rewind the retained descriptor");
    }
    assert!(
        plane.capsule().staged.iter().all(|one| position(one) == 0),
        "{row}: every staged descriptor is back at offset 0"
    );
    ran.assert_one_ledger(row);
}

// ---------------------------------------------------------------------------------------------
// The whole wrapper, end to end, with real objects, real Git, and real frames
// ---------------------------------------------------------------------------------------------

/// Real SHA-1 and SHA-256 capsules (real objects, a real pack, real frames) go from a real phase-V value to
/// the typed phase-G result through ONE call: pass A, the two prevalidations, both stores, and the final
/// proof, with the ORIGINAL capsule's one ledger. The source repository is removed first, so nothing outside
/// the retained destination can supply an object. The final proof is three children of the FINAL database
/// (inventory, reachability, strict fsck; no index, no verify-pack), rooted at the retained repository with
/// HOME, XDG, and GIT_DIR all `.git`, in the closed environment, with no object-store route; the closure
/// evidence, the bootstrap's evidence, and the pre-write agreement all agree, and the result keeps every pin.
#[test]
fn b2c_real_sha1_and_sha256_capsules_restore_through_the_wrapper_with_exact_closure_and_inert_bytes(
) {
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let row = format!("{cformat:?}");
        let capsule = captured(cformat);
        let input = PlaneInV1::rich(&capsule, cformat);
        std::fs::remove_dir_all(&capsule.source.git_dir).expect("the source is removed");
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let plane = ran.success(&row);

        assert_eq!(route.children(), CAPTURED_CHILDREN_V1, "{row}");
        assert_eq!(
            plane.provenance(),
            GitFormatProvenanceV1::CapsuleObjectsAndPack,
            "{row}"
        );
        assert_eq!(plane.object_format(), ran.format, "{row}");
        assert_clean_plane(&ran, plane, &row);

        // The final children: the exact commands, the closed environment rooted at `.git`, no route.
        let labels: Vec<&str> = plane.closure.runs.iter().map(|run| run.label).collect();
        assert_eq!(labels, FINAL_LABELS_CAPTURED_V1, "{row}");
        for run in &plane.closure.runs {
            let env = |key: &str| run.environment.get(key).map(String::as_str);
            assert_eq!(env("GIT_DIR"), Some(".git"), "{row}: {}", run.label);
            assert_eq!(env("HOME"), Some(".git"), "{row}: {}", run.label);
            assert_eq!(env("XDG_CONFIG_HOME"), Some(".git"), "{row}: {}", run.label);
            assert_eq!(env("GIT_CONFIG_GLOBAL"), Some("/dev/null"), "{row}");
            assert_eq!(env("GIT_CONFIG_NOSYSTEM"), Some("1"), "{row}");
            assert!(
                !run.environment.contains_key("GIT_OBJECT_DIRECTORY"),
                "{row}"
            );
            assert!(
                !run.environment
                    .contains_key("GIT_ALTERNATE_OBJECT_DIRECTORIES"),
                "{row}"
            );
            assert_eq!(run.exit_status, Some(0), "{row}: {}", run.label);
        }
        // The bootstrap's children kept their own root (`init` is the one child given no `GIT_DIR`).
        assert_eq!(plane.bootstrap.runs.len(), 6, "{row}");
        for run in &plane.bootstrap.runs {
            let want = if run.label == "init --bare" {
                None
            } else {
                Some("git-bootstrap")
            };
            assert_eq!(
                run.environment.get("GIT_DIR").map(String::as_str),
                want,
                "{row}: {}",
                run.label
            );
        }

        // The closure evidence: every inventory object, reached, fsck strict, in the FINAL database, equal to
        // the bootstrap's.
        let evidence = GitClosureEvidenceV1 {
            inventory_objects: 4,
            closure: GitClosureProofV1::Reachable { objects: 4 },
            fsck_strict: true,
        };
        assert_eq!(plane.closure.evidence, evidence, "{row}");
        assert_eq!(plane.bootstrap.closure, evidence, "{row}");
        assert_eq!(
            plane.prewrite_agreement, plane.metadata.agreement,
            "{row}: the pre-write agreement is the restored files' agreement"
        );
        assert_eq!(
            plane.metadata.agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: Some(real_object(&capsule, KindV1::Commit).object_id().to_owned()),
            },
            "{row}"
        );
        assert_eq!(plane.metadata.agreement.manifest_refs, 5, "{row}");
    }
}

/// Empty objects (no pack, an empty inventory) with a captured, valid, UNBORN HEAD complete the whole wrapper
/// for BOTH caller formats of the same capsule: provenance is `CallerSelectedEmpty`, the closure is explicitly
/// vacuous, and no index-pack, verify-pack, or rev-list child runs anywhere (the bootstrap's init, inventory,
/// and fsck, then the final database's inventory and fsck). The restored tree is the refs frame's directories
/// and HEAD plus the golden config of the CALLER's format, and no object file exists.
#[test]
fn b2c_empty_objects_with_a_captured_unborn_head_complete_both_caller_formats_with_vacuous_reachability(
) {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    for caller in BOTH_CAPSULE_FORMATS_V1 {
        let row = format!("caller {caller:?}");
        let input = PlaneInV1::unborn(&capsule, caller);
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let plane = ran.success(&row);

        assert_eq!(route.children(), EMPTY_CHILDREN_V1, "{row}");
        assert_eq!(
            plane.provenance(),
            GitFormatProvenanceV1::CallerSelectedEmpty,
            "{row}"
        );
        assert_eq!(plane.object_format(), core_format(caller), "{row}");
        assert_clean_plane(&ran, plane, &row);
        assert!(plane.objects.files.is_empty(), "{row}: no pack, no index");
        assert!(
            listing(&pack_directory(&ran.dest)).is_empty(),
            "{row}: no object file"
        );
        let evidence = GitClosureEvidenceV1 {
            inventory_objects: 0,
            closure: GitClosureProofV1::Vacuous,
            fsck_strict: true,
        };
        assert_eq!(plane.closure.evidence, evidence, "{row}");
        assert_eq!(plane.bootstrap.closure, evidence, "{row}");
        let labels: Vec<&str> = plane.closure.runs.iter().map(|run| run.label).collect();
        assert_eq!(labels, FINAL_LABELS_EMPTY_V1, "{row}");
        assert_eq!(
            plane.closure.runs[0].stdout.length, 0,
            "{row}: an empty inventory"
        );
        assert_eq!(
            plane.metadata.agreement.head,
            HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: None,
            },
            "{row}"
        );
        let git = stored(&ran.dest, "repository/.git");
        assert_eq!(
            std::fs::read(git.join("config")).expect("the config"),
            golden_config(core_format(caller)),
            "{row}: the caller's format"
        );
        assert_eq!(
            std::fs::read(git.join("HEAD")).expect("HEAD"),
            HEAD_BYTES_V1,
            "{row}: the captured HEAD, never the bootstrap's"
        );
    }
}

/// Complete G needs a captured HEAD: an Empty `RefsAndHead` class is the typed refusal in BOTH caller formats
/// and for every object shape, with no frame at all and with a reflog frame alone. Pass A ACCEPTS every one of
/// them first (its whole bootstrap ran, and its value is retained), and the wrapper refuses after it with
/// `active_materialization_began = false`, the bootstrap gate as the last completed step, no final child, and
/// no `repository/`. The one ledger's figure is the bootstrap's, preserved; nothing is created or charged.
#[test]
fn b2c_empty_refs_refuse_before_the_repository_for_every_shape_and_format() {
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        for populated in [true, false] {
            let capsule = if populated {
                captured(cformat)
            } else {
                empty(cformat)
            };
            for shape in ["no frame", "reflogs only"] {
                let row = format!("{cformat:?} populated={populated} {shape}");
                let input = if shape == "no frame" {
                    PlaneInV1::frameless(&capsule, cformat)
                } else {
                    PlaneInV1::reflogs_only(&capsule, cformat)
                };
                let route = RouteV1::recorder();
                let ran = run_plane(input, &route, far_deadline());
                let failure = ran.failure(&row);

                assert!(
                    matches!(failure.cause, GitBootstrapErrorV1::EmptyRefsAndHead),
                    "{row}: {:?}",
                    failure.cause
                );
                assert!(!failure.active_materialization_began, "{row}");
                assert_eq!(
                    failure.last_completed,
                    Some(GitPlaneStepV1::BootstrapGate),
                    "{row}"
                );
                // Pass A accepted it: its children ran, and only they.
                let bootstrap_children: &[&str] = if populated {
                    &CAPTURED_CHILDREN_V1[..6]
                } else {
                    &EMPTY_CHILDREN_V1[..3]
                };
                assert_eq!(route.children(), bootstrap_children, "{row}");
                let boot = failure
                    .partial
                    .bootstrap
                    .as_ref()
                    .unwrap_or_else(|| panic!("{row}: pass A's value is retained"));
                assert_eq!(
                    boot.provenance,
                    if populated {
                        GitFormatProvenanceV1::CapsuleObjectsAndPack
                    } else {
                        GitFormatProvenanceV1::CallerSelectedEmpty
                    },
                    "{row}"
                );
                assert!(boot.closure.fsck_strict, "{row}");
                // Nothing under `repository/`; nothing created or charged by the refusal.
                assert_eq!(ran.dest.entries(), [".restore-work"], "{row}");
                assert!(
                    snapshot(&ran.dest.path)
                        .keys()
                        .all(|name| !name.contains("repository")),
                    "{row}"
                );
                assert!(matches!(
                    failure.partial.objects,
                    PlaneObjectsV1::NotStarted
                ));
                assert!(matches!(
                    failure.partial.metadata,
                    PlaneMetadataV1::NotStarted
                ));
                assert!(failure.partial.plan.is_none(), "{row}");
                assert!(failure.partial.final_runs.is_empty(), "{row}");
                // The one ledger, preserved: its figure is the phase-V charge plus the bootstrap's own.
                assert_eq!(
                    failure.ledger_used,
                    ran.phase_v + charge_on_disk(&ran.dest, &BOOTSTRAP_SUBTREES_V1),
                    "{row}"
                );
                ran.assert_one_ledger(&row);
            }
        }
    }
}

/// Detached, unborn, loose-over-packed, packed-only, ORIG_HEAD, FETCH_HEAD, stash, and reflog cases each go
/// through the whole wrapper in both formats: the tree is the test's own decode of the frames plus the golden
/// config, the refs agree from the retained final descriptors, and the final proof closes the same inventory.
#[test]
fn b2c_every_head_state_and_ref_family_completes_the_whole_wrapper_in_both_formats() {
    let families = [
        FamilyV1 {
            row: "an attached HEAD, packed-only refs, ORIG_HEAD",
            edit: edit_none,
            head: family_head,
            counts: (1, 2, 1, 3, 5, 2, 0, 2),
        },
        FamilyV1 {
            row: "a detached HEAD",
            edit: edit_detached,
            head: |specs| HeadStateV1::Detached {
                oid: specs.commit.clone(),
            },
            counts: (1, 2, 1, 3, 5, 2, 0, 2),
        },
        FamilyV1 {
            row: "an unborn branch",
            edit: edit_unborn,
            head: |_| HeadStateV1::Symbolic {
                target: "refs/heads/main".into(),
                resolved: None,
            },
            counts: (0, 2, 1, 2, 4, 1, 0, 2),
        },
        FamilyV1 {
            row: "a loose ref over a packed one",
            edit: edit_loose_over_packed,
            head: family_head,
            counts: (2, 2, 1, 3, 5, 2, 0, 1),
        },
        FamilyV1 {
            row: "FETCH_HEAD, a stash ref, and its reflog",
            edit: edit_pseudorefs_and_stash,
            head: family_head,
            counts: (2, 2, 1, 4, 7, 3, 1, 2),
        },
    ];
    for cformat in BOTH_CAPSULE_FORMATS_V1 {
        let capsule = captured(cformat);
        let format = core_format(cformat);
        for family in &families {
            let row = format!("{cformat:?}: {}", family.row);
            let mut specs = real_specs(&capsule, format);
            (family.edit)(&capsule, &mut specs);
            let input = PlaneInV1::with_frames(
                &capsule,
                cformat,
                &specs.refs,
                Some(&specs.logs),
                specs.manifest_refs.clone(),
            );
            let route = RouteV1::recorder();
            let ran = run_plane(input, &route, far_deadline());
            let plane = ran.success(&row);
            assert_eq!(route.children(), CAPTURED_CHILDREN_V1, "{row}");
            assert_clean_plane(&ran, plane, &row);
            assert_eq!(
                plane.metadata.agreement.head,
                (family.head)(&specs),
                "{row}"
            );
            let a = &plane.metadata.agreement;
            assert_eq!(
                (
                    a.loose_refs,
                    a.packed_refs,
                    a.peeled_rows,
                    a.effective_refs,
                    a.manifest_refs,
                    a.reflog_files,
                    a.fetch_head_rows,
                    a.direct_targets,
                ),
                family.counts,
                "{row}"
            );
            assert_eq!(plane.prewrite_agreement, plane.metadata.agreement, "{row}");
            assert_eq!(
                plane.closure.evidence.closure,
                GitClosureProofV1::Reachable { objects: 4 },
                "{row}"
            );
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Order: each helper runs only after the one before it, on the one deadline
// ---------------------------------------------------------------------------------------------

type GuardEventsV1 = std::rc::Rc<std::cell::RefCell<Vec<&'static str>>>;
type GuardFoundV1 = std::rc::Rc<std::cell::Cell<Option<&'static str>>>;
/// A snapshot of the destination, taken by a hook and read by the row after the run.
type SnapshotSlotV1 = std::rc::Rc<std::cell::RefCell<Option<BTreeMap<String, Option<Vec<u8>>>>>>;

/// Every guard the run reads the clock for, in order, by label.
fn record_plane_guards() -> (GuardEventsV1, GitSeamGuardV1) {
    let events: GuardEventsV1 = GuardEventsV1::default();
    let log = events.clone();
    let guard = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        log.borrow_mut().push(event.label);
    });
    (events, guard)
}

/// [`record_plane_guards`] that also does `act` at the guard with index `at`, if that guard is labelled `label`
/// (the hook point holds ONE hook). `found` is the label the fixture met at that index, so a row whose index
/// drifted is reported as such and never passes for the wrong guard.
fn act_at_index(
    at: usize,
    label: &'static str,
    act: impl Fn() + 'static,
) -> (GuardEventsV1, GuardFoundV1, GitSeamGuardV1) {
    let events: GuardEventsV1 = GuardEventsV1::default();
    let found: GuardFoundV1 = GuardFoundV1::default();
    let (log, met) = (events.clone(), found.clone());
    let guard = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        let index = log.borrow().len();
        log.borrow_mut().push(event.label);
        if index == at {
            met.set(Some(event.label));
            if event.label == label {
                act();
            }
        }
    });
    (events, found, guard)
}

fn logged_children(log: &Path) -> usize {
    std::fs::read_to_string(log)
        .unwrap_or_default()
        .lines()
        .filter(|line| !line.contains("version") && !line.trim().is_empty())
        .count()
}

fn objects_kind(objects: &PlaneObjectsV1) -> &'static str {
    match objects {
        PlaneObjectsV1::NotStarted => "not started",
        PlaneObjectsV1::Refused(_) => "refused",
        PlaneObjectsV1::Whole(_) => "whole",
    }
}

fn metadata_kind(metadata: &PlaneMetadataV1) -> &'static str {
    match metadata {
        PlaneMetadataV1::NotStarted => "not started",
        PlaneMetadataV1::Refused(_) => "refused",
        PlaneMetadataV1::Whole(_) => "whole",
    }
}

/// The helpers run in ONE order, each only after the one before it has completed, and each precondition of
/// the next holds when it runs: B1a and B1b run after pass A's closure and before ANY `repository/` entry;
/// B2a's first entry follows both; B2b starts when the object copy is whole; and no final child starts until
/// the config exists (HEAD, refs, and config all present). Each helper's entry guard is read exactly once.
/// The facts are the filesystem's own, read at the helper's first guard by the test.
#[test]
fn b2c_the_helpers_run_in_the_documented_order_and_each_precondition_holds_when_it_runs() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let route = RouteV1::recorder();
    let (root, log) = (input.dest.path.clone(), route.log.clone());
    // (label, repository exists, pack files copied, HEAD exists, config exists, children logged so far)
    type FactsV1 = (&'static str, bool, usize, bool, bool, usize);
    let facts: std::rc::Rc<std::cell::RefCell<Vec<FactsV1>>> = std::rc::Rc::default();
    let events: GuardEventsV1 = GuardEventsV1::default();
    let (seen, log_events) = (facts.clone(), events.clone());
    let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
        log_events.borrow_mut().push(event.label);
        if matches!(
            event.label,
            "frames-entry" | "refs-entry" | "objects-entry" | "metadata-entry" | "final-entry"
        ) {
            let pack = root.join("repository/.git/objects/pack");
            seen.borrow_mut().push((
                event.label,
                root.join("repository").exists(),
                std::fs::read_dir(&pack).map_or(0, |entries| entries.count()),
                root.join("repository/.git/HEAD").exists(),
                root.join("repository/.git/config").exists(),
                logged_children(&log),
            ));
        }
    });
    let census_children = std::rc::Rc::new(std::cell::RefCell::new(Vec::<(bool, usize)>::new()));
    let (root, log, seen) = (
        input.dest.path.clone(),
        route.log.clone(),
        census_children.clone(),
    );
    let _census = install_git_hook_for_test(GitHookPointV1::BeforeFinalChildCensus, move |_| {
        seen.borrow_mut().push((
            root.join("repository/.git/config").exists(),
            logged_children(&log),
        ));
    });
    let ran = run_plane(input, &route, far_deadline());
    let _ = ran.success("the ordered run");

    let facts = facts.borrow();
    assert_eq!(
        *facts,
        [
            ("frames-entry", false, 0, false, false, 6),
            ("refs-entry", false, 0, false, false, 6),
            ("objects-entry", false, 0, false, false, 6),
            ("metadata-entry", true, 3, false, false, 6),
            ("final-entry", true, 3, true, true, 6),
        ],
        "the state each helper finds when its entry guard reads the clock"
    );
    // The final children start only after the config exists, one after the other.
    assert_eq!(
        *census_children.borrow(),
        [(true, 6), (true, 7), (true, 8)],
        "every final child's census follows the config"
    );
    let events = events.borrow();
    for label in [
        "frames-entry",
        "refs-entry",
        "objects-entry",
        "metadata-entry",
        "final-entry",
    ] {
        assert_eq!(
            events.iter().filter(|event| **event == label).count(),
            1,
            "{label}: read once"
        );
    }
    let first = |label: &str| {
        events
            .iter()
            .position(|event| *event == label)
            .unwrap_or_else(|| panic!("no `{label}` guard"))
    };
    assert!(
        first("closing") < first("frames-entry"),
        "pass A closes first"
    );
    assert!(first("frames-entry") < first("refs-entry"));
    assert!(first("refs-entry") < first("objects-entry"));
    assert!(first("objects-entry") < first("metadata-entry"));
    assert!(first("metadata-entry") < first("final-entry"));
    assert_eq!(route.children(), CAPTURED_CHILDREN_V1);
}

/// A prevalidation or agreement refusal precedes EVERY repository write: a refs frame carrying a symlink, no
/// HEAD, or a name off the allowlist is B1a's refusal; a manifest ref the frames do not carry, or a ref naming
/// an object outside the inventory, is B1b's. Each is typed, begins nothing, and leaves the destination with
/// `.restore-work` alone and the ledger at pass A's charge, with pass A's value retained, no later child run,
/// and the bootstrap gate as the last completed step.
#[test]
fn b2c_a_refused_prevalidation_or_agreement_precedes_every_repository_write() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let format = core_format(CustodyGitObjectFormatV1::Sha1);
    let commit = real_object(&capsule, KindV1::Commit);
    type RowV1 = (
        &'static str,
        FrameSpecV1,
        Vec<CustodyOriginalRefV1>,
        fn(&GitBootstrapErrorV1) -> bool,
        bool,
    );
    let specs = real_specs(&capsule, format);
    let with_ghost = {
        let mut refs = specs.manifest_refs.clone();
        refs.push(direct_ref("refs/heads/ghost", &commit));
        refs
    };
    let rows: Vec<RowV1> = vec![
        (
            "a symlink in the refs frame",
            specs.refs.clone().link("refs/heads/evil", "../../outside"),
            specs.manifest_refs.clone(),
            |cause| matches!(cause, GitBootstrapErrorV1::ActiveFrame { .. }),
            false,
        ),
        (
            "no HEAD",
            specs.refs.clone().without("HEAD"),
            specs.manifest_refs.clone(),
            |cause| matches!(cause, GitBootstrapErrorV1::ActiveFrame { .. }),
            false,
        ),
        (
            "a name off the allowlist",
            specs.refs.clone().file("config", "[core]\n"),
            specs.manifest_refs.clone(),
            |cause| matches!(cause, GitBootstrapErrorV1::ActiveFrame { .. }),
            false,
        ),
        (
            "a manifest ref the frames do not carry",
            specs.refs.clone(),
            with_ghost,
            |cause| matches!(cause, GitBootstrapErrorV1::Refs(_)),
            true,
        ),
        (
            "a ref naming an object outside the inventory",
            specs
                .refs
                .clone()
                .without("refs/heads/main")
                .file("refs/heads/main", format!("{}\n", "f".repeat(40))),
            specs.manifest_refs.clone(),
            |cause| matches!(cause, GitBootstrapErrorV1::Refs(_)),
            true,
        ),
    ];
    for (row, refs, manifest_refs, check, planned) in rows {
        let input = PlaneInV1::with_frames(
            &capsule,
            CustodyGitObjectFormatV1::Sha1,
            &refs,
            Some(&specs.logs),
            manifest_refs,
        );
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let failure = ran.failure(row);
        assert!(check(&failure.cause), "{row}: {:?}", failure.cause);
        assert!(!failure.active_materialization_began, "{row}");
        assert_eq!(
            failure.last_completed,
            Some(GitPlaneStepV1::BootstrapGate),
            "{row}"
        );
        assert_eq!(route.children(), &CAPTURED_CHILDREN_V1[..6], "{row}");
        assert_eq!(ran.dest.entries(), [".restore-work"], "{row}");
        assert_eq!(
            failure.ledger_used,
            ran.phase_v + charge_on_disk(&ran.dest, &BOOTSTRAP_SUBTREES_V1),
            "{row}: the ledger is pass A's, unchanged"
        );
        assert!(failure.partial.bootstrap.is_some(), "{row}");
        assert_eq!(failure.partial.plan.is_some(), planned, "{row}");
        assert_eq!(
            objects_kind(&failure.partial.objects),
            "not started",
            "{row}"
        );
        assert_eq!(
            metadata_kind(&failure.partial.metadata),
            "not started",
            "{row}"
        );
        assert!(failure.partial.final_runs.is_empty(), "{row}");
        ran.assert_one_ledger(row);
    }
}

/// The caller's frame budget, path-table bound, and refs limits reach the helpers that apply them: a table
/// bound too small for the frames is B1a's refusal, a refs limit too small for the files is B1b's, and a
/// frame budget too small to decode them is B1a's `FrameInvalid`; none begins anything. The wrapper takes no
/// other bounds, and applies each of them to every helper that takes it (see the structural row).
#[test]
fn b2c_the_callers_bounds_reach_the_helpers_that_apply_them() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let tiny_budget = CustodyFrameBudgetV1::new(1, 1).expect("a tiny frame budget");
    let small_limits = RefsLimitsV1 {
        entries: 1,
        ..RefsLimitsV1::v1()
    };
    // (the row, the budget, the table bound, the limits, the refusal, whether B1a had already planned)
    type RowV1 = (
        &'static str,
        CustodyFrameBudgetV1,
        u64,
        RefsLimitsV1,
        fn(&GitBootstrapErrorV1) -> bool,
        bool,
    );
    let rows: [RowV1; 3] = [
        (
            "a path table bound of 1",
            frame_budget(),
            1,
            RefsLimitsV1::v1(),
            |cause| {
                matches!(
                    cause,
                    GitBootstrapErrorV1::ActiveFrame {
                        fault: ActiveFrameFaultV1::PathTableBound { bound: 1 },
                        ..
                    }
                )
            },
            false,
        ),
        (
            "refs limits of one entry",
            frame_budget(),
            B2B_TABLE_BOUND_V1,
            small_limits,
            |cause| {
                matches!(
                    cause,
                    GitBootstrapErrorV1::Refs(RefsFaultV1::Limit {
                        what: RefsLimitKindV1::Entries,
                        ..
                    })
                )
            },
            true,
        ),
        (
            "a frame budget that cannot decode the frames",
            tiny_budget,
            B2B_TABLE_BOUND_V1,
            RefsLimitsV1::v1(),
            |cause| {
                matches!(
                    cause,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::FrameInvalid { .. })
                )
            },
            false,
        ),
    ];
    for (row, budget, table_bound, limits, check, planned) in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let route = RouteV1::recorder();
        let ran = run_plane_bounded(input, &route, budget, table_bound, limits);
        let failure = ran.failure(row);
        assert!(check(&failure.cause), "{row}: {:?}", failure.cause);
        assert!(!failure.active_materialization_began, "{row}");
        assert_eq!(ran.dest.entries(), [".restore-work"], "{row}");
        // Which helper refused: B1a runs first, so its refusals leave no plan, and B1b's follow B1a's.
        assert_eq!(
            failure.partial.plan.is_some(),
            planned,
            "{row}: the helper that refused"
        );
        ran.assert_one_ledger(row);
    }
    // The defaults of the wrapper are the documented ones: the same capsule restores without a bound.
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let route = RouteV1::recorder();
    let ran = run_plane_bounded(
        input,
        &route,
        frame_budget(),
        B2B_TABLE_BOUND_V1,
        RefsLimitsV1::v1(),
    );
    let _ = ran.success("the documented defaults");
}

// ---------------------------------------------------------------------------------------------
// The ONE deadline: every helper receives the caller's instant, and none resets it
// ---------------------------------------------------------------------------------------------

/// A step that returns after the caller's ONE absolute deadline, read at each helper's own entry guard in
/// turn: B1a, B1b, B2a, B2b, and the final proof each refuse with the typed timeout, at THAT helper's entry,
/// with nothing created after the guard that found it spent. A helper handed a fresh instant (or a longer
/// one) would not refuse, so the refusal at each entry shows the same instant reached it. The facts are the
/// typed progress and the retained state each stage leaves.
#[test]
fn b2c_the_one_deadline_reaches_every_helper_and_none_resets_it() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    // (the helper's entry guard, last completed, began, plan, objects, metadata, final runs, children)
    type RowV1 = (
        &'static str,
        Option<GitPlaneStepV1>,
        bool,
        bool,
        &'static str,
        &'static str,
        usize,
    );
    let rows: [RowV1; 5] = [
        (
            "frames-entry",
            Some(GitPlaneStepV1::BootstrapGate),
            false,
            false,
            "not started",
            "not started",
            6,
        ),
        (
            "refs-entry",
            Some(GitPlaneStepV1::BootstrapGate),
            false,
            true,
            "not started",
            "not started",
            6,
        ),
        (
            "objects-entry",
            Some(GitPlaneStepV1::BootstrapGate),
            false,
            true,
            "refused",
            "not started",
            6,
        ),
        (
            "metadata-entry",
            Some(GitPlaneStepV1::Objects),
            true,
            true,
            "whole",
            "refused",
            6,
        ),
        (
            "final-entry",
            Some(GitPlaneStepV1::Config),
            true,
            true,
            "whole",
            "whole",
            6,
        ),
    ];
    for (label, completed, began, planned, objects, metadata, children) in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let route = RouteV1::recorder();
        let deadline = Instant::now() + B2C_DEADLINE_V1;
        let root = input.dest.path.clone();
        let at_the_guard: SnapshotSlotV1 = SnapshotSlotV1::default();
        let (stored_state, spent) = (at_the_guard.clone(), std::cell::Cell::new(false));
        let _hook = install_git_hook_for_test(GitHookPointV1::DeadlineObserved, move |event| {
            if event.label == label && !spent.replace(true) {
                *stored_state.borrow_mut() = Some(snapshot(&root));
                pass_the_deadline(deadline);
            }
        });
        let ran = run_plane(input, &route, deadline);
        let failure = ran.failure(label);
        assert!(is_timeout(&failure.cause), "{label}: {:?}", failure.cause);
        assert_eq!(failure.last_completed, completed, "{label}");
        assert_eq!(failure.active_materialization_began, began, "{label}");
        assert_eq!(failure.partial.plan.is_some(), planned, "{label}");
        assert_eq!(objects_kind(&failure.partial.objects), objects, "{label}");
        assert_eq!(
            metadata_kind(&failure.partial.metadata),
            metadata,
            "{label}"
        );
        assert!(failure.partial.final_runs.is_empty(), "{label}");
        assert_eq!(route.children().len(), children, "{label}: no later child");
        assert_eq!(
            Some(snapshot(&ran.dest.path)),
            at_the_guard.borrow().clone(),
            "{label}: nothing was created after the guard that found the deadline spent"
        );
        ran.assert_one_ledger(label);
    }
}

// ---------------------------------------------------------------------------------------------
// The final stage's guards: derived from the filesystem, and each halts the run alone
// ---------------------------------------------------------------------------------------------

/// The parts of ONE final child's bracket that a success is made of, in the order they run. A slow call in any
/// of them returns after the one deadline with a child possibly still to run or still to be accepted, so each is
/// held to that deadline: none may be followed by a call before the clock is read.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BracketV1 {
    /// The zero-effect baseline: the census of the exact tree and the digest of every restored file, before the
    /// runner is called.
    Baseline,
    /// The runner's pre-spawn callback: the mount census and every retained chain.
    BeforeCallback,
    /// The runner's post-exit callback, which cannot know whether the child succeeded.
    AfterCallback,
    /// The settlement of a result that is about to be a success: the census, the digests, and the success gate.
    Settlement,
}

/// Where a guard of the final stage stands.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StageV1 {
    /// The stage's entry guard.
    Entry,
    /// A part of the bracket of final child `n` (1-based).
    Child(usize, BracketV1),
    /// The rewinds of the staged descriptors.
    Rewind,
    /// The closing gate.
    Closing,
}

impl StageV1 {
    /// How many final children had started, and how many proofs the failure records, when a refusal ends the
    /// run in this stage of a run with `total` final children: a refusal in a callback of a child makes the
    /// runner return an error, so the child that ran is not recorded.
    fn children_after(self, total: usize) -> (usize, usize) {
        match self {
            Self::Entry => (0, 0),
            Self::Child(child, BracketV1::Baseline | BracketV1::BeforeCallback) => {
                (child - 1, child - 1)
            }
            Self::Child(child, BracketV1::AfterCallback) => (child, child - 1),
            Self::Child(child, BracketV1::Settlement) => (child, child),
            Self::Rewind | Self::Closing => (total, total),
        }
    }
}

/// One clean run's final stage, with the facts its guard sequence is derived from (the test's OWN
/// measurement of the disk and of the retained value, never the production code under test).
struct FinalShapeV1 {
    events: Vec<&'static str>,
    entry: usize,
    final_children: usize,
    object_files: usize,
    metadata_dirs: usize,
    metadata_files: usize,
    staging_dirs: usize,
    /// The components of every staging directory's key, in the sweep's order (a key's chain is the work and
    /// plain entries and one more per component).
    staging_depths: Vec<usize>,
    bootstrap_dirs: usize,
    staged: usize,
    /// Directories of the final tree: `.git` and every directory beneath it.
    tree_dirs: usize,
    /// Every entry beneath `.git`.
    tree_entries: usize,
    /// How many entries each directory of the tree lists, in the census's directory order (`.git`, then the
    /// directories beneath it by path), by the test's own `read_dir`.
    dir_entries: Vec<usize>,
    /// Whether each entry the closing census listed, in the order it listed them, is a regular file, by the
    /// test's own `symlink_metadata` of the path the census was about to open.
    closing_regular: Vec<bool>,
    /// The one ledger's charge after the clean run.
    ledger: u64,
}

impl FinalShapeV1 {
    /// The guards of the sweep's staging chains, ONE UNIT PER RETAINED EDGE, each behind its own guard and each
    /// attempted once (follow-on 1 targeted repair; before it the work and plain entries were replayed for every
    /// staging key and every key's prefixes were replayed): the work directory's entry (`chain`), the plain
    /// directory's, and each retained staging directory's, once, in key order (`chain-step`).
    fn staging_chain_events(&self) -> Vec<&'static str> {
        let mut events = vec!["chain", "chain-step"];
        events.extend(std::iter::repeat_n("chain-step", self.staging_depths.len()));
        events
    }

    /// The guards of one sweep of everything retained: the five output directories and every copied file, the
    /// metadata directories and files, every admitted source file (a guard before its `fstat` by name and one
    /// before its descriptor's), the retained chains, and the root last.
    fn sweep(&self, events: &mut Vec<&'static str>) {
        events.extend(std::iter::repeat_n("objects-chain", 5 + self.object_files));
        events.extend(std::iter::repeat_n(
            "final-chain",
            self.metadata_dirs + self.metadata_files,
        ));
        for _ in 0..self.object_files {
            events.extend(["final-source", "final-source-statted"]);
        }
        events.extend(self.staging_chain_events());
        events.extend(std::iter::repeat_n("chain", 2 + self.bootstrap_dirs));
        events.push("root");
    }

    /// The guards of one census of the exact tree. Every slow call is followed by a guard before the next one:
    /// the repository (a clock, its `fstat`, a clock, its listing, a clock before its one entry), each
    /// directory (a clock, its `fstat`, a clock, its listing), each entry (a clock before its `fstat`), and, for
    /// a regular file, a clock before its open and one between its open and its `fstat`.
    fn census(&self, events: &mut Vec<&'static str>) {
        events.extend(["final-census", "final-statted", "final-census"]);
        let mut regular = self.closing_regular.iter();
        for entries in &self.dir_entries {
            events.extend(["final-census", "final-statted"]);
            for _ in 0..*entries {
                events.push("final-census");
                if *regular.next().expect("a listed entry") {
                    events.extend(["final-entry-statted", "final-opened"]);
                }
            }
        }
    }

    /// The guards of the digest of every restored file: before each file, after its open, and after its read.
    fn digests(&self, events: &mut Vec<&'static str>) {
        for _ in 0..self.object_files + self.metadata_files {
            events.extend(["final-digest", "final-digest-opened", "final-digest-read"]);
        }
    }

    /// The guards of one gate of a final child (a runner callback's, or the settlement's success gate): its
    /// entry guard, which stands before the mount census and so also right after the call before the gate, then
    /// the sweep of everything retained (whose first guard stands right after the mount census).
    fn gate(&self, events: &mut Vec<&'static str>) {
        events.push("final-gate");
        self.sweep(events);
    }

    /// The whole final stage a clean run must log, derived from the facts above, each guard with where it
    /// stands. Every success-eligible bracket of a final child is held to the one deadline, so each child logs:
    /// its zero-effect baseline (the census of the exact tree and the digest of every restored file, then a
    /// guard before the runner is called); the gate of the pre-spawn callback; the gate of the post-exit
    /// callback; and the settlement of a result that is about to be a success (the census, the digests, and
    /// the success gate). The rewinds and the closing gate follow the last child.
    fn expected_staged(&self) -> Vec<(&'static str, StageV1)> {
        let mut staged: Vec<(&'static str, StageV1)> = vec![("final-entry", StageV1::Entry)];
        let mut part = |stage: StageV1, events: Vec<&'static str>| {
            staged.extend(events.into_iter().map(|label| (label, stage)));
        };
        for child in 1..=self.final_children {
            let mut events = Vec::new();
            self.census(&mut events);
            self.digests(&mut events);
            events.push("final-baselined");
            part(StageV1::Child(child, BracketV1::Baseline), events);
            for bracket in [BracketV1::BeforeCallback, BracketV1::AfterCallback] {
                let mut events = Vec::new();
                self.gate(&mut events);
                part(StageV1::Child(child, bracket), events);
            }
            let mut events = Vec::new();
            self.census(&mut events);
            self.digests(&mut events);
            self.gate(&mut events);
            part(StageV1::Child(child, BracketV1::Settlement), events);
        }
        let mut events = vec!["final-rewind"];
        events.extend(std::iter::repeat_n("final-rewound", self.staged));
        part(StageV1::Rewind, events);
        let mut events = vec!["final-closing", "final-mounts"];
        self.census(&mut events);
        events.push("final-tree");
        self.digests(&mut events);
        events.push("final-digested");
        self.sweep(&mut events);
        part(StageV1::Closing, events);
        staged
    }

    /// [`Self::expected_staged`]'s guards alone.
    fn expected(&self) -> Vec<&'static str> {
        self.expected_staged()
            .into_iter()
            .map(|(label, _)| label)
            .collect()
    }

    /// The index, in the whole run's guards, of the first guard labelled `label` in `stage`.
    fn index_in(&self, stage: StageV1, label: &str) -> usize {
        self.entry
            + self
                .expected_staged()
                .iter()
                .position(|found| *found == (label, stage))
                .unwrap_or_else(|| panic!("no `{label}` guard in {stage:?}"))
    }

    /// The index of the first guard labelled `label` at or after `from`.
    fn first_after(&self, from: usize, label: &str) -> usize {
        from + self.events[from..]
            .iter()
            .position(|event| *event == label)
            .unwrap_or_else(|| panic!("no `{label}` guard after #{from}"))
    }
}

fn clean_final_shape(
    capsule: &CustomCapsuleV1,
    caller: CustodyGitObjectFormatV1,
    rich: bool,
) -> FinalShapeV1 {
    let input = if rich {
        PlaneInV1::rich(capsule, caller)
    } else {
        PlaneInV1::unborn(capsule, caller)
    };
    let staged = input.verified.staged.len();
    let (events, _guard) = record_plane_guards();
    let opens: std::rc::Rc<std::cell::RefCell<Vec<PathBuf>>> = std::rc::Rc::default();
    let seen = opens.clone();
    let _opens = install_git_hook_for_test(GitHookPointV1::BeforeFinalCensusOpen, move |event| {
        seen.borrow_mut().push(event.path.to_path_buf());
    });
    let route = RouteV1::recorder();
    let ran = run_plane(input, &route, far_deadline());
    let plane = ran.success("the clean control");
    let git = stored(&ran.dest, "repository/.git");
    let tree = snapshot(&git);
    let mut dir_keys: Vec<String> = tree
        .iter()
        .filter(|(_, bytes)| bytes.is_none())
        .map(|(name, _)| name.clone())
        .collect();
    dir_keys.push(String::new());
    dir_keys.sort();
    let dir_entries = dir_keys
        .iter()
        .map(|key| {
            std::fs::read_dir(git.join(key))
                .expect("a listable directory")
                .count()
        })
        .collect();
    // Every census lists the same entries, so the closing gate's is the last `tree.len()` the hook saw.
    let opened = opens.borrow();
    let closing_regular = opened[opened.len() - tree.len()..]
        .iter()
        .map(|path| {
            std::fs::symlink_metadata(path)
                .expect("a listed entry")
                .is_file()
        })
        .collect();
    let directories = |root: &Path| {
        snapshot(root)
            .values()
            .filter(|bytes| bytes.is_none())
            .count()
    };
    let staging_depths: Vec<usize> = snapshot(&ran.dest.work().join("plain"))
        .iter()
        .filter(|(_, bytes)| bytes.is_none())
        .map(|(name, _)| name.split('/').count())
        .collect();
    let below = tree.values().filter(|bytes| bytes.is_none()).count();
    let files = tree.len() - below;
    let object_files = tree
        .iter()
        .filter(|(name, bytes)| name.starts_with("objects/pack/") && bytes.is_some())
        .count();
    let events = events.borrow().clone();
    let entry = events
        .iter()
        .position(|event| *event == "final-entry")
        .expect("the final stage's entry guard");
    FinalShapeV1 {
        entry,
        events,
        final_children: plane.closure.runs.len(),
        object_files,
        metadata_dirs: below - 3,
        metadata_files: files - object_files,
        staging_dirs: directories(&ran.dest.work().join("plain")),
        bootstrap_dirs: directories(&ran.dest.bootstrap()) + 1,
        staged,
        staging_depths,
        tree_dirs: 1 + below,
        tree_entries: tree.len(),
        dir_entries,
        closing_regular,
        ledger: plane.ledger_used(),
    }
}

/// The guards of the final stage are EXACTLY the ones derived from the filesystem, in order, for an Empty
/// database (no object file) and a Captured one: the clock is read at the stage's entry; in every part of
/// each final child's bracket (its baseline census and digests and the guard before the runner is called, the
/// gate of its pre-spawn callback and the gate of its post-exit callback, and its settlement census, digests,
/// and success gate, each gate being its entry guard and then every retained chain); before the first staged
/// rewind and after each; and through the closing gate (the mount census, the census of the exact tree after
/// every call that is followed by another, the digest of each restored file after each of its calls, and every
/// chain, one guard per call). The LAST guard is the one immediately before the destination root's identity,
/// with nothing read after it. Every guard site has a halting row below; this pins that none is missing,
/// doubled, or moved.
#[test]
fn b2c_the_final_guards_run_in_the_documented_order() {
    for (row, shape) in [
        (
            "an Empty database",
            clean_final_shape(
                &empty(CustodyGitObjectFormatV1::Sha1),
                CustodyGitObjectFormatV1::Sha1,
                false,
            ),
        ),
        (
            "a Captured database",
            clean_final_shape(
                &captured(CustodyGitObjectFormatV1::Sha1),
                CustodyGitObjectFormatV1::Sha1,
                true,
            ),
        ),
    ] {
        assert_eq!(
            shape.events[shape.entry..],
            shape.expected(),
            "{row}: the final stage's guards"
        );
        assert_eq!(
            shape.events.last(),
            Some(&"root"),
            "{row}: the root's guard is the last read of the run"
        );
    }
}

/// The index, label, and stage of the guards a halting row slows. In the stage's entry, the rewinds, and the
/// closing gate: the first and the last guard of every run of equal labels. In each part of the FIRST final
/// child's bracket (the other children run the same code, so their brackets add nothing): the first and the
/// last guard of the part, and the first guard of every distinct label in it, so every guard of every part
/// has a row, whether it is the plumbing of the deadline into that part or a site the closing gate's rows
/// already cover one by one.
fn halting_rows(shape: &FinalShapeV1) -> Vec<(usize, &'static str, StageV1)> {
    let staged = shape.expected_staged();
    let mut rows = Vec::new();
    let mut at = 0_usize;
    while at < staged.len() {
        let stage = staged[at].1;
        let mut end = at;
        while end < staged.len() && staged[end].1 == stage {
            end += 1;
        }
        match stage {
            StageV1::Child(child, _) if child > 1 => {}
            StageV1::Child(..) => {
                let part = &staged[at..end];
                let mut seen = std::collections::BTreeSet::new();
                for (offset, (label, _)) in part.iter().enumerate() {
                    let first_of_its_label = seen.insert(*label);
                    if first_of_its_label || offset == 0 || offset == part.len() - 1 {
                        rows.push((shape.entry + at + offset, *label, stage));
                    }
                }
            }
            StageV1::Entry | StageV1::Rewind | StageV1::Closing => {
                let mut run = at;
                while run < end {
                    let (label, _) = staged[run];
                    let mut last = run;
                    while last < end && staged[last].0 == label {
                        last += 1;
                    }
                    rows.push((shape.entry + run, label, stage));
                    if last - 1 != run {
                        rows.push((shape.entry + last - 1, label, stage));
                    }
                    run = last;
                }
            }
        }
        at = end;
    }
    rows
}

/// One halting row: the run in which the step before guard `index` (labelled `label`, standing in `stage`) is
/// made slow past the one deadline, and every problem found with how it ended. `rich` runs a Captured database
/// (the bootstrap ran six Git children) and not an Empty one with an unborn HEAD (three).
fn halting_row(
    capsule: &CustomCapsuleV1,
    shape: &FinalShapeV1,
    index: usize,
    label: &'static str,
    stage: StageV1,
    rich: bool,
) -> Vec<String> {
    let name = format!("guard #{index} `{label}` ({stage:?})");
    let input = if rich {
        PlaneInV1::rich(capsule, CustodyGitObjectFormatV1::Sha1)
    } else {
        PlaneInV1::unborn(capsule, CustodyGitObjectFormatV1::Sha1)
    };
    let route = RouteV1::recorder();
    // These concurrent rows share fixture I/O.  This headroom lets each row reach its named
    // recorded guard; the injected guard still supplies the typed timeout proof.
    let deadline = Instant::now() + Duration::from_secs(12);
    let (events, found, _hook) = act_at_index(index, label, move || pass_the_deadline(deadline));
    let ran = run_plane(input, &route, deadline);
    println!(
        "GUARD-MARKER {name}: found={:?} guards_run={} returned {}ms after the deadline",
        found.get(),
        events.borrow().len(),
        Instant::now()
            .saturating_duration_since(deadline)
            .as_millis()
    );
    if found.get() != Some(label) {
        return vec![format!("{name}: the fixture found {:?}", found.get())];
    }
    let Err(failure) = &ran.outcome else {
        return vec![format!("{name}: a success followed the expiry")];
    };
    let (started, recorded) = stage.children_after(shape.final_children);
    let mut judged = Vec::new();
    if !is_timeout(&failure.cause) {
        judged.push(format!("cause {:?}", failure.cause));
    }
    if failure.last_completed != Some(GitPlaneStepV1::Config) {
        judged.push(format!("completed {:?}", failure.last_completed));
    }
    if !failure.active_materialization_began {
        judged.push("began nothing".to_owned());
    }
    if events.borrow().len() != index + 1 {
        judged.push(format!(
            "{} guards ran after it",
            events.borrow().len().saturating_sub(index + 1)
        ));
    }
    if failure.partial.final_runs.len() != recorded {
        judged.push(format!(
            "{} final children recorded, {recorded} had returned",
            failure.partial.final_runs.len()
        ));
    }
    let bootstrap_children = if rich { 6 } else { 3 };
    if route.children().len() != bootstrap_children + started {
        judged.push(format!("children {:?}", route.children()));
    }
    if failure.ledger_used != shape.ledger {
        judged.push(format!(
            "ledger {} not {}",
            failure.ledger_used, shape.ledger
        ));
    }
    if judged.is_empty() {
        Vec::new()
    } else {
        vec![format!("{name}: {}", judged.join("; "))]
    }
}

/// Every guard of the final stage halts the run alone: the step before it is made slow past the one deadline,
/// and the run ends with the typed timeout AT that guard: the children that had started and the proofs that had
/// returned (a refusal in a runner callback makes the runner return an error, so that child's proof is not
/// recorded), `Config` as the last completed step, the ledger exactly as a clean run leaves it, a failure and
/// never a success, and NO later guard read (so nothing further was done toward a result, and the root's
/// identity was never reached). The rows are independent runs that mostly wait for their deadline, so they run
/// on a few threads at once. The rows are derived from an Empty database's run; the guards that exist only for a
/// Captured database (those of its admitted bootstrap files) are derived from a Captured run, and every one of
/// them has its rows too.
#[test]
fn b2c_every_final_guard_halts_the_run_alone_and_no_success_follows_expiry() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let shape = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, false);
    let captured_capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let captured_shape = clean_final_shape(&captured_capsule, CustodyGitObjectFormatV1::Sha1, true);
    let mut rows: Vec<(bool, usize, &'static str, StageV1)> = halting_rows(&shape)
        .into_iter()
        .map(|(index, label, stage)| (false, index, label, stage))
        .collect();
    assert!(rows.len() >= 60, "{}", rows.len());
    for bracket in [
        BracketV1::Baseline,
        BracketV1::BeforeCallback,
        BracketV1::AfterCallback,
        BracketV1::Settlement,
    ] {
        assert!(
            rows.iter().any(|row| row.3 == StageV1::Child(1, bracket)),
            "{bracket:?} has rows"
        );
    }
    // The labels of the Empty database's documented sequence (the order row holds it equal to what a run logs).
    let empty_labels: std::collections::BTreeSet<&str> = shape.expected().into_iter().collect();
    let only_captured: Vec<(bool, usize, &'static str, StageV1)> = halting_rows(&captured_shape)
        .into_iter()
        .filter(|(_, label, _)| !empty_labels.contains(label))
        .map(|(index, label, stage)| (true, index, label, stage))
        .collect();
    let labels: std::collections::BTreeSet<&str> = only_captured
        .iter()
        .map(|&(_, _, label, _)| label)
        .collect();
    assert_eq!(
        labels,
        std::collections::BTreeSet::from(["final-source", "final-source-statted"]),
        "the guards only a Captured database has"
    );
    println!(
        "HALTING-ROWS: {} for an Empty database, {} more for the guards only a Captured one has",
        rows.len(),
        only_captured.len()
    );
    rows.extend(only_captured);
    let problems: Vec<String> = std::thread::scope(|scope| {
        let mut all = Vec::new();
        for chunk in rows.chunks(8) {
            let handles: Vec<_> = chunk
                .iter()
                .map(|&(rich, index, label, stage)| {
                    let (capsule, shape) = if rich {
                        (&captured_capsule, &captured_shape)
                    } else {
                        (&capsule, &shape)
                    };
                    scope.spawn(move || halting_row(capsule, shape, index, label, stage, rich))
                })
                .collect();
            for handle in handles {
                all.extend(handle.join().expect("a halting row's thread"));
            }
        }
        all
    });
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

// ---------------------------------------------------------------------------------------------
// The final gate: the exact tree, every retained chain, and the root LAST
// ---------------------------------------------------------------------------------------------

fn tree_fault(error: &GitBootstrapErrorV1, want: FinalTreeFaultV1) -> bool {
    matches!(error, GitBootstrapErrorV1::FinalTree { fault, .. } if *fault == want)
}

fn symlink_refused(error: &GitBootstrapErrorV1) -> bool {
    matches!(
        error,
        GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { .. })
    )
}

/// `path` as another inode holding the same bytes, atomically: the copy is written outside and renamed over.
fn replace_with_same_bytes(path: &Path, outside: &Path) {
    let staged = outside.join("replacement");
    std::fs::write(&staged, std::fs::read(path).expect("the file")).expect("the replacement");
    std::fs::rename(&staged, path).expect("the replacement takes the name");
}

/// `path` as another inode holding bytes of the same length that are NOT the same (its first byte flipped),
/// atomically: the copy is written outside and renamed over.
fn replace_with_other_bytes(path: &Path, outside: &Path) {
    let mut bytes = std::fs::read(path).expect("the file");
    bytes[0] = !bytes[0];
    let staged = outside.join("replacement-bytes");
    std::fs::write(&staged, bytes).expect("the replacement");
    std::fs::rename(&staged, path).expect("the replacement takes the name");
}

fn replace_with_link(path: &Path, outside: &Path) {
    let staged = outside.join("replacement-link");
    std::os::unix::fs::symlink(outside.join("decoy"), &staged).expect("a link");
    std::fs::rename(&staged, path).expect("the link takes the name");
}

fn replace_with_fifo(path: &Path, outside: &Path) {
    let staged = outside.join("replacement-fifo");
    mkfifo(&staged);
    std::fs::rename(&staged, path).expect("the fifo takes the name");
}

/// A directory moved out of the tree and replaced by an empty one at its name.
fn swap_directory(path: &Path, outside: &Path) {
    std::fs::rename(path, outside.join("moved-away")).expect("the directory moves away");
    std::fs::create_dir(path).expect("a new directory takes the name");
}

/// The `.pack` beneath `git`'s `objects/pack` (the final repository's, or a bootstrap's: the layout is one).
fn pack_file(git: &Path) -> PathBuf {
    admitted_path(git, "pack")
}

/// The final tree changed after every proof and before the closing gate is refused AS WHAT IT IS, by the
/// census of the exact tree and the digest of every restored file: an entry the restore did not make (beside
/// `.git`'s own, in a restored directory, in the object directories, a `hooks` directory, a hidden
/// `.gitconfig`), an entry removed, a same-length change to HEAD or to the pack, a grown config, a file that
/// is another inode with the same bytes, a link, a FIFO, a directory swapped for a new one or for a link, and
/// more entries than the census admits. Each is typed, the run fails (never a success) with `Config` as the
/// last completed step and every proof recorded, and the ledger is the clean run's: the final stage reserves
/// nothing. Every byte stays.
#[test]
fn b2c_a_tree_changed_before_the_final_gate_is_refused_as_what_it_is_with_every_byte_kept() {
    type MutateV1 = fn(&Path, &Path);
    type RowV1 = (&'static str, MutateV1, fn(&GitBootstrapErrorV1) -> bool);
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let rows: Vec<RowV1> = vec![
        (
            "an entry beside the restore's own",
            |git, _| std::fs::write(git.join("stray"), b"x").expect("a stray"),
            |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
        ),
        (
            "an entry beside the Git directory in the repository",
            |git, _| std::fs::write(git.join("../stray"), b"x").expect("a stray"),
            |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
        ),
        (
            "the Git directory moved away",
            |git, outside| std::fs::rename(git, outside.join("git-away")).expect("moved away"),
            |e| tree_fault(e, FinalTreeFaultV1::Missing),
        ),
        (
            "an entry in a restored directory",
            |git, _| std::fs::write(git.join("refs/heads/stray"), b"x").expect("a stray"),
            |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
        ),
        (
            "an entry in the object directory",
            |git, _| std::fs::write(git.join("objects/pack/stray"), b"x").expect("a stray"),
            |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
        ),
        (
            "an entry in the object info directory",
            |git, _| {
                std::fs::write(git.join("objects/info/alternates"), b"/elsewhere\n")
                    .expect("an alternates file")
            },
            |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
        ),
        (
            "a hooks directory",
            |git, _| {
                std::fs::create_dir(git.join("hooks")).expect("hooks");
                std::fs::write(git.join("hooks/pre-commit"), b"#!/bin/sh\n").expect("a hook");
            },
            |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
        ),
        (
            "a hidden gitconfig",
            |git, _| std::fs::write(git.join(".gitconfig"), b"[core]\n").expect("a config"),
            |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
        ),
        (
            "the config removed",
            |git, _| std::fs::remove_file(git.join("config")).expect("the config goes"),
            |e| tree_fault(e, FinalTreeFaultV1::Missing),
        ),
        (
            "a metadata directory moved away",
            |git, outside| {
                std::fs::rename(git.join("refs/tags"), outside.join("tags")).expect("moved")
            },
            |e| tree_fault(e, FinalTreeFaultV1::Missing),
        ),
        (
            "a same-length change to HEAD",
            |git, _| change_in_place(&git.join("HEAD")),
            |e| tree_fault(e, FinalTreeFaultV1::Bytes),
        ),
        (
            "a same-length change to the pack",
            |git, _| change_in_place(&pack_file(git)),
            |e| tree_fault(e, FinalTreeFaultV1::Bytes),
        ),
        (
            "a grown config",
            |git, _| {
                use std::io::Write as _;
                std::fs::OpenOptions::new()
                    .append(true)
                    .open(git.join("config"))
                    .and_then(|mut file| file.write_all(b"x"))
                    .expect("an appended byte");
            },
            |e| tree_fault(e, FinalTreeFaultV1::Bytes),
        ),
        (
            "a file that is another inode with the same bytes",
            |git, outside| replace_with_same_bytes(&git.join("logs/HEAD"), outside),
            |e| tree_fault(e, FinalTreeFaultV1::Replaced),
        ),
        (
            "a file replaced by a link",
            |git, outside| replace_with_link(&git.join("refs/heads/main"), outside),
            symlink_refused,
        ),
        (
            "a file replaced by a FIFO",
            |git, outside| replace_with_fifo(&git.join("ORIG_HEAD"), outside),
            |e| tree_fault(e, FinalTreeFaultV1::Special),
        ),
        (
            "a file replaced by a directory",
            |git, outside| {
                std::fs::rename(git.join("ORIG_HEAD"), outside.join("ORIG_HEAD-away"))
                    .expect("the file moves away");
                std::fs::create_dir(git.join("ORIG_HEAD")).expect("a directory takes the name");
            },
            |e| tree_fault(e, FinalTreeFaultV1::Replaced),
        ),
        (
            "a directory replaced by a regular file",
            |git, outside| {
                std::fs::rename(git.join("refs/tags"), outside.join("tags-away"))
                    .expect("the directory moves away");
                std::fs::write(git.join("refs/tags"), b"x").expect("a file takes the name");
            },
            |e| tree_fault(e, FinalTreeFaultV1::Replaced),
        ),
        (
            "a restored directory swapped for a new one",
            |git, outside| swap_directory(&git.join("refs/heads"), outside),
            is_identity_changed,
        ),
        (
            "a restored directory replaced by a link",
            |git, outside| {
                std::fs::rename(git.join("refs/tags"), outside.join("tags-away")).expect("moved");
                std::os::unix::fs::symlink(outside, git.join("refs/tags")).expect("a link");
            },
            symlink_refused,
        ),
        (
            "more entries than the census admits",
            |git, _| {
                for number in 0..64 {
                    std::fs::write(git.join(format!("stray-{number}")), b"x").expect("a stray");
                }
            },
            |e| tree_fault(e, FinalTreeFaultV1::Bound),
        ),
    ];
    let mut problems = Vec::new();
    for (row, mutate, check) in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (_area, outside) = external_dir_with(&["decoy"]);
        let git = input.dest.path.join("repository/.git");
        let _hook = install_git_hook_for_test(GitHookPointV1::BeforePlaneFinalGate, move |_| {
            mutate(&git, &outside)
        });
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let Err(failure) = &ran.outcome else {
            problems.push(format!("{row}: a success followed the change"));
            continue;
        };
        let mut judged = Vec::new();
        if !check(&failure.cause) {
            judged.push(format!("cause {:?}", failure.cause));
        }
        if failure.last_completed != Some(GitPlaneStepV1::Config) {
            judged.push(format!("completed {:?}", failure.last_completed));
        }
        if !failure.active_materialization_began {
            judged.push("began nothing".to_owned());
        }
        if failure.partial.final_runs.len() != 3 || route.children().len() != 9 {
            judged.push(format!(
                "{} final proofs, children {:?}",
                failure.partial.final_runs.len(),
                route.children()
            ));
        }
        if objects_kind(&failure.partial.objects) != "whole"
            || metadata_kind(&failure.partial.metadata) != "whole"
        {
            judged.push("the retained stores are not whole".to_owned());
        }
        if failure.ledger_used != clean.ledger {
            judged.push(format!(
                "ledger {} not {}",
                failure.ledger_used, clean.ledger
            ));
        }
        if !judged.is_empty() {
            problems.push(format!("{row}: {}", judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// The mount census runs before each final child, after it, and at its success gate, and again at the closing
/// gate: a mount that appears for any ONE of the last seven calls refuses at that call, `Config` as the last
/// completed step, with exactly the children and proofs that had come before it; and a census that cannot
/// list the mount points fails closed at the first and at the last of them.
#[test]
fn b2c_a_mount_appearing_for_a_final_census_refuses_and_a_failing_census_fails_closed() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let caller = CustodyGitObjectFormatV1::Sha1;
    let input = PlaneInV1::unborn(&capsule, caller);
    let census = crate::custody_mounts::seam::install_list(vec![b"/".to_vec()]);
    let route = RouteV1::recorder();
    let ran = run_plane(input, &route, far_deadline());
    let _ = ran.success("a clean run");
    let calls = census.calls();
    drop(census);
    assert!(calls > 7, "{calls}");
    // The last calls, backwards: the closing gate; the second child's success gate, post-exit callback, and
    // pre-spawn callback; the first child's success gate, post-exit callback, and pre-spawn callback. Each
    // is judged by the proofs recorded and the final children that had started.
    let rows: [(usize, usize, usize); 7] = [
        (0, 2, 2),
        (1, 2, 2),
        (2, 1, 2),
        (3, 1, 1),
        (4, 1, 1),
        (5, 0, 1),
        (6, 0, 0),
    ];
    for (offset, recorded, started) in rows {
        let row = format!("census call {} (the last but {offset})", calls - offset);
        let input = PlaneInV1::unborn(&capsule, caller);
        let inside = input
            .dest
            .path
            .join(".restore-work/home")
            .as_os_str()
            .as_bytes()
            .to_vec();
        let call = calls - offset;
        let _census = crate::custody_mounts::seam::install(Box::new(move |number| {
            if number == call {
                Ok(vec![b"/".to_vec(), inside.clone()])
            } else {
                Ok(vec![b"/".to_vec()])
            }
        }));
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let failure = ran.failure(&row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::MountBoundary(_))
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(
            failure.last_completed,
            Some(GitPlaneStepV1::Config),
            "{row}"
        );
        assert!(failure.active_materialization_began, "{row}");
        assert_eq!(failure.partial.final_runs.len(), recorded, "{row}");
        assert_eq!(route.children().len(), 3 + started, "{row}");
        ran.assert_one_ledger(&row);
    }
    for offset in [0, 6] {
        let row = format!("a failing census at the last but {offset}");
        let input = PlaneInV1::unborn(&capsule, caller);
        let call = calls - offset;
        let _census = crate::custody_mounts::seam::install(Box::new(move |number| {
            if number == call {
                Err(crate::custody_mounts::CustodyMountErrorV1::MalformedLine { line: 1 })
            } else {
                Ok(vec![b"/".to_vec()])
            }
        }));
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let failure = ran.failure(&row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::MountBoundary(_))
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(
            failure.last_completed,
            Some(GitPlaneStepV1::Config),
            "{row}"
        );
    }
}

/// A retained chain swapped while the closing gate sweeps it, and the destination root swapped at the guard
/// immediately before its identity check, are each refused by THAT step's own recheck: an output directory,
/// a copied object file (a link), a metadata directory, a metadata file (a link), an admitted bootstrap
/// file (by its entry, and by its retained descriptor after its entry was checked), the work directory, the
/// plain directory and a staging directory after the entries before them were checked, HOME, XDG, the
/// bootstrap root, and a directory of the bootstrap; the root at the closing gate's last guard and at a
/// child's success gate. None is a timeout and none is a success (the clock is NOT spent), no guard is
/// read after the refusing step, and every proof is recorded: the root's identity is still the LAST fallible
/// check after its guard.
#[test]
fn b2c_a_retained_chain_swapped_in_the_final_gates_or_the_root_swapped_last_is_refused_by_its_own_step(
) {
    type SwapV1 = fn(&Path, &Path);
    struct RowV1 {
        name: &'static str,
        index: usize,
        label: &'static str,
        swap: SwapV1,
        check: fn(&GitBootstrapErrorV1) -> bool,
        /// Final children whose proofs were recorded when it refused.
        recorded: usize,
    }
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let shape = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let closing = shape.first_after(shape.entry, "final-closing");
    let sweep = shape.first_after(closing, "objects-chain");
    let first_chain = shape.first_after(sweep, "chain");
    let metadata_chain = shape.first_after(sweep, "final-chain");
    let rows = vec![
        RowV1 {
            name: "an output directory",
            index: sweep + 4,
            label: "objects-chain",
            swap: |root, outside| {
                swap_directory(&root.join("repository/.git/objects/info"), outside)
            },
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "a copied object file replaced by a link",
            index: sweep + 5,
            label: "objects-chain",
            swap: |root, outside| {
                replace_with_link(&pack_file(&root.join("repository/.git")), outside)
            },
            check: symlink_refused,
            recorded: 3,
        },
        RowV1 {
            name: "a metadata directory",
            index: metadata_chain,
            label: "final-chain",
            swap: |root, outside| swap_directory(&root.join("repository/.git/logs"), outside),
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "a metadata file replaced by a link",
            index: metadata_chain + shape.metadata_dirs,
            label: "final-chain",
            swap: |root, outside| replace_with_link(&root.join("repository/.git/HEAD"), outside),
            check: symlink_refused,
            recorded: 3,
        },
        RowV1 {
            name: "an admitted bootstrap file",
            index: shape.first_after(sweep, "final-source"),
            label: "final-source",
            swap: |root, outside| {
                // The first admitted file is the `.pack`, and the step this guard precedes is its own.
                let pack = pack_file(&root.join(".restore-work/git-bootstrap"));
                replace_with_same_bytes(&pack, outside);
            },
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "an admitted bootstrap file's retained descriptor, after its entry was checked",
            index: shape.first_after(sweep, "final-source-statted"),
            label: "final-source-statted",
            swap: |root, _| {
                // The same inode, so the entry by name still matches in identity; only the descriptor's own
                // length, read next, shows it.
                let pack = pack_file(&root.join(".restore-work/git-bootstrap"));
                append_fixture_byte(&pack);
            },
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "the work directory",
            index: first_chain,
            label: "chain",
            swap: |root, outside| swap_directory(&root.join(".restore-work"), outside),
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "the plain directory, after the work directory's entry was checked",
            index: first_chain + 1,
            label: "chain-step",
            swap: |root, outside| swap_directory(&root.join(".restore-work/plain"), outside),
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "a staging directory, after the work and plain entries were checked",
            // One unit per retained edge: the work entry's guard, the plain entry's, then the first staging
            // directory's (follow-on 1 targeted repair: it used to be the fifth, behind a replay of work and plain).
            index: first_chain + 2,
            label: "chain-step",
            swap: |root, outside| {
                swap_directory(&root.join(".restore-work/plain/control"), outside)
            },
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "HOME",
            index: first_chain + shape.staging_chain_events().len(),
            label: "chain",
            swap: |root, outside| swap_directory(&root.join(".restore-work/home"), outside),
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "XDG",
            index: first_chain + shape.staging_chain_events().len() + 1,
            label: "chain",
            swap: |root, outside| swap_directory(&root.join(".restore-work/xdg"), outside),
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "the bootstrap root",
            index: first_chain + shape.staging_chain_events().len() + 2,
            label: "chain",
            swap: |root, outside| {
                swap_directory(&root.join(".restore-work/git-bootstrap"), outside)
            },
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "a directory of the bootstrap",
            index: first_chain + shape.staging_chain_events().len() + 3,
            label: "chain",
            swap: |root, outside| {
                // The second retained bootstrap directory, in the sweep's (sorted) order: the first below the root.
                let bootstrap = root.join(".restore-work/git-bootstrap");
                let (name, _) = snapshot(&bootstrap)
                    .into_iter()
                    .find(|(_, bytes)| bytes.is_none())
                    .expect("a bootstrap directory");
                swap_directory(&bootstrap.join(name), outside);
            },
            check: is_identity_changed,
            recorded: 3,
        },
        RowV1 {
            name: "the destination root at a child's pre-spawn callback",
            index: shape.index_in(StageV1::Child(1, BracketV1::BeforeCallback), "root"),
            label: "root",
            swap: |root, outside| swap_directory(root, outside),
            check: is_identity_changed,
            recorded: 0,
        },
        RowV1 {
            name: "the destination root at a child's post-exit callback",
            index: shape.index_in(StageV1::Child(1, BracketV1::AfterCallback), "root"),
            label: "root",
            swap: |root, outside| swap_directory(root, outside),
            check: is_identity_changed,
            recorded: 0,
        },
        RowV1 {
            name: "the destination root at a child's success gate",
            index: shape.index_in(StageV1::Child(1, BracketV1::Settlement), "root"),
            label: "root",
            swap: |root, outside| swap_directory(root, outside),
            check: is_identity_changed,
            recorded: 1,
        },
        RowV1 {
            name: "the destination root at the closing gate",
            index: shape.events.len() - 1,
            label: "root",
            swap: |root, outside| swap_directory(root, outside),
            check: is_identity_changed,
            recorded: 3,
        },
    ];
    let mut problems = Vec::new();
    for row in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (_area, outside) = external_dir_with(&["decoy"]);
        let root = input.dest.path.clone();
        let swap = row.swap;
        let (events, found, _hook) = act_at_index(row.index, row.label, move || {
            swap(&root, &outside);
        });
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let name = format!("{} (guard #{} `{}`)", row.name, row.index, row.label);
        if found.get() != Some(row.label) {
            problems.push(format!("{name}: the fixture found {:?}", found.get()));
            continue;
        }
        let Err(failure) = &ran.outcome else {
            problems.push(format!("{name}: a success followed the swap"));
            continue;
        };
        let mut judged = Vec::new();
        if !(row.check)(&failure.cause) {
            judged.push(format!("cause {:?}", failure.cause));
        }
        if failure.last_completed != Some(GitPlaneStepV1::Config) {
            judged.push(format!("completed {:?}", failure.last_completed));
        }
        if events.borrow().len() != row.index + 1 {
            judged.push(format!(
                "{} guards ran after the refusing step",
                events.borrow().len().saturating_sub(row.index + 1)
            ));
        }
        if failure.partial.final_runs.len() != row.recorded {
            judged.push(format!(
                "{} proofs recorded, not {}",
                failure.partial.final_runs.len(),
                row.recorded
            ));
        }
        if failure.ledger_used != shape.ledger {
            judged.push(format!(
                "ledger {} not {}",
                failure.ledger_used, shape.ledger
            ));
        }
        if !judged.is_empty() {
            problems.push(format!("{name}: {}", judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

// ---------------------------------------------------------------------------------------------
// Every final child's outcome is judged by its proof, never by its exit status
// ---------------------------------------------------------------------------------------------

type ErrorCheckV2 = fn(&GitBootstrapErrorV1) -> bool;

/// The Captured SHA-1 wrapper run with the FINAL database's child `needle` tampered with by `shell` (the
/// bootstrap's identical child delegates untouched), for each row. Every row is a failure typed by
/// `check`, with `children` tokens logged (the bootstrap's six and the final children that started),
/// `recorded` final proofs, `Config` as the last completed step, materialization begun, the ledger the
/// clean run's, and every byte on disk exactly as it was when the final stage began.
fn final_child_rows(
    capsule: &CustomCapsuleV1,
    needle: &str,
    children: usize,
    recorded: usize,
    rows: &[(&str, &str, ErrorCheckV2)],
) {
    let clean = clean_final_shape(capsule, CustodyGitObjectFormatV1::Sha1, true);
    let mut problems = Vec::new();
    for (row, shell, check) in rows {
        let input = PlaneInV1::rich(capsule, CustodyGitObjectFormatV1::Sha1);
        let root = input.dest.path.clone();
        let stage: SnapshotSlotV1 = SnapshotSlotV1::default();
        let stored_state = stage.clone();
        let _hook = install_git_hook_for_test(GitHookPointV1::BeforeFinalChildCensus, move |_| {
            let mut slot = stored_state.borrow_mut();
            if slot.is_none() {
                *slot = Some(snapshot(&root));
            }
        });
        let route = RouteV1::new(&[(needle, &final_only(shell))]);
        let ran = run_plane(input, &route, far_deadline());
        let Err(failure) = &ran.outcome else {
            problems.push(format!("{needle}: {row}: a success"));
            continue;
        };
        let mut judged = Vec::new();
        if !check(&failure.cause) {
            judged.push(format!("cause {:?}", failure.cause));
        }
        if route.children().len() != children {
            judged.push(format!("children {:?}", route.children()));
        }
        if failure.partial.final_runs.len() != recorded {
            judged.push(format!("{} proofs", failure.partial.final_runs.len()));
        }
        if failure.last_completed != Some(GitPlaneStepV1::Config) {
            judged.push(format!("completed {:?}", failure.last_completed));
        }
        if !failure.active_materialization_began {
            judged.push("began nothing".to_owned());
        }
        if failure.ledger_used != clean.ledger {
            judged.push(format!("ledger {}", failure.ledger_used));
        }
        if Some(snapshot(&ran.dest.path)) != *stage.borrow() {
            judged.push("a byte changed".to_owned());
        }
        if !judged.is_empty() {
            problems.push(format!("{needle}: {row}: {}", judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// The final `cat-file` inventory is the manifest's exact `(oid, kind)` set: a missing, extra, wrong-kind, or
/// duplicate object, a malformed row, output that is not UTF-8 or has no final line feed, and a nonzero exit
/// are each refused with their own type, and no later child starts.
#[test]
fn b2c_the_final_inventory_is_classified_by_its_rows_and_never_by_its_status() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    final_child_rows(
        &capsule,
        "cat-file --batch-all-objects",
        7,
        1,
        &[
            (
                "a missing object",
                "\"$REAL\" \"$@\" | tail -n +2",
                |e| matches!(e, GitBootstrapErrorV1::InventoryMismatch(detail) if detail.contains("missing")),
            ),
            (
                "an extra object",
                "\"$REAL\" \"$@\"; echo 'ffffffffffffffffffffffffffffffffffffffff blob'",
                |e| matches!(e, GitBootstrapErrorV1::InventoryMismatch(detail) if detail.contains("extra object")),
            ),
            (
                "a wrong kind",
                "\"$REAL\" \"$@\" | sed 's/ blob$/ tree/'",
                |e| matches!(e, GitBootstrapErrorV1::InventoryMismatch(detail) if detail.contains("not blob")),
            ),
            (
                "a duplicate row",
                "out=$(\"$REAL\" \"$@\"); echo \"$out\"; echo \"$out\" | head -n 1",
                |e| matches!(e, GitBootstrapErrorV1::InventoryMismatch(detail) if detail.contains("twice")),
            ),
            (
                "a row with a third field",
                "\"$REAL\" \"$@\" | sed '1s/$/ junk/'",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(_)),
            ),
            (
                "an object id that is not hex",
                "\"$REAL\" \"$@\" | sed '1s/^[0-9a-f]/G/'",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(_)),
            ),
            (
                "output that is not UTF-8",
                "\"$REAL\" \"$@\"; printf '\\377\\n'",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("UTF-8")),
            ),
            (
                "a truncated final line",
                "out=$(\"$REAL\" \"$@\"); printf '%s' \"$out\"",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("partial")),
            ),
            (
                "output cut after the first row",
                "\"$REAL\" \"$@\" | head -n 1",
                |e| matches!(e, GitBootstrapErrorV1::InventoryMismatch(detail) if detail.contains("missing")),
            ),
            ("a nonzero exit", "\"$REAL\" \"$@\"; exit 2", |e| {
                is_git_child(e, "cat-file --batch-all-objects", 2)
            }),
            // A malformed stream outranks the exit status; a well-formed one that disagrees does not.
            (
                "a nonzero exit after output that is not UTF-8",
                "\"$REAL\" \"$@\"; printf '\\377\\n'; exit 2",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("UTF-8")),
            ),
            (
                "a nonzero exit after a truncated final line",
                "out=$(\"$REAL\" \"$@\"); printf '%s' \"$out\"; exit 2",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("partial")),
            ),
            (
                "a nonzero exit after a clean prefix of the rows",
                "\"$REAL\" \"$@\" | head -n 1; exit 2",
                |e| is_git_child(e, "cat-file --batch-all-objects", 2),
            ),
        ],
    );
}

/// The final `rev-list` is fed every inventory object and must reach exactly that set: a missing marker, a
/// malformed or duplicate row, an object outside the inventory, an unreached inventory object, output that
/// is not UTF-8 or is truncated, and a nonzero exit are each refused with their own type; the strict fsck
/// never starts.
#[test]
fn b2c_the_final_reachability_is_classified_by_its_rows_and_never_by_its_status() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    final_child_rows(
        &capsule,
        "rev-list --objects",
        8,
        2,
        &[
            (
                "a missing marker",
                "cat > /dev/null; echo \"?$(printf '%040d' 0)\"",
                |e| matches!(e, GitBootstrapErrorV1::ClosureIncomplete(detail) if detail.contains("absent")),
            ),
            ("malformed output", "cat > /dev/null; echo garbage", |e| {
                matches!(e, GitBootstrapErrorV1::GitOutput(_))
            }),
            (
                "an object outside the inventory",
                "\"$REAL\" \"$@\"; echo 'ffffffffffffffffffffffffffffffffffffffff'",
                |e| matches!(e, GitBootstrapErrorV1::ClosureIncomplete(detail) if detail.contains("unexpected")),
            ),
            (
                "an inventory object that is not reached",
                "\"$REAL\" \"$@\" | tail -n +2",
                |e| matches!(e, GitBootstrapErrorV1::ClosureIncomplete(detail) if detail.contains("not reached")),
            ),
            (
                "a duplicate row",
                "out=$(\"$REAL\" \"$@\"); echo \"$out\"; echo \"$out\" | head -n 1",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("twice")),
            ),
            (
                "output that is not UTF-8",
                "\"$REAL\" \"$@\"; printf '\\377\\n'",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("UTF-8")),
            ),
            (
                "a truncated final line",
                "out=$(\"$REAL\" \"$@\"); printf '%s' \"$out\"",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("partial")),
            ),
            ("a nonzero exit", "cat > /dev/null; exit 1", |e| {
                is_git_child(e, "rev-list --missing=print", 1)
            }),
            (
                "a nonzero exit after output that is not UTF-8",
                "\"$REAL\" \"$@\"; printf '\\377\\n'; exit 1",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("UTF-8")),
            ),
            (
                "a nonzero exit after a truncated final line",
                "out=$(\"$REAL\" \"$@\"); printf '%s' \"$out\"; exit 1",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(detail) if detail.contains("partial")),
            ),
            (
                "a nonzero exit after a clean prefix of the rows",
                "\"$REAL\" \"$@\" | head -n 1; exit 1",
                |e| is_git_child(e, "rev-list --missing=print", 1),
            ),
        ],
    );
}

/// The final strict fsck is classified by its WHOLE stream before its exit status: stdout noise, an
/// unclassified diagnostic, a strict-object rejection with a nonzero exit, and a nonzero exit with a clean
/// stream are each refused with their own type, with every earlier proof recorded.
#[test]
fn b2c_the_final_fsck_is_classified_by_its_whole_stream_before_its_exit_status() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    final_child_rows(
        &capsule,
        "fsck --strict",
        9,
        3,
        &[
            (
                "stdout noise",
                "\"$REAL\" \"$@\"; echo noise",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(_)),
            ),
            (
                "a strict object id and a nonzero exit",
                "echo 'error: object 0123456789abcdef0123456789abcdef01234567: zeroPaddedFilemode: contains zero-padded file modes' >&2; exit 1",
                |e| matches!(e, GitBootstrapErrorV1::StrictObjectCheck(id) if id == "zeroPaddedFilemode"),
            ),
            (
                "an unclassified diagnostic",
                "echo 'warning: strange' >&2",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(_)),
            ),
            (
                "a repeated notice",
                "printf 'notice: No default references\\nnotice: No default references\\n' >&2",
                |e| matches!(e, GitBootstrapErrorV1::GitOutput(_)),
            ),
            ("a nonzero exit with a clean stream", "exit 1", |e| {
                is_git_child(e, "fsck --strict", 1)
            }),
        ],
    );
}

/// A final child's EFFECT is measured on every outcome, against the zero-effect baseline the retained tree
/// gave it, and no outcome is lost: a failed child that left an entry keeps BOTH failures; a child that
/// succeeded but grew HEAD, rewrote it in place with every clock stalled (only the digest sees it), replaced
/// it with another inode, or put a link where a file was, is refused for that; a timed-out child, with or
/// without an effect, and a child that also drifted the Git binary, keep the typed timeout and the drift
/// beside their effect. The ledger is the clean run's on every one (a read-only child reserves nothing), and
/// every byte stays.
#[test]
fn b2c_a_final_child_that_leaves_an_effect_is_refused_beside_its_own_outcome_on_every_outcome() {
    type RowV1 = (
        &'static str,
        String,
        ErrorCheckV2,
        usize,
        bool,
        Option<Duration>,
    );
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let rows: Vec<RowV1> = vec![
        (
            "a failed child that left an entry",
            "\"$REAL\" \"$@\"; : > .git/stray; exit 1".into(),
            |e| {
                combined_with(
                    e,
                    |p| is_git_child(p, "fsck --strict", 1),
                    |r| tree_fault(r, FinalTreeFaultV1::Unexpected),
                )
            },
            3,
            false,
            None,
        ),
        (
            "a child that grew HEAD (its post-exit gate sees the length first)",
            "\"$REAL\" \"$@\"; echo x >> .git/HEAD".into(),
            |e| {
                combined_with(
                    e,
                    is_identity_changed,
                    |r| tree_fault(r, FinalTreeFaultV1::Bytes),
                )
            },
            2,
            false,
            None,
        ),
        (
            "a child that rewrote HEAD in place, every clock stalled",
            "\"$REAL\" \"$@\"; printf X | dd of=.git/HEAD bs=1 seek=10 conv=notrunc 2>/dev/null"
                .into(),
            |e| tree_fault(e, FinalTreeFaultV1::Bytes),
            3,
            true,
            None,
        ),
        // Design follow-on 1: the comparison refuses the moved timestamps FIRST (the paced settlement's finding is the
        // primary), and the bytes, which only the file's own retained descriptor can show, are still observed and
        // named beside it: before, this row required the comparison's finding ALONE, which hid them.
        (
            "a child that rewrote HEAD in place, the clocks running",
            "\"$REAL\" \"$@\"; sleep 1; printf X | dd of=.git/HEAD bs=1 seek=10 conv=notrunc 2>/dev/null"
                .into(),
            |e| {
                combined_with(
                    e,
                    |p| is_budget(p, "read-only"),
                    |r| tree_fault(r, FinalTreeFaultV1::Bytes),
                )
            },
            3,
            false,
            None,
        ),
        (
            "a child that replaced HEAD with another inode",
            "\"$REAL\" \"$@\"; cp .git/HEAD .git/HEAD.new; mv .git/HEAD.new .git/HEAD".into(),
            |e| {
                combined_with(
                    e,
                    is_identity_changed,
                    |r| tree_fault(r, FinalTreeFaultV1::Replaced),
                )
            },
            2,
            false,
            None,
        ),
        (
            "a child that put a link where a file was",
            "\"$REAL\" \"$@\"; rm .git/ORIG_HEAD; ln -s /etc/hostname .git/ORIG_HEAD".into(),
            |e| combined_with(e, symlink_refused, symlink_refused),
            2,
            false,
            None,
        ),
        (
            "a timed-out child that left an entry",
            ": > .git/stray; sleep 30".into(),
            |e| {
                combined_with(
                    e,
                    is_timeout,
                    |r| tree_fault(r, FinalTreeFaultV1::Unexpected),
                )
            },
            2,
            false,
            Some(B2C_DEADLINE_V1),
        ),
        (
            "a timed-out child that left nothing",
            "sleep 30".into(),
            |e| is_timeout(e) || combined_with(e, is_timeout, is_timeout),
            2,
            false,
            Some(B2C_DEADLINE_V1),
        ),
        (
            "a child beside a drifted Git binary and an entry",
            "\"$REAL\" \"$@\"; : > .git/stray; chmod u+w \"$0\"; echo '# drift' >> \"$0\"".into(),
            |e| {
                combined_with(
                    e,
                    is_binary_drift,
                    |r| tree_fault(r, FinalTreeFaultV1::Unexpected),
                )
            },
            2,
            false,
            None,
        ),
        // A restored DIRECTORY is part of the zero-effect tree: its mode and timestamps are facts too.
        (
            "a child that changed a restored directory's mode, every clock stalled",
            "\"$REAL\" \"$@\"; chmod 0755 .git/objects/info".into(),
            |e| is_budget(e, "read-only"),
            3,
            true,
            None,
        ),
        (
            "a child that changed the Git directory's mode, the clocks running",
            "\"$REAL\" \"$@\"; chmod 0755 .git".into(),
            |e| is_budget(e, "read-only"),
            3,
            false,
            None,
        ),
        (
            "a child that changed the repository directory's mode, every clock stalled",
            "\"$REAL\" \"$@\"; chmod 0755 .".into(),
            |e| is_budget(e, "read-only"),
            3,
            true,
            None,
        ),
        (
            "a child that touched the repository directory, the clocks running",
            "\"$REAL\" \"$@\"; sleep 1; touch .".into(),
            |e| is_budget(e, "read-only"),
            3,
            false,
            None,
        ),
        (
            "a child that touched a restored directory, the clocks running",
            "\"$REAL\" \"$@\"; sleep 1; touch .git/refs".into(),
            |e| is_budget(e, "read-only"),
            3,
            false,
            None,
        ),
        (
            "a failed child that changed a restored directory's mode",
            "\"$REAL\" \"$@\"; chmod 0755 .git/objects/info; exit 1".into(),
            |e| {
                combined_with(
                    e,
                    |p| is_git_child(p, "fsck --strict", 1),
                    |r| is_budget(r, "read-only"),
                )
            },
            3,
            true,
            None,
        ),
        (
            "a timed-out child that changed a restored directory's mode",
            "chmod 0755 .git/objects/info; sleep 30".into(),
            |e| combined_with(e, is_timeout, |r| is_budget(r, "read-only")),
            2,
            true,
            Some(B2C_DEADLINE_V1),
        ),
        // The byte effect of a child that already failed is measured whatever the clock says.
        (
            "a failed child that rewrote HEAD in place, every clock stalled",
            "\"$REAL\" \"$@\"; printf X | dd of=.git/HEAD bs=1 seek=10 conv=notrunc 2>/dev/null; exit 1"
                .into(),
            |e| {
                combined_with(
                    e,
                    |p| is_git_child(p, "fsck --strict", 1),
                    |r| tree_fault(r, FinalTreeFaultV1::Bytes),
                )
            },
            3,
            true,
            None,
        ),
        (
            "a timed-out child that rewrote HEAD in place, every clock stalled",
            "printf X | dd of=.git/HEAD bs=1 seek=10 conv=notrunc 2>/dev/null; sleep 30".into(),
            |e| {
                combined_with(
                    e,
                    is_timeout,
                    |r| tree_fault(r, FinalTreeFaultV1::Bytes),
                )
            },
            2,
            true,
            Some(B2C_DEADLINE_V1),
        ),
    ];
    let mut problems = Vec::new();
    for (row, shell, check, recorded, stalled, limit) in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let _clocks = stalled.then(|| stall_census_clocks_for_test(BOTH_CLOCKS_V1));
        let route = RouteV1::new(&[("fsck --strict", &final_only(&shell))]);
        let deadline = limit.map_or_else(far_deadline, |limit| Instant::now() + limit);
        let ran = run_plane(input, &route, deadline);
        let Err(failure) = &ran.outcome else {
            problems.push(format!("{row}: a success"));
            continue;
        };
        let mut judged = Vec::new();
        if !check(&failure.cause) {
            judged.push(format!("cause {:?}", failure.cause));
        }
        if route.children().len() != 9 {
            judged.push(format!("children {:?}", route.children()));
        }
        if failure.partial.final_runs.len() != recorded {
            judged.push(format!("{} proofs", failure.partial.final_runs.len()));
        }
        if failure.last_completed != Some(GitPlaneStepV1::Config)
            || !failure.active_materialization_began
        {
            judged.push(format!("completed {:?}", failure.last_completed));
        }
        if failure.ledger_used != clean.ledger {
            judged.push(format!(
                "ledger {} not {}",
                failure.ledger_used, clean.ledger
            ));
        }
        if !judged.is_empty() {
            problems.push(format!("{row}: {}", judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// The digest that serves a child that has ALREADY failed is bounded by the length the census measured, not by
/// the clock: a file that grew after that census and after its descriptor was bound to it (so only the read can
/// show it) is read one byte past the measured length and no further, for a child that failed and for one that
/// timed out (whose deadline has already passed), and the refusal names that count beside the child's own
/// failure. (A timed-out child's grown file is also refused by the retained chains, which the one failure-only
/// reconciliation of a child that may have run now sweeps, so that row keeps both refusals.)
#[test]
fn b2c_a_failed_childs_reconciliation_digest_reads_one_byte_past_the_census_and_no_further() {
    type PrimaryV1 = fn(&GitBootstrapErrorV1) -> bool;
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    // Source round 4: a timed-out child's post-exit gate never ran, so the one failure-only reconciliation also
    // sweeps the retained chains, and the grown HEAD is refused there too (its retained length changed): the
    // digest's refusal, exactly as before, is the first of the two kept beside the timeout. The failed child's
    // post-exit gate ran before the file grew (it grows during the settlement), so only the tree is owed.
    let rows: [(&str, &str, Option<Duration>, PrimaryV1, bool); 2] = [
        (
            "a failed child",
            "\"$REAL\" \"$@\"; exit 1",
            None,
            |e| is_git_child(e, "fsck --strict", 1),
            false,
        ),
        (
            "a timed-out child",
            "sleep 30",
            Some(B2C_DEADLINE_V1),
            is_timeout,
            true,
        ),
    ];
    let mut problems = Vec::new();
    for (row, shell, limit, primary, chains_too) in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let started = std::rc::Rc::new(std::cell::Cell::new(false));
        let measured: std::rc::Rc<std::cell::Cell<Option<u64>>> = std::rc::Rc::default();
        let before = started.clone();
        let _before = install_git_hook_for_test(GitHookPointV1::BeforeFinalChild, move |event| {
            if event.label == "fsck --strict" {
                before.set(true);
            }
        });
        let (grown, length) = (started.clone(), measured.clone());
        let _grow = install_git_hook_for_test(GitHookPointV1::FinalDigestOpened, move |event| {
            if grown.get() && length.get().is_none() {
                length.set(Some(
                    std::fs::metadata(event.path)
                        .expect("a digested file")
                        .len(),
                ));
                let mut file = std::fs::OpenOptions::new()
                    .append(true)
                    .open(event.path)
                    .expect("the digested file");
                std::io::Write::write_all(&mut file, &vec![0_u8; 1 << 20]).expect("the growth");
            }
        });
        let route = RouteV1::new(&[("fsck --strict", &final_only(shell))]);
        let deadline = limit.map_or_else(far_deadline, |limit| Instant::now() + limit);
        let ran = run_plane(input, &route, deadline);
        let (Some(length), Err(failure)) = (measured.get(), &ran.outcome) else {
            problems.push(format!("{row}: no file grew, or the run succeeded"));
            continue;
        };
        let want = format!(
            "{} bytes were read, and the census measured {length}",
            length + 1
        );
        let reconcile = |r: &GitBootstrapErrorV1| {
            matches!(r, GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::IdentityChanged(detail))
                if detail.contains(&want))
        };
        let judged = if chains_too {
            combined_with(&failure.cause, primary, |r| {
                combined_with(r, reconcile, is_identity_changed)
            })
        } else {
            combined_with(&failure.cause, primary, reconcile)
        };
        if !judged {
            problems.push(format!("{row}: {:?}", failure.cause));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

// ---------------------------------------------------------------------------------------------
// Drift between the final children and inside their callbacks stops the next child
// ---------------------------------------------------------------------------------------------

/// `error` is `check`'s refusal, either alone or as the failure a child met while the tree it left is ALSO
/// refused (the primary of the two kept failures).
fn beside(error: &GitBootstrapErrorV1, check: fn(&GitBootstrapErrorV1) -> bool) -> bool {
    check(error)
        || matches!(error, GitBootstrapErrorV1::ChildAndReconcile { primary, .. } if check(primary))
}

/// A final child is held to the retained tree at each of its three moments, and a swap at any of them stops
/// it: an entry planted before the second child's census, a directory swapped before the third's, a swap in a
/// pre-spawn callback (the child never starts), a swap in a post-exit callback (it ran, and its result is
/// refused), and a link planted in a pre-spawn callback. Each is typed, no later child starts, the proofs
/// recorded are exactly the ones that returned, `Config` is the last completed step, and the ledger is the
/// clean run's.
#[test]
fn b2c_drift_between_the_final_children_and_in_their_callbacks_stops_the_next_child() {
    struct RowV1 {
        name: &'static str,
        point: GitHookPointV1,
        label: &'static str,
        act: fn(&Path, &Path),
        check: fn(&GitBootstrapErrorV1) -> bool,
        children: usize,
        recorded: usize,
    }
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let rows = [
        RowV1 {
            name: "an entry planted before the second child's census",
            point: GitHookPointV1::BeforeFinalChildCensus,
            label: "rev-list --missing=print",
            act: |root, _| {
                std::fs::write(root.join("repository/.git/stray"), b"x").expect("a stray");
            },
            check: |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
            children: 7,
            recorded: 1,
        },
        RowV1 {
            name: "a same-length change to HEAD before the second child's census",
            point: GitHookPointV1::BeforeFinalChildCensus,
            label: "rev-list --missing=print",
            act: |root, _| change_in_place(&root.join("repository/.git/HEAD")),
            check: |e| tree_fault(e, FinalTreeFaultV1::Bytes),
            children: 7,
            recorded: 1,
        },
        RowV1 {
            name: "a same-length change to the pack before the third child's census",
            point: GitHookPointV1::BeforeFinalChildCensus,
            label: "fsck --strict",
            act: |root, _| change_in_place(&pack_file(&root.join("repository/.git"))),
            check: |e| tree_fault(e, FinalTreeFaultV1::Bytes),
            children: 8,
            recorded: 2,
        },
        RowV1 {
            name: "a directory swapped before the third child's census",
            point: GitHookPointV1::BeforeFinalChildCensus,
            label: "fsck --strict",
            act: |root, outside| swap_directory(&root.join("repository/.git/refs"), outside),
            check: is_identity_changed,
            children: 8,
            recorded: 2,
        },
        RowV1 {
            name: "a swap in a pre-spawn callback",
            point: GitHookPointV1::BeforeFinalChild,
            label: "fsck --strict",
            act: |root, outside| {
                swap_directory(&root.join("repository/.git/objects/info"), outside);
            },
            check: |e| beside(e, is_identity_changed),
            children: 8,
            recorded: 2,
        },
        RowV1 {
            name: "a link planted in a pre-spawn callback",
            point: GitHookPointV1::BeforeFinalChild,
            label: "rev-list --missing=print",
            act: |root, outside| replace_with_link(&root.join("repository/.git/HEAD"), outside),
            check: |e| beside(e, symlink_refused),
            children: 7,
            recorded: 1,
        },
        RowV1 {
            name: "a swap in the first child's post-exit callback",
            point: GitHookPointV1::AfterFinalChild,
            label: "cat-file --batch-all-objects",
            act: |root, outside| swap_directory(&root.join("repository/.git/refs/heads"), outside),
            check: |e| beside(e, is_identity_changed),
            children: 7,
            recorded: 0,
        },
        RowV1 {
            name: "a swap in the last child's post-exit callback",
            point: GitHookPointV1::AfterFinalChild,
            label: "fsck --strict",
            act: |root, outside| swap_directory(&root.join("repository/.git/logs"), outside),
            check: |e| beside(e, is_identity_changed),
            children: 9,
            recorded: 2,
        },
    ];
    let mut problems = Vec::new();
    for row in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (_area, outside) = external_dir_with(&["decoy"]);
        let root = input.dest.path.clone();
        let (label, act) = (row.label, row.act);
        let _hook = install_git_hook_for_test(row.point, move |event| {
            if event.label == label {
                act(&root, &outside);
            }
        });
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let Err(failure) = &ran.outcome else {
            problems.push(format!("{}: a success", row.name));
            continue;
        };
        let mut judged = Vec::new();
        if !(row.check)(&failure.cause) {
            judged.push(format!("cause {:?}", failure.cause));
        }
        if route.children().len() != row.children {
            judged.push(format!("children {:?}", route.children()));
        }
        if failure.partial.final_runs.len() != row.recorded {
            judged.push(format!("{} proofs", failure.partial.final_runs.len()));
        }
        if failure.last_completed != Some(GitPlaneStepV1::Config)
            || !failure.active_materialization_began
        {
            judged.push(format!("completed {:?}", failure.last_completed));
        }
        if failure.ledger_used != clean.ledger {
            judged.push(format!("ledger {}", failure.ledger_used));
        }
        if !judged.is_empty() {
            problems.push(format!("{}: {}", row.name, judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// A behavior-affecting entry planted inside the final repository where Git would look for it (the hidden
/// `.gitconfig` HOME aliases, the `git/config` XDG alias, a hook, a `config.worktree`, an `info/attributes`
/// filter, an `index` for the fsmonitor token) is an entry the restore did not make: the census refuses it
/// BEFORE the next child starts, so no child ever reads or runs it, and its marker stays absent.
#[test]
fn b2c_a_planted_config_hook_or_filter_inside_the_repository_is_refused_before_any_child_reads_it()
{
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    type PlantV2 = fn(&Path, &Path);
    let rows: [(&str, PlantV2); 5] = [
        ("a hidden gitconfig (HOME)", |git, marker| {
            std::fs::write(
                git.join(".gitconfig"),
                format!("[core]\n\tfsmonitor = touch {}\n", marker.display()),
            )
            .expect("a planted config");
        }),
        ("git/config (XDG)", |git, marker| {
            std::fs::create_dir(git.join("git")).expect("an xdg directory");
            std::fs::write(
                git.join("git/config"),
                format!("[core]\n\tfsmonitor = touch {}\n", marker.display()),
            )
            .expect("a planted config");
        }),
        ("a hook", |git, marker| {
            std::fs::create_dir(git.join("hooks")).expect("hooks");
            std::fs::write(
                git.join("hooks/reference-transaction"),
                format!("#!/bin/sh\ntouch {}\n", marker.display()),
            )
            .expect("a hook");
        }),
        ("config.worktree", |git, marker| {
            std::fs::write(
                git.join("config.worktree"),
                format!("[core]\n\tfsmonitor = touch {}\n", marker.display()),
            )
            .expect("a planted config");
        }),
        ("info/attributes", |git, marker| {
            std::fs::write(
                git.join("objects/info/attributes"),
                format!("* filter=x\n# {}\n", marker.display()),
            )
            .expect("planted attributes");
        }),
    ];
    for (row, plant) in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (_area, outside) = external_dir_with(&[]);
        let marker = outside.join("MARKER-RAN");
        let git = input.dest.path.join("repository/.git");
        let planted_marker = marker.clone();
        let _hook =
            install_git_hook_for_test(GitHookPointV1::BeforeFinalChildCensus, move |event| {
                if event.label == "cat-file --batch-all-objects" {
                    plant(&git, &planted_marker);
                }
            });
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let failure = ran.failure(row);
        assert!(
            tree_fault(&failure.cause, FinalTreeFaultV1::Unexpected),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(route.children().len(), 6, "{row}: no final child started");
        assert!(failure.partial.final_runs.is_empty(), "{row}");
        assert!(!exists(&marker), "{row}: the marker stays absent");
        assert_eq!(
            failure.last_completed,
            Some(GitPlaneStepV1::Config),
            "{row}"
        );
    }
}

// ---------------------------------------------------------------------------------------------
// Typed failure steps and the partial state they leave
// ---------------------------------------------------------------------------------------------

struct StepRowV1 {
    name: &'static str,
    completed: Option<GitPlaneStepV1>,
    began: bool,
    /// Pass A's value is retained (it succeeded).
    bootstrap: bool,
    objects: &'static str,
    metadata: &'static str,
    cause: fn(&GitBootstrapErrorV1) -> bool,
    /// What the partial state must leave on disk.
    disk: fn(&DestV1) -> bool,
}

/// One failing wrapper run, with the seams it needs alive until it ends.
fn failing_run(
    name: &str,
    capsule: &CustomCapsuleV1,
) -> (PlaneRunV1, RouteV1, Vec<GitSeamGuardV1>) {
    let caller = CustodyGitObjectFormatV1::Sha1;
    let mut input = PlaneInV1::rich(capsule, caller);
    let root = input.dest.path.clone();
    let git = root.join("repository/.git");
    let mut guards = Vec::new();
    let mut rules: Vec<(&str, String)> = Vec::new();
    match name {
        "a wrong object format" => input.format = GitObjectFormatV1::Sha256,
        "a planted bootstrap slot" => {
            std::fs::write(root.join(".restore-work/home"), b"planted").expect("a planted slot");
        }
        "a failed index-pack" => {
            rules.push((
                "index-pack --strict --stdin",
                "cat > /dev/null; exit 1".into(),
            ));
        }
        "a failed inventory" => {
            rules.push((
                "cat-file --batch-all-objects",
                "\"$REAL\" \"$@\"; exit 2".into(),
            ));
        }
        "a failed closure" => rules.push(("rev-list --objects", "cat > /dev/null; exit 1".into())),
        "a failed fsck" => rules.push(("fsck --strict", "exit 1".into())),
        "a bootstrap tree changed before its closing gate" => {
            let stray = root.join(".restore-work/git-bootstrap/stray");
            guards.push(install_git_hook_for_test(
                GitHookPointV1::BeforeFinalGate,
                move |_| std::fs::write(&stray, b"x").expect("a stray"),
            ));
        }
        "an Empty refs class" => input = PlaneInV1::frameless(capsule, caller),
        "a collision at HEAD" => {
            let head = git.join("HEAD");
            guards.push(install_git_hook_for_test(
                GitHookPointV1::BeforeObjectCreate,
                move |event| {
                    if event.label == "file" && event.path == head {
                        std::fs::write(&head, b"planted").expect("a planted HEAD");
                    }
                },
            ));
        }
        "a restored ref changed before it is read back" => {
            let target = git.join("refs/heads/main");
            guards.push(install_git_hook_for_test(
                GitHookPointV1::DeadlineObserved,
                move |event| {
                    if event.label == "metadata-refs" {
                        change_in_place(&target);
                    }
                },
            ));
        }
        "a collision at the config" => {
            let config = git.join("config");
            guards.push(install_git_hook_for_test(
                GitHookPointV1::BeforeObjectCreate,
                move |event| {
                    if event.label == "file" && event.path == config {
                        std::fs::write(&config, b"planted").expect("a planted config");
                    }
                },
            ));
        }
        "a failed final proof" => rules.push(("fsck --strict", final_only("exit 1"))),
        other => panic!("no such row: {other}"),
    }
    let rule_refs: Vec<(&str, &str)> = rules
        .iter()
        .map(|(needle, shell)| (*needle, shell.as_str()))
        .collect();
    let route = RouteV1::new(&rule_refs);
    let ran = run_plane(input, &route, far_deadline());
    (ran, route, guards)
}

/// EVERY step of phase G is reported as the last one completed whole, and only once it is whole: a failure
/// at each next step names the previous one. Admission (an object format the capsule contradicts) completes
/// nothing; then the bootstrap slots (`Admission`), init (`BootstrapInit`), indexing (`Indexing`), the
/// inventory (`Inventory`), closure (`Closure`), fsck and the bootstrap's closing gate (`Fsck`), the
/// prevalidations (`BootstrapGate`), the object copy (`Objects`), the metadata (`Metadata`), the refs
/// agreement (`Refs`), and the final proof and gate (`Config`; `FinalGate` is only a success). Each row also
/// shows whether materialization began, which retained values the failure carries, and what stays on disk.
#[test]
fn b2c_the_last_completed_step_and_the_partial_state_are_typed_at_every_step() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let rows = [
        StepRowV1 {
            name: "a wrong object format",
            completed: None,
            began: false,
            bootstrap: false,
            objects: "not started",
            metadata: "not started",
            cause: |e| matches!(e, GitBootstrapErrorV1::FormatMismatch(_)),
            disk: |dest| dest.entries() == [".restore-work"] && dest.work_entries() == ["plain"],
        },
        StepRowV1 {
            name: "a planted bootstrap slot",
            completed: Some(GitPlaneStepV1::Admission),
            began: false,
            bootstrap: false,
            objects: "not started",
            metadata: "not started",
            cause: |e| {
                matches!(
                    e,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { .. })
                )
            },
            disk: |dest| {
                std::fs::read(dest.work().join("home")).is_ok_and(|bytes| bytes == b"planted")
            },
        },
        StepRowV1 {
            name: "a failed index-pack",
            completed: Some(GitPlaneStepV1::BootstrapInit),
            began: false,
            bootstrap: false,
            objects: "not started",
            metadata: "not started",
            cause: |e| matches!(e, GitBootstrapErrorV1::StrictPack(_)),
            disk: |dest| exists(&dest.bootstrap().join("HEAD")),
        },
        StepRowV1 {
            name: "a failed inventory",
            completed: Some(GitPlaneStepV1::Indexing),
            began: false,
            bootstrap: false,
            objects: "not started",
            metadata: "not started",
            cause: |e| is_git_child(e, "cat-file --batch-all-objects", 2),
            disk: |dest| listing(&dest.bootstrap().join("objects/pack")).len() == 3,
        },
        StepRowV1 {
            name: "a failed closure",
            completed: Some(GitPlaneStepV1::Inventory),
            began: false,
            bootstrap: false,
            objects: "not started",
            metadata: "not started",
            cause: |e| is_git_child(e, "rev-list --missing=print", 1),
            disk: |dest| listing(&dest.bootstrap().join("objects/pack")).len() == 3,
        },
        StepRowV1 {
            name: "a failed fsck",
            completed: Some(GitPlaneStepV1::Closure),
            began: false,
            bootstrap: false,
            objects: "not started",
            metadata: "not started",
            cause: |e| is_git_child(e, "fsck --strict", 1),
            disk: |dest| listing(&dest.bootstrap().join("objects/pack")).len() == 3,
        },
        StepRowV1 {
            name: "a bootstrap tree changed before its closing gate",
            completed: Some(GitPlaneStepV1::Fsck),
            began: false,
            bootstrap: false,
            objects: "not started",
            metadata: "not started",
            cause: |e| matches!(e, GitBootstrapErrorV1::UnexpectedEntry { .. }),
            disk: |dest| exists(&dest.bootstrap().join("stray")),
        },
        StepRowV1 {
            name: "an Empty refs class",
            completed: Some(GitPlaneStepV1::BootstrapGate),
            began: false,
            bootstrap: true,
            objects: "not started",
            metadata: "not started",
            cause: |e| matches!(e, GitBootstrapErrorV1::EmptyRefsAndHead),
            disk: |dest| dest.entries() == [".restore-work"],
        },
        StepRowV1 {
            name: "a collision at HEAD",
            completed: Some(GitPlaneStepV1::Objects),
            began: true,
            bootstrap: true,
            objects: "whole",
            metadata: "refused",
            cause: |e| {
                matches!(
                    e,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { .. })
                )
            },
            disk: |dest| {
                std::fs::read(dest.path.join("repository/.git/HEAD"))
                    .is_ok_and(|bytes| bytes == b"planted")
                    && listing(&pack_directory(dest)).len() == 3
                    && !exists(&dest.path.join("repository/.git/config"))
            },
        },
        StepRowV1 {
            name: "a restored ref changed before it is read back",
            completed: Some(GitPlaneStepV1::Metadata),
            began: true,
            bootstrap: true,
            objects: "whole",
            metadata: "refused",
            cause: |e| matches!(e, GitBootstrapErrorV1::MetadataCopy { .. }),
            disk: |dest| {
                exists(&dest.path.join("repository/.git/refs/heads/main"))
                    && !exists(&dest.path.join("repository/.git/config"))
            },
        },
        StepRowV1 {
            name: "a collision at the config",
            completed: Some(GitPlaneStepV1::Refs),
            began: true,
            bootstrap: true,
            objects: "whole",
            metadata: "refused",
            cause: |e| {
                matches!(
                    e,
                    GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::StagingCollision { .. })
                )
            },
            disk: |dest| {
                std::fs::read(dest.path.join("repository/.git/config"))
                    .is_ok_and(|bytes| bytes == b"planted")
            },
        },
        StepRowV1 {
            name: "a failed final proof",
            completed: Some(GitPlaneStepV1::Config),
            began: true,
            bootstrap: true,
            objects: "whole",
            metadata: "whole",
            cause: |e| is_git_child(e, "fsck --strict", 1),
            disk: |dest| {
                std::fs::read(dest.path.join("repository/.git/config"))
                    .is_ok_and(|bytes| bytes == golden_config(GitObjectFormatV1::Sha1))
            },
        },
    ];
    let mut problems = Vec::new();
    for row in rows {
        let (ran, _route, _guards) = failing_run(row.name, &capsule);
        let Err(failure) = &ran.outcome else {
            problems.push(format!("{}: a success", row.name));
            continue;
        };
        let mut judged = Vec::new();
        if !(row.cause)(&failure.cause) {
            judged.push(format!("cause {:?}", failure.cause));
        }
        if failure.last_completed != row.completed {
            judged.push(format!("completed {:?}", failure.last_completed));
        }
        if failure.active_materialization_began != row.began {
            judged.push(format!("began {}", failure.active_materialization_began));
        }
        if failure.partial.bootstrap.is_some() != row.bootstrap {
            judged.push("the bootstrap value".to_owned());
        }
        if objects_kind(&failure.partial.objects) != row.objects
            || metadata_kind(&failure.partial.metadata) != row.metadata
        {
            judged.push(format!(
                "objects {}, metadata {}",
                objects_kind(&failure.partial.objects),
                metadata_kind(&failure.partial.metadata)
            ));
        }
        if !(row.disk)(&ran.dest) {
            judged.push("the partial bytes are not on disk".to_owned());
        }
        // Before pass A's first write the one ledger is exactly phase V's.
        if (row.name == "a wrong object format" || row.name == "a planted bootstrap slot")
            && failure.ledger_used != ran.phase_v
        {
            judged.push(format!(
                "ledger {} not {}",
                failure.ledger_used, ran.phase_v
            ));
        }
        ran.assert_one_ledger(row.name);
        if !judged.is_empty() {
            problems.push(format!("{}: {}", row.name, judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// A refused invocation leaves its created bytes, and a second phase V over the same destination refuses
/// without touching them: dropping the failure (and with it every retained descriptor) removes nothing, and
/// nothing is renamed, overwritten, or cleaned up.
#[test]
fn b2c_a_refused_second_invocation_cannot_overwrite_the_first_partial_state() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let (ran, _route, _guards) = failing_run("a failed final proof", &capsule);
    assert!(ran.failure("a late failure").partial.bootstrap.is_some());
    let before = snapshot(&ran.dest.path);
    assert!(before.contains_key("repository/.git/config"));
    assert!(before.contains_key(".restore-work/git-bootstrap/HEAD"));
    let PlaneRunV1 { dest, outcome, .. } = ran;
    drop(outcome);
    assert_eq!(
        snapshot(&dest.path),
        before,
        "dropping the failure removes nothing"
    );
    let second = verify_and_stage_v1(
        &capsule.capsule,
        &dest.path,
        CustodyRestoreBudgetV1::ceiling(),
        frame_budget(),
        &FixtureOpenerV1::honest(),
    );
    assert!(
        matches!(second, Err(CustodyRestoreErrorV1::DestinationInvalid(_))),
        "{second:?}"
    );
    assert_eq!(
        snapshot(&dest.path),
        before,
        "the partial state is byte-identical"
    );
}

// ---------------------------------------------------------------------------------------------
// The closed environment: nothing ambient or external reaches the final children
// ---------------------------------------------------------------------------------------------

const B2C_AMBIENT_CHILD_V1: &str = "A2A_B2C_AMBIENT_CHILD";

/// The body that runs inside a re-executed test binary whose process environment carries planted `GIT_*`,
/// `HOME`, and `XDG_CONFIG_HOME` state that names a hostile external configuration (an fsmonitor, a hooks
/// path, an include, a filter, a remote, a ssh command, an exec path), a hostile external hooks directory, and
/// a removed source. In an ordinary run it does nothing; the parent control below requires the marker only
/// the planted run prints.
#[test]
fn b2c_ambient_environment_child() {
    if std::env::var_os(B2C_AMBIENT_CHILD_V1).is_none() {
        return;
    }
    use std::os::unix::fs::PermissionsExt as _;
    // Every fixture is built BEFORE anything hostile is planted, and each capsule's source is removed.
    let mut cases = Vec::new();
    for (cformat, rich) in [
        (CustodyGitObjectFormatV1::Sha1, true),
        (CustodyGitObjectFormatV1::Sha256, false),
    ] {
        let capsule = if rich {
            captured(cformat)
        } else {
            empty(cformat)
        };
        let input = if rich {
            PlaneInV1::rich(&capsule, cformat)
        } else {
            PlaneInV1::unborn(&capsule, cformat)
        };
        std::fs::remove_dir_all(&capsule.source.git_dir).expect("the source is removed");
        cases.push((cformat, capsule, input));
    }
    let (_area, external) = external_dir_with(&[]);
    let hook = external.join("hook.sh");
    let marker = |name: &str| external.join(format!("MARKER-{name}"));
    std::fs::write(
        &hook,
        format!("#!/bin/sh\ntouch '{}'\n", marker("hook").display()),
    )
    .expect("the hostile hook");
    std::fs::set_permissions(&hook, std::fs::Permissions::from_mode(0o755)).expect("a mode");
    std::fs::create_dir(external.join("hooks")).expect("hooks");
    for name in ["reference-transaction", "post-checkout", "pre-commit"] {
        let script = external.join("hooks").join(name);
        std::fs::write(
            &script,
            format!("#!/bin/sh\ntouch '{}'\n", marker(name).display()),
        )
        .expect("a hostile hook");
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755)).expect("a mode");
    }
    std::fs::write(
        external.join("more.gitconfig"),
        format!("[core]\n\tfsmonitor = {}\n", hook.display()),
    )
    .expect("an included config");
    let config = format!(
        "[core]\n\tfsmonitor = {hook}\n\thooksPath = {hooks}\n\tsshCommand = {hook}\n\tpager = {hook}\n\teditor = {hook}\n\
         [include]\n\tpath = {more}\n\
         [filter \"x\"]\n\tclean = {hook}\n\tsmudge = {hook}\n\tprocess = {hook}\n\
         [remote \"origin\"]\n\turl = {external}/nowhere.git\n\
         [protocol]\n\tallow = always\n",
        hook = hook.display(),
        hooks = external.join("hooks").display(),
        more = external.join("more.gitconfig").display(),
        external = external.display(),
    );
    std::fs::write(external.join(".gitconfig"), &config).expect("the hostile config");
    let external_text = external.display().to_string();
    let planted = [
        ("GIT_DIR", format!("{external_text}/nonexistent-git-dir")),
        ("GIT_OBJECT_DIRECTORY", format!("{external_text}/objects")),
        (
            "GIT_ALTERNATE_OBJECT_DIRECTORIES",
            format!("{external_text}/alternates"),
        ),
        ("GIT_INDEX_FILE", format!("{external_text}/index")),
        ("GIT_WORK_TREE", format!("{external_text}/worktree")),
        ("GIT_CONFIG_COUNT", "1".to_owned()),
        ("GIT_CONFIG_KEY_0", "core.fsmonitor".to_owned()),
        ("GIT_CONFIG_VALUE_0", hook.display().to_string()),
        ("GIT_CONFIG_GLOBAL", format!("{external_text}/.gitconfig")),
        ("GIT_CONFIG_SYSTEM", format!("{external_text}/.gitconfig")),
        ("GIT_EXEC_PATH", format!("{external_text}/bin")),
        ("GIT_SSH_COMMAND", hook.display().to_string()),
        ("GIT_ASKPASS", hook.display().to_string()),
        ("GIT_EXTERNAL_DIFF", hook.display().to_string()),
        ("GIT_PAGER", hook.display().to_string()),
        ("HOME", external_text.clone()),
        ("XDG_CONFIG_HOME", external_text.clone()),
    ];
    for (key, value) in &planted {
        std::env::set_var(key, value);
    }
    for (cformat, _capsule, input) in cases {
        let route = RouteV1::new(&[(
            "fsck --strict",
            &final_only("env | sort > \"$LOGFILE.env\"; exec \"$REAL\" \"$@\""),
        )]);
        let ran = run_plane(input, &route, far_deadline());
        let row = format!("{cformat:?}");
        let plane = ran.success(&row);
        assert_clean_plane(&ran, plane, &row);
        let env = std::fs::read_to_string(format!("{}.env", route.log.display()))
            .expect("the final fsck's environment log");
        assert!(
            !env.contains(&external_text),
            "{row}: an ambient value reached the final child:\n{env}"
        );
        assert!(env.contains("GIT_DIR=.git"), "{row}: {env}");
        assert!(
            env.contains("HOME=.git") && env.contains("XDG_CONFIG_HOME=.git"),
            "{row}: {env}"
        );
        assert!(env.contains("GIT_CONFIG_GLOBAL=/dev/null"), "{row}: {env}");
        assert!(env.contains("GIT_CONFIG_NOSYSTEM=1"), "{row}: {env}");
        for key in [
            "GIT_OBJECT_DIRECTORY",
            "GIT_ALTERNATE_OBJECT_DIRECTORIES",
            "GIT_INDEX_FILE",
            "GIT_WORK_TREE",
            "GIT_CONFIG_COUNT",
            "GIT_CONFIG_SYSTEM",
            "GIT_EXEC_PATH",
            "GIT_SSH_COMMAND",
            "GIT_ASKPASS",
            "GIT_EXTERNAL_DIFF",
            "GIT_PAGER",
        ] {
            assert!(
                !env.contains(&format!("{key}=")),
                "{row}: {key} reached the final child:\n{env}"
            );
        }
        for run in plane.closure.runs.iter().chain(&plane.bootstrap.runs) {
            assert!(
                !run.environment.contains_key("GIT_OBJECT_DIRECTORY"),
                "{row}"
            );
        }
        for name in [
            "hook",
            "reference-transaction",
            "post-checkout",
            "pre-commit",
        ] {
            assert!(!exists(&marker(name)), "{row}: the {name} marker ran");
        }
        assert_eq!(
            listing(&external)
                .iter()
                .filter(|name| name.starts_with("MARKER-"))
                .count(),
            0,
            "{row}: no marker of any kind"
        );
    }
    println!("B2C-AMBIENT-CHILD-OK");
}

#[test]
fn b2c_planted_ambient_home_includes_hooks_filters_fsmonitor_and_remotes_never_run() {
    if std::env::var_os(B2C_AMBIENT_CHILD_V1).is_some() {
        return;
    }
    let output = Command::new(std::env::current_exe().expect("the test binary"))
        .args([
            "custody_restore::git_tests::b2c_ambient_environment_child",
            "--exact",
            "--test-threads=1",
            "--nocapture",
        ])
        .env(B2C_AMBIENT_CHILD_V1, "1")
        .output()
        .expect("the ambient child runs");
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(
        output.status.success() && stdout.contains("B2C-AMBIENT-CHILD-OK"),
        "the ambient child failed:\n{stdout}\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
}

// ---------------------------------------------------------------------------------------------
// Structure: the wrapper's region runs Git children and gates the whole, and creates nothing itself
// ---------------------------------------------------------------------------------------------

/// STRUCTURAL ONLY. B2c's region (the production source from its marker on, up to the end of the file) is held
/// to its own vocabulary, because B2b's metadata scan now ends at this marker. It is the only caller of the
/// earlier helpers (each exactly once, in the documented order, each handed the caller's `deadline`), so
/// pass A's no-repository invariant stays function-scoped to the direct bootstrap (its own scan and the
/// filesystem rows above are unchanged). It runs only the three final read-only commands, rooted by the one
/// `GitRootNamesV1::new(".git", ".git", ".git")`; it never names `init`, `index-pack`, `verify-pack`, a
/// route, a walker, a path open, a rename, or `unsafe`; it creates, reserves, charges, and releases nothing
/// (the ledger is only READ for a figure); it never names the bootstrap; and it creates no instant of its
/// own: the one deadline is the only clock. The behavior is proven by the rows above, which run the code.
#[test]
fn b2c_the_final_region_names_only_the_final_vocabulary_and_the_split_is_unique() {
    let source = include_str!("custody_restore_git.rs");
    assert_eq!(source.matches(B2C_MARKER_V1).count(), 1, "one marker");
    assert_eq!(source.matches(B2B_MARKER_V1).count(), 1, "one B2b marker");
    let (before, region) = source.split_once(B2C_MARKER_V1).expect("the marker");
    assert!(before.contains(B2B_MARKER_V1), "B2c follows B2b");
    assert!(before.contains("pub(crate) fn materialize_active_metadata_bounded_v1("));
    assert!(region.contains("pub(crate) fn restore_git_plane_v1("));
    assert!(region.contains("pub(crate) fn restore_git_plane_bounded_v1("));
    assert!(
        !before.contains("restore_git_plane_v1(")
            && !before.contains("restore_git_plane_bounded_v1("),
        "the earlier passes do not call the wrapper"
    );
    let code: String = region
        .lines()
        .filter(|line| !line.trim_start().starts_with("//"))
        .collect::<Vec<_>>()
        .join("\n");
    // The final sweep of the retained chains is the one function that rechecks the bootstrap's own entry (it is
    // the final gates' copy of the earlier sweep, with a clock after each read): the bootstrap's name is held
    // out of every OTHER function, and everything else is forbidden in it too.
    let sweep_source = body_of(source, "fn final_sweep_chains(");
    let sweep_code: String = sweep_source
        .lines()
        .filter(|line| !line.trim_start().starts_with("//"))
        .collect::<Vec<_>>()
        .join("\n");
    let others = code.replacen(&sweep_code, "", 1);
    assert!(others.len() < code.len(), "the sweep is in the region");
    let forbidden_names: &[&str] = &[
        "std::fs",
        "File::open(",
        "OpenOptions",
        "read_dir(",
        "GitObjectStoreRouteV1",
        "remeasure_git_directory",
        "measure_git_directory",
        "walk",
        "Command::new",
        "spawn",
        "std::process",
        "mkdir",
        "rename",
        "remove_file",
        "remove_dir",
        "unlink",
        "set_len",
        "truncate",
        "hard_link",
        "symlink(",
        "set_permissions",
        "unsafe",
        "WorkV1",
        "OwnedChargeV1",
        "settle_to",
        "ReservedPairV1",
        "InitBare",
        "IndexPackStrictStdin",
        "VerifyPack",
        "PackObjectsStdout",
        "LsFilesStageZ",
        "CatFileBatchCheck",
        "create_staging_directory",
        "create_output_file",
        "create_new",
        "reserve(",
        "reserve_entries(",
        "release(",
        "write_all",
        "write_step(",
        "BOOTSTRAP_NAME_V1",
        "git-bootstrap",
        "Instant::now",
        "Duration",
        "try_clone(",
        "\"HEAD\"",
        "\"config\"",
    ];
    for forbidden in forbidden_names {
        assert!(
            !others.contains(forbidden),
            "the final region mentions `{forbidden}`"
        );
        if !["BOOTSTRAP_NAME_V1", "git-bootstrap"].contains(forbidden) {
            assert!(
                !sweep_code.contains(forbidden),
                "the final sweep mentions `{forbidden}`"
            );
        }
    }
    // The ledger is only READ, for a figure (a field named `ledger_used` is that figure, not the ledger).
    let reads = code.matches(".ledger.borrow().used()").count();
    assert!(reads >= 1, "the figure is read");
    for (at, _) in code.match_indices(".ledger") {
        assert!(
            code[at..].starts_with(".ledger.borrow().used()")
                || code[at..].starts_with(".ledger_used"),
            "every ledger access is a read of the figure: `{}`",
            &code[at..(at + 40).min(code.len())]
        );
    }
    // The final root: the one set of names, and the three read-only commands.
    assert_eq!(
        code.matches("GitRootNamesV1::new(\".git\", \".git\", \".git\")")
            .count(),
        1,
        "one root"
    );
    for required in [
        "GitCommandV1::CatFileAllObjects",
        "GitCommandV1::RevListMissingPrint",
        "GitCommandV1::FsckStrict",
        "GitRunRequestV1::new(",
        "compare_inventory(",
        "compare_closure(",
        "classify_fsck(",
        "require_success(",
        "stream_digest(",
        "require_measured_file(",
        "refuse_mounts_within(",
        "final_sweep_chains(",
        "output_chains(",
        "final_source_files_unchanged(",
        "observe_deadline(",
        "recheck_regular_entry(",
        "recheck_entry(",
        "observed_stat(",
    ] {
        assert!(
            code.contains(required),
            "the final region lacks `{required}`"
        );
    }
    // The final stage's own helpers are CALLED (a definition alone would satisfy the names above), and the
    // census reads every fact it records through the stalled-clock seam (the file's, the repository's, each
    // directory's).
    for (name, at_least) in [
        ("final_sweep_chains(", 2),
        ("final_source_files_unchanged(", 2),
        ("observed_stat(", 2),
    ] {
        assert!(
            code.matches(name).count() >= at_least,
            "the final region uses `{name}` at least {at_least} times"
        );
    }
    // The census's two recording units (a directory's `fstat`, the repository's included, and a file's descriptor)
    // each read what they record through the stalled-clock seam.
    for unit in ["fn census_stat(", "fn census_file("] {
        assert!(
            body_of(source, unit).contains("observed_stat("),
            "`{unit}` records a fact without the stalled-clock seam"
        );
    }
    // The wrapper calls each earlier helper exactly once, in the documented order, with the one deadline.
    let order = [
        "bootstrap_git_objects_v1(",
        "prevalidate_active_frames_bounded_v1(",
        "agree_active_refs_bounded_v1(",
        "materialize_object_store_v1(",
        "materialize_active_metadata_bounded_v1(",
    ];
    let mut at = 0;
    for call in order {
        assert_eq!(code.matches(call).count(), 1, "{call} is called once");
        let found = code.find(call).expect("the call");
        assert!(found > at, "{call} follows the earlier helpers");
        at = found;
        let arguments = &code[found..(found + 360).min(code.len())];
        assert!(
            arguments.contains("deadline"),
            "{call} is handed the caller's deadline"
        );
    }
    // The caller's bounds reach every helper that applies them.
    let wrapper = body_of(source, "pub(crate) fn restore_git_plane_bounded_v1(");
    assert_eq!(
        wrapper.matches("table_bound").count(),
        3,
        "the parameter, B1a, and B2b"
    );
    assert_eq!(
        wrapper.matches("limits").count(),
        3,
        "the parameter, B1b, and B2b"
    );
    assert_eq!(
        wrapper.matches("frame_budget").count(),
        4,
        "the parameter, B1a, B1b, and B2b"
    );
}

/// STRUCTURAL ONLY (it reads the production source, so it is evidence of order and shape, never of behavior;
/// the behavioral evidence is every row above). The final stage's order is fixed in the source: the closing
/// gate is the clock, the mount census, the census of the exact tree, the digest of every restored file, and
/// then the sweep of every retained chain as its TAIL expression, whose own last statements are the guard and
/// the root's identity (the last fallible call, with only a tail expression after it); the retained chains
/// are the output chains, the metadata chains, the admitted source files, and the sweep, in that order; every
/// success-eligible bracket of a final child is held to the one deadline (the baseline's census and digests
/// then a guard before the runner, both runner callbacks and a child's success arm through the one deadline
/// gate, the settlement's census and digests on the pace its verdict chose), and the ONLY clock-free pace in
/// the final region is the reconciliation of a child whose failure is already known; nothing fallible follows
/// the closing gate but infallible construction; and the wrapper builds its success value infallibly. (Before
/// source round 3 this row asserted the opposite of the callbacks: "the runner callbacks' gate is not held to
/// the deadline". That was the defect, restated as a scan.)
#[test]
fn b2c_the_final_gate_order_is_fixed_in_the_source() {
    let source = include_str!("custody_restore_git.rs");
    let at = |body: &str, needle: &str| {
        body.find(needle)
            .unwrap_or_else(|| panic!("`{needle}` is in `{body}`"))
    };

    let closing = body_of(source, "fn proof_closing_gate(");
    let order = [
        at(closing, "observe_deadline("),
        at(closing, "refuse_mounts_within("),
        at(closing, "self.proof_measure("),
        at(closing, "self.proof_digests("),
        at(closing, "self.proof_chains("),
    ];
    assert!(order.windows(2).all(|pair| pair[0] < pair[1]), "{order:?}");
    assert!(
        !closing[order[4]..].contains(';'),
        "the sweep of every retained chain is the closing gate's tail expression"
    );

    let chains = body_of(source, "fn proof_chains(");
    let order = [
        at(chains, "output_chains("),
        at(chains, "recheck_regular_entry("),
        at(chains, "final_source_files_unchanged("),
        at(chains, "final_sweep_chains("),
    ];
    assert!(order.windows(2).all(|pair| pair[0] < pair[1]), "{order:?}");
    assert!(
        !chains[order[3]..].contains(';'),
        "the sweep, whose last statement before the root's identity is its guard, is the tail expression"
    );

    // ONE gate, always held to the deadline: its entry guard, then the mount census, then every chain on the same
    // pace. A child's success arm and BOTH runner callbacks run it, and there is no gate that is not held to the
    // deadline.
    let gate = body_of(source, "fn proof_deadline_gate(");
    let order = [
        at(gate, "observe_deadline("),
        at(gate, "refuse_mounts_within("),
        at(gate, "self.proof_chains("),
    ];
    assert!(order.windows(2).all(|pair| pair[0] < pair[1]), "{order:?}");
    assert!(
        !source.contains("fn proof_gate(") && !source.contains("self.proof_gate()"),
        "no gate escapes the deadline"
    );
    let child = body_of(source, "fn proof_child<");
    assert!(
        child.contains("match this.proof_deadline_gate("),
        "both runner callbacks run the deadline gate"
    );
    // The baseline is held to the same deadline: its census and digests on the one pace, and a guard before the
    // runner (a filesystem call of its own) is called.
    let order = [
        at(child, "self.proof_measure(&pace)"),
        at(child, "self.proof_digests(&baseline, &pace)"),
        at(child, "\"final-baselined\""),
        at(child, "runner.run("),
    ];
    assert!(order.windows(2).all(|pair| pair[0] < pair[1]), "{order:?}");
    assert!(
        !child.contains("unpaced"),
        "no step of a child's bracket leaves the clock out"
    );
    // The settlement of a result that is about to be a success is paced and bound to the deadline and ends in
    // the success gate; it never leaves the clock out. EVERY failure of a final child (one that is already known:
    // a runner error, a callback refusal, a nonzero status, a parser refusal; and one that becomes known inside
    // the paced settlement, the typed timeout or a custody finding) enters ONE failure-only completion, at ONE
    // call site, after the paced settlement or a known verdict, and the verdict's value is returned only after
    // the paced settlement and its gate succeeded. (Design follow-on 1: before it, a non-timeout paced finding
    // was returned alone, and the timeout was one of two call sites.)
    let settle = body_of(source, "fn proof_settle<");
    assert_eq!(
        settle.matches("unpaced").count(),
        0,
        "the settlement itself never leaves the clock out"
    );
    assert_eq!(
        settle.matches("self.proof_reconcile(").count(),
        1,
        "every failure of a final child enters the one completion at ONE site"
    );
    let order = [
        at(settle, "self.proof_settle_paced("),
        at(settle, "return Ok(value)"),
        at(settle, "self.proof_reconcile("),
    ];
    assert!(order.windows(2).all(|pair| pair[0] < pair[1]), "{order:?}");
    let paced = body_of(source, "fn proof_settle_paced(");
    assert!(
        !paced.contains("unpaced") && !paced.contains("proof_reconcile"),
        "the paced settlement is held to the deadline and never completes"
    );
    let order = [
        at(paced, ".proof_census(&paced"),
        at(paced, "final_unchanged("),
        at(paced, ".proof_digests_counted("),
        at(paced, ".proof_deadline_gate("),
    ];
    assert!(order.windows(2).all(|pair| pair[0] < pair[1]), "{order:?}");
    assert!(
        !paced[order[3]..].contains(';'),
        "the success gate is the paced settlement's tail expression"
    );
    // The ONE failure-only completion: the mount census, then the exact tree and its comparison, then the digest
    // of every restored file by its RETAINED descriptor, then every retained chain (the destination root's
    // identity LAST), all on the one clock-free pace, with no gate, no runner, and no classifier in it, and a
    // return type that is a FAILURE: it cannot return a verified value.
    let reconcile = body_of(source, "fn proof_reconcile(");
    assert_eq!(
        reconcile.matches("&unpaced").count(),
        1,
        "one clock-free pace"
    );
    let order = [
        at(reconcile, "refuse_mounts_within("),
        at(reconcile, "self.proof_census(pace"),
        at(reconcile, "final_unchanged("),
        at(reconcile, "self.proof_retained_digests("),
        at(reconcile, "self.proof_chains(pace"),
    ];
    assert!(order.windows(2).all(|pair| pair[0] < pair[1]), "{order:?}");
    for forbidden in [
        "proof_deadline_gate",
        "runner",
        "classify",
        "observe_deadline",
        "Ok(value)",
        "self.proof_digests(",
        "proof_digests_counted",
    ] {
        assert!(
            !reconcile.contains(forbidden),
            "the failure-only helper mentions `{forbidden}`"
        );
    }
    let signature = &source[at(source, "fn proof_reconcile(")..];
    let signature = &signature[..at(signature, "{\n")];
    assert!(
        signature.contains("-> GitBootstrapErrorV1"),
        "the helper's result is a failure: {signature}"
    );
    // The digest of a restored file after a failure is known reads ONLY the descriptor the restore retained, at
    // explicit offsets (no seek of a shared cursor, no reopened name, no clone), bounded to its length plus one
    // byte, and never retries an interruption: it is an observation of one file's own descriptor and nothing else.
    let retained = body_of(source, "fn proof_retained_digest(");
    assert!(retained.contains("read_at("), "positioned reads");
    for forbidden in [
        "open_regular_file",
        "seek(",
        "Seek",
        "try_clone",
        "by_ref",
        "Interrupted",
        "continue",
        "observe_deadline",
        "Instant",
    ] {
        assert!(
            !retained.contains(forbidden),
            "the retained digest mentions `{forbidden}`"
        );
    }
    assert!(
        !source.contains("fn reconciling_digest(") && !source.contains("DigestBoundV1"),
        "no failure-only digest reopens a name or retries an interruption"
    );
    // Progress is kept CALL by call and never as one boolean for a class (follow-on 1 targeted repair): the
    // settlement's census is a resumable value the completion continues, the digest cursor carries the bytes a paced
    // read returned, a name refusal settles no digest (only a verdict about the original bytes does), and the
    // comparison with the baseline is unavailable after a finding.
    assert!(
        !source.contains("tree: Cell<bool>") && !source.contains("settled.tree"),
        "no stage-wide boolean stands for the whole census"
    );
    let census = body_of(source, "fn proof_census(");
    assert!(
        census.contains("if c.ended || c.finished") && census.contains("collect"),
        "the census is resumable and a completion collects each finding"
    );
    let digest = body_of(source, "fn proof_digest_file(");
    let read = at(digest, "seen.read.set(Some((read, sha256)))");
    assert!(
        at(digest, "stream_digest(") < read && read < at(digest, "pace(\"final-digest-read\")"),
        "the bytes a paced read returned are recorded before the guard that follows the read"
    );
    assert!(
        digest[..at(digest, "stream_digest(")]
            .matches("seen.settle()")
            .count()
            == 0,
        "a refusal of the name (the open, the binding fstat) settles no digest"
    );
    assert!(
        reconcile.contains("!settled.census.faulted"),
        "the comparison needs a complete census that found nothing"
    );
    assert!(
        child.contains("self.proof_settle(&baseline, label, verdict, beside, exit)"),
        "the child's bracket hands the settlement what its callbacks saw"
    );
    assert!(
        child.contains("is_final_gate_refusal("),
        "a callback's refusal replaces ONLY the route refusal this file made"
    );
    // The completion is the one site every failure enters; the observations are each a UNIT, a refusal of one
    // never ends the others (a completion's chains keep every refusal and the root is the last unit).
    let pass = body_of(source, "fn unit(");
    assert!(
        pass.contains("self.exhaustive"),
        "a completion's unit keeps its refusal and goes on"
    );
    let region = source.split_once(B2C_MARKER_V1).expect("the B2c marker").1;
    assert_eq!(
        region
            .lines()
            .filter(|line| !line.trim_start().starts_with("//"))
            .map(|line| line.matches("&unpaced").count())
            .sum::<usize>(),
        1,
        "the only unpaced pace in the final region is the known failure's reconciliation"
    );

    let prove = body_of(source, "fn proof_run(");
    let tail =
        &prove[at(prove, "self.proof_closing_gate()?;") + "self.proof_closing_gate()?;".len()..];
    assert!(
        !tail.contains('?'),
        "only infallible construction follows the closing gate"
    );
    let wrapper = body_of(source, "pub(crate) fn restore_git_plane_bounded_v1(");
    let success = &wrapper[at(wrapper, "Ok(RestoredGitPlaneV1 {")..];
    assert!(
        !success.contains('?'),
        "the success value is built infallibly"
    );
}

// ---------------------------------------------------------------------------------------------
// One ledger, retained descriptors, a spent deadline, and the device census
// ---------------------------------------------------------------------------------------------

/// The ONE ledger binds every helper and is never replenished: with exactly the headroom a clean run charges
/// (pass A's pins and children, the object copy, the metadata and config) the wrapper succeeds and uses all of
/// it, and with one byte less, or half, it refuses with the budget's typed refusal at the stage that needs
/// the missing byte, before any final child, with the one figure unchanged by the refusal. A second ledger,
/// a reset, or a release of what was never charged would let a short run pass.
#[test]
fn b2c_the_one_ledger_binds_every_helper_and_is_never_replenished() {
    let capsule = empty(CustodyGitObjectFormatV1::Sha1);
    let caller = CustodyGitObjectFormatV1::Sha1;
    let clean = clean_final_shape(&capsule, caller, false);
    let delta = clean.ledger - PlaneInV1::unborn(&capsule, caller).phase_v;
    assert!(delta > 4 * ENTRY_V1, "{delta}");
    for (row, headroom, succeeds) in [
        ("exactly the whole charge", delta, true),
        ("one byte short", delta - 1, false),
        ("half of it", delta / 2, false),
        ("one entry", ENTRY_V1, false),
    ] {
        let input = PlaneInV1::unborn(&capsule, caller);
        leave_headroom(&input.verified, headroom);
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        if succeeds {
            let plane = ran.success(row);
            assert_eq!(
                plane.ledger_used(),
                RESTORE_BYTES_CEILING_V1,
                "{row}: the whole headroom is used, and nothing more"
            );
            continue;
        }
        let failure = ran.failure(row);
        assert!(
            matches!(
                failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Budget(_))
            ),
            "{row}: {:?}",
            failure.cause
        );
        assert!(failure.ledger_used <= RESTORE_BYTES_CEILING_V1, "{row}");
        assert!(failure.partial.final_runs.is_empty(), "{row}");
        assert!(route.children().len() <= 3, "{row}: {:?}", route.children());
        ran.assert_one_ledger(row);
    }
}

/// Every staged plaintext is read through its retained descriptor, never by name: with the NAME of every
/// staged file removed from the destination before the call, the whole wrapper still restores exactly (the
/// pack is streamed to `index-pack` from its descriptor, and each active frame is rehashed and decoded twice
/// from its descriptor), and the result keeps every staged descriptor, back at offset 0.
#[test]
fn b2c_the_staged_inputs_are_read_from_their_retained_descriptors_after_their_names_are_gone() {
    fn remove_files(directory: &Path) -> usize {
        let mut removed = 0;
        for entry in std::fs::read_dir(directory).expect("a listable directory") {
            let path = entry.expect("an entry").path();
            if std::fs::symlink_metadata(&path).expect("metadata").is_dir() {
                removed += remove_files(&path);
            } else {
                std::fs::remove_file(&path).expect("a staged name is removed");
                removed += 1;
            }
        }
        removed
    }
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let staged = input.verified.staged.len();
    let removed = remove_files(&input.dest.work().join("plain"));
    // The pack and the controls have names beneath `plain/`; the two active frames the fixture re-staged
    // (see `stage_frame`) never had one.
    assert!((4..=staged).contains(&removed), "{removed} of {staged}");
    assert!(
        snapshot(&input.dest.work().join("plain"))
            .values()
            .all(Option::is_none),
        "only directories remain beneath plain/"
    );
    let route = RouteV1::recorder();
    let ran = run_plane(input, &route, far_deadline());
    let plane = ran.success("names gone");
    assert_clean_plane(&ran, plane, "names gone");
    assert_eq!(plane.capsule().staged.len(), staged);
    assert_eq!(route.children(), CAPTURED_CHILDREN_V1);
}

/// A deadline already spent when the wrapper is called is the caller's ONE deadline all the same: no child
/// starts, the refusal is the typed timeout, nothing is created beneath the repository, and the one ledger
/// holds only what pass A had reserved for its pins.
#[test]
fn b2c_a_deadline_spent_before_the_call_refuses_before_any_child_starts() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let route = RouteV1::recorder();
    let ran = run_plane(input, &route, Instant::now());
    let failure = ran.failure("a spent deadline");
    assert!(is_timeout(&failure.cause), "{:?}", failure.cause);
    assert_eq!(route.children(), Vec::<String>::new());
    assert!(!failure.active_materialization_began);
    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Admission));
    assert_eq!(ran.dest.entries(), [".restore-work"]);
    assert!(failure.partial.final_runs.is_empty());
    ran.assert_one_ledger("a spent deadline");
}

/// The device of every kind of entry in the final tree is the root's, in the census before the first final
/// child: the repository, its Git directory, an object directory, a metadata directory, and a regular file.
/// A change of device refuses with the custody refusal that names the entry, before any final child starts,
/// with `Config` as the last completed step and the one ledger unchanged.
#[test]
fn b2c_a_final_entry_on_another_device_refuses_for_every_kind_of_entry() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    for name in [
        "repository",
        "repository/.git",
        "repository/.git/objects",
        "repository/.git/refs/heads",
        "repository/.git/HEAD",
        "repository/.git/config",
    ] {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let dev = device_of(&input.dest.path);
        let _guard = override_census_dev_for_test(name, dev + 1);
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        let failure = ran.failure(name);
        assert!(
            matches!(
                &failure.cause,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::DeviceCrossing { name: found })
                    if found == name
            ),
            "{name}: {:?}",
            failure.cause
        );
        assert_eq!(
            failure.last_completed,
            Some(GitPlaneStepV1::Config),
            "{name}"
        );
        assert!(failure.partial.final_runs.is_empty(), "{name}");
        assert_eq!(route.children().len(), 6, "{name}");
        assert_eq!(failure.ledger_used, clean.ledger, "{name}");
    }
}

/// A deadline spent while a child's baseline is being taken refuses before the child starts: the digest of the
/// restored files keeps the ONE deadline before every read, so the typed timeout is returned, no child is
/// started (the second child's census is where the clock ran out), and the first child's proof stays recorded.
#[test]
fn b2c_a_deadline_spent_before_a_childs_digest_refuses_before_the_child_starts() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let route = RouteV1::recorder();
    let deadline = Instant::now() + B2C_DEADLINE_V1;
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeFinalChildCensus, move |event| {
        if event.label == "rev-list --missing=print" {
            pass_the_deadline(deadline);
        }
    });
    let ran = run_plane(input, &route, deadline);
    let failure = ran.failure("a spent deadline");
    assert!(is_timeout(&failure.cause), "{:?}", failure.cause);
    assert_eq!(
        route.children().len(),
        7,
        "the second final child never started"
    );
    assert_eq!(failure.partial.final_runs.len(), 1);
    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Config));
    assert_eq!(failure.ledger_used, clean.ledger);
}

/// A digest is bound to the census it serves, and a changed read is refused by that binding: in the closing
/// gate, a name swapped for another inode holding other bytes of the same length between the census and the
/// digest (the digest descriptor is not the file the census measured: without the binding, the refusal would be
/// a mismatch of bytes), a file grown while its digest is open, and a file cut short after its digest opened it
/// are each an identity change, typed as such, with every proof recorded and every byte kept.
#[test]
fn b2c_a_digest_is_bound_to_the_census_and_a_changed_read_is_refused() {
    #[derive(Clone, Copy)]
    enum AtV1 {
        /// The guard right after the census, before any digest: `act` runs in it.
        AfterCensus,
        /// The digest of this file (beneath `.git`) has opened it, and read nothing.
        Opened(&'static str),
        /// The digest of this file has read it to its end; its closing `fstat` has not run.
        Hashed(&'static str),
    }
    type RowV1 = (&'static str, AtV1, fn(&Path, &Path));
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let rows: [RowV1; 3] = [
        (
            "a name swapped between the census and the digest",
            AtV1::AfterCensus,
            |git, outside| replace_with_other_bytes(&git.join("HEAD"), outside),
        ),
        (
            "a file grown while its digest is open",
            AtV1::Hashed("config"),
            |git, _| {
                use std::io::Write as _;
                std::fs::OpenOptions::new()
                    .append(true)
                    .open(git.join("config"))
                    .and_then(|mut file| file.write_all(b"x"))
                    .expect("an appended byte");
            },
        ),
        (
            "a file cut short after its digest opened it",
            AtV1::Opened("config"),
            |git, _| {
                std::fs::OpenOptions::new()
                    .write(true)
                    .open(git.join("config"))
                    .and_then(|file| file.set_len(5))
                    .expect("a cut file");
            },
        ),
    ];
    for (row, at, act) in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let (_area, outside) = external_dir_with(&["decoy"]);
        let git = input.dest.path.join("repository/.git");
        let in_closing_gate = std::rc::Rc::new(std::cell::Cell::new(false));
        let acted = std::rc::Rc::new(std::cell::Cell::new(false));
        let mut hooks = Vec::new();
        {
            let (closing, acted) = (in_closing_gate.clone(), acted.clone());
            let (git, outside) = (git.clone(), outside.clone());
            hooks.push(install_git_hook_for_test(
                GitHookPointV1::DeadlineObserved,
                move |event| {
                    if event.label == "final-closing" {
                        closing.set(true);
                    }
                    if matches!(at, AtV1::AfterCensus)
                        && event.label == "final-tree"
                        && !acted.replace(true)
                    {
                        act(&git, &outside);
                    }
                },
            ));
        }
        for (point, opened) in [
            (GitHookPointV1::FinalDigestOpened, true),
            (GitHookPointV1::FinalDigestHashed, false),
        ] {
            let target = match at {
                AtV1::Opened(file) if opened => Some(file),
                AtV1::Hashed(file) if !opened => Some(file),
                _ => None,
            };
            let Some(file) = target else { continue };
            let (closing, acted) = (in_closing_gate.clone(), acted.clone());
            let (git, outside) = (git.clone(), outside.clone());
            let wanted = git.join(file);
            hooks.push(install_git_hook_for_test(point, move |event| {
                if closing.get() && event.path == wanted && !acted.replace(true) {
                    act(&git, &outside);
                }
            }));
        }
        let route = RouteV1::recorder();
        let ran = run_plane(input, &route, far_deadline());
        drop(hooks);
        let failure = ran.failure(row);
        assert!(acted.get(), "{row}: the change was made");
        assert!(
            is_identity_changed(&failure.cause),
            "{row}: {:?}",
            failure.cause
        );
        assert_eq!(
            failure.last_completed,
            Some(GitPlaneStepV1::Config),
            "{row}"
        );
        assert_eq!(failure.partial.final_runs.len(), 3, "{row}");
        assert_eq!(failure.ledger_used, clean.ledger, "{row}");
    }
}

/// A file swapped for another inode holding the same bytes AFTER the census listed it and BEFORE it opened it
/// is never measured as the listed entry: the no-follow descriptor's own `fstat` is compared with the listing,
/// so the replacement is refused as an identity change, in the census before the first final child, with no
/// final child started.
#[test]
fn b2c_a_file_swapped_between_its_listing_and_its_open_is_never_measured() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let (_area, outside) = external_dir_with(&["decoy"]);
    let head = input.dest.path.join("repository/.git/HEAD");
    let swapped = std::cell::Cell::new(false);
    let _hook = install_git_hook_for_test(GitHookPointV1::BeforeFinalCensusOpen, {
        let head = head.clone();
        move |event| {
            if event.path == head && !swapped.replace(true) {
                replace_with_same_bytes(&head, &outside);
            }
        }
    });
    let route = RouteV1::recorder();
    let ran = run_plane(input, &route, far_deadline());
    let failure = ran.failure("a swap between listing and open");
    assert!(is_identity_changed(&failure.cause), "{:?}", failure.cause);
    assert_eq!(route.children().len(), 6, "no final child started");
    assert!(failure.partial.final_runs.is_empty());
    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Config));
    assert_eq!(failure.ledger_used, clean.ledger);
}

/// Every staged descriptor is seeked back to offset 0 explicitly before the result is returned, whatever any
/// earlier step left: each is moved off offset 0 (through a duplicate, which shares the offset) in the last
/// final child's post-exit callback, which precedes the rewinds, and the result still holds every one of
/// them at offset 0. A rewind that is not run, or that does not seek, leaves them where they were moved.
#[test]
fn b2c_every_staged_descriptor_is_rewound_before_the_result_is_returned() {
    use std::io::Seek as _;
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let shared: Vec<std::fs::File> = input
        .verified
        .staged
        .iter()
        .map(|one| one.file.try_clone().expect("a duplicate descriptor"))
        .collect();
    let moved = std::cell::Cell::new(false);
    let _hook = install_git_hook_for_test(GitHookPointV1::AfterFinalChild, move |event| {
        if event.label == "fsck --strict" && !moved.replace(true) {
            for file in &shared {
                (&*file)
                    .seek(SeekFrom::Start(3))
                    .expect("the shared offset moves");
            }
        }
    });
    let route = RouteV1::recorder();
    let ran = run_plane(input, &route, far_deadline());
    let plane = ran.success("moved offsets");
    assert_clean_plane(&ran, plane, "moved offsets");
    assert!(plane.capsule().staged.iter().all(|one| position(one) == 0));
}

// ---------------------------------------------------------------------------------------------
// A slow call that returns after the deadline is followed by no further call
// ---------------------------------------------------------------------------------------------

/// One row: the closing gate's census and digest, with the call a hook point stands behind made slow past the
/// one deadline (the first such call in the closing gate, on a regular file for the entry points), and every
/// later hook and guard of the closing gate recorded. Returns every problem found with how it ended.
fn slow_return_row(
    capsule: &CustomCapsuleV1,
    name: &'static str,
    point: GitHookPointV1,
    regular_only: bool,
) -> Vec<String> {
    const POINTS: [(GitHookPointV1, &str); 9] = [
        (GitHookPointV1::FinalCensusStatted, "statted"),
        (GitHookPointV1::FinalCensusListed, "listed"),
        (GitHookPointV1::BeforeFinalCensusOpen, "entry-statted"),
        (GitHookPointV1::FinalFileOpened, "file-opened"),
        (GitHookPointV1::FinalDigestFileOpened, "digest-file-opened"),
        (GitHookPointV1::FinalDigestOpened, "digest-bound"),
        (GitHookPointV1::FinalDigestHashed, "digest-read"),
        (GitHookPointV1::FinalSourceStatted, "source-statted"),
        (GitHookPointV1::FinalStagingChecked, "staging-checked"),
    ];
    let input = PlaneInV1::rich(capsule, CustodyGitObjectFormatV1::Sha1);
    let route = RouteV1::recorder();
    let deadline = Instant::now() + B2C_DEADLINE_V1;
    let log: std::rc::Rc<std::cell::RefCell<Vec<String>>> = std::rc::Rc::default();
    let closing = std::rc::Rc::new(std::cell::Cell::new(false));
    let slowed_at: std::rc::Rc<std::cell::Cell<Option<usize>>> = std::rc::Rc::default();
    let mut hooks = Vec::new();
    for (hook_point, label) in POINTS {
        let (log, closing, slowed_at) = (log.clone(), closing.clone(), slowed_at.clone());
        hooks.push(install_git_hook_for_test(hook_point, move |event| {
            if !closing.get() {
                return;
            }
            log.borrow_mut().push(format!("hook:{label}"));
            let wanted = hook_point == point && (!regular_only || event.path.is_file());
            if wanted && slowed_at.get().is_none() {
                slowed_at.set(Some(log.borrow().len() - 1));
                pass_the_deadline(deadline);
            }
        }));
    }
    {
        let (log, closing) = (log.clone(), closing.clone());
        hooks.push(install_git_hook_for_test(
            GitHookPointV1::DeadlineObserved,
            move |event| {
                if event.label == "final-closing" {
                    closing.set(true);
                }
                if closing.get() {
                    log.borrow_mut().push(format!("guard:{}", event.label));
                }
            },
        ));
    }
    let ran = run_plane(input, &route, deadline);
    drop(hooks);
    let Some(at) = slowed_at.get() else {
        return vec![format!("{name}: the call was never reached")];
    };
    let Err(failure) = &ran.outcome else {
        return vec![format!("{name}: a success followed the expiry")];
    };
    let log = log.borrow();
    let after = &log[at + 1..];
    let mut judged = Vec::new();
    if !is_timeout(&failure.cause) {
        judged.push(format!("cause {:?}", failure.cause));
    }
    if failure.last_completed != Some(GitPlaneStepV1::Config) {
        judged.push(format!("completed {:?}", failure.last_completed));
    }
    // Nothing is done after the slow call returned but the clock: at most one guard, and no later hook (every
    // hook stands right after a call that was made).
    if after.len() > 1 || after.iter().any(|event| event.starts_with("hook:")) {
        judged.push(format!("{} events followed it: {after:?}", after.len()));
    }
    if judged.is_empty() {
        Vec::new()
    } else {
        vec![format!("{name}: {}", judged.join("; "))]
    }
}

/// Every slow call of the closing gate's census, digests, and chains is followed by the clock BEFORE the next
/// call, not only before the one after it: the `fstat` of a directory, its listing, the `fstat` of an entry, the
/// open of a file and its descriptor's `fstat`, a digest's open, its binding `fstat`, and its read, an admitted
/// file's `fstat` by name, and the first entry of a staging chain are each made slow past the one deadline in
/// turn, and the run ends with the typed timeout and NOTHING further done: at most the guard that reads the
/// clock, and no later call (a later call would announce itself through its hook). A digest's bound read keeps
/// its own clock before every read, so the call after the binding `fstat` is its first read, which refuses
/// without a hook. A call that is followed by one call that has no hook (a descriptor's own `fstat`) is held by
/// the exact guard sequence and by the swap rows at those guards, not by this row.
#[test]
fn b2c_a_slow_call_that_returns_after_the_deadline_is_followed_by_no_further_call() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let rows: [(&'static str, GitHookPointV1, bool); 9] = [
        (
            "a directory's fstat",
            GitHookPointV1::FinalCensusStatted,
            false,
        ),
        (
            "a directory's listing",
            GitHookPointV1::FinalCensusListed,
            false,
        ),
        (
            "a regular entry's fstat",
            GitHookPointV1::BeforeFinalCensusOpen,
            true,
        ),
        ("a file's open", GitHookPointV1::FinalFileOpened, true),
        (
            "a digest's open",
            GitHookPointV1::FinalDigestFileOpened,
            true,
        ),
        (
            "a digest's binding fstat",
            GitHookPointV1::FinalDigestOpened,
            true,
        ),
        ("a digest's read", GitHookPointV1::FinalDigestHashed, true),
        (
            "an admitted file's entry fstat",
            GitHookPointV1::FinalSourceStatted,
            false,
        ),
        (
            "a staging chain entry's recheck",
            GitHookPointV1::FinalStagingChecked,
            false,
        ),
    ];
    let problems: Vec<String> = std::thread::scope(|scope| {
        let handles: Vec<_> = rows
            .iter()
            .map(|&(name, point, regular)| {
                let capsule = &capsule;
                scope.spawn(move || slow_return_row(capsule, name, point, regular))
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|handle| handle.join().expect("a slow-return row's thread"))
            .collect()
    });
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

// ---------------------------------------------------------------------------------------------
// A deadline spent in a runner callback is still reconciled beside what the child left (source round 3)
// ---------------------------------------------------------------------------------------------

/// The runner's callbacks are held to the one deadline, so a callback that finds it spent refuses with the typed
/// timeout. That refusal makes the child's failure KNOWN, and a known failure is reconciled WITHOUT the clock
/// (bounded by the measured lengths): what the child left is measured after the deadline and named beside the
/// timeout, never lost to it. In a post-exit callback (the child ran; the runner returns an error, so its proof
/// is not recorded) the child left an entry, or rewrote HEAD in place with every clock stalled (only the digest
/// sees it); the typed timeout is the primary and the effect the reconciliation. In a pre-spawn callback an
/// entry appeared before the child would start: the child never starts, and the same two failures are kept
/// (the control: it did so before the callbacks were paced too). Every byte stays, the ledger is the clean
/// run's, and the second final child's proof is the last recorded.
#[test]
fn b2c_a_deadline_spent_in_a_runner_callback_is_reconciled_beside_what_the_child_left() {
    type CheckV1 = fn(&GitBootstrapErrorV1) -> bool;
    struct RowV1 {
        name: &'static str,
        point: GitHookPointV1,
        shell: Option<&'static str>,
        /// Whether the hook itself plants the entry (a child that never starts cannot).
        plant: bool,
        stalled: bool,
        children: usize,
        check: CheckV1,
    }
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let rows = [
        RowV1 {
            name: "a post-exit callback, the child left an entry",
            point: GitHookPointV1::AfterFinalChild,
            shell: Some("\"$REAL\" \"$@\"; : > .git/stray"),
            plant: false,
            stalled: false,
            children: 9,
            check: |error| {
                combined_with(error, is_timeout, |r| {
                    tree_fault(r, FinalTreeFaultV1::Unexpected)
                })
            },
        },
        RowV1 {
            name: "a post-exit callback, the child rewrote HEAD in place with every clock stalled",
            point: GitHookPointV1::AfterFinalChild,
            shell: Some(
                "\"$REAL\" \"$@\"; printf X | dd of=.git/HEAD bs=1 seek=10 conv=notrunc 2>/dev/null",
            ),
            plant: false,
            stalled: true,
            children: 9,
            check: |error| {
                combined_with(error, is_timeout, |r| tree_fault(r, FinalTreeFaultV1::Bytes))
            },
        },
        RowV1 {
            name: "a pre-spawn callback, an entry appeared before the child would start",
            point: GitHookPointV1::BeforeFinalChild,
            shell: None,
            plant: true,
            stalled: false,
            children: 8,
            check: |error| {
                combined_with(error, is_timeout, |r| {
                    tree_fault(r, FinalTreeFaultV1::Unexpected)
                })
            },
        },
    ];
    let mut problems = Vec::new();
    for row in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let root = input.dest.path.clone();
        let stray = root.join("repository/.git/stray");
        let route = match row.shell {
            Some(shell) => RouteV1::new(&[("fsck --strict", &final_only(shell))]),
            None => RouteV1::recorder(),
        };
        let deadline = Instant::now() + B2C_DEADLINE_V1;
        let at_the_hook: SnapshotSlotV1 = SnapshotSlotV1::default();
        let (slot, planted, hooked_root) = (at_the_hook.clone(), row.plant, root.clone());
        let _hook = install_git_hook_for_test(row.point, move |event| {
            if event.label == "fsck --strict" {
                if planted {
                    std::fs::write(&stray, b"").expect("a planted entry");
                }
                *slot.borrow_mut() = Some(snapshot(&hooked_root));
                pass_the_deadline(deadline);
            }
        });
        let _clocks = row
            .stalled
            .then(|| stall_census_clocks_for_test(BOTH_CLOCKS_V1));
        let ran = run_plane(input, &route, deadline);
        let Err(failure) = &ran.outcome else {
            problems.push(format!("{}: a success", row.name));
            continue;
        };
        let mut judged = Vec::new();
        if !(row.check)(&failure.cause) {
            judged.push(format!("cause {:?}", failure.cause));
        }
        if route.children().len() != row.children {
            judged.push(format!("children {:?}", route.children()));
        }
        if failure.partial.final_runs.len() != 2 {
            judged.push(format!("{} proofs", failure.partial.final_runs.len()));
        }
        if failure.last_completed != Some(GitPlaneStepV1::Config)
            || !failure.active_materialization_began
        {
            judged.push(format!("completed {:?}", failure.last_completed));
        }
        if failure.ledger_used != clean.ledger {
            judged.push(format!(
                "ledger {} not {}",
                failure.ledger_used, clean.ledger
            ));
        }
        if Some(snapshot(&ran.dest.path)) != at_the_hook.borrow().clone() {
            judged.push("a byte changed after the hook".to_owned());
        }
        if !judged.is_empty() {
            problems.push(format!("{}: {}", row.name, judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

// ---------------------------------------------------------------------------------------------
// A slow call inside a final child's bracket is followed by no further call (source round 3)
//
// The rows above slow the closing gate. Every final child is bracketed by four more success-eligible parts, and
// each is held to the same one deadline: the zero-effect baseline (census and digests), the pre-spawn callback,
// the post-exit callback, and the settlement of a result that is about to be a success. These rows make ONE call
// of one part slow past the deadline (or, as the control, slow but with headroom), and record every event that
// follows it: the clock's guards, the hooks that stand right after later calls, and each mount census. A
// failure that is already KNOWN (a callback that found the deadline spent) is still reconciled without the
// clock, so the census and digest hooks of that reconciliation are allowed after it; the pre-spawn callback's
// gate (a mount census, an admitted file's or a staging entry's recheck, a second guard) is not.
//
// Source round 4 changes what follows a slow call in the post-exit callback and in the settlement: the clock cut
// a part of a child that may have run short, so the typed timeout is a KNOWN failure there, and exactly one
// failure-only reconciliation (the mount census, the exact tree, every retained chain, no clock) is now
// REQUIRED after the guard, where before nothing but a tree reconciliation (a callback) or nothing at all (a
// settlement) followed. What stays prohibited is every success-eligible continuation: a second guard, a child,
// a second census, a success.
// ---------------------------------------------------------------------------------------------

/// Where in a bracket the slow call is made.
#[derive(Clone, Copy, Debug)]
enum SiteV1 {
    /// The bracket's first moment: the hook that stands before anything of the bracket is done.
    Entry,
    /// The mount census (a runner callback's first call, and the success gate's).
    Mount,
    /// The call behind this hook point (`true`: only a regular file's, for the points that stand behind a
    /// per-entry call).
    Call(GitHookPointV1, bool),
}

/// How slow the call is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HowSlowV1 {
    /// Past the one deadline: it returns after it.
    PastTheDeadline,
    /// Slow, but returning well inside the deadline: the control that nothing refuses a live deadline.
    WithHeadroom,
}

/// How long a slow call with headroom takes.
const HEADROOM_SLOW_V1: Duration = Duration::from_millis(300);

/// What a bracket row records after the arming guard, in order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SeenV1 {
    /// The clock was read for this step.
    Guard(&'static str),
    /// A hook that stands right after a call ran.
    Hook(GitHookPointV1),
    /// The mount census ran.
    Mount,
}

/// The hook points that stand behind a call of the census, the digests, or the retained chains.
const CALL_POINTS_V1: [GitHookPointV1; 9] = [
    GitHookPointV1::FinalCensusStatted,
    GitHookPointV1::FinalCensusListed,
    GitHookPointV1::BeforeFinalCensusOpen,
    GitHookPointV1::FinalFileOpened,
    GitHookPointV1::FinalDigestFileOpened,
    GitHookPointV1::FinalDigestOpened,
    GitHookPointV1::FinalDigestHashed,
    GitHookPointV1::FinalSourceStatted,
    GitHookPointV1::FinalStagingChecked,
];

/// The calls of a census, of the digests, and of the retained chains, by the site that slows each.
const CENSUS_SITES_V1: [SiteV1; 4] = [
    SiteV1::Call(GitHookPointV1::FinalCensusStatted, false),
    SiteV1::Call(GitHookPointV1::FinalCensusListed, false),
    SiteV1::Call(GitHookPointV1::BeforeFinalCensusOpen, true),
    SiteV1::Call(GitHookPointV1::FinalFileOpened, true),
];
const DIGEST_SITES_V1: [SiteV1; 3] = [
    SiteV1::Call(GitHookPointV1::FinalDigestFileOpened, true),
    SiteV1::Call(GitHookPointV1::FinalDigestOpened, true),
    SiteV1::Call(GitHookPointV1::FinalDigestHashed, true),
];
const GATE_SITES_V1: [SiteV1; 3] = [
    SiteV1::Mount,
    SiteV1::Call(GitHookPointV1::FinalSourceStatted, false),
    SiteV1::Call(GitHookPointV1::FinalStagingChecked, false),
];

/// Every bracket row: all of the FIRST final child's sites, and a representative set for the other two (the
/// bracket is one function for every child, so what differs is only which child's hooks are reached).
fn bracket_rows() -> Vec<(usize, BracketV1, SiteV1)> {
    let mut rows = vec![(1, BracketV1::Baseline, SiteV1::Entry)];
    for site in CENSUS_SITES_V1.into_iter().chain(DIGEST_SITES_V1) {
        rows.push((1, BracketV1::Baseline, site));
    }
    for bracket in [BracketV1::BeforeCallback, BracketV1::AfterCallback] {
        rows.push((1, bracket, SiteV1::Entry));
        for site in GATE_SITES_V1 {
            rows.push((1, bracket, site));
        }
    }
    for site in CENSUS_SITES_V1
        .into_iter()
        .chain(DIGEST_SITES_V1)
        .chain(GATE_SITES_V1)
    {
        rows.push((1, BracketV1::Settlement, site));
    }
    for child in [2, 3] {
        rows.push((child, BracketV1::Baseline, SiteV1::Entry));
        rows.push((
            child,
            BracketV1::Baseline,
            SiteV1::Call(GitHookPointV1::FinalDigestHashed, true),
        ));
        rows.push((child, BracketV1::BeforeCallback, SiteV1::Mount));
        rows.push((child, BracketV1::AfterCallback, SiteV1::Mount));
        rows.push((
            child,
            BracketV1::Settlement,
            SiteV1::Call(GitHookPointV1::FinalCensusStatted, false),
        ));
        rows.push((
            child,
            BracketV1::Settlement,
            SiteV1::Call(GitHookPointV1::FinalDigestHashed, true),
        ));
        rows.push((child, BracketV1::Settlement, SiteV1::Mount));
    }
    rows
}

/// One bracket row: final child `child` (1-based), the call at `site` in its `bracket` (the first such call,
/// on a regular file for the points that stand behind a per-entry call) made `slow`, over a Captured database
/// (the only one with every site), with everything that follows recorded. Returns every problem found.
fn bracket_row(
    capsule: &CustomCapsuleV1,
    clean: &FinalShapeV1,
    child: usize,
    bracket: BracketV1,
    site: SiteV1,
    slow: HowSlowV1,
) -> Vec<String> {
    type WindowV1 = std::rc::Rc<std::cell::Cell<Option<(&'static str, BracketV1)>>>;
    let label = FINAL_LABELS_CAPTURED_V1[child - 1];
    let name = format!("child {child} (`{label}`), {bracket:?}, {site:?}, {slow:?}");
    let input = PlaneInV1::rich(capsule, CustodyGitObjectFormatV1::Sha1);
    let root = input.dest.path.clone();
    let route = RouteV1::recorder();
    let deadline = Instant::now() + B2C_DEADLINE_V1;
    let log: std::rc::Rc<std::cell::RefCell<Vec<SeenV1>>> = std::rc::Rc::default();
    let armed = std::rc::Rc::new(std::cell::Cell::new(false));
    let window: WindowV1 = WindowV1::default();
    let slowed_at: std::rc::Rc<std::cell::Cell<Option<usize>>> = std::rc::Rc::default();
    let at_the_slow_call: SnapshotSlotV1 = SnapshotSlotV1::default();
    // The ONE place an event is recorded: nothing before the final stage's entry guard is.
    let record: std::rc::Rc<dyn Fn(SeenV1) -> Option<usize>> = {
        let (log, armed) = (log.clone(), armed.clone());
        std::rc::Rc::new(move |seen: SeenV1| {
            if !armed.get() {
                return None;
            }
            let mut log = log.borrow_mut();
            log.push(seen);
            Some(log.len() - 1)
        })
    };
    // The ONE slow call: noted, the tree snapshotted as it stands, and then made slow.
    let slow_now: std::rc::Rc<dyn Fn(usize)> = {
        let (slowed_at, at_the_slow_call) = (slowed_at.clone(), at_the_slow_call.clone());
        std::rc::Rc::new(move |index: usize| {
            slowed_at.set(Some(index));
            *at_the_slow_call.borrow_mut() = Some(snapshot(&root));
            match slow {
                HowSlowV1::PastTheDeadline => pass_the_deadline(deadline),
                HowSlowV1::WithHeadroom => std::thread::sleep(HEADROOM_SLOW_V1),
            }
        })
    };
    let mut hooks = Vec::new();
    // The three hooks that open a bracket for the child they name.
    for (point, part) in [
        (GitHookPointV1::BeforeFinalChildCensus, BracketV1::Baseline),
        (GitHookPointV1::BeforeFinalChild, BracketV1::BeforeCallback),
        (GitHookPointV1::AfterFinalChild, BracketV1::AfterCallback),
    ] {
        let (window, record, slow_now, slowed_at) = (
            window.clone(),
            record.clone(),
            slow_now.clone(),
            slowed_at.clone(),
        );
        hooks.push(install_git_hook_for_test(point, move |event| {
            window.set(Some((event.label, part)));
            let Some(index) = record(SeenV1::Hook(point)) else {
                return;
            };
            if matches!(site, SiteV1::Entry)
                && part == bracket
                && event.label == label
                && slowed_at.get().is_none()
            {
                slow_now(index);
            }
        }));
    }
    // The hooks behind a call. The first census call after a post-exit callback opens the settlement.
    for point in CALL_POINTS_V1 {
        let (window, record, slow_now, slowed_at) = (
            window.clone(),
            record.clone(),
            slow_now.clone(),
            slowed_at.clone(),
        );
        hooks.push(install_git_hook_for_test(point, move |event| {
            if point == GitHookPointV1::FinalCensusStatted
                && window.get() == Some((label, BracketV1::AfterCallback))
            {
                window.set(Some((label, BracketV1::Settlement)));
            }
            let Some(index) = record(SeenV1::Hook(point)) else {
                return;
            };
            if let SiteV1::Call(wanted, regular_only) = site {
                if wanted == point
                    && window.get() == Some((label, bracket))
                    && (!regular_only || event.path.is_file())
                    && slowed_at.get().is_none()
                {
                    slow_now(index);
                }
            }
        }));
    }
    // The clock's own guards arm the recording at the stage's entry and close the brackets at the rewinds.
    {
        let (window, armed, record) = (window.clone(), armed.clone(), record.clone());
        hooks.push(install_git_hook_for_test(
            GitHookPointV1::DeadlineObserved,
            move |event| {
                if event.label == "final-entry" {
                    armed.set(true);
                }
                if event.label == "final-rewind" {
                    window.set(None);
                }
                record(SeenV1::Guard(event.label));
            },
        ));
    }
    let census = {
        let (window, record, slow_now, slowed_at) = (
            window.clone(),
            record.clone(),
            slow_now.clone(),
            slowed_at.clone(),
        );
        crate::custody_mounts::seam::install(Box::new(move |_| {
            if let Some(index) = record(SeenV1::Mount) {
                if matches!(site, SiteV1::Mount)
                    && window.get() == Some((label, bracket))
                    && slowed_at.get().is_none()
                {
                    slow_now(index);
                }
            }
            Ok(vec![b"/".to_vec()])
        }))
    };
    let ran = run_plane(input, &route, deadline);
    drop(hooks);
    drop(census);
    let Some(at) = slowed_at.get() else {
        return vec![format!("{name}: the call was never reached")];
    };
    let log = log.borrow();
    let after = &log[at + 1..];
    let (started, recorded) = StageV1::Child(child, bracket).children_after(clean.final_children);
    let mut judged = Vec::new();
    match slow {
        HowSlowV1::PastTheDeadline => {
            let Err(failure) = &ran.outcome else {
                return vec![format!("{name}: a success followed the expiry")];
            };
            if !is_timeout(&failure.cause) {
                judged.push(format!("cause {:?}", failure.cause));
            }
            if failure.last_completed != Some(GitPlaneStepV1::Config) {
                judged.push(format!("completed {:?}", failure.last_completed));
            }
            if !failure.active_materialization_began {
                judged.push("began nothing".to_owned());
            }
            if failure.partial.final_runs.len() != recorded {
                judged.push(format!(
                    "{} proofs recorded, {recorded} had returned",
                    failure.partial.final_runs.len()
                ));
            }
            if route.children().len() != 6 + started {
                judged.push(format!("children {:?}", route.children()));
            }
            if failure.ledger_used != clean.ledger {
                judged.push(format!(
                    "ledger {} not {}",
                    failure.ledger_used, clean.ledger
                ));
            }
            if Some(snapshot(&ran.dest.path)) != at_the_slow_call.borrow().clone() {
                judged.push("a byte changed after the slow call".to_owned());
            }
            match bracket {
                // A failure that is not yet known when the call returns, and that no child is owed: the clock is
                // the ONLY thing that may follow it (at most one guard), and not a hook, a census, or a second
                // call. A baseline that runs late refuses before the runner is called: nothing started.
                BracketV1::Baseline => {
                    if after.len() > 1
                        || after
                            .iter()
                            .any(|seen| matches!(seen, SeenV1::Hook(_) | SeenV1::Mount))
                    {
                        judged.push(format!("{} events followed it: {after:?}", after.len()));
                    }
                }
                // Source round 4. The clock cut a success-eligible part of a child that may have run short (the
                // post-exit callback, or the settlement of a result that was about to be a success): that
                // typed timeout is now a KNOWN failure, and exactly ONE failure-only reconciliation follows the
                // guard that found it, without reading the clock again: the mount census, the exact tree, and
                // every retained chain (see `failure_only_reconciliation`). No child began or resumed, and no
                // success-eligible step went on.
                //
                // Design follow-on 1: what is owed is by UNIT, from the part's own progress: a slow call returns,
                // the next guard of the SAME unit finds the deadline spent, so that unit and every unit after it
                // are owed, and every unit before it is not observed again (`owed_after_the_slow_call`).
                BracketV1::AfterCallback | BracketV1::Settlement => {
                    judged.extend(failure_only_reconciliation(
                        after,
                        clean,
                        owed_after_the_slow_call(bracket, site),
                        attempted_in_phase(&log[..=at], bracket == BracketV1::Settlement),
                    ));
                }
                // A pre-spawn callback's refusal makes a failure known before the child starts, and a known
                // failure is still reconciled without the clock (a census and the digests, whose hooks may
                // follow): but nothing of the callback's own gate may, and the guard that found the deadline
                // spent must be the very next event.
                BracketV1::BeforeCallback => {
                    let gate: Vec<&SeenV1> = after
                        .iter()
                        .filter(|seen| {
                            matches!(
                                seen,
                                SeenV1::Guard(_)
                                    | SeenV1::Mount
                                    | SeenV1::Hook(GitHookPointV1::FinalSourceStatted)
                                    | SeenV1::Hook(GitHookPointV1::FinalStagingChecked)
                            )
                        })
                        .collect();
                    if gate.len() > 1
                        || (gate.len() == 1 && !matches!(after.first(), Some(SeenV1::Guard(_))))
                    {
                        judged.push(format!("the gate went on after it: {after:?}"));
                    }
                }
            }
        }
        HowSlowV1::WithHeadroom => {
            match &ran.outcome {
                Ok(plane) => {
                    if plane.closure.runs.len() != clean.final_children {
                        judged.push(format!("{} proofs", plane.closure.runs.len()));
                    }
                }
                Err(failure) => judged.push(format!("refused: {:?}", failure.cause)),
            }
            if route.children() != CAPTURED_CHILDREN_V1 {
                judged.push(format!("children {:?}", route.children()));
            }
            if Instant::now() >= deadline {
                judged.push("finished after its deadline".to_owned());
            }
            if after.is_empty() {
                judged.push("nothing followed the slow call".to_owned());
            }
        }
    }
    if judged.is_empty() {
        Vec::new()
    } else {
        vec![format!("{name}: {}", judged.join("; "))]
    }
}

/// Runs every bracket row with `slow` on a few threads at once, and returns every problem.
fn bracket_problems(slow: HowSlowV1) -> Vec<String> {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    assert_eq!(
        clean.final_children, 3,
        "a Captured database has three final children"
    );
    let rows = bracket_rows();
    std::thread::scope(|scope| {
        let mut all = Vec::new();
        for chunk in rows.chunks(8) {
            let handles: Vec<_> = chunk
                .iter()
                .map(|&(child, bracket, site)| {
                    let (capsule, clean) = (&capsule, &clean);
                    scope.spawn(move || bracket_row(capsule, clean, child, bracket, site, slow))
                })
                .collect();
            for handle in handles {
                all.extend(handle.join().expect("a bracket row's thread"));
            }
        }
        all
    })
}

/// Every success-eligible bracket of every final child is held to the ONE deadline at every slow call: the
/// baseline's census (a directory's `fstat`, its listing, an entry's `fstat`, a file's open) and digest (an open,
/// its binding `fstat`, a read), the mount census and the retained chains of BOTH runner callbacks, the
/// settlement's census, digests, and success gate, and each bracket's own first moment (a deadline already
/// spent when the bracket begins). Each is made slow past the deadline in turn, and the run ends with the typed
/// timeout and NO SUCCESS-ELIGIBLE step further done: a baseline is followed by at most the guard that reads the
/// clock (no hook, no census: its child never started); a pre-spawn callback by that guard and then only the
/// clock-free reconciliation of the final tree (its gate does not go on); and the post-exit callback and the
/// settlement (source round 4) by that guard and then exactly ONE clock-free failure-only reconciliation (the
/// mount census once, the exact tree once, every retained chain once, no clock, no child, no success); the child
/// that had not started never starts, the proofs are exactly the ones that returned, and every byte is as it
/// stood when the slow call returned. (Design follow-on 1: what the completion owes is by UNIT, from the part's own
/// progress: the slow call returns, the next guard of the SAME unit finds the deadline spent, so that unit and
/// every unit after it are observed once, and every unit before it, which ran to a verdict, is not observed
/// again; `owed_after_the_slow_call` states it for each site.)
#[test]
fn b2c_a_slow_call_inside_a_childs_bracket_is_followed_by_no_further_call() {
    let problems = bracket_problems(HowSlowV1::PastTheDeadline);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// The control of the rows above: the very same calls, slow but returning WITH headroom, change nothing: the
/// run goes on past each one and succeeds with all three final children, before its deadline.
#[test]
fn b2c_a_slow_call_with_headroom_inside_a_childs_bracket_changes_nothing() {
    let problems = bracket_problems(HowSlowV1::WithHeadroom);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

// ---------------------------------------------------------------------------------------------
// A KNOWN failure is reconciled once, through one bounded failure-only helper (source round 4)
//
// Source round 3/3 found two finite transitions in which a final child's failure was known, or became known, and
// what the child left behind was still never examined: (1) a child the runner TIMES OUT meets a post-exit
// callback whose gate stops at its entry guard, so the mount census and every retained chain went unexamined;
// (2) a success-eligible settlement whose slow call returns after the deadline returned the bare typed timeout,
// so the entries and bytes of a child that had succeeded went unmeasured. These rows drive the REAL wrapper over
// REAL Git with a routed final `fsck` child and the real runner, with only the hooks and the mount-census seam
// that already existed, and judge the outcome (the typed primary beside the typed reconciliation failure), the
// filesystem (no byte after the failure was known), the ledger, the proofs, the children that started, and the
// FOOTPRINT of the reconciliation (the events that followed the failure becoming known).
// ---------------------------------------------------------------------------------------------

/// How often a failure-only reconciliation owes one class of observation, by unit and not by boolean (design
/// follow-on 1): a class whose units a completed phase already ran to a verdict is owed NOTHING again, a class no
/// phase ran is owed ONCE, in full, and a class can stop early only for a fault of its own (the census of the
/// tree stops at its first fault; no other class does, because its units are independent).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum OwedV1 {
    /// Every unit of the class, exactly once.
    Once,
    /// Nothing: an earlier phase ran every unit of the class to a verdict.
    Never,
    /// The class's own fault stops it: at least its first step, at most the whole of it.
    Early,
}

/// What a failure-only reconciliation owes, judged from the events that followed it.
#[derive(Clone, Copy, Debug)]
struct FailureOnlyV1 {
    /// The mount census is owed once (no verdict of it followed the child), or not at all.
    mounts: bool,
    /// The census of the exact tree.
    census: OwedV1,
    /// The digest of every restored file, by its retained descriptor.
    digests: OwedV1,
    /// The recheck of every admitted bootstrap file.
    sources: OwedV1,
    /// The recheck of the staging chains.
    staging: OwedV1,
}

impl FailureOnlyV1 {
    /// Nothing was observed after the child: every class owed once, a clean tree and clean chains.
    fn complete() -> Self {
        Self {
            mounts: true,
            census: OwedV1::Once,
            digests: OwedV1::Once,
            sources: OwedV1::Once,
            staging: OwedV1::Once,
        }
    }
}

/// What a slow call at `site` of `bracket` leaves owed (design follow-on 1: the units the part had already run to
/// a verdict are NOT observed again, and the unit the guard stopped is). A post-exit callback's gate is its
/// entry guard, the mount census, then every retained chain in custody order (the admitted bootstrap files
/// before the staging chains); a settlement is the census (whose comparison follows it), the digests, and then
/// the same gate. A slow call returns, then the NEXT guard of its own unit finds the deadline spent: the unit it
/// was in is unsettled, and every unit before it is settled.
fn owed_after_the_slow_call(bracket: BracketV1, site: SiteV1) -> FailureOnlyV1 {
    let all = FailureOnlyV1::complete();
    let census_point = |point| {
        matches!(
            point,
            GitHookPointV1::FinalCensusStatted
                | GitHookPointV1::FinalCensusListed
                | GitHookPointV1::BeforeFinalCensusOpen
                | GitHookPointV1::FinalFileOpened
        )
    };
    match (bracket, site) {
        (BracketV1::AfterCallback, SiteV1::Entry) => all,
        (BracketV1::AfterCallback, SiteV1::Mount) => FailureOnlyV1 {
            mounts: false,
            ..all
        },
        (BracketV1::AfterCallback, SiteV1::Call(GitHookPointV1::FinalSourceStatted, _)) => {
            FailureOnlyV1 {
                mounts: false,
                ..all
            }
        }
        (BracketV1::AfterCallback, SiteV1::Call(GitHookPointV1::FinalStagingChecked, _)) => {
            FailureOnlyV1 {
                mounts: false,
                sources: OwedV1::Never,
                ..all
            }
        }
        (BracketV1::Settlement, SiteV1::Call(point, _)) if census_point(point) => all,
        (
            BracketV1::Settlement,
            SiteV1::Call(
                GitHookPointV1::FinalDigestFileOpened
                | GitHookPointV1::FinalDigestOpened
                | GitHookPointV1::FinalDigestHashed,
                _,
            ),
        ) => FailureOnlyV1 {
            census: OwedV1::Never,
            ..all
        },
        (
            BracketV1::Settlement,
            SiteV1::Mount | SiteV1::Call(GitHookPointV1::FinalSourceStatted, _),
        ) => FailureOnlyV1 {
            mounts: false,
            census: OwedV1::Never,
            digests: OwedV1::Never,
            ..all
        },
        (BracketV1::Settlement, SiteV1::Call(GitHookPointV1::FinalStagingChecked, _)) => {
            FailureOnlyV1 {
                mounts: false,
                census: OwedV1::Never,
                digests: OwedV1::Never,
                sources: OwedV1::Never,
                ..all
            }
        }
        other => panic!("no reconciliation is owed after a slow call at {other:?}"),
    }
}

/// The units of the census and of the admitted-file chain that the PACED part of a final child's bracket had
/// already made a call for when a slow call returned (the slow call included), counted from the hooks that stand
/// right after each call: a completion never makes such a call again (follow-on 1 targeted repair), so it is owed
/// only the rest.
#[derive(Clone, Copy, Debug, Default)]
struct AttemptedV2 {
    stats: usize,
    listed: usize,
    entries: usize,
    opened: usize,
    sources: usize,
}

/// [`AttemptedV2`] from the events up to and including the slow call. A post-exit callback's own part starts at its
/// callback (its gate has no census, only admitted-file rechecks); a settlement's starts at its first census call
/// after that callback, which is also where its terminal gate's admitted-file rechecks belong.
fn attempted_in_phase(prefix: &[SeenV1], settlement: bool) -> AttemptedV2 {
    let exit = prefix
        .iter()
        .rposition(|seen| matches!(seen, SeenV1::Hook(GitHookPointV1::AfterFinalChild)))
        .unwrap_or(0);
    let start = if settlement {
        prefix[exit..]
            .iter()
            .position(|seen| matches!(seen, SeenV1::Hook(GitHookPointV1::FinalCensusStatted)))
            .map_or(prefix.len(), |at| exit + at)
    } else {
        exit
    };
    let count = |point| {
        prefix[start..]
            .iter()
            .filter(|seen| matches!(seen, SeenV1::Hook(found) if *found == point))
            .count()
    };
    AttemptedV2 {
        stats: count(GitHookPointV1::FinalCensusStatted),
        listed: count(GitHookPointV1::FinalCensusListed),
        entries: count(GitHookPointV1::BeforeFinalCensusOpen),
        opened: count(GitHookPointV1::FinalFileOpened),
        sources: count(GitHookPointV1::FinalSourceStatted),
    }
}

/// Judges what followed a slow call that returned after the deadline (`after` starts right after it). The ONLY
/// event allowed before the reconciliation is the guard that read the clock (a bounded digest read reads it
/// itself, unlogged); the reconciliation itself reads no clock and begins and resumes no child. Each class of
/// observation is owed exactly as `scope` says, by unit (see [`OwedV1`]): the mount census once or not at all,
/// the census of the tree once, early (its own fault), or not at all, the digest of every restored file, the
/// admitted bootstrap files, and the staging chains likewise. Returns every problem found.
fn failure_only_reconciliation(
    after: &[SeenV1],
    clean: &FinalShapeV1,
    scope: FailureOnlyV1,
    attempted: AttemptedV2,
) -> Vec<String> {
    let reconcile = match after.split_first() {
        Some((SeenV1::Guard(_), reconcile)) => reconcile,
        // A bounded digest read keeps its own clock and reads it with no logged guard: the reconciliation's first
        // event (the mount census, which is owed whenever this scope applies) then follows the slow call itself,
        // and a read that went on would have announced itself through its own hook first.
        Some((SeenV1::Mount, _)) if scope.mounts => after,
        None => {
            return vec![
                "nothing followed the slow call: no failure-only reconciliation ran".to_owned(),
            ];
        }
        Some(_) => {
            return vec![format!(
                "a call followed the slow one before the clock was read: {after:?}"
            )];
        }
    };
    let count =
        |wanted: &dyn Fn(&SeenV1) -> bool| reconcile.iter().filter(|seen| wanted(seen)).count();
    let mut judged = Vec::new();
    if reconcile
        .iter()
        .any(|seen| matches!(seen, SeenV1::Guard(_)))
    {
        judged.push(format!(
            "the clock was read again, so a step went on past the guard: {reconcile:?}"
        ));
    }
    if reconcile.iter().any(|seen| {
        matches!(
            seen,
            SeenV1::Hook(
                GitHookPointV1::BeforeFinalChildCensus
                    | GitHookPointV1::BeforeFinalChild
                    | GitHookPointV1::AfterFinalChild
            )
        )
    }) {
        judged.push(format!("a child began or resumed: {reconcile:?}"));
    }
    let mounts = count(&|seen| matches!(seen, SeenV1::Mount));
    let want_mounts = usize::from(scope.mounts);
    if mounts != want_mounts {
        judged.push(format!("{mounts} mount censuses, {want_mounts} owed"));
    }
    let one_census = 1 + clean.tree_dirs;
    let hooks = |point| count(&|seen| matches!(seen, SeenV1::Hook(found) if *found == point));
    let stats = hooks(GitHookPointV1::FinalCensusStatted);
    let listed = hooks(GitHookPointV1::FinalCensusListed);
    let entries = hooks(GitHookPointV1::BeforeFinalCensusOpen);
    let opened = hooks(GitHookPointV1::FinalFileOpened);
    let files = clean.object_files + clean.metadata_files;
    let digests = hooks(GitHookPointV1::FinalDigestFileOpened);
    let sources = hooks(GitHookPointV1::FinalSourceStatted);
    let staging = hooks(GitHookPointV1::FinalStagingChecked);
    // (class, found, whole, already attempted by the paced part before the completion, owed). A unit whose call
    // RETURNED before the guard found the deadline spent is attempted: the completion carries its fact and never
    // makes the call again (follow-on 1 targeted repair), so a class owed `Once` is owed exactly the units of it
    // that no call had returned for.
    for (class, found, whole, done, owed) in [
        (
            "directory censuses",
            stats,
            one_census,
            attempted.stats,
            scope.census,
        ),
        (
            "directory listings",
            listed,
            one_census,
            attempted.listed,
            scope.census,
        ),
        (
            "entry censuses",
            entries,
            clean.tree_entries,
            attempted.entries,
            scope.census,
        ),
        ("file opens", opened, files, attempted.opened, scope.census),
        ("digests", digests, files, 0, scope.digests),
        (
            "admitted-file rechecks",
            sources,
            clean.object_files,
            attempted.sources,
            scope.sources,
        ),
    ] {
        let wrong = match owed {
            OwedV1::Once => found + done != whole,
            OwedV1::Never => found != 0,
            // An early stop is bounded by what the class holds, and an entry the child added is one more name.
            OwedV1::Early => {
                found + done > whole + 1 || (class == "directory censuses" && found + done == 0)
            }
        };
        if wrong {
            judged.push(format!(
                "{found} {class} (and {done} already attempted), {owed:?} of {whole} owed"
            ));
        }
    }
    let wrong = match scope.staging {
        OwedV1::Once => staging == 0,
        OwedV1::Never => staging != 0,
        OwedV1::Early => false,
    };
    if wrong {
        judged.push(format!(
            "{staging} staging rechecks, {:?} owed",
            scope.staging
        ));
    }
    judged
}

/// When the failure of a row's final `fsck` child becomes known.
#[derive(Clone, Copy, Debug)]
enum KnownWhenV1 {
    /// At the child's post-exit callback (the child timed out, exited, or was refused by its gate).
    AfterChild,
    /// At a call of the child's settlement that returns late (or, as the control, slow with headroom).
    SlowSettlement(GitHookPointV1, HowSlowV1),
}

/// What a row expects of the reconciliation that follows the failure.
#[derive(Clone, Copy, Debug)]
enum ReconciledV1 {
    /// Source round 4: ONE failure-only reconciliation after the guard that found the deadline spent.
    Once(FailureOnlyV1),
    /// The post-exit gate itself ran to a verdict (a pass, or a custody refusal that is the finding): only the
    /// tree is owed beside the primary, and the gate's own single mount census and single chain sweep are the
    /// only ones that follow the child.
    TreeAfterTheGate,
    /// A settlement that had headroom found a custody finding of its own (the first paced finding is the
    /// primary), which makes the failure known: its census had already run to that verdict, so it is not
    /// observed again, and every other observation still owed (the mount census, the digest of every restored
    /// file by its retained descriptor, and every retained chain) is made exactly once, as the paced settlement
    /// itself never reached them (design follow-on 1; the control that used to require no reconciliation here
    /// asserted the defect).
    AfterPacedFinding,
}

/// One row: the final `fsck` child runs `shell` (or delegates), the failure becomes known `when`, and the run
/// must end with the typed cause `cause`.
struct KnownRowV1 {
    name: &'static str,
    shell: Option<&'static str>,
    when: KnownWhenV1,
    /// The child overruns the one deadline (it sleeps), so the runner times it out.
    timed_out: bool,
    /// Every census clock is reported as never having advanced (only a digest can see an in-place write).
    stalled: bool,
    /// A mount appears inside the destination as soon as the child has exited.
    mount_after_exit: bool,
    cause: fn(&GitBootstrapErrorV1) -> bool,
    reconciled: ReconciledV1,
    /// The final proofs recorded when the run ends (a refused callback makes the runner return an error).
    recorded: usize,
}

/// A bootstrap-relative mount point of the destination, as the census would list it.
fn mount_inside(root: &Path) -> Vec<u8> {
    root.join(".restore-work/home")
        .as_os_str()
        .as_bytes()
        .to_vec()
}

/// Runs one row and returns every problem found (and prints its verdict, so a green row is as visible as a red
/// one).
fn known_row(capsule: &CustomCapsuleV1, clean: &FinalShapeV1, row: &KnownRowV1) -> Vec<String> {
    type LogV1 = std::rc::Rc<std::cell::RefCell<Vec<SeenV1>>>;
    let name = row.name;
    let input = PlaneInV1::rich(capsule, CustodyGitObjectFormatV1::Sha1);
    let root = input.dest.path.clone();
    let spends_the_deadline = row.timed_out
        || matches!(
            row.when,
            KnownWhenV1::SlowSettlement(_, HowSlowV1::PastTheDeadline)
        );
    let body = row.shell.map(final_only);
    let route = match &body {
        Some(body) => RouteV1::new(&[("fsck --strict", body.as_str())]),
        None => RouteV1::recorder(),
    };
    let deadline = if spends_the_deadline {
        Instant::now() + B2C_DEADLINE_V1
    } else {
        far_deadline()
    };
    let log: LogV1 = LogV1::default();
    let armed = std::rc::Rc::new(std::cell::Cell::new(false));
    let after_exit = std::rc::Rc::new(std::cell::Cell::new(false));
    let appeared = std::rc::Rc::new(std::cell::Cell::new(false));
    let known_at: std::rc::Rc<std::cell::Cell<Option<usize>>> = std::rc::Rc::default();
    let at_known: SnapshotSlotV1 = SnapshotSlotV1::default();
    // The ONE place an event is recorded: nothing before the final stage's entry guard is.
    let record: std::rc::Rc<dyn Fn(SeenV1) -> Option<usize>> = {
        let (log, armed) = (log.clone(), armed.clone());
        std::rc::Rc::new(move |seen: SeenV1| {
            if !armed.get() {
                return None;
            }
            let mut log = log.borrow_mut();
            log.push(seen);
            Some(log.len() - 1)
        })
    };
    let mut hooks = Vec::new();
    // The three hooks that open a part of a final child's bracket: the post-exit one is the moment a child that
    // exited (or timed out) is judged, and where a row that waits for it notes that its failure is known.
    for point in [
        GitHookPointV1::BeforeFinalChildCensus,
        GitHookPointV1::BeforeFinalChild,
        GitHookPointV1::AfterFinalChild,
    ] {
        let (record, after_exit, appeared, known_at, at_known, root) = (
            record.clone(),
            after_exit.clone(),
            appeared.clone(),
            known_at.clone(),
            at_known.clone(),
            root.clone(),
        );
        let (when, mount_after_exit) = (row.when, row.mount_after_exit);
        hooks.push(install_git_hook_for_test(point, move |event| {
            let index = record(SeenV1::Hook(point));
            if point == GitHookPointV1::AfterFinalChild && event.label == "fsck --strict" {
                after_exit.set(true);
                if mount_after_exit {
                    appeared.set(true);
                }
                if let (Some(index), KnownWhenV1::AfterChild) = (index, when) {
                    known_at.set(Some(index));
                    *at_known.borrow_mut() = Some(snapshot(&root));
                }
            }
        }));
    }
    // The hooks behind a call: the settlement of the `fsck` child is the first such call after its post-exit
    // callback (the callback's gate has no census and no digest), and the row's slow call is made there.
    for point in CALL_POINTS_V1 {
        let (record, after_exit, known_at, at_known, root) = (
            record.clone(),
            after_exit.clone(),
            known_at.clone(),
            at_known.clone(),
            root.clone(),
        );
        let when = row.when;
        hooks.push(install_git_hook_for_test(point, move |_| {
            let Some(index) = record(SeenV1::Hook(point)) else {
                return;
            };
            if let KnownWhenV1::SlowSettlement(wanted, slow) = when {
                if wanted == point && after_exit.get() && known_at.get().is_none() {
                    known_at.set(Some(index));
                    *at_known.borrow_mut() = Some(snapshot(&root));
                    match slow {
                        HowSlowV1::PastTheDeadline => pass_the_deadline(deadline),
                        HowSlowV1::WithHeadroom => std::thread::sleep(HEADROOM_SLOW_V1),
                    }
                }
            }
        }));
    }
    {
        let (armed, record) = (armed.clone(), record.clone());
        hooks.push(install_git_hook_for_test(
            GitHookPointV1::DeadlineObserved,
            move |event| {
                if event.label == "final-entry" {
                    armed.set(true);
                }
                record(SeenV1::Guard(event.label));
            },
        ));
    }
    let census = {
        let (record, appeared) = (record.clone(), appeared.clone());
        let inside = mount_inside(&root);
        crate::custody_mounts::seam::install(Box::new(move |_| {
            record(SeenV1::Mount);
            if appeared.get() {
                Ok(vec![b"/".to_vec(), inside.clone()])
            } else {
                Ok(vec![b"/".to_vec()])
            }
        }))
    };
    let _clocks = row
        .stalled
        .then(|| stall_census_clocks_for_test(BOTH_CLOCKS_V1));
    let ran = run_plane(input, &route, deadline);
    drop(hooks);
    drop(census);
    let Some(known) = known_at.get() else {
        let seen = format!("{name}: the failure never became known (the fixture did not reach it)");
        println!("KNOWN-ROW {seen}");
        return vec![seen];
    };
    let Err(failure) = &ran.outcome else {
        let seen = format!("{name}: a success followed the failure");
        println!("KNOWN-ROW {seen}");
        return vec![seen];
    };
    let log = log.borrow();
    let after = &log[known + 1..];
    let mut judged = Vec::new();
    if !(row.cause)(&failure.cause) {
        judged.push(format!("cause {:?}", failure.cause));
    }
    if failure.last_completed != Some(GitPlaneStepV1::Config)
        || !failure.active_materialization_began
    {
        judged.push(format!("completed {:?}", failure.last_completed));
    }
    if route.children().len() != 9 {
        judged.push(format!("children {:?}", route.children()));
    }
    if failure.partial.final_runs.len() != row.recorded {
        judged.push(format!(
            "{} proofs, {} had returned",
            failure.partial.final_runs.len(),
            row.recorded
        ));
    }
    if failure.ledger_used != clean.ledger {
        judged.push(format!(
            "ledger {} not {}",
            failure.ledger_used, clean.ledger
        ));
    }
    if Some(snapshot(&ran.dest.path)) != *at_known.borrow() {
        judged.push("a byte changed after the failure was known".to_owned());
    }
    match row.reconciled {
        ReconciledV1::Once(scope) => {
            let attempted = match row.when {
                KnownWhenV1::AfterChild => AttemptedV2::default(),
                KnownWhenV1::SlowSettlement(..) => attempted_in_phase(&log[..=known], true),
            };
            judged.extend(failure_only_reconciliation(after, clean, scope, attempted));
        }
        ReconciledV1::TreeAfterTheGate => {
            let count =
                |wanted: &dyn Fn(&SeenV1) -> bool| after.iter().filter(|seen| wanted(seen)).count();
            let mounts = count(&|seen| matches!(seen, SeenV1::Mount));
            if mounts != 1 {
                judged.push(format!("{mounts} mount censuses, the gate's own one owed"));
            }
            let sources =
                count(&|seen| matches!(seen, SeenV1::Hook(GitHookPointV1::FinalSourceStatted)));
            if sources != clean.object_files {
                judged.push(format!(
                    "{sources} source rechecks, the gate's own {} owed",
                    clean.object_files
                ));
            }
            let stats =
                count(&|seen| matches!(seen, SeenV1::Hook(GitHookPointV1::FinalCensusStatted)));
            if stats != 1 + clean.tree_dirs {
                judged.push(format!(
                    "{stats} directory censuses, exactly {} owed",
                    1 + clean.tree_dirs
                ));
            }
        }
        ReconciledV1::AfterPacedFinding => {
            let count =
                |wanted: &dyn Fn(&SeenV1) -> bool| after.iter().filter(|seen| wanted(seen)).count();
            let mounts = count(&|seen| matches!(seen, SeenV1::Mount));
            if mounts != 1 {
                judged.push(format!(
                    "{mounts} mount censuses, the one completion's owed (the paced settlement never reached its gate)"
                ));
            }
            let digests =
                count(&|seen| matches!(seen, SeenV1::Hook(GitHookPointV1::FinalDigestFileOpened)));
            let files = clean.object_files + clean.metadata_files;
            if digests != files {
                judged.push(format!(
                    "{digests} digests, exactly {files} owed (the paced settlement never reached its digests)"
                ));
            }
            let sources =
                count(&|seen| matches!(seen, SeenV1::Hook(GitHookPointV1::FinalSourceStatted)));
            let staging =
                count(&|seen| matches!(seen, SeenV1::Hook(GitHookPointV1::FinalStagingChecked)));
            if sources != clean.object_files || staging == 0 {
                judged.push(format!(
                    "{sources} source rechecks (exactly {} owed) and {staging} staging rechecks (some owed)",
                    clean.object_files
                ));
            }
            if after.iter().any(|seen| {
                matches!(
                    seen,
                    SeenV1::Hook(
                        GitHookPointV1::AfterFinalChild
                            | GitHookPointV1::BeforeFinalChild
                            | GitHookPointV1::BeforeFinalChildCensus
                    )
                )
            }) {
                judged.push(format!("a child began or resumed: {after:?}"));
            }
        }
    }
    println!(
        "KNOWN-ROW {name}: {}",
        if judged.is_empty() {
            "ok".to_owned()
        } else {
            judged.join("; ")
        }
    );
    if judged.is_empty() {
        Vec::new()
    } else {
        vec![format!("{name}: {}", judged.join("; "))]
    }
}

/// Runs the rows of one test, a few threads at a time (each row installs its own hooks and census seam in its own
/// thread), and returns every problem.
fn known_problems(rows: Vec<KnownRowV1>) -> Vec<String> {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    std::thread::scope(|scope| {
        let mut all = Vec::new();
        for chunk in rows.chunks(8) {
            let handles: Vec<_> = chunk
                .iter()
                .map(|row| {
                    let (capsule, clean) = (&capsule, &clean);
                    scope.spawn(move || known_row(capsule, clean, row))
                })
                .collect();
            for handle in handles {
                all.extend(handle.join().expect("a known-failure row's thread"));
            }
        }
        all
    })
}

/// A child the runner TIMES OUT has run, and the post-exit callback cannot gate it (its entry guard finds the
/// deadline spent). The failure is known: the typed timeout is the primary, and ONE failure-only reconciliation
/// follows it, WITHOUT the clock, and examines everything the child may have left: the mount census, the exact
/// tree, and every retained chain. A retained bootstrap directory, staging directory, admitted bootstrap object
/// file, and the output chain's repository entry are each swapped by the child while the final repository stays
/// byte-identical, and a mount appears just after it exits: each is named beside the timeout. Both a tree effect
/// and a chain swap are kept (neither class hides the other). The reconciliation stays finite for a child that
/// left hundreds of names, and one that put a link where a restored file was is refused by the tree AND by the
/// chains (never followed); a child that left nothing is the bare timeout. Every
/// row: the same children, the proofs that had returned, `Config`, the one ledger unchanged, no byte after the
/// failure was known, one mount census, no clock, no child resumed, no success.
#[test]
fn b2c_a_timed_out_final_child_is_reconciled_once_beside_every_retained_chain_and_mount_it_left_owed(
) {
    // Design follow-on 1: the units of one class are independent, so a failing chain edge never stops the next
    // edge, and the census of the tree stopping at its own first fault never stops the digests (they read the
    // retained descriptors) or the chains: only the census itself can stop early.
    let chain_fails = FailureOnlyV1::complete();
    let tree_fails = FailureOnlyV1 {
        census: OwedV1::Early,
        ..FailureOnlyV1::complete()
    };
    let timed_out =
        |name, shell, cause: fn(&GitBootstrapErrorV1) -> bool, scope: FailureOnlyV1| KnownRowV1 {
            name,
            shell: Some(shell),
            when: KnownWhenV1::AfterChild,
            timed_out: true,
            stalled: false,
            mount_after_exit: false,
            cause,
            reconciled: ReconciledV1::Once(scope),
            recorded: 2,
        };
    let rows = vec![
        timed_out(
            "a timed-out child swapped a retained bootstrap directory, the repository unchanged",
            "mv ../.restore-work/git-bootstrap/objects ../.restore-work/git-bootstrap/objects.away; mkdir ../.restore-work/git-bootstrap/objects; sleep 30",
            |e| combined_with(e, is_timeout, is_identity_changed),
            chain_fails,
        ),
        timed_out(
            "a timed-out child swapped a retained staging directory, the repository unchanged",
            "mv ../.restore-work/plain/control ../.restore-work/plain/control.away; mkdir ../.restore-work/plain/control; sleep 30",
            |e| combined_with(e, is_timeout, is_identity_changed),
            chain_fails,
        ),
        timed_out(
            "a timed-out child replaced an admitted bootstrap object file with another inode",
            "for f in ../.restore-work/git-bootstrap/objects/pack/*.pack; do cp \"$f\" \"$f.new\"; mv \"$f.new\" \"$f\"; done; sleep 30",
            |e| combined_with(e, is_timeout, is_identity_changed),
            chain_fails,
        ),
        // A rename moves the pinned directory's own ctime, which the census of the tree would see by itself: the
        // clocks are stalled so only the chain (the root's entry for `repository`) can.
        KnownRowV1 {
            stalled: true,
            ..timed_out(
                "a timed-out child swapped the repository directory itself (the output chain), every clock stalled",
                "mv ../repository ../repository.away; mkdir ../repository; sleep 30",
                |e| combined_with(e, is_timeout, is_identity_changed),
                chain_fails,
            )
        },
        KnownRowV1 {
            mount_after_exit: true,
            ..timed_out(
                "a mount appeared inside the destination as a timed-out child exited",
                "sleep 30",
                |e| {
                    combined_with(e, is_timeout, |r| {
                        matches!(
                            r,
                            GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::MountBoundary(_))
                        )
                    })
                },
                FailureOnlyV1::complete(),
            )
        },
        timed_out(
            "a timed-out child that left an entry AND swapped a retained bootstrap directory",
            ": > .git/stray; mv ../.restore-work/git-bootstrap/objects ../.restore-work/git-bootstrap/objects.away; mkdir ../.restore-work/git-bootstrap/objects; sleep 30",
            |e| {
                matches!(e, GitBootstrapErrorV1::ChildAndReconcile { primary, reconcile }
                    if is_timeout(primary)
                        && combined_with(
                            reconcile,
                            |p| tree_fault(p, FinalTreeFaultV1::Unexpected),
                            is_identity_changed,
                        ))
            },
            // The census stops at the stray; the digests and every chain edge are still owed in full.
            tree_fails,
        ),
        timed_out(
            "a timed-out child that left nothing is the bare timeout",
            "sleep 30",
            is_timeout,
            FailureOnlyV1::complete(),
        ),
        timed_out(
            "a timed-out child that left hundreds of names stops at the census bound",
            "i=0; while [ $i -lt 500 ]; do : > .git/n$i; i=$((i+1)); done; sleep 30",
            |e| combined_with(e, is_timeout, |r| tree_fault(r, FinalTreeFaultV1::Bound)),
            tree_fails,
        ),
        // A restored metadata file is in two classes: the census of the tree and the retained chains each refuse the
        // link (neither follows it), and neither hides the other.
        timed_out(
            "a timed-out child that put a link where a file was is refused by both the tree and the chains, never followed",
            "rm .git/ORIG_HEAD; ln -s /etc/hostname .git/ORIG_HEAD; sleep 30",
            |e| {
                matches!(e, GitBootstrapErrorV1::ChildAndReconcile { primary, reconcile }
                    if is_timeout(primary) && combined_with(reconcile, symlink_refused, symlink_refused))
            },
            tree_fails,
        ),
    ];
    let problems = known_problems(rows);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// A child that SUCCEEDED (its runner result and both callbacks are clean) enters the settlement on the one
/// deadline; a call of that settlement that returns after the deadline makes the typed timeout the PRIMARY
/// failure, now known, and ONE failure-only reconciliation follows the guard that found it, without the clock:
/// the effect the child left is named beside the timeout, never lost to it. A child that added `.git/stray`
/// (the post-exit gate does not enumerate names) whose settlement's first `fstat` returns late; a child that
/// rewrote HEAD in place with every clock stalled whose settlement's first digest open returns late (only the
/// digest sees the bytes); and, as the control, a child that left nothing is the bare timeout. The same
/// exactly-once, no-clock, no-resumed-child, no-success, unchanged-ledger, no-byte-after judgements hold.
#[test]
fn b2c_a_successful_final_child_whose_settlement_returns_late_is_reconciled_once_beside_what_it_left(
) {
    let late =
        |name, shell, point, stalled, cause: fn(&GitBootstrapErrorV1) -> bool, scope| KnownRowV1 {
            name,
            shell,
            when: KnownWhenV1::SlowSettlement(point, HowSlowV1::PastTheDeadline),
            timed_out: false,
            stalled,
            mount_after_exit: false,
            cause,
            reconciled: ReconciledV1::Once(scope),
            recorded: 3,
        };
    let rows = vec![
        late(
            "a successful child added an entry and its settlement's first fstat returned late",
            Some("\"$REAL\" \"$@\"; : > .git/stray"),
            GitHookPointV1::FinalCensusStatted,
            false,
            |e| {
                combined_with(e, is_timeout, |r| {
                    tree_fault(r, FinalTreeFaultV1::Unexpected)
                })
            },
            // The late call is in the census, which stops at the entry; every other class is owed in full.
            FailureOnlyV1 {
                census: OwedV1::Early,
                ..FailureOnlyV1::complete()
            },
        ),
        late(
            "a successful child rewrote HEAD in place, every clock stalled, and its first digest open returned late",
            Some("\"$REAL\" \"$@\"; printf X | dd of=.git/HEAD bs=1 seek=10 conv=notrunc 2>/dev/null"),
            GitHookPointV1::FinalDigestFileOpened,
            true,
            |e| combined_with(e, is_timeout, |r| tree_fault(r, FinalTreeFaultV1::Bytes)),
            // The late call is the first digest's: the settlement's census and its comparison had already run to
            // their verdict (clean), so they are not observed again; every digest is owed, by its retained
            // descriptor, and so are the mount census and every chain.
            FailureOnlyV1 {
                census: OwedV1::Never,
                ..FailureOnlyV1::complete()
            },
        ),
        late(
            "a successful child that left nothing is the bare timeout when its settlement returns late",
            None,
            GitHookPointV1::FinalCensusStatted,
            false,
            is_timeout,
            FailureOnlyV1::complete(),
        ),
    ];
    let problems = known_problems(rows);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// The controls of the two rows above, against the same fixture. A failure whose post-exit gate ran to its end is
/// reconciled for the TREE only, and a gate that refused part way is never observed again for the units it ran:
/// a child that failed with a nonzero status and left nothing, and a child that swapped a retained bootstrap
/// directory and exited normally (its own post-exit gate refuses at that directory, after the mount census and
/// every admitted file and staging chain it had already run to a verdict, and only the units after the refusing one
/// are owed, of which none finds anything) each show the gate's own single mount census and single sweep of the
/// admitted files and the tree once, nothing more. And the SAME slow settlement call, slow but returning WITH
/// headroom, is no timeout: the paced settlement measures the added entry itself and that custody finding is the
/// primary (design follow-on 1: it used to be returned ALONE, which hid every observation still owed), and the
/// observations it never reached (the mount census, the digest of every restored file, and every retained chain)
/// are made exactly once, finding nothing more here, so the entry is reported alone, with no clock and no child.
#[test]
fn b2c_a_known_failure_whose_gate_already_ran_is_reconciled_for_the_tree_only_and_a_headroom_call_for_none(
) {
    let rows = vec![
        KnownRowV1 {
            name: "a child failed with a nonzero status and left nothing (its post-exit gate passed)",
            shell: Some("\"$REAL\" \"$@\"; exit 1"),
            when: KnownWhenV1::AfterChild,
            timed_out: false,
            stalled: false,
            mount_after_exit: false,
            cause: |e| is_git_child(e, "fsck --strict", 1),
            reconciled: ReconciledV1::TreeAfterTheGate,
            recorded: 3,
        },
        KnownRowV1 {
            name: "a child swapped a retained bootstrap directory and exited (its post-exit gate refuses)",
            shell: Some("\"$REAL\" \"$@\"; mv ../.restore-work/git-bootstrap/objects ../.restore-work/git-bootstrap/objects.away; mkdir ../.restore-work/git-bootstrap/objects"),
            when: KnownWhenV1::AfterChild,
            timed_out: false,
            stalled: false,
            mount_after_exit: false,
            cause: is_identity_changed,
            reconciled: ReconciledV1::TreeAfterTheGate,
            recorded: 2,
        },
        KnownRowV1 {
            name: "the same slow settlement call with headroom: the paced settlement's own finding is the primary and everything still owed is observed once",
            shell: Some("\"$REAL\" \"$@\"; : > .git/stray"),
            when: KnownWhenV1::SlowSettlement(
                GitHookPointV1::FinalCensusStatted,
                HowSlowV1::WithHeadroom,
            ),
            timed_out: false,
            stalled: false,
            mount_after_exit: false,
            // Nothing else was left behind, so the observations that are still owed find nothing: the entry is
            // reported alone, but they ran (see `ReconciledV1::AfterPacedFinding`).
            cause: |e| tree_fault(e, FinalTreeFaultV1::Unexpected),
            reconciled: ReconciledV1::AfterPacedFinding,
            recorded: 3,
        },
    ];
    let problems = known_problems(rows);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

// ---------------------------------------------------------------------------------------------
// Design follow-on 1: every owed observation of a known failure is made, independently, once
//
// The design pass (1/1, SHA-256 e932e69c…) found that a failure that is already known (or becomes known inside the
// paced settlement) still let ONE failing observation suppress the independent evidence of another: a census fault
// hid the bytes of a rewritten file, a callback refusal erased a drifted binary, a refused mount census was
// treated as a completed gate, a non-timeout paced finding was returned alone, a first bad file or chain edge
// stopped the rest, and the failure-only digest retried `Interrupted` without bound. These rows drive the REAL
// wrapper over REAL Git with a routed final `fsck` child and the real runner (and, for a detached helper's effect
// during the settlement, the hooks that already stand behind each call), with the typed failures a row expects
// listed IN ORDER: the primary, then the callback's refusal, the mount census, the census of the tree, the digest
// of each restored file by path, each retained chain in custody order, and the destination root LAST.
// ---------------------------------------------------------------------------------------------

/// One typed failure a row expects, by what it is (never by its text alone).
#[derive(Clone, Debug)]
enum ExpectedFailureV1 {
    Timeout,
    Drift,
    Child(&'static str, i32),
    Tree(FinalTreeFaultV1, &'static str),
    /// An identity refusal whose detail names this (a path, or the root).
    Identity(&'static str),
    Mount,
    /// An I/O refusal whose detail names this file.
    Io(&'static str),
    /// A link refused, never followed, by exactly this name.
    Symlink(&'static str),
    /// The comparison with the pre-child baseline refused (a read-only child changed the final repository).
    Changed,
}

impl ExpectedFailureV1 {
    fn is(&self, error: &GitBootstrapErrorV1) -> bool {
        match self {
            Self::Symlink(needle) => matches!(
                error,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { name })
                    if name == needle
            ),
            Self::Changed => matches!(
                error,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Budget(detail))
                    if detail.contains("a read-only child changed the final repository")
            ),
            Self::Timeout => is_timeout(error),
            Self::Drift => is_binary_drift(error),
            Self::Child(command, status) => is_git_child(error, command, *status),
            Self::Tree(fault, name) => matches!(
                error,
                GitBootstrapErrorV1::FinalTree { fault: found, name: named }
                    if found == fault && named.as_str() == *name
            ),
            Self::Identity(needle) => matches!(
                error,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::IdentityChanged(detail))
                    if detail.contains(needle)
            ),
            Self::Mount => matches!(
                error,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::MountBoundary(_))
            ),
            Self::Io(needle) => matches!(
                error,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::Io(detail))
                    if detail.contains(needle)
            ),
        }
    }
}

/// Every typed failure a (possibly nested) `ChildAndReconcile` holds, the primary first, in order.
fn leaves(error: &GitBootstrapErrorV1) -> Vec<&GitBootstrapErrorV1> {
    match error {
        GitBootstrapErrorV1::ChildAndReconcile { primary, reconcile } => {
            let mut all = leaves(primary);
            all.extend(leaves(reconcile));
            all
        }
        other => vec![other],
    }
}

/// How the mount census answers once the final child has exited.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MountsAfterV1 {
    Quiet,
    /// A mount appears inside the destination.
    Appears,
    /// The census cannot list the mount points (it fails closed).
    Fails,
}

/// What was observed from a moment on, by kind.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct CountsV1 {
    mounts: usize,
    sources: usize,
    stats: usize,
    digests: usize,
}

/// The counts a row holds exactly (`None`: not judged).
#[derive(Clone, Copy, Debug, Default)]
struct CountsExpectedFailureV1 {
    mounts: Option<usize>,
    sources: Option<usize>,
    stats: Option<usize>,
    digests: Option<usize>,
}

/// A change made to the destination, given the destination root and an outside directory.
type ActV1 = fn(&Path, &Path);
/// The shell the final `fsck --strict` child runs, given the destination root and an outside directory.
type ShellV1 = fn(&Path, &Path) -> String;

struct OwedRowV1 {
    name: &'static str,
    /// The final child's shell (`None`: the recorder runs the real child, which succeeds).
    shell: Option<ShellV1>,
    /// The child overruns the one deadline (it sleeps), so the runner times it out.
    timed_out: bool,
    /// Every census clock is reported as never having advanced (only a digest can see an in-place write).
    stalled: bool,
    mounts: MountsAfterV1,
    /// A change made as the child's pre-spawn callback begins.
    pre_spawn: Option<ActV1>,
    /// A detached helper's effect, made at the first call of the census after the child exited.
    helper: Option<ActV1>,
    /// Count from the pre-spawn callback of the final child (`true`) or from its post-exit callback.
    count_from_pre_spawn: bool,
    /// The typed failures, in order, the primary first.
    want: Vec<ExpectedFailureV1>,
    /// Every child that had started (`6` of pass A, then the final ones).
    children: usize,
    /// The final proofs that had returned.
    recorded: usize,
    counts: CountsExpectedFailureV1,
}

impl OwedRowV1 {
    fn new(name: &'static str, want: Vec<ExpectedFailureV1>) -> Self {
        Self {
            name,
            shell: None,
            timed_out: false,
            stalled: false,
            mounts: MountsAfterV1::Quiet,
            pre_spawn: None,
            helper: None,
            count_from_pre_spawn: false,
            want,
            children: 9,
            recorded: 3,
            counts: CountsExpectedFailureV1::default(),
        }
    }
}

/// The final `fsck --strict` child's `shell`, with the destination and an outside directory.
fn fsck_shell(shell: fn(&Path, &Path) -> String) -> Option<fn(&Path, &Path) -> String> {
    Some(shell)
}

/// Runs one row and returns every problem found (and prints its verdict, so a green row is as visible as a red
/// one).
fn owed_row(capsule: &CustomCapsuleV1, clean: &FinalShapeV1, row: &OwedRowV1) -> Vec<String> {
    use std::cell::Cell;
    use std::rc::Rc;
    let name = row.name;
    let input = PlaneInV1::rich(capsule, CustodyGitObjectFormatV1::Sha1);
    let root = input.dest.path.clone();
    let (_area, outside) = external_dir_with(&["decoy"]);
    let body = row.shell.map(|shell| final_only(&shell(&root, &outside)));
    let route = match &body {
        Some(body) => RouteV1::new(&[("fsck --strict", body.as_str())]),
        None => RouteV1::recorder(),
    };
    let deadline = if row.timed_out {
        Instant::now() + B2C_DEADLINE_V1
    } else {
        far_deadline()
    };
    let counting = Rc::new(Cell::new(false));
    let exited = Rc::new(Cell::new(false));
    let helped = Rc::new(Cell::new(false));
    let counts = Rc::new(Cell::new(CountsV1::default()));
    let mut hooks = Vec::new();
    {
        let (counting, root, outside) = (counting.clone(), root.clone(), outside.clone());
        let (pre_spawn, from_pre_spawn) = (row.pre_spawn, row.count_from_pre_spawn);
        hooks.push(install_git_hook_for_test(
            GitHookPointV1::BeforeFinalChild,
            move |event| {
                if event.label != "fsck --strict" {
                    return;
                }
                if from_pre_spawn {
                    counting.set(true);
                }
                if let Some(act) = pre_spawn {
                    act(&root, &outside);
                }
            },
        ));
    }
    {
        let (counting, exited) = (counting.clone(), exited.clone());
        let from_pre_spawn = row.count_from_pre_spawn;
        hooks.push(install_git_hook_for_test(
            GitHookPointV1::AfterFinalChild,
            move |event| {
                if event.label == "fsck --strict" {
                    exited.set(true);
                    if !from_pre_spawn {
                        counting.set(true);
                    }
                }
            },
        ));
    }
    for point in [
        GitHookPointV1::FinalCensusStatted,
        GitHookPointV1::FinalSourceStatted,
        GitHookPointV1::FinalDigestFileOpened,
    ] {
        let (counting, counts, exited, helped) = (
            counting.clone(),
            counts.clone(),
            exited.clone(),
            helped.clone(),
        );
        let (root, outside, helper) = (root.clone(), outside.clone(), row.helper);
        hooks.push(install_git_hook_for_test(point, move |_| {
            if !counting.get() {
                return;
            }
            let mut seen = counts.get();
            match point {
                GitHookPointV1::FinalCensusStatted => {
                    seen.stats += 1;
                    if exited.get() && !helped.get() {
                        helped.set(true);
                        if let Some(act) = helper {
                            act(&root, &outside);
                        }
                    }
                }
                GitHookPointV1::FinalSourceStatted => seen.sources += 1,
                _ => seen.digests += 1,
            }
            counts.set(seen);
        }));
    }
    let census = {
        let (counting, counts, exited) = (counting.clone(), counts.clone(), exited.clone());
        let (mode, inside) = (row.mounts, mount_inside(&root));
        crate::custody_mounts::seam::install(Box::new(move |_| {
            if counting.get() {
                let mut seen = counts.get();
                seen.mounts += 1;
                counts.set(seen);
            }
            match (mode, exited.get()) {
                (MountsAfterV1::Appears, true) => Ok(vec![b"/".to_vec(), inside.clone()]),
                (MountsAfterV1::Fails, true) => {
                    Err(crate::custody_mounts::CustodyMountErrorV1::MalformedLine { line: 1 })
                }
                _ => Ok(vec![b"/".to_vec()]),
            }
        }))
    };
    let _clocks = row
        .stalled
        .then(|| stall_census_clocks_for_test(BOTH_CLOCKS_V1));
    let ran = run_plane(input, &route, deadline);
    drop(hooks);
    drop(census);
    let Err(failure) = &ran.outcome else {
        let seen = format!("{name}: a success");
        println!("OWED-ROW {seen}");
        return vec![seen];
    };
    let held = leaves(&failure.cause);
    let mut judged = Vec::new();
    if held.len() != row.want.len()
        || !held
            .iter()
            .zip(&row.want)
            .all(|(error, want)| want.is(error))
    {
        judged.push(format!(
            "the typed failures were {held:?}, wanted {:?}",
            row.want
        ));
    }
    if route.children().len() != row.children {
        judged.push(format!("children {:?}", route.children()));
    }
    if failure.partial.final_runs.len() != row.recorded {
        judged.push(format!(
            "{} proofs, {} had returned",
            failure.partial.final_runs.len(),
            row.recorded
        ));
    }
    if failure.last_completed != Some(GitPlaneStepV1::Config)
        || !failure.active_materialization_began
    {
        judged.push(format!("completed {:?}", failure.last_completed));
    }
    if failure.ledger_used != clean.ledger {
        judged.push(format!(
            "ledger {} not {}",
            failure.ledger_used, clean.ledger
        ));
    }
    let seen = counts.get();
    for (what, got, want) in [
        ("mount censuses", seen.mounts, row.counts.mounts),
        ("admitted-file rechecks", seen.sources, row.counts.sources),
        ("directory censuses", seen.stats, row.counts.stats),
        ("digests", seen.digests, row.counts.digests),
    ] {
        if let Some(want) = want {
            if got != want {
                judged.push(format!("{got} {what}, exactly {want} owed"));
            }
        }
    }
    println!(
        "OWED-ROW {name}: {}",
        if judged.is_empty() {
            "ok".to_owned()
        } else {
            judged.join("; ")
        }
    );
    if judged.is_empty() {
        Vec::new()
    } else {
        vec![format!("{name}: {}", judged.join("; "))]
    }
}

/// Runs the rows of one test, a few threads at a time (each row installs its own hooks and census seam in its own
/// thread), and returns every problem.
fn owed_problems(rows: Vec<OwedRowV1>) -> Vec<String> {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    std::thread::scope(|scope| {
        let mut all = Vec::new();
        for chunk in rows.chunks(8) {
            let handles: Vec<_> = chunk
                .iter()
                .map(|row| {
                    let (capsule, clean) = (&capsule, &clean);
                    scope.spawn(move || owed_row(capsule, clean, row))
                })
                .collect();
            for handle in handles {
                all.extend(handle.join().expect("an owed-observation row's thread"));
            }
        }
        all
    })
}

/// What the Git directory's HEAD and ORIG_HEAD look like to an in-place, same-length rewrite.
const REWRITE_HEAD_V1: &str = "printf X | dd of=.git/HEAD bs=1 seek=10 conv=notrunc 2>/dev/null";
const REWRITE_ORIG_HEAD_V1: &str =
    "printf X | dd of=.git/ORIG_HEAD bs=1 seek=10 conv=notrunc 2>/dev/null";

/// REGRESSION 1 (design finding 1). A final `fsck` adds `.git/0stray`, rewrites HEAD in place at the same
/// length, and fails. The census refuses the stray, but that must not hide the bytes: the rewritten file's own
/// retained descriptor still shows them, so the run names the child's failure, the unexpected entry, and the
/// changed bytes, in that order, and nothing else (the post-exit gate that ran to its end is not repeated).
#[test]
fn b2c_a_failed_final_child_that_added_an_entry_and_rewrote_head_reports_both_the_entry_and_the_bytes(
) {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let row = OwedRowV1 {
        shell: fsck_shell(|_, _| {
            format!("\"$REAL\" \"$@\"; : > .git/0stray; {REWRITE_HEAD_V1}; exit 1")
        }),
        counts: CountsExpectedFailureV1 {
            mounts: Some(1),
            sources: Some(clean.object_files),
            digests: Some(files),
            ..CountsExpectedFailureV1::default()
        },
        ..OwedRowV1::new(
            "a failed child added an entry and rewrote HEAD in place",
            vec![
                ExpectedFailureV1::Child("fsck --strict", 1),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0stray"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Bytes, "HEAD"),
            ],
        )
    };
    let problems = owed_problems(vec![row]);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// REGRESSION 2 (design finding 1, with the runner's timeout). The same effects, and the child overruns the one
/// deadline: the typed timeout is the primary, and BOTH observations follow it (the mount census and every
/// retained chain, owed because no gate saw this child, find nothing).
#[test]
fn b2c_a_timed_out_final_child_that_added_an_entry_and_rewrote_head_reports_the_timeout_beside_both(
) {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let row = OwedRowV1 {
        shell: fsck_shell(|_, _| format!(": > .git/0stray; {REWRITE_HEAD_V1}; sleep 30")),
        timed_out: true,
        recorded: 2,
        counts: CountsExpectedFailureV1 {
            mounts: Some(1),
            sources: Some(clean.object_files),
            digests: Some(files),
            ..CountsExpectedFailureV1::default()
        },
        ..OwedRowV1::new(
            "a timed-out child added an entry and rewrote HEAD in place",
            vec![
                ExpectedFailureV1::Timeout,
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0stray"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Bytes, "HEAD"),
            ],
        )
    };
    let problems = owed_problems(vec![row]);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// REGRESSION 3 (design finding 2). A final child that mutates `$0` (the Git route) and swaps a retained
/// bootstrap directory: the runner evaluates BOTH the drift and the post-exit callback, and drift dominates, so
/// the primary is `BinaryDrift` and the callback's identity refusal is named beside it (it used to REPLACE it).
/// The same drift beside a callback that found the deadline spent keeps both too, and a drift whose callback
/// passed stays bare (the control).
#[test]
fn b2c_a_drifted_binary_stays_the_primary_beside_the_callback_refusal_and_what_the_child_left() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let rows = vec![
        OwedRowV1 {
            shell: fsck_shell(|_, outside| {
                format!(
                    "\"$REAL\" \"$@\"; chmod u+w \"$0\"; echo '# drift' >> \"$0\"; mv ../.restore-work/git-bootstrap/objects {o}/objects-away; mkdir ../.restore-work/git-bootstrap/objects",
                    o = outside.display()
                )
            }),
            recorded: 2,
            counts: CountsExpectedFailureV1 {
                // The gate's own census and its admitted-file rechecks (before the refusing directory), once.
                mounts: Some(1),
                sources: Some(clean.object_files),
                digests: Some(files),
                ..CountsExpectedFailureV1::default()
            },
            ..OwedRowV1::new(
                "a drifted binary beside a swapped retained bootstrap directory",
                vec![
                    ExpectedFailureV1::Drift,
                    ExpectedFailureV1::Identity("git-bootstrap/objects"),
                ],
            )
        },
        OwedRowV1 {
            shell: fsck_shell(|_, _| {
                "chmod u+w \"$0\"; echo '# drift' >> \"$0\"; sleep 30".to_owned()
            }),
            timed_out: true,
            recorded: 2,
            counts: CountsExpectedFailureV1 {
                mounts: Some(1),
                sources: Some(clean.object_files),
                digests: Some(files),
                ..CountsExpectedFailureV1::default()
            },
            ..OwedRowV1::new(
                "a drifted binary beside a callback that found the deadline spent",
                vec![ExpectedFailureV1::Drift, ExpectedFailureV1::Timeout],
            )
        },
        // Control: the drift alone, its post-exit callback passed.
        OwedRowV1 {
            shell: fsck_shell(|_, _| format!("\"$REAL\" \"$@\"; {DRIFT_V1}")),
            recorded: 2,
            counts: CountsExpectedFailureV1 {
                mounts: Some(1),
                sources: Some(clean.object_files),
                stats: Some(1 + clean.tree_dirs),
                digests: Some(files),
            },
            ..OwedRowV1::new("a drifted binary alone", vec![ExpectedFailureV1::Drift])
        },
    ];
    let problems = owed_problems(rows);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// REGRESSION 4 (design finding 3). The post-exit gate is a fail-fast list, and a refused mount census is the
/// first thing in it: it must not be treated as a completed gate. The child swaps a retained bootstrap directory
/// while the census refuses (a mount appears, or the census cannot list the mount points), so BOTH typed
/// failures are named: the census's refusal as the primary (the callback's), then the later chain's identity
/// change, and the mount census is made exactly once (the gate's own; it is not owed again).
#[test]
fn b2c_a_refused_mount_census_in_a_callback_does_not_hide_a_later_retained_chain_failure() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let swapped = |_: &Path, outside: &Path| {
        format!(
            "\"$REAL\" \"$@\"; mv ../.restore-work/git-bootstrap/objects {o}/objects-away; mkdir ../.restore-work/git-bootstrap/objects",
            o = outside.display()
        )
    };
    let rows: Vec<OwedRowV1> = [
        (
            "a mount appeared as the child exited, beside a swapped bootstrap directory",
            MountsAfterV1::Appears,
        ),
        (
            "the mount census could not list the mount points, beside a swapped bootstrap directory",
            MountsAfterV1::Fails,
        ),
    ]
    .into_iter()
    .map(|(name, mounts)| OwedRowV1 {
        shell: fsck_shell(swapped),
        mounts,
        recorded: 2,
        counts: CountsExpectedFailureV1 {
            mounts: Some(1),
            sources: Some(clean.object_files),
            digests: Some(files),
            ..CountsExpectedFailureV1::default()
        },
        ..OwedRowV1::new(
            name,
            vec![ExpectedFailureV1::Mount, ExpectedFailureV1::Identity("git-bootstrap/objects")],
        )
    })
    .collect();
    let problems = owed_problems(rows);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// REGRESSION 5 (design finding 4). A final child SUCCEEDS (its result and both callbacks are clean) and a
/// detached helper changes the destination while the settlement runs: it adds `.git/0stray`, rewrites HEAD in
/// place, and swaps a retained bootstrap directory. The paced settlement's census meets the stray first, and
/// that custody finding is the primary; it must not be returned alone: the bytes, the swapped chain, and the
/// mount census the paced settlement never reached are each observed once, in order, and the census that
/// produced the primary is not observed again.
#[test]
fn b2c_a_successful_final_childs_settlement_finding_is_reported_beside_every_other_owed_observation(
) {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let row = OwedRowV1 {
        helper: Some(|root, outside| {
            std::fs::write(root.join("repository/.git/0stray"), b"").expect("a stray");
            change_in_place(&root.join("repository/.git/HEAD"));
            swap_directory(&root.join(".restore-work/git-bootstrap/objects"), outside);
        }),
        counts: CountsExpectedFailureV1 {
            // The post-exit gate's own census and admitted-file rechecks, then the completion's (the settlement
            // never reached its gate), and the digest of every file once.
            mounts: Some(2),
            sources: Some(2 * clean.object_files),
            digests: Some(files),
            ..CountsExpectedFailureV1::default()
        },
        ..OwedRowV1::new(
            "a successful child's settlement meets an entry, changed bytes, and a swapped chain",
            vec![
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0stray"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Bytes, "HEAD"),
                ExpectedFailureV1::Identity("git-bootstrap/objects"),
            ],
        )
    };
    let problems = owed_problems(vec![row]);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// REGRESSION 6 (design finding 5, digests). Two restored files are rewritten in place at the same length with
/// every census clock stalled (so only a digest can see either), by a child that fails. BOTH are named, in
/// relative-path order, and the evidence that every retained descriptor was attempted is that the digest ran
/// once for every restored file (the first bad file used to stop the rest).
#[test]
fn b2c_two_restored_files_rewritten_in_place_are_both_reported_and_every_retained_descriptor_is_attempted(
) {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let row = OwedRowV1 {
        shell: fsck_shell(|_, _| {
            format!("\"$REAL\" \"$@\"; {REWRITE_HEAD_V1}; {REWRITE_ORIG_HEAD_V1}; exit 1")
        }),
        stalled: true,
        counts: CountsExpectedFailureV1 {
            mounts: Some(1),
            sources: Some(clean.object_files),
            stats: Some(1 + clean.tree_dirs),
            digests: Some(files),
        },
        ..OwedRowV1::new(
            "a failed child rewrote two restored files in place, every clock stalled",
            vec![
                ExpectedFailureV1::Child("fsck --strict", 1),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Bytes, "HEAD"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Bytes, "ORIG_HEAD"),
            ],
        )
    };
    let problems = owed_problems(vec![row]);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// REGRESSION 7 (design finding 5, chains). Two retained chain entries (a staging directory and a bootstrap
/// directory) and then the destination root are swapped. Every edge is its own unit: all three identity
/// failures are named in custody order and the root is LAST, for a child the runner timed out (its gate never
/// ran) and for a child whose post-exit gate refused at the first of them (the units it had run are not
/// repeated, and the ones after it are still observed).
#[test]
fn b2c_two_swapped_retained_chain_entries_and_a_swapped_root_are_all_reported_with_the_root_last() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let identities = || {
        vec![
            ExpectedFailureV1::Identity("plain/control"),
            ExpectedFailureV1::Identity("git-bootstrap/objects"),
            ExpectedFailureV1::Identity("pinned scan root"),
        ]
    };
    let rows = vec![
        OwedRowV1 {
            shell: fsck_shell(|root, outside| format!("{}; sleep 30", swaps_of(root, outside))),
            timed_out: true,
            recorded: 2,
            counts: CountsExpectedFailureV1 {
                mounts: Some(1),
                sources: Some(clean.object_files),
                digests: Some(files),
                ..CountsExpectedFailureV1::default()
            },
            ..OwedRowV1::new(
                "a timed-out child swapped two chain entries and the root",
                [vec![ExpectedFailureV1::Timeout], identities()].concat(),
            )
        },
        OwedRowV1 {
            shell: fsck_shell(|root, outside| {
                format!("\"$REAL\" \"$@\"; {}", swaps_of(root, outside))
            }),
            recorded: 2,
            counts: CountsExpectedFailureV1 {
                // The post-exit gate ran the census and the admitted-file rechecks before the first swapped
                // entry (the staging chains come after the admitted files), and the units after it are the
                // completion's: no census and no admitted-file recheck is repeated.
                mounts: Some(1),
                sources: Some(clean.object_files),
                digests: Some(files),
                ..CountsExpectedFailureV1::default()
            },
            ..OwedRowV1::new(
                "a child exited after swapping two chain entries and the root",
                identities(),
            )
        },
    ];
    let problems = owed_problems(rows);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// The destination root's and two retained entries' swaps, as one shell fragment.
fn swaps_of(root: &Path, outside: &Path) -> String {
    let o = outside.display();
    format!(
        "mv ../.restore-work/plain/control {o}/control-away; mkdir ../.restore-work/plain/control; mv ../.restore-work/git-bootstrap/objects {o}/objects-away; mkdir ../.restore-work/git-bootstrap/objects; mv {r} {o}/root-away; mkdir {r}",
        r = root.display()
    )
}

/// REGRESSION 8 (design finding 6). The failure-only digest of a child that already failed has no clock, so an
/// `Interrupted` read must never be retried: it is ONE typed I/O refusal for that file, the later files are
/// still observed, and the number of read calls is finite (the interrupted file is read once; every other file
/// at most `length / buffer + 2` times). The injection is finite (64 interruptions), so the unrepaired retry
/// ends and the test cannot hang.
#[test]
fn b2c_an_interrupted_failure_only_digest_read_is_one_typed_refusal_with_no_retry_and_a_finite_read_count(
) {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let watch = watch_reconcile_reads_for_test(Some(("HEAD", 64)));
    let route = RouteV1::new(&[("fsck --strict", &final_only("\"$REAL\" \"$@\"; exit 1"))]);
    let ran = run_plane(input, &route, far_deadline());
    let calls = reconcile_read_calls_for_test();
    drop(watch);
    let failure = ran.failure("a failed child whose HEAD digest read is interrupted");
    let held = leaves(&failure.cause);
    let want = [
        ExpectedFailureV1::Child("fsck --strict", 1),
        ExpectedFailureV1::Io("HEAD"),
    ];
    let mut problems = Vec::new();
    if held.len() != want.len() || !held.iter().zip(&want).all(|(error, want)| want.is(error)) {
        problems.push(format!("the typed failures were {held:?}, wanted {want:?}"));
    }
    let git = stored(&ran.dest, "repository/.git");
    let lengths: BTreeMap<String, u64> = snapshot(&git)
        .into_iter()
        .filter_map(|(name, bytes)| bytes.map(|bytes| (name, bytes.len() as u64)))
        .collect();
    if calls.keys().collect::<Vec<_>>() != lengths.keys().collect::<Vec<_>>() {
        problems.push(format!("not every restored file was attempted: {calls:?}"));
    }
    if calls.get("HEAD") != Some(&1) {
        problems.push(format!(
            "the interrupted read was made {:?} times, never to be retried: {calls:?}",
            calls.get("HEAD")
        ));
    }
    for (file, length) in &lengths {
        let bound = length / HASH_BUFFER_BYTES_V1 as u64 + 2;
        let made = calls.get(file).copied().unwrap_or(0);
        if made == 0 || u64::from(made) > bound {
            problems.push(format!("{file}: {made} read calls, between 1 and {bound}"));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// CONTROLS of the eight rows above. (a) A pre-spawn callback refusal: the child never starts, no gate work is
/// replayed (the one mount census and one sweep of the admitted files are the gate's own), and the tree is
/// observed once. (b) A failed child whose post-exit gate ran to its end owes only the tree: the gate's own one
/// mount census and one sweep are not repeated. (c) A clean timeout stays the bare timeout. (d) A name replaced by
/// another inode holding DIFFERENT bytes of the same length is refused as a replacement and the replacement's
/// bytes are never read: the original inode's retained descriptor is clean, so there is no byte finding.
#[test]
fn b2c_controls_a_refused_pre_spawn_gate_is_not_replayed_and_a_completed_post_exit_gate_is_not_repeated(
) {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let one_census = 1 + clean.tree_dirs;
    let rows = vec![
        OwedRowV1 {
            pre_spawn: Some(|root, outside| {
                swap_directory(&root.join(".restore-work/git-bootstrap/objects"), outside);
            }),
            count_from_pre_spawn: true,
            children: 8,
            recorded: 2,
            counts: CountsExpectedFailureV1 {
                mounts: Some(1),
                sources: Some(clean.object_files),
                stats: Some(one_census),
                digests: Some(files),
            },
            ..OwedRowV1::new(
                "(a) a pre-spawn callback refused a swapped bootstrap directory",
                vec![ExpectedFailureV1::Identity("git-bootstrap/objects")],
            )
        },
        OwedRowV1 {
            shell: fsck_shell(|_, _| "\"$REAL\" \"$@\"; exit 1".to_owned()),
            counts: CountsExpectedFailureV1 {
                mounts: Some(1),
                sources: Some(clean.object_files),
                stats: Some(one_census),
                digests: Some(files),
            },
            ..OwedRowV1::new(
                "(b) a failed child that left nothing, its post-exit gate completed",
                vec![ExpectedFailureV1::Child("fsck --strict", 1)],
            )
        },
        OwedRowV1 {
            shell: fsck_shell(|_, _| "sleep 30".to_owned()),
            timed_out: true,
            recorded: 2,
            counts: CountsExpectedFailureV1 {
                mounts: Some(1),
                sources: Some(clean.object_files),
                stats: Some(one_census),
                digests: Some(files),
            },
            ..OwedRowV1::new(
                "(c) a timed-out child that left nothing",
                vec![ExpectedFailureV1::Timeout],
            )
        },
        OwedRowV1 {
            shell: fsck_shell(|_, _| {
                "\"$REAL\" \"$@\"; cp .git/HEAD .git/HEAD.new; printf Y | dd of=.git/HEAD.new bs=1 seek=10 conv=notrunc 2>/dev/null; mv .git/HEAD.new .git/HEAD".to_owned()
            }),
            recorded: 2,
            ..OwedRowV1::new(
                "(d) HEAD replaced by another inode with different bytes of the same length",
                vec![
                    ExpectedFailureV1::Identity(".git/HEAD"),
                    ExpectedFailureV1::Tree(FinalTreeFaultV1::Replaced, "HEAD"),
                ],
            )
        },
    ];
    let problems = owed_problems(rows);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// EDGE CONTROLS of the failure-only digest, which observes one retained descriptor per file and never a name.
/// (1) A retained file the child TRUNCATED is resized: the descriptor's own `fstat` says so, so it is one byte
/// finding (the census names the same fault of the same file, reported once), its content is never read, and
/// every other restored file is still observed. (2) A file that SHRINKS between the digest's binding and its read
/// reads short and is the file's own typed byte finding; the digests of the other files still run.
#[test]
fn b2c_edge_a_resized_or_shrunk_retained_file_is_its_own_byte_finding_and_never_hides_the_others() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let mut problems = Vec::new();

    // (1) The truncated HEAD, with the read calls counted.
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let watch = watch_reconcile_reads_for_test(None);
    let route = RouteV1::new(&[(
        "fsck --strict",
        &final_only("\"$REAL\" \"$@\"; : > .git/HEAD; exit 1"),
    )]);
    let ran = run_plane(input, &route, far_deadline());
    let calls = reconcile_read_calls_for_test();
    drop(watch);
    let failure = ran.failure("a child truncated HEAD");
    let held = leaves(&failure.cause);
    let want = [
        ExpectedFailureV1::Identity(".git/HEAD"),
        ExpectedFailureV1::Tree(FinalTreeFaultV1::Bytes, "HEAD"),
    ];
    if held.len() != want.len() || !held.iter().zip(&want).all(|(error, want)| want.is(error)) {
        problems.push(format!(
            "(1) the typed failures were {held:?}, wanted {want:?}"
        ));
    }
    if calls.contains_key("HEAD") {
        problems.push(format!(
            "(1) the truncated file's content was read: {calls:?}"
        ));
    }
    if calls.len() != files - 1 {
        problems.push(format!(
            "(1) {} of the {} other restored files were observed: {calls:?}",
            calls.len(),
            files - 1
        ));
    }

    // (2) HEAD shrinks after the digest bound its descriptor and before it read.
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let started = std::rc::Rc::new(std::cell::Cell::new(false));
    let digests = std::rc::Rc::new(std::cell::Cell::new(0_usize));
    let shrunk = std::rc::Rc::new(std::cell::Cell::new(false));
    let before = started.clone();
    let _before = install_git_hook_for_test(GitHookPointV1::BeforeFinalChild, move |event| {
        if event.label == "fsck --strict" {
            before.set(true);
        }
    });
    let (counting, counted) = (started.clone(), digests.clone());
    let _opened = install_git_hook_for_test(GitHookPointV1::FinalDigestFileOpened, move |_| {
        if counting.get() {
            counted.set(counted.get() + 1);
        }
    });
    let (armed, done) = (started.clone(), shrunk.clone());
    let _shrink = install_git_hook_for_test(GitHookPointV1::FinalDigestOpened, move |event| {
        if armed.get() && !done.get() {
            done.set(true);
            std::fs::OpenOptions::new()
                .write(true)
                .open(event.path)
                .and_then(|file| file.set_len(5))
                .expect("the digested file shrinks");
        }
    });
    let route = RouteV1::new(&[("fsck --strict", &final_only("\"$REAL\" \"$@\"; exit 1"))]);
    let ran = run_plane(input, &route, far_deadline());
    let failure = ran.failure("a file shrank under its digest");
    let held = leaves(&failure.cause);
    let want = [
        ExpectedFailureV1::Child("fsck --strict", 1),
        ExpectedFailureV1::Tree(FinalTreeFaultV1::Bytes, "HEAD"),
    ];
    if !shrunk.get() {
        problems.push("(2) the file never shrank".to_owned());
    }
    if held.len() != want.len() || !held.iter().zip(&want).all(|(error, want)| want.is(error)) {
        problems.push(format!(
            "(2) the typed failures were {held:?}, wanted {want:?}"
        ));
    }
    if digests.get() != files {
        problems.push(format!(
            "(2) {} digests, every one of the {files} restored files owed one",
            digests.get()
        ));
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// CONTROL: a clean, successful run never reads through the failure-only digest (it is entered only after a
/// failure is known), and a failure whose digests all pass reads every restored file through it a finite,
/// small number of times, with no interruption injected.
#[test]
fn b2c_controls_a_successful_run_never_uses_the_failure_only_digest() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let watch = watch_reconcile_reads_for_test(None);
    let route = RouteV1::recorder();
    let ran = run_plane(input, &route, far_deadline());
    let calls = reconcile_read_calls_for_test();
    drop(watch);
    let _ = ran.success("a clean run");
    assert!(
        calls.is_empty(),
        "a success read through the failure-only digest: {calls:?}"
    );
}

/// The final database's refusals name the final database: a missing object in the final inventory is
/// "missing from the final repository", and the typed refusal's text never calls it the bootstrap (nor does the
/// text of an unreached final object or of a final stream that is not text); the bootstrap's own refusal, from
/// the same parser, still names the bootstrap.
#[test]
fn b2c_the_diagnostics_name_the_database_that_was_read() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    // The final inventory with a missing row.
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let route = RouteV1::new(&[(
        "cat-file --batch-all-objects",
        &final_only("\"$REAL\" \"$@\" | tail -n +2"),
    )]);
    let ran = run_plane(input, &route, far_deadline());
    let failure = ran.failure("a missing final object");
    let shown = failure.cause.to_string();
    assert!(
        matches!(&failure.cause, GitBootstrapErrorV1::InventoryMismatch(detail)
            if detail.contains("is missing from the final repository")),
        "{:?}",
        failure.cause
    );
    assert!(!shown.contains("bootstrap"), "{shown}");
    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Config));
    // Every other refusal of the final proof's streams reads the same: an object the final reachability did
    // not reach, and a final stream that is not text, never call the final database the bootstrap.
    for (label, shell, wanted) in [
        (
            "rev-list --objects",
            "\"$REAL\" \"$@\" | tail -n +2",
            "was not reached",
        ),
        (
            "cat-file --batch-all-objects",
            "\"$REAL\" \"$@\"; printf '\\377\\n'",
            "UTF-8",
        ),
    ] {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let route = RouteV1::new(&[(label, &final_only(shell))]);
        let ran = run_plane(input, &route, far_deadline());
        let failure = ran.failure(label);
        let shown = failure.cause.to_string();
        assert!(shown.contains(wanted), "{label}: {shown}");
        assert!(!shown.contains("bootstrap"), "{label}: {shown}");
        assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Config));
    }
    // The same parser over the bootstrap's own inventory.
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let route = RouteV1::new(&[(
        "cat-file --batch-all-objects",
        "\"$REAL\" \"$@\" | tail -n +2",
    )]);
    let ran = run_plane(input, &route, far_deadline());
    let failure = ran.failure("a missing bootstrap object");
    assert!(
        matches!(&failure.cause, GitBootstrapErrorV1::InventoryMismatch(detail)
            if detail.contains("is missing from the bootstrap")),
        "{:?}",
        failure.cause
    );
    assert_eq!(failure.last_completed, Some(GitPlaneStepV1::Indexing));
}

// ---------------------------------------------------------------------------------------------
// Follow-on 1 targeted repair (before follow-on 2/2): the three closed C/D/R progress classes
//
// Source follow-on 1/2 found that the progress model collapsed what had RUN into one boolean or one compound unit:
// (1) the census of the exact tree was one fail-fast unit, so a second replaced sibling went unreported and a call
// that had returned before its guard found the deadline spent was made again; (2) a paced digest's NAME refusal
// settled the retained descriptor's digest, and bytes already read were read again after the following guard;
// (3) a staging chain was one unit that replayed the work and plain entries for every key, so one refusal hid the
// next retained edge and was repeated. These rows drive the REAL wrapper over REAL Git with a routed final `fsck`
// child and the real runner, and use only hooks, the stalled-clock seam, the mount-census seam and the failure-only
// read counter that already existed at de4164. A unit is ATTEMPTED when its call returned; a returned fact is
// carried, never re-observed; every other unit still runs exactly once; a refusal of one unit settles no other.
// ---------------------------------------------------------------------------------------------

/// One event of a watched run, recorded from the final stage's entry guard on.
#[derive(Clone, Debug, PartialEq, Eq)]
enum EvV2 {
    /// A hook that stands right after a call, with the path it was made on.
    Hook(GitHookPointV1, PathBuf),
    /// One of the three hooks that open a part of a final child's bracket, with the child's label.
    Child(GitHookPointV1, &'static str),
    /// The clock was read for this step.
    Guard(&'static str),
    /// The mount census ran.
    Mount,
}

/// What a watched run calls after each recorded event, with the log so far.
type ActV2 = std::rc::Rc<dyn Fn(&[EvV2])>;

/// A watched run: the outcome, every recorded event, and every read call the failure-only digest made.
struct WatchedV2 {
    ran: PlaneRunV1,
    log: Vec<EvV2>,
    reads: BTreeMap<String, u32>,
}

/// The real wrapper under `deadline` with every hook, guard, and mount census recorded from the final stage's entry
/// guard on, and `act` called after each recorded event with the log so far (its last element is the new event).
/// The act may change the filesystem or make a call slow; it must not re-enter the wrapper.
fn run_watched_v2(
    input: PlaneInV1,
    route: &RouteV1,
    deadline: Instant,
    stalled: bool,
    act: impl Fn(&[EvV2]) + 'static,
) -> WatchedV2 {
    let log: std::rc::Rc<std::cell::RefCell<Vec<EvV2>>> = std::rc::Rc::default();
    let armed = std::rc::Rc::new(std::cell::Cell::new(false));
    let act: ActV2 = std::rc::Rc::new(act);
    let record: std::rc::Rc<dyn Fn(EvV2)> = {
        let (log, armed) = (log.clone(), armed.clone());
        std::rc::Rc::new(move |event: EvV2| {
            if !armed.get() {
                return;
            }
            log.borrow_mut().push(event);
            act(&log.borrow());
        })
    };
    let mut hooks = Vec::new();
    for point in CALL_POINTS_V1 {
        let record = record.clone();
        hooks.push(install_git_hook_for_test(point, move |event| {
            record(EvV2::Hook(point, event.path.to_path_buf()));
        }));
    }
    for point in [
        GitHookPointV1::BeforeFinalChildCensus,
        GitHookPointV1::BeforeFinalChild,
        GitHookPointV1::AfterFinalChild,
    ] {
        let record = record.clone();
        hooks.push(install_git_hook_for_test(point, move |event| {
            record(EvV2::Child(point, event.label));
        }));
    }
    {
        let (armed, record) = (armed.clone(), record.clone());
        hooks.push(install_git_hook_for_test(
            GitHookPointV1::DeadlineObserved,
            move |event| {
                if event.label == "final-entry" {
                    armed.set(true);
                }
                record(EvV2::Guard(event.label));
            },
        ));
    }
    let census = {
        let record = record.clone();
        crate::custody_mounts::seam::install(Box::new(move |_| {
            record(EvV2::Mount);
            Ok(vec![b"/".to_vec()])
        }))
    };
    let _clocks = stalled.then(|| stall_census_clocks_for_test(BOTH_CLOCKS_V1));
    let watch = watch_reconcile_reads_for_test(None);
    let ran = run_plane(input, route, deadline);
    let reads = reconcile_read_calls_for_test();
    drop(watch);
    drop(hooks);
    drop(census);
    let log = log.borrow().clone();
    WatchedV2 { ran, log, reads }
}

/// Whether the final `fsck` child's post-exit callback has begun.
fn exited_v2(log: &[EvV2]) -> bool {
    log.iter().any(|event| {
        matches!(
            event,
            EvV2::Child(GitHookPointV1::AfterFinalChild, "fsck --strict")
        )
    })
}

/// The events from the final `fsck` child's post-exit callback to the staged rewinds (or the end of the run).
fn settlement_window_v2(log: &[EvV2]) -> &[EvV2] {
    let from = log
        .iter()
        .position(|event| {
            matches!(
                event,
                EvV2::Child(GitHookPointV1::AfterFinalChild, "fsck --strict")
            )
        })
        .map_or(log.len(), |at| at + 1);
    let to = log
        .iter()
        .position(|event| *event == EvV2::Guard("final-rewind"))
        .unwrap_or(log.len())
        .max(from);
    &log[from..to]
}

fn hooks_v2(window: &[EvV2], point: GitHookPointV1) -> usize {
    window
        .iter()
        .filter(|event| matches!(event, EvV2::Hook(found, _) if *found == point))
        .count()
}

/// The typed failures of `error`, in order, against `want`, or what they were.
fn judge_leaves_v2(error: &GitBootstrapErrorV1, want: &[ExpectedFailureV1]) -> Option<String> {
    let held = leaves(error);
    (held.len() != want.len() || !held.iter().zip(want).all(|(error, want)| want.is(error)))
        .then(|| format!("the typed failures were {held:?}, wanted {want:?}"))
}

/// What every failing row of the repair keeps: the typed last step, the one ledger, every child that started,
/// the proofs that had returned, and the materialization that began.
fn judge_failure_v2(
    failure: &GitPlaneRestoreFailureV1,
    route: &RouteV1,
    clean: &FinalShapeV1,
    recorded: usize,
) -> Vec<String> {
    let mut judged = Vec::new();
    if failure.last_completed != Some(GitPlaneStepV1::Config)
        || !failure.active_materialization_began
    {
        judged.push(format!("completed {:?}", failure.last_completed));
    }
    if route.children().len() != 9 {
        judged.push(format!("children {:?}", route.children()));
    }
    if failure.partial.final_runs.len() != recorded {
        judged.push(format!(
            "{} proofs, {recorded} had returned",
            failure.partial.final_runs.len()
        ));
    }
    if failure.ledger_used != clean.ledger {
        judged.push(format!(
            "ledger {} not {}",
            failure.ledger_used, clean.ledger
        ));
    }
    judged
}

/// The restored files' relative names, in path order, as the failure retains them.
fn restored_files_v2(failure: &GitPlaneRestoreFailureV1) -> Vec<String> {
    let mut names = std::collections::BTreeSet::new();
    if let PlaneObjectsV1::Whole(objects) = &failure.partial.objects {
        names.extend(objects.files.iter().map(|file| file.relative.clone()));
    }
    if let PlaneMetadataV1::Whole(metadata) = &failure.partial.metadata {
        names.extend(metadata.files.iter().map(|file| file.relative.clone()));
    }
    names.into_iter().collect()
}

type RcCellV2<T> = std::rc::Rc<std::cell::Cell<T>>;

/// FINDING 1 (census siblings). A successful final child, then a detached helper replaces expected restored files
/// by other inodes after the post-exit gate and before the settlement's census. Every replaced sibling is its own
/// typed finding: the census meets the first and the completion goes on to the next without descending either
/// (the census used to return at the first and mark itself complete), and the chain of each is refused too. A lone
/// replacement is the control: exactly one finding of its own, never duplicated.
#[test]
fn b2c_two_replaced_census_siblings_are_both_typed_findings_and_a_lone_one_is_reported_once() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let mut problems = Vec::new();
    for (name, replaced) in [
        ("two replaced siblings", vec!["HEAD", "ORIG_HEAD"]),
        ("one replaced sibling (the control)", vec!["HEAD"]),
    ] {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let git = input.dest.path.join("repository/.git");
        let (_area, outside) = external_dir_with(&["decoy"]);
        let acted: RcCellV2<bool> = RcCellV2::default();
        let (done, files) = (acted.clone(), replaced.clone());
        let act = move |log: &[EvV2]| {
            if !done.get()
                && exited_v2(log)
                && matches!(
                    log.last(),
                    Some(EvV2::Hook(GitHookPointV1::FinalCensusStatted, _))
                )
            {
                done.set(true);
                for file in &files {
                    replace_with_other_bytes(&git.join(file), &outside);
                }
            }
        };
        let route = RouteV1::recorder();
        let watched = run_watched_v2(input, &route, far_deadline(), false, act);
        if !acted.get() {
            problems.push(format!("{name}: the replacement was never made"));
            continue;
        }
        let Err(failure) = &watched.ran.outcome else {
            problems.push(format!("{name}: a success followed the replacement"));
            continue;
        };
        let held = leaves(&failure.cause);
        let mut judged = judge_failure_v2(failure, &route, &clean, 3);
        let n = replaced.len();
        let census: Vec<ExpectedFailureV1> = replaced
            .iter()
            .map(|file| ExpectedFailureV1::Tree(FinalTreeFaultV1::Replaced, file))
            .collect();
        let chains: Vec<ExpectedFailureV1> = replaced
            .iter()
            .map(|file| match *file {
                "HEAD" => ExpectedFailureV1::Identity(".git/HEAD"),
                _ => ExpectedFailureV1::Identity(".git/ORIG_HEAD"),
            })
            .collect();
        let ordered = held.len() == 2 * n
            && held[..n]
                .iter()
                .zip(&census)
                .all(|(error, want)| want.is(error));
        // The two chains are in the restore's file order: each named exactly once, after the census's findings.
        let chained = held.len() == 2 * n
            && chains
                .iter()
                .all(|want| held[n..].iter().filter(|error| want.is(error)).count() == 1);
        if !(ordered && chained) {
            judged.push(format!(
                "the typed failures were {held:?}, wanted the census findings {census:?} then the chains {chains:?}"
            ));
        }
        if !judged.is_empty() {
            problems.push(format!("{name}: {}", judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// FINDING 1 (slow call). The settlement's census is made slow at one call (its repository `fstat`, a listing, an
/// entry's `fstatat`, a file's `open`) so that the call RETURNS after the deadline and the next guard finds it
/// spent. That call is attempted: its fact is carried and the completion never makes it again, and every unit that
/// had no call yet runs exactly once, so each kind of call is made exactly as often as one clean census makes it
/// (it used to be made again for every unit already attempted, from the repository on). The controls: no slow call
/// (a success, the same totals), and, beside a slow `fstat`, an added entry (the census reports it, and the
/// comparison with the baseline is unavailable after a faulted census: it reports nothing) and a touched file (a
/// complete clean census, so the comparison runs and reports the change).
#[test]
fn b2c_a_returned_slow_census_call_is_counted_once_and_every_unattempted_unit_still_runs_once() {
    #[derive(Clone, Copy)]
    enum Make {
        Nothing,
        Slow,
        SlowAndStray,
        SlowAndTouch,
    }
    struct RowV2 {
        name: &'static str,
        point: GitHookPointV1,
        regular_only: bool,
        make: Make,
        /// Whether the totals of every kind of call are held to one clean census's.
        totals: bool,
    }
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let files = clean.object_files + clean.metadata_files;
    let one_census = 1 + clean.tree_dirs;
    let rows = [
        RowV2 {
            name: "the repository's fstat returned late",
            point: GitHookPointV1::FinalCensusStatted,
            regular_only: false,
            make: Make::Slow,
            totals: true,
        },
        RowV2 {
            name: "a listing returned late",
            point: GitHookPointV1::FinalCensusListed,
            regular_only: false,
            make: Make::Slow,
            totals: true,
        },
        RowV2 {
            name: "a regular entry's fstatat returned late",
            point: GitHookPointV1::BeforeFinalCensusOpen,
            regular_only: true,
            make: Make::Slow,
            totals: true,
        },
        RowV2 {
            name: "a regular file's open returned late",
            point: GitHookPointV1::FinalFileOpened,
            regular_only: true,
            make: Make::Slow,
            totals: true,
        },
        RowV2 {
            name: "control: no slow call",
            point: GitHookPointV1::FinalCensusStatted,
            regular_only: false,
            make: Make::Nothing,
            totals: true,
        },
        RowV2 {
            name: "control: a slow fstat beside an added entry (the comparison is unavailable)",
            point: GitHookPointV1::FinalCensusStatted,
            regular_only: false,
            make: Make::SlowAndStray,
            totals: false,
        },
        RowV2 {
            name: "control: a slow fstat beside a touched file (a complete clean census: the comparison runs)",
            point: GitHookPointV1::FinalCensusStatted,
            regular_only: false,
            make: Make::SlowAndTouch,
            totals: false,
        },
    ];
    let problems: Vec<String> = std::thread::scope(|scope| {
        let handles: Vec<_> = rows
            .iter()
            .map(|row| {
                let (capsule, clean) = (&capsule, &clean);
                scope.spawn(move || {
                    let input = PlaneInV1::rich(capsule, CustodyGitObjectFormatV1::Sha1);
                    let git = input.dest.path.join("repository/.git");
                    let route = RouteV1::recorder();
                    let deadline = Instant::now() + B2C_DEADLINE_V1;
                    let acted: RcCellV2<bool> = RcCellV2::default();
                    let done = acted.clone();
                    let (point, regular_only, make) = (row.point, row.regular_only, row.make);
                    let act = move |log: &[EvV2]| {
                        let Some(EvV2::Hook(found, path)) = log.last() else {
                            return;
                        };
                        if matches!(make, Make::Nothing)
                            || done.get()
                            || *found != point
                            || !exited_v2(log)
                            || (regular_only && !path.is_file())
                        {
                            return;
                        }
                        done.set(true);
                        match make {
                            Make::SlowAndStray => {
                                std::fs::write(git.join("0stray"), b"").expect("a stray");
                            }
                            Make::SlowAndTouch => {
                                std::fs::OpenOptions::new()
                                    .write(true)
                                    .open(git.join("HEAD"))
                                    .and_then(|file| {
                                        file.set_modified(
                                            std::time::SystemTime::UNIX_EPOCH
                                                + Duration::from_secs(1_000_000),
                                        )
                                    })
                                    .expect("a touched file");
                            }
                            Make::Slow | Make::Nothing => {}
                        }
                        pass_the_deadline(deadline);
                    };
                    let watched = run_watched_v2(input, &route, deadline, false, act);
                    let mut judged = Vec::new();
                    if !matches!(make, Make::Nothing) && !acted.get() {
                        return vec![format!("{}: the slow call was never reached", row.name)];
                    }
                    match (&watched.ran.outcome, make) {
                        (Ok(_), Make::Nothing) => {}
                        (Ok(_), _) => judged.push("a success followed the expiry".to_owned()),
                        (Err(failure), Make::Nothing) => {
                            judged.push(format!("refused: {:?}", failure.cause));
                        }
                        (Err(failure), make) => {
                            let want: Vec<ExpectedFailureV1> = match make {
                                Make::SlowAndStray => vec![
                                    ExpectedFailureV1::Timeout,
                                    ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0stray"),
                                ],
                                Make::SlowAndTouch => {
                                    vec![ExpectedFailureV1::Timeout, ExpectedFailureV1::Changed]
                                }
                                _ => vec![ExpectedFailureV1::Timeout],
                            };
                            judged.extend(judge_leaves_v2(&failure.cause, &want));
                            judged.extend(judge_failure_v2(failure, &route, clean, 3));
                        }
                    }
                    if row.totals {
                        let window = settlement_window_v2(&watched.log);
                        for (kind, point, whole) in [
                            ("directory censuses", GitHookPointV1::FinalCensusStatted, one_census),
                            ("directory listings", GitHookPointV1::FinalCensusListed, one_census),
                            (
                                "entry censuses",
                                GitHookPointV1::BeforeFinalCensusOpen,
                                clean.tree_entries,
                            ),
                            ("file opens", GitHookPointV1::FinalFileOpened, files),
                        ] {
                            let made = hooks_v2(window, point);
                            if made != whole {
                                judged.push(format!(
                                    "{made} {kind} were made across the settlement and its completion, exactly {whole} (one clean census) owed"
                                ));
                            }
                        }
                    }
                    if judged.is_empty() {
                        Vec::new()
                    } else {
                        vec![format!("{}: {}", row.name, judged.join("; "))]
                    }
                })
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|handle| handle.join().expect("a slow-census row's thread"))
            .collect()
    });
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// FINDING 2 (name versus retained descriptor). After a CLEAN census, at the barrier before the settlement's first
/// digest open, a detached helper moves `ORIG_HEAD` away, rewrites the moved ORIGINAL inode in place at the same
/// length (as a helper holding an inherited descriptor would), and puts a link at the name. The paced digest meets
/// the link at the NAME and refuses; that settles nothing about the original inode: the completion still reads the
/// RETAINED descriptor of `ORIG_HEAD` and reports its changed bytes, then reads every later file once. `HEAD`,
/// whose paced digest ran to its verdict before the refusal, is not read again. The control leaves the original
/// clean: no byte finding, but the retained descriptor of `ORIG_HEAD` and every later file is still observed.
#[test]
fn b2c_a_name_refusal_never_settles_the_retained_original_digest_and_the_later_descriptors_run_once(
) {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let mut problems = Vec::new();
    for (name, rewrite) in [
        ("the original inode rewritten in place", true),
        ("control: the original inode left clean", false),
    ] {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let git = input.dest.path.join("repository/.git");
        let (_area, outside) = external_dir_with(&["decoy"]);
        let acted: RcCellV2<bool> = RcCellV2::default();
        let done = acted.clone();
        let act = move |log: &[EvV2]| {
            if !done.get() && exited_v2(log) && log.last() == Some(&EvV2::Guard("final-digest")) {
                done.set(true);
                let away = outside.join("ORIG_HEAD.away");
                std::fs::rename(git.join("ORIG_HEAD"), &away).expect("the original moves away");
                if rewrite {
                    change_in_place(&away);
                }
                std::os::unix::fs::symlink(outside.join("decoy"), git.join("ORIG_HEAD"))
                    .expect("a link takes the name");
            }
        };
        let route = RouteV1::recorder();
        let watched = run_watched_v2(input, &route, far_deadline(), false, act);
        if !acted.get() {
            problems.push(format!("{name}: the barrier was never reached"));
            continue;
        }
        let Err(failure) = &watched.ran.outcome else {
            problems.push(format!("{name}: a success followed the link"));
            continue;
        };
        let mut want = vec![ExpectedFailureV1::Symlink("ORIG_HEAD")];
        if rewrite {
            want.push(ExpectedFailureV1::Tree(
                FinalTreeFaultV1::Bytes,
                "ORIG_HEAD",
            ));
        }
        want.push(ExpectedFailureV1::Symlink("repository/.git/ORIG_HEAD"));
        let mut judged: Vec<String> = judge_leaves_v2(&failure.cause, &want).into_iter().collect();
        judged.extend(judge_failure_v2(failure, &route, &clean, 3));
        let files = restored_files_v2(failure);
        let observed: Vec<&String> = watched.reads.keys().collect();
        let expected: Vec<&String> = files
            .iter()
            .filter(|file| file.as_str() >= "ORIG_HEAD")
            .collect();
        if files.first().map(String::as_str) != Some("HEAD") || observed != expected {
            judged.push(format!(
                "the retained descriptors observed were {observed:?}, wanted ORIG_HEAD and every later file {expected:?} (HEAD, before it, ran to its paced verdict; restored files {files:?})"
            ));
        }
        for (file, calls) in &watched.reads {
            if *calls == 0 || u64::from(*calls) > 64 {
                judged.push(format!("{file}: {calls} read calls"));
            }
        }
        if !judged.is_empty() {
            problems.push(format!("{name}: {}", judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// FINDING 2 (bytes already read). A successful child rewrote `HEAD` in place with every clock stalled (only the
/// digest sees it), and the settlement's paced digest of `HEAD` RETURNS its bytes; the call after it is made slow
/// past the deadline, so the next guard finds it spent. Those bytes were read: the completion carries them, reports
/// their verdict (here the changed bytes, though the helper has since put the original byte back, so a second read
/// would see a clean file), and does not read `HEAD` again, while every later file is read once. The control makes
/// the call BEFORE the read slow instead: no bytes had returned, so the retained descriptor of `HEAD` is read once.
#[test]
fn b2c_a_timeout_after_the_paced_digest_bytes_returned_does_not_reread_them() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let mut problems = Vec::new();
    for (name, point, restore, carried) in [
        (
            "the digest's read returned, then the guard found the deadline spent",
            GitHookPointV1::FinalDigestHashed,
            true,
            true,
        ),
        (
            "control: the binding fstat returned (no byte read), then the read found the deadline spent",
            GitHookPointV1::FinalDigestOpened,
            false,
            false,
        ),
    ] {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let head = input.dest.path.join("repository/.git/HEAD");
        let route = RouteV1::new(&[("fsck --strict", &final_only(&format!("\"$REAL\" \"$@\"; {REWRITE_HEAD_V1}")))]);
        let deadline = Instant::now() + B2C_DEADLINE_V1;
        let original: RcCellV2<Option<u8>> = RcCellV2::default();
        let slowed: RcCellV2<bool> = RcCellV2::default();
        let (remember, done) = (original.clone(), slowed.clone());
        let act = move |log: &[EvV2]| {
            match log.last() {
                Some(EvV2::Child(GitHookPointV1::BeforeFinalChild, "fsck --strict")) => {
                    remember.set(std::fs::read(&head).ok().and_then(|bytes| bytes.get(10).copied()));
                }
                Some(EvV2::Hook(found, path))
                    if *found == point
                        && !done.get()
                        && exited_v2(log)
                        && path.ends_with("repository/.git/HEAD") =>
                {
                    done.set(true);
                    if restore {
                        use std::os::unix::fs::FileExt as _;
                        let byte = remember.get().expect("the original byte");
                        std::fs::OpenOptions::new()
                            .write(true)
                            .open(path)
                            .and_then(|file| file.write_all_at(&[byte], 10))
                            .expect("the original byte is put back");
                    }
                    pass_the_deadline(deadline);
                }
                _ => {}
            }
        };
        let watched = run_watched_v2(input, &route, deadline, true, act);
        if !slowed.get() {
            problems.push(format!("{name}: the slow call was never reached"));
            continue;
        }
        let Err(failure) = &watched.ran.outcome else {
            problems.push(format!("{name}: a success followed the expiry"));
            continue;
        };
        let want = [
            ExpectedFailureV1::Timeout,
            ExpectedFailureV1::Tree(FinalTreeFaultV1::Bytes, "HEAD"),
        ];
        let mut judged: Vec<String> = judge_leaves_v2(&failure.cause, &want).into_iter().collect();
        judged.extend(judge_failure_v2(failure, &route, &clean, 3));
        let files = restored_files_v2(failure);
        let observed: Vec<&String> = watched.reads.keys().collect();
        let expected: Vec<&String> = files
            .iter()
            .filter(|file| {
                if carried {
                    file.as_str() > "HEAD"
                } else {
                    file.as_str() >= "HEAD"
                }
            })
            .collect();
        if observed != expected {
            judged.push(format!(
                "the retained descriptors read were {observed:?}, wanted {expected:?} (HEAD's bytes {} returned)",
                if carried { "had" } else { "had not" }
            ));
        }
        if !judged.is_empty() {
            problems.push(format!("{name}: {}", judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// A nested staging directory `parent/child`, created beneath the retained pin of the staging directory `parent` and
/// retained as a staging key of its own, so that a staging chain has a prefix that is itself a retained edge (the
/// fixture's staging directories are all one deep). Nothing is charged: it is an extra retained edge for the rows,
/// not a restore step.
fn add_nested_staging_v2(input: &PlaneInV1, parent: &[u8], child: &str) {
    let destination = &input.verified.destination;
    let nested = {
        let staging = destination.staging.borrow();
        let pin = staging.get(parent).unwrap_or_else(|| {
            panic!(
                "no staging directory {:?} among {:?}",
                String::from_utf8_lossy(parent),
                staging
                    .keys()
                    .map(|key| String::from_utf8_lossy(key).into_owned())
                    .collect::<Vec<_>>()
            )
        });
        pin.create_new_child_directory(std::ffi::OsStr::new(child), "a nested staging directory")
            .expect("a nested staging directory")
    };
    let mut key = parent.to_vec();
    key.push(b'/');
    key.extend_from_slice(child.as_bytes());
    destination
        .staging
        .borrow_mut()
        .insert(key, std::rc::Rc::new(nested));
}

/// FINDING 3 (staging edges). The work directory and the plain directory beneath it are swapped TOGETHER (plain
/// first, beneath the retained work directory, then the work directory beneath the retained root), so each retained
/// edge is refused for its own reason: both identities are named, exactly once each, in custody order, and the
/// root is the LAST unit when it is swapped too (a refusal of the work edge used to hide the plain edge and to
/// repeat itself for every staging key). A bootstrap-directory swap alone is the control. A clean completion
/// rechecks each retained staging edge exactly once: the work and plain entries and each staging directory, with no
/// replay of a common prefix.
#[test]
fn b2c_work_and_plain_swapped_together_are_both_reported_once_each_with_unique_prefixes_and_the_root_last(
) {
    struct RowV2 {
        name: &'static str,
        shell: ShellV1,
        timed_out: bool,
        /// Whether a nested staging directory `control/nested` is retained as a staging key too.
        nested: bool,
        recorded: usize,
        want: Vec<ExpectedFailureV1>,
    }
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    assert!(
        !clean.staging_depths.is_empty(),
        "the fixture holds a staging directory"
    );
    let work_name = || ExpectedFailureV1::Identity(".restore-work: ");
    let plain_name = || ExpectedFailureV1::Identity(".restore-work/plain");
    let rows = vec![
        RowV2 {
            name: "a child exited after swapping plain and then work",
            shell: |_, outside| {
                format!(
                    "\"$REAL\" \"$@\"; mv ../.restore-work/plain ../.restore-work/plain.away; mkdir ../.restore-work/plain; mv ../.restore-work {o}/work-away; mkdir ../.restore-work",
                    o = outside.display()
                )
            },
            timed_out: false,
            nested: false,
            recorded: 2,
            want: vec![work_name(), plain_name()],
        },
        RowV2 {
            name: "a timed-out child swapped plain and then work",
            shell: |_, outside| {
                format!(
                    "mv ../.restore-work/plain ../.restore-work/plain.away; mkdir ../.restore-work/plain; mv ../.restore-work {o}/work-away; mkdir ../.restore-work; sleep 30",
                    o = outside.display()
                )
            },
            timed_out: true,
            nested: false,
            recorded: 2,
            want: vec![ExpectedFailureV1::Timeout, work_name(), plain_name()],
        },
        RowV2 {
            name: "a timed-out child swapped plain, then work, then the root",
            shell: |root, outside| {
                format!(
                    "mv ../.restore-work/plain ../.restore-work/plain.away; mkdir ../.restore-work/plain; mv ../.restore-work {o}/work-away; mkdir ../.restore-work; mv {r} {o}/root-away; mkdir {r}; sleep 30",
                    o = outside.display(),
                    r = root.display()
                )
            },
            timed_out: true,
            nested: false,
            recorded: 2,
            want: vec![
                ExpectedFailureV1::Timeout,
                work_name(),
                plain_name(),
                ExpectedFailureV1::Identity("pinned scan root"),
            ],
        },
        RowV2 {
            name: "control: a timed-out child swapped one bootstrap directory",
            shell: |_, outside| {
                format!(
                    "mv ../.restore-work/git-bootstrap/objects {o}/objects-away; mkdir ../.restore-work/git-bootstrap/objects; sleep 30",
                    o = outside.display()
                )
            },
            timed_out: true,
            nested: false,
            recorded: 2,
            want: vec![
                ExpectedFailureV1::Timeout,
                ExpectedFailureV1::Identity("git-bootstrap/objects"),
            ],
        },
        RowV2 {
            name:
                "a timed-out child swapped a nested staging directory and then its retained parent",
            shell: |_, outside| {
                format!(
                    "mv ../.restore-work/plain/control/nested {o}/nested-away; mkdir ../.restore-work/plain/control/nested; mv ../.restore-work/plain/control {o}/control-away; mkdir ../.restore-work/plain/control; sleep 30",
                    o = outside.display()
                )
            },
            timed_out: true,
            nested: true,
            recorded: 2,
            want: vec![
                ExpectedFailureV1::Timeout,
                ExpectedFailureV1::Identity(".restore-work/plain/control: "),
                ExpectedFailureV1::Identity(".restore-work/plain/control/nested"),
            ],
        },
        RowV2 {
            name: "control: a timed-out child that left nothing is the bare timeout",
            shell: |_, _| "sleep 30".to_owned(),
            timed_out: true,
            nested: true,
            recorded: 2,
            want: vec![ExpectedFailureV1::Timeout],
        },
    ];
    let mut problems = Vec::new();
    for row in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        if row.nested {
            add_nested_staging_v2(&input, b"control", "nested");
        }
        let retained_staging = input.verified.destination.staging.borrow().len();
        let root = input.dest.path.clone();
        let (_area, outside) = external_dir_with(&["decoy"]);
        let body = final_only(&(row.shell)(&root, &outside));
        let route = RouteV1::new(&[("fsck --strict", body.as_str())]);
        let deadline = if row.timed_out {
            Instant::now() + B2C_DEADLINE_V1
        } else {
            far_deadline()
        };
        let watched = run_watched_v2(input, &route, deadline, false, |_| {});
        let Err(failure) = &watched.ran.outcome else {
            problems.push(format!("{}: a success", row.name));
            continue;
        };
        let mut judged: Vec<String> = judge_leaves_v2(&failure.cause, &row.want)
            .into_iter()
            .collect();
        judged.extend(judge_failure_v2(failure, &route, &clean, row.recorded));
        if row
            .name
            .starts_with("control: a timed-out child that left nothing")
        {
            // No gate saw a timed-out child, so the whole staging chain is the completion's: each retained edge
            // (work, plain, and every staging directory) exactly once.
            let staging = hooks_v2(
                settlement_window_v2(&watched.log),
                GitHookPointV1::FinalStagingChecked,
            );
            let whole = 2 + retained_staging;
            if staging != whole {
                judged.push(format!(
                    "{staging} staging rechecks, exactly {whole} (work, plain, and {retained_staging} retained staging directories, each once) owed"
                ));
            }
        }
        if !judged.is_empty() {
            problems.push(format!("{}: {}", row.name, judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// FINDING 3 (admitted source files). A retained admitted bootstrap file is two calls: its entry by name, and its
/// retained descriptor. The post-exit gate's guard between them finds the deadline spent: the entry check had
/// returned, so it is attempted and the completion does not make it again, while the descriptor check (no call
/// yet) is made: each admitted file's entry is checked exactly once across the gate and its completion.
#[test]
fn b2c_a_gate_stopped_between_an_admitted_files_two_calls_does_not_repeat_the_first() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
    let route = RouteV1::recorder();
    let deadline = Instant::now() + B2C_DEADLINE_V1;
    let slowed: RcCellV2<bool> = RcCellV2::default();
    let done = slowed.clone();
    let act = move |log: &[EvV2]| {
        if !done.get()
            && exited_v2(log)
            && matches!(
                log.last(),
                Some(EvV2::Hook(GitHookPointV1::FinalSourceStatted, _))
            )
        {
            done.set(true);
            pass_the_deadline(deadline);
        }
    };
    let watched = run_watched_v2(input, &route, deadline, false, act);
    assert!(slowed.get(), "the slow call was never reached");
    let Err(failure) = &watched.ran.outcome else {
        panic!("a success followed the expiry");
    };
    let mut judged: Vec<String> = judge_leaves_v2(&failure.cause, &[ExpectedFailureV1::Timeout])
        .into_iter()
        .collect();
    judged.extend(judge_failure_v2(failure, &route, &clean, 2));
    let window = settlement_window_v2(&watched.log);
    let checked = hooks_v2(window, GitHookPointV1::FinalSourceStatted);
    if checked != clean.object_files {
        judged.push(format!(
            "{checked} admitted-file entry checks across the gate and its completion, exactly {} (each file once) owed",
            clean.object_files
        ));
    }
    let mounts = window.iter().filter(|event| **event == EvV2::Mount).count();
    if mounts != 1 {
        judged.push(format!("{mounts} mount censuses, the gate's own one owed"));
    }
    assert!(judged.is_empty(), "{}", judged.join("\n"));
}

/// STRUCTURAL ONLY (it reads the production source, so it is evidence of shape, never of behavior; the behavioral
/// evidence is every row above). Every unit of the retained chains is ONE guard and ONE call: the staging chain is
/// not a function of its own that replays a prefix, the sweep's staging edges are single-call units, and an
/// admitted bootstrap file's two calls are two units.
#[test]
fn b2c_every_retained_chain_unit_is_one_guard_and_one_call_in_the_source() {
    let source = include_str!("custody_restore_git.rs");
    assert!(
        !source.contains("fn final_staging_chain("),
        "no compound staging chain that replays work, plain, and every prefix per key"
    );
    for function in [
        "fn final_sweep_chains(",
        "fn final_source_files_unchanged(",
        "fn final_output_chains(",
    ] {
        let body = body_of(source, function);
        let code: String = body
            .lines()
            .filter(|line| !line.trim_start().starts_with("//"))
            .collect::<Vec<_>>()
            .join("\n");
        let units: Vec<&str> = code.split("pass.unit(").skip(1).collect();
        assert!(!units.is_empty(), "{function} runs its steps as units");
        for unit in units {
            // A unit's closure ends at the next `pass.unit(`: ONE guard (its own, before its call), and, for the
            // functions whose units have a single call site, ONE call.
            let guards = unit.matches("pace(").count();
            let calls = unit.matches("recheck_entry(").count()
                + unit.matches("child_metadata_no_follow(").count()
                + unit.matches(".metadata()").count()
                + unit.matches("pinned_root_unchanged(").count();
            assert!(
                guards == 1 && (function == "fn final_sweep_chains(" || calls <= 1),
                "{function}: a unit holds {guards} guards and {calls} calls: {unit}"
            );
        }
    }
}

/// FINDING 1 (every kind of census finding). A successful child, then a detached helper makes TWO simultaneous
/// changes of different kinds after the post-exit gate and before the settlement's census: two unexpected files, a
/// link and a FIFO where restored files were, two restored files removed, an unexpected file beside a removed one,
/// an unexpected entry beside the repository and beside a replaced file, an unexpected file beside a replaced one,
/// and a replaced directory beside a replaced file; and two added names, which spend the census's one shared listing
/// bound (a `Bound` finding that ends the census, as it always did). Each is its own typed finding of the census, in the census's own (byte) order, none hides
/// another, and none is descended or opened (a link and a FIFO are only `fstatat`ed: the run does not hang on the
/// FIFO). The settlement's census meets the first as the primary and the completion continues with the rest.
#[test]
fn b2c_every_kind_of_census_finding_is_kept_beside_its_siblings_and_none_is_descended() {
    struct RowV2 {
        name: &'static str,
        act: fn(&Path, &Path),
        /// The census's own findings, in order (the chains' and digests' are not judged here).
        want: Vec<ExpectedFailureV1>,
    }
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let rows = vec![
        RowV2 {
            // The census's listing budget is one name more than the restore made, shared by every listing: two added
            // names spend it at the last listing, which is a `Bound` finding and the end of the census (the retained
            // bound; nothing past it is listed).
            name: "two unexpected files exhaust the one shared listing bound",
            act: |root, _| {
                for name in ["0a", "0b"] {
                    std::fs::write(root.join("repository/.git").join(name), b"").expect("a stray");
                }
            },
            want: vec![
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0a"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0b"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Bound, "repository/.git/refs/heads"),
            ],
        },
        RowV2 {
            name: "an unexpected file and a removed file",
            act: |root, _| {
                std::fs::write(root.join("repository/.git/0a"), b"").expect("a stray");
                std::fs::remove_file(root.join("repository/.git/HEAD")).expect("a removed file");
            },
            want: vec![
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0a"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Missing, "HEAD"),
            ],
        },
        RowV2 {
            name: "a link and a FIFO where restored files were",
            act: |root, outside| {
                replace_with_link(&root.join("repository/.git/HEAD"), outside);
                replace_with_fifo(&root.join("repository/.git/ORIG_HEAD"), outside);
            },
            want: vec![
                ExpectedFailureV1::Symlink("HEAD"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Special, "ORIG_HEAD"),
            ],
        },
        RowV2 {
            name: "two restored files removed",
            act: |root, _| {
                for name in ["HEAD", "ORIG_HEAD"] {
                    std::fs::remove_file(root.join("repository/.git").join(name))
                        .expect("a removed file");
                }
            },
            want: vec![
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Missing, "HEAD"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Missing, "ORIG_HEAD"),
            ],
        },
        RowV2 {
            name: "an unexpected entry beside the repository and a replaced file",
            act: |root, outside| {
                std::fs::write(root.join("repository/0stray"), b"").expect("a stray");
                replace_with_other_bytes(&root.join("repository/.git/HEAD"), outside);
            },
            want: vec![
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0stray"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Replaced, "HEAD"),
            ],
        },
        RowV2 {
            name: "an unexpected file beside a replaced one",
            act: |root, outside| {
                std::fs::write(root.join("repository/.git/0stray"), b"").expect("a stray");
                replace_with_other_bytes(&root.join("repository/.git/HEAD"), outside);
            },
            want: vec![
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0stray"),
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Replaced, "HEAD"),
            ],
        },
        RowV2 {
            name: "a replaced directory beside a replaced file",
            act: |root, outside| {
                replace_with_other_bytes(&root.join("repository/.git/HEAD"), outside);
                swap_directory(&root.join("repository/.git/objects/info"), outside);
            },
            want: vec![
                ExpectedFailureV1::Tree(FinalTreeFaultV1::Replaced, "HEAD"),
                ExpectedFailureV1::Identity(
                    "objects/info: the entry is no longer the retained directory",
                ),
            ],
        },
    ];
    let mut problems = Vec::new();
    for row in rows {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let root = input.dest.path.clone();
        let (_area, outside) = external_dir_with(&["decoy"]);
        let acted: RcCellV2<bool> = RcCellV2::default();
        let (done, act) = (acted.clone(), row.act);
        let hook = move |log: &[EvV2]| {
            if !done.get()
                && exited_v2(log)
                && matches!(
                    log.last(),
                    Some(EvV2::Hook(GitHookPointV1::FinalCensusStatted, _))
                )
            {
                done.set(true);
                act(&root, &outside);
            }
        };
        let route = RouteV1::recorder();
        let watched = run_watched_v2(input, &route, far_deadline(), false, hook);
        if !acted.get() {
            problems.push(format!("{}: the change was never made", row.name));
            continue;
        }
        let Err(failure) = &watched.ran.outcome else {
            problems.push(format!("{}: a success followed the change", row.name));
            continue;
        };
        // The census's own findings: the tree faults and the links it met beneath a name of the Git directory
        // (the chains' refusals name `repository/.git/...`, and no digest of a replaced original can fail here).
        let held: Vec<&GitBootstrapErrorV1> = leaves(&failure.cause)
            .into_iter()
            .filter(|error| match error {
                GitBootstrapErrorV1::FinalTree { .. } => true,
                GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { name })
                | GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::IdentityChanged(name)) => {
                    !name.starts_with("repository/")
                }
                _ => false,
            })
            .collect();
        let mut judged = judge_failure_v2(failure, &route, &clean, 3);
        if held.len() != row.want.len()
            || !held
                .iter()
                .zip(&row.want)
                .all(|(error, want)| want.is(error))
        {
            judged.push(format!(
                "the census's findings were {held:?}, wanted {:?}",
                row.want
            ));
        }
        if !judged.is_empty() {
            problems.push(format!("{}: {}", row.name, judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// FINDING 3 (independent units of one admitted file). An admitted bootstrap file is checked twice, by its entry
/// NAME and by its RETAINED descriptor, and the two are independent units. A child that grows the original inode (an
/// append through a hard link) and then puts another inode at the name makes BOTH refuse, for different reasons:
/// the post-exit gate refuses the entry (the child's failure) and the completion still makes the descriptor's own
/// check and names its length (the whole compound unit used to be settled by the first refusal). A control puts
/// another inode with the same bytes at the name and leaves the original alone: only the entry refuses.
#[test]
fn b2c_an_admitted_files_entry_and_its_retained_descriptor_are_independent_units() {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let mut problems = Vec::new();
    let grown_shell = format!("{APPEND_FIXTURE_BYTE_SH_V1}\n\"$REAL\" \"$@\"; for f in ../.restore-work/git-bootstrap/objects/pack/*.pack; do ln \"$f\" \"$f.keep\" || exit 97; append_fixture_byte \"$f.keep\"; cp \"$f.keep\" \"$f.new\" || exit 97; mv \"$f.new\" \"$f\" || exit 97; done");
    for (name, shell, want) in [
        (
            "the original grown and another inode at the name",
            grown_shell.as_str(),
            vec![
                ExpectedFailureV1::Identity("no longer the admitted object file"),
                ExpectedFailureV1::Identity("the retained descriptor is no longer the admitted object file"),
            ],
        ),
        (
            "control: another inode with the same bytes at the name, the original untouched",
            "\"$REAL\" \"$@\"; for f in ../.restore-work/git-bootstrap/objects/pack/*.pack; do cp \"$f\" \"$f.new\"; mv \"$f.new\" \"$f\"; done",
            vec![ExpectedFailureV1::Identity("no longer the admitted object file")],
        ),
    ] {
        let input = PlaneInV1::rich(&capsule, CustodyGitObjectFormatV1::Sha1);
        let body = final_only(shell);
        let route = RouteV1::new(&[("fsck --strict", body.as_str())]);
        let watched = run_watched_v2(input, &route, far_deadline(), false, |_| {});
        let Err(failure) = &watched.ran.outcome else {
            problems.push(format!("{name}: a success"));
            continue;
        };
        let mut judged: Vec<String> = judge_leaves_v2(&failure.cause, &want).into_iter().collect();
        judged.extend(judge_failure_v2(failure, &route, &clean, 2));
        if !judged.is_empty() {
            problems.push(format!("{name}: {}", judged.join("; ")));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

// ---------------------------------------------------------------------------------------------
// Lossless census (same-artifact repair after source round 4 and design follow-on 2/2). A census unit is
// keyed by the object it OBSERVES: the exact bytes of one directory entry, read through
// `OsStr::from_bytes`. Two different raw names are two units even when their lossy renderings are the same
// string (`ff` and `fe` both render as U+FFFD, and so does the valid `ef bf bd`), a rendered name never
// decides membership, a missing check, a returned fact, or a duplicate, and an unexpected, linked, or special
// entry is never opened or descended. Every row below acts AFTER the final `fsck` child has exited and BEFORE
// the settlement's first listing, exactly as the census rows above do, and keeps the shared listing bound's
// total constant (each row removes as many expected entries as it adds, so the bound never ends the census).
// A row records everything it observes (raw attempts from the hooks' paths as bytes, the typed findings, the
// listing count) BEFORE any assertion, and a family judges all of its rows together. A CAUSAL row names a
// collision the repair removes; a CONTROL names a separation that already held and must hold after.
// ---------------------------------------------------------------------------------------------

/// The kind of one raw entry a row adds.
#[cfg(target_os = "linux")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RawKindV3 {
    Regular,
    Link,
    Fifo,
}

/// Where a row makes the one deadline pass.
#[cfg(target_os = "linux")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RawStopV3 {
    /// Never: the paced settlement meets the first finding.
    Never,
    /// Right after the `.git` listing RETURNED: the paced pass stops at the first entry's guard (the typed
    /// timeout) and the completion resumes from the cached list.
    AfterGitListing,
    /// Inside the first added entry's `fstatat`: the completion owes the rest and has no clock.
    AtFirstStat,
}

/// One entry a row adds: its parent beneath the destination root, its EXACT bytes, and its kind.
#[cfg(target_os = "linux")]
struct RawAddV3 {
    parent: &'static str,
    name: &'static [u8],
    kind: RawKindV3,
}

#[cfg(target_os = "linux")]
struct RawRowV3 {
    name: &'static str,
    /// Whether the row's collision is the one the repair removes (a control separates what already held).
    causal: bool,
    adds: Vec<RawAddV3>,
    /// Expected restored files removed from `.git` (named beneath it), so the listing total does not change.
    removes: Vec<&'static str>,
    stop: RawStopV3,
    /// The census's own findings, in the census's order (rendered names are the public leaves').
    want: Vec<ExpectedFailureV1>,
}

/// What one row observed and how it judged it: `invalid` is a construction problem (never evidence), and
/// `collisions` is every way the observed run differs from the row's expectation.
#[cfg(target_os = "linux")]
struct RawOutcomeV3 {
    name: &'static str,
    causal: bool,
    invalid: Vec<String>,
    collisions: Vec<String>,
    seen: String,
}

#[cfg(target_os = "linux")]
fn hex_v3(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

/// A finding of the census itself (not a chain's or a digest's): a tree fault, or a link met beneath a name of
/// the Git directory (the chains' refusals name `repository/.git/...`).
#[cfg(target_os = "linux")]
fn census_own_v3(error: &GitBootstrapErrorV1) -> bool {
    match error {
        GitBootstrapErrorV1::FinalTree { .. } => true,
        GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::SymlinkRefused { name })
        | GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::IdentityChanged(name)) => {
            !name.starts_with("repository/")
        }
        _ => false,
    }
}

/// The chain refusal of a restored metadata file whose entry is gone.
#[cfg(target_os = "linux")]
fn gone_chain_v3(error: &GitBootstrapErrorV1, file: &str) -> bool {
    matches!(
        error,
        GitBootstrapErrorV1::Restore(CustodyRestoreErrorV1::IdentityChanged(detail))
            if *detail == format!("repository/.git/{file}: the metadata file's entry is gone")
    )
}

/// Run one row: the real wrapper over the rich capsule, the row's change made at the settlement's first
/// directory `fstat`, every observation recorded, and the row judged against its own expectation.
#[cfg(target_os = "linux")]
fn run_raw_row_v3(row: &RawRowV3, capsule: &CustomCapsuleV1, clean: &FinalShapeV1) -> RawOutcomeV3 {
    use std::os::unix::ffi::OsStrExt as _;

    #[derive(Default)]
    struct StateV3 {
        acted: std::cell::Cell<bool>,
        slowed: std::cell::Cell<bool>,
        invalid: std::cell::RefCell<Vec<String>>,
    }
    fn alias_of(add: &RawAddV3) -> PathBuf {
        use std::os::unix::ffi::OsStrExt as _;
        Path::new(add.parent).join(std::ffi::OsStr::from_bytes(add.name))
    }
    let input = PlaneInV1::rich(capsule, CustodyGitObjectFormatV1::Sha1);
    let root = input.dest.path.clone();
    let (_area, outside) = external_dir_with(&["decoy"]);
    let route = RouteV1::recorder();
    let deadline = match row.stop {
        RawStopV3::Never => far_deadline(),
        RawStopV3::AfterGitListing | RawStopV3::AtFirstStat => Instant::now() + B2C_DEADLINE_V1,
    };
    // The first added entry beneath a retained directory, in byte order: the one a first-stat stop slows.
    let first_stat = row
        .adds
        .iter()
        .filter(|add| add.parent != "repository")
        .min_by_key(|add| add.name)
        .map(alias_of);
    let state: std::rc::Rc<StateV3> = std::rc::Rc::default();
    let act = {
        let state = state.clone();
        let adds: Vec<(PathBuf, RawKindV3, &'static str, &'static [u8])> = row
            .adds
            .iter()
            .map(|add| (alias_of(add), add.kind, add.parent, add.name))
            .collect();
        let removes = row.removes.clone();
        let (root, stop) = (root.clone(), row.stop);
        let first_stat = first_stat.clone();
        move |log: &[EvV2]| {
            let Some(EvV2::Hook(point, path)) = log.last() else {
                return;
            };
            if !state.acted.get() {
                if exited_v2(log) && *point == GitHookPointV1::FinalCensusStatted {
                    state.acted.set(true);
                    let mut invalid = state.invalid.borrow_mut();
                    for (relative, kind, parent, name) in &adds {
                        let at = root.join(relative);
                        match kind {
                            RawKindV3::Regular => std::fs::write(&at, b"").expect("a raw entry"),
                            RawKindV3::Link => {
                                std::os::unix::fs::symlink(outside.join("decoy"), &at)
                                    .expect("a raw link");
                            }
                            RawKindV3::Fifo => mkfifo(&at),
                        }
                        // The fixture must really hold this EXACT name, of this kind (a filesystem that
                        // refuses a raw name would otherwise make the row vacuous).
                        let listed: Vec<Vec<u8>> = std::fs::read_dir(root.join(parent))
                            .expect("the parent lists")
                            .map(|entry| entry.expect("an entry").file_name().as_bytes().to_vec())
                            .collect();
                        if listed
                            .iter()
                            .filter(|held| held.as_slice() == *name)
                            .count()
                            != 1
                        {
                            invalid.push(format!("{} is not listed exactly once", hex_v3(name)));
                        }
                        let made = std::fs::symlink_metadata(&at).expect("the raw entry exists");
                        let right = match kind {
                            RawKindV3::Regular => made.file_type().is_file(),
                            RawKindV3::Link => made.file_type().is_symlink(),
                            RawKindV3::Fifo => {
                                std::os::unix::fs::FileTypeExt::is_fifo(&made.file_type())
                            }
                        };
                        if !right {
                            invalid.push(format!("{} is not of its kind", hex_v3(name)));
                        }
                    }
                    for name in &removes {
                        let at = root.join("repository/.git").join(name);
                        std::fs::remove_file(&at).expect("a removed file");
                        if std::fs::symlink_metadata(&at).is_ok() {
                            invalid.push(format!("{name} was not removed"));
                        }
                    }
                }
                return;
            }
            if state.slowed.get() {
                return;
            }
            let slow = match stop {
                RawStopV3::Never => false,
                RawStopV3::AfterGitListing => {
                    *point == GitHookPointV1::FinalCensusListed && path.ends_with("repository/.git")
                }
                RawStopV3::AtFirstStat => {
                    *point == GitHookPointV1::BeforeFinalCensusOpen
                        && first_stat
                            .as_ref()
                            .is_some_and(|first| path.ends_with(first))
                }
            };
            if slow {
                state.slowed.set(true);
                pass_the_deadline(deadline);
            }
        }
    };
    let watched = run_watched_v2(input, &route, deadline, false, act);

    let mut invalid = state.invalid.borrow().clone();
    let mut collisions = Vec::new();
    let mut seen = String::new();
    if !state.acted.get() {
        invalid.push("the change was never made".to_owned());
    }
    if row.stop != RawStopV3::Never && !state.slowed.get() {
        invalid.push("the deadline was never made to pass".to_owned());
    }
    let window = settlement_window_v2(&watched.log);
    match &watched.ran.outcome {
        Ok(_) => collisions.push("a success followed the change".to_owned()),
        Err(failure) => {
            let held = leaves(&failure.cause);
            let own: Vec<&GitBootstrapErrorV1> = held
                .iter()
                .copied()
                .filter(|error| census_own_v3(error))
                .collect();
            seen.push_str(&format!("findings {own:?}"));
            if own.len() != row.want.len()
                || !own
                    .iter()
                    .zip(&row.want)
                    .all(|(error, want)| want.is(error))
            {
                collisions.push(format!(
                    "the census's findings were {} ({own:?}), wanted {} ({:?})",
                    own.len(),
                    row.want.len(),
                    row.want
                ));
            }
            // The chain aftermath: each removed restored file is refused once by its retained chain.
            for file in &row.removes {
                let made = held
                    .iter()
                    .filter(|error| gone_chain_v3(error, file))
                    .count();
                if made != 1 {
                    collisions.push(format!(
                        "{made} chain refusals of the removed {file}, wanted 1"
                    ));
                }
            }
            if held.iter().any(|error| {
                matches!(
                    error,
                    GitBootstrapErrorV1::FinalTree {
                        fault: FinalTreeFaultV1::Bound,
                        ..
                    }
                )
            }) {
                collisions.push("a Bound finding ended the census".to_owned());
            }
            // A leaf a row expects is the census's own, a removed file's chain refusal, or the leading timeout.
            let expected = |at: usize, error: &GitBootstrapErrorV1| {
                census_own_v3(error)
                    || row.removes.iter().any(|file| gone_chain_v3(error, file))
                    || (at == 0 && is_timeout(error))
            };
            let stray: Vec<&&GitBootstrapErrorV1> = held
                .iter()
                .enumerate()
                .filter(|(at, error)| !expected(*at, error))
                .map(|(_, error)| error)
                .collect();
            if !stray.is_empty() {
                collisions.push(format!("leaves no row expects: {stray:?}"));
            }
            if row.stop == RawStopV3::AfterGitListing
                && !held.first().is_some_and(|error| is_timeout(error))
            {
                invalid.push(
                    "the typed timeout was not the primary: the stop took no effect".to_owned(),
                );
            }
            for message in judge_failure_v2(failure, &route, clean, 3) {
                collisions.push(format!("failure state: {message}"));
            }
        }
    }
    // One no-follow stat per exact raw name beneath a retained directory, and none for a repository child
    // (an unexpected repository entry makes no call at all); no event of any other kind at an added entry's
    // path (never opened, never read, never listed, never descended).
    for add in &row.adds {
        let relative = alias_of(add);
        let attempts = window
            .iter()
            .filter(|event| {
                matches!(event, EvV2::Hook(GitHookPointV1::BeforeFinalCensusOpen, path)
                    if path.ends_with(&relative))
            })
            .count();
        let wanted = usize::from(add.parent != "repository");
        seen.push_str(&format!(" | {} attempts {attempts}", hex_v3(add.name)));
        if attempts != wanted {
            collisions.push(format!(
                "{} was attempted {attempts} times beneath {}, wanted {wanted}",
                hex_v3(add.name),
                add.parent
            ));
        }
        let beyond = window
            .iter()
            .filter(|event| {
                matches!(event, EvV2::Hook(point, path)
                    if *point != GitHookPointV1::BeforeFinalCensusOpen
                        && path.ends_with(&relative))
            })
            .count();
        if beyond != 0 {
            collisions.push(format!(
                "{} was opened, read, listed, or descended ({beyond} events)",
                hex_v3(add.name)
            ));
        }
    }
    let listings = hooks_v2(window, GitHookPointV1::FinalCensusListed);
    seen.push_str(&format!(" | listings {listings}"));
    if listings != 1 + clean.tree_dirs {
        collisions.push(format!(
            "{listings} directory listings across the settlement and its completion, wanted {}",
            1 + clean.tree_dirs
        ));
    }
    RawOutcomeV3 {
        name: row.name,
        causal: row.causal,
        invalid,
        collisions,
        seen,
    }
}

/// Run every row of a family (each on its own thread: the hooks are thread-local), print one line per row
/// BEFORE any assertion, and assert once: no row is invalid, and every row matches its expectation.
#[cfg(target_os = "linux")]
fn judge_raw_rows_v3(family: &str, rows: Vec<RawRowV3>) {
    let capsule = captured(CustodyGitObjectFormatV1::Sha1);
    let clean = clean_final_shape(&capsule, CustodyGitObjectFormatV1::Sha1, true);
    let outcomes: Vec<RawOutcomeV3> = std::thread::scope(|scope| {
        let handles: Vec<_> = rows
            .iter()
            .map(|row| {
                let (capsule, clean) = (&capsule, &clean);
                scope.spawn(move || run_raw_row_v3(row, capsule, clean))
            })
            .collect();
        handles
            .into_iter()
            .map(|handle| handle.join().expect("a raw row's thread"))
            .collect()
    });
    let mut problems = Vec::new();
    for outcome in &outcomes {
        let status = if !outcome.invalid.is_empty() {
            "INVALID"
        } else if outcome.collisions.is_empty() {
            "MATCHES"
        } else {
            "COLLISION"
        };
        println!(
            "RAW-ROW | {family} | {} | {} | {status} | {} | invalid {:?} | differs {:?}",
            if outcome.causal { "causal" } else { "control" },
            outcome.name,
            outcome.seen,
            outcome.invalid,
            outcome.collisions
        );
        if !outcome.invalid.is_empty() {
            problems.push(format!(
                "INVALID (not behavioral evidence) {}: {}",
                outcome.name,
                outcome.invalid.join("; ")
            ));
        } else if !outcome.collisions.is_empty() {
            problems.push(format!(
                "{} row {}: {}",
                if outcome.causal { "CAUSAL" } else { "CONTROL" },
                outcome.name,
                outcome.collisions.join("; ")
            ));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// FAMILY 1 (raw aliases, exact attempts, resume). Two raw names of ONE parent whose lossy renderings are the
/// same string (`ff` and `fe`; `ff` and the valid UTF-8 `ef bf bd`) are two independent census units: each is
/// `fstatat`ed exactly once by its exact bytes and each is its own finding (the two public leaves may look
/// identical), beside the findings of the removed expected files and their chain aftermath, and each directory is
/// listed once. A deadline spent right after the `.git` listing RETURNED stops the paced pass at the first entry's
/// guard, and the completion resumes from the cached list and attempts each raw name once. The controls are two
/// distinct VALID names and one alias alone.
#[cfg(target_os = "linux")]
#[test]
fn b2c_lossless_raw_name_aliases_are_independent_census_units_with_exact_attempts_and_resume() {
    let ff_fe = || {
        vec![
            RawAddV3 {
                parent: "repository/.git",
                name: b"\xff",
                kind: RawKindV3::Regular,
            },
            RawAddV3 {
                parent: "repository/.git",
                name: b"\xfe",
                kind: RawKindV3::Regular,
            },
        ]
    };
    let ff_replacement = || {
        vec![
            RawAddV3 {
                parent: "repository/.git",
                name: b"\xff",
                kind: RawKindV3::Regular,
            },
            RawAddV3 {
                parent: "repository/.git",
                name: b"\xef\xbf\xbd",
                kind: RawKindV3::Regular,
            },
        ]
    };
    let unexpected = || ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "\u{fffd}");
    let missing = |name| ExpectedFailureV1::Tree(FinalTreeFaultV1::Missing, name);
    let two = || {
        vec![
            unexpected(),
            unexpected(),
            missing("HEAD"),
            missing("ORIG_HEAD"),
        ]
    };
    let removed = || vec!["HEAD", "ORIG_HEAD"];
    judge_raw_rows_v3(
        "family 1",
        vec![
            RawRowV3 {
                name: "two invalid raw names {ff, fe} beneath .git",
                causal: true,
                adds: ff_fe(),
                removes: removed(),
                stop: RawStopV3::Never,
                want: two(),
            },
            RawRowV3 {
                name: "an invalid raw name and the valid U+FFFD {ff, ef bf bd} beneath .git",
                causal: true,
                adds: ff_replacement(),
                removes: removed(),
                stop: RawStopV3::Never,
                want: two(),
            },
            RawRowV3 {
                name: "two invalid raw names {ff, fe} beneath the nested retained parent refs",
                causal: true,
                adds: vec![
                    RawAddV3 { parent: "repository/.git/refs", name: b"\xff", kind: RawKindV3::Regular },
                    RawAddV3 { parent: "repository/.git/refs", name: b"\xfe", kind: RawKindV3::Regular },
                ],
                removes: removed(),
                stop: RawStopV3::Never,
                want: vec![
                    ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "refs/\u{fffd}"),
                    ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "refs/\u{fffd}"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                ],
            },
            RawRowV3 {
                name: "{ff, fe} with the deadline spent right after the .git listing returned (resume from the cached list)",
                causal: true,
                adds: ff_fe(),
                removes: removed(),
                stop: RawStopV3::AfterGitListing,
                want: two(),
            },
            RawRowV3 {
                name: "{ff, ef bf bd} with the deadline spent right after the .git listing returned (resume from the cached list)",
                causal: true,
                adds: ff_replacement(),
                removes: removed(),
                stop: RawStopV3::AfterGitListing,
                want: two(),
            },
            RawRowV3 {
                name: "{ff, fe} with the deadline spent inside the first name's fstatat (a clock-free completion)",
                causal: true,
                adds: ff_fe(),
                removes: removed(),
                stop: RawStopV3::AtFirstStat,
                want: two(),
            },
            RawRowV3 {
                name: "control: two distinct valid names {0a, 0b}",
                causal: false,
                adds: vec![
                    RawAddV3 { parent: "repository/.git", name: b"0a", kind: RawKindV3::Regular },
                    RawAddV3 { parent: "repository/.git", name: b"0b", kind: RawKindV3::Regular },
                ],
                removes: removed(),
                stop: RawStopV3::Never,
                want: vec![
                    ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0a"),
                    ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, "0b"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                ],
            },
            RawRowV3 {
                name: "control: one invalid raw name {ff} alone",
                causal: false,
                adds: vec![RawAddV3 {
                    parent: "repository/.git",
                    name: b"\xff",
                    kind: RawKindV3::Regular,
                }],
                removes: vec!["HEAD"],
                stop: RawStopV3::Never,
                want: vec![unexpected(), missing("HEAD")],
            },
        ],
    );
}

/// FAMILY 2 (the repository's own children, the sentinel, and the namespaces that were already separate). Two raw
/// names of the REPOSITORY directory (outside `.git`) are two units and two findings (an unexpected repository
/// child makes no call at all), and a Git child whose raw name is `\x01HEAD` is its own entry that must not
/// settle the missing check of `HEAD` (a missing unit used to be a prefixed string in the same set as the
/// entries). The CONTROLS hold on every version: equal raw spelling in the repository and in the Git namespace,
/// the same rendered name under two retained parents (equal and different raw bytes), and one repository child
/// alone, each its own units.
#[cfg(target_os = "linux")]
#[test]
fn b2c_lossless_repository_aliases_the_missing_namespace_and_the_separate_namespace_controls() {
    let unexpected = |name| ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, name);
    let missing = |name| ExpectedFailureV1::Tree(FinalTreeFaultV1::Missing, name);
    let removed = || vec!["HEAD", "ORIG_HEAD"];
    judge_raw_rows_v3(
        "family 2",
        vec![
            RawRowV3 {
                name: "two invalid raw names {ff, fe} beside the repository's .git",
                causal: true,
                adds: vec![
                    RawAddV3 { parent: "repository", name: b"\xff", kind: RawKindV3::Regular },
                    RawAddV3 { parent: "repository", name: b"\xfe", kind: RawKindV3::Regular },
                ],
                removes: removed(),
                stop: RawStopV3::Never,
                want: vec![
                    unexpected("\u{fffd}"),
                    unexpected("\u{fffd}"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                ],
            },
            RawRowV3 {
                name: "an invalid raw name and the valid U+FFFD {ff, ef bf bd} beside the repository's .git",
                causal: true,
                adds: vec![
                    RawAddV3 { parent: "repository", name: b"\xff", kind: RawKindV3::Regular },
                    RawAddV3 { parent: "repository", name: b"\xef\xbf\xbd", kind: RawKindV3::Regular },
                ],
                removes: removed(),
                stop: RawStopV3::Never,
                want: vec![
                    unexpected("\u{fffd}"),
                    unexpected("\u{fffd}"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                ],
            },
            RawRowV3 {
                name: "the Git child \\x01HEAD beside a removed HEAD (the missing unit is not an entry)",
                causal: true,
                adds: vec![RawAddV3 {
                    parent: "repository/.git",
                    name: b"\x01HEAD",
                    kind: RawKindV3::Regular,
                }],
                removes: vec!["HEAD"],
                stop: RawStopV3::Never,
                want: vec![unexpected("\u{1}HEAD"), missing("HEAD")],
            },
            RawRowV3 {
                name: "control: equal raw spelling {ff} in the repository and beneath .git",
                causal: false,
                adds: vec![
                    RawAddV3 { parent: "repository", name: b"\xff", kind: RawKindV3::Regular },
                    RawAddV3 { parent: "repository/.git", name: b"\xff", kind: RawKindV3::Regular },
                ],
                removes: removed(),
                stop: RawStopV3::Never,
                want: vec![
                    unexpected("\u{fffd}"),
                    unexpected("\u{fffd}"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                ],
            },
            RawRowV3 {
                name: "control: equal raw spelling {ff} beneath the two retained parents logs and refs",
                causal: false,
                adds: vec![
                    RawAddV3 { parent: "repository/.git/logs", name: b"\xff", kind: RawKindV3::Regular },
                    RawAddV3 { parent: "repository/.git/refs", name: b"\xff", kind: RawKindV3::Regular },
                ],
                removes: removed(),
                stop: RawStopV3::Never,
                want: vec![
                    unexpected("logs/\u{fffd}"),
                    unexpected("refs/\u{fffd}"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                ],
            },
            RawRowV3 {
                name: "control: different raw bytes {ff, fe} with one rendering beneath logs and refs",
                causal: false,
                adds: vec![
                    RawAddV3 { parent: "repository/.git/logs", name: b"\xff", kind: RawKindV3::Regular },
                    RawAddV3 { parent: "repository/.git/refs", name: b"\xfe", kind: RawKindV3::Regular },
                ],
                removes: removed(),
                stop: RawStopV3::Never,
                want: vec![
                    unexpected("logs/\u{fffd}"),
                    unexpected("refs/\u{fffd}"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                ],
            },
            RawRowV3 {
                name: "control: one invalid repository child {ff} alone",
                causal: false,
                adds: vec![RawAddV3 {
                    parent: "repository",
                    name: b"\xff",
                    kind: RawKindV3::Regular,
                }],
                removes: vec!["HEAD"],
                stop: RawStopV3::Never,
                want: vec![unexpected("\u{fffd}"), missing("HEAD")],
            },
        ],
    );
}

/// FAMILY 3 (regular, link, and special entries of distinct raw names). Byte-distinct invalid names that are a
/// regular file, a symlink, and a FIFO (in either order) are each classified by their own `fstatat` and each is
/// its own finding, in raw byte order, beside every removed file's missing check and chain; the link and the FIFO
/// are never opened, read, or descended (an `open` of the FIFO would hang the run). One entry alone of each
/// class is exactly one attempt and one finding, and three distinct VALID names classify the same way.
#[cfg(target_os = "linux")]
#[test]
fn b2c_lossless_regular_link_and_special_aliases_are_classified_independently_and_never_opened() {
    let unexpected = |name| ExpectedFailureV1::Tree(FinalTreeFaultV1::Unexpected, name);
    let special = |name| ExpectedFailureV1::Tree(FinalTreeFaultV1::Special, name);
    let missing = |name| ExpectedFailureV1::Tree(FinalTreeFaultV1::Missing, name);
    let three = || vec!["HEAD", "ORIG_HEAD", "packed-refs"];
    let in_git = |name: &'static [u8], kind| RawAddV3 {
        parent: "repository/.git",
        name,
        kind,
    };
    judge_raw_rows_v3(
        "family 3",
        vec![
            RawRowV3 {
                name: "{fd regular, fe symlink, ff FIFO} replacing three restored files",
                causal: true,
                adds: vec![
                    in_git(b"\xfd", RawKindV3::Regular),
                    in_git(b"\xfe", RawKindV3::Link),
                    in_git(b"\xff", RawKindV3::Fifo),
                ],
                removes: three(),
                stop: RawStopV3::Never,
                want: vec![
                    unexpected("\u{fffd}"),
                    ExpectedFailureV1::Symlink("\u{fffd}"),
                    special("\u{fffd}"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                    missing("packed-refs"),
                ],
            },
            RawRowV3 {
                name: "{fd FIFO, fe symlink, ff regular} replacing three restored files",
                causal: true,
                adds: vec![
                    in_git(b"\xfd", RawKindV3::Fifo),
                    in_git(b"\xfe", RawKindV3::Link),
                    in_git(b"\xff", RawKindV3::Regular),
                ],
                removes: three(),
                stop: RawStopV3::Never,
                want: vec![
                    special("\u{fffd}"),
                    ExpectedFailureV1::Symlink("\u{fffd}"),
                    unexpected("\u{fffd}"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                    missing("packed-refs"),
                ],
            },
            RawRowV3 {
                name: "control: one regular raw name {ff} alone",
                causal: false,
                adds: vec![in_git(b"\xff", RawKindV3::Regular)],
                removes: vec!["HEAD"],
                stop: RawStopV3::Never,
                want: vec![unexpected("\u{fffd}"), missing("HEAD")],
            },
            RawRowV3 {
                name: "control: one symlink raw name {ff} alone",
                causal: false,
                adds: vec![in_git(b"\xff", RawKindV3::Link)],
                removes: vec!["HEAD"],
                stop: RawStopV3::Never,
                want: vec![ExpectedFailureV1::Symlink("\u{fffd}"), missing("HEAD")],
            },
            RawRowV3 {
                name: "control: one FIFO raw name {ff} alone",
                causal: false,
                adds: vec![in_git(b"\xff", RawKindV3::Fifo)],
                removes: vec!["HEAD"],
                stop: RawStopV3::Never,
                want: vec![special("\u{fffd}"), missing("HEAD")],
            },
            RawRowV3 {
                name: "control: three distinct valid names {0a regular, 0b symlink, 0c FIFO}",
                causal: false,
                adds: vec![
                    in_git(b"0a", RawKindV3::Regular),
                    in_git(b"0b", RawKindV3::Link),
                    in_git(b"0c", RawKindV3::Fifo),
                ],
                removes: three(),
                stop: RawStopV3::Never,
                want: vec![
                    unexpected("0a"),
                    ExpectedFailureV1::Symlink("0b"),
                    special("0c"),
                    missing("HEAD"),
                    missing("ORIG_HEAD"),
                    missing("packed-refs"),
                ],
            },
        ],
    );
}

// 2B3c phase P's controls: a child module, so every row reuses the real phase-V-to-G fixtures above
// without widening any of them.
#[path = "custody_restore_payload_tests.rs"]
mod payload_tests;
